__CR('t:sql',[{"t":"SQL 심화 — 실행 채점 (SQLite)","l":[{"t":"서브쿼리·조인 심화","q":[{"t":"sql","k":"sqlx2-subquery-avg-price","q":"products 테이블에서 전체 평균 가격보다 비싼 상품만 골라 name, price 두 컬럼을 price 내림차순으로 출력하세요.","schema":"CREATE TABLE products (id INTEGER, name TEXT, price INTEGER);\nINSERT INTO products VALUES (1,'USB허브',100),(2,'키보드',200),(3,'모니터',300),(4,'그래픽카드',400),(5,'노트북',500);","src":"-- 힌트: WHERE 절에서 스칼라 서브쿼리 (SELECT AVG(price) FROM products) 를 비교하세요.\n-- 아래는 필터가 빠진 미완성 쿼리입니다.\nSELECT name, price FROM products ORDER BY price DESC;","sol":"SELECT name, price FROM products WHERE price > (SELECT AVG(price) FROM products) ORDER BY price DESC;","ordered":true,"cat":"design","ex":"평균 가격(300)을 스칼라 서브쿼리로 구한 뒤 그 값보다 큰 행만 남깁니다. 결과는 그래픽카드(400), 노트북(500) 순의 역순인 500, 400 입니다.\n💡 개념: WHERE 절의 스칼라 서브쿼리는 단일 값을 반환해 비교 대상으로 쓰입니다. 집계값과 개별 행을 한 쿼리에서 비교할 때 필수 패턴입니다.\n🛠 실무: '평균 이상 구매 고객', '중앙값 초과 응답시간' 같은 기준선 필터링에 자주 씁니다. AVG는 매 행마다 재계산되지 않고 한 번만 평가됩니다."},{"t":"sql","k":"sqlx2-correlated-group-max","q":"sales 테이블에서 각 region 별 최대 amount와 값이 같은 행을 region, amount 컬럼으로 region 오름차순 출력하세요. 동점이 있으면 모두 포함합니다.","schema":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER);\nINSERT INTO sales VALUES (1,'서울',300),(2,'서울',500),(3,'부산',200),(4,'부산',450),(5,'대구',150),(6,'대구',150);","src":"-- 힌트: 상관 서브쿼리로 같은 region의 MAX(amount)를 구해 비교하세요.\n-- 아래는 모든 행을 출력하는 미완성 쿼리입니다.\nSELECT region, amount FROM sales ORDER BY region;","sol":"SELECT region, amount FROM sales s WHERE amount = (SELECT MAX(amount) FROM sales s2 WHERE s2.region = s.region) ORDER BY region;","ordered":true,"cat":"design","ex":"바깥 행마다 같은 region의 최대값을 다시 계산해 비교하는 상관 서브쿼리입니다. 대구는 150이 둘 다 최대라 두 행 모두 출력됩니다.\n💡 개념: 상관 서브쿼리는 바깥 쿼리의 현재 행(s)을 참조하므로 그룹별 조건을 GROUP BY 없이 표현할 수 있습니다.\n🛠 실무: '각 카테고리 최신 주문', '부서별 최고 연봉자'처럼 그룹 내 대표 행 추출에 씁니다. 대량 데이터에서는 윈도우 함수가 더 빠를 수 있습니다."},{"t":"sql","k":"sqlx2-case-grade-bucket","q":"students 테이블의 score를 90 이상이면 'A', 80 이상이면 'B', 그 외 'C' 등급으로 분류하고 등급별 인원수를 grade, cnt 컬럼으로 grade 오름차순 출력하세요.","schema":"CREATE TABLE students (name TEXT, score INTEGER);\nINSERT INTO students VALUES ('김',95),('이',88),('박',82),('최',70),('정',91),('강',60);","src":"-- 힌트: SELECT 절의 CASE 식으로 등급 컬럼을 만들고 그 별칭으로 GROUP BY 하세요.\n-- 아래는 분류 없이 전체 인원만 세는 미완성 쿼리입니다.\nSELECT '전체' AS grade, COUNT(*) AS cnt FROM students;","sol":"SELECT CASE WHEN score >= 90 THEN 'A' WHEN score >= 80 THEN 'B' ELSE 'C' END AS grade, COUNT(*) AS cnt FROM students GROUP BY grade ORDER BY grade;","ordered":true,"cat":"internals","ex":"CASE 식으로 만든 grade 별칭을 GROUP BY에 그대로 쓸 수 있습니다(SQLite는 SELECT 별칭을 GROUP BY에서 허용). A:2, B:2, C:2 입니다.\n💡 개념: CASE는 SQL의 조건 분기식으로 위에서부터 처음 참인 WHEN이 채택됩니다. 경계값(90, 80) 순서가 중요합니다.\n🛠 실무: 연령대/금액대 구간화(bucketing)나 SUM(CASE WHEN ...)을 이용한 피벗 집계의 기본기입니다."},{"t":"sql","k":"sqlx2-self-join-manager","q":"employees 테이블에서 각 직원과 그 직원의 매니저 이름을 emp, mgr 컬럼으로 emp 오름차순 출력하세요. 매니저가 없는 사람은 제외합니다.","schema":"CREATE TABLE employees (id INTEGER, name TEXT, manager_id INTEGER);\nINSERT INTO employees VALUES (1,'대표',NULL),(2,'김이사',1),(3,'이팀장',2),(4,'박사원',3),(5,'최사원',3);","src":"-- 힌트: employees 를 e, m 두 별칭으로 셀프 조인해 e.manager_id = m.id 로 연결하세요.\n-- 아래는 매니저 정보 없이 직원만 나열한 미완성 쿼리입니다.\nSELECT name AS emp, manager_id AS mgr FROM employees ORDER BY name;","sol":"SELECT e.name AS emp, m.name AS mgr FROM employees e JOIN employees m ON e.manager_id = m.id ORDER BY emp;","ordered":true,"cat":"design","ex":"같은 테이블을 e(직원), m(매니저) 두 역할로 조인합니다. INNER JOIN이라 manager_id가 NULL인 대표는 자동 제외됩니다.\n💡 개념: 셀프 조인은 계층/비교 관계를 한 테이블 안에서 표현할 때 씁니다. 별칭으로 두 인스턴스를 구분하는 것이 핵심입니다.\n🛠 실무: 조직도, 친구 추천, 같은 주문 내 상품 쌍 비교 등에 활용합니다."},{"t":"sql","k":"sqlx2-union-dedup","q":"온라인(online_customers)과 오프라인(store_customers) 두 소스의 고객명을 합쳐 중복을 제거한 명단을 name 컬럼으로 name 오름차순 출력하세요.","schema":"CREATE TABLE online_customers (name TEXT);\nINSERT INTO online_customers VALUES ('김'),('이'),('박');\nCREATE TABLE store_customers (name TEXT);\nINSERT INTO store_customers VALUES ('박'),('최'),('정');","src":"-- 힌트: 두 SELECT 를 UNION 으로 결합하면 중복이 제거됩니다(UNION ALL 은 유지).\n-- 아래는 한쪽 소스만 조회하는 미완성 쿼리입니다.\nSELECT name FROM online_customers ORDER BY name;","sol":"SELECT name FROM online_customers UNION SELECT name FROM store_customers ORDER BY name;","ordered":true,"cat":"design","ex":"UNION은 두 결과를 합치며 중복 행을 제거합니다. '박'이 양쪽에 있어도 한 번만 나와 김, 박, 이, 정, 최 5개가 됩니다.\n💡 개념: UNION은 정렬/중복제거 비용이 있고, UNION ALL은 중복을 그대로 두어 더 빠릅니다. 중복이 없음을 아는 경우 ALL이 낫습니다.\n🛠 실무: 여러 기간/샤드 테이블 통합, 이벤트 소스 병합에 씁니다. ORDER BY는 UNION 전체 결과에 한 번만 적용됩니다."},{"t":"sql","k":"sqlx2-coalesce-null-bonus","q":"employees2 테이블에서 bonus가 NULL이면 0으로 대체한 값을 name, bonus_val 컬럼으로 출력하세요. 정렬은 bonus_val 내림차순, 같으면 name 오름차순입니다.","schema":"CREATE TABLE employees2 (name TEXT, bonus INTEGER);\nINSERT INTO employees2 VALUES ('김',500),('이',NULL),('박',300),('최',NULL),('정',700);","src":"-- 힌트: COALESCE(bonus, 0) 으로 NULL 을 0 으로 치환하세요.\n-- 아래는 NULL 을 그대로 두어 정렬이 어긋나는 미완성 쿼리입니다.\nSELECT name, bonus AS bonus_val FROM employees2 ORDER BY bonus_val DESC, name;","sol":"SELECT name, COALESCE(bonus, 0) AS bonus_val FROM employees2 ORDER BY bonus_val DESC, name;","ordered":true,"cat":"internals","ex":"COALESCE는 첫 번째 비-NULL 인자를 반환합니다. NULL 보너스가 0으로 바뀌어 정렬 맨 아래로 내려가고 이, 최는 이름순으로 정렬됩니다.\n💡 개념: NULL은 '알 수 없음'이라 산술/비교에서 전파됩니다. 집계 함수(SUM 등)는 NULL을 건너뛰지만 표시나 정렬 전에는 명시적 치환이 필요합니다.\n🛠 실무: 리포트에서 빈 값을 0/'미정'으로 보여주거나, NULL로 인한 계산 누락을 막을 때 COALESCE/IFNULL을 씁니다."}],"th":{"sum":"실행 채점(SQLite)에서는 서브쿼리·`JOIN`·`GROUP BY`·`CASE`·`COALESCE`·집합·날짜 문자열을 정확한 **컬럼명과 정렬**로 출력해야 한다.","body":[{"h":"서브쿼리·조인·CASE","t":"'평균보다 비싼 상품'은 `WHERE price > (SELECT AVG(price) FROM products)`. self-join으로 직원-매니저를 잇고, 매니저 없는 사람 제외는 INNER JOIN이 자연스럽다. 등급별 인원은 `CASE`로 등급을 만들고 `GROUP BY grade, COUNT(*)`. 요구한 컬럼 별칭(`AS`)과 순서를 정확히 맞춘다."},{"h":"집계·NULL·날짜·집합","t":"각 region 최대값과 같은 행은 상관 서브쿼리나 윈도우로 뽑는다. NULL 대체는 `COALESCE(bonus,0)`. 월별 매출은 SQLite `strftime('%Y-%m', d)`로 'YYYY-MM'을 만들어 `GROUP BY`한다. 중복 없는 합집합은 `UNION`이다. `ORDER BY`는 문제가 지정한 컬럼·방향대로 마지막에 붙인다."}],"code":{"c":"SELECT name, price\nFROM products\nWHERE price > (SELECT AVG(price) FROM products)\nORDER BY price DESC;","cap":"전체 평균보다 비싼 상품을 가격 내림차순"},"key":["평균 비교는 스칼라 서브쿼리, 등급은 `CASE`+`GROUP BY`","NULL 대체 `COALESCE`, 월 추출 `strftime('%Y-%m', d)`","중복 제거 합집합 `UNION`, 컬럼명·정렬을 정확히"]}},{"t":"집계·NULL·날짜","q":[{"t":"sql","k":"sqlx2-strftime-monthly","q":"orders 테이블에서 월별(YYYY-MM) 총 매출을 ym, total 컬럼으로 ym 오름차순 출력하세요.","schema":"CREATE TABLE orders (id INTEGER, order_date TEXT, amount INTEGER);\nINSERT INTO orders VALUES (1,'2024-01-05',100),(2,'2024-01-20',200),(3,'2024-02-03',150),(4,'2024-02-28',350),(5,'2024-03-10',400);","src":"-- 힌트: strftime('%Y-%m', order_date) 로 연-월을 뽑아 GROUP BY 하세요.\n-- 아래는 날짜를 그대로 두어 일자별로 쪼개지는 미완성 쿼리입니다.\nSELECT order_date AS ym, SUM(amount) AS total FROM orders GROUP BY order_date ORDER BY order_date;","sol":"SELECT strftime('%Y-%m', order_date) AS ym, SUM(amount) AS total FROM orders GROUP BY ym ORDER BY ym;","ordered":true,"cat":"design","ex":"strftime('%Y-%m', ...)로 날짜에서 연-월 문자열을 추출해 그룹화합니다. 2024-01:300, 2024-02:500, 2024-03:400 입니다.\n💡 개념: SQLite는 별도 DATE 타입이 없어 'YYYY-MM-DD' 텍스트를 날짜로 다루며 strftime으로 포맷/구성요소를 뽑습니다.\n🛠 실무: 월별/주별/요일별 매출 집계 대시보드의 기본입니다. 인덱스 활용을 위해 원본 컬럼에는 함수를 걸지 않는 설계가 이상적입니다."},{"t":"sql","k":"sqlx2-window-running-total","q":"daily_sales 테이블에서 날짜 오름차순 기준 누적 매출을 d, amount, running_total 컬럼으로 d 오름차순 출력하세요.","schema":"CREATE TABLE daily_sales (d TEXT, amount INTEGER);\nINSERT INTO daily_sales VALUES ('2024-01-01',100),('2024-01-02',200),('2024-01-03',150),('2024-01-04',300);","src":"-- 힌트: SUM(amount) OVER (ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) 를 쓰세요.\n-- 아래는 누적이 아니라 전체 합만 붙이는 미완성 쿼리입니다.\nSELECT d, amount, (SELECT SUM(amount) FROM daily_sales) AS running_total FROM daily_sales ORDER BY d;","sol":"SELECT d, amount, SUM(amount) OVER (ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM daily_sales ORDER BY d;","ordered":true,"cat":"perf","ex":"윈도우 프레임 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW가 첫 행부터 현재 행까지 누적합을 만듭니다. 100, 300, 450, 750 입니다.\n💡 개념: 윈도우 함수는 GROUP BY와 달리 행을 접지 않고 각 행 옆에 집계값을 붙입니다. 프레임 절이 누적 범위를 정합니다.\n🛠 실무: 누적 매출, 러닝 밸런스, 코호트 누적 지표 계산에 필수입니다. 자기조인 누적합보다 훨씬 빠릅니다."},{"t":"sql","k":"sqlx2-window-lag-mom","q":"monthly 테이블에서 전월 대비 매출 증감(diff = 이번달 revenue - 전월 revenue)을 ym, revenue, diff 컬럼으로 ym 오름차순 출력하세요. 첫 달의 diff는 NULL입니다.","schema":"CREATE TABLE monthly (ym TEXT, revenue INTEGER);\nINSERT INTO monthly VALUES ('2024-01',1000),('2024-02',1200),('2024-03',900),('2024-04',1500);","src":"-- 힌트: LAG(revenue) OVER (ORDER BY ym) 로 전월 값을 가져와 빼세요.\n-- 아래는 전월 값을 못 구해 diff 가 항상 0 인 미완성 쿼리입니다.\nSELECT ym, revenue, revenue - revenue AS diff FROM monthly ORDER BY ym;","sol":"SELECT ym, revenue, revenue - LAG(revenue) OVER (ORDER BY ym) AS diff FROM monthly ORDER BY ym;","ordered":true,"cat":"perf","ex":"LAG(revenue)는 정렬 순서상 바로 이전 행의 값을 가져옵니다. 첫 행은 이전 행이 없어 NULL, 이후 200, -300, 600 입니다.\n💡 개념: LAG/LEAD는 오프셋 접근 윈도우 함수로 전월/전일 대비, 이전 상태와의 변화 감지에 씁니다.\n🛠 실무: MoM/DoD 성장률, 상태 전이 감지(이전 값과 다른 행 찾기)에 표준으로 쓰입니다."},{"t":"sql","k":"sqlx2-window-rank-partition","q":"scores 테이블에서 부서(dept)별로 score 내림차순 순위를 매겨 dept, name, score, rnk 컬럼으로 출력하세요. 정렬은 dept 오름차순, 같은 부서 내에서는 rnk 오름차순입니다. 동점은 같은 순위를 부여합니다.","schema":"CREATE TABLE scores (dept TEXT, name TEXT, score INTEGER);\nINSERT INTO scores VALUES ('영업','김',90),('영업','이',85),('영업','박',90),('개발','최',70),('개발','정',95);","src":"-- 힌트: RANK() OVER (PARTITION BY dept ORDER BY score DESC) 를 쓰세요.\n-- 아래는 부서 구분 없이 전체 순위를 매기는 미완성 쿼리입니다.\nSELECT dept, name, score, RANK() OVER (ORDER BY score DESC) AS rnk FROM scores ORDER BY dept, rnk;","sol":"SELECT dept, name, score, RANK() OVER (PARTITION BY dept ORDER BY score DESC) AS rnk FROM scores ORDER BY dept, rnk;","ordered":true,"cat":"perf","ex":"PARTITION BY dept가 부서별로 순위 계산을 초기화합니다. 영업의 김/박은 90 동점이라 둘 다 1위, 이는 3위(RANK는 건너뜀)입니다.\n💡 개념: RANK는 동점에 같은 순위를 주고 다음 순위를 건너뜁니다(1,1,3). 건너뛰지 않으려면 DENSE_RANK, 고유 순번은 ROW_NUMBER를 씁니다.\n🛠 실무: 부서별 상위 N, 카테고리별 베스트셀러 선정 등 그룹 내 랭킹의 핵심입니다."},{"t":"sql","k":"sqlx2-having-vip-customer","q":"purchases 테이블에서 고객별 총 구매액이 1000을 초과하는 우량 고객을 customer, total 컬럼으로 total 내림차순 출력하세요.","schema":"CREATE TABLE purchases (customer TEXT, amount INTEGER);\nINSERT INTO purchases VALUES ('김',600),('김',700),('이',300),('박',1200),('박',100),('최',900);","src":"-- 힌트: GROUP BY 후 HAVING SUM(amount) > 1000 으로 그룹 집계값을 필터링하세요.\n-- 아래는 조건 없이 모든 고객 합계를 보여주는 미완성 쿼리입니다.\nSELECT customer, SUM(amount) AS total FROM purchases GROUP BY customer ORDER BY total DESC;","sol":"SELECT customer, SUM(amount) AS total FROM purchases GROUP BY customer HAVING SUM(amount) > 1000 ORDER BY total DESC;","ordered":true,"cat":"design","ex":"WHERE는 그룹화 전 개별 행을, HAVING은 그룹화 후 집계값을 필터링합니다. 김(1300), 박(1300)만 1000을 초과합니다.\n💡 개념: 집계 결과에 대한 조건은 반드시 HAVING에 써야 합니다. WHERE에는 집계 함수를 쓸 수 없습니다.\n🛠 실무: VIP 고객, 임계치 초과 리소스, 최소 주문 건수 이상 판매자 등 '집계 기준 필터'에 씁니다."},{"t":"sql","k":"sqlx2-three-table-join","q":"users, orders, products 세 테이블을 조인해 각 주문의 사용자 이름, 상품명, 결제금액(qty * price)을 user_name, product_name, amount 컬럼으로 주문 id(orders.id) 오름차순 출력하세요.","schema":"CREATE TABLE users (id INTEGER, name TEXT);\nINSERT INTO users VALUES (1,'김'),(2,'이');\nCREATE TABLE products (id INTEGER, pname TEXT, price INTEGER);\nINSERT INTO products VALUES (10,'마우스',20),(20,'키보드',50);\nCREATE TABLE orders (id INTEGER, user_id INTEGER, product_id INTEGER, qty INTEGER);\nINSERT INTO orders VALUES (1,1,10,3),(2,2,20,1),(3,1,20,2);","src":"-- 힌트: orders 를 중심으로 users, products 를 각각 JOIN 하고 qty*price 를 계산하세요.\n-- 아래는 조인 없이 orders 원본만 보여주는 미완성 쿼리입니다.\nSELECT user_id AS user_name, product_id AS product_name, qty AS amount FROM orders ORDER BY id;","sol":"SELECT u.name AS user_name, p.pname AS product_name, o.qty * p.price AS amount FROM orders o JOIN users u ON o.user_id = u.id JOIN products p ON o.product_id = p.id ORDER BY o.id;","ordered":true,"cat":"design","ex":"orders를 사실 테이블(fact)로 두고 users, products 두 차원을 각각 조인해 계산 컬럼을 만듭니다. 김/마우스/60, 이/키보드/50, 김/키보드/100 입니다.\n💡 개념: 다중 조인은 각 ON 조건이 어떤 키를 연결하는지 명확히 하는 것이 중요합니다. 조인 순서와 무관하게 결과는 같지만 가독성을 위해 중심 테이블부터 씁니다.\n🛠 실무: 정규화된 스키마에서 리포트용 넓은 결과를 만들 때의 전형적 패턴입니다."}],"th":{"sum":"실행 채점(SQLite)에서는 서브쿼리·`JOIN`·`GROUP BY`·`CASE`·`COALESCE`·집합·날짜 문자열을 정확한 **컬럼명과 정렬**로 출력해야 한다.","body":[{"h":"서브쿼리·조인·CASE","t":"'평균보다 비싼 상품'은 `WHERE price > (SELECT AVG(price) FROM products)`. self-join으로 직원-매니저를 잇고, 매니저 없는 사람 제외는 INNER JOIN이 자연스럽다. 등급별 인원은 `CASE`로 등급을 만들고 `GROUP BY grade, COUNT(*)`. 요구한 컬럼 별칭(`AS`)과 순서를 정확히 맞춘다."},{"h":"집계·NULL·날짜·집합","t":"각 region 최대값과 같은 행은 상관 서브쿼리나 윈도우로 뽑는다. NULL 대체는 `COALESCE(bonus,0)`. 월별 매출은 SQLite `strftime('%Y-%m', d)`로 'YYYY-MM'을 만들어 `GROUP BY`한다. 중복 없는 합집합은 `UNION`이다. `ORDER BY`는 문제가 지정한 컬럼·방향대로 마지막에 붙인다."}],"code":{"c":"SELECT name, price\nFROM products\nWHERE price > (SELECT AVG(price) FROM products)\nORDER BY price DESC;","cap":"전체 평균보다 비싼 상품을 가격 내림차순"},"key":["평균 비교는 스칼라 서브쿼리, 등급은 `CASE`+`GROUP BY`","NULL 대체 `COALESCE`, 월 추출 `strftime('%Y-%m', d)`","중복 제거 합집합 `UNION`, 컬럼명·정렬을 정확히"]}},{"t":"윈도우·CTE·집합","q":[{"t":"sql","k":"sqlx2-count-distinct-visitors","q":"visits 테이블에서 페이지별 방문한 고유 사용자 수를 page, uniq_users 컬럼으로 출력하세요. 정렬은 uniq_users 내림차순, 같으면 page 오름차순입니다.","schema":"CREATE TABLE visits (user_id INTEGER, page TEXT);\nINSERT INTO visits VALUES (1,'home'),(1,'home'),(2,'home'),(2,'cart'),(3,'cart'),(1,'cart');","src":"-- 힌트: COUNT(DISTINCT user_id) 로 중복 방문을 제거하고 세세요.\n-- 아래는 방문 횟수(중복 포함)를 세는 미완성 쿼리입니다.\nSELECT page, COUNT(*) AS uniq_users FROM visits GROUP BY page ORDER BY uniq_users DESC, page;","sol":"SELECT page, COUNT(DISTINCT user_id) AS uniq_users FROM visits GROUP BY page ORDER BY uniq_users DESC, page;","ordered":true,"cat":"design","ex":"COUNT(DISTINCT user_id)는 같은 사용자의 중복 방문을 한 번만 셉니다. home은 user 1,2 → 2명, cart는 user 2,3,1 → 3명입니다.\n💡 개념: COUNT(*)는 행 수, COUNT(DISTINCT col)는 고유값 수로 의미가 다릅니다. UV(순방문자)와 PV(페이지뷰)의 차이와 같습니다.\n🛠 실무: DAU/MAU, 고유 구매자 수, 유입 경로별 순사용자 집계의 기본 지표입니다."},{"t":"sql","k":"sqlx2-limit-offset-page2","q":"products3 테이블을 price 내림차순으로 정렬했을 때 3번째와 4번째에 해당하는 상품(페이지 크기 2의 2페이지)을 name, price 컬럼으로 출력하세요.","schema":"CREATE TABLE products3 (id INTEGER, name TEXT, price INTEGER);\nINSERT INTO products3 VALUES (1,'A',500),(2,'B',400),(3,'C',300),(4,'D',200),(5,'E',100);","src":"-- 힌트: ORDER BY price DESC 후 LIMIT 2 OFFSET 2 로 2페이지를 가져오세요.\n-- 아래는 첫 페이지(1~2위)를 가져오는 미완성 쿼리입니다.\nSELECT name, price FROM products3 ORDER BY price DESC LIMIT 2 OFFSET 0;","sol":"SELECT name, price FROM products3 ORDER BY price DESC LIMIT 2 OFFSET 2;","ordered":true,"cat":"perf","ex":"OFFSET 2는 상위 2건을 건너뛰고 LIMIT 2로 그 다음 2건을 가져옵니다. 500,400 다음인 C(300), D(200)입니다.\n💡 개념: 페이지 N은 OFFSET (N-1)*크기 로 계산합니다. 안정적 페이지네이션에는 결정적 ORDER BY(동점 시 tie-breaker 컬럼)가 필요합니다.\n🛠 실무: 목록 페이지네이션에 쓰지만 OFFSET이 커지면 느려집니다. 대량 데이터는 키셋(seek) 페이지네이션이 유리합니다."},{"t":"sql","k":"sqlx2-recursive-org-tree","q":"org 테이블(parent_id로 계층 표현)에서 최상위(parent_id가 NULL)를 레벨 0으로 두고 재귀 CTE로 계층을 전개하여 각 노드의 name, lvl 컬럼을 lvl 오름차순, 같으면 name 오름차순으로 출력하세요.","schema":"CREATE TABLE org (id INTEGER, name TEXT, parent_id INTEGER);\nINSERT INTO org VALUES (1,'본사',NULL),(2,'영업본부',1),(3,'개발본부',1),(4,'영업1팀',2),(5,'개발1팀',3);","src":"-- 힌트: WITH RECURSIVE tree(id,name,lvl) AS ( 앵커: parent_id IS NULL, lvl 0  UNION ALL  재귀: 자식 조인하며 lvl+1 )\n-- 아래는 최상위 한 노드만 반환하는 미완성 쿼리입니다.\nSELECT name, 0 AS lvl FROM org WHERE parent_id IS NULL ORDER BY lvl, name;","sol":"WITH RECURSIVE tree(id, name, lvl) AS (\n  SELECT id, name, 0 FROM org WHERE parent_id IS NULL\n  UNION ALL\n  SELECT o.id, o.name, t.lvl + 1 FROM org o JOIN tree t ON o.parent_id = t.id\n)\nSELECT name, lvl FROM tree ORDER BY lvl, name;","ordered":true,"cat":"design","ex":"앵커(본사, lvl 0)에서 시작해 재귀 항이 자식을 붙이며 lvl을 1씩 늘립니다. 본사(0), 개발본부/영업본부(1), 개발1팀/영업1팀(2)이 나옵니다.\n💡 개념: 재귀 CTE는 앵커 멤버와 재귀 멤버를 UNION ALL로 연결하고, 재귀 멤버가 CTE 자신을 참조하다 더 이상 행이 없으면 멈춥니다.\n🛠 실무: 조직도, 카테고리 트리, 댓글 스레드, BOM(부품 전개) 등 계층 데이터 순회에 씁니다."},{"t":"sql","k":"sqlx2-antijoin-never-ordered","q":"products4 테이블의 상품 중 한 번도 주문(order_items)되지 않은 상품의 pname을 pname 오름차순 출력하세요.","schema":"CREATE TABLE products4 (id INTEGER, pname TEXT);\nINSERT INTO products4 VALUES (1,'사과'),(2,'바나나'),(3,'체리'),(4,'딸기');\nCREATE TABLE order_items (order_id INTEGER, product_id INTEGER);\nINSERT INTO order_items VALUES (100,1),(100,3),(101,1);","src":"-- 힌트: NOT EXISTS 서브쿼리 또는 LEFT JOIN ... WHERE oi.product_id IS NULL 로 안티조인 하세요.\n-- 아래는 주문 여부와 무관하게 모든 상품을 나열한 미완성 쿼리입니다.\nSELECT pname FROM products4 ORDER BY pname;","sol":"SELECT pname FROM products4 p WHERE NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.product_id = p.id) ORDER BY pname;","ordered":true,"cat":"design","ex":"NOT EXISTS는 주문 내역에 매칭되는 행이 하나도 없는 상품만 남깁니다. 주문된 사과(1), 체리(3)를 뺀 딸기, 바나나가 결과입니다.\n💡 개념: 차집합(존재하지 않음)은 NOT EXISTS 또는 LEFT JOIN + IS NULL로 구현하는 안티조인 패턴입니다. NOT IN은 서브쿼리에 NULL이 있으면 결과가 사라지는 함정이 있어 NOT EXISTS가 안전합니다.\n🛠 실무: 미구매 상품, 활동 없는 사용자, 미처리 주문 등 '없는 것 찾기'에 광범위하게 쓰입니다."}],"th":{"sum":"실행 채점(SQLite)에서는 서브쿼리·`JOIN`·`GROUP BY`·`CASE`·`COALESCE`·집합·날짜 문자열을 정확한 **컬럼명과 정렬**로 출력해야 한다.","body":[{"h":"서브쿼리·조인·CASE","t":"'평균보다 비싼 상품'은 `WHERE price > (SELECT AVG(price) FROM products)`. self-join으로 직원-매니저를 잇고, 매니저 없는 사람 제외는 INNER JOIN이 자연스럽다. 등급별 인원은 `CASE`로 등급을 만들고 `GROUP BY grade, COUNT(*)`. 요구한 컬럼 별칭(`AS`)과 순서를 정확히 맞춘다."},{"h":"집계·NULL·날짜·집합","t":"각 region 최대값과 같은 행은 상관 서브쿼리나 윈도우로 뽑는다. NULL 대체는 `COALESCE(bonus,0)`. 월별 매출은 SQLite `strftime('%Y-%m', d)`로 'YYYY-MM'을 만들어 `GROUP BY`한다. 중복 없는 합집합은 `UNION`이다. `ORDER BY`는 문제가 지정한 컬럼·방향대로 마지막에 붙인다."}],"code":{"c":"SELECT name, price\nFROM products\nWHERE price > (SELECT AVG(price) FROM products)\nORDER BY price DESC;","cap":"전체 평균보다 비싼 상품을 가격 내림차순"},"key":["평균 비교는 스칼라 서브쿼리, 등급은 `CASE`+`GROUP BY`","NULL 대체 `COALESCE`, 월 추출 `strftime('%Y-%m', d)`","중복 제거 합집합 `UNION`, 컬럼명·정렬을 정확히"]}}]},{"t":"직접 SQL — 실행 채점 (SQLite)","l":[{"t":"조인·집계·윈도우 실습","q":[{"t":"sql","k":"sqlx-groupcount","q":"도시별 사용자 수를 구하세요. 컬럼은 city, cnt 순서로, 도시명 오름차순 정렬.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- users 테이블에서 도시별 인원수\nSELECT city, COUNT(*) AS cnt\nFROM users\n-- GROUP BY 와 ORDER BY 를 채우세요\n","sol":"SELECT city, COUNT(*) AS cnt FROM users GROUP BY city ORDER BY city","ordered":true,"ex":"GROUP BY city 로 묶고 COUNT(*)로 세어 city 오름차순 정렬합니다.\n💡 개념: 집계 함수는 GROUP BY로 만든 그룹마다 한 번씩 계산됩니다.\n🛠 실무: 대시보드의 '지역별 사용자' 같은 지표가 정확히 이 패턴입니다.","cat":"perf"},{"t":"sql","k":"sqlx-joinsum","q":"사용자별 총 주문 금액을 구하세요. 컬럼은 name, total 순서, total 내림차순 정렬. 주문이 있는 사용자만.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- users 와 orders 를 조인해 사용자별 합계\nSELECT u.name, SUM(o.amount) AS total\nFROM users u\nJOIN orders o ON u.id = o.user_id\n-- GROUP BY, ORDER BY 채우기\n","sol":"SELECT u.name, SUM(o.amount) AS total FROM users u JOIN orders o ON u.id=o.user_id GROUP BY u.id ORDER BY total DESC","ordered":true,"ex":"INNER JOIN으로 두 테이블을 연결하고 사용자별로 SUM을 구해 내림차순 정렬합니다.\n💡 개념: JOIN 후 GROUP BY u.id 로 묶으면 사용자 단위 집계가 됩니다.\n🛠 실무: '고객별 매출' 리포트의 기본형. INNER JOIN이라 주문 없는 사용자는 자동 제외됩니다.","cat":"design"},{"t":"sql","k":"sqlx-having","q":"주문을 2건 이상 한 사용자의 이름과 주문 건수를 구하세요. 컬럼 name, cnt, cnt 내림차순.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- HAVING 으로 그룹 조건을 거세요\nSELECT u.name, COUNT(*) AS cnt\nFROM users u JOIN orders o ON u.id=o.user_id\n\n","sol":"SELECT u.name, COUNT(*) AS cnt FROM users u JOIN orders o ON u.id=o.user_id GROUP BY u.id HAVING COUNT(*)>=2 ORDER BY cnt DESC","ordered":true,"ex":"WHERE는 행을, HAVING은 그룹을 거릅니다. 집계 결과(COUNT)로 필터하려면 HAVING을 씁니다.\n💡 개념: 실행 순서는 WHERE → GROUP BY → HAVING → SELECT → ORDER BY.\n🛠 실무: '충성 고객(N회 이상 구매)' 세그먼트 추출에 그대로 쓰입니다.","cat":"perf"},{"t":"sql","k":"sqlx-nolefti","q":"한 번도 주문하지 않은 사용자의 이름을 구하세요. 컬럼 name.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- LEFT JOIN 후 매칭이 없는 행을 찾으세요\nSELECT u.name\nFROM users u\nLEFT JOIN orders o ON u.id=o.user_id\n\n","sol":"SELECT u.name FROM users u LEFT JOIN orders o ON u.id=o.user_id WHERE o.id IS NULL","ordered":false,"ex":"LEFT JOIN은 오른쪽에 매칭이 없어도 NULL로 남깁니다. o.id IS NULL 이면 주문이 없다는 뜻입니다.\n💡 개념: '존재하지 않음'은 NOT IN, NOT EXISTS, LEFT JOIN+IS NULL 세 가지로 표현할 수 있습니다.\n🛠 실무: '가입했지만 미구매' 사용자 타겟팅에 필수 패턴입니다.","cat":"design"},{"t":"sql","k":"sqlx-rank","q":"각 주문의 금액 순위를 매기세요(1위가 가장 큰 금액). 컬럼 product, amount, rnk. rnk 오름차순.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- 윈도우 함수 RANK() 를 사용하세요\nSELECT product, amount,\n       RANK() OVER (/* 정렬 기준 */) AS rnk\nFROM orders\nORDER BY rnk\n","sol":"SELECT product, amount, RANK() OVER (ORDER BY amount DESC) AS rnk FROM orders ORDER BY rnk","ordered":true,"ex":"RANK() OVER (ORDER BY amount DESC)는 GROUP BY 없이 각 행에 순위를 부여합니다.\n💡 개념: 윈도우 함수는 행을 접지 않고(집계와 달리) 각 행 옆에 계산값을 붙입니다. 동점은 같은 순위+건너뜀.\n🛠 실무: '매출 상위 N', '카테고리별 랭킹'을 한 방에 뽑을 때 GROUP BY보다 강력합니다.","cat":"perf"},{"t":"sql","k":"sqlx-cte-month","q":"월별 매출 합계를 구하세요. 컬럼 mon('YYYY-MM'), total, mon 오름차순. CTE를 활용하세요.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- WITH 로 월(mon)을 만든 뒤 집계하세요. (SQLite: strftime('%Y-%m', created))\nWITH m AS (\n  SELECT strftime('%Y-%m', created) AS mon, amount FROM orders\n)\nSELECT mon, SUM(amount) AS total\nFROM m\n\n","sol":"WITH m AS (SELECT strftime('%Y-%m', created) AS mon, amount FROM orders) SELECT mon, SUM(amount) AS total FROM m GROUP BY mon ORDER BY mon","ordered":true,"ex":"CTE(WITH)로 '월' 파생 컬럼을 먼저 만든 뒤 그것으로 그룹 집계하면 쿼리가 읽기 쉬워집니다.\n💡 개념: CTE는 이름 붙인 임시 결과셋입니다. 서브쿼리를 위에서 정의해 가독성을 높입니다.\n🛠 실무: 복잡한 리포트를 단계(정제→집계→랭킹)로 쪼갤 때 CTE를 층층이 씁니다.","cat":"design"},{"t":"sql","k":"sqlx-distinct-city","q":"10만원 이상 주문을 한 사용자가 사는 도시를 중복 없이 구하세요. 컬럼 city, 오름차순.","schema":"CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, city TEXT, joined TEXT);CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER, product TEXT, amount INTEGER, created TEXT);INSERT INTO users VALUES (1,'김지은','서울','2024-01-05'),(2,'이준호','부산','2024-02-11'),(3,'박서연','서울','2024-03-02'),(4,'최민수','대구','2024-03-20'),(5,'정하나','서울','2024-04-01');INSERT INTO orders VALUES (1,1,'노트북',1200000,'2024-04-01'),(2,1,'마우스',30000,'2024-04-03'),(3,2,'키보드',80000,'2024-04-05'),(4,3,'노트북',1250000,'2024-04-06'),(5,3,'모니터',300000,'2024-04-10'),(6,2,'노트북',1180000,'2024-05-01'),(7,4,'마우스',25000,'2024-05-02'),(8,1,'모니터',320000,'2024-05-11'),(9,3,'키보드',75000,'2024-05-15'),(10,2,'모니터',310000,'2024-06-02');","src":"-- 조인 + 조건 + 중복 제거\nSELECT DISTINCT u.city\nFROM users u JOIN orders o ON u.id=o.user_id\n\n","sol":"SELECT DISTINCT u.city FROM users u JOIN orders o ON u.id=o.user_id WHERE o.amount>=100000 ORDER BY city","ordered":true,"ex":"WHERE로 고가 주문만 남기고 DISTINCT로 도시 중복을 제거합니다.\n💡 개념: DISTINCT는 SELECT된 컬럼 조합의 유일값만 남깁니다.\n🛠 실무: '고액 구매가 발생한 지역' 같은 커버리지 분석에 쓰입니다.","cat":"design"}],"th":{"sum":"직접 작성 실습에서는 `GROUP BY` 집계, `LEFT JOIN`/`NOT EXISTS`, 윈도우 순위, `CTE`를 조합해 요구 **컬럼 순서·정렬**을 지켜 출력한다.","body":[{"h":"집계와 조인","t":"도시별 인원은 `GROUP BY city, COUNT(*) AS cnt` 후 `ORDER BY city`. 사용자별 총 주문액은 users와 orders를 조인해 `SUM`하고 주문 있는 사용자만 나오게 INNER JOIN, `ORDER BY total DESC`. '2건 이상'은 `HAVING COUNT(*) >= 2`. '한 번도 주문 안 한' 사용자는 `LEFT JOIN ... WHERE o.id IS NULL`이나 `NOT EXISTS`로 찾는다."},{"h":"윈도우와 CTE","t":"금액 순위는 `RANK() OVER (ORDER BY amount DESC) AS rnk`로 매기고 `ORDER BY rnk`. 월별 매출 합계는 `WITH` CTE에서 `strftime('%Y-%m', d) AS mon`으로 묶어 `SUM`한 뒤 `ORDER BY mon`. 10만원 이상 주문 도시는 조인 후 `DISTINCT city`로 중복을 없앤다."}],"code":{"c":"SELECT u.name, COUNT(*) AS cnt\nFROM users u\nJOIN orders o ON o.user_id = u.id\nGROUP BY u.name\nHAVING COUNT(*) >= 2\nORDER BY cnt DESC;","cap":"주문 2건 이상 사용자와 건수(내림차순)"},"key":["그룹 집계 후 `HAVING`으로 건수 필터","'주문 없음'은 `LEFT JOIN ... IS NULL`/`NOT EXISTS`","순위는 `RANK() OVER`, 월별은 CTE+`strftime`, 중복은 `DISTINCT`"]}}]},{"t":"분산 데이터베이스 - 복제와 샤딩","l":[{"t":"복제와 복제 지연","q":[{"t":"choice","k":"복제지연","cat":"design","q":"사용자가 프로필을 수정한 직후 새로고침했더니 예전 값이 보인다. 쓰기는 마스터, 읽기는 리드 리플리카로 분산된 구조다. 원인은?","o":["비동기 복제의 복제 지연(replication lag)으로 리플리카가 아직 최신 쓰기를 반영하지 못함","마스터 디스크 장애로 쓰기가 실패함","커넥션 풀 고갈로 요청이 큐잉됨","인덱스 누락으로 인한 풀스캔 지연"],"a":0,"ex":"비동기 복제에서 리플리카가 마스터를 따라잡기 전에 읽으면 stale read가 발생한다.\n💡 개념: read-your-writes 일관성이 깨지는 전형적 사례로, 원인은 복제 지연이다.\n🛠 실무: 쓰기 직후 읽기는 마스터로 라우팅하거나 세션 스티키니스를 걸고, 리플리카 lag 임계를 넘으면 마스터로 fallback한다."},{"t":"choice","k":"동기복제","cat":"design","q":"금융 잔액처럼 유실이 절대 안 되는 데이터에 동기(synchronous) 복제를 택할 때 감수해야 하는 대가는?","o":["쓰기 지연 증가와 가용성 저하로, 리플리카 장애 시 쓰기가 블록될 수 있음","데이터 유실 위험이 오히려 커짐","읽기 성능이 심각하게 저하됨","스토리지 사용량이 필연적으로 2배가 됨"],"a":0,"ex":"동기 복제는 리플리카 ack를 기다린 뒤 커밋하므로 지연이 늘고, 리플리카가 죽으면 쓰기가 막힐 수 있다.\n💡 개념: 강한 내구성과 가용성/지연 사이의 트레이드오프다.\n🛠 실무: 유실이 치명적인 데이터만 동기 복제로 두고, 반동기 복제로 최소 1개 ack만 요구해 지연을 완화한다."},{"t":"input","k":"반동기복제","cat":"design","q":"최소 하나의 리플리카가 쓰기를 받았다고 ack하면 커밋을 완료하는, 동기와 비동기의 절충 복제 방식을 무엇이라 하나?","a":["반동기 복제","semi-synchronous replication","세미싱크","반동기"],"ex":"반동기 복제는 최소 1개 리플리카의 수신 확인만 기다린다.\n💡 개념: 완전 동기의 지연과 완전 비동기의 유실 위험 사이를 절충한다.\n🛠 실무: 하나의 리플리카가 커밋 로그를 받았음을 보장해 failover 시 유실을 줄이되, 타임아웃 시 비동기로 자동 강등되는 설정에 주의한다."},{"t":"choice","k":"멀티리더","cat":"design","q":"지역별로 각각 쓰기를 받는 멀티 리더(multi-leader) 복제를 도입했다. 가장 먼저 설계해야 할 문제는?","o":["동일 레코드에 대한 동시 쓰기 충돌 해결(conflict resolution) 전략","리드 리플리카의 복제 지연 모니터링","인덱스 재구성 스케줄","커넥션 풀 크기 튜닝"],"a":0,"ex":"여러 리더가 같은 행을 동시에 수정하면 충돌이 발생하므로 해결 정책이 선행되어야 한다.\n💡 개념: last-write-wins, 버전 벡터, 애플리케이션 병합 등 충돌 해결 전략이 핵심이다.\n🛠 실무: 지역별로 쓰기 대상을 분리(파티셔닝)해 충돌 가능성 자체를 줄이거나, CRDT/버전 벡터로 병합한다."},{"t":"choice","k":"failover유실","cat":"design","q":"비동기 복제 환경에서 마스터가 죽어 리플리카로 failover했더니 마지막 몇 건의 커밋이 사라졌다. 근본 원인은?","o":["마스터가 아직 리플리카에 전파하지 못한 커밋이 failover 시점에 유실됨","리플리카 디스크가 물리적으로 손상됨","네트워크 스위치 설정 오류","트랜잭션 격리 수준 설정 실수"],"a":0,"ex":"비동기 복제는 마스터 커밋과 전파 사이 시간차가 있어, 그 사이 마스터가 죽으면 미전파 커밋이 사라진다.\n💡 개념: 비동기 복제의 durability 갭이 failover 데이터 유실로 이어진다.\n🛠 실무: 유실이 치명적이면 반동기/동기 복제를 쓰거나, failover 전 리플리카 lag가 0인지 확인한다."}],"th":{"sum":"비동기 복제는 **복제 지연**으로 방금 쓴 값을 리플리카에서 못 읽거나 failover 시 마지막 커밋이 유실될 수 있다. 샤딩 키는 **트래픽이 골고루 퍼지게** 골라야 한다.","body":[{"h":"복제와 지연","t":"쓰기는 마스터, 읽기는 리플리카로 나누면 비동기 복제 지연 탓에 수정 직후 조회 시 옛 값이 보인다(read-your-writes 문제). 동기 복제는 유실을 막지만 지연·가용성 저하를 감수해야 하고, 그 절충이 최소 한 리플리카의 ack를 기다리는 **반동기(semi-sync)** 복제다. 비동기에서 마스터가 죽어 failover하면 아직 복제 안 된 커밋이 사라진다. 멀티 리더는 쓰기 충돌 해결(conflict resolution)을 가장 먼저 설계해야 한다."},{"h":"샤딩과 파티셔닝","t":"auto-increment를 샤드 키로 쓰면 최신 데이터가 한 샤드로 몰리는 핫스팟이 생긴다. 해시 기반 키나 값 분산이 좋은 키로 바꿔 고르게 분포시킨다. 서로 다른 샤드의 테이블을 앱이 모아 합치는 것을 **스캐터-개더(scatter-gather)**/크로스 샤드 조인이라 하며 느리고 복잡하다."}],"code":{"c":"-- 핫스팟 방지: 순번 대신 해시 샤드 키\n-- shard = hash(user_id) % N\nSELECT * FROM orders_shard_3\nWHERE user_id = 8842;","cap":"auto-increment 대신 해시로 샤드 분산"},"key":["비동기 복제 지연 → 방금 쓴 값 못 읽음","반동기=한 리플리카 ack 대기(절충)","순번 샤드 키는 핫스팟, 해시로 분산; 크로스 샤드 조인=scatter-gather"]}},{"t":"샤딩과 파티셔닝","q":[{"t":"choice","k":"샤드키핫스팟","cat":"design","q":"주문 테이블을 샤딩하는데 샤드 키로 auto-increment 순번을 썼더니 최신 트래픽이 한 샤드에 몰린다. 원인과 개선은?","o":["순차 키가 특정 샤드에 집중되는 핫스팟; 해시 기반 또는 고카디널리티 키로 분산","샤드 수가 부족한 것뿐; 샤드만 늘리면 됨","복제 지연 때문; 리플리카를 추가","인덱스 부재; 인덱스만 추가하면 해결"],"a":0,"ex":"단조 증가 키는 항상 마지막 샤드로 라우팅되어 쓰기가 한 곳에 몰린다.\n💡 개념: 좋은 샤드 키는 카디널리티가 높고 접근이 고르게 분산되어야 한다.\n🛠 실무: 해시 샤딩을 쓰거나, 사용자ID처럼 분산이 고른 키를 선택하고, 시간 기반은 해시와 조합한다."},{"t":"input","k":"크로스샤드조인","cat":"design","q":"서로 다른 샤드에 있는 테이블을 조인하기 위해 애플리케이션이 여러 샤드에서 데이터를 모아 합치는, 성능 저하와 복잡도를 유발하는 이 연산을 무엇이라 하나?","a":["크로스샤드 조인","cross-shard join","분산 조인","교차 샤드 조인"],"ex":"크로스샤드 조인은 여러 샤드에 흩어진 데이터를 앱 레벨에서 취합해야 한다.\n💡 개념: 샤딩은 조인 지역성을 깨뜨려 분산 조인 비용을 유발한다.\n🛠 실무: 함께 조회되는 데이터는 같은 샤드 키로 co-location하거나, 조회 전용 비정규화 테이블을 둔다."},{"t":"choice","k":"range vs hash","cat":"design","q":"시계열 로그를 날짜 기준 range로 파티셔닝했더니 최근 파티션에만 쓰기가 집중된다. 쓰기 균등 분산이 최우선이라면?","o":["해시 파티셔닝으로 전환해 쓰기를 여러 파티션에 고르게 분산","파티션을 더 잘게 range로 쪼갬","리스트 파티셔닝으로 변경","파티션을 아예 없앰"],"a":0,"ex":"날짜 range 파티셔닝은 최신 시점에 쓰기가 몰리는 핫 파티션을 만든다.\n💡 개념: range는 범위 조회와 오래된 파티션 삭제에 유리하지만 쓰기 편중이 단점이다.\n🛠 실무: 쓰기 분산이 목표면 해시로, 시간범위 조회와 파티션 드롭이 목표면 range로, 필요하면 둘을 조합한다."},{"t":"choice","k":"일관된해싱","cat":"design","q":"샤드를 hash(key) % N 으로 배치했는데 샤드를 N개에서 N+1개로 늘리자 거의 모든 키가 재배치됐다. 리밸런싱 부담을 줄이려면?","o":["일관된 해싱(consistent hashing)을 도입해 재배치되는 키 범위를 최소화","샤드 수를 항상 2배로만 늘림","range 파티셔닝으로 전면 변경","리플리카만 추가"],"a":0,"ex":"모듈로 방식은 N이 바뀌면 대부분의 키 매핑이 달라져 대규모 데이터 이동이 발생한다.\n💡 개념: 일관된 해싱은 노드 추가/삭제 시 인접 구간의 키만 이동시킨다.\n🛠 실무: 가상 노드(vnode)를 두어 분산을 고르게 하고, 온라인 리밸런싱으로 점진 이전한다."},{"t":"choice","k":"list파티셔닝","cat":"design","q":"국가 코드처럼 값의 집합이 명확히 정해진 컬럼으로 데이터를 나눌 때 가장 적합한 파티셔닝 방식은?","o":["리스트(list) 파티셔닝","레인지(range) 파티셔닝","해시(hash) 파티셔닝","라운드로빈 분배"],"a":0,"ex":"값이 이산적이고 명시적으로 열거 가능한 경우 리스트 파티셔닝이 적합하다.\n💡 개념: range는 연속 범위, hash는 균등 분산, list는 명시적 값 집합에 쓴다.\n🛠 실무: 국가/지역별 규제 격리나 지역별 조회 편의를 위해 list 파티셔닝을 활용한다."}],"th":{"sum":"비동기 복제는 **복제 지연**으로 방금 쓴 값을 리플리카에서 못 읽거나 failover 시 마지막 커밋이 유실될 수 있다. 샤딩 키는 **트래픽이 골고루 퍼지게** 골라야 한다.","body":[{"h":"복제와 지연","t":"쓰기는 마스터, 읽기는 리플리카로 나누면 비동기 복제 지연 탓에 수정 직후 조회 시 옛 값이 보인다(read-your-writes 문제). 동기 복제는 유실을 막지만 지연·가용성 저하를 감수해야 하고, 그 절충이 최소 한 리플리카의 ack를 기다리는 **반동기(semi-sync)** 복제다. 비동기에서 마스터가 죽어 failover하면 아직 복제 안 된 커밋이 사라진다. 멀티 리더는 쓰기 충돌 해결(conflict resolution)을 가장 먼저 설계해야 한다."},{"h":"샤딩과 파티셔닝","t":"auto-increment를 샤드 키로 쓰면 최신 데이터가 한 샤드로 몰리는 핫스팟이 생긴다. 해시 기반 키나 값 분산이 좋은 키로 바꿔 고르게 분포시킨다. 서로 다른 샤드의 테이블을 앱이 모아 합치는 것을 **스캐터-개더(scatter-gather)**/크로스 샤드 조인이라 하며 느리고 복잡하다."}],"code":{"c":"-- 핫스팟 방지: 순번 대신 해시 샤드 키\n-- shard = hash(user_id) % N\nSELECT * FROM orders_shard_3\nWHERE user_id = 8842;","cap":"auto-increment 대신 해시로 샤드 분산"},"key":["비동기 복제 지연 → 방금 쓴 값 못 읽음","반동기=한 리플리카 ack 대기(절충)","순번 샤드 키는 핫스팟, 해시로 분산; 크로스 샤드 조인=scatter-gather"]}}]},{"t":"분산 데이터베이스 - 일관성과 트랜잭션","l":[{"t":"일관성, CAP, 쿼럼","q":[{"t":"choice","k":"CAP","cat":"design","q":"네트워크 파티션이 발생한 순간, CAP 정리에 따르면 분산 시스템이 동시에 보장할 수 없는 것은?","o":["일관성(C)과 가용성(A)을 동시에 만족할 수 없다","일관성(C)과 파티션 내성(P)","가용성(A)과 파티션 내성(P)","세 가지 모두 항상 보장 가능하다"],"a":0,"ex":"파티션(P)이 불가피한 분산 환경에서는 파티션 발생 시 C와 A 중 하나를 포기해야 한다.\n💡 개념: CAP은 파티션 상황에서 CP(일관성 우선)냐 AP(가용성 우선)냐의 선택 문제다.\n🛠 실무: 잔액은 CP로 오류를 반환하고, 장바구니는 AP로 응답 후 나중에 병합하는 식으로 도메인별로 결정한다."},{"t":"input","k":"쿼럼공식","cat":"design","q":"노드 N개 복제에서 쓰기 W개, 읽기 R개 노드의 응답을 요구할 때, 최신값 읽기를 보장하기 위해 만족해야 하는 부등식을 W, R, N으로 쓰면? (형식: W + R &gt; N)","a":["W + R &gt; N","W+R&gt;N","R + W &gt; N","r+w&gt;n"],"ex":"W + R &gt; N이면 읽기 쿼럼과 쓰기 쿼럼이 최소 한 노드에서 겹쳐 최신값을 읽는다.\n💡 개념: 쿼럼 겹침이 강한 일관성의 조건이다.\n🛠 실무: W=R=(N/2)+1로 잡으면 균형이 좋고, 읽기 지연을 줄이려면 W를 키우고 R을 줄인다."},{"t":"choice","k":"최종일관성","cat":"design","q":"좋아요 수 카운터처럼 잠깐 오차가 있어도 되는 데이터에 강한 일관성 대신 최종 일관성을 택하는 이유는?","o":["가용성과 낮은 지연시간, 높은 쓰기 처리량을 확보하기 위해","데이터 정확성을 더 높이기 위해","스토리지를 절약하기 위해","트랜잭션을 완전히 없애기 위해"],"a":0,"ex":"최종 일관성은 즉시 합의를 기다리지 않아 빠르고 가용성이 높다.\n💡 개념: 일관성 강도와 성능/가용성은 트레이드오프 관계다.\n🛠 실무: 정확성이 덜 중요한 지표성 데이터는 최종 일관성으로 처리량을 확보하고, 잔액 등은 강한 일관성을 유지한다."},{"t":"choice","k":"쿼럼설정","cat":"design","q":"가용성만 보고 N=3 복제에서 W=1, R=1로 설정했다. 어떤 문제가 생기나?","o":["W+R이 N 이하라 쿼럼이 겹치지 않아 stale read가 가능","쓰기가 지나치게 느려짐","노드 하나만 죽어도 쓰기가 불가능해짐","스토리지가 낭비됨"],"a":0,"ex":"W+R = 2 ≤ 3이므로 읽기/쓰기 쿼럼이 겹치지 않아 옛 값을 읽을 수 있다.\n💡 개념: 쿼럼 겹침이 없으면 강한 일관성이 깨진다.\n🛠 실무: 강한 일관성이 필요하면 W+R &gt; N을 만족하도록 값을 올리고, read repair와 anti-entropy로 수렴을 돕는다."},{"t":"choice","k":"선형화","cat":"design","q":"여러 클라이언트가 봐도 마치 단일 최신 복사본 하나에 순차적으로 접근하는 것처럼 보이는 가장 강한 일관성 모델은?","o":["선형화 가능성(linearizability)","최종 일관성(eventual consistency)","인과 일관성(causal consistency)","읽기 커밋(read committed)"],"a":0,"ex":"선형화 가능성은 모든 연산이 실시간 순서를 지키는 단일 복사본처럼 동작하게 한다.\n💡 개념: 가장 강한 일관성 모델로 구현 비용과 지연이 크다.\n🛠 실무: 분산 락, 리더 선출, 유일성 보장이 필요한 곳에만 쓰고, 나머지는 완화된 모델로 성능을 확보한다."}],"th":{"sum":"네트워크 파티션 시 **CAP**에서 일관성(C)과 가용성(A)을 동시에 못 지킨다. 쿼럼은 `W + R > N`이면 최신값 읽기를 보장한다.","body":[{"h":"CAP과 쿼럼","t":"파티션(P)이 불가피한 분산 시스템은 C와 A 중 하나를 포기한다. 쿼럼 복제는 쓰기 W개·읽기 R개 노드 응답을 요구하며, `W + R > N`이면 읽기·쓰기 집합이 겹쳐 최신값을 본다. N=3에 W=1,R=1은 W+R=2 ≤ 3이라 최신 보장이 안 돼 오래된 값을 읽을 수 있다. 좋아요 수처럼 오차 허용 데이터는 최종 일관성으로 가용성·성능을 택한다. 단일 최신본에 순차 접근하는 듯한 가장 강한 모델은 **선형성(linearizability)**이다."},{"h":"2PC","t":"2단계 커밋은 1단계 **prepare(준비)**에서 코디네이터가 모든 참여자에게 커밋 가능 여부를 묻고 각자 락을 잡은 뒤, 2단계에서 commit/abort를 지시한다. prepare 후 commit 지시 전에 코디네이터가 죽으면 참여자들이 락을 쥔 채 결정을 못 내리는 **블로킹**에 빠진다."}],"code":{"c":"-- 쿼럼 예: N=3\n-- W=2, R=2  ->  W + R = 4 > 3  (최신값 보장)\n-- W=1, R=1  ->  W + R = 2 <= 3 (보장 안 됨)","cap":"쿼럼 부등식 W+R>N으로 최신 읽기 판단"},"key":["파티션 시 CAP: C와 A 동시 불가","최신 읽기 조건 `W + R > N`","2PC prepare 후 코디네이터 사망=블로킹"]}},{"t":"분산 트랜잭션과 2PC","q":[{"t":"choice","k":"2PC블로킹","cat":"design","q":"2단계 커밋(2PC)에서 코디네이터가 prepare 후 commit 지시를 내리기 전에 죽으면 어떤 함정이 생기나?","o":["참여자들이 락을 쥔 채 결정을 기다리며 무기한 블로킹됨","자동으로 즉시 롤백됨","데이터가 물리적으로 유실됨","모든 참여자가 자동 커밋됨"],"a":0,"ex":"prepare 이후 참여자는 스스로 결정할 수 없어 코디네이터 복구까지 락을 쥐고 대기한다.\n💡 개념: 코디네이터가 단일 장애점이 되는 2PC의 대표적 함정이다.\n🛠 실무: 코디네이터를 다중화하거나 타임아웃/휴리스틱 결정을 두고, 가능하면 saga로 대체한다."},{"t":"input","k":"2PC단계","cat":"design","q":"2단계 커밋의 두 단계 중, 코디네이터가 모든 참여자에게 커밋 준비가 되었는지 묻고 각자 락을 잡는 첫 단계를 무엇이라 하나?","a":["prepare 단계","준비 단계","prepare","voting phase","투표 단계"],"ex":"첫 단계는 prepare(투표) 단계로, 참여자는 커밋 가능 여부를 투표하고 자원을 잠근다.\n💡 개념: 이후 commit 단계에서 코디네이터가 최종 결정을 전파한다.\n🛠 실무: prepare~commit 사이 락 보유 시간이 길수록 동시성이 떨어지므로 트랜잭션 범위를 최소화한다."},{"t":"choice","k":"saga","cat":"design","q":"마이크로서비스 간 장기 분산 트랜잭션에서 2PC의 블로킹을 피하려고, 각 로컬 트랜잭션 실패 시 보상 트랜잭션으로 되돌리는 패턴은?","o":["사가(saga) 패턴","2단계 커밋(2PC)","3단계 커밋(3PC)","쿼럼 쓰기"],"a":0,"ex":"사가는 여러 로컬 트랜잭션을 순차 실행하고, 실패하면 이미 수행한 단계를 보상 트랜잭션으로 되돌린다.\n💡 개념: 원자성 대신 최종 일관성과 보상 로직으로 분산 트랜잭션을 구현한다.\n🛠 실무: 오케스트레이션 또는 코레오그래피로 구성하고, 각 단계의 멱등성과 보상 가능성을 반드시 설계한다."},{"t":"choice","k":"2PC성능","cat":"design","q":"2PC를 마이크로서비스 API 호출마다 적용했더니 처리량이 급락했다. 근본 이유는?","o":["prepare~commit 사이 참여자들이 락을 오래 잡아 동시성이 크게 떨어짐","네트워크 대역폭이 부족해서","JSON 직렬화 오버헤드 때문에","인덱스 락 경합 때문에"],"a":0,"ex":"2PC는 커밋 확정 전까지 자원을 잠그므로 여러 서비스가 얽히면 락 대기가 누적된다.\n💡 개념: 분산 락 보유 시간이 곧 동시성 병목이 된다.\n🛠 실무: 강한 원자성이 꼭 필요한 곳만 2PC로 최소화하고, 나머지는 saga와 멱등 재시도로 전환한다."},{"t":"choice","k":"멱등성","cat":"design","q":"분산 결제에서 네트워크 타임아웃으로 재시도할 때 중복 청구를 막기 위해, 각 요청에 유니크 키를 부여해 한 번만 처리되게 하는 성질은?","o":["멱등성(idempotency)","원자성(atomicity)","격리성(isolation)","지속성(durability)"],"a":0,"ex":"멱등성은 같은 요청을 여러 번 보내도 결과가 한 번 처리한 것과 동일하도록 보장한다.\n💡 개념: 분산 환경의 재시도/중복 전달을 안전하게 만드는 핵심 성질이다.\n🛠 실무: idempotency key를 저장하고 중복 요청을 서버에서 걸러 결제/주문 중복을 방지한다."}],"th":{"sum":"네트워크 파티션 시 **CAP**에서 일관성(C)과 가용성(A)을 동시에 못 지킨다. 쿼럼은 `W + R > N`이면 최신값 읽기를 보장한다.","body":[{"h":"CAP과 쿼럼","t":"파티션(P)이 불가피한 분산 시스템은 C와 A 중 하나를 포기한다. 쿼럼 복제는 쓰기 W개·읽기 R개 노드 응답을 요구하며, `W + R > N`이면 읽기·쓰기 집합이 겹쳐 최신값을 본다. N=3에 W=1,R=1은 W+R=2 ≤ 3이라 최신 보장이 안 돼 오래된 값을 읽을 수 있다. 좋아요 수처럼 오차 허용 데이터는 최종 일관성으로 가용성·성능을 택한다. 단일 최신본에 순차 접근하는 듯한 가장 강한 모델은 **선형성(linearizability)**이다."},{"h":"2PC","t":"2단계 커밋은 1단계 **prepare(준비)**에서 코디네이터가 모든 참여자에게 커밋 가능 여부를 묻고 각자 락을 잡은 뒤, 2단계에서 commit/abort를 지시한다. prepare 후 commit 지시 전에 코디네이터가 죽으면 참여자들이 락을 쥔 채 결정을 못 내리는 **블로킹**에 빠진다."}],"code":{"c":"-- 쿼럼 예: N=3\n-- W=2, R=2  ->  W + R = 4 > 3  (최신값 보장)\n-- W=1, R=1  ->  W + R = 2 <= 3 (보장 안 됨)","cap":"쿼럼 부등식 W+R>N으로 최신 읽기 판단"},"key":["파티션 시 CAP: C와 A 동시 불가","최신 읽기 조건 `W + R > N`","2PC prepare 후 코디네이터 사망=블로킹"]}}]},{"t":"데이터 모델링 - 정규화와 비정규화","l":[{"t":"정규화와 관계 모델링","q":[{"t":"choice","k":"1NF","cat":"design","q":"한 컬럼에 010-1111,010-2222 처럼 여러 전화번호를 콤마로 이어 저장했다. 어떤 정규형을 위반했고 어떻게 고치나?","o":["원자성 위반으로 1NF 위배; 값을 분해해 별도 행/테이블로 저장","부분 함수 종속으로 2NF 위배","이행 종속으로 3NF 위배","BCNF 위배"],"a":0,"ex":"하나의 셀에 다중 값을 넣으면 원자값 원칙이 깨져 1NF를 위반한다.\n💡 개념: 1NF는 각 컬럼이 더 쪼갤 수 없는 단일 값을 가질 것을 요구한다.\n🛠 실무: 전화번호를 별도 phone 테이블로 분리하면 검색/갱신/집계가 정확하고 쉬워진다."},{"t":"choice","k":"2NF","cat":"design","q":"주문상세 테이블의 PK가 (주문ID, 상품ID)인데 상품명이 상품ID에만 종속된다. 어떤 정규형 문제인가?","o":["복합키 일부에만 종속되는 부분 함수 종속으로 2NF 위배; 상품 정보를 별도 테이블로 분리","이행 종속으로 3NF 위배","원자성 위반으로 1NF 위배","위반 없음"],"a":0,"ex":"상품명이 복합 PK의 일부(상품ID)에만 종속되므로 부분 함수 종속이며 2NF를 위반한다.\n💡 개념: 2NF는 후보키 전체에 완전 함수 종속일 것을 요구한다.\n🛠 실무: 상품 속성을 product 테이블로 분리해 주문상세에는 상품ID만 남긴다."},{"t":"input","k":"이행종속","cat":"design","q":"직원 테이블에 부서ID와 함께 부서명이 저장되어, 키가 아닌 부서ID를 통해 부서명이 결정되는 이 종속을 무엇이라 하나?","a":["이행 함수 종속","이행 종속","transitive dependency","이행적 종속"],"ex":"기본키가 아닌 컬럼(부서ID)을 거쳐 다른 컬럼(부서명)이 결정되면 이행 종속이다.\n💡 개념: 3NF는 이행 함수 종속을 제거해 갱신 이상을 막는다.\n🛠 실무: 부서명을 department 테이블로 분리하면 부서명 변경이 한 곳에서만 일어난다."},{"t":"choice","k":"M:N모델링","cat":"design","q":"학생과 강의는 서로 여러 개를 가질 수 있는 다대다(M:N) 관계다. 관계형 DB에서 올바른 모델링은?","o":["수강신청 같은 연결(junction) 테이블을 두어 두 개의 1:N 관계로 분해","한 테이블에 배열 컬럼으로 강의 목록을 저장","두 테이블을 하나로 합침","양쪽 테이블에 외래키를 두어 직접 연결"],"a":0,"ex":"M:N은 중간에 연결 테이블을 두어 각각 1:N으로 풀어야 한다.\n💡 개념: 연결 테이블은 두 엔티티의 키를 참조하며 관계 고유 속성(수강일 등)도 담을 수 있다.\n🛠 실무: enrollment(student_id, course_id) 형태로 만들고 복합 유니크 제약으로 중복 수강을 막는다."},{"t":"choice","k":"정규화목적","cat":"design","q":"정규화를 통해 얻는 가장 핵심적인 이점은?","o":["데이터 중복을 제거해 삽입/갱신/삭제 이상(anomaly)을 방지","조회 성능을 항상 극대화","스토리지를 무제한으로 절약","모든 조인을 제거"],"a":0,"ex":"정규화의 본질은 중복 제거를 통한 데이터 정합성 확보다.\n💡 개념: 중복이 있으면 한 사실을 여러 곳에서 관리해 갱신 이상이 생긴다.\n🛠 실무: 정규화로 무결성을 확보하되, 조회 병목에는 선택적 비정규화로 균형을 잡는다."}],"th":{"sum":"**정규화**는 중복을 없애 이상현상을 막고, **비정규화**는 중복을 감수하고 조인을 줄여 읽기 성능을 높이는 반대 방향 설계다.","body":[{"h":"정규화와 관계","t":"한 칸에 여러 값을 콤마로 넣으면 원자값을 어긴 것이라 **1NF** 위반이다. PK 일부에만 종속되면 **2NF**(부분 종속) 문제, 키가 아닌 컬럼을 거쳐 종속되면 **3NF**(이행 종속) 문제다. 다대다(M:N) 관계는 중간에 연결(교차) 테이블을 두어 두 개의 1:N으로 푼다."},{"h":"비정규화 트레이드오프","t":"조인이 많아 느릴 때 카테고리명 같은 값을 미리 복제해 저장하면 읽기는 빨라진다. 대신 원본이 바뀔 때 여러 곳을 갱신해야 하고, 갱신을 놓치면 데이터 불일치가 생긴다. 즉 읽기 성능을 쓰기 복잡도와 중복으로 산 것이다."}],"code":{"c":"-- M:N 을 연결 테이블로 분해\nCREATE TABLE enrollment (\n  student_id INT,\n  course_id  INT,\n  PRIMARY KEY (student_id, course_id)\n);","cap":"학생-강의 다대다를 교차 테이블로 모델링"},"key":["콤마로 여러 값 저장 → 1NF 위반","부분 종속=2NF, 이행 종속=3NF 문제","비정규화의 대가는 중복 갱신과 불일치 위험"]}},{"t":"비정규화 트레이드오프","q":[{"t":"choice","k":"비정규화대가","cat":"design","q":"상품 목록 조회에서 매번 5개 테이블을 조인해 느리다. 카테고리명을 상품 테이블에 중복 저장(비정규화)하기로 했다. 감수하는 대가는?","o":["카테고리명 변경 시 중복된 여러 행을 함께 갱신해야 하는 갱신 이상 위험","조회가 오히려 더 느려짐","스토리지가 줄어듦","데이터 정합성이 자동으로 향상됨"],"a":0,"ex":"비정규화는 읽기를 빠르게 하는 대신 중복 데이터의 동기화 부담을 진다.\n💡 개념: 읽기 성능과 쓰기 정합성 사이의 트레이드오프다.\n🛠 실무: 변경 빈도가 낮은 값만 중복 저장하고, 원본 변경 시 배치/트리거로 파생 컬럼을 갱신한다."},{"t":"input","k":"비정규화","cat":"design","q":"조인 비용을 줄여 읽기 성능을 높이려고 일부러 중복 데이터를 허용하는, 정규화의 반대 방향 설계 기법을 무엇이라 하나?","a":["비정규화","denormalization","역정규화","반정규화"],"ex":"비정규화는 의도적으로 중복을 허용해 조인을 줄이고 읽기를 가속한다.\n💡 개념: 정규화로 무결성을 확보한 뒤 성능 병목에 한해 선택적으로 적용한다.\n🛠 실무: 읽기 대 쓰기 비율, 조인 비용, 정합성 요구를 근거로 도입 여부를 판단한다."},{"t":"choice","k":"집계컬럼","cat":"design","q":"게시글의 댓글 수를 매번 COUNT로 계산하니 느려서 comment_count 컬럼을 두어 미리 저장하기로 했다. 반드시 함께 설계할 것은?","o":["댓글 추가/삭제 시 카운터를 동기화하는 로직과 값 어긋남 보정 절차","인덱스 전면 제거","테이블 샤딩","복제 지연 허용 정책"],"a":0,"ex":"파생 집계 컬럼은 원본 변경과 동기화되지 않으면 실제 값과 어긋난다.\n💡 개념: 비정규화된 집계값은 정합성 유지 책임이 애플리케이션/트리거로 넘어온다.\n🛠 실무: 트랜잭션 내에서 함께 증감하고, 주기적 배치로 실제 COUNT와 대조해 보정한다."},{"t":"choice","k":"비정규화판단","cat":"design","q":"비정규화를 도입하기에 가장 적절한 판단 기준은?","o":["읽기가 쓰기보다 압도적으로 많고 조인이 명확한 병목일 때","쓰기가 많고 정합성이 최우선일 때","데이터가 매우 자주 바뀔 때","단순히 테이블 개수를 줄이고 싶을 때"],"a":0,"ex":"비정규화는 읽기 중심이고 조인이 병목일 때 이득이 크다.\n💡 개념: 쓰기가 잦으면 중복 동기화 비용이 커져 오히려 손해다.\n🛠 실무: 실제 쿼리 프로파일로 조인 병목을 확인한 뒤, 인덱스/캐시로 먼저 시도하고 그래도 부족하면 비정규화한다."},{"t":"choice","k":"CQRS","cat":"design","q":"원본은 정규화 상태로 유지하되, 조회 전용으로 비정규화된 읽기 모델을 따로 두어 명령과 조회를 분리하는 패턴은?","o":["CQRS(명령-조회 책임 분리)","2단계 커밋(2PC)","해시 샤딩","쿼럼 읽기"],"a":0,"ex":"CQRS는 쓰기 모델과 읽기 모델을 분리해 각각을 독립적으로 최적화한다.\n💡 개념: 정규화된 쓰기 모델의 무결성과 비정규화된 읽기 모델의 성능을 동시에 얻는다.\n🛠 실무: 이벤트/CDC로 읽기 모델을 갱신하며, 최종 일관성으로 인한 반영 지연을 감안해 설계한다."}],"th":{"sum":"**정규화**는 중복을 없애 이상현상을 막고, **비정규화**는 중복을 감수하고 조인을 줄여 읽기 성능을 높이는 반대 방향 설계다.","body":[{"h":"정규화와 관계","t":"한 칸에 여러 값을 콤마로 넣으면 원자값을 어긴 것이라 **1NF** 위반이다. PK 일부에만 종속되면 **2NF**(부분 종속) 문제, 키가 아닌 컬럼을 거쳐 종속되면 **3NF**(이행 종속) 문제다. 다대다(M:N) 관계는 중간에 연결(교차) 테이블을 두어 두 개의 1:N으로 푼다."},{"h":"비정규화 트레이드오프","t":"조인이 많아 느릴 때 카테고리명 같은 값을 미리 복제해 저장하면 읽기는 빨라진다. 대신 원본이 바뀔 때 여러 곳을 갱신해야 하고, 갱신을 놓치면 데이터 불일치가 생긴다. 즉 읽기 성능을 쓰기 복잡도와 중복으로 산 것이다."}],"code":{"c":"-- M:N 을 연결 테이블로 분해\nCREATE TABLE enrollment (\n  student_id INT,\n  course_id  INT,\n  PRIMARY KEY (student_id, course_id)\n);","cap":"학생-강의 다대다를 교차 테이블로 모델링"},"key":["콤마로 여러 값 저장 → 1NF 위반","부분 종속=2NF, 이행 종속=3NF 문제","비정규화의 대가는 중복 갱신과 불일치 위험"]}}]},{"t":"데이터 모델링 - 스키마 진화와 인덱스","l":[{"t":"스키마 진화와 무중단 마이그레이션","q":[{"t":"choice","k":"확장수축순서","cat":"design","q":"운영 중인 서비스에 NOT NULL 컬럼을 무중단으로 추가하려 한다. 확장-수축(expand-contract) 원칙에서 올바른 순서는?","o":["nullable로 컬럼 추가(expand) → 백필 → 앱이 신규 컬럼 사용 → 제약 강화/구조 정리(contract)","곧바로 NOT NULL 컬럼을 추가","구컬럼을 먼저 삭제한 뒤 신규 컬럼 추가","테이블 전체를 락 걸고 한 번에 alter"],"a":0,"ex":"먼저 호환 가능한 형태(nullable)로 추가·백필하고, 코드가 전환된 뒤에 제약을 강화한다.\n💡 개념: 구/신 코드가 공존하는 배포 구간에서도 스키마 호환을 유지하는 것이 핵심이다.\n🛠 실무: 기본값 없이 즉시 NOT NULL을 걸면 배포 중 구버전 INSERT가 실패하므로 단계적으로 진행한다."},{"t":"input","k":"확장수축","cat":"design","q":"무중단 스키마 변경에서 먼저 새 구조를 추가해 호환을 유지하고, 코드 전환 후 옛 구조를 제거하는 2단계 마이그레이션 패턴을 무엇이라 하나?","a":["확장-수축","expand-contract","expand and contract","확장 수축 패턴","parallel change"],"ex":"확장-수축(parallel change)은 추가 단계와 제거 단계를 분리해 항상 하위 호환을 유지한다.\n💡 개념: 배포와 스키마 변경을 여러 안전한 단계로 쪼갠다.\n🛠 실무: expand로 신구 공존을 만들고, 모든 인스턴스가 새 구조를 쓰는 것을 확인한 뒤 contract로 구조를 제거한다."},{"t":"choice","k":"rename함정","cat":"design","q":"운영 DB에서 컬럼명을 곧바로 RENAME 했더니 롤링 배포 중이던 구버전 앱 인스턴스가 에러를 냈다. 지켜야 할 무중단 원칙은?","o":["구/신 코드가 동시에 도는 배포 구간을 고려해 항상 하위 호환을 유지해야 함","배포를 한 번에 몰아서 전부 교체","DB를 잠시 내리고 변경","롤백 경로를 없애 강제 진행"],"a":0,"ex":"롤링 배포 중에는 구버전과 신버전이 같은 스키마를 동시에 바라본다.\n💡 개념: 파괴적 변경(rename/drop)은 호환을 깨므로 확장-수축으로 나눠야 한다.\n🛠 실무: 새 컬럼을 추가하고 양쪽에 이중 기록(dual write)한 뒤, 전환 완료 후 옛 컬럼을 제거한다."},{"t":"choice","k":"백필배치","cat":"design","q":"1억 행 테이블에 신규 컬럼 값을 백필하는데 UPDATE 한 방으로 실행하니 락과 복제 지연이 폭발했다. 개선책은?","o":["작은 배치로 나눠 커밋하며 복제 지연을 모니터링하고 속도를 조절","하나의 트랜잭션으로 더 크게 묶어 실행","모든 인덱스를 제거한 뒤 실행","동기 복제로 전환해 실행"],"a":0,"ex":"대량 UPDATE를 단일 트랜잭션으로 하면 긴 락과 거대한 복제 스트림이 발생한다.\n💡 개념: 백필은 청크 단위로 나눠 부하와 lag를 통제하는 것이 원칙이다.\n🛠 실무: PK 범위로 배치를 쪼개 커밋하고, 리플리카 lag가 임계를 넘으면 잠시 멈춰 따라잡게 한다."},{"t":"choice","k":"온라인DDL","cat":"design","q":"MySQL에서 대형 테이블 ALTER 시 테이블 락을 피하려고 shadow 테이블에 복사 후 스위칭하는 도구(gh-ost, pt-osc)가 해결하는 문제는?","o":["장시간 테이블 락으로 인한 쓰기 중단과 서비스 다운을 회피","복제 지연 자체를 제거","인덱스를 자동으로 최적 생성","샤딩을 자동화"],"a":0,"ex":"온라인 스키마 변경 도구는 원본을 잠그지 않고 그림자 테이블에 점진 복사 후 원자적으로 교체한다.\n💡 개념: 대형 DDL의 락 시간을 사실상 없애 무중단 변경을 가능케 한다.\n🛠 실무: 트리거/바이너리로그 기반으로 변경을 따라잡히며, 부하가 크므로 저트래픽 시간대에 실행한다."}],"th":{"sum":"무중단 스키마 변경은 **확장-수축(expand-contract)** 으로: 새 구조를 먼저 추가→코드 전환→옛 구조 제거. 백필은 배치로, 복합 인덱스는 **선택도 높은 등호 컬럼을 앞**에 둔다.","body":[{"h":"스키마 진화","t":"NOT NULL 컬럼은 곧바로 못 넣으니 nullable/기본값으로 추가→값 백필→제약 강화 순으로 간다. 컬럼을 바로 RENAME하면 롤링 배포 중 구버전 앱이 깨지므로, 새 컬럼 추가 후 양쪽 호환을 유지하다 정리한다(expand-contract). 1억 행 백필은 한 방 UPDATE 대신 청크로 나눠 락·복제 지연을 줄이고, 대형 ALTER는 gh-ost/pt-osc로 shadow 테이블에 복사 후 스위칭해 테이블 락을 피한다."},{"h":"인덱스 설계","t":"`WHERE user_id=? AND created_at>?`엔 등호로 좁히는 `user_id`를 앞, 범위 `created_at`을 뒤에 둔 복합 인덱스 `(user_id, created_at)`가 유리하다. 쿼리가 필요로 하는 모든 컬럼을 인덱스가 포함해 테이블 본체를 안 읽는 것을 **커버링 인덱스**라 한다."}],"code":{"c":"-- expand-contract\nALTER TABLE users ADD COLUMN email_v2 VARCHAR(255) NULL;\n-- backfill in batches, dual-write, switch reads...\nALTER TABLE users MODIFY email_v2 VARCHAR(255) NOT NULL;\n-- later: drop old column","cap":"무중단 컬럼 추가의 확장-수축 흐름"},"key":["expand-contract: 추가 → 전환 → 제거","대량 백필은 청크 배치, ALTER는 gh-ost/pt-osc","복합 인덱스는 등호(선택도 높음) 컬럼을 앞에"]}},{"t":"인덱스 설계","q":[{"t":"choice","k":"복합인덱스순서","cat":"design","q":"WHERE user_id = ? AND created_at &gt; ? 쿼리가 느리다. 복합 인덱스를 만들 때 컬럼 순서 원칙은?","o":["등치 비교 컬럼(user_id)을 앞, 범위 비교 컬럼(created_at)을 뒤에 둔다","범위 비교 컬럼을 앞에 둔다","카디널리티가 낮은 컬럼을 앞에 둔다","순서는 성능과 무관하다"],"a":0,"ex":"등치 조건을 앞에 두어야 인덱스가 좁혀진 뒤 범위 스캔이 이어진다.\n💡 개념: 복합 인덱스는 왼쪽 접두사 규칙을 따르며 범위 뒤 컬럼은 인덱스 정렬 이점을 못 받는다.\n🛠 실무: (user_id, created_at) 순으로 만들면 정렬/범위 조회까지 커버되어 효율적이다."},{"t":"input","k":"커버링인덱스","cat":"design","q":"쿼리가 필요로 하는 모든 컬럼이 인덱스에 포함되어 테이블 본체 접근 없이 인덱스만으로 결과를 반환하는 인덱스를 무엇이라 하나?","a":["커버링 인덱스","covering index","커버링","covering"],"ex":"커버링 인덱스는 필요한 컬럼을 모두 담아 테이블 룩업(랜덤 I/O)을 없앤다.\n💡 개념: 인덱스 온리 스캔으로 조회 비용을 크게 낮춘다.\n🛠 실무: 자주 조회하는 컬럼을 INCLUDE 하거나 복합 인덱스 뒤에 붙여 커버링을 구성하되, 인덱스 크기 증가를 감안한다."},{"t":"choice","k":"인덱스과다","cat":"design","q":"쓰기가 많은 테이블에 인덱스를 10개 걸었더니 INSERT가 눈에 띄게 느려졌다. 이유는?","o":["매 쓰기마다 모든 인덱스를 함께 갱신해야 해 쓰기 비용이 증가","인덱스가 조회를 느리게 만들어서","인덱스가 스토리지를 줄여서","복제가 멈춰서"],"a":0,"ex":"INSERT/UPDATE/DELETE 시 관련된 모든 인덱스가 유지·재정렬되어야 한다.\n💡 개념: 인덱스는 읽기를 돕는 대신 쓰기 비용과 저장 공간을 늘리는 트레이드오프다.\n🛠 실무: 실제 쿼리에 쓰이지 않는 인덱스를 제거하고, 쓰기 위주 테이블은 인덱스를 최소화한다."},{"t":"choice","k":"sargable","cat":"design","q":"인덱스가 있는 created_at 컬럼에 WHERE DATE(created_at) = '2026-07-22' 를 썼더니 풀스캔이 발생했다. 원인은?","o":["컬럼에 함수를 씌워 인덱스를 타지 못하는 sargable 위반; 범위 조건으로 재작성","인덱스 통계가 손상되어서","복합 인덱스 순서 문제라서","커넥션 풀이 부족해서"],"a":0,"ex":"인덱스 컬럼을 함수로 가공하면 인덱스 정렬을 활용할 수 없어 풀스캔이 된다.\n💡 개념: 검색 조건은 컬럼을 가공하지 않는 sargable 형태여야 인덱스를 탄다.\n🛠 실무: created_at &gt;= '2026-07-22' AND created_at &lt; '2026-07-23' 처럼 범위로 바꾸거나 표현식 인덱스를 만든다."},{"t":"choice","k":"저선택도","cat":"design","q":"성별(남/여)처럼 값 종류가 적은(카디널리티 낮은) 컬럼에 단독 B-tree 인덱스를 거는 것이 대체로 비효율인 이유는?","o":["선택도가 낮아 인덱스가 대부분의 행을 가리키므로 옵티마이저가 풀스캔을 택함","인덱스 파일이 지나치게 커져서","쓰기가 불가능해져서","정렬 순서가 깨져서"],"a":0,"ex":"값이 몇 종류뿐이면 조건 하나가 테이블의 큰 비율을 반환해 인덱스 이점이 사라진다.\n💡 개념: 인덱스는 선택도(고유한 값의 비율)가 높을수록 효과적이다.\n🛠 실무: 저카디널리티 컬럼은 다른 고선택도 컬럼과 묶은 복합 인덱스나 부분 인덱스로 활용한다."}],"th":{"sum":"무중단 스키마 변경은 **확장-수축(expand-contract)** 으로: 새 구조를 먼저 추가→코드 전환→옛 구조 제거. 백필은 배치로, 복합 인덱스는 **선택도 높은 등호 컬럼을 앞**에 둔다.","body":[{"h":"스키마 진화","t":"NOT NULL 컬럼은 곧바로 못 넣으니 nullable/기본값으로 추가→값 백필→제약 강화 순으로 간다. 컬럼을 바로 RENAME하면 롤링 배포 중 구버전 앱이 깨지므로, 새 컬럼 추가 후 양쪽 호환을 유지하다 정리한다(expand-contract). 1억 행 백필은 한 방 UPDATE 대신 청크로 나눠 락·복제 지연을 줄이고, 대형 ALTER는 gh-ost/pt-osc로 shadow 테이블에 복사 후 스위칭해 테이블 락을 피한다."},{"h":"인덱스 설계","t":"`WHERE user_id=? AND created_at>?`엔 등호로 좁히는 `user_id`를 앞, 범위 `created_at`을 뒤에 둔 복합 인덱스 `(user_id, created_at)`가 유리하다. 쿼리가 필요로 하는 모든 컬럼을 인덱스가 포함해 테이블 본체를 안 읽는 것을 **커버링 인덱스**라 한다."}],"code":{"c":"-- expand-contract\nALTER TABLE users ADD COLUMN email_v2 VARCHAR(255) NULL;\n-- backfill in batches, dual-write, switch reads...\nALTER TABLE users MODIFY email_v2 VARCHAR(255) NOT NULL;\n-- later: drop old column","cap":"무중단 컬럼 추가의 확장-수축 흐름"},"key":["expand-contract: 추가 → 전환 → 제거","대량 백필은 청크 배치, ALTER는 gh-ost/pt-osc","복합 인덱스는 등호(선택도 높음) 컬럼을 앞에"]}}]},{"t":"실행 계획과 인덱스 스캔","l":[{"t":"실행 계획 읽기 (EXPLAIN/ANALYZE)","q":[{"t":"choice","k":"seq-scan-line","cat":"perf","q":"주문 테이블(1000만 건)에서 status='PAID' 조건 쿼리의 EXPLAIN에 'Seq Scan on orders'가 보인다. 이 라인이 의미하는 것은?","code":"EXPLAIN SELECT * FROM orders WHERE status = 'PAID';","o":["인덱스를 이용해 일부 행만 읽는다","테이블 전체를 처음부터 끝까지 순차적으로 읽는다","정렬된 인덱스를 역순으로 스캔한다","실행 계획 캐시에서 결과를 가져온다"],"a":1,"ex":"Seq Scan은 테이블 전체를 순차적으로 훑는 풀 스캔이다.\n💡 개념: 옵티마이저가 조건에 맞는 인덱스가 없거나, 조회 대상 비율이 높아 인덱스보다 전체 스캔이 싸다고 판단하면 Seq Scan을 선택한다.\n🛠 실무: status가 선택도 높은 값이라면 인덱스 생성 후 Index Scan으로 바뀌는지 EXPLAIN으로 확인한다."},{"t":"choice","k":"explain-vs-analyze","cat":"perf","q":"쿼리 튜닝 중 '추정치'가 아니라 '실제로 걸린 시간과 실제 행 수'를 보고 싶다. 어떤 명령을 써야 하나?","o":["EXPLAIN","EXPLAIN ANALYZE","EXPLAIN (COSTS OFF)","DESCRIBE"],"a":1,"ex":"EXPLAIN ANALYZE는 쿼리를 실제 실행해 actual time과 actual rows를 보여준다.\n💡 개념: 그냥 EXPLAIN은 옵티마이저의 추정 계획만 출력하고 실행하지 않는다. ANALYZE는 실행하므로 INSERT/UPDATE에는 주의한다.\n🛠 실무: 추정 rows와 actual rows 차이를 비교해 통계 오류를 진단한다."},{"t":"input","k":"estimate-gap-cause","cat":"perf","q":"EXPLAIN ANALYZE에서 estimated rows=10 인데 actual rows=980000 처럼 추정과 실제가 크게 벌어졌다. 옵티마이저가 잘못 판단한 근본 원인을 한 단어로?","a":["통계","통계정보","통계 정보","statistics"],"ex":"오래되거나 부정확한 통계 정보 때문에 카디널리티 추정이 틀렸다.\n💡 개념: 옵티마이저는 컬럼 히스토그램/통계에 기반해 행 수를 추정하는데, 데이터가 크게 바뀌면 추정이 어긋난다.\n🛠 실무: ANALYZE(PostgreSQL) 또는 통계 갱신을 실행하고, 필요하면 통계 수집 대상 컬럼 수를 늘린다."},{"t":"choice","k":"cost-two-numbers","cat":"perf","q":"실행 계획의 'cost=0.42..8500.15'에서 두 숫자의 의미는?","o":["최소 메모리..최대 메모리","시작 비용(첫 행)..총 비용(마지막 행)","추정 행수..실제 행수","디스크 읽기..캐시 히트"],"a":1,"ex":"앞은 첫 행을 반환하기까지의 startup cost, 뒤는 전체를 반환하는 total cost다.\n💡 개념: 정렬/해시처럼 준비가 필요한 연산은 startup cost가 크다. LIMIT 쿼리는 startup cost가 중요하다.\n🛠 실무: 상위 노드의 total cost로 병목 연산을 찾아 위에서 아래로 내려가며 분석한다."},{"t":"choice","k":"rows-removed-filter","cat":"perf","q":"Index Scan 노드 아래에 'Rows Removed by Filter: 940000'이 크게 찍혔다. 이는 무엇을 시사하나?","o":["인덱스가 완벽하게 동작하고 있다","인덱스로 좁힌 뒤에도 대부분 행을 조건으로 버렸다 — 인덱스 설계 재검토 필요","조인 순서가 잘못됐다","통계가 최신이다"],"a":1,"ex":"인덱스로 접근한 행 대부분을 필터로 버렸다는 뜻으로, 인덱스 선택도가 낮다.\n💡 개념: 인덱스 컬럼이 조건을 충분히 좁히지 못하면 많은 행을 읽고 나서 버려 비효율적이다.\n🛠 실무: 필터 조건 컬럼을 인덱스에 포함하거나 복합 인덱스로 재설계한다."}],"th":{"sum":"`EXPLAIN`은 추정 계획, `EXPLAIN ANALYZE`는 **실제 시간·행 수**를 보여준다. 함수로 감싼 컬럼(`DATE(col)`)은 인덱스를 못 타므로 범위 조건으로 재작성한다.","body":[{"h":"실행 계획 읽기","t":"'Seq Scan on orders'는 인덱스 없이 테이블을 처음부터 끝까지 훑는다는 뜻이다. 추정이 아닌 실측이 필요하면 `EXPLAIN ANALYZE`를 쓴다. `cost=0.42..8500.15`는 첫 행 반환 비용과 전체 완료 비용이다. estimated와 actual rows가 크게 벌어지면 통계가 낡아 옵티마이저가 오판한 것이니 `ANALYZE`로 통계를 갱신한다."},{"h":"인덱스 스캔 vs 풀 스캔","t":"`Rows Removed by Filter`가 크면 인덱스로 좁혔지만 대부분을 버린 것이라 인덱스 선택도가 낮음을 시사한다. `WHERE DATE(created_at)='2026-07-22'`는 컬럼을 함수로 감싸 인덱스를 못 쓴다. `created_at >= '2026-07-22' AND created_at < '2026-07-23'` 같은 SARGable 범위로 바꾸면 인덱스를 탄다."}],"code":{"c":"-- 인덱스를 타도록 재작성\nSELECT * FROM orders\nWHERE created_at >= '2026-07-22'\n  AND created_at <  '2026-07-23';","cap":"함수 대신 범위 조건으로 인덱스 활용"},"key":["Seq Scan=풀 스캔, 실측은 `EXPLAIN ANALYZE`","추정≠실제 행 수 → 통계 갱신(ANALYZE)","컬럼을 함수로 감싸면 인덱스 불가 → 범위로 재작성"]}},{"t":"인덱스 스캔 vs 풀 스캔","q":[{"t":"choice","k":"func-wrapped-column","cat":"perf","q":"created_at에 인덱스가 있는데 아래 쿼리가 Seq Scan을 탄다. 이유는?","code":"SELECT * FROM orders WHERE DATE(created_at) = '2026-07-22';","o":["인덱스가 손상됐다","컬럼을 함수로 감싸 인덱스를 사용할 수 없다(non-SARGable)","날짜 타입이 인덱스를 지원하지 않는다","WHERE 절 위치가 잘못됐다"],"a":1,"ex":"DATE(created_at)처럼 컬럼을 함수로 감싸면 인덱스가 무력화된다.\n💡 개념: 인덱스는 원본 컬럼 값 순으로 정렬돼 있어, 가공된 값으로는 탐색할 수 없다(SARGable하지 않음).\n🛠 실무: 범위 조건으로 재작성한다 — created_at &gt;= '2026-07-22' AND created_at &lt; '2026-07-23'."},{"t":"input","k":"date-range-rewrite","cat":"perf","q":"위 DATE(created_at)='2026-07-22' 쿼리를 인덱스를 타도록 재작성할 때, created_at &gt;= '2026-07-22' AND created_at &lt; ? 의 ?에 들어갈 날짜는?","a":["2026-07-23","'2026-07-23'"],"ex":"다음 날 00:00 미만으로 반열린 구간을 잡는다.\n💡 개념: &gt;= 시작일 AND &lt; 다음날 로 하루를 표현하면 컬럼을 가공하지 않아 인덱스 범위 스캔이 가능하다.\n🛠 실무: BETWEEN '...00:00' AND '...23:59:59'는 경계/소수초 누락 위험이 있어 &lt; 다음날을 권장한다."},{"t":"choice","k":"leading-wildcard","cat":"perf","q":"email에 인덱스가 있지만 아래 쿼리는 풀 스캔이다. 인덱스를 못 타는 이유는?","code":"SELECT * FROM users WHERE email LIKE '%@gmail.com';","o":["LIKE는 인덱스를 절대 못 쓴다","패턴이 % 로 시작해 접두어를 특정할 수 없다","email 컬럼이 너무 길다","대소문자 때문이다"],"a":1,"ex":"앞쪽 와일드카드(%...)는 인덱스 접두어 탐색을 불가능하게 한다.\n💡 개념: B-tree 인덱스는 왼쪽부터의 접두어로 탐색한다. 'abc%'는 가능하지만 '%abc'는 불가능하다.\n🛠 실무: 도메인 검색이 잦으면 역순 저장 컬럼 인덱스나 별도 도메인 컬럼, 혹은 전문검색(GIN/trigram)을 고려한다."},{"t":"choice","k":"low-selectivity-seq","cat":"perf","q":"gender='M' (전체의 약 50%) 조건 쿼리에서 인덱스가 있는데도 옵티마이저가 Seq Scan을 골랐다. 가장 타당한 이유는?","o":["옵티마이저 버그","조회 대상 비율이 높아 랜덤 액세스보다 순차 읽기가 더 싸다","인덱스가 비활성 상태다","힌트가 없어서다"],"a":1,"ex":"선택도가 낮아(대상 행 비율이 큼) 인덱스 랜덤 I/O보다 순차 스캔이 유리하다.\n💡 개념: 인덱스 스캔은 매칭 행마다 테이블을 랜덤 액세스하므로, 대상이 많으면 오히려 느리다.\n🛠 실무: 선택도 높은 컬럼에 인덱스를 만들고, 저선택도 컬럼 단독 인덱스는 지양한다."},{"t":"input","k":"full-scan-term","cat":"perf","q":"인덱스를 사용하지 않고 테이블의 모든 블록을 처음부터 끝까지 읽는 접근 방식을 부르는 용어는? (PostgreSQL 기준 영문 표기)","a":["Seq Scan","Sequential Scan","seq scan","full scan","Full Table Scan"],"ex":"PostgreSQL에서는 Seq Scan(순차 스캔), 다른 DB에서는 Full Table Scan이라 부른다.\n💡 개념: 소량 조회엔 불리하지만, 대량/대부분 조회엔 순차 I/O 특성상 오히려 효율적일 수 있다.\n🛠 실무: 무조건 나쁜 게 아니라, 조회 비율과 데이터량을 함께 보고 판단한다."}],"th":{"sum":"`EXPLAIN`은 추정 계획, `EXPLAIN ANALYZE`는 **실제 시간·행 수**를 보여준다. 함수로 감싼 컬럼(`DATE(col)`)은 인덱스를 못 타므로 범위 조건으로 재작성한다.","body":[{"h":"실행 계획 읽기","t":"'Seq Scan on orders'는 인덱스 없이 테이블을 처음부터 끝까지 훑는다는 뜻이다. 추정이 아닌 실측이 필요하면 `EXPLAIN ANALYZE`를 쓴다. `cost=0.42..8500.15`는 첫 행 반환 비용과 전체 완료 비용이다. estimated와 actual rows가 크게 벌어지면 통계가 낡아 옵티마이저가 오판한 것이니 `ANALYZE`로 통계를 갱신한다."},{"h":"인덱스 스캔 vs 풀 스캔","t":"`Rows Removed by Filter`가 크면 인덱스로 좁혔지만 대부분을 버린 것이라 인덱스 선택도가 낮음을 시사한다. `WHERE DATE(created_at)='2026-07-22'`는 컬럼을 함수로 감싸 인덱스를 못 쓴다. `created_at >= '2026-07-22' AND created_at < '2026-07-23'` 같은 SARGable 범위로 바꾸면 인덱스를 탄다."}],"code":{"c":"-- 인덱스를 타도록 재작성\nSELECT * FROM orders\nWHERE created_at >= '2026-07-22'\n  AND created_at <  '2026-07-23';","cap":"함수 대신 범위 조건으로 인덱스 활용"},"key":["Seq Scan=풀 스캔, 실측은 `EXPLAIN ANALYZE`","추정≠실제 행 수 → 통계 갱신(ANALYZE)","컬럼을 함수로 감싸면 인덱스 불가 → 범위로 재작성"]}},{"t":"복합 인덱스와 커버링 인덱스","q":[{"t":"choice","k":"composite-eq-first","cat":"perf","q":"(a, b) 복합 인덱스가 있다. 다음 중 이 인덱스를 가장 효율적으로 활용하는 WHERE 조건은?","o":["WHERE b = 10","WHERE a &gt; 5 AND b = 10","WHERE a = 5 AND b = 10","WHERE b &gt; 10 (a는 조건에 없음)"],"a":2,"ex":"선두 컬럼 a를 등호로 고정하고 b도 등호면 인덱스를 완전히 활용한다.\n💡 개념: 복합 인덱스는 왼쪽 컬럼부터 사용된다. 선두 컬럼이 조건에 없으면(예: b만) 인덱스를 제대로 못 탄다.\n🛠 실무: 등호(=) 조건 컬럼을 앞에, 범위(&gt;, &lt;) 조건 컬럼을 뒤에 배치한다."},{"t":"choice","k":"range-then-eq-order","cat":"perf","q":"(status, created_at) 인덱스에서 'WHERE status='PAID' AND created_at &gt; '2026-01-01' ORDER BY created_at'는 효율적이지만, (created_at, status) 순서는 왜 비효율적일 수 있나?","o":["created_at 범위 조건 뒤의 status는 인덱스로 좁히기 어렵다","컬럼 순서는 성능과 무관하다","created_at이 문자열이라 안 된다","인덱스는 2개 컬럼을 못 담는다"],"a":0,"ex":"선두가 범위 컬럼이면 그 뒤 컬럼은 정렬이 흩어져 등호 탐색 효과가 떨어진다.\n💡 개념: 범위 조건 컬럼 이후의 인덱스 컬럼은 더 이상 정렬된 상태로 좁혀지지 않는다.\n🛠 실무: '등호 컬럼 → 범위/정렬 컬럼' 순으로 배치하는 것이 정석이다."},{"t":"choice","k":"covering-index-benefit","cat":"perf","q":"커버링 인덱스(covering index)를 사용했을 때 얻는 핵심 이점은?","o":["인덱스 크기가 줄어든다","테이블 원본 접근(랜덤 I/O) 없이 인덱스만으로 결과를 반환한다","락을 걸지 않는다","정렬을 항상 생략한다"],"a":1,"ex":"쿼리가 필요로 하는 컬럼이 모두 인덱스에 있어 테이블을 안 읽는다(Index Only Scan).\n💡 개념: SELECT/WHERE에 쓰이는 컬럼을 인덱스가 전부 포함하면 힙 접근이 사라져 빠르다.\n🛠 실무: PostgreSQL은 INCLUDE 컬럼, MySQL은 복합 인덱스로 자주 조회하는 컬럼을 커버링 설계한다."},{"t":"input","k":"include-keyword","cat":"perf","q":"PostgreSQL에서 인덱스에 SELECT용 컬럼을 함께 담아 커버링/Index Only Scan을 유도할 때 CREATE INDEX ... (a) 뒤에 붙이는 키워드는? (영문)","a":["INCLUDE","include"],"ex":"INCLUDE 절로 인덱스 리프에 비탐색용 컬럼을 저장한다.\n💡 개념: INCLUDE 컬럼은 정렬/탐색엔 안 쓰이지만 저장돼 있어 힙 접근을 없앤다.\n🛠 실무: CREATE INDEX idx ON t (status) INCLUDE (amount); 처럼 자주 함께 읽는 컬럼을 포함한다."},{"t":"choice","k":"leftmost-prefix-miss","cat":"perf","q":"(company_id, created_at) 인덱스만 있는 상태에서 'WHERE created_at &gt; '2026-01-01'' (company_id 조건 없음) 쿼리를 실행하면?","o":["인덱스를 완전 활용한다","선두 컬럼 company_id가 조건에 없어 효율적 탐색이 안 된다(대개 풀/전체 인덱스 스캔)","에러가 난다","자동으로 company_id=0으로 채운다"],"a":1,"ex":"복합 인덱스는 선두 컬럼이 조건에 없으면 효율적 탐색이 안 된다.\n💡 개념: 왼쪽 접두어 규칙(leftmost prefix) 때문에 두 번째 컬럼만으로는 시작점을 못 잡는다.\n🛠 실무: created_at 단독 검색이 잦으면 (created_at) 인덱스를 추가하거나 컬럼 순서를 재검토한다."}],"th":{"sum":"`EXPLAIN`은 추정 계획, `EXPLAIN ANALYZE`는 **실제 시간·행 수**를 보여준다. 함수로 감싼 컬럼(`DATE(col)`)은 인덱스를 못 타므로 범위 조건으로 재작성한다.","body":[{"h":"실행 계획 읽기","t":"'Seq Scan on orders'는 인덱스 없이 테이블을 처음부터 끝까지 훑는다는 뜻이다. 추정이 아닌 실측이 필요하면 `EXPLAIN ANALYZE`를 쓴다. `cost=0.42..8500.15`는 첫 행 반환 비용과 전체 완료 비용이다. estimated와 actual rows가 크게 벌어지면 통계가 낡아 옵티마이저가 오판한 것이니 `ANALYZE`로 통계를 갱신한다."},{"h":"인덱스 스캔 vs 풀 스캔","t":"`Rows Removed by Filter`가 크면 인덱스로 좁혔지만 대부분을 버린 것이라 인덱스 선택도가 낮음을 시사한다. `WHERE DATE(created_at)='2026-07-22'`는 컬럼을 함수로 감싸 인덱스를 못 쓴다. `created_at >= '2026-07-22' AND created_at < '2026-07-23'` 같은 SARGable 범위로 바꾸면 인덱스를 탄다."}],"code":{"c":"-- 인덱스를 타도록 재작성\nSELECT * FROM orders\nWHERE created_at >= '2026-07-22'\n  AND created_at <  '2026-07-23';","cap":"함수 대신 범위 조건으로 인덱스 활용"},"key":["Seq Scan=풀 스캔, 실측은 `EXPLAIN ANALYZE`","추정≠실제 행 수 → 통계 갱신(ANALYZE)","컬럼을 함수로 감싸면 인덱스 불가 → 범위로 재작성"]}}]},{"t":"조인 최적화와 쿼리 재작성","l":[{"t":"조인 알고리즘과 최적화","q":[{"t":"choice","k":"nested-loop-fit","cat":"perf","q":"작은 결과셋(수십 건)과 큰 테이블을 조인하는데 큰 테이블 조인 키에 인덱스가 있다. 옵티마이저가 고를 가장 효율적인 조인 방식은?","o":["Hash Join","Nested Loop Join","Merge Join","Cartesian Join"],"a":1,"ex":"바깥 소량 행마다 인덱스로 안쪽을 찌르는 Nested Loop가 유리하다.\n💡 개념: Nested Loop는 바깥 행 수가 적고 안쪽에 인덱스가 있을 때 최적이다. 바깥이 크면 반복 횟수가 폭증한다.\n🛠 실무: 소량 필터 후 조인 시 안쪽 조인 키 인덱스를 반드시 확보한다."},{"t":"choice","k":"hash-join-fit","cat":"perf","q":"인덱스가 없는 두 대형 테이블을 등호 조인해 대량 결과를 만든다. 일반적으로 가장 적합한 조인 알고리즘은?","o":["Nested Loop","Hash Join","Index Scan","Bitmap Scan"],"a":1,"ex":"한쪽으로 해시 테이블을 만들고 다른 쪽을 훑는 Hash Join이 대량 등호 조인에 강하다.\n💡 개념: Hash Join은 등치(equi) 조인 전용이며, 인덱스가 없어도 O(N+M)로 처리한다. 메모리(work_mem)가 관건이다.\n🛠 실무: 해시가 메모리를 넘겨 디스크로 넘치면 느려지므로 work_mem 조정이나 조인 대상 축소를 검토한다."},{"t":"choice","k":"merge-join-fit","cat":"perf","q":"두 테이블이 모두 조인 키로 이미 정렬되어 있을 때(또는 정렬 인덱스가 있을 때) 유리한 조인은?","o":["Hash Join","Nested Loop","Merge Join(Sort-Merge)","Loop Join"],"a":2,"ex":"정렬된 양쪽을 나란히 훑어 병합하는 Merge Join이 유리하다.\n💡 개념: 정렬이 이미 되어 있으면 정렬 비용 없이 순차 병합이 가능하고, 범위 조인에도 활용된다.\n🛠 실무: 큰 정렬 비용이 새로 든다면 Hash Join이 더 나을 수 있어 EXPLAIN으로 비교한다."},{"t":"input","k":"nested-loop-inner-need","cat":"perf","q":"Nested Loop Join 성능의 핵심은 안쪽(inner) 테이블의 조인 키에 무엇이 있어야 한다는 점이다. 무엇인가? (한 단어)","a":["인덱스","index","인덱스(index)"],"ex":"안쪽 조인 키에 인덱스가 있어야 반복 탐색이 빠르다.\n💡 개념: 인덱스가 없으면 바깥 행마다 안쪽을 풀 스캔해 O(N×M)로 폭발한다.\n🛠 실무: 조인 조건 컬럼(FK 등)에 인덱스가 있는지 먼저 확인한다."},{"t":"choice","k":"join-order-filter-early","cat":"perf","q":"3개 테이블 조인이 느리다. 튜닝의 일반 원칙으로 가장 적절한 것은?","o":["가장 큰 테이블부터 조인한다","선택도 높은 필터로 중간 결과셋을 최대한 일찍 줄인다","항상 알파벳 순으로 조인한다","무조건 서브쿼리로 감싼다"],"a":1,"ex":"일찍 행을 줄이면 이후 조인이 처리할 데이터가 급감한다.\n💡 개념: 중간 결과셋(intermediate result) 크기가 조인 비용을 좌우한다.\n🛠 실무: WHERE로 강하게 걸리는 테이블을 구동 테이블로 삼고, 필터 컬럼에 인덱스를 둔다."}],"th":{"sum":"옵티마이저는 데이터 크기·인덱스에 따라 **Nested Loop / Hash / Sort-Merge** 조인을 고른다. 인덱스를 못 쓰게 만드는 조건은 non-SARGable이며, N+1은 조인/IN으로 재작성한다.","body":[{"h":"조인 알고리즘","t":"작은 결과셋 + 큰 테이블(조인 키에 인덱스)이면 **Nested Loop**가 최적이다(안쪽 테이블 조인 키의 인덱스가 핵심). 인덱스 없는 두 대형 테이블의 등호 조인 대량 결과엔 **Hash Join**, 양쪽이 이미 조인 키로 정렬돼 있으면 **Sort-Merge**가 유리하다. 3-테이블 조인은 중간 결과가 작아지도록 선택도 높은 조건부터 좁히는 게 원칙이다. 대량 배치 적재 후 통계가 낡으면 옵티마이저가 잘못 Nested Loop를 골라 느려지니 `ANALYZE`로 통계를 갱신한다."},{"h":"SARGable과 재작성","t":"SARGable은 인덱스를 활용할 수 있는 검색 조건(컬럼을 가공하지 않고 `컬럼 연산자 값` 형태)을 뜻한다. `WHERE YEAR(d)=2024`는 non-SARGable, 범위 조건은 SARGable이다. 반복 단건 조회(N+1)는 `IN (...)`이나 조인 한 방으로 묶어 라운드트립을 줄인다."}],"code":{"c":"-- N+1 을 IN 한 방으로\nSELECT * FROM order_items\nWHERE order_id IN (101, 102, 103, 104);","cap":"반복 조회를 IN으로 묶어 N+1 제거"},"key":["작은 셋+인덱스=Nested Loop, 대형 등호 대량=Hash, 정렬됨=Sort-Merge","Nested Loop 핵심은 inner 조인 키의 인덱스","SARGable=컬럼 미가공 조건; N+1은 IN/조인으로"]}},{"t":"카디널리티와 SARGable 조건","q":[{"t":"choice","k":"stale-stats-badplan","cat":"perf","q":"대량 배치 적재 직후 조인 쿼리가 갑자기 Nested Loop를 골라 수십 배 느려졌다. 가장 가능성 높은 원인과 조치는?","o":["인덱스 삭제됨 — 재생성","통계가 낡아 카디널리티를 과소추정 — 통계 갱신(ANALYZE)","네트워크 지연 — 재시도","락 경합 — 트랜잭션 축소"],"a":1,"ex":"적재로 데이터 분포가 바뀌었는데 통계가 낡아 행 수를 과소추정한 것이다.\n💡 개념: 과소추정하면 옵티마이저가 Nested Loop를 골라 실제로는 엄청난 반복이 발생한다.\n🛠 실무: 대량 DML 후 ANALYZE로 통계를 갱신하고, 자동 통계 임계치도 점검한다."},{"t":"choice","k":"sargable-def","cat":"perf","q":"'SARGable(Search ARGument able)' 조건이란?","o":["항상 서브쿼리를 쓰는 조건","인덱스를 활용해 탐색 범위를 좁힐 수 있는 형태의 조건","반드시 풀 스캔하는 조건","집계 함수가 포함된 조건"],"a":1,"ex":"SARGable은 인덱스로 범위를 좁힐 수 있게 작성된 조건을 뜻한다.\n💡 개념: 컬럼을 가공하지 않고 'column 연산자 값' 형태여야 SARGable하다. 함수 감싸기/연산은 이를 깨뜨린다.\n🛠 실무: WHERE price * 1.1 &gt; 100 대신 WHERE price &gt; 100 / 1.1 처럼 컬럼을 좌변에 홀로 둔다."},{"t":"choice","k":"column-arith-rewrite","cat":"perf","q":"salary 인덱스가 있는데 아래 쿼리가 인덱스를 못 탄다. SARGable하게 고친 것은?","code":"SELECT * FROM emp WHERE salary + 100 &gt; 5000;","o":["WHERE salary + 100 &gt;= 5000","WHERE salary &gt; 4900","WHERE ABS(salary) &gt; 4900","고칠 수 없다"],"a":1,"ex":"컬럼에 붙은 연산을 상수 쪽으로 옮겨 컬럼을 홀로 둔다.\n💡 개념: salary + 100 은 계산된 값이라 인덱스를 못 쓴다. salary &gt; 4900 으로 이항하면 SARGable해진다.\n🛠 실무: 조건식에서 컬럼은 항상 가공 없이 한쪽에 단독으로 두는 습관을 들인다."},{"t":"input","k":"cardinality-term","cat":"perf","q":"옵티마이저가 조인/스캔 비용을 추정할 때 사용하는, '조건을 만족하는 예상 행 수(고유 값 분포 포함)'를 가리키는 용어는? (외래어 한 단어)","a":["카디널리티","cardinality","Cardinality"],"ex":"카디널리티는 컬럼/조건의 예상 행 수 및 고유값 분포를 의미한다.\n💡 개념: 카디널리티 추정이 틀리면 조인 방식/순서 선택이 어긋나 성능이 급락한다.\n🛠 실무: 상관관계 있는 컬럼은 다변량 통계(예: CREATE STATISTICS)로 추정 정확도를 높인다."},{"t":"choice","k":"implicit-cast","cat":"perf","q":"phone 컬럼이 VARCHAR이고 인덱스가 있는데 'WHERE phone = 01012345678' (숫자 리터럴)이 풀 스캔한다. 이유는?","o":["숫자가 너무 커서","문자열 컬럼과 숫자 비교로 암묵적 형변환이 일어나 인덱스가 무력화됨","인덱스가 잠겨서","phone은 인덱스 대상이 아님"],"a":1,"ex":"타입 불일치로 컬럼 측 암묵적 형변환이 발생해 인덱스를 못 쓴다.\n💡 개념: 컬럼에 CAST가 씌워지는 셈이라 함수로 감싼 것과 같아진다.\n🛠 실무: WHERE phone = '01012345678' 처럼 리터럴 타입을 컬럼과 일치시킨다."}],"th":{"sum":"옵티마이저는 데이터 크기·인덱스에 따라 **Nested Loop / Hash / Sort-Merge** 조인을 고른다. 인덱스를 못 쓰게 만드는 조건은 non-SARGable이며, N+1은 조인/IN으로 재작성한다.","body":[{"h":"조인 알고리즘","t":"작은 결과셋 + 큰 테이블(조인 키에 인덱스)이면 **Nested Loop**가 최적이다(안쪽 테이블 조인 키의 인덱스가 핵심). 인덱스 없는 두 대형 테이블의 등호 조인 대량 결과엔 **Hash Join**, 양쪽이 이미 조인 키로 정렬돼 있으면 **Sort-Merge**가 유리하다. 3-테이블 조인은 중간 결과가 작아지도록 선택도 높은 조건부터 좁히는 게 원칙이다. 대량 배치 적재 후 통계가 낡으면 옵티마이저가 잘못 Nested Loop를 골라 느려지니 `ANALYZE`로 통계를 갱신한다."},{"h":"SARGable과 재작성","t":"SARGable은 인덱스를 활용할 수 있는 검색 조건(컬럼을 가공하지 않고 `컬럼 연산자 값` 형태)을 뜻한다. `WHERE YEAR(d)=2024`는 non-SARGable, 범위 조건은 SARGable이다. 반복 단건 조회(N+1)는 `IN (...)`이나 조인 한 방으로 묶어 라운드트립을 줄인다."}],"code":{"c":"-- N+1 을 IN 한 방으로\nSELECT * FROM order_items\nWHERE order_id IN (101, 102, 103, 104);","cap":"반복 조회를 IN으로 묶어 N+1 제거"},"key":["작은 셋+인덱스=Nested Loop, 대형 등호 대량=Hash, 정렬됨=Sort-Merge","Nested Loop 핵심은 inner 조인 키의 인덱스","SARGable=컬럼 미가공 조건; N+1은 IN/조인으로"]}},{"t":"쿼리 재작성 (N+1, OR/IN)","q":[{"t":"choice","k":"n-plus-one-def","cat":"perf","q":"게시글 목록 100건을 조회한 뒤, 각 글의 작성자를 위해 쿼리를 100번 더 날린다. 이 안티패턴의 이름은?","o":["카티션 곱","N+1 문제","팬텀 리드","인덱스 스큐"],"a":1,"ex":"목록 1번 + 각 행마다 1번씩, 총 N+1번 쿼리가 나가는 N+1 문제다.\n💡 개념: ORM 지연 로딩에서 흔하며, 쿼리 수 폭증으로 왕복 비용이 커진다.\n🛠 실무: JOIN 또는 IN(...)으로 한 번에 로딩하거나 ORM의 eager/batch 로딩을 사용한다."},{"t":"choice","k":"n-plus-one-fix","cat":"perf","q":"위 N+1 문제를 해결하는 가장 일반적인 방법은?","o":["글을 하나씩 순회하며 매번 커밋","작성자들을 WHERE author_id IN (...) 로 한 번에 조회하거나 JOIN으로 합침","인덱스를 제거","트랜잭션 격리 수준을 올림"],"a":1,"ex":"여러 개별 쿼리를 IN 한 방 또는 JOIN으로 합쳐 왕복을 줄인다.\n💡 개념: 쿼리 왕복(round-trip) 수를 줄이는 것이 핵심이다. 100번을 1~2번으로 줄인다.\n🛠 실무: ORM이면 batch size 설정이나 join fetch, GraphQL이면 DataLoader로 배치한다."},{"t":"choice","k":"or-to-union","cat":"perf","q":"두 컬럼 각각에 인덱스가 있으나 'WHERE a = 1 OR b = 2' 가 인덱스를 잘 못 탈 때, 재작성 전략으로 적절한 것은?","code":"SELECT * FROM t WHERE a = 1 OR b = 2;","o":["항상 그냥 둔다","각 조건을 SELECT ... WHERE a=1 UNION SELECT ... WHERE b=2 로 분리","OR를 AND로 바꾼다","서브쿼리로 감싼다"],"a":1,"ex":"OR를 UNION으로 쪼개면 각 브랜치가 자기 인덱스를 탈 수 있다.\n💡 개념: 서로 다른 컬럼에 걸린 OR는 단일 인덱스로 동시에 좁히기 어렵다. UNION은 각 인덱스 스캔 후 병합한다.\n🛠 실무: 중복 제거가 필요 없으면 UNION ALL이 더 빠르다. PostgreSQL은 BitmapOr로 자동 최적화하기도 한다."},{"t":"input","k":"in-to-exists","cat":"perf","q":"'WHERE id IN (SELECT ...)' 서브쿼리가 느릴 때, 존재 여부만 확인하도록 재작성하는 데 쓰는 키워드는? (영문)","a":["EXISTS","exists"],"ex":"대량/상관 조건은 IN 대신 EXISTS 또는 JOIN으로 재작성하면 빠른 경우가 많다.\n💡 개념: EXISTS는 매칭 하나만 찾으면 즉시 참을 반환해 조기 종료(short-circuit)가 가능하다.\n🛠 실무: NULL 가능 컬럼엔 NOT IN이 위험(NULL로 전체 거짓)하니 NOT EXISTS를 선호한다."},{"t":"choice","k":"select-star-covering","cat":"perf","q":"리스트 API에서 SELECT * 로 전체 컬럼을 가져오다 커버링 인덱스가 깨져 느려졌다. 가장 적절한 개선은?","o":["항상 SELECT * 유지","실제 필요한 컬럼만 명시해 Index Only Scan/전송량 감소를 노린다","LIMIT을 제거","모든 컬럼에 인덱스를 건다"],"a":1,"ex":"필요한 컬럼만 SELECT하면 커버링 인덱스 활용과 I/O·네트워크 절감이 가능하다.\n💡 개념: SELECT * 는 인덱스에 없는 컬럼까지 요구해 힙 접근을 유발하고 커버링을 깨뜨린다.\n🛠 실무: 목록 화면은 표시 컬럼만 조회하고, 그 컬럼을 커버링 인덱스로 설계한다."}],"th":{"sum":"옵티마이저는 데이터 크기·인덱스에 따라 **Nested Loop / Hash / Sort-Merge** 조인을 고른다. 인덱스를 못 쓰게 만드는 조건은 non-SARGable이며, N+1은 조인/IN으로 재작성한다.","body":[{"h":"조인 알고리즘","t":"작은 결과셋 + 큰 테이블(조인 키에 인덱스)이면 **Nested Loop**가 최적이다(안쪽 테이블 조인 키의 인덱스가 핵심). 인덱스 없는 두 대형 테이블의 등호 조인 대량 결과엔 **Hash Join**, 양쪽이 이미 조인 키로 정렬돼 있으면 **Sort-Merge**가 유리하다. 3-테이블 조인은 중간 결과가 작아지도록 선택도 높은 조건부터 좁히는 게 원칙이다. 대량 배치 적재 후 통계가 낡으면 옵티마이저가 잘못 Nested Loop를 골라 느려지니 `ANALYZE`로 통계를 갱신한다."},{"h":"SARGable과 재작성","t":"SARGable은 인덱스를 활용할 수 있는 검색 조건(컬럼을 가공하지 않고 `컬럼 연산자 값` 형태)을 뜻한다. `WHERE YEAR(d)=2024`는 non-SARGable, 범위 조건은 SARGable이다. 반복 단건 조회(N+1)는 `IN (...)`이나 조인 한 방으로 묶어 라운드트립을 줄인다."}],"code":{"c":"-- N+1 을 IN 한 방으로\nSELECT * FROM order_items\nWHERE order_id IN (101, 102, 103, 104);","cap":"반복 조회를 IN으로 묶어 N+1 제거"},"key":["작은 셋+인덱스=Nested Loop, 대형 등호 대량=Hash, 정렬됨=Sort-Merge","Nested Loop 핵심은 inner 조인 키의 인덱스","SARGable=컬럼 미가공 조건; N+1은 IN/조인으로"]}}]},{"t":"스토리지 엔진과 로깅 내부","l":[{"t":"스토리지 엔진: 힙, B-tree, LSM-tree","q":[{"t":"choice","k":"clustered-index","cat":"internals","q":"InnoDB 테이블에서 기본키로 범위 조회(BETWEEN)를 자주 하는데, 같은 데이터를 힙 기반 엔진보다 InnoDB가 순차 스캔에 유리한 근본 이유는?","o":["InnoDB는 기본키 순서로 데이터 행 자체를 리프에 정렬 저장하는 클러스터드 인덱스라서 물리적으로 인접함","InnoDB는 모든 조회를 메모리에서만 처리해서 디스크를 읽지 않음","힙 테이블은 인덱스를 만들 수 없어서 항상 느림","InnoDB는 범위 조회 시 자동으로 테이블을 복제해 병렬 스캔함"],"a":0,"ex":"InnoDB의 기본키는 클러스터드 인덱스라 행 데이터가 키 순서로 리프 페이지에 정렬 저장된다.\n💡 개념: 클러스터드 인덱스는 리프에 행 전체를 담고 물리 순서를 키 순서로 유지한다. 힙은 삽입 순서로 흩어져 저장되고 별도 인덱스가 튜플 위치(ctid/rowid)를 가리킨다.\n🛠 실무: 범위·정렬 조회가 잦은 컬럼을 기본키/클러스터 키로 두면 랜덤 I/O가 순차 I/O로 바뀌어 유리하다."},{"t":"choice","k":"secondary-index-lookup","cat":"internals","q":"InnoDB에서 보조 인덱스로 조회할 때 기본키를 함께 저장하는 이유와, 그로 인해 발생하는 추가 비용은?","o":["보조 인덱스 리프는 기본키 값을 저장하고, 실제 행을 얻으려면 클러스터드 인덱스를 다시 타는 2차 탐색이 필요하다","보조 인덱스는 행의 물리 주소를 저장하므로 추가 탐색이 전혀 없다","기본키를 저장하지 않으며 조회 시 전체 테이블을 스캔한다","보조 인덱스는 항상 커버링이라 클러스터드 인덱스를 볼 필요가 없다"],"a":0,"ex":"보조 인덱스 리프는 기본키를 담고, 행을 얻으려면 클러스터드 인덱스로 되돌아가는 북마크 룩업이 발생한다.\n💡 개념: 힙 엔진은 보조 인덱스가 rowid(물리 위치)를 직접 가리키지만, 클러스터드 방식은 논리 키(기본키)를 저장해 한 번 더 탐색한다.\n🛠 실무: 조회에 필요한 컬럼을 인덱스에 포함(커버링 인덱스)하면 2차 탐색을 없애 성능을 끌어올린다."},{"t":"choice","k":"lsm-vs-btree","cat":"internals","q":"쓰기 폭주(대량 INSERT) 워크로드에서 B-tree보다 LSM-tree(RocksDB, Cassandra 등)가 유리한 이유로 가장 정확한 것은?","o":["쓰기를 메모리(memtable)에 모아 순차적으로 SSTable로 플러시하므로 랜덤 쓰기를 순차 쓰기로 바꾼다","LSM-tree는 디스크에 데이터를 전혀 쓰지 않기 때문에 빠르다","LSM-tree는 읽기와 쓰기 모두 항상 B-tree보다 빠르다","LSM-tree는 인덱스가 없어서 쓰기 시 정렬 비용이 들지 않는다"],"a":0,"ex":"LSM은 memtable에 쓰기를 모았다가 정렬된 SSTable로 순차 플러시해 랜덤 쓰기를 회피한다.\n💡 개념: B-tree는 갱신을 제자리(in-place)로 해 랜덤 I/O와 쓰기 증폭이 크고, LSM은 append 후 백그라운드 컴팩션으로 병합한다.\n🛠 실무: 쓰기 집약(로그·시계열·IoT)에는 LSM이, 읽기·범위 스캔 위주에는 B-tree가 대체로 적합하다."},{"t":"choice","k":"read-amplification","cat":"internals","q":"LSM-tree 기반 저장소에서 특정 키를 단건 조회하는데 컴팩션이 밀려 여러 SSTable을 뒤져야 할 때 발생하는 현상은?","o":["읽기 증폭(read amplification): 하나의 논리 조회가 여러 레벨의 SSTable을 확인해야 한다","쓰기 증폭이 사라져 읽기가 항상 빨라진다","데드락이 발생해 조회가 무한 대기한다","버퍼 풀이 자동으로 두 배로 커진다"],"a":0,"ex":"키가 여러 레벨에 흩어져 있으면 조회 하나가 다수 SSTable을 확인해 읽기 증폭이 커진다.\n💡 개념: 블룸 필터로 존재하지 않는 SSTable 접근을 걸러 읽기 증폭을 줄이고, 컴팩션이 레벨을 병합해 파일 수를 낮춘다.\n🛠 실무: 조회 지연이 튀면 컴팩션 지연·블룸 필터 적중률·레벨 파일 수를 먼저 점검한다."},{"t":"input","k":"btree-fanout","cat":"internals","q":"B-tree에서 한 노드(페이지)가 자식을 많이 가져 트리 높이를 낮게 유지하는 성질을 무엇이라 하는가? (한 단어)","a":["팬아웃","fan-out","fanout","fan out"],"ex":"팬아웃(fan-out)이 클수록 트리 높이가 낮아져 조회에 필요한 페이지 읽기 수가 준다.\n💡 개념: 높은 팬아웃 덕에 수억 행도 3~4 레벨이면 리프에 도달해 디스크 I/O 횟수가 로그 스케일로 유지된다.\n🛠 실무: 인덱스 키를 짧게(예: UUID보다 정수) 유지하면 한 페이지에 키가 더 들어가 팬아웃이 커지고 인덱스가 작아진다."}],"th":{"sum":"InnoDB는 **클러스터형 인덱스**라 PK 순으로 물리 정렬돼 범위 스캔에 유리하다. B-tree는 낮은 트리 높이(**fan-out**), LSM-tree는 쓰기 폭주에 강하다. 변경은 **WAL**에 먼저 기록한다.","body":[{"h":"스토리지 엔진","t":"InnoDB는 데이터가 PK B-tree 리프에 정렬 저장(클러스터형)돼 PK 범위 조회가 순차적이라 힙보다 빠르다. 보조 인덱스는 PK를 함께 저장해 실제 행을 찾는데(2차 조회 비용), PK가 크면 인덱스도 커진다. LSM-tree는 쓰기를 메모리+순차 append로 처리해 대량 INSERT에 유리하지만, 컴팩션이 밀리면 여러 SSTable을 뒤져 **읽기 증폭**이 생긴다. 한 페이지가 자식을 많이 갖는 성질이 fan-out이다."},{"h":"버퍼 풀과 WAL","t":"버퍼 풀은 자주 쓰는 페이지를 메모리에 캐시한다. 히트율이 99%→80%로 떨어지면 작업셋이 버퍼 풀보다 커져 디스크 I/O가 급증한 것이다. 더티 페이지를 즉시 안 쓰고 모아 쓰는 이유는 랜덤 쓰기를 줄여 처리량을 높이기 위함이며, 지속성은 **WAL(로그 선기록)**이 보장한다. 체크포인트는 더티 페이지를 주기적으로 디스크에 반영해 복구 범위를 줄인다."}],"code":{"c":"-- InnoDB: PK 순 물리 정렬 → 범위 스캔 순차적\nSELECT * FROM orders\nWHERE id BETWEEN 1000 AND 2000;","cap":"클러스터형 PK 덕에 범위 조회가 순차 스캔"},"key":["InnoDB=클러스터형(PK 정렬), 보조 인덱스는 PK 저장","LSM=쓰기 강함, 컴팩션 지연 시 읽기 증폭","변경은 WAL 선기록, 더티 페이지는 지연 후 일괄 쓰기"]}},{"t":"버퍼 풀과 페이지 캐시","q":[{"t":"choice","k":"buffer-pool-hit","cat":"internals","q":"운영 중 갑자기 디스크 I/O가 급증하고 쿼리가 느려졌다. 버퍼 풀 히트율이 99%에서 80%로 떨어진 것이 원인일 때 가장 그럴듯한 설명은?","o":["작업 세트가 버퍼 풀 크기를 초과해 필요한 페이지가 자주 캐시에서 밀려나 디스크에서 다시 읽힌다","버퍼 풀 히트율이 낮을수록 디스크 I/O는 줄어든다","버퍼 풀은 쓰기 전용이라 조회 성능과 무관하다","히트율 하락은 항상 인덱스가 삭제되었다는 의미다"],"a":0,"ex":"작업 세트가 버퍼 풀보다 커지면 페이지가 자주 축출되고 재요청되어 물리 읽기가 폭증한다.\n💡 개념: 버퍼 풀은 디스크 페이지를 메모리에 캐시하며 대개 LRU 계열로 관리한다. 히트율 하락은 캐시 미스 증가를 뜻한다.\n🛠 실무: 히트율이 떨어지면 버퍼 풀 크기 증설, 인덱스로 스캔 범위 축소, 대형 배치의 캐시 오염(스캔이 핫 페이지를 밀어냄) 여부를 확인한다."},{"t":"choice","k":"dirty-page-flush","cat":"internals","q":"버퍼 풀에서 변경된 페이지(더티 페이지)를 디스크로 즉시 쓰지 않고 지연 후 모아서 쓰는 이유는?","o":["랜덤 쓰기를 모아 순차화하고 반복 갱신을 합쳐 디스크 쓰기 횟수를 줄이기 위해서","더티 페이지는 절대 디스크에 쓰지 않고 메모리에만 남기려고","즉시 쓰면 데이터가 손상되기 때문에","WAL이 없으면 페이지를 아예 쓸 수 없어서"],"a":0,"ex":"더티 페이지를 모아 지연 플러시하면 반복 갱신이 병합되고 쓰기가 순차화되어 I/O가 줄어든다.\n💡 개념: 커밋 시점엔 WAL만 강제로 기록(내구성 확보)하고, 실제 데이터 페이지는 나중에 백그라운드로 플러시한다.\n🛠 실무: 더티 페이지가 과도하게 쌓이면 체크포인트/플러시가 몰려 지연 스파이크가 생기므로 플러시 속도 파라미터를 조율한다."},{"t":"choice","k":"os-page-cache","cat":"internals","q":"PostgreSQL은 자체 shared_buffers 외에 OS 페이지 캐시에도 의존한다. shared_buffers를 물리 메모리의 대부분으로 잡는 것이 오히려 비효율일 수 있는 이유는?","o":["같은 데이터가 shared_buffers와 OS 페이지 캐시에 이중 캐싱되어 유효 메모리가 낭비될 수 있다","shared_buffers는 클수록 항상 빠르므로 비효율은 없다","OS 페이지 캐시는 PostgreSQL이 사용할 수 없다","shared_buffers를 키우면 WAL이 비활성화된다"],"a":0,"ex":"Postgres는 OS 페이지 캐시도 활용하므로 shared_buffers를 과도하게 키우면 이중 캐싱으로 메모리가 낭비될 수 있다.\n💡 개념: MySQL InnoDB는 O_DIRECT 등으로 OS 캐시를 우회해 버퍼 풀을 크게 잡지만, Postgres는 OS 캐시와 협력하는 설계다.\n🛠 실무: Postgres shared_buffers는 흔히 RAM의 25% 안팎에서 시작해 워크로드로 튜닝한다."},{"t":"choice","k":"prefetch","cat":"internals","q":"대량 순차 스캔에서 DB가 곧 필요할 페이지를 미리 버퍼 풀로 읽어오는 기법과 그 목적은?","o":["선행 읽기(read-ahead/prefetch): I/O 대기를 계산과 겹쳐 처리량을 높인다","지연 쓰기: 읽기를 미뤄 CPU를 아낀다","락 에스컬레이션: 페이지 락을 테이블 락으로 승격한다","체크포인트: 더티 페이지를 즉시 디스크에 반영한다"],"a":0,"ex":"선행 읽기는 접근 패턴을 예측해 페이지를 미리 적재, I/O 지연을 연산과 겹쳐 숨긴다.\n💡 개념: 순차·범위 스캔에서 특히 효과가 크며, 랜덤 접근에서는 예측이 빗나가 오히려 캐시를 오염시킬 수 있다.\n🛠 실무: 배치 리포트 쿼리 튜닝 시 선행 읽기 관련 설정과 스캔이 핫 데이터를 밀어내는 캐시 오염을 함께 살핀다."},{"t":"input","k":"eviction-policy","cat":"internals","q":"버퍼 풀이 가득 찼을 때 가장 오래 참조되지 않은 페이지를 우선 축출하는 대표적 캐시 교체 정책의 약자는? (영문 약자)","a":["LRU","Least Recently Used","least recently used"],"ex":"LRU(Least Recently Used)는 가장 오래 안 쓰인 페이지를 먼저 축출한다.\n💡 개념: 실제 엔진은 순차 스캔이 핫 페이지를 밀어내는 것을 막으려 LRU를 변형한다(InnoDB의 young/old 리스트, Postgres의 clock-sweep).\n🛠 실무: 대형 스캔이 캐시를 오염시키면 히트율이 급락하므로 midpoint insertion 같은 변형 정책의 동작을 이해해 두면 진단에 도움된다."}],"th":{"sum":"InnoDB는 **클러스터형 인덱스**라 PK 순으로 물리 정렬돼 범위 스캔에 유리하다. B-tree는 낮은 트리 높이(**fan-out**), LSM-tree는 쓰기 폭주에 강하다. 변경은 **WAL**에 먼저 기록한다.","body":[{"h":"스토리지 엔진","t":"InnoDB는 데이터가 PK B-tree 리프에 정렬 저장(클러스터형)돼 PK 범위 조회가 순차적이라 힙보다 빠르다. 보조 인덱스는 PK를 함께 저장해 실제 행을 찾는데(2차 조회 비용), PK가 크면 인덱스도 커진다. LSM-tree는 쓰기를 메모리+순차 append로 처리해 대량 INSERT에 유리하지만, 컴팩션이 밀리면 여러 SSTable을 뒤져 **읽기 증폭**이 생긴다. 한 페이지가 자식을 많이 갖는 성질이 fan-out이다."},{"h":"버퍼 풀과 WAL","t":"버퍼 풀은 자주 쓰는 페이지를 메모리에 캐시한다. 히트율이 99%→80%로 떨어지면 작업셋이 버퍼 풀보다 커져 디스크 I/O가 급증한 것이다. 더티 페이지를 즉시 안 쓰고 모아 쓰는 이유는 랜덤 쓰기를 줄여 처리량을 높이기 위함이며, 지속성은 **WAL(로그 선기록)**이 보장한다. 체크포인트는 더티 페이지를 주기적으로 디스크에 반영해 복구 범위를 줄인다."}],"code":{"c":"-- InnoDB: PK 순 물리 정렬 → 범위 스캔 순차적\nSELECT * FROM orders\nWHERE id BETWEEN 1000 AND 2000;","cap":"클러스터형 PK 덕에 범위 조회가 순차 스캔"},"key":["InnoDB=클러스터형(PK 정렬), 보조 인덱스는 PK 저장","LSM=쓰기 강함, 컴팩션 지연 시 읽기 증폭","변경은 WAL 선기록, 더티 페이지는 지연 후 일괄 쓰기"]}},{"t":"WAL과 체크포인트","q":[{"t":"choice","k":"wal-durability","cat":"internals","q":"트랜잭션 커밋 시 데이터 페이지는 아직 디스크에 안 갔는데도 장애 후 복구가 가능한 근본 원리는?","o":["커밋 전에 변경 내역을 WAL에 먼저 순차 기록하고 fsync하므로, 장애 후 로그를 재생(redo)해 복구한다","데이터 페이지가 커밋과 동시에 항상 디스크에 반영되기 때문이다","버퍼 풀이 비휘발성 메모리라서 장애에도 사라지지 않기 때문이다","커밋된 데이터는 네트워크로 다른 서버에 즉시 복제되기 때문이다"],"a":0,"ex":"WAL 원칙상 변경 로그를 데이터 페이지보다 먼저 디스크에 기록하므로, 장애 시 로그 재생으로 커밋을 복구한다.\n💡 개념: Write-Ahead Logging은 로그를 순차 append+fsync해 랜덤한 데이터 페이지 쓰기를 커밋 경로에서 제거하면서 내구성(D)을 보장한다.\n🛠 실무: WAL은 순차 I/O라 빠른 디스크에 두면 커밋 지연이 준다. fsync를 끄면 성능은 오르지만 크래시 시 데이터 손실 위험이 생긴다."},{"t":"choice","k":"checkpoint-purpose","cat":"internals","q":"체크포인트를 주기적으로 수행하는 주된 목적은?","o":["더티 페이지를 디스크에 반영하고 복구 시작 지점을 앞당겨 크래시 복구 시간을 짧게 유지한다","WAL을 완전히 삭제해 디스크 공간을 즉시 회수한다","모든 트랜잭션을 강제로 롤백해 정합성을 맞춘다","버퍼 풀을 비워 메모리를 확보한다"],"a":0,"ex":"체크포인트는 더티 페이지를 디스크에 내리고 복구 시작점(redo 지점)을 전진시켜 복구 시간을 제한한다.\n💡 개념: 체크포인트 이전에 반영된 변경은 복구 시 재생할 필요가 없으므로, WAL 재생 구간이 짧아진다.\n🛠 실무: 체크포인트 간격을 너무 벌리면 복구는 길어지고, 너무 잦으면 더티 페이지 플러시가 몰려 I/O 스파이크가 생겨 균형이 필요하다."},{"t":"choice","k":"wal-retention","cat":"internals","q":"복제 슬롯을 쓰는 스탠바이가 오래 지연되자 프라이머리의 디스크가 WAL로 가득 차기 시작했다. 원인으로 가장 적절한 것은?","o":["복제 슬롯이 아직 소비되지 않은 WAL의 삭제를 막아, 스탠바이가 따라잡을 때까지 WAL이 계속 쌓인다","체크포인트가 WAL을 지우지 못하는 것은 항상 디스크 하드웨어 오류 때문이다","WAL은 원래 삭제되지 않으며 무한히 커지는 것이 정상이다","스탠바이 지연은 프라이머리 WAL 양과 전혀 무관하다"],"a":0,"ex":"복제 슬롯은 소비되지 않은 WAL의 재활용을 막아, 지연된 스탠바이가 따라잡기 전까지 WAL이 누적된다.\n💡 개념: 슬롯은 스탠바이가 필요한 WAL을 보존해 데이터 유실을 막지만, 소비자가 멈추면 프라이머리 디스크를 위협한다.\n🛠 실무: max_slot_wal_keep_size로 상한을 두거나 죽은 슬롯을 정리해 프라이머리 디스크 고갈을 예방한다."},{"t":"choice","k":"group-commit","cat":"internals","q":"동시 커밋이 매우 많은 시스템에서 여러 트랜잭션의 WAL fsync를 하나로 묶어 처리하는 최적화는?","o":["그룹 커밋(group commit): 여러 커밋의 로그 flush를 한 번의 fsync로 합쳐 디스크 동기화 비용을 분산한다","락 에스컬레이션: 여러 락을 하나로 합친다","MVCC 스냅샷: 커밋을 병렬 버전으로 분리한다","체크포인트 병합: 커밋마다 체크포인트를 수행한다"],"a":0,"ex":"그룹 커밋은 동시에 대기 중인 여러 트랜잭션의 로그를 한 번의 fsync로 함께 내려 동기화 오버헤드를 나눈다.\n💡 개념: fsync는 비용이 크므로, 짧게 모아 배치하면 커밋당 평균 비용이 줄어 처리량이 오른다.\n🛠 실무: commit_delay/commit_siblings(Postgres)나 binlog_group_commit(MySQL) 관련 설정으로 고동시성 커밋 처리량을 튜닝한다."},{"t":"input","k":"wal-principle-name","cat":"internals","q":"'데이터 페이지를 디스크에 쓰기 전에 반드시 로그를 먼저 디스크에 기록한다'는 원칙을 부르는 영문 약자는?","a":["WAL","Write-Ahead Log","Write Ahead Logging","write-ahead logging"],"ex":"WAL(Write-Ahead Logging): 로그를 데이터보다 먼저 영속화한다는 원칙이다.\n💡 개념: 이 순서 보장 덕분에 커밋된 변경은 재생(redo)으로 복원되고, 미완료 변경은 취소(undo)할 수 있어 원자성·내구성이 성립한다.\n🛠 실무: 로그 선기록 순서가 깨지면 복구 정합성이 무너지므로, fsync 배리어와 저장장치의 쓰기 캐시 정책을 신뢰할 수 있게 구성한다."}],"th":{"sum":"InnoDB는 **클러스터형 인덱스**라 PK 순으로 물리 정렬돼 범위 스캔에 유리하다. B-tree는 낮은 트리 높이(**fan-out**), LSM-tree는 쓰기 폭주에 강하다. 변경은 **WAL**에 먼저 기록한다.","body":[{"h":"스토리지 엔진","t":"InnoDB는 데이터가 PK B-tree 리프에 정렬 저장(클러스터형)돼 PK 범위 조회가 순차적이라 힙보다 빠르다. 보조 인덱스는 PK를 함께 저장해 실제 행을 찾는데(2차 조회 비용), PK가 크면 인덱스도 커진다. LSM-tree는 쓰기를 메모리+순차 append로 처리해 대량 INSERT에 유리하지만, 컴팩션이 밀리면 여러 SSTable을 뒤져 **읽기 증폭**이 생긴다. 한 페이지가 자식을 많이 갖는 성질이 fan-out이다."},{"h":"버퍼 풀과 WAL","t":"버퍼 풀은 자주 쓰는 페이지를 메모리에 캐시한다. 히트율이 99%→80%로 떨어지면 작업셋이 버퍼 풀보다 커져 디스크 I/O가 급증한 것이다. 더티 페이지를 즉시 안 쓰고 모아 쓰는 이유는 랜덤 쓰기를 줄여 처리량을 높이기 위함이며, 지속성은 **WAL(로그 선기록)**이 보장한다. 체크포인트는 더티 페이지를 주기적으로 디스크에 반영해 복구 범위를 줄인다."}],"code":{"c":"-- InnoDB: PK 순 물리 정렬 → 범위 스캔 순차적\nSELECT * FROM orders\nWHERE id BETWEEN 1000 AND 2000;","cap":"클러스터형 PK 덕에 범위 조회가 순차 스캔"},"key":["InnoDB=클러스터형(PK 정렬), 보조 인덱스는 PK 저장","LSM=쓰기 강함, 컴팩션 지연 시 읽기 증폭","변경은 WAL 선기록, 더티 페이지는 지연 후 일괄 쓰기"]}}]},{"t":"동시성 제어와 트랜잭션 격리","l":[{"t":"MVCC와 버전 정리(VACUUM)","q":[{"t":"choice","k":"mvcc-snapshot","cat":"internals","q":"MVCC 기반 DB에서 읽기 트랜잭션이 동시 쓰기 트랜잭션에 의해 블로킹되지 않는 근본 이유는?","o":["쓰기는 새 버전을 만들고 읽기는 자신의 스냅샷에 보이는 이전 버전을 읽으므로 서로 락으로 막지 않는다","읽기 트랜잭션은 항상 배타 락을 먼저 잡아 쓰기를 밀어내기 때문이다","MVCC는 모든 쓰기를 직렬화해 동시성이 아예 없기 때문이다","읽기는 디스크를 보지 않고 캐시만 보기 때문이다"],"a":0,"ex":"MVCC는 갱신 시 새 버전을 추가하고 각 트랜잭션은 스냅샷에 맞는 버전을 읽어, 읽기와 쓰기가 서로 막지 않는다.\n💡 개념: 각 행 버전은 생성/삭제 트랜잭션 정보를 갖고, 스냅샷은 어떤 버전이 보이는지 결정한다(가시성 규칙).\n🛠 실무: '읽기가 쓰기를 막지 않는다'는 특성 덕에 분석 조회와 OLTP 쓰기를 같이 돌릴 수 있지만, 오래된 버전 축적 비용이 따른다."},{"t":"choice","k":"long-txn-bloat","cat":"internals","q":"장시간 열린 채 방치된 트랜잭션이 하나 있으면 테이블과 인덱스가 비대해지고 조회가 점점 느려지는 이유는?","o":["그 트랜잭션의 스냅샷이 오래된 행 버전을 여전히 볼 수 있어, VACUUM이 죽은 튜플을 회수하지 못하고 계속 쌓인다","열린 트랜잭션은 인덱스를 자동으로 두 배로 복제하기 때문이다","장시간 트랜잭션은 버퍼 풀을 강제로 비우기 때문이다","오래된 트랜잭션은 WAL 기록을 중단시키기 때문이다"],"a":0,"ex":"오래된 트랜잭션의 스냅샷이 옛 버전을 필요로 하는 한 VACUUM이 죽은 튜플을 못 지워 블로트가 누적된다.\n💡 개념: MVCC에서 UPDATE/DELETE는 옛 버전을 즉시 지우지 않고 dead tuple로 남기며, 어떤 스냅샷도 더는 필요로 하지 않을 때 회수된다.\n🛠 실무: idle in transaction 세션을 모니터링·타임아웃 처리하고, 오래 도는 리포트 쿼리를 분리해 블로트를 막는다."},{"t":"choice","k":"vacuum-role","cat":"internals","q":"PostgreSQL에서 (auto)VACUUM이 수행하는 핵심 역할로 가장 정확한 것은?","o":["더 이상 어떤 스냅샷에도 보이지 않는 죽은 튜플의 공간을 회수하고 가시성 맵·통계를 갱신한다","모든 인덱스를 삭제해 디스크를 비운다","실행 중인 모든 트랜잭션을 강제 커밋한다","WAL을 데이터 페이지로 즉시 병합해 로그를 없앤다"],"a":0,"ex":"VACUUM은 죽은 튜플 공간을 재사용 가능하게 회수하고 가시성 맵과 플래너 통계를 갱신한다.\n💡 개념: 일반 VACUUM은 공간을 파일 내부에서 재사용하게 표시할 뿐 OS에 반환하진 않는다. 물리 축소는 VACUUM FULL(락 발생)이 필요하다.\n🛠 실무: 갱신이 잦은 테이블은 autovacuum 임계값을 낮춰 더 자주 돌게 하고, 트랜잭션 ID 소진(wraparound) 경고를 방치하지 않는다."},{"t":"choice","k":"txid-wraparound","cat":"internals","q":"autovacuum이 오래 지연된 대형 테이블에서 데이터베이스가 강제로 읽기 전용 모드로 전환될 위험을 부르는 현상은?","o":["트랜잭션 ID 랩어라운드(wraparound): 32비트 XID가 소진되면 과거/미래 판정이 무너져 데이터 손상을 막으려 셧다운을 유도한다","데드락 폭주로 인한 커넥션 고갈","버퍼 풀 오버플로로 인한 메모리 누수","WAL 세그먼트 순환으로 인한 로그 삭제"],"a":0,"ex":"XID 랩어라운드는 트랜잭션 ID가 순환하며 가시성 판정이 뒤집히는 것을 막고자, 한계 근접 시 DB가 방어적으로 멈춘다.\n💡 개념: freeze 처리가 오래된 튜플의 XID를 특수 값으로 동결해 랩어라운드를 예방하며, 이는 autovacuum의 핵심 임무 중 하나다.\n🛠 실무: age(datfrozenxid)를 모니터링하고 대형·저빈도 테이블도 주기적으로 freeze되도록 autovacuum 설정을 조정한다."},{"t":"input","k":"dead-tuple-term","cat":"internals","q":"MVCC에서 UPDATE/DELETE 후 더 이상 어떤 트랜잭션에도 보이지 않게 된, 회수 대상 행 버전을 무엇이라 부르는가? (한국어 또는 영어)","a":["죽은 튜플","dead tuple","데드 튜플","dead tuples","죽은튜플"],"ex":"죽은 튜플(dead tuple): 어떤 스냅샷에도 보이지 않아 정리(VACUUM) 대상이 된 옛 행 버전이다.\n💡 개념: 갱신은 제자리 수정이 아니라 새 버전 추가이므로 옛 버전이 죽은 튜플로 남고, 이것이 테이블/인덱스 블로트의 원천이다.\n🛠 실무: n_dead_tup 지표로 죽은 튜플 누적을 감시하고, 급증하면 autovacuum 튜닝이나 장기 트랜잭션 여부를 점검한다."}],"th":{"sum":"**MVCC**는 행의 여러 버전을 유지해 읽기가 쓰기를 막지 않는다. 오래된 버전(죽은 튜플)은 `VACUUM`이 회수하며, 방치된 롱 트랜잭션은 비대화를 부른다.","body":[{"h":"MVCC와 VACUUM","t":"읽기 트랜잭션은 자기 스냅샷 시점의 버전을 보므로 동시 쓰기에 블로킹되지 않는다. UPDATE/DELETE는 옛 버전을 남기는데, 어떤 트랜잭션에도 안 보이게 된 것을 **죽은 튜플(dead tuple)**이라 한다. 롱 트랜잭션이 열려 있으면 그 스냅샷이 옛 버전을 붙잡아 VACUUM이 회수를 못 해 테이블·인덱스가 비대해지고 느려진다. autovacuum이 죽은 튜플을 회수하며, 크게 밀리면 트랜잭션 ID wraparound 방지로 DB가 강제 읽기 전용이 될 위험이 있다."},{"h":"락과 격리","t":"공유 락(S)은 여러 트랜잭션이 같이 읽게 하되 수정하려면 배타 락(X)으로 혼자여야 한다(읽기 공유·쓰기 배타). 많은 행을 한 트랜잭션이 갱신하면 엔진이 행 락을 테이블 락으로 승격(에스컬레이션)하는데, 관리 오버헤드는 줄지만 동시성이 크게 떨어지는 트레이드오프가 있다."}],"code":{"c":"-- 방치된 롱 트랜잭션이 VACUUM을 막는지 확인\nSELECT pid, state, xact_start\nFROM pg_stat_activity\nWHERE state = 'idle in transaction'\nORDER BY xact_start;","cap":"죽은 튜플 회수를 막는 롱 트랜잭션 탐지"},"key":["MVCC=버전 유지, 읽기가 쓰기를 안 막음","죽은 튜플은 VACUUM이 회수, 롱 트랜잭션이 방해","읽기 공유(S)·쓰기 배타(X), 락 에스컬레이션은 동시성 저하"]}},{"t":"락: 공유/배타, 행/테이블, 데드락","q":[{"t":"choice","k":"shared-exclusive","cat":"internals","q":"여러 트랜잭션이 같은 행을 동시에 읽을 수는 있지만, 한 트랜잭션이 그 행을 수정하려면 혼자여야 하는 락 규칙은?","o":["공유 락(S)은 서로 호환되지만, 배타 락(X)은 S·X 어느 것과도 호환되지 않는다","공유 락은 배타 락과 항상 호환된다","배타 락은 여러 개가 동시에 잡힐 수 있다","공유 락끼리는 서로 배타적이라 동시에 못 잡는다"],"a":0,"ex":"공유(S) 락은 다수의 읽기가 공존하게 하지만, 배타(X) 락은 다른 어떤 락과도 호환되지 않아 수정 시 단독 접근을 강제한다.\n💡 개념: 락 호환성 행렬에서 S-S는 허용, S-X와 X-X는 충돌한다. 이것이 읽기 동시성과 쓰기 배타성을 동시에 만든다.\n🛠 실무: 순수 MVCC 읽기는 락이 없지만 SELECT ... FOR UPDATE는 X 성격의 행 락을 잡으므로 남용 시 경합을 유발한다."},{"t":"choice","k":"lock-granularity","cat":"internals","q":"많은 행을 한 트랜잭션이 갱신하자 엔진이 개별 행 락 대신 테이블 락으로 승격했다. 이 동작(락 에스컬레이션)의 트레이드오프는?","o":["락 관리 메모리는 절약되지만 락 범위가 넓어져 다른 트랜잭션의 동시성이 크게 떨어진다","동시성이 올라가고 메모리도 절약되어 단점이 없다","행 락보다 항상 더 세밀한 제어가 가능해진다","테이블 락은 읽기를 전혀 막지 않으므로 영향이 없다"],"a":0,"ex":"락 에스컬레이션은 수많은 행 락을 하나의 테이블 락으로 바꿔 오버헤드를 줄이지만, 잠금 범위가 넓어져 동시성을 희생한다.\n💡 개념: 세밀한 락(행)은 동시성이 높지만 락 객체가 많아 메모리·관리 비용이 크고, 굵은 락(테이블)은 그 반대다.\n🛠 실무: 대량 배치는 청크로 나눠 커밋해 광범위한 락 유지 시간을 줄이고 에스컬레이션과 경합을 완화한다."},{"t":"choice","k":"deadlock-cause","cat":"internals","q":"두 트랜잭션이 서로 상대가 쥔 락을 기다려 영원히 진행하지 못하는 데드락을 애플리케이션 레벨에서 예방하는 가장 실용적인 방법은?","o":["여러 자원에 락을 걸 때 모든 트랜잭션이 항상 동일한 순서로 락을 획득하도록 강제한다","모든 트랜잭션을 무한히 길게 유지한다","락을 아예 사용하지 않도록 격리 수준을 없앤다","각 트랜잭션이 자원을 무작위 순서로 잠근다"],"a":0,"ex":"일관된 락 획득 순서를 강제하면 순환 대기 조건이 깨져 데드락이 예방된다.\n💡 개념: 데드락은 상호 배제·점유 대기·비선점·순환 대기 네 조건이 모두 성립할 때 발생하며, 순환 대기를 없애는 것이 실무적으로 가장 쉽다.\n🛠 실무: 엔진의 데드락 탐지기가 한쪽을 victim으로 롤백하므로, 앱은 데드락 오류를 잡아 재시도 로직을 두고 락 순서를 표준화한다."},{"t":"choice","k":"deadlock-resolution","cat":"internals","q":"InnoDB나 PostgreSQL이 데드락을 감지했을 때 실제로 하는 처리는?","o":["사이클에 속한 트랜잭션 중 하나를 victim으로 골라 롤백해 나머지가 진행하게 한다","두 트랜잭션을 모두 무한 대기시켜 사람이 개입할 때까지 둔다","데이터베이스 전체를 재시작한다","두 트랜잭션을 자동 병합해 하나로 만든다"],"a":0,"ex":"엔진은 대기 그래프에서 사이클을 찾아 한 트랜잭션을 victim으로 롤백, 교착을 해소한다.\n💡 개념: 보통 롤백 비용(변경량)이 적은 쪽을 victim으로 선택해 낭비를 줄인다.\n🛠 실무: victim이 된 트랜잭션은 애플리케이션에서 오류로 반환되므로, 지수 백오프 재시도와 짧은 트랜잭션 설계로 대응한다."},{"t":"input","k":"lock-wait-timeout","cat":"internals","q":"트랜잭션이 락을 무한정 기다리지 않도록, 일정 시간 후 대기를 포기하고 에러를 내게 하는 설정을 통칭 무엇이라 하는가? (한국어 또는 영어 구)","a":["락 타임아웃","lock timeout","lock wait timeout","락 대기 타임아웃","lock_timeout"],"ex":"락 타임아웃(lock timeout)은 지정 시간 초과 시 락 대기를 중단하고 오류를 반환한다.\n💡 개념: 데드락 탐지가 순환 대기를 해소한다면, 락 타임아웃은 단순히 오래 걸리는 경합(비순환 대기)까지 한계를 둔다.\n🛠 실무: OLTP 경로에 짧은 lock_timeout을 두어 한 세션의 락 점유가 커넥션 풀 전체를 마비시키는 것을 막는다."}],"th":{"sum":"**MVCC**는 행의 여러 버전을 유지해 읽기가 쓰기를 막지 않는다. 오래된 버전(죽은 튜플)은 `VACUUM`이 회수하며, 방치된 롱 트랜잭션은 비대화를 부른다.","body":[{"h":"MVCC와 VACUUM","t":"읽기 트랜잭션은 자기 스냅샷 시점의 버전을 보므로 동시 쓰기에 블로킹되지 않는다. UPDATE/DELETE는 옛 버전을 남기는데, 어떤 트랜잭션에도 안 보이게 된 것을 **죽은 튜플(dead tuple)**이라 한다. 롱 트랜잭션이 열려 있으면 그 스냅샷이 옛 버전을 붙잡아 VACUUM이 회수를 못 해 테이블·인덱스가 비대해지고 느려진다. autovacuum이 죽은 튜플을 회수하며, 크게 밀리면 트랜잭션 ID wraparound 방지로 DB가 강제 읽기 전용이 될 위험이 있다."},{"h":"락과 격리","t":"공유 락(S)은 여러 트랜잭션이 같이 읽게 하되 수정하려면 배타 락(X)으로 혼자여야 한다(읽기 공유·쓰기 배타). 많은 행을 한 트랜잭션이 갱신하면 엔진이 행 락을 테이블 락으로 승격(에스컬레이션)하는데, 관리 오버헤드는 줄지만 동시성이 크게 떨어지는 트레이드오프가 있다."}],"code":{"c":"-- 방치된 롱 트랜잭션이 VACUUM을 막는지 확인\nSELECT pid, state, xact_start\nFROM pg_stat_activity\nWHERE state = 'idle in transaction'\nORDER BY xact_start;","cap":"죽은 튜플 회수를 막는 롱 트랜잭션 탐지"},"key":["MVCC=버전 유지, 읽기가 쓰기를 안 막음","죽은 튜플은 VACUUM이 회수, 롱 트랜잭션이 방해","읽기 공유(S)·쓰기 배타(X), 락 에스컬레이션은 동시성 저하"]}},{"t":"격리 수준과 동시성 이상현상","q":[{"t":"choice","k":"dirty-read","cat":"internals","q":"한 트랜잭션이 아직 커밋되지 않은 다른 트랜잭션의 변경을 읽어버려, 상대가 롤백하면 존재한 적 없는 값을 본 셈이 되는 이상현상은?","o":["더티 리드(dirty read): READ UNCOMMITTED에서 발생하며 READ COMMITTED 이상에서 방지된다","팬텀 리드: 커밋된 데이터만 읽을 때 발생한다","반복 불가능 읽기: 커밋 전 데이터를 읽을 때만 발생한다","직렬화 실패: 더티 리드와 동일한 의미다"],"a":0,"ex":"더티 리드는 커밋되지 않은 변경을 읽는 것으로, READ UNCOMMITTED에서만 허용되고 READ COMMITTED부터 차단된다.\n💡 개념: 격리 수준은 dirty/non-repeatable/phantom 세 이상현상의 허용 여부로 정의된다.\n🛠 실무: 대부분의 DB 기본값은 READ COMMITTED(또는 그 이상)라 더티 리드는 실무에서 거의 문제되지 않는다."},{"t":"choice","k":"non-repeatable-read","cat":"internals","q":"READ COMMITTED에서 한 트랜잭션이 같은 행을 두 번 SELECT했더니 사이에 다른 트랜잭션이 커밋해 값이 달라졌다. 이 현상과 이를 막는 격리 수준은?","o":["반복 불가능 읽기(non-repeatable read)이며 REPEATABLE READ 이상에서 방지된다","더티 리드이며 SERIALIZABLE에서만 방지된다","팬텀 리드이며 어떤 수준에서도 못 막는다","정상 동작이며 이상현상이 아니다"],"a":0,"ex":"같은 행의 재조회 값이 중간 커밋으로 달라지는 것이 반복 불가능 읽기이며, REPEATABLE READ부터 방지된다.\n💡 개념: RC는 매 문장마다 새 스냅샷을 보지만, RR은 트랜잭션 시작 시점의 스냅샷을 트랜잭션 내내 유지해 재조회 일관성을 준다.\n🛠 실무: 여러 번 읽어 계산하는 정산·리포트 로직은 RR로 올려 중간 변경에 흔들리지 않게 한다."},{"t":"choice","k":"phantom-read","cat":"internals","q":"같은 조건(WHERE)으로 범위를 두 번 조회했더니 다른 트랜잭션이 새 행을 INSERT+커밋해 결과 행 수가 늘어났다. 이 이상현상의 이름은?","o":["팬텀 리드(phantom read): 조건에 맞는 행 집합이 중간 삽입으로 달라진다","더티 리드: 삽입된 커밋 전 행을 본다","반복 불가능 읽기: 기존 행의 값만 바뀐다","데드락: 두 트랜잭션이 서로를 기다린다"],"a":0,"ex":"팬텀 리드는 같은 조건의 결과 집합에 새 행이 나타나거나 사라지는 현상이다.\n💡 개념: 반복 불가능 읽기가 '기존 행 값' 변화라면, 팬텀은 '행 집합(존재 여부)' 변화다. 표준상 SERIALIZABLE에서 방지된다.\n🛠 실무: InnoDB는 갭 락(next-key lock)으로, Postgres는 직렬화 스냅샷 격리(SSI)로 팬텀을 다루므로 엔진별 동작을 확인한다."},{"t":"choice","k":"serializable-cost","cat":"internals","q":"가장 강한 SERIALIZABLE 격리를 무분별하게 전면 적용할 때의 대표적 비용은?","o":["락 경합 증가 또는 직렬화 충돌로 인한 트랜잭션 롤백/재시도가 늘어 처리량이 떨어진다","데이터 정합성이 오히려 나빠진다","WAL이 비활성화되어 내구성이 사라진다","인덱스가 자동으로 삭제된다"],"a":0,"ex":"SERIALIZABLE은 정확성이 가장 높지만 락 경합이나 직렬화 실패로 인한 재시도가 늘어 처리량을 희생한다.\n💡 개념: 엔진에 따라 2PL(엄격한 락) 또는 SSI(충돌 감지 후 롤백)로 구현되며, 후자는 실패 시 앱의 재시도를 전제로 한다.\n🛠 실무: 정말 직렬성이 필요한 소수 트랜잭션에만 SERIALIZABLE을 쓰고, 재시도 루프를 반드시 갖춘다."},{"t":"input","k":"snapshot-isolation","cat":"internals","q":"MVCC 기반에서 트랜잭션이 시작 시점의 일관된 스냅샷만 읽어, 다른 트랜잭션의 중간 커밋에 영향받지 않는 격리 방식을 무엇이라 하는가? (한국어 또는 영어)","a":["스냅샷 격리","snapshot isolation","SI","스냅샷 아이솔레이션"],"ex":"스냅샷 격리(snapshot isolation)는 트랜잭션 시작 시점의 일관된 버전 집합만 읽는다.\n💡 개념: PostgreSQL의 REPEATABLE READ가 사실상 스냅샷 격리이며, 이것만으로는 write skew(쓰기 왜곡) 이상을 못 막아 SERIALIZABLE(SSI)이 필요하다.\n🛠 실무: 잔액 합계 제약처럼 두 행을 각각 읽고 각각 갱신하는 로직은 write skew에 취약하므로 SERIALIZABLE이나 명시적 락으로 보강한다."}],"th":{"sum":"**MVCC**는 행의 여러 버전을 유지해 읽기가 쓰기를 막지 않는다. 오래된 버전(죽은 튜플)은 `VACUUM`이 회수하며, 방치된 롱 트랜잭션은 비대화를 부른다.","body":[{"h":"MVCC와 VACUUM","t":"읽기 트랜잭션은 자기 스냅샷 시점의 버전을 보므로 동시 쓰기에 블로킹되지 않는다. UPDATE/DELETE는 옛 버전을 남기는데, 어떤 트랜잭션에도 안 보이게 된 것을 **죽은 튜플(dead tuple)**이라 한다. 롱 트랜잭션이 열려 있으면 그 스냅샷이 옛 버전을 붙잡아 VACUUM이 회수를 못 해 테이블·인덱스가 비대해지고 느려진다. autovacuum이 죽은 튜플을 회수하며, 크게 밀리면 트랜잭션 ID wraparound 방지로 DB가 강제 읽기 전용이 될 위험이 있다."},{"h":"락과 격리","t":"공유 락(S)은 여러 트랜잭션이 같이 읽게 하되 수정하려면 배타 락(X)으로 혼자여야 한다(읽기 공유·쓰기 배타). 많은 행을 한 트랜잭션이 갱신하면 엔진이 행 락을 테이블 락으로 승격(에스컬레이션)하는데, 관리 오버헤드는 줄지만 동시성이 크게 떨어지는 트레이드오프가 있다."}],"code":{"c":"-- 방치된 롱 트랜잭션이 VACUUM을 막는지 확인\nSELECT pid, state, xact_start\nFROM pg_stat_activity\nWHERE state = 'idle in transaction'\nORDER BY xact_start;","cap":"죽은 튜플 회수를 막는 롱 트랜잭션 탐지"},"key":["MVCC=버전 유지, 읽기가 쓰기를 안 막음","죽은 튜플은 VACUUM이 회수, 롱 트랜잭션이 방해","읽기 공유(S)·쓰기 배타(X), 락 에스컬레이션은 동시성 저하"]}}]},{"t":"데이터 조회 기초","l":[{"t":"SELECT 로 가져오기","q":[{"t":"input","k":"빈칸","q":"users 테이블의 모든 데이터를 조회하세요.","code":"SELECT * ____ users;","a":["FROM","from"],"ex":"FROM 다음에 테이블 이름을 씁니다."},{"t":"choice","k":"문장 끝","q":"SQL 한 문장의 끝에 보통 붙이는 기호는?","o":[".",";",":",","],"a":1,"ex":"세미콜론(;) 으로 문장을 끝냅니다."}],"th":{"sum":"데이터를 읽는 기본은 `SELECT ... FROM ...` 이고, `WHERE`로 원하는 행만 걸러낸다. **모든 열**은 `*`로 나타낸다.","body":[{"h":"SELECT와 FROM","t":"`SELECT`는 어떤 열을 가져올지, `FROM`은 어떤 테이블에서 가져올지 지정한다. 특정 열만 원하면 `SELECT name`, 전체 열은 `SELECT *`처럼 쓴다. 한 문장의 끝에는 보통 세미콜론(`;`)을 붙인다."},{"h":"WHERE와 정렬·제한","t":"`WHERE`는 조건에 맞는 행만 남긴다. 예: `WHERE age = 20`. 결과를 정렬하려면 `ORDER BY`, 몇 개만 보려면 `LIMIT`을 덧붙인다. 문자열 값은 작은따옴표로 감싼다."}],"code":{"c":"SELECT name\nFROM users\nWHERE age = 20\nORDER BY name\nLIMIT 10;","cap":"users에서 나이가 20인 행의 name만 정렬해 10개 조회"},"key":["조회 명령은 `SELECT`, 전체 열은 `*`","조건 필터는 `WHERE`, 정렬은 `ORDER BY`","문장 끝은 세미콜론, 문자열은 작은따옴표"]}},{"t":"WHERE 로 걸러내기","q":[{"t":"input","k":"빈칸","q":"age 가 20인 행만 조회하세요.","code":"SELECT * FROM users WHERE age _ <span class=\"nu\">20</span>;","a":["=","= 20"],"ex":"SQL에서 '같다'는 = 하나입니다."},{"t":"choice","k":"문자열 조건","q":"city 가 'Seoul' 인 조건으로 맞는 것은?","o":["city = Seoul","city == 'Seoul'","city = 'Seoul'","city is Seoul"],"a":2,"ex":"문자열은 작은따옴표로 감싸고 = 로 비교."}],"th":{"sum":"데이터를 읽는 기본은 `SELECT ... FROM ...` 이고, `WHERE`로 원하는 행만 걸러낸다. **모든 열**은 `*`로 나타낸다.","body":[{"h":"SELECT와 FROM","t":"`SELECT`는 어떤 열을 가져올지, `FROM`은 어떤 테이블에서 가져올지 지정한다. 특정 열만 원하면 `SELECT name`, 전체 열은 `SELECT *`처럼 쓴다. 한 문장의 끝에는 보통 세미콜론(`;`)을 붙인다."},{"h":"WHERE와 정렬·제한","t":"`WHERE`는 조건에 맞는 행만 남긴다. 예: `WHERE age = 20`. 결과를 정렬하려면 `ORDER BY`, 몇 개만 보려면 `LIMIT`을 덧붙인다. 문자열 값은 작은따옴표로 감싼다."}],"code":{"c":"SELECT name\nFROM users\nWHERE age = 20\nORDER BY name\nLIMIT 10;","cap":"users에서 나이가 20인 행의 name만 정렬해 10개 조회"},"key":["조회 명령은 `SELECT`, 전체 열은 `*`","조건 필터는 `WHERE`, 정렬은 `ORDER BY`","문장 끝은 세미콜론, 문자열은 작은따옴표"]}},{"t":"정렬과 개수 제한","q":[{"t":"choice","k":"내림차순","q":"큰 값부터 정렬하는 키워드는?","o":["ASC","DESC","DOWN","HIGH"],"a":1,"ex":"DESC 는 내림차순, ASC 는 오름차순(기본)."},{"t":"input","k":"빈칸","q":"결과를 5개만 가져오세요. (MySQL 기준)","code":"SELECT * FROM users _____ <span class=\"nu\">5</span>;","a":["LIMIT","limit"],"ex":"LIMIT n 으로 개수를 제한합니다."}],"th":{"sum":"데이터를 읽는 기본은 `SELECT ... FROM ...` 이고, `WHERE`로 원하는 행만 걸러낸다. **모든 열**은 `*`로 나타낸다.","body":[{"h":"SELECT와 FROM","t":"`SELECT`는 어떤 열을 가져올지, `FROM`은 어떤 테이블에서 가져올지 지정한다. 특정 열만 원하면 `SELECT name`, 전체 열은 `SELECT *`처럼 쓴다. 한 문장의 끝에는 보통 세미콜론(`;`)을 붙인다."},{"h":"WHERE와 정렬·제한","t":"`WHERE`는 조건에 맞는 행만 남긴다. 예: `WHERE age = 20`. 결과를 정렬하려면 `ORDER BY`, 몇 개만 보려면 `LIMIT`을 덧붙인다. 문자열 값은 작은따옴표로 감싼다."}],"code":{"c":"SELECT name\nFROM users\nWHERE age = 20\nORDER BY name\nLIMIT 10;","cap":"users에서 나이가 20인 행의 name만 정렬해 10개 조회"},"key":["조회 명령은 `SELECT`, 전체 열은 `*`","조건 필터는 `WHERE`, 정렬은 `ORDER BY`","문장 끝은 세미콜론, 문자열은 작은따옴표"]}}]},{"t":"집계와 그룹","l":[{"t":"개수·합계 구하기","q":[{"t":"choice","k":"개념","q":"행의 개수를 세는 함수는?","o":["SUM()","COUNT()","NUM()","TOTAL()"],"a":1,"ex":"COUNT(*) 로 행 수를 셉니다."},{"t":"input","k":"빈칸","q":"가장 큰 값을 구하는 함수 이름은?","code":"SELECT ___(price) FROM items;","a":["MAX","max"],"ex":"MAX() 는 최댓값, MIN() 은 최솟값."}],"th":{"sum":"집계 함수 `COUNT`,`SUM`,`AVG`,`MAX`,`MIN`으로 값을 요약하고, `GROUP BY`로 **같은 값끼리 묶어** 그룹별 집계를 낸다.","body":[{"h":"집계 함수","t":"`COUNT(*)`는 행 개수, `SUM(price)`는 합계, `AVG`는 평균, `MAX`/`MIN`은 최대·최소를 구한다. 이들은 여러 행을 하나의 값으로 압축한다."},{"h":"GROUP BY","t":"'도시별 인원 수'처럼 범주별 집계를 낼 때 기준 컬럼을 `GROUP BY`에 두고 `COUNT(*)`를 함께 쓴다. SELECT에는 보통 그룹 기준 컬럼과 집계 함수만 올 수 있다."}],"code":{"c":"SELECT city, COUNT(*) AS cnt\nFROM users\nGROUP BY city;","cap":"도시별 사용자 수 집계"},"key":["개수는 `COUNT`, 합계 `SUM`, 평균 `AVG`, 최대 `MAX`","그룹 집계는 `GROUP BY` + 집계 함수","SELECT엔 그룹 기준 컬럼과 집계만"]}},{"t":"GROUP BY 로 묶기","q":[{"t":"choice","k":"JOIN","q":"두 테이블을 연결해 조회하는 것은?","o":["MERGE","LINK","JOIN","CONNECT"],"a":2,"ex":"JOIN 으로 테이블을 결합합니다."},{"t":"choice","k":"연결 조건","q":"JOIN 에서 연결 기준을 정하는 키워드는?","o":["ON","AT","BY","IF"],"a":0,"ex":"JOIN ... ON 조건 형태입니다."}],"th":{"sum":"집계 함수 `COUNT`,`SUM`,`AVG`,`MAX`,`MIN`으로 값을 요약하고, `GROUP BY`로 **같은 값끼리 묶어** 그룹별 집계를 낸다.","body":[{"h":"집계 함수","t":"`COUNT(*)`는 행 개수, `SUM(price)`는 합계, `AVG`는 평균, `MAX`/`MIN`은 최대·최소를 구한다. 이들은 여러 행을 하나의 값으로 압축한다."},{"h":"GROUP BY","t":"'도시별 인원 수'처럼 범주별 집계를 낼 때 기준 컬럼을 `GROUP BY`에 두고 `COUNT(*)`를 함께 쓴다. SELECT에는 보통 그룹 기준 컬럼과 집계 함수만 올 수 있다."}],"code":{"c":"SELECT city, COUNT(*) AS cnt\nFROM users\nGROUP BY city;","cap":"도시별 사용자 수 집계"},"key":["개수는 `COUNT`, 합계 `SUM`, 평균 `AVG`, 최대 `MAX`","그룹 집계는 `GROUP BY` + 집계 함수","SELECT엔 그룹 기준 컬럼과 집계만"]}}]},{"t":"JOIN 심화","l":[{"t":"INNER JOIN과 LEFT JOIN","q":[{"t":"choice","k":"개념","q":"INNER JOIN은 두 테이블에서 어떤 행을 반환하나요?","o":["양쪽 테이블에 모두 매칭되는 행만","왼쪽 테이블의 모든 행","오른쪽 테이블의 모든 행","매칭되지 않는 행만"],"a":0,"ex":"INNER JOIN은 조인 조건이 일치하는 행만 반환합니다."},{"t":"input","k":"빈칸","q":"두 테이블에서 조건이 일치하는 행만 가져오는 조인은 ____ JOIN이다.","a":["INNER"],"ex":"INNER JOIN은 교집합에 해당하는 행만 반환합니다."}],"th":{"sum":"`INNER JOIN`은 양쪽 다 일치하는 행만, `LEFT JOIN`은 **왼쪽 전체**를 유지하고 짝 없으면 오른쪽을 NULL로 채운다. 별칭 `AS`로 테이블을 짧게 부른다.","body":[{"h":"INNER와 LEFT/RIGHT","t":"`INNER JOIN`은 조건이 맞는 행만 반환한다. `LEFT JOIN`은 왼쪽 테이블 모든 행을 보장하고 매칭 없는 오른쪽 컬럼은 NULL이 되므로, 주문 없는 고객도 결과에 NULL로 나타난다. `RIGHT JOIN`은 오른쪽 전체를 유지하며, `A LEFT JOIN B`는 테이블 순서를 바꾸면 `B RIGHT JOIN A`와 같다."},{"h":"여러 테이블과 별칭","t":"테이블 3개를 잇으려면 보통 `JOIN` 절이 2번 필요하다(테이블 수 - 1). 컬럼·테이블에 `AS`로 별칭을 붙이면 `c.name`, `o.amount`처럼 짧고 명확하게 참조할 수 있고, self-join 등 같은 테이블을 두 번 쓸 때 필수다."}],"code":{"c":"SELECT c.name, o.amount\nFROM customers AS c\nLEFT JOIN orders AS o ON o.customer_id = c.id;","cap":"주문 없는 고객도 NULL로 함께 조회(LEFT JOIN)"},"key":["INNER=양쪽 일치, LEFT=왼쪽 전체+오른쪽 NULL","`A LEFT JOIN B` = `B RIGHT JOIN A`","테이블 3개=JOIN 2번, 별칭은 `AS`"]}},{"t":"RIGHT JOIN과 여러 테이블","q":[{"t":"input","k":"빈칸","q":"테이블 3개를 조인하려면 보통 JOIN 절이 몇 번 필요한가요? (숫자)","a":["2"],"ex":"테이블 N개를 연결하려면 보통 N-1개의 JOIN 절이 필요합니다."},{"t":"choice","k":"개념","q":"양쪽 테이블의 매칭되지 않는 행까지 모두 포함하는 조인은? (표준 SQL)","o":["FULL OUTER JOIN","INNER JOIN","CROSS JOIN","SELF JOIN"],"a":0,"ex":"FULL OUTER JOIN은 양쪽의 모든 행을 포함하며, MySQL은 직접 지원하지 않아 UNION으로 구현합니다."}],"th":{"sum":"`INNER JOIN`은 양쪽 다 일치하는 행만, `LEFT JOIN`은 **왼쪽 전체**를 유지하고 짝 없으면 오른쪽을 NULL로 채운다. 별칭 `AS`로 테이블을 짧게 부른다.","body":[{"h":"INNER와 LEFT/RIGHT","t":"`INNER JOIN`은 조건이 맞는 행만 반환한다. `LEFT JOIN`은 왼쪽 테이블 모든 행을 보장하고 매칭 없는 오른쪽 컬럼은 NULL이 되므로, 주문 없는 고객도 결과에 NULL로 나타난다. `RIGHT JOIN`은 오른쪽 전체를 유지하며, `A LEFT JOIN B`는 테이블 순서를 바꾸면 `B RIGHT JOIN A`와 같다."},{"h":"여러 테이블과 별칭","t":"테이블 3개를 잇으려면 보통 `JOIN` 절이 2번 필요하다(테이블 수 - 1). 컬럼·테이블에 `AS`로 별칭을 붙이면 `c.name`, `o.amount`처럼 짧고 명확하게 참조할 수 있고, self-join 등 같은 테이블을 두 번 쓸 때 필수다."}],"code":{"c":"SELECT c.name, o.amount\nFROM customers AS c\nLEFT JOIN orders AS o ON o.customer_id = c.id;","cap":"주문 없는 고객도 NULL로 함께 조회(LEFT JOIN)"},"key":["INNER=양쪽 일치, LEFT=왼쪽 전체+오른쪽 NULL","`A LEFT JOIN B` = `B RIGHT JOIN A`","테이블 3개=JOIN 2번, 별칭은 `AS`"]}},{"t":"별칭 AS로 조인 다루기","q":[{"t":"input","k":"빈칸","q":"컬럼이나 테이블에 별칭을 붙일 때 쓰는 키워드는?","a":["AS"],"ex":"AS로 별칭을 지정하며, 대부분의 DB에서 AS는 생략할 수 있습니다."},{"t":"choice","k":"개념","q":"조인 시 테이블 별칭을 사용하는 주된 이유는?","o":["긴 테이블명을 짧게 쓰고 같은 컬럼명을 구분","성능을 두 배로 향상","데이터를 삭제하려고","인덱스를 자동 생성하려고"],"a":0,"ex":"별칭은 쿼리를 간결하게 하고 여러 테이블의 동일한 컬럼명을 명확히 구분해 줍니다."},{"t":"input","k":"빈칸","q":"SELECT COUNT(*) ____ total 처럼 집계 결과에 이름을 붙이는 키워드는?","a":["AS"],"ex":"AS로 집계 결과 컬럼에 total 같은 별칭을 붙일 수 있습니다."}],"th":{"sum":"`INNER JOIN`은 양쪽 다 일치하는 행만, `LEFT JOIN`은 **왼쪽 전체**를 유지하고 짝 없으면 오른쪽을 NULL로 채운다. 별칭 `AS`로 테이블을 짧게 부른다.","body":[{"h":"INNER와 LEFT/RIGHT","t":"`INNER JOIN`은 조건이 맞는 행만 반환한다. `LEFT JOIN`은 왼쪽 테이블 모든 행을 보장하고 매칭 없는 오른쪽 컬럼은 NULL이 되므로, 주문 없는 고객도 결과에 NULL로 나타난다. `RIGHT JOIN`은 오른쪽 전체를 유지하며, `A LEFT JOIN B`는 테이블 순서를 바꾸면 `B RIGHT JOIN A`와 같다."},{"h":"여러 테이블과 별칭","t":"테이블 3개를 잇으려면 보통 `JOIN` 절이 2번 필요하다(테이블 수 - 1). 컬럼·테이블에 `AS`로 별칭을 붙이면 `c.name`, `o.amount`처럼 짧고 명확하게 참조할 수 있고, self-join 등 같은 테이블을 두 번 쓸 때 필수다."}],"code":{"c":"SELECT c.name, o.amount\nFROM customers AS c\nLEFT JOIN orders AS o ON o.customer_id = c.id;","cap":"주문 없는 고객도 NULL로 함께 조회(LEFT JOIN)"},"key":["INNER=양쪽 일치, LEFT=왼쪽 전체+오른쪽 NULL","`A LEFT JOIN B` = `B RIGHT JOIN A`","테이블 3개=JOIN 2번, 별칭은 `AS`"]}}]},{"t":"데이터 조작","l":[{"t":"INSERT INTO로 추가하기","q":[{"t":"input","k":"빈칸","q":"테이블에 새 행을 추가하는 명령은 ____ INTO 이다.","a":["INSERT"],"ex":"INSERT INTO 테이블 (컬럼) VALUES (값) 형식으로 새 행을 추가합니다."},{"t":"choice","k":"개념","q":"여러 행을 한 번에 삽입할 때 VALUES 뒤 형식으로 옳은 것은?","o":["(값1),(값2),(값3)","값1 값2 값3","VALUES를 여러 번 반복","한 번에 삽입은 불가능"],"a":0,"ex":"VALUES (..),(..),(..) 처럼 괄호 묶음을 콤마로 나열하면 여러 행을 한 번에 삽입합니다."}],"th":{"sum":"행 추가는 `INSERT INTO`, 값 수정은 `UPDATE ... SET`, 삭제는 `DELETE`다. `UPDATE`/`DELETE`에 `WHERE`를 빠뜨리면 **전체 행**이 대상이 되니 주의.","body":[{"h":"INSERT","t":"`INSERT INTO users (name) VALUES ('Kim')`은 name만 지정하고 나머지 컬럼은 기본값이나 NULL로 채운다. 여러 행은 `VALUES (...),(...),(...)`처럼 콤마로 잇는다. 조회 결과를 그대로 넣으려면 `INSERT INTO ... SELECT ...`를 쓴다."},{"h":"UPDATE와 DELETE","t":"`UPDATE`는 `SET 컬럼 = 값`으로 무엇을 바꿀지 정하고, `WHERE`로 어떤 행인지 좁힌다. `WHERE`가 없으면 모든 행이 바뀌거나 지워지므로 항상 조건을 먼저 확인한다."}],"code":{"c":"INSERT INTO users (name) VALUES ('Kim');\nUPDATE users SET age = 21 WHERE name = 'Kim';\nDELETE FROM users WHERE name = 'Kim';","cap":"추가·수정·삭제의 기본 3형태"},"key":["추가 `INSERT INTO`, 수정 `UPDATE SET`, 삭제 `DELETE`","미지정 컬럼은 기본값/NULL","WHERE 없는 UPDATE/DELETE는 전체 행"]}},{"t":"UPDATE와 SET","q":[{"t":"input","k":"빈칸","q":"기존 행의 값을 수정하는 명령은?","a":["UPDATE"],"ex":"UPDATE 테이블 SET 컬럼=값 WHERE 조건 형식으로 값을 수정합니다."},{"t":"choice","k":"개념","q":"UPDATE에서 어떤 컬럼을 어떤 값으로 바꿀지 지정하는 절은?","o":["SET","WHERE","FROM","VALUES"],"a":0,"ex":"SET 절에 컬럼=새값 을 지정하여 수정할 내용을 정합니다."}],"th":{"sum":"행 추가는 `INSERT INTO`, 값 수정은 `UPDATE ... SET`, 삭제는 `DELETE`다. `UPDATE`/`DELETE`에 `WHERE`를 빠뜨리면 **전체 행**이 대상이 되니 주의.","body":[{"h":"INSERT","t":"`INSERT INTO users (name) VALUES ('Kim')`은 name만 지정하고 나머지 컬럼은 기본값이나 NULL로 채운다. 여러 행은 `VALUES (...),(...),(...)`처럼 콤마로 잇는다. 조회 결과를 그대로 넣으려면 `INSERT INTO ... SELECT ...`를 쓴다."},{"h":"UPDATE와 DELETE","t":"`UPDATE`는 `SET 컬럼 = 값`으로 무엇을 바꿀지 정하고, `WHERE`로 어떤 행인지 좁힌다. `WHERE`가 없으면 모든 행이 바뀌거나 지워지므로 항상 조건을 먼저 확인한다."}],"code":{"c":"INSERT INTO users (name) VALUES ('Kim');\nUPDATE users SET age = 21 WHERE name = 'Kim';\nDELETE FROM users WHERE name = 'Kim';","cap":"추가·수정·삭제의 기본 3형태"},"key":["추가 `INSERT INTO`, 수정 `UPDATE SET`, 삭제 `DELETE`","미지정 컬럼은 기본값/NULL","WHERE 없는 UPDATE/DELETE는 전체 행"]}},{"t":"DELETE와 주의사항","q":[{"t":"input","k":"빈칸","q":"테이블에서 행을 삭제하는 명령은?","a":["DELETE"],"ex":"DELETE FROM 테이블 WHERE 조건 형식으로 행을 삭제합니다."},{"t":"choice","k":"개념","q":"특정 행만 안전하게 삭제하려면 반드시 함께 써야 할 절은?","o":["WHERE","ORDER BY","GROUP BY","HAVING"],"a":0,"ex":"WHERE 조건으로 삭제 대상 행을 한정해야 합니다."}],"th":{"sum":"행 추가는 `INSERT INTO`, 값 수정은 `UPDATE ... SET`, 삭제는 `DELETE`다. `UPDATE`/`DELETE`에 `WHERE`를 빠뜨리면 **전체 행**이 대상이 되니 주의.","body":[{"h":"INSERT","t":"`INSERT INTO users (name) VALUES ('Kim')`은 name만 지정하고 나머지 컬럼은 기본값이나 NULL로 채운다. 여러 행은 `VALUES (...),(...),(...)`처럼 콤마로 잇는다. 조회 결과를 그대로 넣으려면 `INSERT INTO ... SELECT ...`를 쓴다."},{"h":"UPDATE와 DELETE","t":"`UPDATE`는 `SET 컬럼 = 값`으로 무엇을 바꿀지 정하고, `WHERE`로 어떤 행인지 좁힌다. `WHERE`가 없으면 모든 행이 바뀌거나 지워지므로 항상 조건을 먼저 확인한다."}],"code":{"c":"INSERT INTO users (name) VALUES ('Kim');\nUPDATE users SET age = 21 WHERE name = 'Kim';\nDELETE FROM users WHERE name = 'Kim';","cap":"추가·수정·삭제의 기본 3형태"},"key":["추가 `INSERT INTO`, 수정 `UPDATE SET`, 삭제 `DELETE`","미지정 컬럼은 기본값/NULL","WHERE 없는 UPDATE/DELETE는 전체 행"]}}]},{"t":"필터·집합 심화","l":[{"t":"DISTINCT와 LIKE","q":[{"t":"input","k":"빈칸","q":"중복을 제거하고 고유한 값만 조회하는 키워드는?","a":["DISTINCT"],"ex":"SELECT DISTINCT 컬럼 은 중복을 제거한 고유 값만 반환합니다."},{"t":"choice","k":"LIKE","q":"LIKE 'A%' 는 무엇을 찾나요?","o":["A로 시작하는 문자열","A로 끝나는 문자열","정확히 'A%' 문자열","A를 포함하지 않는 문자열"],"a":0,"ex":"% 는 0개 이상의 임의 문자를 의미하므로 'A%'는 A로 시작하는 값을 찾습니다."},{"t":"choice","k":"쿼리","q":"이 쿼리의 결과는?","o":["중복 없는 도시 목록","모든 행의 city (중복 포함)","도시의 개수","가장 큰 city 값"],"a":0,"code":"SELECT DISTINCT city\nFROM customers","ex":"DISTINCT로 city의 중복을 제거한 고유 목록을 반환합니다."},{"t":"choice","k":"LIKE","q":"'%son' 패턴에 매칭되는 값은?","o":["Johnson","Sonata","sonic","song"],"a":0,"ex":"'%son'은 son으로 끝나는 문자열을 찾으므로 Johnson이 매칭됩니다."}],"th":{"sum":"`DISTINCT`는 중복 제거, `LIKE`는 패턴 검색(`%`=여러 글자, `_`=한 글자). `IN`/`BETWEEN`/`IS NULL`로 조건을 간결히 쓴다.","body":[{"h":"DISTINCT와 LIKE","t":"`DISTINCT`는 고유 값만 남긴다. `LIKE 'A%'`는 A로 시작하는 값, `'%son'`은 son으로 끝나는 값(예: Johnson, Wilson)을 찾는다. `%`는 0글자 이상, `_`는 정확히 한 글자를 대체한다."},{"h":"IN·BETWEEN·IS NULL","t":"`age IN (10,20,30)`은 `age=10 OR age=20 OR age=30`과 같다. `BETWEEN 1 AND 10`은 경계를 포함한 1~10 범위다. NULL은 `=`로 비교할 수 없어 반드시 `IS NULL`/`IS NOT NULL`을 쓴다. `UNION`과 서브쿼리로 여러 조건 결과를 합치거나 중첩 조회할 수 있다."}],"code":{"c":"SELECT DISTINCT city\nFROM users\nWHERE age BETWEEN 20 AND 29\n  AND name LIKE 'A%'\n  AND phone IS NOT NULL;","cap":"중복 제거+범위+패턴+NULL 조건 결합"},"key":["중복 제거 `DISTINCT`, 패턴 `LIKE`(%=여러, _=한 글자)","`IN`=OR 나열, `BETWEEN`=경계 포함 범위","NULL 비교는 `IS NULL`(=은 안 됨)"]}},{"t":"IN, BETWEEN, IS NULL","q":[{"t":"input","k":"빈칸","q":"NULL 값을 찾을 때 = NULL 대신 써야 하는 표현은? (____ NULL)","a":["IS"],"ex":"NULL 비교는 = 로 할 수 없고 IS NULL / IS NOT NULL 을 사용합니다."},{"t":"choice","k":"NULL","q":"WHERE price = NULL 이 원하는 대로 동작하지 않는 이유는?","o":["NULL은 = 로 비교되지 않아 결과가 항상 UNKNOWN","문법 오류라서","NULL이 항상 0이라서","price 컬럼이 없어서"],"a":0,"ex":"NULL과의 비교는 참도 거짓도 아닌 UNKNOWN이라 IS NULL을 써야 합니다."}],"th":{"sum":"`DISTINCT`는 중복 제거, `LIKE`는 패턴 검색(`%`=여러 글자, `_`=한 글자). `IN`/`BETWEEN`/`IS NULL`로 조건을 간결히 쓴다.","body":[{"h":"DISTINCT와 LIKE","t":"`DISTINCT`는 고유 값만 남긴다. `LIKE 'A%'`는 A로 시작하는 값, `'%son'`은 son으로 끝나는 값(예: Johnson, Wilson)을 찾는다. `%`는 0글자 이상, `_`는 정확히 한 글자를 대체한다."},{"h":"IN·BETWEEN·IS NULL","t":"`age IN (10,20,30)`은 `age=10 OR age=20 OR age=30`과 같다. `BETWEEN 1 AND 10`은 경계를 포함한 1~10 범위다. NULL은 `=`로 비교할 수 없어 반드시 `IS NULL`/`IS NOT NULL`을 쓴다. `UNION`과 서브쿼리로 여러 조건 결과를 합치거나 중첩 조회할 수 있다."}],"code":{"c":"SELECT DISTINCT city\nFROM users\nWHERE age BETWEEN 20 AND 29\n  AND name LIKE 'A%'\n  AND phone IS NOT NULL;","cap":"중복 제거+범위+패턴+NULL 조건 결합"},"key":["중복 제거 `DISTINCT`, 패턴 `LIKE`(%=여러, _=한 글자)","`IN`=OR 나열, `BETWEEN`=경계 포함 범위","NULL 비교는 `IS NULL`(=은 안 됨)"]}},{"t":"UNION과 서브쿼리","q":[{"t":"choice","k":"UNION","q":"UNION과 UNION ALL의 차이는?","o":["UNION은 중복 제거, UNION ALL은 중복 유지","둘은 완전히 같다","UNION ALL이 중복을 제거한다","UNION은 정렬만 한다"],"a":0,"ex":"UNION은 중복을 제거하고, UNION ALL은 모든 행을 그대로 유지해 보통 더 빠릅니다."},{"t":"choice","k":"쿼리","q":"이 쿼리가 반환하는 것은?","o":["직원이 5명 이상인 부서","모든 부서","직원 수가 5 미만인 부서","가장 큰 부서 하나"],"a":0,"code":"SELECT dept, COUNT(*)\nFROM emp\nGROUP BY dept\nHAVING COUNT(*) &gt;= 5","ex":"GROUP BY로 부서별 집계 후 HAVING으로 직원 5명 이상인 그룹만 남깁니다."}],"th":{"sum":"`DISTINCT`는 중복 제거, `LIKE`는 패턴 검색(`%`=여러 글자, `_`=한 글자). `IN`/`BETWEEN`/`IS NULL`로 조건을 간결히 쓴다.","body":[{"h":"DISTINCT와 LIKE","t":"`DISTINCT`는 고유 값만 남긴다. `LIKE 'A%'`는 A로 시작하는 값, `'%son'`은 son으로 끝나는 값(예: Johnson, Wilson)을 찾는다. `%`는 0글자 이상, `_`는 정확히 한 글자를 대체한다."},{"h":"IN·BETWEEN·IS NULL","t":"`age IN (10,20,30)`은 `age=10 OR age=20 OR age=30`과 같다. `BETWEEN 1 AND 10`은 경계를 포함한 1~10 범위다. NULL은 `=`로 비교할 수 없어 반드시 `IS NULL`/`IS NOT NULL`을 쓴다. `UNION`과 서브쿼리로 여러 조건 결과를 합치거나 중첩 조회할 수 있다."}],"code":{"c":"SELECT DISTINCT city\nFROM users\nWHERE age BETWEEN 20 AND 29\n  AND name LIKE 'A%'\n  AND phone IS NOT NULL;","cap":"중복 제거+범위+패턴+NULL 조건 결합"},"key":["중복 제거 `DISTINCT`, 패턴 `LIKE`(%=여러, _=한 글자)","`IN`=OR 나열, `BETWEEN`=경계 포함 범위","NULL 비교는 `IS NULL`(=은 안 됨)"]}}]},{"t":"문자열·숫자 함수","l":[{"t":"문자열 함수 기초","q":[{"t":"choice","k":"함수","q":"UPPER('sql') 의 결과는?","o":["SQL","sql","Sql","sQl"],"a":0,"ex":"UPPER는 문자열을 모두 대문자로 변환합니다. 'sql' → 'SQL'."},{"t":"choice","k":"함수","q":"LOWER('Hello') 의 결과는?","o":["hello","HELLO","Hello","hELLO"],"a":0,"ex":"LOWER는 문자열을 모두 소문자로 변환합니다. 'Hello' → 'hello'."},{"t":"input","k":"빈칸","q":"LENGTH('apple') 의 결과 숫자를 쓰세요.","a":["5"],"ex":"LENGTH는 문자열의 길이를 반환합니다. 'apple'은 5글자입니다."},{"t":"choice","k":"함수","q":"문자열의 길이를 구하는 함수는?","o":["LENGTH","UPPER","CONCAT","ROUND"],"a":0,"ex":"LENGTH가 문자열 길이를 반환합니다. UPPER는 대문자 변환입니다."},{"t":"input","k":"빈칸","q":"문자열을 대문자로 바꾸려면 어떤 함수를 쓰나요? (함수 이름만)","a":["UPPER"],"ex":"UPPER('abc') → 'ABC' 처럼 대문자로 변환합니다."}],"th":{"sum":"문자열은 `UPPER`/`LOWER`로 대소문자, `LENGTH`로 길이, `CONCAT`으로 이어붙이고 `SUBSTRING`으로 잘라낸다.","body":[{"h":"문자열 함수","t":"`UPPER('sql')`→'SQL', `LOWER('Hello')`→'hello', `LENGTH('apple')`→5다. `CONCAT('SQL','문법')`은 'SQL문법'처럼 인자들을 순서대로 붙인다."},{"h":"SUBSTRING과 숫자 함수","t":"`SUBSTRING(문자열, 시작, 길이)`는 1부터 세는 시작 위치에서 지정한 길이만큼 잘라낸다. `SUBSTRING('Database',1,4)`→'Data'. 숫자 함수로는 반올림 `ROUND`, 나머지 `MOD`, 절대값 `ABS` 등이 있다."}],"code":{"c":"SELECT UPPER('sql'),\n       LENGTH('apple'),\n       CONCAT('SQL','문법'),\n       SUBSTRING('Database', 1, 4);","cap":"대문자·길이·연결·부분추출 결과 확인"},"key":["대문자 `UPPER`, 소문자 `LOWER`, 길이 `LENGTH`","이어붙이기 `CONCAT`","`SUBSTRING`은 시작 위치를 1부터 셈"]}},{"t":"문자열 조작","q":[{"t":"choice","k":"함수","q":"CONCAT('SQL','문법') 의 결과는?","o":["SQL문법","문법SQL","SQL 문법","SQLNULL"],"a":0,"ex":"CONCAT은 문자열을 이어 붙입니다. 공백 없이 'SQL문법'이 됩니다."},{"t":"choice","k":"함수","q":"SUBSTRING('Database', 1, 4) 의 결과는?","o":["Data","atab","base","Datab"],"a":0,"ex":"SUBSTRING(문자열, 시작위치, 길이)로, 1번째부터 4글자는 'Data'입니다. 위치는 1부터 셉니다."},{"t":"input","k":"함수","q":"두 문자열을 이어 붙이는 함수 이름은? (함수 이름만)","a":["CONCAT"],"ex":"CONCAT('a','b') → 'ab' 처럼 문자열을 연결합니다."},{"t":"input","k":"빈칸","q":"SUBSTRING('coding', 1, 4) 의 결과 문자열을 쓰세요.","a":["codi"],"ex":"1번째부터 4글자를 뽑으면 c, o, d, i → 'codi'입니다."}],"th":{"sum":"문자열은 `UPPER`/`LOWER`로 대소문자, `LENGTH`로 길이, `CONCAT`으로 이어붙이고 `SUBSTRING`으로 잘라낸다.","body":[{"h":"문자열 함수","t":"`UPPER('sql')`→'SQL', `LOWER('Hello')`→'hello', `LENGTH('apple')`→5다. `CONCAT('SQL','문법')`은 'SQL문법'처럼 인자들을 순서대로 붙인다."},{"h":"SUBSTRING과 숫자 함수","t":"`SUBSTRING(문자열, 시작, 길이)`는 1부터 세는 시작 위치에서 지정한 길이만큼 잘라낸다. `SUBSTRING('Database',1,4)`→'Data'. 숫자 함수로는 반올림 `ROUND`, 나머지 `MOD`, 절대값 `ABS` 등이 있다."}],"code":{"c":"SELECT UPPER('sql'),\n       LENGTH('apple'),\n       CONCAT('SQL','문법'),\n       SUBSTRING('Database', 1, 4);","cap":"대문자·길이·연결·부분추출 결과 확인"},"key":["대문자 `UPPER`, 소문자 `LOWER`, 길이 `LENGTH`","이어붙이기 `CONCAT`","`SUBSTRING`은 시작 위치를 1부터 셈"]}},{"t":"숫자 함수","q":[{"t":"choice","k":"함수","q":"ROUND(3.14159, 2) 의 결과는?","o":["3.14","3.15","3.1","3.142"],"a":0,"ex":"ROUND(값, 자릿수)는 소수점 아래 지정 자리까지 반올림합니다. 2자리 → 3.14."},{"t":"input","k":"빈칸","q":"MOD(10, 3) 의 결과 숫자를 쓰세요.","a":["1"],"ex":"MOD는 나머지를 반환합니다. 10을 3으로 나눈 나머지는 1입니다."},{"t":"choice","k":"함수","q":"ROUND(7.836, 1) 의 결과는?","o":["7.8","7.9","7.83","8"],"a":0,"ex":"소수점 아래 1자리까지 반올림하면 셋째 자리 6을 보고 둘째 자리에서 반올림하여 7.8입니다."},{"t":"input","k":"빈칸","q":"ABS(-15) 의 결과 숫자를 쓰세요.","a":["15"],"ex":"절댓값 함수 ABS는 부호를 없앤 값을 반환합니다. -15 → 15."}],"th":{"sum":"문자열은 `UPPER`/`LOWER`로 대소문자, `LENGTH`로 길이, `CONCAT`으로 이어붙이고 `SUBSTRING`으로 잘라낸다.","body":[{"h":"문자열 함수","t":"`UPPER('sql')`→'SQL', `LOWER('Hello')`→'hello', `LENGTH('apple')`→5다. `CONCAT('SQL','문법')`은 'SQL문법'처럼 인자들을 순서대로 붙인다."},{"h":"SUBSTRING과 숫자 함수","t":"`SUBSTRING(문자열, 시작, 길이)`는 1부터 세는 시작 위치에서 지정한 길이만큼 잘라낸다. `SUBSTRING('Database',1,4)`→'Data'. 숫자 함수로는 반올림 `ROUND`, 나머지 `MOD`, 절대값 `ABS` 등이 있다."}],"code":{"c":"SELECT UPPER('sql'),\n       LENGTH('apple'),\n       CONCAT('SQL','문법'),\n       SUBSTRING('Database', 1, 4);","cap":"대문자·길이·연결·부분추출 결과 확인"},"key":["대문자 `UPPER`, 소문자 `LOWER`, 길이 `LENGTH`","이어붙이기 `CONCAT`","`SUBSTRING`은 시작 위치를 1부터 셈"]}}]},{"t":"CASE와 조건식","l":[{"t":"CASE 기본","q":[{"t":"choice","k":"CASE","q":"score 값이 85일 때 아래 CASE의 결과는?","code":"CASE WHEN score &gt;= 90 THEN 'A'\n     WHEN score &gt;= 80 THEN 'B'\n     ELSE 'C' END","o":["B","A","C","NULL"],"a":0,"ex":"위에서부터 조건을 확인합니다. 85는 90 미만이라 첫 조건은 거짓, 80 이상이라 두 번째가 참이므로 'B'."},{"t":"input","k":"빈칸","q":"조건을 지정하는 키워드를 채우세요: CASE ___ score &gt; 60 THEN '합격' END","a":["WHEN"],"ex":"CASE 다음에 WHEN 조건 THEN 결과 형태로 작성합니다."}],"th":{"sum":"`CASE WHEN 조건 THEN 값 ... ELSE 값 END`로 조건에 따라 다른 값을 낸다. 맞는 `WHEN`이 없고 `ELSE`도 없으면 결과는 **NULL**이다.","body":[{"h":"검색 CASE와 단순 CASE","t":"검색 CASE는 `CASE WHEN score > 60 THEN '합격' END`처럼 각 WHEN에 조건식을 쓴다. 단순 CASE는 `CASE 표현식 WHEN 값 THEN ...`으로 한 표현식을 여러 값과 등호 비교한다. 둘 다 `END`로 끝난다."},{"h":"평가 순서와 ELSE","t":"WHEN들은 위에서부터 평가되어 처음 참인 가지의 값을 반환한다. 어떤 WHEN도 만족하지 않으면 `ELSE` 값을, ELSE가 없으면 NULL을 낸다. `IF(조건, 참값, 거짓값)`은 두 갈래일 때 간단한 대안이다."}],"code":{"c":"SELECT CASE\n         WHEN score >= 90 THEN 'A'\n         WHEN score >= 80 THEN 'B'\n         ELSE 'C'\n       END AS grade\nFROM students;","cap":"점수를 등급으로 분류하는 검색 CASE"},"key":["CASE는 `END`로 종료","일치 WHEN 없고 ELSE 없으면 NULL","단순 CASE는 표현식과 값을 등호 비교"]}},{"t":"CASE 활용","q":[{"t":"choice","k":"CASE","q":"grade 값이 3일 때 아래 단순 CASE의 결과는?","code":"CASE grade WHEN 1 THEN '금'\n           WHEN 2 THEN '은'\n           WHEN 3 THEN '동' END","o":["동","은","금","NULL"],"a":0,"ex":"단순 CASE는 grade 값과 각 값을 비교합니다. 3과 일치하는 '동'이 반환됩니다."},{"t":"choice","k":"CASE","q":"단순 CASE 식(CASE 표현식 WHEN 값...)에 대한 설명으로 옳은 것은?","o":["특정 값과 같은지(=) 비교할 때 사용한다","부등호(&lt;, &gt;) 범위 비교에 적합하다","END를 생략할 수 있다","ELSE가 반드시 필요하다"],"a":0,"ex":"단순 CASE는 등호 일치 비교에 쓰이고, 범위 비교는 검색 CASE(CASE WHEN 조건)를 씁니다."},{"t":"input","k":"빈칸","q":"CASE 결과에 별칭을 주려면 END 뒤에 어떤 키워드를 쓰나요? (키워드만)","a":["AS"],"ex":"CASE ... END AS 별칭 형태로 컬럼에 이름을 붙입니다."},{"t":"choice","k":"CASE","q":"CASE 식을 사용할 수 있는 위치는?","o":["SELECT 절만","WHERE 절만","ORDER BY 절만","위 모두 가능"],"a":3,"ex":"CASE는 SELECT, WHERE, ORDER BY 등 다양한 위치에서 사용할 수 있습니다."}],"th":{"sum":"`CASE WHEN 조건 THEN 값 ... ELSE 값 END`로 조건에 따라 다른 값을 낸다. 맞는 `WHEN`이 없고 `ELSE`도 없으면 결과는 **NULL**이다.","body":[{"h":"검색 CASE와 단순 CASE","t":"검색 CASE는 `CASE WHEN score > 60 THEN '합격' END`처럼 각 WHEN에 조건식을 쓴다. 단순 CASE는 `CASE 표현식 WHEN 값 THEN ...`으로 한 표현식을 여러 값과 등호 비교한다. 둘 다 `END`로 끝난다."},{"h":"평가 순서와 ELSE","t":"WHEN들은 위에서부터 평가되어 처음 참인 가지의 값을 반환한다. 어떤 WHEN도 만족하지 않으면 `ELSE` 값을, ELSE가 없으면 NULL을 낸다. `IF(조건, 참값, 거짓값)`은 두 갈래일 때 간단한 대안이다."}],"code":{"c":"SELECT CASE\n         WHEN score >= 90 THEN 'A'\n         WHEN score >= 80 THEN 'B'\n         ELSE 'C'\n       END AS grade\nFROM students;","cap":"점수를 등급으로 분류하는 검색 CASE"},"key":["CASE는 `END`로 종료","일치 WHEN 없고 ELSE 없으면 NULL","단순 CASE는 표현식과 값을 등호 비교"]}},{"t":"IF 함수","q":[{"t":"choice","k":"IF","q":"IF(5 &gt; 3, 'Y', 'N') 의 결과는?","o":["Y","N","NULL","오류"],"a":0,"ex":"IF(조건, 참일때, 거짓일때) 구조입니다. 5 &gt; 3이 참이므로 'Y'."},{"t":"choice","k":"IF","q":"MySQL의 IF 함수 인자 순서로 옳은 것은?","o":["IF(조건, 참일때 값, 거짓일때 값)","IF(참일때 값, 조건, 거짓일때 값)","IF(거짓일때 값, 참일때 값, 조건)","IF(조건, 거짓일때 값, 참일때 값)"],"a":0,"ex":"첫 번째가 조건, 두 번째가 참일 때 값, 세 번째가 거짓일 때 값입니다."},{"t":"input","k":"빈칸","q":"IF(10 &gt; 20, 100, 200) 의 결과 숫자를 쓰세요.","a":["200"],"ex":"10 &gt; 20은 거짓이므로 세 번째 값 200이 반환됩니다."},{"t":"choice","k":"IF","q":"IF 함수와 같은 역할을 하는 표준 SQL 조건식은?","o":["CASE","WHERE","JOIN","GROUP BY"],"a":0,"ex":"IF는 MySQL 함수이며, 표준 SQL에서는 CASE로 같은 조건 분기를 표현합니다."}],"th":{"sum":"`CASE WHEN 조건 THEN 값 ... ELSE 값 END`로 조건에 따라 다른 값을 낸다. 맞는 `WHEN`이 없고 `ELSE`도 없으면 결과는 **NULL**이다.","body":[{"h":"검색 CASE와 단순 CASE","t":"검색 CASE는 `CASE WHEN score > 60 THEN '합격' END`처럼 각 WHEN에 조건식을 쓴다. 단순 CASE는 `CASE 표현식 WHEN 값 THEN ...`으로 한 표현식을 여러 값과 등호 비교한다. 둘 다 `END`로 끝난다."},{"h":"평가 순서와 ELSE","t":"WHEN들은 위에서부터 평가되어 처음 참인 가지의 값을 반환한다. 어떤 WHEN도 만족하지 않으면 `ELSE` 값을, ELSE가 없으면 NULL을 낸다. `IF(조건, 참값, 거짓값)`은 두 갈래일 때 간단한 대안이다."}],"code":{"c":"SELECT CASE\n         WHEN score >= 90 THEN 'A'\n         WHEN score >= 80 THEN 'B'\n         ELSE 'C'\n       END AS grade\nFROM students;","cap":"점수를 등급으로 분류하는 검색 CASE"},"key":["CASE는 `END`로 종료","일치 WHEN 없고 ELSE 없으면 NULL","단순 CASE는 표현식과 값을 등호 비교"]}}]},{"t":"NULL 처리","l":[{"t":"COALESCE","q":[{"t":"choice","k":"NULL","q":"COALESCE(NULL, NULL, 'A', 'B') 의 결과는?","o":["A","B","NULL","AB"],"a":0,"ex":"COALESCE는 인자들 중 처음으로 NULL이 아닌 값을 반환합니다. 여기서는 'A'."},{"t":"input","k":"빈칸","q":"COALESCE(NULL, NULL, 10) 의 결과 숫자를 쓰세요.","a":["10"],"ex":"처음 두 값이 NULL이므로 NULL이 아닌 10이 반환됩니다."}],"th":{"sum":"`COALESCE`는 인자를 왼쪽부터 보아 **첫 번째 NULL이 아닌 값**을 돌려준다. 모두 NULL이면 NULL이다.","body":[{"h":"COALESCE","t":"`COALESCE(NULL, NULL, 'A', 'B')`→'A', `COALESCE(NULL, 5)`→5다. 인자를 여러 개 받을 수 있고 표준 SQL 함수라 이식성이 좋다. `COALESCE(salary, 0)`은 급여가 NULL이면 0으로 대체한다는 뜻."},{"h":"IFNULL / NVL과 집계","t":"`IFNULL(a, b)`(MySQL)와 `NVL(a, b)`(Oracle)는 인자가 두 개인 COALESCE와 같다. `IFNULL(NULL,'X')`→'X'. 참고로 `SUM`/`AVG` 같은 집계는 NULL을 무시하고 계산하며, `COUNT(컬럼)`도 NULL을 세지 않는다."}],"code":{"c":"SELECT COALESCE(salary, 0) AS pay,\n       IFNULL(nickname, 'N/A') AS nick\nFROM users;","cap":"NULL을 기본값으로 대체"},"key":["`COALESCE`=첫 non-NULL 값, 다인자 가능","`IFNULL`/`NVL`=2인자 버전","집계 함수는 NULL을 무시"]}},{"t":"IFNULL / NVL","q":[{"t":"choice","k":"NULL","q":"IFNULL(NULL, 'X') 의 결과는?","o":["X","NULL","0","오류"],"a":0,"ex":"IFNULL(값, 대체값)은 첫 값이 NULL이면 대체값을 반환합니다. 결과는 'X'."},{"t":"input","k":"빈칸","q":"Oracle에서 IFNULL과 같은 역할을 하는 함수 이름은? (함수 이름만)","a":["NVL"],"ex":"Oracle에서는 NVL(값, 대체값)을 사용합니다. MySQL의 IFNULL과 같은 역할입니다."}],"th":{"sum":"`COALESCE`는 인자를 왼쪽부터 보아 **첫 번째 NULL이 아닌 값**을 돌려준다. 모두 NULL이면 NULL이다.","body":[{"h":"COALESCE","t":"`COALESCE(NULL, NULL, 'A', 'B')`→'A', `COALESCE(NULL, 5)`→5다. 인자를 여러 개 받을 수 있고 표준 SQL 함수라 이식성이 좋다. `COALESCE(salary, 0)`은 급여가 NULL이면 0으로 대체한다는 뜻."},{"h":"IFNULL / NVL과 집계","t":"`IFNULL(a, b)`(MySQL)와 `NVL(a, b)`(Oracle)는 인자가 두 개인 COALESCE와 같다. `IFNULL(NULL,'X')`→'X'. 참고로 `SUM`/`AVG` 같은 집계는 NULL을 무시하고 계산하며, `COUNT(컬럼)`도 NULL을 세지 않는다."}],"code":{"c":"SELECT COALESCE(salary, 0) AS pay,\n       IFNULL(nickname, 'N/A') AS nick\nFROM users;","cap":"NULL을 기본값으로 대체"},"key":["`COALESCE`=첫 non-NULL 값, 다인자 가능","`IFNULL`/`NVL`=2인자 버전","집계 함수는 NULL을 무시"]}},{"t":"NULL과 집계","q":[{"t":"choice","k":"집계","q":"col 값이 [10, NULL, 20, 30] 일 때 AVG(col) 의 결과는?","o":["20","15","60","NULL"],"a":0,"ex":"AVG는 NULL을 제외하고 계산합니다. (10+20+30)/3 = 20."},{"t":"input","k":"빈칸","q":"col 값이 [5, NULL, 15] 일 때 SUM(col) 의 결과 숫자를 쓰세요.","a":["20"],"ex":"SUM은 NULL을 무시하고 더합니다. 5 + 15 = 20."},{"t":"choice","k":"NULL","q":"값이 NULL인지 확인하는 올바른 조건은?","o":["col IS NULL","col = NULL","col == NULL","col NULL()"],"a":0,"ex":"NULL 비교는 = 이 아니라 IS NULL을 사용합니다. = NULL은 항상 참이 되지 않습니다."},{"t":"choice","k":"집계","q":"col 값이 [1, 2, NULL, 4, NULL] 일 때 COUNT(col) 의 결과는?","o":["3","5","2","4"],"a":0,"ex":"COUNT(col)은 NULL을 제외한 값의 개수를 셉니다. NULL 2개를 빼면 3."}],"th":{"sum":"`COALESCE`는 인자를 왼쪽부터 보아 **첫 번째 NULL이 아닌 값**을 돌려준다. 모두 NULL이면 NULL이다.","body":[{"h":"COALESCE","t":"`COALESCE(NULL, NULL, 'A', 'B')`→'A', `COALESCE(NULL, 5)`→5다. 인자를 여러 개 받을 수 있고 표준 SQL 함수라 이식성이 좋다. `COALESCE(salary, 0)`은 급여가 NULL이면 0으로 대체한다는 뜻."},{"h":"IFNULL / NVL과 집계","t":"`IFNULL(a, b)`(MySQL)와 `NVL(a, b)`(Oracle)는 인자가 두 개인 COALESCE와 같다. `IFNULL(NULL,'X')`→'X'. 참고로 `SUM`/`AVG` 같은 집계는 NULL을 무시하고 계산하며, `COUNT(컬럼)`도 NULL을 세지 않는다."}],"code":{"c":"SELECT COALESCE(salary, 0) AS pay,\n       IFNULL(nickname, 'N/A') AS nick\nFROM users;","cap":"NULL을 기본값으로 대체"},"key":["`COALESCE`=첫 non-NULL 값, 다인자 가능","`IFNULL`/`NVL`=2인자 버전","집계 함수는 NULL을 무시"]}}]},{"t":"윈도우 함수와 CTE","l":[{"t":"ROW_NUMBER · RANK · DENSE_RANK","q":[{"t":"choice","k":"RANK 값","q":"점수 90, 90, 80을 내림차순 정렬해 RANK()를 매길 때, 세 번째 행(80점)의 RANK 값은?","code":"SELECT score,\n       RANK() OVER (ORDER BY score DESC) AS rnk\nFROM scores;","o":["2","3","1","4"],"a":1,"ex":"RANK는 동점자에게 같은 순위를 주고 그 다음 순위는 동점자 수만큼 건너뛴다. 90,90은 모두 1위이고 다음은 2가 아니라 3이 된다."},{"t":"choice","k":"DENSE_RANK 값","q":"같은 데이터(90, 90, 80 내림차순)에서 DENSE_RANK()를 쓰면 세 번째 행(80점)의 값은?","code":"SELECT score,\n       DENSE_RANK() OVER (ORDER BY score DESC) AS drnk\nFROM scores;","o":["3","2","1","4"],"a":1,"ex":"DENSE_RANK는 동점을 같은 순위로 처리하되 gap을 만들지 않는다. 90,90=1, 80=2가 된다. RANK가 3을 주는 것과 대비된다."},{"t":"input","k":"gap 만드는 함수","q":"동점자에게 같은 순위를 주고 그 뒤에 gap을 만들어 1, 1, 3 형태의 순위를 생성하는 윈도우 함수 이름은? (함수명만)","a":["RANK","RANK()"],"ex":"RANK()는 동점 뒤 순위를 건너뛴다(1,1,3). DENSE_RANK()는 건너뛰지 않는다(1,1,2)."}],"th":{"sum":"윈도우 함수는 `OVER(PARTITION BY ... ORDER BY ...)`로 그룹 안 순위·번호를 매긴다. `RANK`는 동점 뒤 **gap**을, `DENSE_RANK`는 gap 없이, `ROW_NUMBER`는 무조건 유일 번호를 준다.","body":[{"h":"세 순위 함수의 차이","t":"90,90,80을 내림차순 매기면 `RANK`는 1,1,3(동점 뒤 3), `DENSE_RANK`는 1,1,2(gap 없음), `ROW_NUMBER`는 1,2,3(동점도 임의로 구분)이다. 부서별로 동점 무시하고 정확히 한 명만 뽑으려면 `ROW_NUMBER`가 적합하다."},{"h":"PARTITION BY와 CTE","t":"`PARTITION BY`는 그룹을 나눠 각 그룹 안에서 순위를 초기화하고, `ORDER BY`가 순위 기준이다. `WITH 이름 AS (...)` CTE는 복잡한 쿼리를 이름 붙인 임시 결과로 쪼개 가독성을 높이며, 윈도우 함수 결과를 다시 필터링할 때 자주 함께 쓴다."}],"code":{"c":"WITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept\n                            ORDER BY salary DESC) AS rn\n  FROM emp\n)\nSELECT * FROM ranked WHERE rn = 1;","cap":"부서별 급여 1위 한 명씩 추출"},"key":["RANK=gap 있음(1,1,3), DENSE_RANK=gap 없음(1,1,2)","ROW_NUMBER=항상 유일 번호, 한 명만 뽑기에 적합","CTE(`WITH`)로 윈도우 결과를 재필터"]}},{"t":"OVER(PARTITION BY … ORDER BY …)","q":[{"t":"input","k":"이전 행 참조","q":"정렬된 파티션에서 '이전 행'의 값을 가져오는 윈도우 함수 이름은? (함수명만)","a":["LAG","LAG()"],"ex":"이전 행은 LAG, 다음 행은 LEAD로 참조한다."},{"t":"choice","k":"LAG 첫 행","q":"LAG(salary, 1) OVER (ORDER BY hire_date)에서 정렬상 가장 첫 행의 결과 값은?","o":["0","NULL","자기 자신의 salary","에러"],"a":1,"ex":"첫 행은 참조할 이전 행이 없으므로 기본값 NULL이 반환된다. 세 번째 인자로 기본값을 지정할 수 있다."}],"th":{"sum":"윈도우 함수는 `OVER(PARTITION BY ... ORDER BY ...)`로 그룹 안 순위·번호를 매긴다. `RANK`는 동점 뒤 **gap**을, `DENSE_RANK`는 gap 없이, `ROW_NUMBER`는 무조건 유일 번호를 준다.","body":[{"h":"세 순위 함수의 차이","t":"90,90,80을 내림차순 매기면 `RANK`는 1,1,3(동점 뒤 3), `DENSE_RANK`는 1,1,2(gap 없음), `ROW_NUMBER`는 1,2,3(동점도 임의로 구분)이다. 부서별로 동점 무시하고 정확히 한 명만 뽑으려면 `ROW_NUMBER`가 적합하다."},{"h":"PARTITION BY와 CTE","t":"`PARTITION BY`는 그룹을 나눠 각 그룹 안에서 순위를 초기화하고, `ORDER BY`가 순위 기준이다. `WITH 이름 AS (...)` CTE는 복잡한 쿼리를 이름 붙인 임시 결과로 쪼개 가독성을 높이며, 윈도우 함수 결과를 다시 필터링할 때 자주 함께 쓴다."}],"code":{"c":"WITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept\n                            ORDER BY salary DESC) AS rn\n  FROM emp\n)\nSELECT * FROM ranked WHERE rn = 1;","cap":"부서별 급여 1위 한 명씩 추출"},"key":["RANK=gap 있음(1,1,3), DENSE_RANK=gap 없음(1,1,2)","ROW_NUMBER=항상 유일 번호, 한 명만 뽑기에 적합","CTE(`WITH`)로 윈도우 결과를 재필터"]}},{"t":"CTE (WITH 절)","q":[{"t":"input","k":"CTE 키워드","q":"CTE를 정의할 때 쿼리 앞에 쓰는 키워드는? (한 단어)","a":["WITH"],"ex":"CTE는 WITH cte_name AS ( ... ) 형태로 정의한다."},{"t":"choice","k":"CTE 특징","q":"CTE의 장점에 대한 설명으로 옳은 것은?","o":["항상 서브쿼리보다 실행 성능이 빠르다","복잡한 쿼리를 논리적 단계로 나눠 가독성을 높이고 재귀를 지원한다","JOIN을 완전히 대체하는 문법이다","집계 함수를 사용할 수 없다"],"a":1,"ex":"CTE의 핵심 가치는 가독성/구조화와 재귀 지원이다. 성능은 옵티마이저가 인라인/구체화를 어떻게 처리하느냐에 달려 있어 '항상 빠르다'는 틀렸다."}],"th":{"sum":"윈도우 함수는 `OVER(PARTITION BY ... ORDER BY ...)`로 그룹 안 순위·번호를 매긴다. `RANK`는 동점 뒤 **gap**을, `DENSE_RANK`는 gap 없이, `ROW_NUMBER`는 무조건 유일 번호를 준다.","body":[{"h":"세 순위 함수의 차이","t":"90,90,80을 내림차순 매기면 `RANK`는 1,1,3(동점 뒤 3), `DENSE_RANK`는 1,1,2(gap 없음), `ROW_NUMBER`는 1,2,3(동점도 임의로 구분)이다. 부서별로 동점 무시하고 정확히 한 명만 뽑으려면 `ROW_NUMBER`가 적합하다."},{"h":"PARTITION BY와 CTE","t":"`PARTITION BY`는 그룹을 나눠 각 그룹 안에서 순위를 초기화하고, `ORDER BY`가 순위 기준이다. `WITH 이름 AS (...)` CTE는 복잡한 쿼리를 이름 붙인 임시 결과로 쪼개 가독성을 높이며, 윈도우 함수 결과를 다시 필터링할 때 자주 함께 쓴다."}],"code":{"c":"WITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept\n                            ORDER BY salary DESC) AS rn\n  FROM emp\n)\nSELECT * FROM ranked WHERE rn = 1;","cap":"부서별 급여 1위 한 명씩 추출"},"key":["RANK=gap 있음(1,1,3), DENSE_RANK=gap 없음(1,1,2)","ROW_NUMBER=항상 유일 번호, 한 명만 뽑기에 적합","CTE(`WITH`)로 윈도우 결과를 재필터"]}}]},{"t":"서브쿼리와 NULL의 함정","l":[{"t":"NOT IN + NULL 함정과 EXISTS","q":[{"t":"choice","k":"NOT IN + NULL","q":"dept 테이블의 dept_id 컬럼에 NULL이 하나라도 포함되어 있을 때, 다음 쿼리의 결과는?","code":"SELECT *\nFROM emp\nWHERE dept_id NOT IN (SELECT dept_id FROM dept);","o":["emp의 모든 행","dept에 없는 dept_id를 가진 emp 행","빈 결과(0행)","런타임 에러"],"a":2,"ex":"서브쿼리 결과에 NULL이 있으면 NOT IN은 사실상 어떤 행도 TRUE가 되지 못해 0행을 반환한다. 대표적인 함정이다."},{"t":"input","k":"대체 구문","q":"NULL이 포함될 수 있는 'NOT IN (서브쿼리)'를 가장 안전하게 대체하는 구문은? (2단어)","a":["NOT EXISTS"],"ex":"NOT EXISTS로 대체하면 NULL 함정과 무관하게 의도한 '차집합' 결과를 얻는다."}],"th":{"sum":"`NOT IN (서브쿼리)`에 **NULL이 하나라도** 있으면 결과가 통째로 비어버린다. 이 함정은 `NOT EXISTS`로 안전하게 대체한다.","body":[{"h":"NOT IN + NULL 함정","t":"`x NOT IN (1, NULL)`은 `x<>1 AND x<>NULL`로 풀리는데 `x<>NULL`은 UNKNOWN이라 전체가 참이 될 수 없다. 그래서 목록에 NULL이 있으면 어떤 x도 통과하지 못해 0행이 된다. `NOT EXISTS`는 NULL을 이런 식으로 전파하지 않아 안전하다."},{"h":"상관 서브쿼리","t":"상관(correlated) 서브쿼리는 바깥 쿼리의 각 행 값을 참조해 행마다 다시 평가된다. `NOT EXISTS (SELECT 1 FROM ... WHERE 안쪽.키 = 바깥.키)` 형태로 '~에 없는' 조건을 표현한다. 정렬 시 NULL은 DB마다 맨 앞/뒤 위치가 다르니 `NULLS FIRST/LAST`를 확인한다."}],"code":{"c":"SELECT e.name\nFROM emp e\nWHERE NOT EXISTS (\n  SELECT 1 FROM dept d\n  WHERE d.dept_id = e.dept_id\n);","cap":"NULL 함정 없이 '부서에 없는 직원' 조회"},"key":["`NOT IN`에 NULL → 결과 0행","원인: `x<>NULL`이 UNKNOWN이라 참 불가","안전한 대체는 `NOT EXISTS`(2단어)"]}},{"t":"상관 서브쿼리","q":[{"t":"choice","k":"부서 평균 비교","q":"다음 상관 서브쿼리는 무엇을 반환하는가?","code":"SELECT e.name\nFROM emp e\nWHERE e.salary &gt; (SELECT AVG(e2.salary)\n                  FROM emp e2\n                  WHERE e2.dept_id = e.dept_id);","o":["전체 평균보다 급여가 높은 직원","자기 부서 평균보다 급여가 높은 직원","각 부서에서 급여가 가장 높은 직원","문법 에러"],"a":1,"ex":"내부 서브쿼리가 e.dept_id를 참조해 '해당 직원과 같은 부서'의 평균을 계산하므로, 자기 부서 평균 초과 직원이 나온다."},{"t":"input","k":"참조 방향","q":"상관 서브쿼리에서 내부 쿼리는 바깥쪽(___) 쿼리의 컬럼을 참조한다. 빈칸에 들어갈 말은?","a":["outer","외부","바깥"],"ex":"내부(inner) 서브쿼리가 외부(outer) 쿼리의 컬럼을 참조하기 때문에 'correlated(상관)'라 불린다."}],"th":{"sum":"`NOT IN (서브쿼리)`에 **NULL이 하나라도** 있으면 결과가 통째로 비어버린다. 이 함정은 `NOT EXISTS`로 안전하게 대체한다.","body":[{"h":"NOT IN + NULL 함정","t":"`x NOT IN (1, NULL)`은 `x<>1 AND x<>NULL`로 풀리는데 `x<>NULL`은 UNKNOWN이라 전체가 참이 될 수 없다. 그래서 목록에 NULL이 있으면 어떤 x도 통과하지 못해 0행이 된다. `NOT EXISTS`는 NULL을 이런 식으로 전파하지 않아 안전하다."},{"h":"상관 서브쿼리","t":"상관(correlated) 서브쿼리는 바깥 쿼리의 각 행 값을 참조해 행마다 다시 평가된다. `NOT EXISTS (SELECT 1 FROM ... WHERE 안쪽.키 = 바깥.키)` 형태로 '~에 없는' 조건을 표현한다. 정렬 시 NULL은 DB마다 맨 앞/뒤 위치가 다르니 `NULLS FIRST/LAST`를 확인한다."}],"code":{"c":"SELECT e.name\nFROM emp e\nWHERE NOT EXISTS (\n  SELECT 1 FROM dept d\n  WHERE d.dept_id = e.dept_id\n);","cap":"NULL 함정 없이 '부서에 없는 직원' 조회"},"key":["`NOT IN`에 NULL → 결과 0행","원인: `x<>NULL`이 UNKNOWN이라 참 불가","안전한 대체는 `NOT EXISTS`(2단어)"]}},{"t":"NULL 비교와 ORDER BY","q":[{"t":"choice","k":"NULL 판별","q":"어떤 컬럼이 NULL인지 판별하는 올바른 방법은?","o":["col = NULL","col IS NULL","col == NULL","col EQUALS NULL"],"a":1,"ex":"= NULL은 항상 UNKNOWN이라 행을 걸러낼 수 없다. 반드시 IS NULL / IS NOT NULL을 사용한다."},{"t":"choice","k":"부등호와 NULL","q":"WHERE col &lt;&gt; 'A' 조건은 col이 NULL인 행을 결과에 포함하는가?","o":["예, NULL 행도 포함된다","아니오, NULL 행은 제외된다","런타임 에러가 난다","NULL을 'A'로 간주한다"],"a":1,"ex":"NULL &lt;&gt; 'A'는 UNKNOWN이므로 WHERE 조건을 통과하지 못한다. NULL 행까지 원하면 OR col IS NULL을 추가해야 한다."},{"t":"input","k":"NULL 정렬 위치","q":"ORDER BY에서 NULL을 명시적으로 맨 마지막에 정렬시키는 절은? (2단어)","a":["NULLS LAST"],"ex":"표준 SQL은 NULLS FIRST / NULLS LAST로 NULL의 정렬 위치를 명시할 수 있다. 미지정 시 위치는 구현에 따라 다르다."}],"th":{"sum":"`NOT IN (서브쿼리)`에 **NULL이 하나라도** 있으면 결과가 통째로 비어버린다. 이 함정은 `NOT EXISTS`로 안전하게 대체한다.","body":[{"h":"NOT IN + NULL 함정","t":"`x NOT IN (1, NULL)`은 `x<>1 AND x<>NULL`로 풀리는데 `x<>NULL`은 UNKNOWN이라 전체가 참이 될 수 없다. 그래서 목록에 NULL이 있으면 어떤 x도 통과하지 못해 0행이 된다. `NOT EXISTS`는 NULL을 이런 식으로 전파하지 않아 안전하다."},{"h":"상관 서브쿼리","t":"상관(correlated) 서브쿼리는 바깥 쿼리의 각 행 값을 참조해 행마다 다시 평가된다. `NOT EXISTS (SELECT 1 FROM ... WHERE 안쪽.키 = 바깥.키)` 형태로 '~에 없는' 조건을 표현한다. 정렬 시 NULL은 DB마다 맨 앞/뒤 위치가 다르니 `NULLS FIRST/LAST`를 확인한다."}],"code":{"c":"SELECT e.name\nFROM emp e\nWHERE NOT EXISTS (\n  SELECT 1 FROM dept d\n  WHERE d.dept_id = e.dept_id\n);","cap":"NULL 함정 없이 '부서에 없는 직원' 조회"},"key":["`NOT IN`에 NULL → 결과 0행","원인: `x<>NULL`이 UNKNOWN이라 참 불가","안전한 대체는 `NOT EXISTS`(2단어)"]}}]},{"t":"JOIN과 집계의 함정","l":[{"t":"WHERE vs HAVING · GROUP BY 규칙","q":[{"t":"choice","k":"WHERE에 집계","q":"WHERE 절에 집계 함수를 직접 쓸 수 있는가?","o":["예, WHERE COUNT(*) &gt; 5 처럼 쓸 수 있다","아니오, 집계 결과에 대한 조건은 HAVING을 사용해야 한다","예, GROUP BY 없이도 가능하다","WHERE와 HAVING은 완전히 동일하다"],"a":1,"ex":"WHERE는 그룹화/집계 이전 단계에서 평가되므로 집계 함수를 쓸 수 없다. 집계 결과 조건은 HAVING을 쓴다."},{"t":"input","k":"집계 조건 절","q":"집계 결과값을 기준으로 그룹을 필터링할 때 사용하는 절은? (한 단어)","a":["HAVING"],"ex":"집계 후 그룹 필터는 HAVING, 집계 전 행 필터는 WHERE다."}],"th":{"sum":"`WHERE`는 그룹 전(개별 행), `HAVING`은 그룹 후(집계값)에 건다. 1:N 조인은 **행이 뻥튀기**되어 `SUM`/`COUNT`가 부풀 수 있다.","body":[{"h":"WHERE vs HAVING","t":"`WHERE`엔 집계 함수를 쓸 수 없다. 집계 결과로 그룹을 거르려면 `HAVING COUNT(*) > 10`처럼 쓴다. 표준 SQL에서 GROUP BY하면 SELECT의 비집계 컬럼은 모두 GROUP BY에 있어야 유효하다."},{"h":"조인 중복과 LEFT JOIN 함정","t":"orders(1):order_items(N)를 조인하면 주문이 아이템 수만큼 복제돼 `SUM(o.amount)`가 과다 계산된다. 해결은 order_items 쪽을 미리 집계한 서브쿼리와 조인해 1:1로 만드는 것이다(`SUM(DISTINCT)`는 같은 금액이 여러 주문에 있으면 값을 잃으므로 해결책이 아니다). 반면 '주문 건수'처럼 개수를 셀 때는 `COUNT(DISTINCT o.id)`로 복제된 행을 걸러 정확한 값을 얻는다. 또 LEFT JOIN 후 오른쪽 테이블 컬럼을 `WHERE`에 걸면 매칭 실패 행(NULL)이 제거돼 사실상 INNER JOIN이 된다."}],"code":{"c":"SELECT dept, COUNT(*) AS n\nFROM emp\nGROUP BY dept\nHAVING COUNT(*) > 10;","cap":"집계값 기준 필터는 HAVING"},"key":["`WHERE`엔 집계 불가, 집계 필터는 `HAVING`","1:N 조인은 행 뻥튀기 → 합계는 사전 집계 조인, 건수는 `COUNT(DISTINCT)`","LEFT JOIN 후 우측 컬럼 WHERE=INNER화"]}},{"t":"JOIN 중복 · LEFT JOIN 함정 · self-join","q":[{"t":"choice","k":"LEFT JOIN 보존","q":"위 상황에서 진짜 LEFT JOIN(주문 없는 고객 보존)을 유지하려면 status 조건을 어디로 옮겨야 하는가?","o":["ON 절로 옮긴다","HAVING 절로 옮긴다","GROUP BY로 옮긴다","그대로 WHERE에 둔다"],"a":0,"ex":"조건을 ON 절로 옮기면 조인 단계에서만 적용되어 매칭 안 된 왼쪽 행은 NULL로 보존된다. WHERE에 두면 그 보존 행이 제거된다."},{"t":"input","k":"자기 조인 명칭","q":"하나의 테이블을 자기 자신과 조인하는 것을 무슨 조인이라 하는가? (한 단어)","a":["self","셀프","자체"],"ex":"동일 테이블에 별칭 두 개를 부여해 조인하는 것을 self-join(자기 조인)이라 한다."}],"th":{"sum":"`WHERE`는 그룹 전(개별 행), `HAVING`은 그룹 후(집계값)에 건다. 1:N 조인은 **행이 뻥튀기**되어 `SUM`/`COUNT`가 부풀 수 있다.","body":[{"h":"WHERE vs HAVING","t":"`WHERE`엔 집계 함수를 쓸 수 없다. 집계 결과로 그룹을 거르려면 `HAVING COUNT(*) > 10`처럼 쓴다. 표준 SQL에서 GROUP BY하면 SELECT의 비집계 컬럼은 모두 GROUP BY에 있어야 유효하다."},{"h":"조인 중복과 LEFT JOIN 함정","t":"orders(1):order_items(N)를 조인하면 주문이 아이템 수만큼 복제돼 `SUM(o.amount)`가 과다 계산된다. 해결은 order_items 쪽을 미리 집계한 서브쿼리와 조인해 1:1로 만드는 것이다(`SUM(DISTINCT)`는 같은 금액이 여러 주문에 있으면 값을 잃으므로 해결책이 아니다). 반면 '주문 건수'처럼 개수를 셀 때는 `COUNT(DISTINCT o.id)`로 복제된 행을 걸러 정확한 값을 얻는다. 또 LEFT JOIN 후 오른쪽 테이블 컬럼을 `WHERE`에 걸면 매칭 실패 행(NULL)이 제거돼 사실상 INNER JOIN이 된다."}],"code":{"c":"SELECT dept, COUNT(*) AS n\nFROM emp\nGROUP BY dept\nHAVING COUNT(*) > 10;","cap":"집계값 기준 필터는 HAVING"},"key":["`WHERE`엔 집계 불가, 집계 필터는 `HAVING`","1:N 조인은 행 뻥튀기 → 합계는 사전 집계 조인, 건수는 `COUNT(DISTINCT)`","LEFT JOIN 후 우측 컬럼 WHERE=INNER화"]}},{"t":"COUNT(DISTINCT) · 조건부 집계","q":[{"t":"choice","k":"COUNT 등가 함정","q":"SUM(CASE WHEN status='paid' THEN 1 ELSE 0 END)와 결과가 동일한 것은?","o":["COUNT(CASE WHEN status='paid' THEN 1 ELSE 0 END)","COUNT(CASE WHEN status='paid' THEN 1 END)","COUNT(*)","COUNT(status)"],"a":1,"ex":"COUNT는 NULL이 아닌 값을 센다. ELSE를 생략하면 미해당 행은 NULL이 되어 세지 않는다. 반대로 ELSE 0을 두면 0도 비-NULL이라 전체 행이 세져 함정이 된다."},{"t":"input","k":"고유 값 세기","q":"한 컬럼의 서로 다른 값만 세려면 COUNT(____ col) 형태로 쓴다. 빈칸의 키워드는? (한 단어)","a":["DISTINCT"],"ex":"COUNT(DISTINCT col)로 중복을 제거한 고유 값 개수를 센다."}],"th":{"sum":"`WHERE`는 그룹 전(개별 행), `HAVING`은 그룹 후(집계값)에 건다. 1:N 조인은 **행이 뻥튀기**되어 `SUM`/`COUNT`가 부풀 수 있다.","body":[{"h":"WHERE vs HAVING","t":"`WHERE`엔 집계 함수를 쓸 수 없다. 집계 결과로 그룹을 거르려면 `HAVING COUNT(*) > 10`처럼 쓴다. 표준 SQL에서 GROUP BY하면 SELECT의 비집계 컬럼은 모두 GROUP BY에 있어야 유효하다."},{"h":"조인 중복과 LEFT JOIN 함정","t":"orders(1):order_items(N)를 조인하면 주문이 아이템 수만큼 복제돼 `SUM(o.amount)`가 과다 계산된다. 해결은 order_items 쪽을 미리 집계한 서브쿼리와 조인해 1:1로 만드는 것이다(`SUM(DISTINCT)`는 같은 금액이 여러 주문에 있으면 값을 잃으므로 해결책이 아니다). 반면 '주문 건수'처럼 개수를 셀 때는 `COUNT(DISTINCT o.id)`로 복제된 행을 걸러 정확한 값을 얻는다. 또 LEFT JOIN 후 오른쪽 테이블 컬럼을 `WHERE`에 걸면 매칭 실패 행(NULL)이 제거돼 사실상 INNER JOIN이 된다."}],"code":{"c":"SELECT dept, COUNT(*) AS n\nFROM emp\nGROUP BY dept\nHAVING COUNT(*) > 10;","cap":"집계값 기준 필터는 HAVING"},"key":["`WHERE`엔 집계 불가, 집계 필터는 `HAVING`","1:N 조인은 행 뻥튀기 → 합계는 사전 집계 조인, 건수는 `COUNT(DISTINCT)`","LEFT JOIN 후 우측 컬럼 WHERE=INNER화"]}}]},{"t":"날짜·시간 함수","l":[{"t":"현재 날짜와 시간","q":[{"t":"choice","k":"CURDATE","q":"시간 없이 오늘 날짜만 얻는 함수는?","o":["CURDATE()","NOW()","CURTIME()","YEAR()"],"a":0,"ex":"CURDATE()는 시간 부분 없이 날짜(YYYY-MM-DD)만 반환합니다. CURRENT_DATE도 동일합니다."},{"t":"input","k":"현재 시각","q":"현재 시각(HH:MM:SS)만 반환하는 MySQL 함수를 쓰세요.","a":["CURTIME","CURTIME()","CURRENT_TIME"],"ex":"CURTIME()은 시:분:초만 반환하며 CURRENT_TIME과 같습니다."},{"t":"choice","k":"CURRENT_DATE","q":"CURRENT_DATE와 같은 결과를 반환하는 함수는?","o":["CURDATE()","CURTIME()","NOW()","TIME()"],"a":0,"ex":"CURRENT_DATE는 CURDATE()의 동의어로, 둘 다 오늘 날짜만 반환합니다."},{"t":"choice","k":"NOW vs SYSDATE","q":"MySQL에서 한 쿼리 안에 여러 번 호출해도 같은 값을 반환하는 함수는?","o":["NOW()","SYSDATE()","RAND()","UUID()"],"a":0,"ex":"MySQL의 NOW()는 문장 시작 시각으로 고정되지만, SYSDATE()는 호출되는 실제 시각을 반환해 값이 달라질 수 있습니다."}],"th":{"sum":"`NOW()`는 날짜+시간, `CURRENT_DATE`는 날짜만, `CURRENT_TIME`은 시각만 준다. `YEAR`/`MONTH`/`DAY`로 요소를 정수로 추출한다.","body":[{"h":"현재 날짜·시간","t":"`NOW()`는 'YYYY-MM-DD HH:MM:SS'를 반환하고 한 쿼리 안에서 여러 번 불러도 같은 값을 준다(문장 시작 시각 고정). 날짜만은 `CURDATE()`/`CURRENT_DATE`, 시각만은 `CURTIME()`/`CURRENT_TIME`이다."},{"h":"요소 추출과 계산","t":"`YEAR('2026-07-21')`→2026, `MONTH(...)`→월 정수, `DAY(...)`→일이다. 날짜 계산은 `DATE_ADD(날짜, INTERVAL 7 DAY)`나 `DATEDIFF(a, b)`로 하며 결과는 일 수 차이다."}],"code":{"c":"SELECT NOW(),\n       CURRENT_DATE,\n       YEAR('2026-07-21') AS y,\n       MONTH('2026-07-21') AS m;","cap":"현재값과 연·월 추출"},"key":["`NOW()`=날짜+시간, `CURRENT_DATE`=날짜만","요소 추출: `YEAR`/`MONTH`/`DAY`","`NOW()`는 한 쿼리 내 값 고정"]}},{"t":"날짜 요소 추출","q":[{"t":"input","k":"월 추출","q":"날짜에서 '월'을 정수로 추출하는 함수 이름을 쓰세요.","a":["MONTH","MONTH()"],"ex":"MONTH('2026-07-21')은 7을 반환합니다."},{"t":"choice","k":"DAYOFWEEK","q":"MySQL DAYOFWEEK()에서 일요일에 해당하는 값은?","o":["1","2","7","0"],"a":0,"ex":"MySQL DAYOFWEEK()는 일요일=1 ~ 토요일=7을 반환합니다. (WEEKDAY()는 월요일=0 기준으로 다릅니다.)"}],"th":{"sum":"`NOW()`는 날짜+시간, `CURRENT_DATE`는 날짜만, `CURRENT_TIME`은 시각만 준다. `YEAR`/`MONTH`/`DAY`로 요소를 정수로 추출한다.","body":[{"h":"현재 날짜·시간","t":"`NOW()`는 'YYYY-MM-DD HH:MM:SS'를 반환하고 한 쿼리 안에서 여러 번 불러도 같은 값을 준다(문장 시작 시각 고정). 날짜만은 `CURDATE()`/`CURRENT_DATE`, 시각만은 `CURTIME()`/`CURRENT_TIME`이다."},{"h":"요소 추출과 계산","t":"`YEAR('2026-07-21')`→2026, `MONTH(...)`→월 정수, `DAY(...)`→일이다. 날짜 계산은 `DATE_ADD(날짜, INTERVAL 7 DAY)`나 `DATEDIFF(a, b)`로 하며 결과는 일 수 차이다."}],"code":{"c":"SELECT NOW(),\n       CURRENT_DATE,\n       YEAR('2026-07-21') AS y,\n       MONTH('2026-07-21') AS m;","cap":"현재값과 연·월 추출"},"key":["`NOW()`=날짜+시간, `CURRENT_DATE`=날짜만","요소 추출: `YEAR`/`MONTH`/`DAY`","`NOW()`는 한 쿼리 내 값 고정"]}},{"t":"날짜 계산","q":[{"t":"choice","k":"DATEDIFF","q":"MySQL에서 DATEDIFF('2026-07-21','2026-07-01')의 결과는?","o":["20","21","19","-20"],"a":0,"ex":"MySQL DATEDIFF(a, b)는 a - b를 일수로 반환합니다. 21 - 1 = 20일."},{"t":"input","k":"INTERVAL","q":"오늘로부터 7일 후: DATE_ADD(CURDATE(), INTERVAL 7 ___). 빈칸의 단위 키워드는?","a":["DAY","DAYS"],"ex":"INTERVAL 7 DAY는 7일을 의미합니다. MONTH, YEAR, HOUR 등도 사용 가능합니다."},{"t":"choice","k":"DATE_SUB","q":"날짜에서 일정 기간을 빼는 함수는?","o":["DATE_SUB()","DATE_MINUS()","DATE_DIFF()","MINUS()"],"a":0,"ex":"DATE_SUB(d, INTERVAL 3 DAY)는 3일을 뺍니다. DATE_ADD에 음수 INTERVAL을 써도 됩니다."}],"th":{"sum":"`NOW()`는 날짜+시간, `CURRENT_DATE`는 날짜만, `CURRENT_TIME`은 시각만 준다. `YEAR`/`MONTH`/`DAY`로 요소를 정수로 추출한다.","body":[{"h":"현재 날짜·시간","t":"`NOW()`는 'YYYY-MM-DD HH:MM:SS'를 반환하고 한 쿼리 안에서 여러 번 불러도 같은 값을 준다(문장 시작 시각 고정). 날짜만은 `CURDATE()`/`CURRENT_DATE`, 시각만은 `CURTIME()`/`CURRENT_TIME`이다."},{"h":"요소 추출과 계산","t":"`YEAR('2026-07-21')`→2026, `MONTH(...)`→월 정수, `DAY(...)`→일이다. 날짜 계산은 `DATE_ADD(날짜, INTERVAL 7 DAY)`나 `DATEDIFF(a, b)`로 하며 결과는 일 수 차이다."}],"code":{"c":"SELECT NOW(),\n       CURRENT_DATE,\n       YEAR('2026-07-21') AS y,\n       MONTH('2026-07-21') AS m;","cap":"현재값과 연·월 추출"},"key":["`NOW()`=날짜+시간, `CURRENT_DATE`=날짜만","요소 추출: `YEAR`/`MONTH`/`DAY`","`NOW()`는 한 쿼리 내 값 고정"]}}]},{"t":"트랜잭션과 무결성","l":[{"t":"트랜잭션 기본","q":[{"t":"choice","k":"시작","q":"새 트랜잭션을 시작하는 표준 명령은?","o":["START TRANSACTION","START TABLE","OPEN TRANSACTION","TRANSACTION BEGIN"],"a":0,"ex":"START TRANSACTION(또는 BEGIN)으로 트랜잭션을 시작합니다."},{"t":"input","k":"SAVEPOINT","q":"트랜잭션 중간에 부분 롤백 지점을 만드는 명령 키워드는?","a":["SAVEPOINT"],"ex":"SAVEPOINT name으로 지점을 만들고 ROLLBACK TO name으로 그 지점까지만 되돌립니다."}],"th":{"sum":"트랜잭션은 `BEGIN`으로 시작, `COMMIT`으로 영구 저장, `ROLLBACK`으로 되돌린다. **ACID**로 원자성·일관성·격리성·지속성을 보장한다.","body":[{"h":"트랜잭션 명령","t":"`BEGIN`(또는 `START TRANSACTION`)으로 시작하고 `COMMIT`으로 확정, `ROLLBACK`으로 전부 취소한다. `SAVEPOINT`로 중간 지점을 만들어 부분 롤백할 수 있다. COMMIT 전에 ROLLBACK하면 그 트랜잭션의 변경이 모두 사라진다. AUTOCOMMIT이 켜져 있으면 각 문장이 즉시 커밋된다."},{"h":"ACID","t":"A(원자성)는 전부 성공 아니면 전부 취소를 보장한다. C(일관성)는 제약조건 등 규칙을 지켜 유효한 상태만 남긴다. I(격리성)는 동시 트랜잭션이 서로 간섭하지 않게, D(지속성)는 커밋된 결과가 장애에도 유지되게 한다. 제약조건(PK/FK/CHECK)은 C를 지탱한다."}],"code":{"c":"BEGIN;\nUPDATE account SET bal = bal - 100 WHERE id = 1;\nUPDATE account SET bal = bal + 100 WHERE id = 2;\nCOMMIT;","cap":"계좌 이체를 하나의 원자적 트랜잭션으로"},"key":["시작 `BEGIN`, 확정 `COMMIT`, 취소 `ROLLBACK`","부분 롤백 지점은 `SAVEPOINT`","A=전부 성공/전부 실패, C=제약 준수"]}},{"t":"ACID 원칙","q":[{"t":"choice","k":"A","q":"ACID의 A(Atomicity)가 보장하는 것은?","o":["작업이 모두 실행되거나 모두 취소된다","항상 최신 값을 읽는다","작업 순서가 유지된다","병렬 실행을 보장한다"],"a":0,"ex":"원자성은 트랜잭션이 전부 성공하거나 전부 실패(취소)함을 보장합니다. 계좌이체 중 일부만 반영되는 일을 막습니다."},{"t":"choice","k":"Dirty Read","q":"아직 커밋되지 않은 다른 트랜잭션의 변경을 읽는 현상은?","o":["Dirty Read","Phantom Row","Deadlock","Rollback"],"a":0,"ex":"Dirty Read는 커밋되지 않은 데이터를 읽는 문제로, READ COMMITTED 이상의 격리 수준에서 방지됩니다."}],"th":{"sum":"트랜잭션은 `BEGIN`으로 시작, `COMMIT`으로 영구 저장, `ROLLBACK`으로 되돌린다. **ACID**로 원자성·일관성·격리성·지속성을 보장한다.","body":[{"h":"트랜잭션 명령","t":"`BEGIN`(또는 `START TRANSACTION`)으로 시작하고 `COMMIT`으로 확정, `ROLLBACK`으로 전부 취소한다. `SAVEPOINT`로 중간 지점을 만들어 부분 롤백할 수 있다. COMMIT 전에 ROLLBACK하면 그 트랜잭션의 변경이 모두 사라진다. AUTOCOMMIT이 켜져 있으면 각 문장이 즉시 커밋된다."},{"h":"ACID","t":"A(원자성)는 전부 성공 아니면 전부 취소를 보장한다. C(일관성)는 제약조건 등 규칙을 지켜 유효한 상태만 남긴다. I(격리성)는 동시 트랜잭션이 서로 간섭하지 않게, D(지속성)는 커밋된 결과가 장애에도 유지되게 한다. 제약조건(PK/FK/CHECK)은 C를 지탱한다."}],"code":{"c":"BEGIN;\nUPDATE account SET bal = bal - 100 WHERE id = 1;\nUPDATE account SET bal = bal + 100 WHERE id = 2;\nCOMMIT;","cap":"계좌 이체를 하나의 원자적 트랜잭션으로"},"key":["시작 `BEGIN`, 확정 `COMMIT`, 취소 `ROLLBACK`","부분 롤백 지점은 `SAVEPOINT`","A=전부 성공/전부 실패, C=제약 준수"]}},{"t":"제약조건과 AUTOCOMMIT","q":[{"t":"choice","k":"PK 위반","q":"기본키(PK) 값이 중복되는 INSERT를 실행하면?","o":["제약 위반 오류가 발생한다","자동으로 덮어쓴다","NULL로 저장된다","조용히 무시된다"],"a":0,"ex":"기본키는 중복을 허용하지 않으므로 중복 삽입 시 오류가 발생하고 해당 문장은 실패합니다."},{"t":"choice","k":"FK 위반","q":"FOREIGN KEY가 참조하는 부모 행을 삭제하려 하면(기본 RESTRICT)?","o":["삭제가 거부된다","자식 행이 자동 삭제된다","자식 값이 NULL이 된다","무시되고 삭제된다"],"a":0,"ex":"기본 동작(RESTRICT/NO ACTION)에서는 참조하는 자식 행이 있으면 부모 행 삭제가 거부됩니다."},{"t":"input","k":"NOT NULL","q":"컬럼에 NULL 저장을 허용하지 않는 제약조건 이름은?","a":["NOT NULL"],"ex":"NOT NULL 제약은 해당 컬럼에 값이 반드시 있어야 함을 강제합니다."},{"t":"choice","k":"CASCADE","q":"부모 행 삭제 시 자식 행도 함께 삭제되게 하는 옵션은?","o":["ON DELETE CASCADE","ON DELETE RESTRICT","ON DELETE SET DEFAULT","ON UPDATE CASCADE"],"a":0,"ex":"ON DELETE CASCADE는 부모 행이 삭제될 때 이를 참조하는 자식 행도 자동으로 삭제합니다."}],"th":{"sum":"트랜잭션은 `BEGIN`으로 시작, `COMMIT`으로 영구 저장, `ROLLBACK`으로 되돌린다. **ACID**로 원자성·일관성·격리성·지속성을 보장한다.","body":[{"h":"트랜잭션 명령","t":"`BEGIN`(또는 `START TRANSACTION`)으로 시작하고 `COMMIT`으로 확정, `ROLLBACK`으로 전부 취소한다. `SAVEPOINT`로 중간 지점을 만들어 부분 롤백할 수 있다. COMMIT 전에 ROLLBACK하면 그 트랜잭션의 변경이 모두 사라진다. AUTOCOMMIT이 켜져 있으면 각 문장이 즉시 커밋된다."},{"h":"ACID","t":"A(원자성)는 전부 성공 아니면 전부 취소를 보장한다. C(일관성)는 제약조건 등 규칙을 지켜 유효한 상태만 남긴다. I(격리성)는 동시 트랜잭션이 서로 간섭하지 않게, D(지속성)는 커밋된 결과가 장애에도 유지되게 한다. 제약조건(PK/FK/CHECK)은 C를 지탱한다."}],"code":{"c":"BEGIN;\nUPDATE account SET bal = bal - 100 WHERE id = 1;\nUPDATE account SET bal = bal + 100 WHERE id = 2;\nCOMMIT;","cap":"계좌 이체를 하나의 원자적 트랜잭션으로"},"key":["시작 `BEGIN`, 확정 `COMMIT`, 취소 `ROLLBACK`","부분 롤백 지점은 `SAVEPOINT`","A=전부 성공/전부 실패, C=제약 준수"]}}]},{"t":"형변환","l":[{"t":"CAST 기본","q":[{"t":"choice","k":"문법","q":"CAST의 올바른 문법은?","o":["CAST(expr AS type)","CAST(expr, type)","CAST(type, expr)","CONVERT(expr AS type)"],"a":0,"ex":"표준 SQL의 형변환 문법은 CAST(표현식 AS 대상타입)입니다."},{"t":"input","k":"함수명","q":"표준 SQL에서 값을 다른 타입으로 변환하는 함수 이름은?","a":["CAST"],"ex":"CAST는 표준 SQL에 정의된 형변환 함수로 대부분의 DBMS가 지원합니다."},{"t":"choice","k":"문자→숫자","q":"MySQL에서 CAST('123' AS SIGNED)의 결과는?","o":["정수 123","문자열 '123'","오류","NULL"],"a":0,"ex":"문자열 '123'을 정수 123으로 변환합니다. MySQL은 정수 변환에 SIGNED/UNSIGNED 키워드를 씁니다."},{"t":"choice","k":"정수 타입","q":"MySQL의 CAST에서 정수로 변환할 때 쓰는 타입 키워드는?","o":["SIGNED","INT","NUMBER","INTEGER4"],"a":0,"ex":"MySQL의 CAST 대상 타입으로는 SIGNED/UNSIGNED를 씁니다. INT는 전통적으로 CAST 대상 타입으로 허용되지 않습니다."}],"th":{"sum":"표준 형변환은 `CAST(값 AS 타입)`이다. MySQL 정수는 `SIGNED`, 문자는 `CHAR`를 쓰고 `CONVERT`도 지원한다.","body":[{"h":"CAST 문법","t":"`CAST('123' AS SIGNED)`→123(정수), `CAST(123 AS CHAR)`→'123'(문자열)이다. 표준 SQL의 변환 함수는 `CAST`이며 MySQL에서 정수 타입 키워드는 `SIGNED`(부호 있음)/`UNSIGNED`다. DECIMAL, DATE 등으로도 변환할 수 있다."},{"h":"CONVERT와 암묵적 변환","t":"MySQL의 `CONVERT(값, 타입)` 형태로도 변환하고, 문자셋 변경은 `CONVERT(값 USING utf8mb4)`처럼 `USING` 절을 쓴다. 비교·연산 시 타입이 다르면 DB가 암묵적으로 변환하는데, 이때 문자열과 숫자를 섞으면 예상 밖 결과나 인덱스 미사용이 생길 수 있으니 명시적 변환이 안전하다."}],"code":{"c":"SELECT CAST('123' AS SIGNED) AS n,\n       CAST(123 AS CHAR) AS s,\n       CONVERT('가' USING utf8mb4) AS c;","cap":"표준 CAST와 MySQL CONVERT/문자셋 변환"},"key":["표준은 `CAST(값 AS 타입)`","MySQL 정수=`SIGNED`, 문자=`CHAR`","문자셋 변경은 `CONVERT(값 USING ...)`"]}},{"t":"CONVERT와 데이터 타입","q":[{"t":"choice","k":"MySQL CONVERT","q":"MySQL의 CONVERT()로 타입 변환을 하는 올바른 문법은?","o":["CONVERT(expr, type)","CONVERT(type, expr)","CONVERT(expr AS type)","CONVERT(expr TO type)"],"a":0,"ex":"MySQL은 CONVERT(expr, type) 형식입니다. SQL Server는 CONVERT(type, expr, style)로 인자 순서가 다릅니다."},{"t":"choice","k":"문자셋","q":"MySQL에서 문자셋을 바꿀 때 CONVERT에 쓰는 절은?","o":["USING","CHARSET","AS","WITH"],"a":0,"ex":"CONVERT(str USING utf8mb4)처럼 USING 절로 문자셋을 변환합니다."},{"t":"input","k":"날짜 변환","q":"CAST('2026-07-21' AS ___)로 날짜 타입으로 바꿀 때 빈칸의 타입은?","a":["DATE"],"ex":"CAST('2026-07-21' AS DATE)는 문자열을 DATE 타입으로 변환합니다."}],"th":{"sum":"표준 형변환은 `CAST(값 AS 타입)`이다. MySQL 정수는 `SIGNED`, 문자는 `CHAR`를 쓰고 `CONVERT`도 지원한다.","body":[{"h":"CAST 문법","t":"`CAST('123' AS SIGNED)`→123(정수), `CAST(123 AS CHAR)`→'123'(문자열)이다. 표준 SQL의 변환 함수는 `CAST`이며 MySQL에서 정수 타입 키워드는 `SIGNED`(부호 있음)/`UNSIGNED`다. DECIMAL, DATE 등으로도 변환할 수 있다."},{"h":"CONVERT와 암묵적 변환","t":"MySQL의 `CONVERT(값, 타입)` 형태로도 변환하고, 문자셋 변경은 `CONVERT(값 USING utf8mb4)`처럼 `USING` 절을 쓴다. 비교·연산 시 타입이 다르면 DB가 암묵적으로 변환하는데, 이때 문자열과 숫자를 섞으면 예상 밖 결과나 인덱스 미사용이 생길 수 있으니 명시적 변환이 안전하다."}],"code":{"c":"SELECT CAST('123' AS SIGNED) AS n,\n       CAST(123 AS CHAR) AS s,\n       CONVERT('가' USING utf8mb4) AS c;","cap":"표준 CAST와 MySQL CONVERT/문자셋 변환"},"key":["표준은 `CAST(값 AS 타입)`","MySQL 정수=`SIGNED`, 문자=`CHAR`","문자셋 변경은 `CONVERT(값 USING ...)`"]}},{"t":"암묵적 형변환","q":[{"t":"choice","k":"문자+숫자","q":"MySQL에서 '10' + 5의 결과는?","o":["15","'105'","오류","NULL"],"a":0,"ex":"MySQL에서 +는 산술 연산자이므로 '10'이 숫자 10으로 암묵 변환되어 15가 됩니다. (문자열 연결에는 CONCAT을 씁니다.)"},{"t":"choice","k":"CONCAT","q":"MySQL에서 CONCAT('10', 5)의 결과는?","o":["'105'","15","오류","'10 5'"],"a":0,"ex":"CONCAT은 인자를 문자열로 변환해 이어붙이므로 '105'가 됩니다."}],"th":{"sum":"표준 형변환은 `CAST(값 AS 타입)`이다. MySQL 정수는 `SIGNED`, 문자는 `CHAR`를 쓰고 `CONVERT`도 지원한다.","body":[{"h":"CAST 문법","t":"`CAST('123' AS SIGNED)`→123(정수), `CAST(123 AS CHAR)`→'123'(문자열)이다. 표준 SQL의 변환 함수는 `CAST`이며 MySQL에서 정수 타입 키워드는 `SIGNED`(부호 있음)/`UNSIGNED`다. DECIMAL, DATE 등으로도 변환할 수 있다."},{"h":"CONVERT와 암묵적 변환","t":"MySQL의 `CONVERT(값, 타입)` 형태로도 변환하고, 문자셋 변경은 `CONVERT(값 USING utf8mb4)`처럼 `USING` 절을 쓴다. 비교·연산 시 타입이 다르면 DB가 암묵적으로 변환하는데, 이때 문자열과 숫자를 섞으면 예상 밖 결과나 인덱스 미사용이 생길 수 있으니 명시적 변환이 안전하다."}],"code":{"c":"SELECT CAST('123' AS SIGNED) AS n,\n       CAST(123 AS CHAR) AS s,\n       CONVERT('가' USING utf8mb4) AS c;","cap":"표준 CAST와 MySQL CONVERT/문자셋 변환"},"key":["표준은 `CAST(값 AS 타입)`","MySQL 정수=`SIGNED`, 문자=`CHAR`","문자셋 변경은 `CONVERT(값 USING ...)`"]}}]},{"t":"고급 윈도우 함수","l":[{"t":"LEAD와 LAG","q":[{"t":"choice","k":"LAG 첫 행","q":"ORDER BY로 정렬된 파티션에서 LAG(amount, 1)을 사용할 때, 파티션의 '첫 번째' 행이 반환하는 값은?","o":["첫 행의 amount","0","NULL","마지막 행의 amount"],"a":2,"ex":"LAG는 현재 행보다 offset만큼 '앞선' 행을 참조합니다. 첫 행에는 이전 행이 없으므로 기본값을 지정하지 않으면 NULL을 반환합니다. LEAD는 반대로 마지막 행이 NULL이 됩니다."},{"t":"input","k":"LAG 값 계산","q":"아래 데이터를 mon 순으로 정렬했을 때 mon='Mar' 행에서 LAG(rev, 1)이 반환하는 값은?","code":"-- rows (mon, rev)\n-- Jan, 100\n-- Feb, 150\n-- Mar, 120\n-- Apr, 200\nLAG(rev, 1) OVER (ORDER BY mon)","a":["150"],"ex":"LAG(rev,1)은 바로 이전 행(Feb)의 rev 값을 가져옵니다. Mar의 이전 행은 Feb이고 그 rev는 150입니다. Mar 자신의 120이 아님에 주의하세요."},{"t":"input","k":"전월 대비 증감","q":"위와 동일한 데이터에서 rev - LAG(rev, 1) OVER (ORDER BY mon)로 계산한 Mar 행의 결과값은? (부호 포함)","a":["-30"],"ex":"Mar의 rev(120)에서 이전 행 Feb의 rev(150)를 빼면 120 - 150 = -30 입니다. 전월 대비 감소를 나타내는 전형적인 delta 계산 패턴입니다."},{"t":"choice","k":"LEAD offset 2","q":"총 5개 행이 ORDER BY로 정렬되어 있을 때 LEAD(x, 2)가 NULL을 반환하는 행은 몇 개인가?","o":["0개","1개","2개","3개"],"a":2,"ex":"LEAD(x, 2)는 2행 뒤를 참조합니다. 마지막 두 행(4번째, 5번째)은 각각 6번째, 7번째 행이 없으므로 NULL이 됩니다. 따라서 2개 행이 NULL입니다."}],"th":{"sum":"`LAG`/`LEAD`는 정렬된 파티션에서 이전·다음 행 값을 당겨온다. 경계에서 값이 없으면 **NULL**(또는 지정한 기본값). `NTILE(n)`은 행을 n개 버킷으로 균등 분배한다.","body":[{"h":"LAG / LEAD","t":"`LAG(amount,1)`은 이전 행 값을 주며 첫 행엔 이전이 없어 NULL이다. `LAG(price,2,0)`의 세 번째 인자 0은 값이 없을 때 대신 쓸 기본값이다. `LEAD(x,2)`는 두 칸 뒤를 보므로 5개 행이면 뒤 2개 행이 NULL을 낸다. 전월 대비는 `rev - LAG(rev,1) OVER(ORDER BY mon)`로 구한다."},{"h":"NTILE와 프레임","t":"`NTILE(4)`로 10개 행을 나누면 나머지를 앞 버킷부터 채워 3,3,2,2가 되고, 7번째 행은 세 번째 버킷에 든다. 누적합은 프레임 `ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`로 `SUM(x) OVER(ORDER BY ...)`처럼 만든다. `FIRST_VALUE`/`LAST_VALUE`는 프레임 범위에 민감하니 주의."}],"code":{"c":"SELECT mon, rev,\n       rev - LAG(rev, 1) OVER (ORDER BY mon) AS diff,\n       NTILE(4) OVER (ORDER BY rev) AS bucket\nFROM monthly;","cap":"전월 대비 증감과 4분위 버킷"},"key":["`LAG`/`LEAD` 경계값은 NULL, 3번째 인자로 기본값 지정","`NTILE(n)`은 나머지를 앞 버킷부터 배분","누적합은 프레임 UNBOUNDED PRECEDING~CURRENT ROW"]}},{"t":"NTILE와 FIRST/LAST_VALUE","q":[{"t":"choice","k":"NTILE 분배","q":"10개 행에 NTILE(4)를 적용하면 각 버킷의 행 개수는 어떻게 분배되는가?","o":["2,2,2,4","3,3,2,2","2,2,3,3","4,2,2,2"],"a":1,"ex":"NTILE(n)은 행을 균등 분할하되 나누어떨어지지 않으면 '앞쪽' 버킷에 여분을 배정합니다. 10/4 = 2 나머지 2이므로 앞의 두 버킷이 3개, 뒤의 두 버킷이 2개가 되어 3,3,2,2 입니다."},{"t":"input","k":"NTILE 버킷 번호","q":"10개 행을 NTILE(4)로 나눌 때(3,3,2,2 분배), 정렬 순서상 7번째 행이 속하는 버킷 번호는?","a":["3"],"ex":"버킷1은 1~3행, 버킷2는 4~6행, 버킷3은 7~8행, 버킷4는 9~10행입니다. 따라서 7번째 행은 버킷 3에 속합니다."},{"t":"choice","k":"LAST_VALUE 교정","q":"파티션 '전체'의 마지막 값을 얻으려면 LAST_VALUE에 어떤 프레임을 명시해야 하는가?","o":["ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW","ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING","ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING","RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING"],"a":2,"ex":"프레임을 ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING로 확장해야 파티션의 처음부터 끝까지 전체를 보므로 진짜 마지막 값을 얻습니다. FIRST_VALUE는 기본 프레임으로도 문제없습니다."},{"t":"input","k":"FIRST_VALUE 결과","q":"hire 오름차순 파티션에서 FIRST_VALUE(name) OVER (PARTITION BY dept ORDER BY hire)는 각 부서의 어떤 사원 이름을 반환하는가? '가장 먼저' 또는 '가장 나중' 중 하나로 답하시오.","a":["가장 먼저","가장먼저"],"ex":"FIRST_VALUE는 프레임의 첫 행 값을 반환하며, 기본 프레임의 시작은 UNBOUNDED PRECEDING입니다. hire 오름차순이므로 각 부서에서 가장 먼저 입사한(가장 오래된) 사원의 이름을 돌려줍니다."}],"th":{"sum":"`LAG`/`LEAD`는 정렬된 파티션에서 이전·다음 행 값을 당겨온다. 경계에서 값이 없으면 **NULL**(또는 지정한 기본값). `NTILE(n)`은 행을 n개 버킷으로 균등 분배한다.","body":[{"h":"LAG / LEAD","t":"`LAG(amount,1)`은 이전 행 값을 주며 첫 행엔 이전이 없어 NULL이다. `LAG(price,2,0)`의 세 번째 인자 0은 값이 없을 때 대신 쓸 기본값이다. `LEAD(x,2)`는 두 칸 뒤를 보므로 5개 행이면 뒤 2개 행이 NULL을 낸다. 전월 대비는 `rev - LAG(rev,1) OVER(ORDER BY mon)`로 구한다."},{"h":"NTILE와 프레임","t":"`NTILE(4)`로 10개 행을 나누면 나머지를 앞 버킷부터 채워 3,3,2,2가 되고, 7번째 행은 세 번째 버킷에 든다. 누적합은 프레임 `ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`로 `SUM(x) OVER(ORDER BY ...)`처럼 만든다. `FIRST_VALUE`/`LAST_VALUE`는 프레임 범위에 민감하니 주의."}],"code":{"c":"SELECT mon, rev,\n       rev - LAG(rev, 1) OVER (ORDER BY mon) AS diff,\n       NTILE(4) OVER (ORDER BY rev) AS bucket\nFROM monthly;","cap":"전월 대비 증감과 4분위 버킷"},"key":["`LAG`/`LEAD` 경계값은 NULL, 3번째 인자로 기본값 지정","`NTILE(n)`은 나머지를 앞 버킷부터 배분","누적합은 프레임 UNBOUNDED PRECEDING~CURRENT ROW"]}},{"t":"프레임과 누적합","q":[{"t":"input","k":"누적합 계산","q":"amount를 day 순으로 정렬하고 SUM(amount) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)로 누적합을 구할 때, 3번째 행(70)의 누적합 값은?","code":"-- rows in day order (amount)\n-- 50\n-- 30\n-- 70\n-- 20\nSUM(amount) OVER (\n  ORDER BY day\n  ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)","a":["150"],"ex":"누적합은 첫 행부터 현재 행까지 더합니다. 50 + 30 + 70 = 150. (4번째 행은 170이 됩니다.)"},{"t":"input","k":"RANGE 동점 합","q":"val 순으로 정렬된 (10, 10, 20) 세 행에서 SUM(val) OVER (ORDER BY val RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)를 계산할 때 '첫 번째' 행(val=10)의 결과값은?","a":["20"],"ex":"RANGE는 같은 정렬값 peer를 모두 포함합니다. 첫 행의 val=10과 두 번째 행의 val=10은 peer이므로 프레임에 둘 다 들어가 10 + 10 = 20입니다. ROWS였다면 10이었을 것입니다."},{"t":"choice","k":"PARTITION과 프레임","q":"PARTITION BY dept와 프레임의 상호작용에 대해 옳은 것은?","o":["프레임은 테이블 전체에 걸쳐 확장될 수 있다","프레임(UNBOUNDED PRECEDING 포함)은 현재 파티션 경계를 넘지 못한다","PARTITION BY가 있으면 프레임을 쓸 수 없다","프레임은 파티션을 무시하고 항상 전역이다"],"a":1,"ex":"프레임은 항상 현재 행이 속한 파티션 내부에서만 계산됩니다. UNBOUNDED PRECEDING은 '파티션의' 첫 행을, UNBOUNDED FOLLOWING은 '파티션의' 마지막 행을 의미하며 다른 파티션으로 넘어가지 않습니다."}],"th":{"sum":"`LAG`/`LEAD`는 정렬된 파티션에서 이전·다음 행 값을 당겨온다. 경계에서 값이 없으면 **NULL**(또는 지정한 기본값). `NTILE(n)`은 행을 n개 버킷으로 균등 분배한다.","body":[{"h":"LAG / LEAD","t":"`LAG(amount,1)`은 이전 행 값을 주며 첫 행엔 이전이 없어 NULL이다. `LAG(price,2,0)`의 세 번째 인자 0은 값이 없을 때 대신 쓸 기본값이다. `LEAD(x,2)`는 두 칸 뒤를 보므로 5개 행이면 뒤 2개 행이 NULL을 낸다. 전월 대비는 `rev - LAG(rev,1) OVER(ORDER BY mon)`로 구한다."},{"h":"NTILE와 프레임","t":"`NTILE(4)`로 10개 행을 나누면 나머지를 앞 버킷부터 채워 3,3,2,2가 되고, 7번째 행은 세 번째 버킷에 든다. 누적합은 프레임 `ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`로 `SUM(x) OVER(ORDER BY ...)`처럼 만든다. `FIRST_VALUE`/`LAST_VALUE`는 프레임 범위에 민감하니 주의."}],"code":{"c":"SELECT mon, rev,\n       rev - LAG(rev, 1) OVER (ORDER BY mon) AS diff,\n       NTILE(4) OVER (ORDER BY rev) AS bucket\nFROM monthly;","cap":"전월 대비 증감과 4분위 버킷"},"key":["`LAG`/`LEAD` 경계값은 NULL, 3번째 인자로 기본값 지정","`NTILE(n)`은 나머지를 앞 버킷부터 배분","누적합은 프레임 UNBOUNDED PRECEDING~CURRENT ROW"]}}]},{"t":"재귀 CTE","l":[{"t":"재귀 CTE 구조","q":[{"t":"input","k":"필수 키워드","q":"재귀 CTE를 정의할 때 WITH 다음에 반드시 붙여야 하는 키워드는? (영어 대문자)","a":["RECURSIVE"],"ex":"표준 SQL과 PostgreSQL, MySQL 8+에서는 WITH RECURSIVE로 선언해야 재귀가 허용됩니다. (참고: SQL Server는 RECURSIVE 키워드 없이 재귀 CTE를 지원합니다.)"},{"t":"choice","k":"두 멤버 구조","q":"재귀 CTE는 두 부분을 UNION ALL로 결합합니다. 올바른 구성은?","o":["앵커 멤버 + 재귀 멤버","SELECT + INSERT","인덱스 멤버 + 스캔 멤버","앵커 멤버 두 개"],"a":0,"ex":"재귀 CTE는 초기 결과를 만드는 앵커 멤버(anchor)와, CTE 자기 자신을 참조하며 반복 실행되는 재귀 멤버(recursive member)를 UNION ALL로 결합한 구조입니다."},{"t":"choice","k":"자기참조 위치","q":"재귀 CTE에서 CTE 이름 자기 자신을 FROM 절에서 참조하는 부분은?","o":["앵커 멤버","재귀 멤버","최종 외부 SELECT","WHERE 절"],"a":1,"ex":"재귀 멤버만이 정의 중인 CTE 자신을 FROM에 참조합니다. 앵커 멤버는 자기 자신을 참조하지 않고 시작 집합만 생성합니다."}],"th":{"sum":"재귀 CTE는 `WITH RECURSIVE`로 선언하고, **앵커(초기)** 와 **재귀** 부분을 `UNION ALL`로 결합해 종료 조건까지 반복한다.","body":[{"h":"구조","t":"`WITH RECURSIVE`가 필수 키워드다. 앵커 SELECT가 시작 행을 만들고, 재귀 SELECT가 CTE 이름 자신을 `FROM`에서 참조해 직전 결과에 이어붙인다. 이 둘을 `UNION ALL`로 잇고, 재귀 부분의 `WHERE`가 종료 조건을 준다."},{"h":"종료와 UNION 차이","t":"종료 조건(예: `WHERE n < 5`)이 없으면 무한 루프에 빠진다. `UNION ALL` 대신 `UNION`을 쓰면 매 단계 중복 제거가 일어나 같은 값이 반복되면 자연히 멈출 수 있지만 성능이 떨어진다. 계층(조직도) 탐색과 연속 숫자 생성이 대표 용도다."}],"code":{"c":"WITH RECURSIVE nums(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM nums WHERE n < 5\n)\nSELECT SUM(n) FROM nums;   -- 1..5 합계 = 15","cap":"1~5를 생성해 합계 구하는 재귀 CTE"},"key":["선언 키워드는 `WITH RECURSIVE`","앵커 + 재귀를 `UNION ALL`로 결합","종료 조건 없으면 무한 루프"]}},{"t":"숫자 생성과 계층 탐색","q":[{"t":"input","k":"행 개수","q":"아래 재귀 CTE가 생성하는 행의 총 개수는?","code":"WITH RECURSIVE nums(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM nums WHERE n &lt; 5\n)\nSELECT * FROM nums;","a":["5"],"ex":"앵커가 1을 만들고, 재귀가 n&lt;5인 동안 n+1을 추가합니다: 1,2,3,4,5. n=5는 조건 n&lt;5를 만족하지 못해 멈춥니다. 총 5개 행(1부터 5까지)이 생성됩니다."},{"t":"input","k":"합계 결과","q":"위 nums CTE에 대해 SELECT SUM(n) FROM nums; 의 결과값은?","a":["15"],"ex":"생성된 값은 1,2,3,4,5이며 합은 1+2+3+4+5 = 15입니다."},{"t":"choice","k":"계층 탐색","q":"employee(id, mgr_id) 테이블에서 특정 사원의 모든 하위(부하) 직원을 찾으려 할 때, 재귀 멤버의 JOIN 조건으로 옳은 것은?","o":["e.id = cte.mgr_id","e.mgr_id = cte.id","e.id = cte.id","e.mgr_id = cte.mgr_id"],"a":1,"ex":"하향(부하 방향) 탐색은 '현재까지 찾은 사원(cte.id)을 상사로 두는 직원(e.mgr_id)'을 이어붙입니다. 즉 e.mgr_id = cte.id 조건으로 한 단계 아래로 내려갑니다."}],"th":{"sum":"재귀 CTE는 `WITH RECURSIVE`로 선언하고, **앵커(초기)** 와 **재귀** 부분을 `UNION ALL`로 결합해 종료 조건까지 반복한다.","body":[{"h":"구조","t":"`WITH RECURSIVE`가 필수 키워드다. 앵커 SELECT가 시작 행을 만들고, 재귀 SELECT가 CTE 이름 자신을 `FROM`에서 참조해 직전 결과에 이어붙인다. 이 둘을 `UNION ALL`로 잇고, 재귀 부분의 `WHERE`가 종료 조건을 준다."},{"h":"종료와 UNION 차이","t":"종료 조건(예: `WHERE n < 5`)이 없으면 무한 루프에 빠진다. `UNION ALL` 대신 `UNION`을 쓰면 매 단계 중복 제거가 일어나 같은 값이 반복되면 자연히 멈출 수 있지만 성능이 떨어진다. 계층(조직도) 탐색과 연속 숫자 생성이 대표 용도다."}],"code":{"c":"WITH RECURSIVE nums(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM nums WHERE n < 5\n)\nSELECT SUM(n) FROM nums;   -- 1..5 합계 = 15","cap":"1~5를 생성해 합계 구하는 재귀 CTE"},"key":["선언 키워드는 `WITH RECURSIVE`","앵커 + 재귀를 `UNION ALL`로 결합","종료 조건 없으면 무한 루프"]}},{"t":"종료 조건과 무한루프","q":[{"t":"choice","k":"순환 데이터","q":"그래프에 순환(A→B→A)이 있는 데이터를 계층 탐색할 때 무한루프를 막는 방법으로 적절하지 '않은' 것은?","o":["방문 경로를 배열/문자열로 누적해 이미 방문한 노드면 제외","재귀 깊이(레벨) 상한을 WHERE로 설정","UNION(중복 제거)을 활용","ORDER BY를 추가해서 정렬"],"a":3,"ex":"ORDER BY는 최종 결과 정렬일 뿐 순환을 끊지 못합니다. 순환 방지는 방문 노드 추적, 깊이 상한, 또는 중복 제거(UNION) 등으로 해결합니다. PostgreSQL은 CYCLE 절도 제공합니다."},{"t":"choice","k":"깊이 한계","q":"MySQL 8+에서 재귀 반복 횟수의 기본 상한을 제어하는 설정은?","o":["max_recursion","cte_max_recursion_depth","recursion_limit","OPTION (MAXRECURSION)"],"a":1,"ex":"MySQL 8+는 시스템 변수 cte_max_recursion_depth(기본 1000)로 재귀 깊이를 제한합니다. SQL Server는 OPTION (MAXRECURSION n), PostgreSQL은 기본 깊이 제한이 없어 종료 조건 설계가 특히 중요합니다."},{"t":"input","k":"생성 최댓값","q":"WITH RECURSIVE t(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM t WHERE n &lt; 100)에서 t가 생성하는 n의 '최댓값'은?","a":["100"],"ex":"n=99일 때 조건(99&lt;100)이 참이라 100을 생성합니다. n=100은 조건(100&lt;100)이 거짓이라 더 생성하지 않습니다. 따라서 값은 1부터 100까지이며 최댓값은 100입니다."}],"th":{"sum":"재귀 CTE는 `WITH RECURSIVE`로 선언하고, **앵커(초기)** 와 **재귀** 부분을 `UNION ALL`로 결합해 종료 조건까지 반복한다.","body":[{"h":"구조","t":"`WITH RECURSIVE`가 필수 키워드다. 앵커 SELECT가 시작 행을 만들고, 재귀 SELECT가 CTE 이름 자신을 `FROM`에서 참조해 직전 결과에 이어붙인다. 이 둘을 `UNION ALL`로 잇고, 재귀 부분의 `WHERE`가 종료 조건을 준다."},{"h":"종료와 UNION 차이","t":"종료 조건(예: `WHERE n < 5`)이 없으면 무한 루프에 빠진다. `UNION ALL` 대신 `UNION`을 쓰면 매 단계 중복 제거가 일어나 같은 값이 반복되면 자연히 멈출 수 있지만 성능이 떨어진다. 계층(조직도) 탐색과 연속 숫자 생성이 대표 용도다."}],"code":{"c":"WITH RECURSIVE nums(n) AS (\n  SELECT 1\n  UNION ALL\n  SELECT n + 1 FROM nums WHERE n < 5\n)\nSELECT SUM(n) FROM nums;   -- 1..5 합계 = 15","cap":"1~5를 생성해 합계 구하는 재귀 CTE"},"key":["선언 키워드는 `WITH RECURSIVE`","앵커 + 재귀를 `UNION ALL`로 결합","종료 조건 없으면 무한 루프"]}}]},{"t":"인덱스와 실행계획","l":[{"t":"B-tree와 인덱스 활용 조건","q":[{"t":"choice","k":"함수 적용","q":"col에 일반 인덱스가 있을 때, 다음 중 그 인덱스를 '타지 못하는' 조건은?","o":["WHERE col = 100","WHERE col BETWEEN 10 AND 20","WHERE YEAR(col) = 2024","WHERE col &gt; 50"],"a":2,"ex":"인덱스 컬럼에 함수(YEAR(col))를 감싸면 인덱스에 저장된 원본 값 순서를 활용할 수 없어 인덱스를 못 탑니다. col &gt;= '2024-01-01' AND col &lt; '2025-01-01' 처럼 sargable하게 바꾸거나 함수 기반 인덱스를 만들어야 합니다."},{"t":"choice","k":"선행 와일드카드","q":"name에 B-tree 인덱스가 있을 때 인덱스 range scan을 '활용하지 못하는' LIKE 패턴은?","o":["LIKE 'kim%'","LIKE 'a%'","LIKE '%son'","LIKE 'park%'"],"a":2,"ex":"B-tree는 왼쪽부터 정렬된 접두사를 기준으로 탐색합니다. LIKE '%son'처럼 선행 와일드카드가 있으면 시작 접두사를 알 수 없어 range scan을 못 하고 전체 스캔에 가까워집니다. 접미 검색이 잦으면 역순 컬럼 인덱스 등을 고려합니다."},{"t":"input","k":"sargable 변환","q":"WHERE YEAR(order_date) = 2024 를 인덱스가 동작하도록 바꿀 때, 범위 조건의 '하한 경계' 날짜 리터럴은? (YYYY-MM-DD 형식)","a":["2024-01-01","'2024-01-01'"],"ex":"order_date &gt;= '2024-01-01' AND order_date &lt; '2025-01-01' 로 바꾸면 컬럼에 함수를 씌우지 않아 인덱스 range scan이 가능합니다. 하한 경계는 2024-01-01 입니다."}],"th":{"sum":"B-tree 인덱스는 등호·범위·정렬에 강하지만, 컬럼을 **함수로 감싸거나** 앞쪽 와일드카드 `LIKE '%x'`를 쓰면 못 탄다. 복합 인덱스는 **선두 컬럼부터** 써야 유효하다.","body":[{"h":"인덱스 활용 조건","t":"B-tree는 정렬 구조라 `=`, `<`, `>`, `BETWEEN`, `ORDER BY`, `LIKE 'seoul%'`(뒤쪽 와일드카드는 접두어가 고정이라 범위 스캔 가능)에 쓸 수 있다. 반면 `LIKE '%seoul'`(앞 와일드카드)이나 `WHERE YEAR(order_date)=2024`처럼 컬럼을 가공하면 인덱스를 못 탄다. 후자는 `order_date >= '2024-01-01' AND order_date < '2025-01-01'`로 바꾼다(하한 리터럴 2024-01-01)."},{"h":"복합 인덱스","t":"복합 인덱스 `(a,b,c)`는 왼쪽부터 연속으로 써야 효율적이다. `WHERE b=? AND c=?`처럼 선두 `a`가 없으면 잘 못 탄다. `(a,b)`에서 `a>10 AND b=5`면 `a`가 범위라 그 뒤 `b`는 인덱스로 좁히지 못한다(범위 컬럼 이후는 정렬이 깨짐)."}],"code":{"c":"-- 인덱스 타도록 함수 제거\nSELECT * FROM orders\nWHERE order_date >= '2024-01-01'\n  AND order_date <  '2025-01-01';","cap":"YEAR() 대신 범위 조건으로 B-tree 활용"},"key":["함수 감싼 컬럼·앞 와일드카드 `%x`는 인덱스 불가","`LIKE 'x%'`는 접두어 고정이라 범위 스캔 가능","복합 인덱스는 선두 컬럼부터, 범위 뒤 컬럼은 무력화"]}},{"t":"복합 인덱스와 커버링","q":[{"t":"choice","k":"leftmost","q":"복합 인덱스 (a, b, c)가 있을 때, 인덱스를 효율적으로 사용할 수 '없는' WHERE 조건은?","o":["WHERE a = 1","WHERE a = 1 AND b = 2","WHERE b = 2 AND c = 3","WHERE a = 1 AND b = 2 AND c = 3"],"a":2,"ex":"복합 인덱스는 leftmost prefix 규칙을 따릅니다. 선행 컬럼 a 없이 b, c만으로는 인덱스 시작점을 정할 수 없어 효율적으로 탈 수 없습니다. a가 조건에 포함되어야 인덱스를 활용합니다."},{"t":"choice","k":"커버링 이점","q":"커버링 인덱스가 성능상 유리한 핵심 이유는?","o":["인덱스가 자동으로 정렬되어서","테이블 랜덤 접근(row/bookmark lookup)을 제거해 I/O를 줄이므로","쓰기 성능이 빨라져서","NULL 처리가 빨라져서"],"a":1,"ex":"일반적으로 인덱스에서 원하는 행을 찾은 뒤 나머지 컬럼을 위해 테이블 본체를 다시 조회(row/bookmark lookup)합니다. 커버링 인덱스는 이 추가 접근을 없애 랜덤 I/O를 크게 줄입니다. MySQL EXPLAIN의 Extra에 'Using index'로 나타납니다."}],"th":{"sum":"B-tree 인덱스는 등호·범위·정렬에 강하지만, 컬럼을 **함수로 감싸거나** 앞쪽 와일드카드 `LIKE '%x'`를 쓰면 못 탄다. 복합 인덱스는 **선두 컬럼부터** 써야 유효하다.","body":[{"h":"인덱스 활용 조건","t":"B-tree는 정렬 구조라 `=`, `<`, `>`, `BETWEEN`, `ORDER BY`, `LIKE 'seoul%'`(뒤쪽 와일드카드는 접두어가 고정이라 범위 스캔 가능)에 쓸 수 있다. 반면 `LIKE '%seoul'`(앞 와일드카드)이나 `WHERE YEAR(order_date)=2024`처럼 컬럼을 가공하면 인덱스를 못 탄다. 후자는 `order_date >= '2024-01-01' AND order_date < '2025-01-01'`로 바꾼다(하한 리터럴 2024-01-01)."},{"h":"복합 인덱스","t":"복합 인덱스 `(a,b,c)`는 왼쪽부터 연속으로 써야 효율적이다. `WHERE b=? AND c=?`처럼 선두 `a`가 없으면 잘 못 탄다. `(a,b)`에서 `a>10 AND b=5`면 `a`가 범위라 그 뒤 `b`는 인덱스로 좁히지 못한다(범위 컬럼 이후는 정렬이 깨짐)."}],"code":{"c":"-- 인덱스 타도록 함수 제거\nSELECT * FROM orders\nWHERE order_date >= '2024-01-01'\n  AND order_date <  '2025-01-01';","cap":"YEAR() 대신 범위 조건으로 B-tree 활용"},"key":["함수 감싼 컬럼·앞 와일드카드 `%x`는 인덱스 불가","`LIKE 'x%'`는 접두어 고정이라 범위 스캔 가능","복합 인덱스는 선두 컬럼부터, 범위 뒤 컬럼은 무력화"]}},{"t":"EXPLAIN과 트레이드오프","q":[{"t":"choice","k":"풀스캔 신호","q":"MySQL EXPLAIN 결과에서 인덱스를 타지 못하고 풀 테이블 스캔이 일어남을 나타내는 type 값은?","o":["const","ref","range","ALL"],"a":3,"ex":"type=ALL은 풀 테이블 스캔을 의미하며 대개 튜닝 대상입니다. 좋은 순서는 대략 const &gt; eq_ref &gt; ref &gt; range &gt; index &gt; ALL 이며, 뒤로 갈수록 스캔량이 많아집니다."},{"t":"input","k":"Extra 표시","q":"MySQL EXPLAIN의 Extra 컬럼에서, 쿼리가 인덱스만으로 처리되어 테이블 접근이 없었음을(커버링 인덱스) 뜻하는 표현은?","a":["Using index","using index"],"ex":"Extra에 'Using index'가 표시되면 인덱스만으로 필요한 데이터를 모두 얻어 테이블 본체를 읽지 않은 커버링 인덱스 상황입니다. (참고: 'Using index condition'은 인덱스 컨디션 푸시다운으로 의미가 다릅니다.)"}],"th":{"sum":"B-tree 인덱스는 등호·범위·정렬에 강하지만, 컬럼을 **함수로 감싸거나** 앞쪽 와일드카드 `LIKE '%x'`를 쓰면 못 탄다. 복합 인덱스는 **선두 컬럼부터** 써야 유효하다.","body":[{"h":"인덱스 활용 조건","t":"B-tree는 정렬 구조라 `=`, `<`, `>`, `BETWEEN`, `ORDER BY`, `LIKE 'seoul%'`(뒤쪽 와일드카드는 접두어가 고정이라 범위 스캔 가능)에 쓸 수 있다. 반면 `LIKE '%seoul'`(앞 와일드카드)이나 `WHERE YEAR(order_date)=2024`처럼 컬럼을 가공하면 인덱스를 못 탄다. 후자는 `order_date >= '2024-01-01' AND order_date < '2025-01-01'`로 바꾼다(하한 리터럴 2024-01-01)."},{"h":"복합 인덱스","t":"복합 인덱스 `(a,b,c)`는 왼쪽부터 연속으로 써야 효율적이다. `WHERE b=? AND c=?`처럼 선두 `a`가 없으면 잘 못 탄다. `(a,b)`에서 `a>10 AND b=5`면 `a`가 범위라 그 뒤 `b`는 인덱스로 좁히지 못한다(범위 컬럼 이후는 정렬이 깨짐)."}],"code":{"c":"-- 인덱스 타도록 함수 제거\nSELECT * FROM orders\nWHERE order_date >= '2024-01-01'\n  AND order_date <  '2025-01-01';","cap":"YEAR() 대신 범위 조건으로 B-tree 활용"},"key":["함수 감싼 컬럼·앞 와일드카드 `%x`는 인덱스 불가","`LIKE 'x%'`는 접두어 고정이라 범위 스캔 가능","복합 인덱스는 선두 컬럼부터, 범위 뒤 컬럼은 무력화"]}}]},{"t":"뷰·프로시저·트리거","l":[{"t":"뷰(VIEW)의 본질","q":[{"t":"choice","k":"뷰 저장 대상","q":"CREATE VIEW로 뷰를 만들면 데이터베이스에 실제로 저장되는 것은?","o":["뷰 결과 행들의 복사본","SELECT 쿼리 정의(정의문)","베이스 테이블의 인덱스","뷰 전용 물리 테이블"],"a":1,"ex":"일반 뷰는 가상 테이블로, 데이터가 아니라 쿼리 정의만 저장된다. 조회 시점에 정의가 실행되어 결과를 만든다. 결과를 물리적으로 저장하는 것은 materialized view다."},{"t":"input","k":"뷰 삭제문","q":"employees_view라는 뷰를 제거하는 표준 SQL DDL 문장을 작성하시오 (세미콜론 제외).","a":["DROP VIEW employees_view","drop view employees_view"],"ex":"뷰 제거는 DROP VIEW 뷰이름. DROP TABLE은 베이스 테이블용이며 뷰에 쓰면 안 된다."}],"th":{"sum":"**뷰**는 저장된 쿼리(정의)일 뿐 데이터를 복제하지 않는다. **프로시저**는 값을 반환하지 않는 실행 단위, **함수**는 값을 반환한다. **트리거**는 DML 시 자동 실행된다.","body":[{"h":"뷰","t":"`CREATE VIEW`는 SELECT 정의만 저장하며 조회 시 실행된다. 복잡한 쿼리 캡슐화·권한 제어에 좋다. 단일 테이블·집계 없음 등 조건을 만족하면 updatable view가 되어 갱신도 가능하고, `WITH CHECK OPTION`은 뷰 조건을 벗어나는 INSERT/UPDATE를 막는다. 제거는 `DROP VIEW employees_view`."},{"h":"프로시저·함수·트리거","t":"저장 함수는 값을 반환해 SQL 식에서 호출할 수 있고, 프로시저는 `CALL 이름()`으로 실행하며 결과셋·부작용 중심이다. 트리거는 `BEFORE/AFTER INSERT|UPDATE|DELETE` 시점에 자동 발화해 감사 로그·검증 등에 쓴다."}],"code":{"c":"CREATE VIEW active_users AS\n  SELECT id, name FROM users WHERE active = 1;\n\nDROP VIEW employees_view;","cap":"뷰 생성(정의만 저장)과 제거"},"key":["뷰=저장된 쿼리 정의, 데이터 복제 아님","함수는 값 반환, 프로시저는 `CALL`로 실행","제거는 `DROP VIEW ...`, 조건 강제는 WITH CHECK OPTION"]}},{"t":"저장 프로시저와 함수","q":[{"t":"choice","k":"프로시저 호출","q":"MySQL에서 저장 프로시저를 실행하는 문장은?","o":["EXEC procedure_name","RUN procedure_name","CALL procedure_name()","SELECT procedure_name()"],"a":2,"ex":"표준 및 MySQL에서 저장 프로시저는 CALL 문으로 호출한다. SELECT로 호출하는 것은 (스칼라) 함수다."},{"t":"input","k":"블록 구분자","q":"MySQL에서 BEGIN...END 프로시저 본문의 세미콜론과 충돌을 피하려고 임시로 문장 종료 기호를 바꿀 때 쓰는 키워드는?","a":["DELIMITER","delimiter"],"ex":"DELIMITER $ 처럼 종료 기호를 바꿔 본문 내부의 ; 를 문장 끝으로 오인하지 않게 한 뒤, 정의가 끝나면 다시 DELIMITER ; 로 되돌린다."},{"t":"choice","k":"결정성","q":"저장 함수를 DETERMINISTIC으로 선언한다는 의미는?","o":["같은 입력에 항상 같은 결과를 반환한다","트랜잭션을 자동 커밋한다","실행마다 난수를 반환한다","반드시 테이블을 수정한다"],"a":0,"ex":"DETERMINISTIC은 동일 입력에 동일 출력을 보장한다는 선언으로, 옵티마이저 최적화와 복제 안전성에 활용된다. NOW()나 RAND()를 쓰면 NOT DETERMINISTIC이다."}],"th":{"sum":"**뷰**는 저장된 쿼리(정의)일 뿐 데이터를 복제하지 않는다. **프로시저**는 값을 반환하지 않는 실행 단위, **함수**는 값을 반환한다. **트리거**는 DML 시 자동 실행된다.","body":[{"h":"뷰","t":"`CREATE VIEW`는 SELECT 정의만 저장하며 조회 시 실행된다. 복잡한 쿼리 캡슐화·권한 제어에 좋다. 단일 테이블·집계 없음 등 조건을 만족하면 updatable view가 되어 갱신도 가능하고, `WITH CHECK OPTION`은 뷰 조건을 벗어나는 INSERT/UPDATE를 막는다. 제거는 `DROP VIEW employees_view`."},{"h":"프로시저·함수·트리거","t":"저장 함수는 값을 반환해 SQL 식에서 호출할 수 있고, 프로시저는 `CALL 이름()`으로 실행하며 결과셋·부작용 중심이다. 트리거는 `BEFORE/AFTER INSERT|UPDATE|DELETE` 시점에 자동 발화해 감사 로그·검증 등에 쓴다."}],"code":{"c":"CREATE VIEW active_users AS\n  SELECT id, name FROM users WHERE active = 1;\n\nDROP VIEW employees_view;","cap":"뷰 생성(정의만 저장)과 제거"},"key":["뷰=저장된 쿼리 정의, 데이터 복제 아님","함수는 값 반환, 프로시저는 `CALL`로 실행","제거는 `DROP VIEW ...`, 조건 강제는 WITH CHECK OPTION"]}},{"t":"트리거(TRIGGER)","q":[{"t":"choice","k":"FOR EACH ROW","q":"MySQL 트리거의 FOR EACH ROW 의미로 옳은 것은?","o":["문장 전체에 대해 한 번만 실행","영향받는 각 행마다 트리거 본문 실행","트랜잭션당 한 번 실행","테이블당 하루 한 번 실행"],"a":1,"ex":"FOR EACH ROW는 행 수준 트리거로, 영향을 받는 각 행마다 본문이 실행된다. 문장 수준(statement-level) 트리거와 대비된다."},{"t":"input","k":"발동 시점 키워드","q":"트리거 본문 실행 시점을 실제 쓰기 전/후로 지정하는 두 키워드 중 하나를 쓰시오.","a":["BEFORE","AFTER","before","after"],"ex":"트리거는 BEFORE 또는 AFTER 시점에 INSERT/UPDATE/DELETE 이벤트로 정의된다."}],"th":{"sum":"**뷰**는 저장된 쿼리(정의)일 뿐 데이터를 복제하지 않는다. **프로시저**는 값을 반환하지 않는 실행 단위, **함수**는 값을 반환한다. **트리거**는 DML 시 자동 실행된다.","body":[{"h":"뷰","t":"`CREATE VIEW`는 SELECT 정의만 저장하며 조회 시 실행된다. 복잡한 쿼리 캡슐화·권한 제어에 좋다. 단일 테이블·집계 없음 등 조건을 만족하면 updatable view가 되어 갱신도 가능하고, `WITH CHECK OPTION`은 뷰 조건을 벗어나는 INSERT/UPDATE를 막는다. 제거는 `DROP VIEW employees_view`."},{"h":"프로시저·함수·트리거","t":"저장 함수는 값을 반환해 SQL 식에서 호출할 수 있고, 프로시저는 `CALL 이름()`으로 실행하며 결과셋·부작용 중심이다. 트리거는 `BEFORE/AFTER INSERT|UPDATE|DELETE` 시점에 자동 발화해 감사 로그·검증 등에 쓴다."}],"code":{"c":"CREATE VIEW active_users AS\n  SELECT id, name FROM users WHERE active = 1;\n\nDROP VIEW employees_view;","cap":"뷰 생성(정의만 저장)과 제거"},"key":["뷰=저장된 쿼리 정의, 데이터 복제 아님","함수는 값 반환, 프로시저는 `CALL`로 실행","제거는 `DROP VIEW ...`, 조건 강제는 WITH CHECK OPTION"]}}]},{"t":"트랜잭션 격리 수준","l":[{"t":"네 가지 격리 수준","q":[{"t":"choice","k":"모두 허용","q":"세 가지 읽기 이상현상(Dirty/Non-repeatable/Phantom)을 모두 허용하는 가장 낮은 격리 수준은?","o":["READ UNCOMMITTED","READ COMMITTED","REPEATABLE READ","SERIALIZABLE"],"a":0,"ex":"READ UNCOMMITTED는 커밋되지 않은 데이터까지 읽어 Dirty·Non-repeatable·Phantom Read를 모두 허용한다. 가장 낮은 격리이자 최고 동시성이다."},{"t":"choice","k":"모두 차단","q":"세 가지 읽기 이상현상을 모두 방지하는 가장 높은 격리 수준은?","o":["READ COMMITTED","REPEATABLE READ","SERIALIZABLE","READ UNCOMMITTED"],"a":2,"ex":"SERIALIZABLE은 트랜잭션들을 직렬 실행한 것과 동등하게 만들어 Dirty·Non-repeatable·Phantom Read를 전부 막는다. 대신 동시성이 가장 낮다."},{"t":"choice","k":"RC가 막는 것","q":"READ COMMITTED가 방지하는 이상현상은?","o":["Dirty Read만","Dirty와 Non-repeatable Read","Non-repeatable Read만","Phantom Read만"],"a":0,"ex":"READ COMMITTED는 커밋된 데이터만 읽으므로 Dirty Read만 방지한다. 같은 행을 다시 읽으면 값이 바뀔 수 있어(Non-repeatable) 이 현상과 Phantom은 허용된다."},{"t":"choice","k":"트레이드오프","q":"격리 수준을 높일수록 일반적으로 나타나는 경향은?","o":["동시성 증가, 일관성 감소","동시성 감소, 일관성 증가","동시성·일관성 모두 증가","동시성·일관성 모두 감소"],"a":1,"ex":"격리 수준이 높을수록 잠금/차단이 늘어 동시성은 떨어지지만 데이터 일관성은 강해진다. 전형적인 성능-정합성 트레이드오프다."}],"th":{"sum":"격리 수준은 낮은 것부터 READ UNCOMMITTED → READ COMMITTED → REPEATABLE READ → SERIALIZABLE. 높일수록 이상현상은 줄고 **동시성은 낮아진다**.","body":[{"h":"네 수준과 이상현상 매핑","t":"READ UNCOMMITTED는 Dirty/Non-repeatable/Phantom을 모두 허용(가장 낮음), SERIALIZABLE은 셋 다 방지(가장 높음)한다. READ COMMITTED는 커밋된 것만 읽어 Dirty Read를 막지만 Non-repeatable은 허용한다. REPEATABLE READ는 Dirty·Non-repeatable을 막고 표준상 Phantom은 허용한다(InnoDB는 갭 락으로 상당수 방지)."},{"h":"이상현상 정의","t":"Dirty Read는 아직 커밋 안 된 다른 트랜잭션의 변경을 읽는 것, Non-repeatable Read는 같은 행을 두 번 읽는 사이 다른 트랜잭션이 커밋해 값이 달라지는 것, Phantom Read는 같은 조건 재조회 시 행 수가 달라지는 것이다. 격리를 높이면 락·대기가 늘어 데드락 가능성도 커진다."}],"code":{"c":"SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;\nBEGIN;\nSELECT * FROM t WHERE id = 1;  -- 반복 조회 값 고정\nCOMMIT;","cap":"격리 수준 지정으로 재조회 일관성 확보"},"key":["낮음 RU → RC → RR → SERIALIZABLE 높음","RC는 Dirty 방지·Non-repeatable 허용, RR은 둘 방지","격리↑ → 이상현상↓·동시성↓"]}},{"t":"읽기 이상현상 매핑","q":[{"t":"choice","k":"Dirty Read","q":"Dirty Read의 정의로 옳은 것은?","o":["다른 트랜잭션이 커밋하지 않은 변경을 읽는 것","같은 조건 재조회 시 행 수가 달라지는 것","같은 행을 두 번 읽을 때 값이 달라지는 것","커밋 후에도 값이 유지되는 것"],"a":0,"ex":"Dirty Read는 아직 커밋되지 않은(롤백될 수도 있는) 다른 트랜잭션의 변경을 읽는 것이다. 롤백되면 존재하지 않았던 값을 읽은 셈이 된다."},{"t":"choice","k":"수준 선택","q":"Phantom Read는 허용하되 Non-repeatable Read는 막고 싶다면 표준상 어떤 수준을 선택해야 하나?","o":["READ UNCOMMITTED","READ COMMITTED","REPEATABLE READ","SERIALIZABLE"],"a":2,"ex":"REPEATABLE READ가 Non-repeatable은 막고 Phantom은 (표준상) 허용하는 유일한 수준이다. 위 요구에 정확히 부합한다."},{"t":"input","k":"롤백 위험 읽기","q":"롤백될 수도 있는, 커밋되지 않은 데이터를 읽는 이상현상의 영어 명칭 두 단어를 쓰시오.","a":["Dirty Read","dirty read","dirtyread"],"ex":"커밋 전 데이터를 읽는 현상은 Dirty Read이며, READ UNCOMMITTED에서만 발생한다."}],"th":{"sum":"격리 수준은 낮은 것부터 READ UNCOMMITTED → READ COMMITTED → REPEATABLE READ → SERIALIZABLE. 높일수록 이상현상은 줄고 **동시성은 낮아진다**.","body":[{"h":"네 수준과 이상현상 매핑","t":"READ UNCOMMITTED는 Dirty/Non-repeatable/Phantom을 모두 허용(가장 낮음), SERIALIZABLE은 셋 다 방지(가장 높음)한다. READ COMMITTED는 커밋된 것만 읽어 Dirty Read를 막지만 Non-repeatable은 허용한다. REPEATABLE READ는 Dirty·Non-repeatable을 막고 표준상 Phantom은 허용한다(InnoDB는 갭 락으로 상당수 방지)."},{"h":"이상현상 정의","t":"Dirty Read는 아직 커밋 안 된 다른 트랜잭션의 변경을 읽는 것, Non-repeatable Read는 같은 행을 두 번 읽는 사이 다른 트랜잭션이 커밋해 값이 달라지는 것, Phantom Read는 같은 조건 재조회 시 행 수가 달라지는 것이다. 격리를 높이면 락·대기가 늘어 데드락 가능성도 커진다."}],"code":{"c":"SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;\nBEGIN;\nSELECT * FROM t WHERE id = 1;  -- 반복 조회 값 고정\nCOMMIT;","cap":"격리 수준 지정으로 재조회 일관성 확보"},"key":["낮음 RU → RC → RR → SERIALIZABLE 높음","RC는 Dirty 방지·Non-repeatable 허용, RR은 둘 방지","격리↑ → 이상현상↓·동시성↓"]}},{"t":"잠금·데드락·InnoDB","q":[{"t":"choice","k":"InnoDB 기본","q":"MySQL InnoDB 스토리지 엔진의 기본 트랜잭션 격리 수준은?","o":["READ UNCOMMITTED","READ COMMITTED","REPEATABLE READ","SERIALIZABLE"],"a":2,"ex":"InnoDB의 기본 격리 수준은 REPEATABLE READ이며, 갭 락(next-key lock) 덕분에 이 수준에서 팬텀까지 상당 부분 방지하는 특징이 있다."},{"t":"choice","k":"데드락 대응","q":"데드락을 줄이거나 대응하는 방법으로 적절하지 않은 것은?","o":["트랜잭션에서 자원을 항상 동일한 순서로 접근","트랜잭션을 짧게 유지","데드락 감지 시 재시도 로직 적용","모든 트랜잭션 격리 수준을 SERIALIZABLE로 강제"],"a":3,"ex":"자원 접근 순서 일관화, 짧은 트랜잭션, 재시도는 유효한 완화책이다. 무조건 SERIALIZABLE로 올리면 잠금이 늘어 오히려 데드락과 대기가 증가할 수 있다."}],"th":{"sum":"격리 수준은 낮은 것부터 READ UNCOMMITTED → READ COMMITTED → REPEATABLE READ → SERIALIZABLE. 높일수록 이상현상은 줄고 **동시성은 낮아진다**.","body":[{"h":"네 수준과 이상현상 매핑","t":"READ UNCOMMITTED는 Dirty/Non-repeatable/Phantom을 모두 허용(가장 낮음), SERIALIZABLE은 셋 다 방지(가장 높음)한다. READ COMMITTED는 커밋된 것만 읽어 Dirty Read를 막지만 Non-repeatable은 허용한다. REPEATABLE READ는 Dirty·Non-repeatable을 막고 표준상 Phantom은 허용한다(InnoDB는 갭 락으로 상당수 방지)."},{"h":"이상현상 정의","t":"Dirty Read는 아직 커밋 안 된 다른 트랜잭션의 변경을 읽는 것, Non-repeatable Read는 같은 행을 두 번 읽는 사이 다른 트랜잭션이 커밋해 값이 달라지는 것, Phantom Read는 같은 조건 재조회 시 행 수가 달라지는 것이다. 격리를 높이면 락·대기가 늘어 데드락 가능성도 커진다."}],"code":{"c":"SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;\nBEGIN;\nSELECT * FROM t WHERE id = 1;  -- 반복 조회 값 고정\nCOMMIT;","cap":"격리 수준 지정으로 재조회 일관성 확보"},"key":["낮음 RU → RC → RR → SERIALIZABLE 높음","RC는 Dirty 방지·Non-repeatable 허용, RR은 둘 방지","격리↑ → 이상현상↓·동시성↓"]}}]},{"t":"정규화와 설계","l":[{"t":"함수 종속과 이상현상","q":[{"t":"choice","k":"갱신 이상","q":"갱신 이상(update anomaly)이 뜻하는 것은?","o":["중복 저장된 값 중 일부만 수정되어 데이터가 불일치","행을 삭제하면 필요한 정보까지 사라짐","새 정보를 넣으려면 불필요한 값이 강제됨","조회 속도가 느려짐"],"a":0,"ex":"갱신 이상은 같은 사실이 여러 행에 중복 저장돼 있을 때 일부만 갱신되어 값이 모순되는 문제다. 삭제 이상·삽입 이상과 함께 비정규 설계의 대표 폐해다."},{"t":"choice","k":"종속 표기","q":"결정자 X가 종속자 Y를 유일하게 결정하는 함수 종속을 기호로 표기하면?","o":["X → Y","X ↔ Y","X = Y","X ⊂ Y"],"a":0,"ex":"함수 종속은 X → Y로 표기하며, X를 결정자(determinant), Y를 종속자라 한다."}],"th":{"sum":"함수 종속 `A → B`는 A가 정해지면 B가 유일하게 정해진다는 뜻. 중복 설계는 삽입·갱신·삭제 **이상현상**을 낳고, 정규형은 이를 단계적으로 제거한다.","body":[{"h":"이상현상","t":"갱신 이상은 같은 사실이 여러 행에 중복돼 일부만 고치면 불일치가 생기는 것, 삽입 이상은 불필요한 정보가 없으면 원하는 행을 넣지 못하는 것, 삭제 이상은 한 행을 지우면 보존하고 싶던 정보까지 사라지는 것이다. 모두 중복·잘못된 종속이 원인이다."},{"h":"1NF~BCNF","t":"1NF는 모든 값이 원자값일 것(반복 그룹 제거). 2NF는 복합키에서 키 일부에만 의존하는 부분 종속 제거. 3NF는 키가 아닌 컬럼을 거친 이행 종속 제거. BCNF는 모든 결정자가 후보키여야 한다는 더 엄격한 조건이다."}],"code":{"c":"-- 부분 종속(2NF 위반) 분리\n-- order_item(order_id, product_id, product_name)\n--   product_name 은 product_id 에만 종속 → 분리\nCREATE TABLE product (\n  product_id INT PRIMARY KEY,\n  product_name VARCHAR(100)\n);","cap":"부분 종속을 별도 테이블로 분리(2NF)"},"key":["`A → B`: A가 B를 유일하게 결정","이상현상=갱신/삽입/삭제, 원인은 중복","1NF 원자값 → 2NF 부분종속 → 3NF 이행종속 제거"]}},{"t":"정규형 1NF~BCNF","q":[{"t":"choice","k":"BCNF","q":"BCNF(Boyce-Codd 정규형)가 3NF보다 엄격한 점은?","o":["모든 결정자가 후보키여야 한다","원자값만 허용한다","외래키를 금지한다","중복 인덱스를 제거한다"],"a":0,"ex":"BCNF는 모든 함수 종속의 결정자가 반드시 후보키일 것을 요구한다. 3NF는 결정자가 후보키가 아니어도 종속자가 주요 속성이면 허용해 BCNF보다 약하다."},{"t":"choice","k":"BCNF 판정","q":"관계 R(교수, 과목, 시간)에서 (과목,시간)→교수 이고 교수→과목 이며 후보키가 (과목,시간)과 (교수,시간)일 때, 교수→과목 때문에 위반되는 정규형은?","o":["1NF","2NF","3NF는 만족하나 BCNF는 위반","어떤 정규형도 위반 안 함"],"a":2,"ex":"교수→과목에서 결정자 '교수'는 후보키가 아니지만 종속자 '과목'이 주요 속성이라 3NF는 만족할 수 있다. 그러나 결정자가 후보키가 아니므로 BCNF는 위반한다."}],"th":{"sum":"함수 종속 `A → B`는 A가 정해지면 B가 유일하게 정해진다는 뜻. 중복 설계는 삽입·갱신·삭제 **이상현상**을 낳고, 정규형은 이를 단계적으로 제거한다.","body":[{"h":"이상현상","t":"갱신 이상은 같은 사실이 여러 행에 중복돼 일부만 고치면 불일치가 생기는 것, 삽입 이상은 불필요한 정보가 없으면 원하는 행을 넣지 못하는 것, 삭제 이상은 한 행을 지우면 보존하고 싶던 정보까지 사라지는 것이다. 모두 중복·잘못된 종속이 원인이다."},{"h":"1NF~BCNF","t":"1NF는 모든 값이 원자값일 것(반복 그룹 제거). 2NF는 복합키에서 키 일부에만 의존하는 부분 종속 제거. 3NF는 키가 아닌 컬럼을 거친 이행 종속 제거. BCNF는 모든 결정자가 후보키여야 한다는 더 엄격한 조건이다."}],"code":{"c":"-- 부분 종속(2NF 위반) 분리\n-- order_item(order_id, product_id, product_name)\n--   product_name 은 product_id 에만 종속 → 분리\nCREATE TABLE product (\n  product_id INT PRIMARY KEY,\n  product_name VARCHAR(100)\n);","cap":"부분 종속을 별도 테이블로 분리(2NF)"},"key":["`A → B`: A가 B를 유일하게 결정","이상현상=갱신/삽입/삭제, 원인은 중복","1NF 원자값 → 2NF 부분종속 → 3NF 이행종속 제거"]}},{"t":"반정규화·키·파티셔닝","q":[{"t":"choice","k":"기본키","q":"기본키(PRIMARY KEY) 설계 원칙으로 옳지 않은 것은?","o":["NULL을 허용하지 않는다","각 행을 유일하게 식별한다","자주 변경되는 값을 고르는 것이 이상적이다","최소한의 속성으로 구성한다"],"a":2,"ex":"기본키는 유일성·NOT NULL·불변성(자주 바뀌지 않음)·최소성이 바람직하다. 자주 변경되는 값을 키로 삼으면 참조 갱신 부담이 커져 부적절하다."},{"t":"input","k":"성능용 중복 허용","q":"정규화된 스키마에서 조회 성능을 위해 의도적으로 중복을 도입하는 설계 기법의 영어 명칭은?","a":["denormalization","비정규화","반정규화"],"ex":"성능을 위해 중복·집계값을 의도적으로 추가하는 기법을 denormalization(반정규화)이라 한다. 정규화의 역방향 트레이드오프다."}],"th":{"sum":"함수 종속 `A → B`는 A가 정해지면 B가 유일하게 정해진다는 뜻. 중복 설계는 삽입·갱신·삭제 **이상현상**을 낳고, 정규형은 이를 단계적으로 제거한다.","body":[{"h":"이상현상","t":"갱신 이상은 같은 사실이 여러 행에 중복돼 일부만 고치면 불일치가 생기는 것, 삽입 이상은 불필요한 정보가 없으면 원하는 행을 넣지 못하는 것, 삭제 이상은 한 행을 지우면 보존하고 싶던 정보까지 사라지는 것이다. 모두 중복·잘못된 종속이 원인이다."},{"h":"1NF~BCNF","t":"1NF는 모든 값이 원자값일 것(반복 그룹 제거). 2NF는 복합키에서 키 일부에만 의존하는 부분 종속 제거. 3NF는 키가 아닌 컬럼을 거친 이행 종속 제거. BCNF는 모든 결정자가 후보키여야 한다는 더 엄격한 조건이다."}],"code":{"c":"-- 부분 종속(2NF 위반) 분리\n-- order_item(order_id, product_id, product_name)\n--   product_name 은 product_id 에만 종속 → 분리\nCREATE TABLE product (\n  product_id INT PRIMARY KEY,\n  product_name VARCHAR(100)\n);","cap":"부분 종속을 별도 테이블로 분리(2NF)"},"key":["`A → B`: A가 B를 유일하게 결정","이상현상=갱신/삽입/삭제, 원인은 중복","1NF 원자값 → 2NF 부분종속 → 3NF 이행종속 제거"]}}]},{"t":"집합 연산자","l":[{"t":"UNION과 UNION ALL","q":[{"t":"choice","k":"성능","q":"일반적으로 UNION ALL이 UNION보다 빠른 이유는?","o":["중복 제거를 위한 정렬/해싱 작업이 없기 때문","더 적은 컬럼을 반환하기 때문","항상 인덱스를 사용하기 때문","결과를 자동으로 캐시에 저장하기 때문"],"a":0,"ex":"UNION은 중복 제거를 위해 정렬 또는 해시 연산이 추가로 필요하다. 중복이 없음을 아는 경우 UNION ALL이 더 효율적이다."},{"t":"input","k":"UNION 행 수","q":"A.id={1,2,3}, B.id={3,4}일 때 위 쿼리의 결과 행 수는?","code":"SELECT id FROM A\nUNION\nSELECT id FROM B;","a":["4"],"ex":"UNION은 중복을 제거한다. 합집합 {1,2,3,4} = 4행. UNION ALL이면 5행이 된다."},{"t":"choice","k":"컬럼명","q":"UNION 결과의 컬럼명(헤더)은 어느 SELECT를 기준으로 정해지는가?","o":["첫 번째 SELECT","마지막 SELECT","컬럼명이 가장 긴 SELECT","알파벳순으로 정렬된 이름"],"a":0,"ex":"결과 컬럼명은 첫 번째 SELECT의 컬럼명(또는 별칭)을 따른다. 별칭도 첫 SELECT에 지정해야 반영된다."}],"th":{"sum":"`UNION`은 두 결과를 합치며 **중복 제거**, `UNION ALL`은 중복을 그대로 둔다. 컬럼 수·타입이 일치해야 하고 헤더는 첫 SELECT 기준이다.","body":[{"h":"UNION vs UNION ALL","t":"`UNION`은 중복 제거를 위해 정렬·해시 작업을 하므로 보통 `UNION ALL`보다 느리다. 중복이 없거나 상관없다면 `UNION ALL`이 성능상 유리하다. A.id={1,2,3}, B.id={3,4}를 `UNION`하면 {1,2,3,4}로 4행이다."},{"h":"컬럼 규칙과 ORDER BY","t":"결합하려면 각 SELECT의 컬럼 개수와 대응 타입이 일치해야 하고, 결과 컬럼명은 첫 SELECT를 따른다. `ORDER BY`는 개별 SELECT가 아니라 전체 결합 결과의 맨 끝에 한 번만 쓰며, 첫 SELECT의 컬럼명이나 위치 번호로 지정하는 게 안전하다. `INTERSECT`(교집합), `EXCEPT`/`MINUS`(차집합)도 같은 규칙을 따른다."}],"code":{"c":"SELECT name FROM online_customers\nUNION\nSELECT name FROM store_customers\nORDER BY name;","cap":"두 소스 명단 합치고 중복 제거 후 정렬"},"key":["`UNION`=중복 제거, `UNION ALL`=중복 유지(더 빠름)","컬럼 수·타입 일치, 헤더는 첫 SELECT","`ORDER BY`는 맨 끝에 한 번만"]}},{"t":"ORDER BY와 컬럼 규칙","q":[{"t":"choice","k":"ORDER BY 위치","q":"UNION으로 결합된 쿼리에서 ORDER BY는 어디에 써야 하는가?","o":["전체 쿼리의 맨 마지막에 한 번만","각 SELECT마다 하나씩","첫 번째 SELECT에만","ORDER BY는 사용할 수 없다"],"a":0,"ex":"ORDER BY는 개별 SELECT가 아니라 최종 결과 전체에 대해 맨 마지막에 한 번만 작성한다."},{"t":"input","k":"연산자 채우기","q":"중복을 제거하지 않고 두 결과를 모두 합치려면 빈칸(____ ALL)에 들어갈 연산자는?","code":"SELECT name FROM emp\n____ ALL\nSELECT name FROM contractor;","a":["UNION"],"ex":"UNION ALL은 중복 제거 없이 두 결과의 모든 행을 결합한다."},{"t":"choice","k":"NULL 결합","q":"UNION은 중복 제거 시 NULL을 어떻게 취급하는가?","o":["두 NULL을 서로 같은 값으로 간주해 하나로 합친다","NULL끼리는 항상 다른 값으로 본다","NULL이 있으면 오류가 발생한다","NULL 행은 결과에서 무조건 제외된다"],"a":0,"ex":"일반 비교(=)에서 NULL=NULL은 unknown이지만, UNION/DISTINCT의 중복 판정에서는 NULL들을 동일하게 취급해 하나로 묶는다."}],"th":{"sum":"`UNION`은 두 결과를 합치며 **중복 제거**, `UNION ALL`은 중복을 그대로 둔다. 컬럼 수·타입이 일치해야 하고 헤더는 첫 SELECT 기준이다.","body":[{"h":"UNION vs UNION ALL","t":"`UNION`은 중복 제거를 위해 정렬·해시 작업을 하므로 보통 `UNION ALL`보다 느리다. 중복이 없거나 상관없다면 `UNION ALL`이 성능상 유리하다. A.id={1,2,3}, B.id={3,4}를 `UNION`하면 {1,2,3,4}로 4행이다."},{"h":"컬럼 규칙과 ORDER BY","t":"결합하려면 각 SELECT의 컬럼 개수와 대응 타입이 일치해야 하고, 결과 컬럼명은 첫 SELECT를 따른다. `ORDER BY`는 개별 SELECT가 아니라 전체 결합 결과의 맨 끝에 한 번만 쓰며, 첫 SELECT의 컬럼명이나 위치 번호로 지정하는 게 안전하다. `INTERSECT`(교집합), `EXCEPT`/`MINUS`(차집합)도 같은 규칙을 따른다."}],"code":{"c":"SELECT name FROM online_customers\nUNION\nSELECT name FROM store_customers\nORDER BY name;","cap":"두 소스 명단 합치고 중복 제거 후 정렬"},"key":["`UNION`=중복 제거, `UNION ALL`=중복 유지(더 빠름)","컬럼 수·타입 일치, 헤더는 첫 SELECT","`ORDER BY`는 맨 끝에 한 번만"]}},{"t":"INTERSECT와 EXCEPT/MINUS","q":[{"t":"input","k":"INTERSECT 행 수","q":"A.id={1,2,3,4}, B.id={3,4,5,6}일 때 위 쿼리의 결과 행 수는?","code":"SELECT id FROM A\nINTERSECT\nSELECT id FROM B;","a":["2"],"ex":"양쪽 모두에 있는 값은 3,4 뿐이므로 2행이다."},{"t":"input","k":"EXCEPT 행 수","q":"같은 A, B에 대해 위 쿼리(A EXCEPT B)의 결과 행 수는?","code":"SELECT id FROM A\nEXCEPT\nSELECT id FROM B;","a":["2"],"ex":"EXCEPT는 A에는 있고 B에는 없는 행을 반환한다. {1,2} 이므로 2행이다."},{"t":"choice","k":"방언","q":"Oracle에서 EXCEPT와 동일한 차집합 연산자는? (MySQL은 8.0.31부터 INTERSECT/EXCEPT 지원)","o":["MINUS","SUBTRACT","DIFF","REMOVE"],"a":0,"ex":"Oracle은 표준 EXCEPT 대신 MINUS를 쓴다. MySQL은 8.0.31 미만 버전에서 INTERSECT/EXCEPT를 지원하지 않는다."}],"th":{"sum":"`UNION`은 두 결과를 합치며 **중복 제거**, `UNION ALL`은 중복을 그대로 둔다. 컬럼 수·타입이 일치해야 하고 헤더는 첫 SELECT 기준이다.","body":[{"h":"UNION vs UNION ALL","t":"`UNION`은 중복 제거를 위해 정렬·해시 작업을 하므로 보통 `UNION ALL`보다 느리다. 중복이 없거나 상관없다면 `UNION ALL`이 성능상 유리하다. A.id={1,2,3}, B.id={3,4}를 `UNION`하면 {1,2,3,4}로 4행이다."},{"h":"컬럼 규칙과 ORDER BY","t":"결합하려면 각 SELECT의 컬럼 개수와 대응 타입이 일치해야 하고, 결과 컬럼명은 첫 SELECT를 따른다. `ORDER BY`는 개별 SELECT가 아니라 전체 결합 결과의 맨 끝에 한 번만 쓰며, 첫 SELECT의 컬럼명이나 위치 번호로 지정하는 게 안전하다. `INTERSECT`(교집합), `EXCEPT`/`MINUS`(차집합)도 같은 규칙을 따른다."}],"code":{"c":"SELECT name FROM online_customers\nUNION\nSELECT name FROM store_customers\nORDER BY name;","cap":"두 소스 명단 합치고 중복 제거 후 정렬"},"key":["`UNION`=중복 제거, `UNION ALL`=중복 유지(더 빠름)","컬럼 수·타입 일치, 헤더는 첫 SELECT","`ORDER BY`는 맨 끝에 한 번만"]}}]},{"t":"고급 그룹화","l":[{"t":"ROLLUP","q":[{"t":"input","k":"ROLLUP 그룹 수","q":"ROLLUP(a, b, c)는 몇 개의 그룹화 집합(집계 수준)을 생성하는가?","a":["4"],"ex":"ROLLUP(n개 컬럼)은 n+1개 수준을 만든다. (a,b,c),(a,b),(a),() 로 4개다."},{"t":"choice","k":"MySQL 방언","q":"MySQL에서 ROLLUP을 사용하는 문법은?","o":["GROUP BY region, product WITH ROLLUP","GROUP BY ROLLUP(region, product)","GROUP BY region, product ADD ROLLUP","ROLLUP GROUP BY region, product"],"a":0,"ex":"MySQL은 표준 GROUP BY ROLLUP(...) 대신 GROUP BY ... WITH ROLLUP 구문을 쓴다. Postgres/Oracle/SQL Server는 함수형 ROLLUP(...)을 지원한다."},{"t":"input","k":"총계 행 수","q":"ROLLUP(region)에서 region이 3종류일 때, 상세·소계를 제외한 '총계(grand total)' 행은 몇 개 생기는가?","a":["1"],"ex":"ROLLUP은 항상 하나의 총계 행(모든 컬럼이 NULL)을 추가한다."}],"th":{"sum":"`ROLLUP`은 소계·총계를 계층적으로 추가하고, `CUBE`는 모든 조합의 소계를, `GROUPING SETS`는 원하는 집합만 만든다.","body":[{"h":"ROLLUP","t":"`ROLLUP(region, product)`은 (region,product)+region별 소계+전체 총계를 낸다. n개 컬럼 ROLLUP은 n+1개 그룹화 집합을 만든다. 소계·총계 행에서 해당 그룹 컬럼은 NULL로 표시되며, MySQL은 `GROUP BY region, product WITH ROLLUP` 문법을 쓴다. 총계 행은 항상 1개다."},{"h":"CUBE와 GROUPING","t":"`CUBE(a,b)`는 (a,b),(a),(b),()의 모든 부분집합 조합, 즉 2^n개(여기선 4개) 집합을 만든다. `GROUPING(컬럼)` 함수는 그 NULL이 실제 NULL인지 소계로 인한 NULL인지 구분해주며, `HAVING`으로 특정 집계 수준만 걸러낼 수 있다."}],"code":{"c":"SELECT region, product, SUM(sales)\nFROM t\nGROUP BY region, product WITH ROLLUP;","cap":"상세+region 소계+총계를 한 번에(MySQL ROLLUP)"},"key":["ROLLUP(n컬럼)=n+1개 집합, 총계 1행","CUBE(n컬럼)=2^n개 모든 조합","소계 컬럼은 NULL, `GROUPING`으로 구분"]}},{"t":"CUBE와 GROUPING SETS","q":[{"t":"input","k":"CUBE 집합 수","q":"CUBE(a, b, c)는 몇 개의 그룹화 집합을 생성하는가?","a":["8"],"ex":"CUBE(n)은 2^n개 집합을 만든다. 2^3 = 8개다."},{"t":"choice","k":"ROLLUP 표현","q":"GROUPING SETS로 ROLLUP(a,b)와 동일한 결과를 만들려면?","o":["GROUPING SETS ((a,b),(a),())","GROUPING SETS ((a,b),(b),())","GROUPING SETS ((a),(b))","GROUPING SETS ((a,b))"],"a":0,"ex":"ROLLUP(a,b)는 GROUPING SETS ((a,b),(a),())와 동등하다. CUBE(a,b)는 여기에 (b)를 더한 것이다."}],"th":{"sum":"`ROLLUP`은 소계·총계를 계층적으로 추가하고, `CUBE`는 모든 조합의 소계를, `GROUPING SETS`는 원하는 집합만 만든다.","body":[{"h":"ROLLUP","t":"`ROLLUP(region, product)`은 (region,product)+region별 소계+전체 총계를 낸다. n개 컬럼 ROLLUP은 n+1개 그룹화 집합을 만든다. 소계·총계 행에서 해당 그룹 컬럼은 NULL로 표시되며, MySQL은 `GROUP BY region, product WITH ROLLUP` 문법을 쓴다. 총계 행은 항상 1개다."},{"h":"CUBE와 GROUPING","t":"`CUBE(a,b)`는 (a,b),(a),(b),()의 모든 부분집합 조합, 즉 2^n개(여기선 4개) 집합을 만든다. `GROUPING(컬럼)` 함수는 그 NULL이 실제 NULL인지 소계로 인한 NULL인지 구분해주며, `HAVING`으로 특정 집계 수준만 걸러낼 수 있다."}],"code":{"c":"SELECT region, product, SUM(sales)\nFROM t\nGROUP BY region, product WITH ROLLUP;","cap":"상세+region 소계+총계를 한 번에(MySQL ROLLUP)"},"key":["ROLLUP(n컬럼)=n+1개 집합, 총계 1행","CUBE(n컬럼)=2^n개 모든 조합","소계 컬럼은 NULL, `GROUPING`으로 구분"]}},{"t":"GROUPING 함수와 HAVING","q":[{"t":"choice","k":"HAVING 조합","q":"ROLLUP 결과에서 소계 행만 남기고 상세 행을 제외하려면?","o":["HAVING GROUPING(product) = 1","WHERE product IS NULL","HAVING COUNT(*) = 1","GROUP BY product ONLY SUBTOTAL"],"a":0,"ex":"HAVING GROUPING(product)=1은 product가 집계된 소계 행만 남긴다. WHERE는 그룹화 전에 적용되어 소계 필터에 부적합하다."},{"t":"input","k":"소계 의미","q":"집계 그룹화 결과에서 소계를 나타내는 컬럼 값은 무엇으로 표시되는가? (영문 키워드)","a":["NULL"],"ex":"ROLLUP/CUBE의 소계·총계 행에서 묶인 컬럼은 NULL로 표시되며 '해당 컬럼의 모든 값'을 의미한다."}],"th":{"sum":"`ROLLUP`은 소계·총계를 계층적으로 추가하고, `CUBE`는 모든 조합의 소계를, `GROUPING SETS`는 원하는 집합만 만든다.","body":[{"h":"ROLLUP","t":"`ROLLUP(region, product)`은 (region,product)+region별 소계+전체 총계를 낸다. n개 컬럼 ROLLUP은 n+1개 그룹화 집합을 만든다. 소계·총계 행에서 해당 그룹 컬럼은 NULL로 표시되며, MySQL은 `GROUP BY region, product WITH ROLLUP` 문법을 쓴다. 총계 행은 항상 1개다."},{"h":"CUBE와 GROUPING","t":"`CUBE(a,b)`는 (a,b),(a),(b),()의 모든 부분집합 조합, 즉 2^n개(여기선 4개) 집합을 만든다. `GROUPING(컬럼)` 함수는 그 NULL이 실제 NULL인지 소계로 인한 NULL인지 구분해주며, `HAVING`으로 특정 집계 수준만 걸러낼 수 있다."}],"code":{"c":"SELECT region, product, SUM(sales)\nFROM t\nGROUP BY region, product WITH ROLLUP;","cap":"상세+region 소계+총계를 한 번에(MySQL ROLLUP)"},"key":["ROLLUP(n컬럼)=n+1개 집합, 총계 1행","CUBE(n컬럼)=2^n개 모든 조합","소계 컬럼은 NULL, `GROUPING`으로 구분"]}}]},{"t":"EXISTS와 정량 비교","l":[{"t":"EXISTS vs IN","q":[{"t":"choice","k":"EXISTS","q":"EXISTS 서브쿼리가 TRUE를 반환하는 조건은?","o":["서브쿼리가 최소 한 행이라도 반환할 때","서브쿼리가 정확히 한 행을 반환할 때","서브쿼리가 NULL을 반환할 때","서브쿼리의 모든 행이 조건을 만족할 때"],"a":0,"ex":"EXISTS는 서브쿼리 결과에 행이 하나라도 있으면 TRUE다. 실제 값이나 행 수는 무관해 흔히 SELECT 1을 쓴다."},{"t":"choice","k":"안전한 대안","q":"NULL이 섞일 수 있는 서브쿼리에서 '~에 없는' 조건을 안전하게 쓰려면?","o":["NOT EXISTS를 사용한다","NOT IN을 사용한다","!= ALL을 사용한다","&lt;&gt; ANY를 사용한다"],"a":0,"ex":"NOT EXISTS는 NULL에 안전하다. 상관 조건이 매칭되는 행의 존재 여부만 보므로 NULL이 있어도 논리가 무너지지 않는다."}],"th":{"sum":"`EXISTS`는 서브쿼리에 **행이 하나라도 있으면 TRUE**이고 첫 행에서 멈춘다. NULL 섞인 '없음' 조건은 `NOT IN` 대신 `NOT EXISTS`로.","body":[{"h":"EXISTS vs IN","t":"`EXISTS`는 존재 여부만 보므로 SELECT 절에 `1`이든 `*`이든 결과가 같다. 매칭되는 첫 행을 찾으면 즉시 참이 된다. 서브쿼리 결과에 NULL이 섞이면 `NOT IN`은 전체가 UNKNOWN이 되어 위험하니 `NOT EXISTS`가 안전하다."},{"h":"상관 서브쿼리와 ANY/ALL","t":"상관 서브쿼리는 바깥 행 값을 참조해 행마다 재평가된다. '주문이 하나도 없는 고객'은 `NOT EXISTS (SELECT 1 FROM orders WHERE orders.cid=c.id)`가 정석이다. `> ANY`는 하나라도 크면 참, `> ALL`은 모두보다 커야 참이며 스칼라 서브쿼리는 단일 값을 반환해 비교식에 직접 쓴다."}],"code":{"c":"SELECT c.name\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o\n  WHERE o.customer_id = c.id\n);","cap":"주문이 하나도 없는 고객 찾기"},"key":["`EXISTS`=행 존재 시 TRUE, 첫 행에서 단락","NULL 섞인 '없음'은 `NOT EXISTS`로","`ANY`=하나라도, `ALL`=모두 만족"]}},{"t":"NOT EXISTS와 상관 서브쿼리","q":[{"t":"choice","k":"상관","q":"상관(correlated) 서브쿼리의 특징은?","o":["외부 쿼리의 각 행 값을 참조하며 행마다 평가된다","외부 쿼리와 무관하게 한 번만 실행된다","반드시 GROUP BY를 포함한다","항상 스칼라 값 하나만 반환한다"],"a":0,"ex":"상관 서브쿼리는 외부 쿼리의 컬럼을 참조하므로 외부 각 행마다 다시 평가된다. EXISTS와 자주 결합된다."},{"t":"input","k":"안티조인","q":"NOT EXISTS로 구현하는, 한쪽에만 있고 다른 쪽에는 없는 행을 찾는 조인 패턴의 이름은? (영문)","a":["anti join","antijoin","anti-join"],"ex":"NOT EXISTS(또는 LEFT JOIN ... IS NULL)로 구현하는 패턴을 anti join(안티 조인)이라 한다."},{"t":"choice","k":"동등 변환","q":"WHERE x IN (SELECT y FROM t)와 논리적으로 동등한 EXISTS 형태는?","o":["WHERE EXISTS (SELECT 1 FROM t WHERE t.y = x)","WHERE EXISTS (SELECT 1 FROM t WHERE t.y &lt;&gt; x)","WHERE NOT EXISTS (SELECT 1 FROM t WHERE t.y = x)","WHERE EXISTS (SELECT x FROM t)"],"a":0,"ex":"IN은 상관 EXISTS로 바꿀 수 있다. x IN (SELECT y ...)는 EXISTS(... WHERE y = x)와 같다. 단 NOT 형태로 바꿀 때는 NULL 처리에 주의한다."}],"th":{"sum":"`EXISTS`는 서브쿼리에 **행이 하나라도 있으면 TRUE**이고 첫 행에서 멈춘다. NULL 섞인 '없음' 조건은 `NOT IN` 대신 `NOT EXISTS`로.","body":[{"h":"EXISTS vs IN","t":"`EXISTS`는 존재 여부만 보므로 SELECT 절에 `1`이든 `*`이든 결과가 같다. 매칭되는 첫 행을 찾으면 즉시 참이 된다. 서브쿼리 결과에 NULL이 섞이면 `NOT IN`은 전체가 UNKNOWN이 되어 위험하니 `NOT EXISTS`가 안전하다."},{"h":"상관 서브쿼리와 ANY/ALL","t":"상관 서브쿼리는 바깥 행 값을 참조해 행마다 재평가된다. '주문이 하나도 없는 고객'은 `NOT EXISTS (SELECT 1 FROM orders WHERE orders.cid=c.id)`가 정석이다. `> ANY`는 하나라도 크면 참, `> ALL`은 모두보다 커야 참이며 스칼라 서브쿼리는 단일 값을 반환해 비교식에 직접 쓴다."}],"code":{"c":"SELECT c.name\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o\n  WHERE o.customer_id = c.id\n);","cap":"주문이 하나도 없는 고객 찾기"},"key":["`EXISTS`=행 존재 시 TRUE, 첫 행에서 단락","NULL 섞인 '없음'은 `NOT EXISTS`로","`ANY`=하나라도, `ALL`=모두 만족"]}},{"t":"ANY / ALL과 스칼라 서브쿼리","q":[{"t":"choice","k":"= ANY","q":"x = ANY (SELECT ...)와 동등한 연산자는?","o":["x IN (SELECT ...)","x = ALL (SELECT ...)","x NOT IN (SELECT ...)","EXISTS (SELECT ...)"],"a":0,"ex":"= ANY는 서브쿼리 값들 중 하나라도 같으면 참이므로 IN과 동등하다. SOME은 ANY의 동의어다."},{"t":"input","k":"gt ANY 개수","q":"t.v={10,20,30}, s.x={5,15,35}일 때 x &gt; ANY(...) 조건을 만족하는 x는 몇 개?","code":"-- t.v: 10, 20, 30\nSELECT x FROM s\nWHERE x &gt; ANY (SELECT v FROM t);","a":["2"],"ex":"&gt; ANY는 최솟값 10보다 크면 참이다. 15와 35가 만족하므로 2개다(5는 제외)."},{"t":"input","k":"gt ALL 개수","q":"같은 데이터(t.v 최댓값=30, s.x={5,15,35})에서 x &gt; ALL (SELECT v FROM t)를 만족하는 x는 몇 개?","a":["1"],"ex":"&gt; ALL은 최댓값 30보다 커야 한다. 35만 만족하므로 1개다."}],"th":{"sum":"`EXISTS`는 서브쿼리에 **행이 하나라도 있으면 TRUE**이고 첫 행에서 멈춘다. NULL 섞인 '없음' 조건은 `NOT IN` 대신 `NOT EXISTS`로.","body":[{"h":"EXISTS vs IN","t":"`EXISTS`는 존재 여부만 보므로 SELECT 절에 `1`이든 `*`이든 결과가 같다. 매칭되는 첫 행을 찾으면 즉시 참이 된다. 서브쿼리 결과에 NULL이 섞이면 `NOT IN`은 전체가 UNKNOWN이 되어 위험하니 `NOT EXISTS`가 안전하다."},{"h":"상관 서브쿼리와 ANY/ALL","t":"상관 서브쿼리는 바깥 행 값을 참조해 행마다 재평가된다. '주문이 하나도 없는 고객'은 `NOT EXISTS (SELECT 1 FROM orders WHERE orders.cid=c.id)`가 정석이다. `> ANY`는 하나라도 크면 참, `> ALL`은 모두보다 커야 참이며 스칼라 서브쿼리는 단일 값을 반환해 비교식에 직접 쓴다."}],"code":{"c":"SELECT c.name\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o\n  WHERE o.customer_id = c.id\n);","cap":"주문이 하나도 없는 고객 찾기"},"key":["`EXISTS`=행 존재 시 TRUE, 첫 행에서 단락","NULL 섞인 '없음'은 `NOT EXISTS`로","`ANY`=하나라도, `ALL`=모두 만족"]}}]},{"t":"그룹별 상위 N","l":[{"t":"순위 함수 3형제","q":[{"t":"choice","k":"동점 처리","q":"점수 90, 90, 80 순서로 정렬할 때 RANK()가 매기는 순위는?","o":["1, 2, 3","1, 1, 3","1, 1, 2","1, 2, 2"],"a":1,"ex":"RANK()는 동점에 같은 순위를 주고 다음 순위를 건너뜁니다. 90,90은 둘 다 1위, 80은 3위(2위 건너뜀)."},{"t":"choice","k":"DENSE_RANK","q":"같은 데이터(90, 90, 80)에 DENSE_RANK()를 쓰면?","o":["1, 1, 3","1, 2, 3","1, 1, 2","1, 2, 2"],"a":2,"ex":"DENSE_RANK()는 동점에 같은 순위를 주되 순위를 건너뛰지 않습니다. 90,90은 1위, 80은 2위."},{"t":"input","k":"값 채우기","q":"점수 100, 100, 95, 90에 DENSE_RANK()를 매기면 95의 순위 값은? (숫자만)","a":["2"],"ex":"100,100은 1위, 95는 건너뜀 없이 2위. RANK()였다면 3위가 됩니다."}],"th":{"sum":"동점 처리는 `RANK`(gap 있음), `DENSE_RANK`(gap 없음), `ROW_NUMBER`(무조건 연속)로 갈린다. 그룹별 순위는 `PARTITION BY`로 초기화한다.","body":[{"h":"순위 3형제","t":"90,90,80이면 `RANK`=1,1,3, `DENSE_RANK`=1,1,2, `ROW_NUMBER`=1,2,3이다. 100,100,95,90에 `DENSE_RANK`를 쓰면 95는 2위다. 상위 3개를 뽑되 3위 동점을 모두 포함하려면 `RANK`(또는 DENSE_RANK) `<= 3`을 쓴다."},{"h":"PARTITION BY로 그룹별 상위 N","t":"부서별로 순위를 각각 1부터 다시 매기려면 `OVER (PARTITION BY dept ORDER BY salary DESC)`를 쓴다. 빈칸엔 `PARTITION BY` 두 단어가 들어간다. 보통 CTE로 순위를 매긴 뒤 `WHERE rnk <= N`으로 그룹별 상위 N을 뽑는다."}],"code":{"c":"SELECT * FROM (\n  SELECT name, dept, salary,\n         RANK() OVER (PARTITION BY dept\n                      ORDER BY salary DESC) AS rnk\n  FROM emp\n) t\nWHERE rnk <= 3;","cap":"부서별 급여 상위 3위(동점 포함)"},"key":["RANK 1,1,3 / DENSE_RANK 1,1,2 / ROW_NUMBER 1,2,3","동점 포함 상위 N은 RANK ≤ N","그룹별 재순위는 `PARTITION BY`"]}},{"t":"PARTITION BY로 그룹별 순위","q":[{"t":"choice","k":"PARTITION 역할","q":"부서별로 급여 순위를 각각 1부터 다시 매기려면 무엇을 써야 하나?","o":["GROUP BY dept","PARTITION BY dept","ORDER BY dept","HAVING dept"],"a":1,"ex":"윈도우 함수에서 PARTITION BY dept는 부서마다 순위를 1부터 리셋합니다. GROUP BY와 달리 행이 사라지지 않습니다."},{"t":"input","k":"빈칸 채우기","q":"부서별 급여 내림차순 순위: ROW_NUMBER() OVER (____ dept ORDER BY salary DESC). 빈칸에 들어갈 키워드 2단어는?","a":["PARTITION BY","partition by"],"ex":"PARTITION BY dept로 부서별로 나누고 그 안에서 salary 내림차순으로 번호를 매깁니다."},{"t":"choice","k":"결과 예측","q":"부서 A: 300, 300, 250 급여에 ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC)를 쓰면 250의 번호는?","o":["1","2","3","예측 불가"],"a":2,"ex":"300,300에 1,2가 (임의로) 배정되고 250은 3번. ROW_NUMBER는 동점이어도 연속 번호라 250은 항상 마지막인 3."},{"t":"choice","k":"정렬 필수","q":"순위 함수에서 반드시 필요한 절은?","o":["PARTITION BY","ORDER BY","FILTER","DISTINCT"],"a":1,"ex":"순위는 정렬 기준이 있어야 정해지므로 ORDER BY가 필수입니다. PARTITION BY는 선택(없으면 전체가 한 그룹)."}],"th":{"sum":"동점 처리는 `RANK`(gap 있음), `DENSE_RANK`(gap 없음), `ROW_NUMBER`(무조건 연속)로 갈린다. 그룹별 순위는 `PARTITION BY`로 초기화한다.","body":[{"h":"순위 3형제","t":"90,90,80이면 `RANK`=1,1,3, `DENSE_RANK`=1,1,2, `ROW_NUMBER`=1,2,3이다. 100,100,95,90에 `DENSE_RANK`를 쓰면 95는 2위다. 상위 3개를 뽑되 3위 동점을 모두 포함하려면 `RANK`(또는 DENSE_RANK) `<= 3`을 쓴다."},{"h":"PARTITION BY로 그룹별 상위 N","t":"부서별로 순위를 각각 1부터 다시 매기려면 `OVER (PARTITION BY dept ORDER BY salary DESC)`를 쓴다. 빈칸엔 `PARTITION BY` 두 단어가 들어간다. 보통 CTE로 순위를 매긴 뒤 `WHERE rnk <= N`으로 그룹별 상위 N을 뽑는다."}],"code":{"c":"SELECT * FROM (\n  SELECT name, dept, salary,\n         RANK() OVER (PARTITION BY dept\n                      ORDER BY salary DESC) AS rnk\n  FROM emp\n) t\nWHERE rnk <= 3;","cap":"부서별 급여 상위 3위(동점 포함)"},"key":["RANK 1,1,3 / DENSE_RANK 1,1,2 / ROW_NUMBER 1,2,3","동점 포함 상위 N은 RANK ≤ N","그룹별 재순위는 `PARTITION BY`"]}},{"t":"상위 N 뽑기와 중복 제거","q":[{"t":"choice","k":"CTE 패턴","q":"그룹별 상위 N을 뽑는 표준 패턴은?","o":["WHERE절에서 바로 ROW_NUMBER()&lt;=N","CTE로 rn 계산 후 바깥에서 rn&lt;=N 필터","GROUP BY로 상위 N","ORDER BY LIMIT N만"],"a":1,"ex":"윈도우 함수는 WHERE에서 바로 못 씁니다. CTE/서브쿼리에서 rn을 계산한 뒤 바깥 쿼리에서 WHERE rn&lt;=N으로 거릅니다.","code":"WITH ranked AS (\n  SELECT *, ROW_NUMBER() OVER (\n    PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM emp)\nSELECT * FROM ranked WHERE rn &lt;= 3;"},{"t":"input","k":"dedup 조건","q":"위 dedup에서 각 그룹의 첫 행만 남기려면 바깥 쿼리 조건은 rn = ? (숫자만)","a":["1"],"ex":"ROW_NUMBER는 1부터 시작하므로 rn = 1이 각 파티션의 대표(최신) 행입니다."},{"t":"choice","k":"QUALIFY","q":"일부 DB(Snowflake, BigQuery 등)에서 CTE 없이 윈도우 함수 결과를 바로 필터하는 절은?","o":["HAVING","QUALIFY","WITHIN","OVER"],"a":1,"ex":"QUALIFY rn &lt;= 3 처럼 윈도우 함수 결과를 서브쿼리 없이 걸러줍니다. 표준 SQL은 아니지만 분석 DB에서 매우 유용합니다.","code":"SELECT *,\n  ROW_NUMBER() OVER (PARTITION BY dept\n    ORDER BY salary DESC) AS rn\nFROM emp\nQUALIFY rn &lt;= 3;"}],"th":{"sum":"동점 처리는 `RANK`(gap 있음), `DENSE_RANK`(gap 없음), `ROW_NUMBER`(무조건 연속)로 갈린다. 그룹별 순위는 `PARTITION BY`로 초기화한다.","body":[{"h":"순위 3형제","t":"90,90,80이면 `RANK`=1,1,3, `DENSE_RANK`=1,1,2, `ROW_NUMBER`=1,2,3이다. 100,100,95,90에 `DENSE_RANK`를 쓰면 95는 2위다. 상위 3개를 뽑되 3위 동점을 모두 포함하려면 `RANK`(또는 DENSE_RANK) `<= 3`을 쓴다."},{"h":"PARTITION BY로 그룹별 상위 N","t":"부서별로 순위를 각각 1부터 다시 매기려면 `OVER (PARTITION BY dept ORDER BY salary DESC)`를 쓴다. 빈칸엔 `PARTITION BY` 두 단어가 들어간다. 보통 CTE로 순위를 매긴 뒤 `WHERE rnk <= N`으로 그룹별 상위 N을 뽑는다."}],"code":{"c":"SELECT * FROM (\n  SELECT name, dept, salary,\n         RANK() OVER (PARTITION BY dept\n                      ORDER BY salary DESC) AS rnk\n  FROM emp\n) t\nWHERE rnk <= 3;","cap":"부서별 급여 상위 3위(동점 포함)"},"key":["RANK 1,1,3 / DENSE_RANK 1,1,2 / ROW_NUMBER 1,2,3","동점 포함 상위 N은 RANK ≤ N","그룹별 재순위는 `PARTITION BY`"]}}]},{"t":"피벗과 조건부 집계","l":[{"t":"CASE로 행을 열로","q":[{"t":"input","k":"결과 계산","q":"행: (A,1월,100),(A,1월,50),(A,2월,80). SUM(CASE WHEN month=1 THEN amount ELSE 0 END)의 A 값은? (숫자만)","a":["150"],"ex":"1월 행 100+50=150, 2월 행은 ELSE 0이라 무시. jan 열은 150이 됩니다."},{"t":"choice","k":"GROUP BY 필요","q":"제품별 크로스탭을 만들 때 반드시 필요한 절은?","o":["ORDER BY product","GROUP BY product","PARTITION BY product","HAVING product"],"a":1,"ex":"제품마다 한 행으로 접으려면 GROUP BY product가 필요합니다. 그래야 각 제품의 월별 합이 한 행에 모입니다."}],"th":{"sum":"피벗은 `SUM(CASE WHEN 조건 THEN 값 ELSE 0 END)`로 **행을 열로** 바꾼다. 조건부 카운트는 `COUNT(CASE WHEN ... THEN 1 END)`을 쓰되 ELSE 생략이 핵심이다.","body":[{"h":"CASE로 피벗","t":"월별 매출을 가로 열로 만들려면 1월 열은 `SUM(CASE WHEN month=1 THEN amount ELSE 0 END)`이다. (A,1월,100),(A,1월,50),(A,2월,80)에서 이 식의 A값은 150이다. 크로스탭(cross tab)은 이렇게 한 축을 열로 펼친 요약표이며 보통 `GROUP BY`가 필수다."},{"h":"조건부 카운트와 FILTER","t":"`COUNT(CASE WHEN status='paid' THEN 1 END)`은 조건에 맞는 행만 센다. `COUNT`는 NULL을 안 세므로 ELSE를 생략하면 불일치 행이 NULL이 되어 자동 제외된다. paid,paid,void,paid면 결과는 3. 표준 SQL/Postgres는 `COUNT(*) FILTER (WHERE status='paid')`로 더 명확히 쓸 수 있다."}],"code":{"c":"SELECT customer,\n  SUM(CASE WHEN month = 1 THEN amount ELSE 0 END) AS jan,\n  SUM(CASE WHEN month = 2 THEN amount ELSE 0 END) AS feb\nFROM sales\nGROUP BY customer;","cap":"CASE로 월별 매출을 열로 피벗"},"key":["피벗=`SUM(CASE WHEN ... THEN ... ELSE 0 END)`","조건부 카운트는 ELSE 생략(NULL은 안 셈)","표준 대안은 `FILTER (WHERE ...)`"]}},{"t":"COUNT와 조건부 비율","q":[{"t":"choice","k":"COUNT 주의","q":"조건에 맞는 행만 세려고 COUNT(CASE WHEN status='paid' THEN 1 END)를 쓴다. ELSE를 생략하면?","o":["오류가 난다","조건 불일치는 NULL이 되어 COUNT에서 제외된다","0으로 세어진다","전체가 세어진다"],"a":1,"ex":"ELSE 없으면 불일치 행은 NULL. COUNT는 NULL을 세지 않으므로 정확히 paid 건수만 셉니다. ELSE 0을 쓰면 COUNT가 전부 세어 틀립니다."},{"t":"input","k":"건수 계산","q":"status가 paid, paid, void, paid 일 때 COUNT(CASE WHEN status='paid' THEN 1 END) 값은? (숫자만)","a":["3"],"ex":"paid 3건은 1, void는 NULL. COUNT가 NULL을 무시해 결과는 3입니다."},{"t":"input","k":"비율 계산","q":"값이 1,0,1,1,0 일 때 AVG(값)은? (소수로, 예: 0.6)","a":["0.6"],"ex":"합 3, 개수 5, 3/5=0.6. 즉 60%가 1(참)이라는 비율을 뜻합니다."}],"th":{"sum":"피벗은 `SUM(CASE WHEN 조건 THEN 값 ELSE 0 END)`로 **행을 열로** 바꾼다. 조건부 카운트는 `COUNT(CASE WHEN ... THEN 1 END)`을 쓰되 ELSE 생략이 핵심이다.","body":[{"h":"CASE로 피벗","t":"월별 매출을 가로 열로 만들려면 1월 열은 `SUM(CASE WHEN month=1 THEN amount ELSE 0 END)`이다. (A,1월,100),(A,1월,50),(A,2월,80)에서 이 식의 A값은 150이다. 크로스탭(cross tab)은 이렇게 한 축을 열로 펼친 요약표이며 보통 `GROUP BY`가 필수다."},{"h":"조건부 카운트와 FILTER","t":"`COUNT(CASE WHEN status='paid' THEN 1 END)`은 조건에 맞는 행만 센다. `COUNT`는 NULL을 안 세므로 ELSE를 생략하면 불일치 행이 NULL이 되어 자동 제외된다. paid,paid,void,paid면 결과는 3. 표준 SQL/Postgres는 `COUNT(*) FILTER (WHERE status='paid')`로 더 명확히 쓸 수 있다."}],"code":{"c":"SELECT customer,\n  SUM(CASE WHEN month = 1 THEN amount ELSE 0 END) AS jan,\n  SUM(CASE WHEN month = 2 THEN amount ELSE 0 END) AS feb\nFROM sales\nGROUP BY customer;","cap":"CASE로 월별 매출을 열로 피벗"},"key":["피벗=`SUM(CASE WHEN ... THEN ... ELSE 0 END)`","조건부 카운트는 ELSE 생략(NULL은 안 셈)","표준 대안은 `FILTER (WHERE ...)`"]}},{"t":"FILTER 절과 다중 집계","q":[{"t":"choice","k":"동등 변환","q":"COUNT(*) FILTER (WHERE x&gt;0) 과 결과가 같은 CASE 표현은?","o":["COUNT(CASE WHEN x&gt;0 THEN 1 END)","SUM(CASE WHEN x&gt;0 THEN 0 END)","COUNT(CASE WHEN x&gt;0 THEN 0 ELSE 1 END)","COUNT(*)"],"a":0,"ex":"FILTER는 조건에 맞는 행만 남겨 세므로 COUNT(CASE WHEN x&gt;0 THEN 1 END)과 동일합니다(불일치는 NULL로 제외)."},{"t":"input","k":"결과 계산","q":"amount가 10,20,30 이고 status가 paid,void,paid 일 때 SUM(amount) FILTER (WHERE status='paid') 값은? (숫자만)","a":["40"],"ex":"paid 행은 10과 30 → 10+30=40. void(20)는 FILTER에서 제외됩니다."}],"th":{"sum":"피벗은 `SUM(CASE WHEN 조건 THEN 값 ELSE 0 END)`로 **행을 열로** 바꾼다. 조건부 카운트는 `COUNT(CASE WHEN ... THEN 1 END)`을 쓰되 ELSE 생략이 핵심이다.","body":[{"h":"CASE로 피벗","t":"월별 매출을 가로 열로 만들려면 1월 열은 `SUM(CASE WHEN month=1 THEN amount ELSE 0 END)`이다. (A,1월,100),(A,1월,50),(A,2월,80)에서 이 식의 A값은 150이다. 크로스탭(cross tab)은 이렇게 한 축을 열로 펼친 요약표이며 보통 `GROUP BY`가 필수다."},{"h":"조건부 카운트와 FILTER","t":"`COUNT(CASE WHEN status='paid' THEN 1 END)`은 조건에 맞는 행만 센다. `COUNT`는 NULL을 안 세므로 ELSE를 생략하면 불일치 행이 NULL이 되어 자동 제외된다. paid,paid,void,paid면 결과는 3. 표준 SQL/Postgres는 `COUNT(*) FILTER (WHERE status='paid')`로 더 명확히 쓸 수 있다."}],"code":{"c":"SELECT customer,\n  SUM(CASE WHEN month = 1 THEN amount ELSE 0 END) AS jan,\n  SUM(CASE WHEN month = 2 THEN amount ELSE 0 END) AS feb\nFROM sales\nGROUP BY customer;","cap":"CASE로 월별 매출을 열로 피벗"},"key":["피벗=`SUM(CASE WHEN ... THEN ... ELSE 0 END)`","조건부 카운트는 ELSE 생략(NULL은 안 셈)","표준 대안은 `FILTER (WHERE ...)`"]}}]},{"t":"시계열·비율 분석","l":[{"t":"전월 대비와 성장률","q":[{"t":"choice","k":"이전 값","q":"월별 매출에서 '직전 월' 값을 같은 행에 가져오는 함수는?","o":["LEAD()","LAG()","FIRST_VALUE()","SUM()"],"a":1,"ex":"LAG(amount) OVER (ORDER BY month)는 한 행 앞(이전 월)의 값을 가져옵니다. LEAD는 다음 행을 봅니다."},{"t":"choice","k":"증감 계산","q":"전월 대비 증감액을 구하는 식은?","o":["amount - LAG(amount) OVER (ORDER BY month)","amount - LEAD(amount) OVER (ORDER BY month)","amount / SUM(amount)","LAG(amount) - amount"],"a":0,"ex":"이번 달 - 이전 달(LAG)이 증감액입니다. LAG를 빼는 순서가 반대면 부호가 뒤집힙니다.","code":"SELECT month, amount,\n  amount - LAG(amount) OVER (ORDER BY month)\n    AS mom_diff\nFROM monthly;"},{"t":"input","k":"성장률 계산","q":"이전 달 200, 이번 달 250일 때 성장률 (이번-이전)/이전 은 몇 %? (숫자만, 예: 25)","a":["25"],"ex":"(250-200)/200 = 50/200 = 0.25 = 25%. 성장률은 항상 '이전 값'으로 나눕니다."},{"t":"choice","k":"첫 행 NULL","q":"LAG로 전월 대비를 구하면 가장 첫 달의 값이 NULL인 이유는?","o":["이전 행이 없어서","정렬이 틀려서","0으로 나눠서","PARTITION이 없어서"],"a":0,"ex":"첫 행은 앞 행이 없어 LAG가 NULL을 반환합니다. LAG(amount,1,0)처럼 기본값을 주거나 COALESCE로 처리합니다."},{"t":"choice","k":"그룹별 시계열","q":"제품마다 전월 대비를 각각 구하려면 무엇을 추가하나?","o":["PARTITION BY product","GROUP BY month","DISTINCT product","HAVING product"],"a":0,"ex":"LAG(amount) OVER (PARTITION BY product ORDER BY month)로 제품별로 시계열을 분리해 각 제품의 이전 월을 봅니다."}],"th":{"sum":"전월 대비는 `LAG`로 직전 값을 당겨 `현재 - LAG(값)`으로 구한다. 첫 행은 이전이 없어 NULL. 누적합·이동평균은 윈도우 프레임으로 계산한다.","body":[{"h":"전월 대비와 성장률","t":"`LAG(rev,1) OVER(ORDER BY mon)`으로 직전 월을 가져와 증감액 `rev - LAG(rev)`, 성장률 `(현재-이전)/이전`을 낸다. 200→250이면 성장률 25%다. 첫 달은 직전 행이 없어 LAG가 NULL이다. 제품마다 각각 구하려면 `PARTITION BY product`를 추가한다."},{"h":"누적합과 이동평균","t":"날짜순 누적합은 `SUM(x) OVER(ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)`다. 10,20,30이면 3번째 행은 60. 이동평균은 프레임을 `ROWS BETWEEN 2 PRECEDING AND CURRENT ROW`처럼 좁혀 `AVG`를 쓴다. 구성비는 `값/SUM(값) OVER()`로 낸다."}],"code":{"c":"SELECT mon, rev,\n       rev - LAG(rev, 1) OVER (ORDER BY mon) AS diff,\n       SUM(rev) OVER (ORDER BY mon) AS running\nFROM monthly;","cap":"전월 대비 증감과 날짜순 누적합"},"key":["전월값=`LAG`, 첫 행은 NULL","제품별은 `PARTITION BY` 추가","누적합=`SUM() OVER(ORDER BY ...)`"]}},{"t":"누적합과 이동평균","q":[{"t":"choice","k":"누적합","q":"날짜순 running total(누적합)을 구하는 식은?","o":["SUM(amount) OVER (ORDER BY dt)","SUM(amount)","SUM(amount) OVER ()","COUNT(amount) OVER (ORDER BY dt)"],"a":0,"ex":"ORDER BY가 있는 SUM OVER는 기본 프레임이 시작~현재 행이라 누적합이 됩니다.","code":"SELECT dt, amount,\n  SUM(amount) OVER (ORDER BY dt\n    ROWS UNBOUNDED PRECEDING) AS running\nFROM daily;"},{"t":"input","k":"누적 계산","q":"일별 값 10, 20, 30을 날짜순 누적합하면 3번째 행 값은? (숫자만)","a":["60"],"ex":"10, 10+20=30, 30+30=60. 누적합은 현재까지 모두 더한 값이라 마지막은 총합 60."},{"t":"choice","k":"이동평균 프레임","q":"최근 3일 이동평균(당일 포함)을 위한 프레임 절은?","o":["ROWS BETWEEN 2 PRECEDING AND CURRENT ROW","ROWS BETWEEN 3 PRECEDING AND CURRENT ROW","ROWS BETWEEN CURRENT ROW AND 2 FOLLOWING","RANGE UNBOUNDED PRECEDING"],"a":0,"ex":"당일 + 앞 2일 = 3일 창. 2 PRECEDING부터 CURRENT ROW까지가 3개 행이므로 3일 이동평균이 됩니다."},{"t":"input","k":"이동평균 계산","q":"값 10,20,30,40에서 '2 PRECEDING AND CURRENT ROW' 3일 이동평균의 4번째 값은? (숫자만)","a":["30"],"ex":"4번째 창은 20,30,40 → (20+30+40)/3 = 90/3 = 30."}],"th":{"sum":"전월 대비는 `LAG`로 직전 값을 당겨 `현재 - LAG(값)`으로 구한다. 첫 행은 이전이 없어 NULL. 누적합·이동평균은 윈도우 프레임으로 계산한다.","body":[{"h":"전월 대비와 성장률","t":"`LAG(rev,1) OVER(ORDER BY mon)`으로 직전 월을 가져와 증감액 `rev - LAG(rev)`, 성장률 `(현재-이전)/이전`을 낸다. 200→250이면 성장률 25%다. 첫 달은 직전 행이 없어 LAG가 NULL이다. 제품마다 각각 구하려면 `PARTITION BY product`를 추가한다."},{"h":"누적합과 이동평균","t":"날짜순 누적합은 `SUM(x) OVER(ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)`다. 10,20,30이면 3번째 행은 60. 이동평균은 프레임을 `ROWS BETWEEN 2 PRECEDING AND CURRENT ROW`처럼 좁혀 `AVG`를 쓴다. 구성비는 `값/SUM(값) OVER()`로 낸다."}],"code":{"c":"SELECT mon, rev,\n       rev - LAG(rev, 1) OVER (ORDER BY mon) AS diff,\n       SUM(rev) OVER (ORDER BY mon) AS running\nFROM monthly;","cap":"전월 대비 증감과 날짜순 누적합"},"key":["전월값=`LAG`, 첫 행은 NULL","제품별은 `PARTITION BY` 추가","누적합=`SUM() OVER(ORDER BY ...)`"]}},{"t":"구성비와 구간화","q":[{"t":"choice","k":"구성비","q":"각 행의 전체 대비 비율(구성비)을 구하는 식은?","o":["amount / SUM(amount) OVER ()","amount / SUM(amount)","amount / COUNT(*)","SUM(amount) OVER (ORDER BY dt)"],"a":0,"ex":"SUM(amount) OVER () (빈 OVER)는 전체 총합을 모든 행에 붙입니다. 각 amount를 총합으로 나누면 구성비가 됩니다.","code":"SELECT category, amount,\n  1.0 * amount / SUM(amount) OVER () AS pct\nFROM sales;"},{"t":"input","k":"구성비 계산","q":"값 20, 30, 50에서 30인 행의 구성비는? (소수, 예: 0.3)","a":["0.3"],"ex":"총합 20+30+50=100. 30/100=0.3, 즉 30%. OVER ()가 전체 합 100을 제공합니다."},{"t":"choice","k":"NTILE 활용","q":"값을 크기순으로 4등분(사분위)해 그룹 번호를 매기는 함수는?","o":["NTILE(4)","RANK()","ROW_NUMBER()","LAG(4)"],"a":0,"ex":"NTILE(4) OVER (ORDER BY x)는 정렬된 행을 최대한 균등하게 4묶음으로 나눠 1~4 그룹 번호를 부여합니다. 분위수 구간화에 유용."}],"th":{"sum":"전월 대비는 `LAG`로 직전 값을 당겨 `현재 - LAG(값)`으로 구한다. 첫 행은 이전이 없어 NULL. 누적합·이동평균은 윈도우 프레임으로 계산한다.","body":[{"h":"전월 대비와 성장률","t":"`LAG(rev,1) OVER(ORDER BY mon)`으로 직전 월을 가져와 증감액 `rev - LAG(rev)`, 성장률 `(현재-이전)/이전`을 낸다. 200→250이면 성장률 25%다. 첫 달은 직전 행이 없어 LAG가 NULL이다. 제품마다 각각 구하려면 `PARTITION BY product`를 추가한다."},{"h":"누적합과 이동평균","t":"날짜순 누적합은 `SUM(x) OVER(ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)`다. 10,20,30이면 3번째 행은 60. 이동평균은 프레임을 `ROWS BETWEEN 2 PRECEDING AND CURRENT ROW`처럼 좁혀 `AVG`를 쓴다. 구성비는 `값/SUM(값) OVER()`로 낸다."}],"code":{"c":"SELECT mon, rev,\n       rev - LAG(rev, 1) OVER (ORDER BY mon) AS diff,\n       SUM(rev) OVER (ORDER BY mon) AS running\nFROM monthly;","cap":"전월 대비 증감과 날짜순 누적합"},"key":["전월값=`LAG`, 첫 행은 NULL","제품별은 `PARTITION BY` 추가","누적합=`SUM() OVER(ORDER BY ...)`"]}}]},{"t":"SQL 보안","l":[{"t":"SQL Injection 원리","q":[{"t":"input","k":"항상참","q":"WHERE 절을 항상 참으로 만들어 모든 행을 반환시키는 고전적인 주입 문자열을 쓰세요 (OR 사용).","a":["' OR '1'='1","OR '1'='1","' OR 1=1","' or '1'='1"],"ex":"'1'='1' 은 언제나 참이므로 WHERE 조건 전체가 참이 되어 테이블 전체가 노출된다."},{"t":"choice","k":"취약패턴","q":"다음 중 SQL injection에 가장 취약한 코드 패턴은?","o":["입력값을 문자열 연결로 쿼리문에 직접 이어붙인다","프레이스홀더(?)에 입력을 바인딩한다","ORM의 파라미터 바인딩을 쓴다","저장 프로시저에 파라미터로 전달한다"],"a":0,"ex":"문자열 연결(concatenation)로 쿼리를 조립하는 것이 대표적 취약 패턴이다."}],"th":{"sum":"SQL 인젝션은 **입력을 코드와 섞어** 실행할 때 생긴다. 근본 방어는 값을 코드가 아닌 데이터로 취급하는 **파라미터화(prepared statement)**다.","body":[{"h":"원리","t":"사용자 입력을 쿼리 문자열에 직접 이어붙이면 입력이 SQL 구문으로 해석될 수 있다. `admin' --`를 넣으면 뒷부분이 주석 처리돼 비밀번호 검사를 건너뛴다. `' OR '1'='1`은 WHERE를 항상 참으로 만들어 전체 행을 반환시킨다. UNION 기반 인젝션은 다른 테이블 데이터를 결과에 끼워 탈취를 노린다. 문자열 연결(concatenation) 패턴이 가장 취약하다."},{"h":"방어","t":"가장 확실한 방어는 파라미터 바인딩이다. prepared statement는 쿼리 구조를 먼저 컴파일하고 입력을 순수 값으로 바인딩해, 입력에 따옴표·주석이 있어도 구문으로 해석되지 않는다. 여기에 최소 권한 계정, 입력 검증, 민감정보 해시·암호화 저장을 더한다."}],"code":{"c":"-- 안전: 파라미터 바인딩\nPREPARE s FROM 'SELECT * FROM users WHERE id = ?';\nSET @id = 42;\nEXECUTE s USING @id;","cap":"입력을 값으로 바인딩해 인젝션 차단"},"key":["원인=입력을 코드와 섞어 실행(문자열 연결)","`' OR '1'='1`은 WHERE를 항상 참으로","근본 방어=prepared statement(값 바인딩)+최소 권한"]}},{"t":"방어: 파라미터화와 최소 권한","q":[{"t":"choice","k":"근본방어","q":"SQL injection의 가장 근본적이고 확실한 방어책은?","o":["파라미터화 쿼리(prepared statement) 사용","입력에서 작은따옴표만 제거","WAF에만 의존","쿼리를 대문자로 작성"],"a":0,"ex":"파라미터화는 데이터와 코드를 분리해 입력이 SQL 코드로 해석되지 않게 한다. 블랙리스트 필터링은 우회가 가능하다."},{"t":"input","k":"플레이스홀더","q":"많은 드라이버에서 파라미터 자리표시자로 쓰는 물음표 기호 하나는? (기호)","a":["?","물음표"],"ex":"WHERE id = ? 처럼 ? 자리에 값을 바인딩한다. Postgres는 $1, 명명형은 :name 도 쓴다."},{"t":"input","k":"권한부여","q":"특정 테이블에 대한 조회 권한을 사용자에게 주는 DCL 키워드는?","a":["GRANT","grant"],"ex":"GRANT SELECT ON orders TO app_user; 회수는 REVOKE로 한다."}],"th":{"sum":"SQL 인젝션은 **입력을 코드와 섞어** 실행할 때 생긴다. 근본 방어는 값을 코드가 아닌 데이터로 취급하는 **파라미터화(prepared statement)**다.","body":[{"h":"원리","t":"사용자 입력을 쿼리 문자열에 직접 이어붙이면 입력이 SQL 구문으로 해석될 수 있다. `admin' --`를 넣으면 뒷부분이 주석 처리돼 비밀번호 검사를 건너뛴다. `' OR '1'='1`은 WHERE를 항상 참으로 만들어 전체 행을 반환시킨다. UNION 기반 인젝션은 다른 테이블 데이터를 결과에 끼워 탈취를 노린다. 문자열 연결(concatenation) 패턴이 가장 취약하다."},{"h":"방어","t":"가장 확실한 방어는 파라미터 바인딩이다. prepared statement는 쿼리 구조를 먼저 컴파일하고 입력을 순수 값으로 바인딩해, 입력에 따옴표·주석이 있어도 구문으로 해석되지 않는다. 여기에 최소 권한 계정, 입력 검증, 민감정보 해시·암호화 저장을 더한다."}],"code":{"c":"-- 안전: 파라미터 바인딩\nPREPARE s FROM 'SELECT * FROM users WHERE id = ?';\nSET @id = 42;\nEXECUTE s USING @id;","cap":"입력을 값으로 바인딩해 인젝션 차단"},"key":["원인=입력을 코드와 섞어 실행(문자열 연결)","`' OR '1'='1`은 WHERE를 항상 참으로","근본 방어=prepared statement(값 바인딩)+최소 권한"]}},{"t":"접근 제어와 민감정보 저장","q":[{"t":"choice","k":"권한회수","q":"이미 부여한 권한을 거두어들이는 명령은?","o":["REVOKE","DELETE","TRUNCATE","ROLLBACK"],"a":0,"ex":"REVOKE SELECT ON orders FROM app_user; 는 GRANT의 반대 동작이다."},{"t":"input","k":"솔트","q":"같은 비밀번호라도 해시값이 달라지게 하고 레인보우 테이블 공격을 막기 위해 각 비밀번호에 더하는 무작위 값은? (영단어)","a":["salt","솔트"],"ex":"사용자마다 다른 salt를 붙여 해시하면 같은 비밀번호도 서로 다른 해시가 되어 사전·레인보우 공격에 강해진다."}],"th":{"sum":"SQL 인젝션은 **입력을 코드와 섞어** 실행할 때 생긴다. 근본 방어는 값을 코드가 아닌 데이터로 취급하는 **파라미터화(prepared statement)**다.","body":[{"h":"원리","t":"사용자 입력을 쿼리 문자열에 직접 이어붙이면 입력이 SQL 구문으로 해석될 수 있다. `admin' --`를 넣으면 뒷부분이 주석 처리돼 비밀번호 검사를 건너뛴다. `' OR '1'='1`은 WHERE를 항상 참으로 만들어 전체 행을 반환시킨다. UNION 기반 인젝션은 다른 테이블 데이터를 결과에 끼워 탈취를 노린다. 문자열 연결(concatenation) 패턴이 가장 취약하다."},{"h":"방어","t":"가장 확실한 방어는 파라미터 바인딩이다. prepared statement는 쿼리 구조를 먼저 컴파일하고 입력을 순수 값으로 바인딩해, 입력에 따옴표·주석이 있어도 구문으로 해석되지 않는다. 여기에 최소 권한 계정, 입력 검증, 민감정보 해시·암호화 저장을 더한다."}],"code":{"c":"-- 안전: 파라미터 바인딩\nPREPARE s FROM 'SELECT * FROM users WHERE id = ?';\nSET @id = 42;\nEXECUTE s USING @id;","cap":"입력을 값으로 바인딩해 인젝션 차단"},"key":["원인=입력을 코드와 섞어 실행(문자열 연결)","`' OR '1'='1`은 WHERE를 항상 참으로","근본 방어=prepared statement(값 바인딩)+최소 권한"]}}]},{"t":"JSON과 반정형 데이터","l":[{"t":"JSON 타입과 값 추출","q":[{"t":"choice","k":"추출연산자","q":"MySQL에서 JSON 컬럼 data의 name 값을 따옴표 없이 문자열로 꺼내는 표현으로 옳은 것은?","o":["data-&gt;&gt;'$.name'","data.name","data['name']","GET(data,'name')"],"a":0,"ex":"MySQL에서 -&gt; 는 JSON 값(따옴표 포함), -&gt;&gt; 는 언쿼트된 스칼라를 반환한다. -&gt;&gt;'$.name' 은 JSON_UNQUOTE(JSON_EXTRACT(...))와 같다."},{"t":"input","k":"추출함수","q":"MySQL에서 JSON 경로로 값을 추출하는 대표 함수 이름은? (예: ...(data,'$.path'))","a":["JSON_EXTRACT","json_extract"],"ex":"JSON_EXTRACT(data,'$.name') 은 data-&gt;'$.name' 과 같다. 언쿼트하려면 JSON_UNQUOTE 또는 -&gt;&gt; 를 쓴다."}],"th":{"sum":"관계형 DB의 `JSON` 컬럼은 반정형 데이터를 저장한다. Postgres는 `->`(JSON 반환)/`->>`(텍스트 반환), MySQL은 `JSON_EXTRACT`로 값을 꺼낸다.","body":[{"h":"타입과 값 추출","t":"Postgres에서 `json`은 원본 텍스트를 그대로 저장(순서·공백 보존), `jsonb`는 이진 파싱본이라 저장은 느려도 조회·인덱싱이 빠르다. `data->'name'`은 JSON 값을, `data->>'name'`은 텍스트를 반환한다. MySQL은 `JSON_EXTRACT(data,'$.name')`, 따옴표 없이 꺼내려면 `->>` 연산자나 `JSON_UNQUOTE`를 쓴다."},{"h":"생성·인덱싱·트레이드오프","t":"MySQL `JSON_OBJECT('k',v)`는 객체를, `JSON_ARRAY(1,2,'a')`는 `[1, 2, \"a\"]` 배열을 만든다. jsonb엔 GIN 인덱스, MySQL은 생성 컬럼(generated column)에 인덱스를 걸 수 있다. 스키마 유연성은 얻지만 제약·조인·집계가 불편하니, 구조가 고정적이면 정규화가 낫다."}],"code":{"c":"-- MySQL\nSELECT JSON_EXTRACT(data, '$.name') AS name_json,\n       data->>'$.name'            AS name_text\nFROM docs;","cap":"JSON 경로로 값 추출(따옴표 유무 차이)"},"key":["Postgres `->`=JSON, `->>`=텍스트","jsonb=이진·인덱싱 유리, json=원본 텍스트","MySQL 추출은 `JSON_EXTRACT`, 생성은 `JSON_OBJECT`/`JSON_ARRAY`"]}},{"t":"JSON 생성·유효성·인덱싱","q":[{"t":"input","k":"객체생성","q":"MySQL에서 키-값 쌍으로 JSON 객체를 만드는 함수 이름은?","a":["JSON_OBJECT","json_object"],"ex":"JSON_OBJECT('id',1,'name','kim') 은 {\"id\":1,\"name\":\"kim\"} 을 만든다. 배열은 JSON_ARRAY."},{"t":"choice","k":"인덱싱","q":"JSON 내부 특정 키로 자주 조회할 때 성능을 위한 올바른 접근은?","o":["Postgres는 jsonb에 GIN 인덱스, 또는 표현식/생성 컬럼에 B-tree 인덱스를 건다","JSON은 절대 인덱싱 불가라 풀스캔만 가능","전체 컬럼을 문자열 LIKE로 검색","인덱스 대신 캐시만 사용"],"a":0,"ex":"Postgres는 jsonb GIN 인덱스(포함 연산 @&gt;)나 (data-&gt;&gt;'k')에 B-tree를, MySQL은 생성 컬럼에 인덱스를 건다."}],"th":{"sum":"관계형 DB의 `JSON` 컬럼은 반정형 데이터를 저장한다. Postgres는 `->`(JSON 반환)/`->>`(텍스트 반환), MySQL은 `JSON_EXTRACT`로 값을 꺼낸다.","body":[{"h":"타입과 값 추출","t":"Postgres에서 `json`은 원본 텍스트를 그대로 저장(순서·공백 보존), `jsonb`는 이진 파싱본이라 저장은 느려도 조회·인덱싱이 빠르다. `data->'name'`은 JSON 값을, `data->>'name'`은 텍스트를 반환한다. MySQL은 `JSON_EXTRACT(data,'$.name')`, 따옴표 없이 꺼내려면 `->>` 연산자나 `JSON_UNQUOTE`를 쓴다."},{"h":"생성·인덱싱·트레이드오프","t":"MySQL `JSON_OBJECT('k',v)`는 객체를, `JSON_ARRAY(1,2,'a')`는 `[1, 2, \"a\"]` 배열을 만든다. jsonb엔 GIN 인덱스, MySQL은 생성 컬럼(generated column)에 인덱스를 걸 수 있다. 스키마 유연성은 얻지만 제약·조인·집계가 불편하니, 구조가 고정적이면 정규화가 낫다."}],"code":{"c":"-- MySQL\nSELECT JSON_EXTRACT(data, '$.name') AS name_json,\n       data->>'$.name'            AS name_text\nFROM docs;","cap":"JSON 경로로 값 추출(따옴표 유무 차이)"},"key":["Postgres `->`=JSON, `->>`=텍스트","jsonb=이진·인덱싱 유리, json=원본 텍스트","MySQL 추출은 `JSON_EXTRACT`, 생성은 `JSON_OBJECT`/`JSON_ARRAY`"]}},{"t":"정규화 vs JSON: 트레이드오프","q":[{"t":"choice","k":"단점","q":"핵심 데이터를 JSON에 몰아넣을 때의 대표적 단점은?","o":["타입 안정성·제약이 약해지고 내부 값 조회가 느리거나 인덱스 설계가 번거롭다","저장 공간을 항상 절반으로 줄인다","조인이 항상 빨라진다","트랜잭션이 불가능해진다"],"a":0,"ex":"JSON은 유연하지만 FK·타입 검증이 약하고 내부 값 접근·인덱싱에 추가 작업이 필요해, 남용하면 성능·무결성에서 손해다."},{"t":"input","k":"원자성","q":"각 컬럼이 원자값을 갖도록 요구하는(한 칸에 여러 값 나열 금지) 정규형은? (예: 1NF)","a":["1NF","제1정규형","1정규형","1"],"ex":"1NF는 각 컬럼이 원자값을 갖도록 요구한다. 배열/JSON 남용은 이 원칙과 충돌할 수 있어 트레이드오프를 고려한다."}],"th":{"sum":"관계형 DB의 `JSON` 컬럼은 반정형 데이터를 저장한다. Postgres는 `->`(JSON 반환)/`->>`(텍스트 반환), MySQL은 `JSON_EXTRACT`로 값을 꺼낸다.","body":[{"h":"타입과 값 추출","t":"Postgres에서 `json`은 원본 텍스트를 그대로 저장(순서·공백 보존), `jsonb`는 이진 파싱본이라 저장은 느려도 조회·인덱싱이 빠르다. `data->'name'`은 JSON 값을, `data->>'name'`은 텍스트를 반환한다. MySQL은 `JSON_EXTRACT(data,'$.name')`, 따옴표 없이 꺼내려면 `->>` 연산자나 `JSON_UNQUOTE`를 쓴다."},{"h":"생성·인덱싱·트레이드오프","t":"MySQL `JSON_OBJECT('k',v)`는 객체를, `JSON_ARRAY(1,2,'a')`는 `[1, 2, \"a\"]` 배열을 만든다. jsonb엔 GIN 인덱스, MySQL은 생성 컬럼(generated column)에 인덱스를 걸 수 있다. 스키마 유연성은 얻지만 제약·조인·집계가 불편하니, 구조가 고정적이면 정규화가 낫다."}],"code":{"c":"-- MySQL\nSELECT JSON_EXTRACT(data, '$.name') AS name_json,\n       data->>'$.name'            AS name_text\nFROM docs;","cap":"JSON 경로로 값 추출(따옴표 유무 차이)"},"key":["Postgres `->`=JSON, `->>`=텍스트","jsonb=이진·인덱싱 유리, json=원본 텍스트","MySQL 추출은 `JSON_EXTRACT`, 생성은 `JSON_OBJECT`/`JSON_ARRAY`"]}}]},{"t":"성능 튜닝 심화","l":[{"t":"조인 알고리즘","q":[{"t":"choice","k":"NestedLoop","q":"Nested Loop Join의 특성으로 옳은 것은?","o":["바깥 테이블의 각 행마다 안쪽 테이블을 조회하며, 안쪽에 인덱스가 있고 결과가 작을 때 유리","항상 두 테이블을 정렬한 뒤 병합","언제나 해시 테이블을 메모리에 만든다","대량-대량 조인에 항상 최적"],"a":0,"ex":"outer 각 행에 대해 inner를 찾는 방식이다. inner 조인 키에 인덱스가 있고 outer가 작으면 효율적이지만, 양쪽이 크면 O(N*M)로 느려진다."},{"t":"input","k":"등가전용","q":"Hash Join이 기본적으로 지원하는 조인 조건 종류를 가리키는 용어는? (= 조건, 영어)","a":["equi","equi-join","등가조인","등가"],"ex":"해시는 키의 동등 비교에 기반하므로 equi-join에만 쓰인다. 범위 조인은 보통 nested loop나 merge를 쓴다."}],"th":{"sum":"조인 알고리즘은 데이터 특성에 따라 나뉜다: **Nested Loop**(작은 셋+인덱스), **Hash Join**(대형 등호), **Sort-Merge**(정렬된 데이터). `EXPLAIN`으로 계획을 확인한다.","body":[{"h":"세 조인 알고리즘","t":"Nested Loop는 바깥 행마다 안쪽을 찾아 작은 셋+인덱스에 최적이나 대량이면 느리다. Hash Join은 한쪽으로 해시 테이블을 만들어 등호(equi-join) 조인 대량 처리에 강하고, 부등호는 기본 지원하지 않는다(지원 조건 용어: equi-join). Sort-Merge는 양쪽을 조인 키로 정렬 후 병합해 이미 정렬됐거나 정렬 인덱스가 있을 때 유리하다. 옵티마이저는 데이터 양·인덱스·통계로 방식을 고른다."},{"h":"실행계획으로 진단","t":"`EXPLAIN`은 어떤 인덱스·조인·스캔을 쓰는지 보여준다. 큰 테이블의 Seq/Full Scan, 예상과 실제 행 수의 큰 괴리, 대량 `Rows Removed by Filter`, 불필요한 정렬 등이 성능 문제 신호다. 이를 보고 인덱스 추가나 쿼리 재작성을 결정한다."}],"code":{"c":"EXPLAIN\nSELECT o.id, c.name\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nWHERE o.status = 'PAID';","cap":"조인·인덱스 사용 계획 확인"},"key":["Nested Loop=작은 셋+인덱스, Hash=대형 equi-join, Sort-Merge=정렬됨","Hash Join은 등호(equi-join) 조건 기반","Full Scan·추정≠실제 행 수는 튜닝 신호"]}},{"t":"실행계획과 인덱스","q":[{"t":"choice","k":"함수적용","q":"WHERE 절 때문에 인덱스를 못 쓰는(비-SARGable) 대표 사례는?","o":["WHERE YEAR(created_at) = 2025 처럼 인덱스 컬럼에 함수를 적용","WHERE created_at &gt;= '2025-01-01'","WHERE id = 10","WHERE name = 'kim'"],"a":0,"ex":"컬럼을 함수로 감싸면 원본 값 기준 인덱스를 못 탄다. created_at &gt;= '2025-01-01' AND &lt; '2026-01-01' 로 바꾸면 SARGable해진다."},{"t":"input","k":"검색가능","q":"인덱스를 활용할 수 있는 형태의 WHERE 조건을 가리키는 용어는? (영어)","a":["SARGable","sargable","SARG","sarg"],"ex":"Search ARGument able의 줄임말. 컬럼을 가공하지 않고 '컬럼 op 값' 형태로 써야 인덱스 탐색이 가능하다."}],"th":{"sum":"조인 알고리즘은 데이터 특성에 따라 나뉜다: **Nested Loop**(작은 셋+인덱스), **Hash Join**(대형 등호), **Sort-Merge**(정렬된 데이터). `EXPLAIN`으로 계획을 확인한다.","body":[{"h":"세 조인 알고리즘","t":"Nested Loop는 바깥 행마다 안쪽을 찾아 작은 셋+인덱스에 최적이나 대량이면 느리다. Hash Join은 한쪽으로 해시 테이블을 만들어 등호(equi-join) 조인 대량 처리에 강하고, 부등호는 기본 지원하지 않는다(지원 조건 용어: equi-join). Sort-Merge는 양쪽을 조인 키로 정렬 후 병합해 이미 정렬됐거나 정렬 인덱스가 있을 때 유리하다. 옵티마이저는 데이터 양·인덱스·통계로 방식을 고른다."},{"h":"실행계획으로 진단","t":"`EXPLAIN`은 어떤 인덱스·조인·스캔을 쓰는지 보여준다. 큰 테이블의 Seq/Full Scan, 예상과 실제 행 수의 큰 괴리, 대량 `Rows Removed by Filter`, 불필요한 정렬 등이 성능 문제 신호다. 이를 보고 인덱스 추가나 쿼리 재작성을 결정한다."}],"code":{"c":"EXPLAIN\nSELECT o.id, c.name\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nWHERE o.status = 'PAID';","cap":"조인·인덱스 사용 계획 확인"},"key":["Nested Loop=작은 셋+인덱스, Hash=대형 equi-join, Sort-Merge=정렬됨","Hash Join은 등호(equi-join) 조건 기반","Full Scan·추정≠실제 행 수는 튜닝 신호"]}},{"t":"쿼리 최적화 패턴","q":[{"t":"choice","k":"키셋페이징","q":"OFFSET 100000 LIMIT 10 같은 깊은 페이지네이션의 문제와 대안은?","o":["OFFSET은 건너뛴 행까지 다 읽어 느리다 → WHERE id &lt; 마지막본id 방식의 키셋(seek) 페이지네이션 사용","OFFSET이 항상 가장 빠르다","LIMIT을 없애면 해결","정렬을 제거하면 해결"],"a":0,"ex":"OFFSET N은 앞의 N행을 스캔·폐기해 뒤로 갈수록 느려진다. 마지막으로 본 키를 기준으로 이어 읽는 키셋 페이지네이션이 일정한 성능을 낸다."},{"t":"input","k":"통계갱신","q":"옵티마이저가 좋은 계획을 세우도록 테이블의 통계정보를 수집·갱신하는 SQL 명령은?","a":["ANALYZE","analyze"],"ex":"ANALYZE로 카디널리티·분포 통계를 갱신하면 옵티마이저 추정이 정확해져 계획 품질이 오른다. Postgres는 autovacuum이 자동 수행한다."}],"th":{"sum":"조인 알고리즘은 데이터 특성에 따라 나뉜다: **Nested Loop**(작은 셋+인덱스), **Hash Join**(대형 등호), **Sort-Merge**(정렬된 데이터). `EXPLAIN`으로 계획을 확인한다.","body":[{"h":"세 조인 알고리즘","t":"Nested Loop는 바깥 행마다 안쪽을 찾아 작은 셋+인덱스에 최적이나 대량이면 느리다. Hash Join은 한쪽으로 해시 테이블을 만들어 등호(equi-join) 조인 대량 처리에 강하고, 부등호는 기본 지원하지 않는다(지원 조건 용어: equi-join). Sort-Merge는 양쪽을 조인 키로 정렬 후 병합해 이미 정렬됐거나 정렬 인덱스가 있을 때 유리하다. 옵티마이저는 데이터 양·인덱스·통계로 방식을 고른다."},{"h":"실행계획으로 진단","t":"`EXPLAIN`은 어떤 인덱스·조인·스캔을 쓰는지 보여준다. 큰 테이블의 Seq/Full Scan, 예상과 실제 행 수의 큰 괴리, 대량 `Rows Removed by Filter`, 불필요한 정렬 등이 성능 문제 신호다. 이를 보고 인덱스 추가나 쿼리 재작성을 결정한다."}],"code":{"c":"EXPLAIN\nSELECT o.id, c.name\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nWHERE o.status = 'PAID';","cap":"조인·인덱스 사용 계획 확인"},"key":["Nested Loop=작은 셋+인덱스, Hash=대형 equi-join, Sort-Merge=정렬됨","Hash Join은 등호(equi-join) 조건 기반","Full Scan·추정≠실제 행 수는 튜닝 신호"]}}]},{"t":"시니어 SQL 디버깅·리뷰","l":[{"t":"집계와 GROUP BY 함정","q":[{"t":"choice","k":"GROUP BY 누락","cat":"debug","q":"다음 쿼리가 \"column not in GROUP BY\" 오류를 낸다. 원인과 올바른 수정은?","code":"SELECT dept, COUNT(*)\nFROM employees;","o":["집계함수 COUNT(*)와 비집계 컬럼 dept를 함께 select 했지만 GROUP BY dept가 없어 발생 → SELECT dept, COUNT(*) FROM employees GROUP BY dept 로 그룹 기준을 명시한다","COUNT(*) 대신 COUNT(dept)를 쓰면 해결된다","FROM 절에 테이블 별칭이 없어서 발생한다","dept 컬럼에 인덱스가 없어서 발생한다"],"a":0,"ex":"GROUP BY dept 를 추가해 그룹 기준을 명시한다.\n💡 개념: SELECT에 비집계 컬럼과 집계함수를 함께 쓰면 그 비집계 컬럼은 모두 GROUP BY에 있어야 한다.\n🛠 실무: MySQL의 ONLY_FULL_GROUP_BY 미설정 환경에선 오류 대신 임의값이 나와 더 위험하니 표준대로 GROUP BY를 명시한다."},{"t":"choice","k":"fan-out 중복합산","cat":"debug","q":"orders(1):order_items(N)를 조인해 주문 금액 합계를 구했더니 실제보다 크게 나온다. 원인과 해결은?","code":"SELECT o.id, SUM(o.amount)\nFROM orders o\nJOIN order_items i ON i.order_id = o.id\nGROUP BY o.id;","o":["조인으로 order_items 행 수만큼 orders 행이 복제(fan-out)되어 o.amount가 중복 합산됨 → 금액은 조인 전에 집계(서브쿼리)하거나 items를 미리 GROUP BY한 뒤 조인한다","SUM 대신 COUNT를 써야 한다","GROUP BY에 i.order_id를 추가하면 된다","amount 컬럼 타입을 DECIMAL로 바꾸면 된다"],"a":0,"ex":"1:N 조인의 fan-out으로 상위 테이블 값이 N번 합산된다.\n💡 개념: 조인은 매칭되는 자식 행마다 부모 행을 복제하므로 부모 컬럼 집계 전에 곱해진다.\n🛠 실무: 서로 다른 granularity의 값을 한 쿼리에서 SUM하지 말고, 각 레벨을 별도 파생 테이블로 집계한 뒤 조인한다."},{"t":"choice","k":"HAVING vs WHERE","cat":"review","q":"부서별 인원이 10명을 초과하는 부서만 집계하려 한다. 올바른 것은?","o":["집계 결과에 대한 조건이므로 GROUP BY dept 뒤에 HAVING COUNT(*) &gt; 10 을 사용한다","WHERE COUNT(*) &gt; 10 을 GROUP BY 앞에 쓴다","SELECT 절에 COUNT(*) &gt; 10 을 조건으로 넣는다","ORDER BY COUNT(*) &gt; 10 을 쓴다"],"a":0,"ex":"집계 결과 필터는 HAVING을 쓴다.\n💡 개념: WHERE는 그룹핑 전 개별 행을, HAVING은 그룹핑 후 집계 결과를 필터한다.\n🛠 실무: 행 조건은 WHERE로 먼저 걸러 그룹 대상 행을 줄이고, 집계 조건만 HAVING에 남겨 성능을 챙긴다."},{"t":"input","k":"COUNT 전체행","cat":"debug","q":"컬럼 phone에 NULL이 섞여 있어도 NULL을 제외하지 않고 전체 행 수를 세려면 COUNT( ___ )를 써야 한다. 괄호 안 기호 하나는?","a":["*"],"ex":"COUNT(*) 는 NULL 여부와 무관하게 전체 행을 센다.\n💡 개념: COUNT(col)은 해당 컬럼이 NULL인 행을 제외하지만 COUNT(*)는 행 자체를 센다.\n🛠 실무: 존재 여부/총건수는 COUNT(*), 값이 채워진 건수는 COUNT(col)로 의도를 구분해 쓴다."},{"t":"choice","k":"AVG와 NULL","cat":"debug","q":"score 컬럼에 NULL 3개, 값 7개(합 70)가 있다. SELECT AVG(score)의 결과와 이유는?","o":["10 — AVG는 NULL을 제외하고 값이 있는 7행만 대상으로 70/7을 계산하기 때문","7 — 전체 10행으로 70/10을 계산","NULL — NULL이 하나라도 있으면 결과가 NULL","0 — NULL을 0으로 취급"],"a":0,"ex":"AVG는 NULL 행을 분모에서 제외하므로 70/7=10 이다.\n💡 개념: 집계함수는 NULL을 무시한다. 평균에 NULL을 0으로 반영하려면 명시적 치환이 필요하다.\n🛠 실무: NULL을 0으로 보고 평균 내려면 AVG(COALESCE(score,0))처럼 의도를 명시한다."}],"th":{"sum":"흔한 함정 셋: 비집계 컬럼은 **GROUP BY에 넣어야** 하고, 1:N 조인은 합계를 부풀리며, NULL은 `=`로 비교할 수 없다.","body":[{"h":"GROUP BY와 조인 중복","t":"\"column not in GROUP BY\" 오류는 SELECT의 비집계 컬럼이 GROUP BY에 없을 때 난다. 그 컬럼을 GROUP BY에 추가하거나 집계 함수로 감싼다. orders(1):order_items(N) 조인 후 `SUM`이 부풀면 아이템 수만큼 주문 행이 복제된 탓이니, 미리 집계한 서브쿼리와 조인하거나 `SUM(DISTINCT)` 대신 사전 집계를 쓴다. 인원 10명 초과 필터는 집계 조건이라 `HAVING COUNT(*) > 10`이 맞다."},{"h":"NULL 함정","t":"`COUNT(*)`는 NULL 포함 전체 행을 센다(phone에 NULL이 있어도 전체는 `COUNT(*)`). `AVG(score)`는 NULL을 무시하므로 값 7개 합 70이면 70/7=10이다(3개 NULL 제외). `WHERE x = NULL`은 항상 UNKNOWN이라 0행이니 `IS NULL`로 고친다. `NOT IN` 서브쿼리에 NULL이 섞여 0행이 나오면 `NOT EXISTS`로 바꾼다."}],"code":{"c":"-- deleted_at 이 비어있는 행\nSELECT * FROM users\nWHERE deleted_at IS NULL;   -- = NULL 은 항상 0행","cap":"NULL 비교는 반드시 IS NULL"},"key":["비집계 컬럼은 GROUP BY에, 집계 필터는 HAVING","1:N 조인은 합계 뻥튀기 → 사전 집계 후 조인","`= NULL`은 0행 → `IS NULL`, `AVG`는 NULL 무시(70/7=10)"]}},{"t":"NULL과 서브쿼리 함정","q":[{"t":"choice","k":"NOT IN + NULL","cat":"debug","q":"아래 쿼리가 데이터가 있는데도 0행을 반환한다. 원인과 해결은?","code":"SELECT *\nFROM users u\nWHERE u.id NOT IN (SELECT manager_id FROM teams);","o":["서브쿼리 결과에 NULL이 섞이면 NOT IN 비교가 UNKNOWN이 되어 전체가 걸러진다 → NOT EXISTS로 바꾸거나 서브쿼리에 WHERE manager_id IS NOT NULL을 추가한다","users에 인덱스가 없어서 0행이 반환된다","NOT IN 대신 IN을 써야 한다","서브쿼리에 GROUP BY를 추가하면 된다"],"a":0,"ex":"NOT IN 목록에 NULL이 있으면 결과가 항상 UNKNOWN이 되어 0행이 된다.\n💡 개념: x NOT IN (a,b,NULL)은 x!=NULL이 UNKNOWN이라 전체가 참이 될 수 없다.\n🛠 실무: NOT IN 서브쿼리는 NOT EXISTS로 바꾸는 습관을 들여 NULL 함정을 원천 차단한다."},{"t":"choice","k":"= NULL 함정","cat":"review","q":"deleted_at이 비어있는 행을 찾으려 WHERE deleted_at = NULL로 썼더니 0행이다. 이유와 수정은?","o":["NULL은 =로 비교할 수 없고 결과가 항상 UNKNOWN이다 → WHERE deleted_at IS NULL로 써야 한다","deleted_at 컬럼이 존재하지 않는다","= NULL은 문법 오류라 실행이 안 된다","WHERE deleted_at != NULL로 바꾸면 된다"],"a":0,"ex":"NULL 판별은 IS NULL / IS NOT NULL로만 한다.\n💡 개념: NULL은 '값 없음'이라 어떤 값과도 = 비교 시 참이 되지 않는다(3-valued logic).\n🛠 실무: 소프트 삭제 플래그 조회 등은 = NULL이 아니라 IS NULL을 반드시 쓴다."},{"t":"input","k":"NOT EXISTS","cat":"debug","q":"NOT IN 서브쿼리의 NULL 함정을 피하면서 '일치하는 행이 없음'을 안전하게 표현하는 표준 술어는? (영문 두 단어)","a":["NOT EXISTS","not exists"],"ex":"NOT EXISTS 를 쓴다.\n💡 개념: EXISTS는 존재 여부만 판단해 NULL의 3치 논리에 영향받지 않는다.\n🛠 실무: 상관 서브쿼리 NOT EXISTS는 옵티마이저가 anti-join으로 잘 풀어 성능도 안정적이다."},{"t":"choice","k":"NULL 산술 전파","cat":"debug","q":"정산 리포트에서 discount가 NULL인 주문의 최종금액 amount - discount가 NULL로 나온다. 원인과 해결은?","o":["NULL은 산술 연산에 전파되어 결과 전체가 NULL이 된다 → amount - COALESCE(discount, 0)처럼 NULL을 기본값으로 치환한다","discount 컬럼 타입이 잘못되었다","amount가 0이라서 그렇다","SELECT에 DISTINCT를 붙이면 된다"],"a":0,"ex":"COALESCE(discount,0)으로 NULL을 0으로 치환한다.\n💡 개념: NULL이 포함된 산술/문자열 연산은 결과가 NULL로 전파된다.\n🛠 실무: 금액 계산 컬럼은 NULL 가능성을 항상 COALESCE/IFNULL로 방어해 리포트 누락을 막는다."},{"t":"choice","k":"상관 서브쿼리","cat":"review","q":"각 고객의 최근 주문일을 구하는 스칼라 상관 서브쿼리가 고객 수만큼 반복 실행되어 느리다. 개선 방향은?","o":["상관 서브쿼리 대신 orders를 customer_id로 GROUP BY해 MAX(order_date)를 구한 파생 테이블과 한 번에 JOIN한다","서브쿼리에 LIMIT 1만 붙이면 성능이 해결된다","SELECT 절에 인덱스 힌트를 넣는다","customer 테이블을 비정규화한다"],"a":0,"ex":"미리 집계한 파생 테이블과 조인해 한 번에 처리한다.\n💡 개념: 행마다 도는 상관 서브쿼리는 집계 후 조인(또는 윈도우 함수)으로 세트 연산화하면 빨라진다.\n🛠 실무: '각 그룹의 최신 1건'은 GROUP BY MAX 조인이나 ROW_NUMBER() 윈도우로 표현한다."}],"th":{"sum":"흔한 함정 셋: 비집계 컬럼은 **GROUP BY에 넣어야** 하고, 1:N 조인은 합계를 부풀리며, NULL은 `=`로 비교할 수 없다.","body":[{"h":"GROUP BY와 조인 중복","t":"\"column not in GROUP BY\" 오류는 SELECT의 비집계 컬럼이 GROUP BY에 없을 때 난다. 그 컬럼을 GROUP BY에 추가하거나 집계 함수로 감싼다. orders(1):order_items(N) 조인 후 `SUM`이 부풀면 아이템 수만큼 주문 행이 복제된 탓이니, 미리 집계한 서브쿼리와 조인하거나 `SUM(DISTINCT)` 대신 사전 집계를 쓴다. 인원 10명 초과 필터는 집계 조건이라 `HAVING COUNT(*) > 10`이 맞다."},{"h":"NULL 함정","t":"`COUNT(*)`는 NULL 포함 전체 행을 센다(phone에 NULL이 있어도 전체는 `COUNT(*)`). `AVG(score)`는 NULL을 무시하므로 값 7개 합 70이면 70/7=10이다(3개 NULL 제외). `WHERE x = NULL`은 항상 UNKNOWN이라 0행이니 `IS NULL`로 고친다. `NOT IN` 서브쿼리에 NULL이 섞여 0행이 나오면 `NOT EXISTS`로 바꾼다."}],"code":{"c":"-- deleted_at 이 비어있는 행\nSELECT * FROM users\nWHERE deleted_at IS NULL;   -- = NULL 은 항상 0행","cap":"NULL 비교는 반드시 IS NULL"},"key":["비집계 컬럼은 GROUP BY에, 집계 필터는 HAVING","1:N 조인은 합계 뻥튀기 → 사전 집계 후 조인","`= NULL`은 0행 → `IS NULL`, `AVG`는 NULL 무시(70/7=10)"]}},{"t":"조인·형변환·N+1 리뷰","q":[{"t":"choice","k":"LEFT JOIN 변질","cat":"debug","q":"주문 없는 고객까지 보려고 LEFT JOIN 했는데 주문 없는 고객이 결과에서 사라졌다. 원인과 해결은?","code":"SELECT c.*, o.id\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.status = 'paid';","o":["WHERE에 우측 테이블(orders) 조건을 두면 NULL 행이 걸러져 사실상 INNER JOIN이 된다 → 조건을 ON 절로 옮기거나 (o.status = 'paid' OR o.id IS NULL)로 처리한다","LEFT JOIN 대신 RIGHT JOIN을 써야 한다","customers에 인덱스가 없어서 그렇다","SELECT c.*를 SELECT *로 바꾸면 된다"],"a":0,"ex":"우측 테이블 조건은 WHERE가 아니라 ON 절에 둔다.\n💡 개념: LEFT JOIN의 미매칭 행은 우측 컬럼이 NULL인데, WHERE의 우측 조건이 그 NULL을 탈락시켜 INNER처럼 변한다.\n🛠 실무: 외부 조인 필터는 ON에, 구동(좌측) 테이블 필터만 WHERE에 두는 규칙으로 리뷰한다."},{"t":"choice","k":"암묵 형변환","cat":"debug","q":"phone은 VARCHAR이고 인덱스가 있는데 WHERE phone = 01012345678 (숫자 리터럴) 쿼리가 Full Scan이다. 원인과 해결은?","o":["문자열 컬럼을 숫자와 비교하면 컬럼 전체가 숫자로 암묵 형변환되어 인덱스를 못 쓴다 → WHERE phone = '01012345678'처럼 문자열 리터럴로 비교한다","phone 인덱스를 UNIQUE로 바꿔야 한다","숫자 비교가 항상 더 빠르므로 정상이다","phone을 INT 타입으로 바꾸면 항상 옳다"],"a":0,"ex":"리터럴을 컬럼과 같은 문자열 타입으로 맞춘다.\n💡 개념: 타입이 다르면 DB가 컬럼 값에 함수를 씌워 변환하므로 인덱스 정렬을 활용할 수 없다.\n🛠 실무: 전화번호·우편번호처럼 앞자리 0이 의미 있는 값은 문자열로 저장하고 항상 문자열로 비교한다."},{"t":"choice","k":"N+1 쿼리","cat":"review","q":"앱이 게시글 100개를 조회한 뒤 각 글마다 작성자를 개별 SELECT로 조회한다(총 1+100회). 이 안티패턴과 해결은?","o":["N+1 쿼리 문제다 → posts와 users를 JOIN한 단일 쿼리로 가져오거나 author_id IN (...)으로 한 번에 배치 조회한다","정상적인 패턴이므로 그대로 둔다","각 SELECT에 LIMIT 1을 붙이면 해결된다","users 테이블에 파티셔닝을 적용한다"],"a":0,"ex":"JOIN 또는 IN 배치 조회로 왕복 횟수를 1~2회로 줄인다.\n💡 개념: 목록 1회 + 항목마다 1회의 반복 쿼리가 네트워크 왕복과 파싱 비용을 곱한다.\n🛠 실무: ORM에서는 eager loading(JOIN fetch / preload)으로 연관을 한 번에 로드한다."},{"t":"input","k":"N+1 명칭","cat":"review","q":"목록을 가져온 뒤 각 항목마다 연관 데이터를 개별 쿼리로 다시 조회해 쿼리가 폭증하는 문제의 이름은? (예: X+1 형태)","a":["N+1","n+1","N+1 쿼리","N + 1"],"ex":"N+1 쿼리 문제다.\n💡 개념: 1(목록) + N(각 항목별 재조회)의 왕복이 발생한다.\n🛠 실무: 로그에 동일 형태 쿼리가 수백 번 찍히면 N+1을 의심하고 배치/조인으로 묶는다."},{"t":"choice","k":"DISTINCT 남용","cat":"review","q":"조인 결과에 중복 행이 생겨 SELECT DISTINCT로 덮었더니 느려지고 SUM도 여전히 이상하다. 근본 리뷰 관점은?","o":["DISTINCT는 fan-out 중복을 숨길 뿐 원인이 아니다 → 조인 관계(1:N)를 파악해 집계를 조인 전에 수행하거나 조인 키 중복을 제거하는 것이 근본 해결이다","DISTINCT를 DISTINCT ON으로 바꾸면 항상 해결된다","중복은 정상이므로 무시한다","GROUP BY를 모든 컬럼에 걸면 된다"],"a":0,"ex":"DISTINCT는 증상 은폐일 뿐, 조인 다중성을 바로잡아야 한다.\n💡 개념: DISTINCT는 행 중복을 제거하지만 SUM 등 이미 부풀려진 집계값은 되돌리지 못한다.\n🛠 실무: DISTINCT가 필요해지면 '조인이 어디서 행을 늘렸는지'를 먼저 점검하는 신호로 삼는다."}],"th":{"sum":"흔한 함정 셋: 비집계 컬럼은 **GROUP BY에 넣어야** 하고, 1:N 조인은 합계를 부풀리며, NULL은 `=`로 비교할 수 없다.","body":[{"h":"GROUP BY와 조인 중복","t":"\"column not in GROUP BY\" 오류는 SELECT의 비집계 컬럼이 GROUP BY에 없을 때 난다. 그 컬럼을 GROUP BY에 추가하거나 집계 함수로 감싼다. orders(1):order_items(N) 조인 후 `SUM`이 부풀면 아이템 수만큼 주문 행이 복제된 탓이니, 미리 집계한 서브쿼리와 조인하거나 `SUM(DISTINCT)` 대신 사전 집계를 쓴다. 인원 10명 초과 필터는 집계 조건이라 `HAVING COUNT(*) > 10`이 맞다."},{"h":"NULL 함정","t":"`COUNT(*)`는 NULL 포함 전체 행을 센다(phone에 NULL이 있어도 전체는 `COUNT(*)`). `AVG(score)`는 NULL을 무시하므로 값 7개 합 70이면 70/7=10이다(3개 NULL 제외). `WHERE x = NULL`은 항상 UNKNOWN이라 0행이니 `IS NULL`로 고친다. `NOT IN` 서브쿼리에 NULL이 섞여 0행이 나오면 `NOT EXISTS`로 바꾼다."}],"code":{"c":"-- deleted_at 이 비어있는 행\nSELECT * FROM users\nWHERE deleted_at IS NULL;   -- = NULL 은 항상 0행","cap":"NULL 비교는 반드시 IS NULL"},"key":["비집계 컬럼은 GROUP BY에, 집계 필터는 HAVING","1:N 조인은 합계 뻥튀기 → 사전 집계 후 조인","`= NULL`은 0행 → `IS NULL`, `AVG`는 NULL 무시(70/7=10)"]}}]},{"t":"시니어 SQL 성능","l":[{"t":"인덱스와 스캔","q":[{"t":"choice","k":"email 인덱스","cat":"perf","q":"users 테이블(수백만 행)에서 WHERE email = ? 조회가 점점 느려지고 Full Scan이 잡힌다. 원인과 해결은?","code":"SELECT id, name FROM users WHERE email = 'a@b.com';","o":["email에 인덱스가 없어 전체 테이블을 스캔한다 → CREATE INDEX idx_users_email ON users(email); 로 인덱스를 만들면 조회가 로그 시간으로 빨라진다","SELECT 컬럼이 많아서 느린 것이다","email을 대문자로 저장하면 빨라진다","LIMIT 1을 붙이면 인덱스 없이도 빨라진다"],"a":0,"ex":"조회 조건 컬럼 email에 인덱스를 생성한다.\n💡 개념: 등가/범위 조회가 잦은 컬럼에 B-tree 인덱스를 두면 스캔 대신 탐색(seek)으로 바뀐다.\n🛠 실무: 유일해야 하는 email이면 UNIQUE INDEX로 중복 방지와 조회 성능을 동시에 얻는다."},{"t":"choice","k":"커버링 인덱스","cat":"perf","q":"SELECT status FROM orders WHERE user_id = ? 가 인덱스(user_id)를 타지만 테이블 랜덤 액세스가 많아 여전히 느리다. 더 빠르게 하려면?","o":["커버링 인덱스로 만든다 → CREATE INDEX idx ON orders(user_id, status); 처럼 조회에 필요한 컬럼까지 인덱스에 포함하면 테이블을 안 읽고 인덱스만으로 처리된다","status 컬럼을 삭제한다","user_id 인덱스를 UNIQUE로 바꾼다","SELECT *로 바꾼다"],"a":0,"ex":"필요한 컬럼을 인덱스에 포함해 커버링 인덱스를 만든다.\n💡 개념: 인덱스만으로 쿼리를 만족하면 테이블 랜덤 접근(bookmark lookup)이 사라진다.\n🛠 실무: 조회 컬럼이 몇 개로 고정된 hot 쿼리는 (조건컬럼, 조회컬럼) 순서의 복합 인덱스나 INCLUDE로 커버링한다."},{"t":"choice","k":"낮은 선택도","cat":"perf","q":"gender(값 M/F) 컬럼에 인덱스가 있는데도 옵티마이저가 Full Scan을 택한다. 가장 타당한 이유는?","o":["선택도가 낮아(전체의 절반가량 매칭) 인덱스 탐색 후 랜덤 액세스보다 순차 Full Scan이 더 저렴하다고 옵티마이저가 판단하기 때문 — 정상 동작이다","인덱스가 손상되었다","통계가 항상 틀리기 때문","인덱스는 문자열 컬럼에 못 쓴다"],"a":0,"ex":"매칭 행이 많으면 인덱스보다 Full Scan이 싸므로 옵티마이저가 합리적으로 선택한 것이다.\n💡 개념: 인덱스는 결과가 전체의 소수일 때 유리하고, 넓은 범위엔 순차 읽기가 유리하다.\n🛠 실무: 저선택도 컬럼은 단독 인덱스보다 복합 인덱스의 후행 컬럼이나 부분 인덱스로 활용한다."},{"t":"input","k":"선택도 용어","cat":"perf","q":"인덱스 효율을 좌우하는, 컬럼 값의 고유함 정도(높을수록 인덱스 유리)를 가리키는 용어는? (한글 또는 영문 한 단어)","a":["선택도","카디널리티","selectivity","cardinality"],"ex":"선택도(카디널리티)다.\n💡 개념: 고유값이 많아 매칭 행이 적을수록 선택도가 높아 인덱스 효과가 크다.\n🛠 실무: 통계의 카디널리티 추정이 실제와 어긋나면 잘못된 계획이 나오므로 통계 갱신(ANALYZE)을 주기적으로 한다."},{"t":"choice","k":"복합 인덱스 순서","cat":"perf","q":"인덱스가 (a, b) 순서인데 WHERE b = ? 만 걸린 쿼리가 인덱스를 효율적으로 타지 못한다. 이유와 해결은?","o":["복합 인덱스는 선두 컬럼(a)부터 정렬되므로 a 조건이 없으면 b만으로 탐색 이점을 못 쓴다 → (b, a) 인덱스를 만들거나 a 조건을 함께 준다","복합 인덱스는 항상 첫 컬럼만 쓸 수 있다","b를 별도 테이블로 분리한다","인덱스를 UNIQUE로 바꾼다"],"a":0,"ex":"복합 인덱스는 선두 컬럼(leftmost) 기준으로 정렬되므로 조회 패턴에 맞춰 컬럼 순서를 정한다.\n💡 개념: (a,b) 인덱스는 a, 또는 (a,b)엔 유효하지만 b 단독 조건엔 정렬 이점이 없다.\n🛠 실무: 등가 조건 컬럼을 앞에, 범위 조건 컬럼을 뒤에 두는 순서 설계 원칙을 적용한다."}],"th":{"sum":"느린 조회의 단골 원인은 **인덱스 부재/무력화**다. 함수로 감싼 컬럼, 앞 와일드카드, 낮은 선택도(cardinality)는 인덱스를 못 살린다.","body":[{"h":"인덱스와 스캔","t":"수백만 행에서 `WHERE email=?`가 Full Scan이면 email 인덱스가 없는 것이니 인덱스를 추가한다. 인덱스로 좁혀도 테이블 랜덤 액세스가 많으면, 조회 컬럼까지 포함한 **커버링 인덱스**로 테이블 접근을 없앤다. gender(M/F)처럼 선택도(cardinality)가 낮은 컬럼은 인덱스를 타도 대부분을 읽어 옵티마이저가 Full Scan을 택한다."},{"h":"SARGable과 복합 인덱스","t":"`WHERE YEAR(created_at)=2025`는 컬럼을 함수로 감싸 인덱스를 못 타니 범위 조건으로 재작성한다. `LIKE '%kim'`은 앞 와일드카드라 인덱스 불가이며, 뒤 검색이 필요하면 역순 저장 컬럼이나 전문 검색을 쓴다. 인덱스 `(a,b)`인데 `WHERE b=?`만 걸면 선두 `a`가 없어 못 타므로, `b` 단독 인덱스를 추가하거나 인덱스 순서를 조정한다."}],"code":{"c":"-- 인덱스 살리기: 함수 제거 + 범위\nSELECT * FROM logs\nWHERE created_at >= '2025-01-01'\n  AND created_at <  '2026-01-01';","cap":"YEAR() 제거로 인덱스 range scan 유도"},"key":["Full Scan+`=` 조회 → 인덱스 추가; 랜덤 액세스 많으면 커버링 인덱스","선택도(cardinality) 낮으면 인덱스 무시됨","함수·앞 와일드카드·비선두 컬럼은 인덱스 무력화"]}},{"t":"SARGable 쿼리","q":[{"t":"choice","k":"YEAR() 비-SARGable","cat":"perf","q":"created_at에 인덱스가 있는데 WHERE YEAR(created_at) = 2025 가 Full Scan이다. 원인과 해결은?","o":["인덱스 컬럼을 함수로 감싸면 인덱스를 못 탄다(비-SARGable) → WHERE created_at &gt;= '2025-01-01' AND created_at &lt; '2026-01-01' 범위 조건으로 바꾼다","YEAR 함수가 느리므로 MONTH를 써야 한다","2025를 문자열 '2025'로 바꾸면 된다","created_at을 DATE 타입으로 바꾸면 항상 해결된다"],"a":0,"ex":"컬럼을 함수로 감싸지 말고 반열림 범위 조건으로 바꾼다.\n💡 개념: 인덱스는 원본 컬럼 값으로 정렬되어 있어 컬럼에 함수를 적용하면 정렬을 못 쓴다.\n🛠 실무: 함수 조건이 불가피하면 표현식 인덱스(예: created_at의 date_trunc)를 별도로 만든다."},{"t":"choice","k":"선행 와일드카드","cat":"perf","q":"WHERE name LIKE '%kim' 이 인덱스를 못 탄다. 이유와 대안은?","o":["앞에 와일드카드가 오면 B-tree 인덱스의 정렬 순서를 활용할 수 없어 Full Scan이 된다 → 접두 검색(LIKE 'kim%')으로 바꾸거나 Full-Text·역방향 인덱스를 쓴다","LIKE는 항상 인덱스를 못 쓴다","name 컬럼을 숫자로 바꾼다","'%kim%'로 바꾸면 빨라진다"],"a":0,"ex":"선행 와일드카드는 비-SARGable이므로 접두 검색이나 전문 검색 인덱스를 쓴다.\n💡 개념: B-tree는 왼쪽부터 비교하므로 앞이 고정된 'kim%'만 범위 탐색이 가능하다.\n🛠 실무: 접미/부분 일치가 필요하면 Full-Text 인덱스, trigram(GIN), 또는 역순 저장 컬럼을 활용한다."},{"t":"choice","k":"컬럼 연산 제거","cat":"perf","q":"WHERE price * 1.1 &gt; 1000 이 인덱스를 못 탄다. SARGable하게 고치면?","o":["컬럼에 연산을 걸면 비-SARGable이므로 연산을 상수 쪽으로 옮긴다 → WHERE price &gt; 1000 / 1.1","price 인덱스를 삭제한다","1.1을 정수로 바꾼다","그대로 두는 게 맞다"],"a":0,"ex":"컬럼은 그대로 두고 계산을 상수 쪽으로 옮긴다.\n💡 개념: 인덱스는 원본 컬럼 값 기준이라 컬럼에 산술을 적용하면 탐색 경계를 만들 수 없다.\n🛠 실무: WHERE 좌변은 항상 '가공 없는 컬럼', 우변에 상수/표현식을 두는 습관으로 SARGable을 유지한다."},{"t":"input","k":"SARGable 용어","cat":"perf","q":"컬럼을 함수/연산으로 감싸지 않아 인덱스를 탈 수 있는 검색 조건을 뜻하는 영어 용어는? (한 단어)","a":["SARGable","sargable","사거블"],"ex":"SARGable(Search ARGument able) 조건이다.\n💡 개념: 인덱스 탐색 인자로 쓸 수 있는 형태의 조건을 뜻한다.\n🛠 실무: 리뷰 시 'WHERE 좌변에 함수/연산/형변환이 있는가'를 SARGable 체크리스트로 본다."},{"t":"choice","k":"OR을 IN으로","cat":"perf","q":"WHERE status = 'A' OR status = 'B' 형태가 인덱스 활용이 애매하다. 옵티마이저 친화적으로 바꾸면?","o":["같은 컬럼의 OR 목록은 WHERE status IN ('A','B')로 바꾸면 인덱스 range/list 탐색으로 처리되기 쉽다","OR는 항상 UNION ALL로만 풀린다","status를 두 컬럼으로 나눈다","OR는 무조건 Full Scan이라 방법이 없다"],"a":0,"ex":"동일 컬럼의 OR는 IN으로 정리한다.\n💡 개념: IN 목록은 옵티마이저가 여러 개의 인덱스 탐색으로 깔끔히 풀 수 있다.\n🛠 실무: 서로 다른 컬럼을 OR로 묶어 인덱스가 안 먹으면 UNION ALL로 분리하는 방법도 검토한다."}],"th":{"sum":"느린 조회의 단골 원인은 **인덱스 부재/무력화**다. 함수로 감싼 컬럼, 앞 와일드카드, 낮은 선택도(cardinality)는 인덱스를 못 살린다.","body":[{"h":"인덱스와 스캔","t":"수백만 행에서 `WHERE email=?`가 Full Scan이면 email 인덱스가 없는 것이니 인덱스를 추가한다. 인덱스로 좁혀도 테이블 랜덤 액세스가 많으면, 조회 컬럼까지 포함한 **커버링 인덱스**로 테이블 접근을 없앤다. gender(M/F)처럼 선택도(cardinality)가 낮은 컬럼은 인덱스를 타도 대부분을 읽어 옵티마이저가 Full Scan을 택한다."},{"h":"SARGable과 복합 인덱스","t":"`WHERE YEAR(created_at)=2025`는 컬럼을 함수로 감싸 인덱스를 못 타니 범위 조건으로 재작성한다. `LIKE '%kim'`은 앞 와일드카드라 인덱스 불가이며, 뒤 검색이 필요하면 역순 저장 컬럼이나 전문 검색을 쓴다. 인덱스 `(a,b)`인데 `WHERE b=?`만 걸면 선두 `a`가 없어 못 타므로, `b` 단독 인덱스를 추가하거나 인덱스 순서를 조정한다."}],"code":{"c":"-- 인덱스 살리기: 함수 제거 + 범위\nSELECT * FROM logs\nWHERE created_at >= '2025-01-01'\n  AND created_at <  '2026-01-01';","cap":"YEAR() 제거로 인덱스 range scan 유도"},"key":["Full Scan+`=` 조회 → 인덱스 추가; 랜덤 액세스 많으면 커버링 인덱스","선택도(cardinality) 낮으면 인덱스 무시됨","함수·앞 와일드카드·비선두 컬럼은 인덱스 무력화"]}},{"t":"페이지네이션·조인 실행계획","q":[{"t":"choice","k":"깊은 OFFSET","cat":"perf","q":"LIMIT 20 OFFSET 100000 페이지네이션이 뒤 페이지로 갈수록 급격히 느려진다. 원인과 해결은?","code":"SELECT * FROM posts ORDER BY id LIMIT 20 OFFSET 100000;","o":["OFFSET은 건너뛸 10만 행을 모두 읽고 버리므로 느리다 → 키셋(seek) 페이지네이션: WHERE id &gt; :last_id ORDER BY id LIMIT 20 으로 마지막 키 이후만 읽는다","LIMIT을 늘리면 빨라진다","ORDER BY를 제거하면 정확해진다","OFFSET은 인덱스가 있으면 항상 빠르다"],"a":0,"ex":"OFFSET 대신 마지막 키 이후를 조건으로 읽는 키셋 페이지네이션을 쓴다.\n💡 개념: OFFSET N은 N개 행을 스캔·폐기해야 하므로 페이지가 깊을수록 비용이 선형 증가한다.\n🛠 실무: 정렬 키(예: id 또는 (created_at,id))에 인덱스를 두고 마지막 본 값을 커서로 넘겨 조회한다."},{"t":"input","k":"키셋 용어","cat":"perf","q":"OFFSET 대신 마지막으로 본 행의 키 값을 기준으로 다음 페이지를 읽는 페이지네이션 기법의 이름은? (한글 또는 영문)","a":["키셋","keyset","seek","seek method","커서 페이지네이션","keyset pagination"],"ex":"키셋(seek) 페이지네이션이다.\n💡 개념: 절대 위치(OFFSET)가 아니라 마지막 키 값을 기준점으로 삼아 이후 구간만 읽는다.\n🛠 실무: 무한 스크롤·대용량 목록의 안정적 성능을 위해 오프셋 대신 키셋 커서를 기본으로 한다."},{"t":"choice","k":"Hash Join","cat":"perf","q":"각각 수천만 행인 두 테이블을 인덱스 없는 컬럼으로 등가 조인한다. 옵티마이저가 택할 가장 효율적인 조인 방식과 이유는?","o":["Hash Join — 한쪽으로 해시 테이블을 만들고 다른 쪽을 훑어 매칭하므로 인덱스 없는 대용량 등가 조인에서 Nested Loop보다 효율적이다","Nested Loop — 항상 가장 빠르다","Cross Join — 조인 비용이 가장 낮다","Merge Join은 정렬이 필요 없어 항상 최선이다"],"a":0,"ex":"인덱스 없는 대용량 등가 조인은 Hash Join이 유리하다.\n💡 개념: 해시로 매칭하면 각 테이블을 한 번씩만 스캔해 O(N+M)에 처리한다.\n🛠 실무: Hash Join은 등가 조건에만 쓰이고 해시 테이블용 메모리(work_mem)가 부족하면 디스크로 넘쳐 느려지니 메모리 설정을 확인한다."},{"t":"choice","k":"Nested Loop 적합","cat":"perf","q":"작은 구동 테이블과, 조인 키에 인덱스가 있는 큰 테이블을 조인한다. 이때 유리한 조인 방식은?","o":["Nested Loop Join — 작은 쪽 각 행마다 큰 테이블의 인덱스를 탐색하면 매우 효율적이다","Hash Join — 항상 Nested Loop보다 빠르다","무조건 Full Scan 후 Merge Join","Cross Join"],"a":0,"ex":"작은 구동 + 인덱스 있는 큰 테이블 조합엔 Nested Loop가 유리하다.\n💡 개념: 바깥 행 수가 적고 안쪽을 인덱스로 즉시 찾을 수 있으면 반복 탐색 비용이 작다.\n🛠 실무: 구동 테이블이 작게 유지되도록 WHERE로 먼저 걸러 바깥 루프 반복을 줄인다."},{"t":"choice","k":"EXPLAIN 우선","cat":"perf","q":"쿼리가 왜 느린지 파악하려 할 때 시니어가 가장 먼저 하는 일은?","o":["EXPLAIN / EXPLAIN ANALYZE로 실행계획을 보고 스캔 방식(Seq/Index), 조인 방식, 예상 대비 실제 행수·비용을 확인한다","서버를 재시작한다","일단 관련 컬럼에 인덱스를 전부 만든다","LIMIT을 붙여 결과를 줄인다"],"a":0,"ex":"추측하지 말고 EXPLAIN(ANALYZE)로 실제 실행계획을 먼저 본다.\n💡 개념: 추정 행수와 실제 행수의 큰 차이는 통계·조건 문제를, 예상외의 Seq Scan은 인덱스 미사용을 드러낸다.\n🛠 실무: EXPLAIN ANALYZE의 실제 시간·버퍼(BUFFERS)로 병목 노드를 특정한 뒤 인덱스/쿼리를 손본다."}],"th":{"sum":"느린 조회의 단골 원인은 **인덱스 부재/무력화**다. 함수로 감싼 컬럼, 앞 와일드카드, 낮은 선택도(cardinality)는 인덱스를 못 살린다.","body":[{"h":"인덱스와 스캔","t":"수백만 행에서 `WHERE email=?`가 Full Scan이면 email 인덱스가 없는 것이니 인덱스를 추가한다. 인덱스로 좁혀도 테이블 랜덤 액세스가 많으면, 조회 컬럼까지 포함한 **커버링 인덱스**로 테이블 접근을 없앤다. gender(M/F)처럼 선택도(cardinality)가 낮은 컬럼은 인덱스를 타도 대부분을 읽어 옵티마이저가 Full Scan을 택한다."},{"h":"SARGable과 복합 인덱스","t":"`WHERE YEAR(created_at)=2025`는 컬럼을 함수로 감싸 인덱스를 못 타니 범위 조건으로 재작성한다. `LIKE '%kim'`은 앞 와일드카드라 인덱스 불가이며, 뒤 검색이 필요하면 역순 저장 컬럼이나 전문 검색을 쓴다. 인덱스 `(a,b)`인데 `WHERE b=?`만 걸면 선두 `a`가 없어 못 타므로, `b` 단독 인덱스를 추가하거나 인덱스 순서를 조정한다."}],"code":{"c":"-- 인덱스 살리기: 함수 제거 + 범위\nSELECT * FROM logs\nWHERE created_at >= '2025-01-01'\n  AND created_at <  '2026-01-01';","cap":"YEAR() 제거로 인덱스 range scan 유도"},"key":["Full Scan+`=` 조회 → 인덱스 추가; 랜덤 액세스 많으면 커버링 인덱스","선택도(cardinality) 낮으면 인덱스 무시됨","함수·앞 와일드카드·비선두 컬럼은 인덱스 무력화"]}}]},{"t":"시니어 SQL 설계·운영","l":[{"t":"트랜잭션과 동시성","q":[{"t":"choice","k":"송금 원자성","cat":"design","q":"A 계좌 출금 후 B 계좌 입금 직전에 서버가 죽으면 돈이 증발할 수 있다. 올바른 설계는?","code":"UPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;","o":["두 UPDATE를 하나의 트랜잭션(BEGIN ... COMMIT)으로 묶어 원자성을 보장한다 → 중간 실패 시 ROLLBACK되어 전부 취소된다","두 UPDATE 순서를 바꾸면 해결된다","balance 컬럼에 인덱스를 만든다","출금액을 나눠서 여러 번 실행한다"],"a":0,"ex":"두 변경을 한 트랜잭션으로 묶어 all-or-nothing을 보장한다.\n💡 개념: 원자성은 트랜잭션 내 여러 변경이 전부 커밋되거나 전부 롤백됨을 뜻한다.\n🛠 실무: 애플리케이션 코드에서 두 UPDATE 사이에 예외가 나면 반드시 롤백되도록 트랜잭션 경계를 명확히 감싼다."},{"t":"choice","k":"oversell 방지","cat":"ops","q":"재고 1개 상품에 동시 주문 2건이 들어와 재고가 -1(oversell)이 된다. read-modify-write 경합의 해결은?","code":"SELECT stock FROM items WHERE id = 1;\n-- 앱에서 stock &gt; 0 확인 후\nUPDATE items SET stock = stock - 1 WHERE id = 1;","o":["조회 시 행을 잠근다 → SELECT stock FROM items WHERE id = 1 FOR UPDATE; 로 배타 잠금을 걸어 다른 트랜잭션을 대기시키거나, UPDATE items SET stock = stock - 1 WHERE id = 1 AND stock &gt; 0 으로 원자 갱신한다","SELECT를 두 번 실행한다","stock 컬럼을 UNSIGNED로 바꾸면 항상 막힌다","트랜잭션 격리 수준을 READ UNCOMMITTED로 낮춘다"],"a":0,"ex":"SELECT ... FOR UPDATE 행 잠금이나 조건부 원자 UPDATE로 경합을 직렬화한다.\n💡 개념: 조회-판단-갱신 사이의 틈에 다른 트랜잭션이 끼어들어 초과 판매가 난다.\n🛠 실무: 재고 차감은 WHERE stock &gt; 0 로 원자 갱신하고 영향 행이 0이면 품절로 처리하면 잠금 없이도 안전하다."},{"t":"input","k":"원자성 용어","cat":"design","q":"트랜잭션이 '전부 성공하거나 전부 실패'하는 성질을 뜻하는 ACID의 A는? (한글)","a":["원자성","atomicity"],"ex":"원자성(Atomicity)이다.\n💡 개념: 트랜잭션은 더 이상 쪼갤 수 없는 단위로 취급되어 중간 상태가 외부에 남지 않는다.\n🛠 실무: 여러 테이블·행을 함께 바꾸는 업무 로직은 반드시 하나의 트랜잭션으로 원자성을 보장한다."},{"t":"choice","k":"낙관적 락","cat":"ops","q":"잠금 대기 없이 동시 수정 충돌을 감지하려 한다. 낙관적 락(optimistic lock) 구현으로 옳은 것은?","o":["version 컬럼을 두고 UPDATE ... SET ..., version = version + 1 WHERE id = ? AND version = :read_version 로 갱신해, 영향 행이 0이면 충돌로 보고 재시도한다","SELECT FOR UPDATE로 항상 먼저 잠근다","격리 수준을 SERIALIZABLE로만 바꾼다","version 대신 created_at을 비교한다"],"a":0,"ex":"version 컬럼 비교 갱신으로 충돌을 사후 감지·재시도한다.\n💡 개념: 낙관적 락은 잠그지 않고 커밋 시점에 버전 불일치로 경합을 탐지한다.\n🛠 실무: 충돌이 드문 화면 편집 등에 적합하며, 재시도 로직과 사용자 알림을 함께 설계한다."},{"t":"choice","k":"Phantom Read","cat":"design","q":"같은 트랜잭션에서 같은 조건의 조회를 두 번 했더니 그 사이 다른 트랜잭션이 커밋해 행 수가 달라졌다. 이 현상과 대응은?","o":["Phantom Read다 → 필요하면 격리 수준을 SERIALIZABLE(또는 범위 잠금)로 올려 방지하되, 동시성 저하 트레이드오프를 판단한다","Dirty Read이며 인덱스로 해결된다","정상이며 무시하면 된다","트랜잭션을 쓰지 않으면 사라진다"],"a":0,"ex":"새 행이 나타나는 Phantom Read이며, SERIALIZABLE/범위 잠금으로 막는다.\n💡 개념: 격리 수준이 낮을수록 Dirty·Non-repeatable·Phantom Read 이상현상이 허용된다.\n🛠 실무: 모든 것을 SERIALIZABLE로 올리면 경합·데드락이 늘므로 정말 필요한 트랜잭션에만 적용한다."}],"th":{"sum":"돈 계산은 **하나의 트랜잭션**으로 원자성(A)을 지키고, 재고 경합은 잠금이나 **낙관적 락**으로 막는다. `MVCC` 덕에 읽기와 쓰기가 서로 막지 않는다.","body":[{"h":"트랜잭션과 동시성","t":"출금·입금은 한 트랜잭션으로 묶어야 중간 장애 시 전부 롤백되어 돈이 증발하지 않는다(A=원자성, 한글로 '원자성'). 재고 1개에 동시 주문 2건이 -1이 되는 read-modify-write 경합은, `SELECT ... FOR UPDATE`로 행을 잠그거나 `UPDATE ... SET stock=stock-1 WHERE stock>0`처럼 조건부 갱신으로 막는다. 낙관적 락은 version 컬럼을 두고 `UPDATE ... WHERE version=?`로 갱신 후 영향 행 수 0이면 충돌로 감지·재시도한다."},{"h":"MVCC와 격리","t":"같은 조건 재조회 사이 행 수가 달라지면 Phantom Read다. 표준 SQL에서 REPEATABLE READ는 팬텀을 막아주지 못하므로 `SERIALIZABLE`로 올리거나 범위(갭) 락으로 대응한다(MySQL InnoDB는 REPEATABLE READ에서도 갭 락으로 상당수 방지한다). PostgreSQL에서 대량 UPDATE 중에도 SELECT가 안 막히는 이유는 **MVCC**로 각자 스냅샷 버전을 읽기 때문이다(약어 MVCC)."}],"code":{"c":"-- 낙관적 락: version 비교\nUPDATE stock\nSET qty = qty - 1, version = version + 1\nWHERE id = 10 AND version = 3;\n-- 영향 행 0이면 충돌 → 재시도","cap":"version으로 동시 수정 충돌 감지"},"key":["이체는 한 트랜잭션(A=원자성)","재고 경합은 `FOR UPDATE`/조건부 UPDATE/낙관적 락","읽기·쓰기 비차단의 원리는 MVCC, 재조회 행 변화=Phantom(표준상 SERIALIZABLE로 방지)"]}},{"t":"MVCC와 잠금","q":[{"t":"choice","k":"MVCC 원리","cat":"ops","q":"PostgreSQL에서 대량 UPDATE가 도는 중에도 SELECT가 막히지 않고 잘 읽힌다. 그 원리는?","o":["MVCC — 각 트랜잭션은 스냅샷을 보며, 읽기는 커밋된 이전 버전을 읽으므로 쓰기 잠금과 충돌하지 않는다('읽기는 쓰기를, 쓰기는 읽기를 막지 않는다')","모든 SELECT가 캐시에서만 읽기 때문","UPDATE가 테이블 전체를 잠그지 않아 우연히 그런 것","SELECT가 자동으로 READ UNCOMMITTED로 실행되기 때문"],"a":0,"ex":"MVCC의 스냅샷 격리 덕분에 읽기와 쓰기가 서로 막지 않는다.\n💡 개념: 갱신 시 새 버전을 만들고 트랜잭션은 자신의 스냅샷에 보이는 버전만 읽는다.\n🛠 실무: 읽기가 오래된 스냅샷을 보는 특성을 이해하고, 최신값이 필요하면 FOR UPDATE 등 잠금 읽기를 명시한다."},{"t":"input","k":"MVCC 약어","cat":"ops","q":"여러 버전의 행을 유지해 읽기와 쓰기가 서로 막지 않게 하는 동시성 제어 기법의 약어는? (영문 약어)","a":["MVCC","mvcc"],"ex":"MVCC(Multi-Version Concurrency Control)다.\n💡 개념: 하나의 행에 대해 여러 버전을 유지해 읽기 일관성과 동시성을 함께 확보한다.\n🛠 실무: PostgreSQL·Oracle·InnoDB가 채택하며, 대신 죽은 버전 정리(VACUUM/undo) 비용이 따라온다."},{"t":"choice","k":"데드락 대응","cat":"ops","q":"두 트랜잭션이 서로 다른 순서로 두 행을 잠가 데드락이 발생한다. 근본 대응으로 가장 적절한 것은?","o":["자원(행/테이블) 잠금 순서를 애플리케이션 전반에서 동일하게 통일하고, 짧은 트랜잭션·재시도 로직을 둔다 → 순환 대기를 원천 차단한다","데드락은 막을 수 없으므로 서버를 재시작한다","모든 트랜잭션을 SERIALIZABLE로 바꾸면 데드락이 사라진다","잠금을 아예 쓰지 않는다"],"a":0,"ex":"잠금 획득 순서를 통일해 순환 대기를 없애고, 데드락 시 재시도로 복구한다.\n💡 개념: 데드락은 서로가 상대의 잠금을 기다리는 순환 대기에서 발생한다.\n🛠 실무: DB가 데드락을 감지해 한쪽을 롤백하므로 애플리케이션에 재시도(backoff)를 반드시 넣는다."},{"t":"choice","k":"VACUUM","cat":"ops","q":"PostgreSQL MVCC에서 UPDATE/DELETE가 남긴 이전 버전(dead tuple)이 쌓여 테이블이 팽창한다. 운영 대응은?","o":["VACUUM(autovacuum 포함)으로 죽은 튜플 공간을 회수하고, 필요 시 VACUUM FULL·통계 갱신으로 팽창을 관리한다","인덱스를 모두 삭제한다","MVCC를 끈다","테이블을 매번 DROP 후 재생성한다"],"a":0,"ex":"VACUUM으로 dead tuple을 회수하고 autovacuum을 적절히 튜닝한다.\n💡 개념: MVCC는 옛 버전을 즉시 지우지 않으므로 정리 작업이 없으면 테이블/인덱스가 부풀어 오른다.\n🛠 실무: 갱신이 잦은 대형 테이블은 autovacuum 임계치를 낮추고, 심한 팽창은 VACUUM FULL 대신 pg_repack으로 온라인 정리한다."},{"t":"choice","k":"핫로우 카운터","cat":"ops","q":"인기 게시글 조회수 UPDATE views = views + 1 이 동시 요청으로 병목이다. read-modify-write 경합을 줄이는 실무적 방법은?","o":["DB 원자 증가(views = views + 1)는 갱신 손실은 없지만 핫로우 경합이 남는다 → 배치/버퍼링 후 주기적 반영하거나 카운터를 샤딩해 분산한다","앱에서 SELECT 후 계산해 UPDATE하면 더 정확하다","views 컬럼에 UNIQUE 인덱스를 건다","조회수를 트랜잭션 없이 두 번 올린다"],"a":0,"ex":"원자 증가로 정확성은 확보되나 핫로우 경합은 버퍼링/샤딩으로 완화한다.\n💡 개념: 같은 한 행에 쓰기가 몰리면 행 잠금 대기가 직렬화 병목이 된다.\n🛠 실무: 메모리(Redis)에서 집계 후 주기적으로 flush하거나, 여러 서브카운터로 나눠 쓰고 읽을 때 합산한다."}],"th":{"sum":"돈 계산은 **하나의 트랜잭션**으로 원자성(A)을 지키고, 재고 경합은 잠금이나 **낙관적 락**으로 막는다. `MVCC` 덕에 읽기와 쓰기가 서로 막지 않는다.","body":[{"h":"트랜잭션과 동시성","t":"출금·입금은 한 트랜잭션으로 묶어야 중간 장애 시 전부 롤백되어 돈이 증발하지 않는다(A=원자성, 한글로 '원자성'). 재고 1개에 동시 주문 2건이 -1이 되는 read-modify-write 경합은, `SELECT ... FOR UPDATE`로 행을 잠그거나 `UPDATE ... SET stock=stock-1 WHERE stock>0`처럼 조건부 갱신으로 막는다. 낙관적 락은 version 컬럼을 두고 `UPDATE ... WHERE version=?`로 갱신 후 영향 행 수 0이면 충돌로 감지·재시도한다."},{"h":"MVCC와 격리","t":"같은 조건 재조회 사이 행 수가 달라지면 Phantom Read다. 표준 SQL에서 REPEATABLE READ는 팬텀을 막아주지 못하므로 `SERIALIZABLE`로 올리거나 범위(갭) 락으로 대응한다(MySQL InnoDB는 REPEATABLE READ에서도 갭 락으로 상당수 방지한다). PostgreSQL에서 대량 UPDATE 중에도 SELECT가 안 막히는 이유는 **MVCC**로 각자 스냅샷 버전을 읽기 때문이다(약어 MVCC)."}],"code":{"c":"-- 낙관적 락: version 비교\nUPDATE stock\nSET qty = qty - 1, version = version + 1\nWHERE id = 10 AND version = 3;\n-- 영향 행 0이면 충돌 → 재시도","cap":"version으로 동시 수정 충돌 감지"},"key":["이체는 한 트랜잭션(A=원자성)","재고 경합은 `FOR UPDATE`/조건부 UPDATE/낙관적 락","읽기·쓰기 비차단의 원리는 MVCC, 재조회 행 변화=Phantom(표준상 SERIALIZABLE로 방지)"]}},{"t":"확장과 대용량 운영","q":[{"t":"choice","k":"읽기 복제본","cat":"design","q":"읽기 트래픽이 폭증해 단일 DB가 한계다. 쓰기보다 읽기가 압도적으로 많을 때의 확장 설계는?","o":["읽기 복제본(read replica)을 두어 읽기 쿼리를 분산한다 → 쓰기는 primary, 읽기는 replica로 보내되 복제 지연(replication lag)을 감안한다","인덱스를 모두 제거해 쓰기를 빠르게 한다","모든 쿼리를 하나의 커넥션으로 처리한다","트랜잭션 격리 수준을 낮춘다"],"a":0,"ex":"읽기 복제본으로 읽기 부하를 수평 분산한다.\n💡 개념: 복제본은 primary의 변경을 비동기로 따라가므로 약간의 지연 후 최신값이 보인다.\n🛠 실무: 방금 쓴 데이터를 바로 읽어야 하는 흐름(read-your-writes)은 primary로 라우팅해 지연 문제를 피한다."},{"t":"choice","k":"파티셔닝","cat":"design","q":"수십억 행 로그 테이블에서 조회와 오래된 데이터 정리가 모두 느리다. 관리 설계는?","o":["날짜 등 기준으로 파티셔닝(예: 월별 range 파티션) → 조회는 파티션 프루닝으로 빨라지고, 오래된 데이터는 파티션 DROP으로 즉시 정리한다","인덱스를 하나 더 만들면 삭제도 빨라진다","테이블을 그대로 두고 서버 메모리만 늘린다","모든 컬럼을 TEXT로 바꾼다"],"a":0,"ex":"시간 기준 파티셔닝으로 조회 프루닝과 파티션 단위 삭제를 얻는다.\n💡 개념: 파티셔닝은 큰 테이블을 조각으로 나눠 관련 조각만 스캔하고 조각째 관리하게 한다.\n🛠 실무: 대량 DELETE 대신 오래된 파티션을 DROP/DETACH하면 잠금·부하 없이 즉시 정리된다."},{"t":"input","k":"파티션 프루닝","cat":"design","q":"WHERE 조건에 맞지 않는 파티션을 옵티마이저가 아예 읽지 않고 건너뛰는 최적화 용어는? (한글 또는 영문)","a":["파티션 프루닝","프루닝","partition pruning","pruning"],"ex":"파티션 프루닝(partition pruning)이다.\n💡 개념: 파티션 키 조건으로 불필요한 파티션을 계획 단계에서 제외해 스캔량을 줄인다.\n🛠 실무: 프루닝이 먹으려면 쿼리 WHERE에 파티션 키 조건이 SARGable하게 들어가야 한다."},{"t":"choice","k":"비정규화 판단","cat":"design","q":"조인이 너무 많아 읽기 지연이 큰 리포트 화면이 있다. 시니어의 판단으로 적절한 것은?","o":["읽기 성능을 위해 선택적 비정규화(집계 컬럼·요약 테이블·구체화 뷰)를 도입하되, 쓰기 시 정합성 유지 비용과의 트레이드오프를 명시적으로 관리한다","항상 최대한 정규화하는 것이 모든 상황에서 옳다","모든 테이블을 하나로 합친다","조인은 무조건 나쁘므로 전부 제거한다"],"a":0,"ex":"읽기 병목엔 선택적 비정규화를 쓰되 정합성 비용을 함께 설계한다.\n💡 개념: 정규화는 무결성·쓰기에, 비정규화는 읽기 성능에 유리한 트레이드오프다.\n🛠 실무: 요약 테이블/materialized view로 사전 집계하고 갱신 주기와 정합성 허용 범위를 합의한다."},{"t":"choice","k":"샤딩","cat":"design","q":"쓰기 처리량 자체가 단일 서버 한계를 넘었다(읽기 복제본으로도 부족). 확장 방향은?","o":["샤딩(수평 분할)으로 데이터를 샤드 키 기준으로 여러 노드에 분산해 쓰기 부하를 나눈다 → 크로스 샤드 조인·트랜잭션 복잡도라는 비용을 수반한다","읽기 복제본을 더 늘리면 쓰기도 빨라진다","인덱스를 더 만들면 쓰기 병목이 사라진다","컬럼을 늘리면 해결된다"],"a":0,"ex":"쓰기 확장은 샤딩으로 데이터를 노드에 분산한다.\n💡 개념: 복제본은 읽기만 늘려주지만, 샤딩은 쓰기까지 분산한다.\n🛠 실무: 샤드 키 선정이 핵심이며 크로스 샤드 조인·분산 트랜잭션·리밸런싱 비용을 감안해 최후 수단으로 택한다."}],"th":{"sum":"돈 계산은 **하나의 트랜잭션**으로 원자성(A)을 지키고, 재고 경합은 잠금이나 **낙관적 락**으로 막는다. `MVCC` 덕에 읽기와 쓰기가 서로 막지 않는다.","body":[{"h":"트랜잭션과 동시성","t":"출금·입금은 한 트랜잭션으로 묶어야 중간 장애 시 전부 롤백되어 돈이 증발하지 않는다(A=원자성, 한글로 '원자성'). 재고 1개에 동시 주문 2건이 -1이 되는 read-modify-write 경합은, `SELECT ... FOR UPDATE`로 행을 잠그거나 `UPDATE ... SET stock=stock-1 WHERE stock>0`처럼 조건부 갱신으로 막는다. 낙관적 락은 version 컬럼을 두고 `UPDATE ... WHERE version=?`로 갱신 후 영향 행 수 0이면 충돌로 감지·재시도한다."},{"h":"MVCC와 격리","t":"같은 조건 재조회 사이 행 수가 달라지면 Phantom Read다. 표준 SQL에서 REPEATABLE READ는 팬텀을 막아주지 못하므로 `SERIALIZABLE`로 올리거나 범위(갭) 락으로 대응한다(MySQL InnoDB는 REPEATABLE READ에서도 갭 락으로 상당수 방지한다). PostgreSQL에서 대량 UPDATE 중에도 SELECT가 안 막히는 이유는 **MVCC**로 각자 스냅샷 버전을 읽기 때문이다(약어 MVCC)."}],"code":{"c":"-- 낙관적 락: version 비교\nUPDATE stock\nSET qty = qty - 1, version = version + 1\nWHERE id = 10 AND version = 3;\n-- 영향 행 0이면 충돌 → 재시도","cap":"version으로 동시 수정 충돌 감지"},"key":["이체는 한 트랜잭션(A=원자성)","재고 경합은 `FOR UPDATE`/조건부 UPDATE/낙관적 락","읽기·쓰기 비차단의 원리는 MVCC, 재조회 행 변화=Phantom(표준상 SERIALIZABLE로 방지)"]}}]},{"t":"실무 디버깅 — 잘못된 결과 고치기","l":[{"t":"디버깅 I","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"모든 직원과 소속 부서명을 조회하려 한다. 부서가 없거나(NULL) 존재하지 않는 부서를 가진 직원도 부서명은 NULL로 하여 반드시 결과에 포함되어야 한다. 그러나 현재 쿼리는 그런 직원을 통째로 누락시킨다.","schema":"CREATE TABLE departments (id INTEGER, name TEXT);\nINSERT INTO departments VALUES (10,'영업'),(20,'인사');\nCREATE TABLE employees (id INTEGER, name TEXT, dept_id INTEGER);\nINSERT INTO employees VALUES (1,'김',10),(2,'이',20),(3,'박',NULL),(4,'최',99);","src":"SELECT e.name AS emp_name, d.name AS dept_name\nFROM employees e\nJOIN departments d ON e.dept_id = d.id;","sol":"SELECT e.name AS emp_name, d.name AS dept_name\nFROM employees e\nLEFT JOIN departments d ON e.dept_id = d.id;","ordered":false,"ex":"🐛 원인: INNER JOIN은 조인 조건에 매칭되는 행만 남기므로 dept_id가 NULL이거나 부서 테이블에 없는 값을 가진 직원이 제거된다.\n🔧 해결: 기준 테이블(employees)의 모든 행을 보존하도록 INNER JOIN을 LEFT JOIN으로 변경한다.\n🛡 재발 방지: '~가 없어도 포함'이라는 요구사항이 있으면 기준 테이블을 왼쪽에 두고 LEFT JOIN을 기본으로 검토한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"부서별 전체 직원 수를 구해야 한다. 전화번호 등록 여부와 무관하게 모든 직원이 집계되어야 하는데, 현재 쿼리는 전화번호가 없는 직원을 빼고 센다.","schema":"CREATE TABLE employees (id INTEGER, name TEXT, dept TEXT, phone TEXT);\nINSERT INTO employees VALUES\n (1,'김','영업','010-1'),\n (2,'이','영업',NULL),\n (3,'박','인사',NULL),\n (4,'최','인사','010-2'),\n (5,'정','인사','010-3');","src":"SELECT dept, COUNT(phone) AS cnt\nFROM employees\nGROUP BY dept;","sol":"SELECT dept, COUNT(*) AS cnt\nFROM employees\nGROUP BY dept;","ordered":false,"ex":"🐛 원인: COUNT(col)은 해당 컬럼이 NULL이 아닌 행만 센다. phone이 NULL인 직원이 집계에서 빠졌다.\n🔧 해결: 행 수 자체를 세려면 COUNT(*)를 사용한다.\n🛡 재발 방지: '몇 건/몇 명'처럼 행 개수를 셀 때는 COUNT(*), 특정 값이 존재하는 건수를 셀 때만 COUNT(col)을 쓴다고 구분한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"평균 급여가 5000을 초과하는 부서만 조회해야 한다. 그러나 현재 쿼리는 급여가 5000을 넘는 직원이 한 명이라도 있는 부서를 반환하여, 평균은 5000 이하인 부서까지 포함시킨다.","schema":"CREATE TABLE emp (name TEXT, dept TEXT, salary INTEGER);\nINSERT INTO emp VALUES\n ('a','A',3000),('b','A',4000),\n ('c','B',6000),('d','B',3000),\n ('e','C',8000),('f','C',9000);","src":"SELECT dept\nFROM emp\nWHERE salary > 5000\nGROUP BY dept;","sol":"SELECT dept\nFROM emp\nGROUP BY dept\nHAVING AVG(salary) > 5000;","ordered":false,"ex":"🐛 원인: WHERE는 그룹화 전 개별 행을 거르므로 '급여&gt;5000인 직원이 존재하는 부서'를 뽑는다. 집계값(평균)에 대한 조건이 아니다.\n🔧 해결: 그룹 집계 결과에 대한 조건은 HAVING AVG(salary) &gt; 5000 으로 표현한다.\n🛡 재발 방지: 조건이 개별 행 기준인지 그룹 집계 기준인지 먼저 판단해 WHERE와 HAVING을 나눈다."},{"t":"sql","k":"디버깅","cat":"debug","q":"주문을 고객과 조인해 각 주문의 실제 주문 고객 이름과 금액을 조회해야 한다. 그러나 현재 쿼리는 엉뚱한 컬럼으로 조인해 서로 다른 고객에 금액이 붙는다.","schema":"CREATE TABLE customers (id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'김'),(2,'이'),(3,'박');\nCREATE TABLE orders (id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,2,100),(2,3,200),(3,1,300);","src":"SELECT c.name AS name, o.amount AS amount\nFROM orders o\nJOIN customers c ON o.id = c.id;","sol":"SELECT c.name AS name, o.amount AS amount\nFROM orders o\nJOIN customers c ON o.customer_id = c.id;","ordered":false,"ex":"🐛 원인: 조인 키를 o.customer_id 대신 o.id로 잘못 지정해, 주문의 PK와 고객의 PK를 매칭했다. 우연히 실행은 되지만 잘못된 고객과 연결된다.\n🔧 해결: 외래키인 o.customer_id = c.id 로 조인 조건을 수정한다.\n🛡 재발 방지: 조인 시 어느 컬럼이 외래키인지 명확히 확인하고, id끼리 무심코 잇지 않는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"과목별 평균 점수를 소수점까지 정확히 구해야 한다. 그러나 현재 쿼리는 정수 나눗셈으로 소수부가 버려져 90.5가 90으로 나온다.","schema":"CREATE TABLE scores (subject TEXT, score INTEGER);\nINSERT INTO scores VALUES ('수학',90),('수학',91),('과학',80),('과학',85);","src":"SELECT subject, SUM(score)/COUNT(*) AS avg_score\nFROM scores\nGROUP BY subject;","sol":"SELECT subject, AVG(score) AS avg_score\nFROM scores\nGROUP BY subject;","ordered":false,"ex":"🐛 원인: SUM(score)와 COUNT(*)가 모두 정수라 정수 나눗셈이 일어나 소수부가 절삭된다.\n🔧 해결: AVG(score)를 쓰거나 SUM(score)*1.0/COUNT(*)처럼 실수로 승격시킨다.\n🛡 재발 방지: 평균/비율 계산에서는 최소 한쪽 피연산자를 실수로 만들어 정수 나눗셈을 피한다."}],"th":{"sum":"SQL 버그는 대개 **에러 없이 조용히 틀린 결과**를 낸다. 행이 사라지거나, 중복으로 부풀거나, NULL이 조용히 빠진다.","body":[{"h":"행이 사라지거나 부풀어나는 이유","t":"`INNER JOIN`은 짝이 없는 행을 버린다 — 주문 없는 회원까지 세야 한다면 `LEFT JOIN`이어야 한다. 반대로 1:N 조인 뒤 `SUM`을 하면 같은 값이 N번 더해져 부풀어난다(팬아웃). `LEFT JOIN` 후 오른쪽 테이블 컬럼을 `WHERE`에 쓰면 NULL이 걸러져 사실상 `INNER JOIN`이 되어버린다 — 그 조건은 `ON`에 둬야 한다."},{"h":"NULL과 집계의 함정","t":"`COUNT(col)`은 NULL을 세지 않지만 `COUNT(*)`는 모든 행을 센다. NULL은 `= NULL`로 비교되지 않고 `IS NULL`을 써야 한다. 집계 결과를 거르는 조건은 `WHERE`가 아니라 `HAVING`에 와야 하고, `WHERE`는 집계 전 행을 거른다. 정수끼리 나누면 소수점이 잘린다."},{"h":"검증 습관","t":"의심되면 집계 전 원본 행을 먼저 조회해 몇 행이 나오는지 확인하고, 실행 계획(`EXPLAIN`)으로 인덱스를 타는지 본다. '몇 행이 나와야 정상인가'를 먼저 정하고 쿼리를 쓰면 조용한 오차를 잡을 수 있다."}],"code":{"c":"-- 버그: LEFT JOIN 해놓고 오른쪽 컬럼을 WHERE에 두면 INNER JOIN이 된다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.status = 'paid'      -- 주문 없는 회원이 통째로 사라짐\nGROUP BY u.name;\n\n-- 수정: 조건을 ON으로 옮긴다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id AND o.status = 'paid'\nGROUP BY u.name;","cap":"LEFT JOIN의 조건 위치 하나로 결과 집합이 달라진다."},"key":["INNER JOIN은 짝 없는 행을 버린다 — 필요하면 LEFT JOIN","LEFT JOIN 뒤 오른쪽 컬럼 조건은 WHERE가 아니라 ON에","1:N 조인 후 SUM은 팬아웃으로 부풀어난다","COUNT(col)은 NULL 제외, 집계 후 필터는 HAVING"]}},{"t":"디버깅 II","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"food 카테고리 상품 중 가격이 1000 미만이거나 5000 초과인 것만 조회해야 한다. 그러나 현재 쿼리는 괄호가 없어 food가 아닌 고가 상품까지 포함된다.","schema":"CREATE TABLE products (id INTEGER, name TEXT, category TEXT, price INTEGER);\nINSERT INTO products VALUES\n (1,'a','food',500),\n (2,'b','food',6000),\n (3,'c','food',3000),\n (4,'d','toy',7000),\n (5,'e','toy',200);","src":"SELECT id\nFROM products\nWHERE category = 'food' AND price < 1000 OR price > 5000;","sol":"SELECT id\nFROM products\nWHERE category = 'food' AND (price < 1000 OR price > 5000);","ordered":false,"ex":"🐛 원인: AND가 OR보다 우선순위가 높아 (category='food' AND price&lt;1000) OR price&gt;5000 로 해석된다. 그래서 카테고리와 무관한 price&gt;5000 상품이 모두 포함된다.\n🔧 해결: 의도한 OR 묶음을 괄호로 감싼다: category='food' AND (price&lt;1000 OR price&gt;5000).\n🛡 재발 방지: AND와 OR를 함께 쓸 때는 항상 괄호로 결합 순서를 명시한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"담당자가 아직 지정되지 않은(assignee가 NULL) 작업을 조회해야 한다. 그러나 현재 쿼리는 아무 행도 반환하지 않는다.","schema":"CREATE TABLE tasks (id INTEGER, title TEXT, assignee TEXT);\nINSERT INTO tasks VALUES (1,'x','김'),(2,'y',NULL),(3,'z',NULL),(4,'w','이');","src":"SELECT id\nFROM tasks\nWHERE assignee = NULL;","sol":"SELECT id\nFROM tasks\nWHERE assignee IS NULL;","ordered":false,"ex":"🐛 원인: NULL은 =로 비교하면 결과가 참이 아니라 UNKNOWN이 되어 어떤 행도 통과하지 못한다.\n🔧 해결: NULL 여부는 IS NULL / IS NOT NULL 로 검사한다.\n🛡 재발 방지: NULL 비교에는 절대 = 나 != 를 쓰지 않고 IS (NOT) NULL을 사용한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"블랙리스트에 없는 사용자를 조회해야 한다. 그러나 블랙리스트에 NULL 값이 섞여 있어 현재 쿼리는 아무도 반환하지 않는다.","schema":"CREATE TABLE users (id INTEGER, name TEXT);\nINSERT INTO users VALUES (1,'김'),(2,'이'),(3,'박'),(4,'최');\nCREATE TABLE blacklist (user_id INTEGER);\nINSERT INTO blacklist VALUES (2),(NULL);","src":"SELECT id\nFROM users\nWHERE id NOT IN (SELECT user_id FROM blacklist);","sol":"SELECT id\nFROM users\nWHERE id NOT IN (SELECT user_id FROM blacklist WHERE user_id IS NOT NULL);","ordered":false,"ex":"🐛 원인: NOT IN 목록에 NULL이 포함되면 모든 비교가 UNKNOWN이 되어 전체 결과가 비게 된다.\n🔧 해결: 서브쿼리에서 NULL을 제거하거나 NOT EXISTS 패턴으로 바꾼다.\n🛡 재발 방지: NOT IN 서브쿼리 대상 컬럼에 NULL 가능성이 있으면 반드시 걸러내거나 NOT EXISTS를 쓴다."},{"t":"sql","k":"디버깅","cat":"debug","q":"2023년 1월 주문 목록을 날짜 오름차순으로 조회해야 한다. 그러나 현재 쿼리는 상한을 잘못 잡아 1월 31일 주문을 누락한다.","schema":"CREATE TABLE orders (id INTEGER, order_date TEXT, amount INTEGER);\nINSERT INTO orders VALUES\n (1,'2023-01-01',100),\n (2,'2023-01-15',200),\n (3,'2023-01-31',300),\n (4,'2023-02-01',400);","src":"SELECT id, order_date\nFROM orders\nWHERE order_date >= '2023-01-01' AND order_date < '2023-01-31'\nORDER BY order_date;","sol":"SELECT id, order_date\nFROM orders\nWHERE order_date >= '2023-01-01' AND order_date < '2023-02-01'\nORDER BY order_date;","ordered":true,"ex":"🐛 원인: 상한을 order_date &lt; '2023-01-31'로 잡아 31일이 경계에서 제외되는 off-by-one 오류다.\n🔧 해결: 다음 달 1일 미만(&lt; '2023-02-01') 또는 &lt;= '2023-01-31'로 상한을 잡는다.\n🛡 재발 방지: 기간 필터는 [시작 &lt;= x &lt; 다음구간시작] 반열린구간 관례로 통일해 경계 누락을 막는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"삭제되지 않은 활성 회원만 조회해야 한다. 그러나 현재 쿼리는 소프트 삭제(is_deleted=1) 필터를 빠뜨려 삭제된 회원까지 반환한다.","schema":"CREATE TABLE members (id INTEGER, name TEXT, is_deleted INTEGER);\nINSERT INTO members VALUES (1,'김',0),(2,'이',1),(3,'박',0),(4,'최',1);","src":"SELECT id, name\nFROM members;","sol":"SELECT id, name\nFROM members\nWHERE is_deleted = 0;","ordered":false,"ex":"🐛 원인: 소프트 삭제 플래그(is_deleted)를 조건에 넣지 않아 논리적으로 삭제된 행까지 조회된다.\n🔧 해결: WHERE is_deleted = 0 조건을 추가해 활성 행만 남긴다.\n🛡 재발 방지: 소프트 삭제 테이블은 조회 시 항상 삭제 플래그 필터를 기본으로 넣거나 뷰로 캡슐화한다."}],"th":{"sum":"SQL 버그는 대개 **에러 없이 조용히 틀린 결과**를 낸다. 행이 사라지거나, 중복으로 부풀거나, NULL이 조용히 빠진다.","body":[{"h":"행이 사라지거나 부풀어나는 이유","t":"`INNER JOIN`은 짝이 없는 행을 버린다 — 주문 없는 회원까지 세야 한다면 `LEFT JOIN`이어야 한다. 반대로 1:N 조인 뒤 `SUM`을 하면 같은 값이 N번 더해져 부풀어난다(팬아웃). `LEFT JOIN` 후 오른쪽 테이블 컬럼을 `WHERE`에 쓰면 NULL이 걸러져 사실상 `INNER JOIN`이 되어버린다 — 그 조건은 `ON`에 둬야 한다."},{"h":"NULL과 집계의 함정","t":"`COUNT(col)`은 NULL을 세지 않지만 `COUNT(*)`는 모든 행을 센다. NULL은 `= NULL`로 비교되지 않고 `IS NULL`을 써야 한다. 집계 결과를 거르는 조건은 `WHERE`가 아니라 `HAVING`에 와야 하고, `WHERE`는 집계 전 행을 거른다. 정수끼리 나누면 소수점이 잘린다."},{"h":"검증 습관","t":"의심되면 집계 전 원본 행을 먼저 조회해 몇 행이 나오는지 확인하고, 실행 계획(`EXPLAIN`)으로 인덱스를 타는지 본다. '몇 행이 나와야 정상인가'를 먼저 정하고 쿼리를 쓰면 조용한 오차를 잡을 수 있다."}],"code":{"c":"-- 버그: LEFT JOIN 해놓고 오른쪽 컬럼을 WHERE에 두면 INNER JOIN이 된다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.status = 'paid'      -- 주문 없는 회원이 통째로 사라짐\nGROUP BY u.name;\n\n-- 수정: 조건을 ON으로 옮긴다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id AND o.status = 'paid'\nGROUP BY u.name;","cap":"LEFT JOIN의 조건 위치 하나로 결과 집합이 달라진다."},"key":["INNER JOIN은 짝 없는 행을 버린다 — 필요하면 LEFT JOIN","LEFT JOIN 뒤 오른쪽 컬럼 조건은 WHERE가 아니라 ON에","1:N 조인 후 SUM은 팬아웃으로 부풀어난다","COUNT(col)은 NULL 제외, 집계 후 필터는 HAVING"]}},{"t":"디버깅 III","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"결제가 있는 주문에 대해 고객별 주문 금액 합계를 구해야 한다. 각 주문 금액은 한 번만 더해야 하는데, 현재 쿼리는 분할 결제 등으로 결제 행이 여러 개인 주문의 금액을 중복 합산한다.","schema":"CREATE TABLE orders (id INTEGER, customer TEXT, amount INTEGER);\nINSERT INTO orders VALUES (1,'김',100),(2,'김',200),(3,'이',300);\nCREATE TABLE payments (order_id INTEGER, memo TEXT);\nINSERT INTO payments VALUES (1,'1차'),(1,'2차'),(2,'완납'),(3,'완납');","src":"SELECT o.customer AS customer, SUM(o.amount) AS total\nFROM orders o\nJOIN payments p ON p.order_id = o.id\nGROUP BY o.customer;","sol":"SELECT customer, SUM(amount) AS total\nFROM orders\nWHERE id IN (SELECT order_id FROM payments)\nGROUP BY customer;","ordered":false,"ex":"🐛 원인: 주문 1개에 결제 행이 여러 개면 조인 후 주문 행이 결제 수만큼 복제되어(fan-out) SUM(amount)가 중복 합산된다.\n🔧 해결: 금액 합산은 주문 단위로 하고, 결제 존재 여부는 조인 대신 EXISTS/IN 서브쿼리로 판단한다.\n🛡 재발 방지: 1:N 조인 후 집계할 때 값이 부풀려지지 않는지 확인하고, 필요 시 집계를 조인 전에 분리한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"모든 판매 건의 총 매출액을 구해야 한다. 그러나 현재 쿼리는 DISTINCT 때문에 금액이 같은 판매 건을 한 번만 더해 합계가 과소 집계된다.","schema":"CREATE TABLE sales (id INTEGER, amount INTEGER);\nINSERT INTO sales VALUES (1,100),(2,100),(3,200),(4,300),(5,300);","src":"SELECT SUM(DISTINCT amount) AS total\nFROM sales;","sol":"SELECT SUM(amount) AS total\nFROM sales;","ordered":false,"ex":"🐛 원인: SUM(DISTINCT amount)는 중복 금액을 한 번만 더하므로 같은 금액의 서로 다른 판매 건이 무시된다.\n🔧 해결: 모든 건을 합산하려면 DISTINCT 없이 SUM(amount)를 쓴다.\n🛡 재발 방지: DISTINCT는 '고유 값'이 정말 필요한 경우에만 쓰고, 건별 합계에는 사용하지 않는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"부서별 최고 급여를 구해야 한다. 그러나 GROUP BY가 빠져 전체에서 단 한 행(전체 최고 급여)만 반환된다.","schema":"CREATE TABLE emp (dept TEXT, salary INTEGER);\nINSERT INTO emp VALUES ('A',100),('A',200),('B',300),('B',150);","src":"SELECT dept, MAX(salary) AS max_salary\nFROM emp;","sol":"SELECT dept, MAX(salary) AS max_salary\nFROM emp\nGROUP BY dept;","ordered":false,"ex":"🐛 원인: GROUP BY 없이 집계함수를 쓰면 전체가 한 그룹으로 묶여 부서별로 나뉘지 않고 한 행만 나온다.\n🔧 해결: 부서 단위 집계를 위해 GROUP BY dept를 추가한다.\n🛡 재발 방지: '~별' 집계 요구사항은 반드시 해당 기준 컬럼을 GROUP BY에 넣는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"날짜별 고유 방문자 수(서로 다른 사용자 수)를 구해야 한다. 그러나 현재 쿼리는 방문 건수를 세어 같은 사용자의 재방문을 중복으로 센다.","schema":"CREATE TABLE visits (day TEXT, user_id INTEGER);\nINSERT INTO visits VALUES\n ('2023-01-01',1),('2023-01-01',1),('2023-01-01',2),\n ('2023-01-02',3),('2023-01-02',4);","src":"SELECT day, COUNT(*) AS cnt\nFROM visits\nGROUP BY day;","sol":"SELECT day, COUNT(DISTINCT user_id) AS cnt\nFROM visits\nGROUP BY day;","ordered":false,"ex":"🐛 원인: COUNT(*)는 방문 행 수를 세므로 동일 사용자의 재방문이 각각 카운트되어 고유 방문자 수보다 커진다.\n🔧 해결: 고유 사용자 수는 COUNT(DISTINCT user_id)로 센다.\n🛡 재발 방지: '고유/서로 다른' 개수는 COUNT(DISTINCT col)을 쓴다고 명확히 구분한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"모든 고객과 그들의 2023년 주문 건수를 구하되, 2023년 주문이 없는 고객은 0으로 표시해 반드시 포함해야 한다. 그러나 현재 쿼리는 WHERE 조건 때문에 주문 없는 고객이 사라진다.","schema":"CREATE TABLE customers (id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'김'),(2,'이'),(3,'박');\nCREATE TABLE orders (id INTEGER, customer_id INTEGER, order_year INTEGER);\nINSERT INTO orders VALUES (1,1,2023),(2,1,2022),(3,2,2023);","src":"SELECT c.name AS name, COUNT(o.id) AS cnt\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.order_year = 2023\nGROUP BY c.name;","sol":"SELECT c.name AS name, COUNT(o.id) AS cnt\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id AND o.order_year = 2023\nGROUP BY c.name;","ordered":false,"ex":"🐛 원인: LEFT JOIN 뒤 WHERE에서 오른쪽 테이블 컬럼(o.order_year)을 조건으로 걸면, 매칭 없는 행의 NULL이 조건을 통과하지 못해 사실상 INNER JOIN이 되어 주문 없는 고객이 제거된다.\n🔧 해결: 오른쪽 테이블에 대한 필터 조건을 WHERE가 아니라 조인 ON 절로 옮긴다.\n🛡 재발 방지: LEFT JOIN에서 오른쪽 테이블 조건은 ON 절에 두고, WHERE에는 왼쪽 테이블 기준 조건만 둔다."}],"th":{"sum":"SQL 버그는 대개 **에러 없이 조용히 틀린 결과**를 낸다. 행이 사라지거나, 중복으로 부풀거나, NULL이 조용히 빠진다.","body":[{"h":"행이 사라지거나 부풀어나는 이유","t":"`INNER JOIN`은 짝이 없는 행을 버린다 — 주문 없는 회원까지 세야 한다면 `LEFT JOIN`이어야 한다. 반대로 1:N 조인 뒤 `SUM`을 하면 같은 값이 N번 더해져 부풀어난다(팬아웃). `LEFT JOIN` 후 오른쪽 테이블 컬럼을 `WHERE`에 쓰면 NULL이 걸러져 사실상 `INNER JOIN`이 되어버린다 — 그 조건은 `ON`에 둬야 한다."},{"h":"NULL과 집계의 함정","t":"`COUNT(col)`은 NULL을 세지 않지만 `COUNT(*)`는 모든 행을 센다. NULL은 `= NULL`로 비교되지 않고 `IS NULL`을 써야 한다. 집계 결과를 거르는 조건은 `WHERE`가 아니라 `HAVING`에 와야 하고, `WHERE`는 집계 전 행을 거른다. 정수끼리 나누면 소수점이 잘린다."},{"h":"검증 습관","t":"의심되면 집계 전 원본 행을 먼저 조회해 몇 행이 나오는지 확인하고, 실행 계획(`EXPLAIN`)으로 인덱스를 타는지 본다. '몇 행이 나와야 정상인가'를 먼저 정하고 쿼리를 쓰면 조용한 오차를 잡을 수 있다."}],"code":{"c":"-- 버그: LEFT JOIN 해놓고 오른쪽 컬럼을 WHERE에 두면 INNER JOIN이 된다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.status = 'paid'      -- 주문 없는 회원이 통째로 사라짐\nGROUP BY u.name;\n\n-- 수정: 조건을 ON으로 옮긴다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id AND o.status = 'paid'\nGROUP BY u.name;","cap":"LEFT JOIN의 조건 위치 하나로 결과 집합이 달라진다."},"key":["INNER JOIN은 짝 없는 행을 버린다 — 필요하면 LEFT JOIN","LEFT JOIN 뒤 오른쪽 컬럼 조건은 WHERE가 아니라 ON에","1:N 조인 후 SUM은 팬아웃으로 부풀어난다","COUNT(col)은 NULL 제외, 집계 후 필터는 HAVING"]}},{"t":"디버깅 IV","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"고객별 '완료(completed)' 주문 금액 합계를 구하되, 완료 주문이 없는 고객도 합계 0으로 포함해야 한다. 아래 쿼리는 완료 주문이 하나도 없는 고객(Park)을 결과에서 통째로 누락시킨다. 모든 고객이 나오도록 고쳐라.","schema":"CREATE TABLE customer (id INTEGER, name TEXT);\nINSERT INTO customer VALUES (1,'Kim'),(2,'Lee'),(3,'Park');\n\nCREATE TABLE orders (id INTEGER, customer_id INTEGER, status TEXT, amount INTEGER);\nINSERT INTO orders VALUES\n  (10,1,'completed',100),\n  (11,1,'cancelled',50),\n  (12,2,'completed',200);","src":"SELECT c.name, COALESCE(SUM(o.amount),0) AS total\nFROM customer c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.status = 'completed'\nGROUP BY c.id\nORDER BY c.id;","sol":"SELECT c.name, COALESCE(SUM(CASE WHEN o.status='completed' THEN o.amount END),0) AS total\nFROM customer c\nLEFT JOIN orders o ON o.customer_id = c.id\nGROUP BY c.id\nORDER BY c.id;","ordered":true,"ex":"🐛 원인: LEFT JOIN 이후 WHERE 절에서 오른쪽 테이블 컬럼(o.status)을 조건으로 걸면, 매칭 행이 없어 NULL이 채워진 고객 행은 'NULL = completed'가 거짓이 되어 걸러진다. 결과적으로 LEFT JOIN이 INNER JOIN처럼 동작해 주문 없는 고객이 사라진다.\n🔧 해결: 오른쪽 테이블에 대한 필터를 WHERE가 아니라 JOIN의 ON 조건에 넣거나, 집계 시 CASE WHEN으로 조건부 합산한다. 그러면 LEFT JOIN의 보존 특성이 유지되어 Park도 total 0으로 남는다.\n🛡 재발 방지: LEFT JOIN을 쓸 때 오른쪽 테이블 컬럼 조건은 반드시 ON 절이나 조건부 집계로 처리하고, WHERE에는 NULL 허용 여부를 항상 점검한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"고객별 주문 매출 합계(orders.total의 합)를 구해야 한다. 아래 쿼리는 order_items와 조인하면서 아이템 수만큼 주문 금액이 중복 합산된다. 실제 매출(Kim=300, Lee=50)이 나오도록 고쳐라.","schema":"CREATE TABLE orders (id INTEGER, customer TEXT, total INTEGER);\nINSERT INTO orders VALUES (1,'Kim',100),(2,'Kim',200),(3,'Lee',50);\n\nCREATE TABLE order_items (order_id INTEGER, item TEXT);\nINSERT INTO order_items VALUES\n  (1,'A'),(1,'B'),\n  (2,'C'),\n  (3,'D'),(3,'E'),(3,'F');","src":"SELECT o.customer, SUM(o.total) AS revenue\nFROM orders o\nJOIN order_items i ON i.order_id = o.id\nGROUP BY o.customer\nORDER BY o.customer;","sol":"SELECT customer, SUM(total) AS revenue\nFROM orders\nGROUP BY customer\nORDER BY customer;","ordered":true,"ex":"🐛 원인: orders 1행이 order_items의 여러 행과 조인되면서(fan-out) 주문 한 건이 아이템 개수만큼 복제된다. 이 상태에서 SUM(o.total)을 하면 주문 금액이 아이템 수만큼 곱해져 과대 집계된다(예: 주문1의 100이 2번 더해짐).\n🔧 해결: 집계 대상(주문 금액)과 조인 대상(아이템)을 같은 레벨에서 SUM하지 않는다. 주문 금액 합계는 orders만으로 집계하거나, 아이템은 별도 서브쿼리로 미리 집계한 뒤 조인한다.\n🛡 재발 방지: 1:N 조인 후 '1쪽'의 값을 SUM할 때는 항상 fan-out으로 인한 중복 곱셈을 의심하고, 필요하면 사전 집계(pre-aggregation)로 조인 카디널리티를 1:1로 맞춘다."},{"t":"sql","k":"디버깅","cat":"debug","q":"급여의 '두 번째로 높은 서로 다른 급여액'과 그 직원을 찾아야 한다(정답: pay=90인 C). 아래 쿼리는 동점 처리 때문에 결과가 비어 버린다. C가 나오도록 고쳐라.","schema":"CREATE TABLE salary (name TEXT, pay INTEGER);\nINSERT INTO salary VALUES ('A',100),('B',100),('C',90),('D',80);","src":"SELECT name, pay\nFROM (\n  SELECT name, pay, RANK() OVER (ORDER BY pay DESC) AS rnk\n  FROM salary\n)\nWHERE rnk = 2\nORDER BY name;","sol":"SELECT name, pay\nFROM (\n  SELECT name, pay, DENSE_RANK() OVER (ORDER BY pay DESC) AS rnk\n  FROM salary\n)\nWHERE rnk = 2\nORDER BY name;","ordered":true,"ex":"🐛 원인: RANK()는 동점이 있으면 다음 순위를 건너뛴다. 100이 두 명이라 각각 rnk=1을 받고 그 다음 90은 rnk=3이 된다. 따라서 rnk=2 조건에 해당하는 행이 없어 결과가 공집합이 된다.\n🔧 해결: 연속된 순위가 필요할 때는 DENSE_RANK()를 쓴다. DENSE_RANK는 동점이 있어도 다음 순위를 건너뛰지 않아 90이 정확히 rnk=2가 된다.\n🛡 재발 방지: 'N번째로 큰(서로 다른) 값' 문제는 DENSE_RANK, '경쟁 순위(동점 시 건너뜀)'는 RANK, '고유 일련번호'는 ROW_NUMBER로 의도를 명확히 구분해 선택한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"부서별로 급여가 가장 높은 직원 1명씩(총 2명: eng의 A, sales의 C)을 뽑아야 한다. 아래 쿼리는 부서 구분 없이 전체에서 1등만 뽑아 sales의 C 한 명만 나온다. 부서별 1등이 모두 나오도록 고쳐라.","schema":"CREATE TABLE emp (name TEXT, dept TEXT, pay INTEGER);\nINSERT INTO emp VALUES\n  ('A','eng',100),\n  ('B','eng',90),\n  ('C','sales',120),\n  ('D','sales',80);","src":"SELECT name, dept, pay\nFROM (\n  SELECT name, dept, pay,\n         ROW_NUMBER() OVER (ORDER BY pay DESC) AS rn\n  FROM emp\n)\nWHERE rn = 1\nORDER BY dept;","sol":"SELECT name, dept, pay\nFROM (\n  SELECT name, dept, pay,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY pay DESC) AS rn\n  FROM emp\n)\nWHERE rn = 1\nORDER BY dept;","ordered":true,"ex":"🐛 원인: 윈도우 함수에 PARTITION BY dept가 빠져 있어 부서 구분 없이 전체 직원을 하나의 그룹으로 순번을 매긴다. 그 결과 전체 최고 급여자(C)만 rn=1이 되고 각 부서 1등이라는 의도가 무시된다.\n🔧 해결: 부서별로 순위를 리셋하도록 PARTITION BY dept를 추가한다. 그러면 부서마다 rn=1이 하나씩 생겨 A(eng), C(sales)가 모두 선택된다.\n🛡 재발 방지: '그룹별 상위 N' 요구사항에서는 윈도우 함수의 PARTITION BY가 그룹 키와 일치하는지 항상 먼저 확인한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"거래를 날짜순으로 누적 합계(running total)를 구해야 한다. 정답은 각 행마다 10, 30, 35로 한 행씩 누적되어야 한다. 아래 쿼리는 같은 날짜(2024-01-01)의 두 행이 모두 30으로 나온다. 행 단위로 누적되도록 고쳐라.","schema":"CREATE TABLE txn (id INTEGER, d TEXT, amt INTEGER);\nINSERT INTO txn VALUES\n  (1,'2024-01-01',10),\n  (2,'2024-01-01',20),\n  (3,'2024-01-02',5);","src":"SELECT id, amt,\n       SUM(amt) OVER (ORDER BY d) AS running\nFROM txn\nORDER BY id;","sol":"SELECT id, amt,\n       SUM(amt) OVER (ORDER BY d, id\n                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running\nFROM txn\nORDER BY id;","ordered":true,"ex":"🐛 원인: ORDER BY만 지정한 윈도우의 기본 프레임은 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW다. 정렬 키(d)에 동점(같은 날짜)이 있으면 동점 행들이 모두 '피어(peer)'로 묶여 같은 누적값(30)을 갖게 된다.\n🔧 해결: 고유한 보조 정렬 키(id)를 추가하고 프레임을 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW로 명시해 행 단위로 누적되게 한다.\n🛡 재발 방지: 누적 합계에는 정렬 키를 유일하게 만들고 프레임을 ROWS로 명시하는 습관을 들여, RANGE 기본 프레임의 동점 합산을 예방한다."}],"th":{"sum":"SQL 버그는 대개 **에러 없이 조용히 틀린 결과**를 낸다. 행이 사라지거나, 중복으로 부풀거나, NULL이 조용히 빠진다.","body":[{"h":"행이 사라지거나 부풀어나는 이유","t":"`INNER JOIN`은 짝이 없는 행을 버린다 — 주문 없는 회원까지 세야 한다면 `LEFT JOIN`이어야 한다. 반대로 1:N 조인 뒤 `SUM`을 하면 같은 값이 N번 더해져 부풀어난다(팬아웃). `LEFT JOIN` 후 오른쪽 테이블 컬럼을 `WHERE`에 쓰면 NULL이 걸러져 사실상 `INNER JOIN`이 되어버린다 — 그 조건은 `ON`에 둬야 한다."},{"h":"NULL과 집계의 함정","t":"`COUNT(col)`은 NULL을 세지 않지만 `COUNT(*)`는 모든 행을 센다. NULL은 `= NULL`로 비교되지 않고 `IS NULL`을 써야 한다. 집계 결과를 거르는 조건은 `WHERE`가 아니라 `HAVING`에 와야 하고, `WHERE`는 집계 전 행을 거른다. 정수끼리 나누면 소수점이 잘린다."},{"h":"검증 습관","t":"의심되면 집계 전 원본 행을 먼저 조회해 몇 행이 나오는지 확인하고, 실행 계획(`EXPLAIN`)으로 인덱스를 타는지 본다. '몇 행이 나와야 정상인가'를 먼저 정하고 쿼리를 쓰면 조용한 오차를 잡을 수 있다."}],"code":{"c":"-- 버그: LEFT JOIN 해놓고 오른쪽 컬럼을 WHERE에 두면 INNER JOIN이 된다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.status = 'paid'      -- 주문 없는 회원이 통째로 사라짐\nGROUP BY u.name;\n\n-- 수정: 조건을 ON으로 옮긴다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id AND o.status = 'paid'\nGROUP BY u.name;","cap":"LEFT JOIN의 조건 위치 하나로 결과 집합이 달라진다."},"key":["INNER JOIN은 짝 없는 행을 버린다 — 필요하면 LEFT JOIN","LEFT JOIN 뒤 오른쪽 컬럼 조건은 WHERE가 아니라 ON에","1:N 조인 후 SUM은 팬아웃으로 부풀어난다","COUNT(col)은 NULL 제외, 집계 후 필터는 HAVING"]}},{"t":"디버깅 V","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"서로 다른 고객이 2명 이상 주문한 상품만 찾아야 한다(정답: Y만). 아래 쿼리는 같은 고객의 중복 주문까지 세어 X도 잘못 포함한다. 서로 다른 고객 수 기준으로 고쳐라.","schema":"CREATE TABLE ord (product TEXT, customer TEXT);\nINSERT INTO ord VALUES\n  ('X','Kim'),\n  ('X','Kim'),\n  ('Y','Kim'),\n  ('Y','Lee');","src":"SELECT product\nFROM ord\nGROUP BY product\nHAVING COUNT(*) >= 2\nORDER BY product;","sol":"SELECT product\nFROM ord\nGROUP BY product\nHAVING COUNT(DISTINCT customer) >= 2\nORDER BY product;","ordered":true,"ex":"🐛 원인: COUNT(*)는 그룹 내 '행 수'를 세므로 같은 고객(Kim)이 X를 두 번 주문한 것도 2로 계산된다. '서로 다른 고객 수'라는 의도와 달라 X가 조건을 통과한다.\n🔧 해결: 고유 고객 수를 기준으로 하려면 COUNT(DISTINCT customer)를 사용한다. 그러면 X는 고유 고객이 1명이라 제외되고 Y만 남는다.\n🛡 재발 방지: '몇 명/몇 종류'처럼 중복 제거가 필요한 조건은 COUNT(*)가 아니라 COUNT(DISTINCT 컬럼)인지 요구사항을 문장 단위로 대조한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"모든 직원과 그 직속 상사 이름을 함께 출력해야 한다. 상사가 없는 최상위(CEO)는 상사 이름을 NULL로 포함해야 한다. 아래 쿼리는 CEO를 누락시킨다. CEO도 나오도록 고쳐라.","schema":"CREATE TABLE emp (id INTEGER, name TEXT, mgr_id INTEGER);\nINSERT INTO emp VALUES\n  (1,'CEO',NULL),\n  (2,'Kim',1),\n  (3,'Lee',1),\n  (4,'Park',2);","src":"SELECT e.name AS emp, m.name AS mgr\nFROM emp e\nJOIN emp m ON e.mgr_id = m.id\nORDER BY e.id;","sol":"SELECT e.name AS emp, m.name AS mgr\nFROM emp e\nLEFT JOIN emp m ON e.mgr_id = m.id\nORDER BY e.id;","ordered":true,"ex":"🐛 원인: 자기 조인을 INNER JOIN으로 하면 mgr_id가 NULL인 CEO는 매칭되는 상사 행이 없어 결과에서 빠진다.\n🔧 해결: 상사가 없는 직원도 보존하려면 LEFT JOIN을 사용한다. 그러면 CEO는 mgr가 NULL인 채로 결과에 포함된다.\n🛡 재발 방지: 계층/자기 참조 조인에서 '루트(상위 없음)' 행을 포함해야 하는지 확인하고, 포함해야 하면 LEFT JOIN을 사용한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"매니저가 아닌 직원(정답: Lee, Park)을 찾아야 한다. mgr 테이블에는 NULL 값이 섞여 있다. 아래 쿼리는 결과가 통째로 비어 버린다. 올바른 직원들이 나오도록 고쳐라.","schema":"CREATE TABLE emp (id INTEGER, name TEXT);\nINSERT INTO emp VALUES (1,'Kim'),(2,'Lee'),(3,'Park');\n\nCREATE TABLE mgr (emp_id INTEGER);\nINSERT INTO mgr VALUES (1),(NULL);","src":"SELECT name\nFROM emp\nWHERE id NOT IN (SELECT emp_id FROM mgr)\nORDER BY id;","sol":"SELECT name\nFROM emp e\nWHERE NOT EXISTS (SELECT 1 FROM mgr m WHERE m.emp_id = e.id)\nORDER BY id;","ordered":true,"ex":"🐛 원인: 서브쿼리 결과에 NULL이 포함되면 NOT IN은 3치 논리(UNKNOWN)로 인해 어떤 행도 TRUE가 되지 못한다. 'id NOT IN (1, NULL)'은 항상 UNKNOWN이 되어 전체 결과가 공집합이 된다.\n🔧 해결: NOT EXISTS를 사용하거나 서브쿼리에서 NULL을 제거(WHERE emp_id IS NOT NULL)한다. NOT EXISTS는 NULL에 영향을 받지 않아 Lee, Park을 정확히 반환한다.\n🛡 재발 방지: NOT IN 서브쿼리 컬럼이 NULL을 포함할 가능성이 있으면 NOT EXISTS로 대체하는 것을 기본 습관으로 삼는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"학생 점수의 평균을 구하되, 점수가 없는(NULL) 학생은 0점으로 간주해서 평균을 내야 한다(정답: (80+0+40)/3 = 40). 아래 쿼리는 NULL을 제외해 평균이 60으로 부풀려진다. 0으로 간주하도록 고쳐라.","schema":"CREATE TABLE score (student TEXT, s INTEGER);\nINSERT INTO score VALUES ('Kim',80),('Lee',NULL),('Park',40);","src":"SELECT AVG(s) AS avg_score\nFROM score;","sol":"SELECT AVG(COALESCE(s,0)) AS avg_score\nFROM score;","ordered":false,"ex":"🐛 원인: AVG()는 NULL을 계산 대상에서 아예 제외한다. 즉 분모(개수)에서도 빠져 (80+40)/2 = 60이 되어, NULL을 0점으로 보려는 의도와 달라진다.\n🔧 해결: NULL을 0으로 채운 뒤 평균을 내도록 AVG(COALESCE(s,0))로 바꾼다. 그러면 분모가 3명이 되어 (80+0+40)/3 = 40이 나온다.\n🛡 재발 방지: 집계 전에 NULL을 어떻게 취급할지(제외 vs 0으로 치환)를 명시하고, 0으로 봐야 하면 집계 함수 안에서 COALESCE로 먼저 치환한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"방문 로그에서 '순 방문자 수(고유 사용자 수)'를 구해야 한다(정답: 2). 아래 쿼리는 방문 로그 행 수(5)를 세어 버린다. 고유 사용자 수가 나오도록 고쳐라.","schema":"CREATE TABLE visit (user_id INTEGER, page TEXT);\nINSERT INTO visit VALUES\n  (1,'a'),(1,'b'),\n  (2,'a'),(2,'c'),(2,'d');","src":"SELECT COUNT(user_id) AS unique_users\nFROM visit;","sol":"SELECT COUNT(DISTINCT user_id) AS unique_users\nFROM visit;","ordered":false,"ex":"🐛 원인: COUNT(user_id)는 NULL이 아닌 행의 '개수'를 세므로 같은 사용자가 여러 번 방문하면 그만큼 중복 집계된다. 그래서 고유 사용자가 아니라 방문 행 수(5)가 나온다.\n🔧 해결: 고유 사용자 수는 COUNT(DISTINCT user_id)로 센다. 중복 방문이 제거되어 2가 나온다.\n🛡 재발 방지: '순(unique)/고유'라는 단어가 요구사항에 있으면 COUNT에 DISTINCT가 필요한지 반드시 점검한다."}],"th":{"sum":"SQL 버그는 대개 **에러 없이 조용히 틀린 결과**를 낸다. 행이 사라지거나, 중복으로 부풀거나, NULL이 조용히 빠진다.","body":[{"h":"행이 사라지거나 부풀어나는 이유","t":"`INNER JOIN`은 짝이 없는 행을 버린다 — 주문 없는 회원까지 세야 한다면 `LEFT JOIN`이어야 한다. 반대로 1:N 조인 뒤 `SUM`을 하면 같은 값이 N번 더해져 부풀어난다(팬아웃). `LEFT JOIN` 후 오른쪽 테이블 컬럼을 `WHERE`에 쓰면 NULL이 걸러져 사실상 `INNER JOIN`이 되어버린다 — 그 조건은 `ON`에 둬야 한다."},{"h":"NULL과 집계의 함정","t":"`COUNT(col)`은 NULL을 세지 않지만 `COUNT(*)`는 모든 행을 센다. NULL은 `= NULL`로 비교되지 않고 `IS NULL`을 써야 한다. 집계 결과를 거르는 조건은 `WHERE`가 아니라 `HAVING`에 와야 하고, `WHERE`는 집계 전 행을 거른다. 정수끼리 나누면 소수점이 잘린다."},{"h":"검증 습관","t":"의심되면 집계 전 원본 행을 먼저 조회해 몇 행이 나오는지 확인하고, 실행 계획(`EXPLAIN`)으로 인덱스를 타는지 본다. '몇 행이 나와야 정상인가'를 먼저 정하고 쿼리를 쓰면 조용한 오차를 잡을 수 있다."}],"code":{"c":"-- 버그: LEFT JOIN 해놓고 오른쪽 컬럼을 WHERE에 두면 INNER JOIN이 된다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.status = 'paid'      -- 주문 없는 회원이 통째로 사라짐\nGROUP BY u.name;\n\n-- 수정: 조건을 ON으로 옮긴다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id AND o.status = 'paid'\nGROUP BY u.name;","cap":"LEFT JOIN의 조건 위치 하나로 결과 집합이 달라진다."},"key":["INNER JOIN은 짝 없는 행을 버린다 — 필요하면 LEFT JOIN","LEFT JOIN 뒤 오른쪽 컬럼 조건은 WHERE가 아니라 ON에","1:N 조인 후 SUM은 팬아웃으로 부풀어난다","COUNT(col)은 NULL 제외, 집계 후 필터는 HAVING"]}},{"t":"디버깅 VI","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"고객별로 '가장 최근 날짜의 주문 금액'을 구해야 한다(정답: Kim=200, Lee=50). 아래 쿼리는 전체 최신 날짜만 기준으로 삼아 Lee가 누락된다. 고객별 최신 주문이 나오도록 고쳐라.","schema":"CREATE TABLE ord (id INTEGER, customer TEXT, d TEXT, amt INTEGER);\nINSERT INTO ord VALUES\n  (1,'Kim','2024-01-01',100),\n  (2,'Kim','2024-03-01',200),\n  (3,'Lee','2024-02-01',50);","src":"SELECT customer, amt\nFROM ord o\nWHERE d = (SELECT MAX(d) FROM ord)\nORDER BY customer;","sol":"SELECT customer, amt\nFROM ord o\nWHERE d = (SELECT MAX(d) FROM ord o2 WHERE o2.customer = o.customer)\nORDER BY customer;","ordered":true,"ex":"🐛 원인: 서브쿼리가 바깥 행과 상관(correlate)되지 않아 '전체 주문의 최신 날짜(2024-03-01)' 하나만 기준이 된다. 그래서 그 날짜에 주문한 Kim만 남고 Lee는 자기 최신 주문임에도 탈락한다.\n🔧 해결: 서브쿼리를 고객 단위로 상관시킨다(WHERE o2.customer = o.customer). 그러면 각 고객의 최신 날짜와 비교되어 Kim=200, Lee=50이 모두 나온다.\n🛡 재발 방지: '그룹별 최댓값' 조건의 서브쿼리에는 바깥 쿼리와 이어주는 상관 조건이 있는지 확인한다. 없으면 전역 기준으로 잘못 필터된다."},{"t":"sql","k":"디버깅","cat":"debug","q":"부서별 급여 상위 2명씩(총 4명: eng의 A,B / sales의 D,E)을 뽑아야 한다. 아래 쿼리는 전체 상위 2명만 뽑아 A, B만 나온다. 부서별 상위 2명이 나오도록 고쳐라.","schema":"CREATE TABLE emp (name TEXT, dept TEXT, pay INTEGER);\nINSERT INTO emp VALUES\n  ('A','eng',100),\n  ('B','eng',90),\n  ('C','eng',80),\n  ('D','sales',70),\n  ('E','sales',60);","src":"SELECT name, dept, pay\nFROM emp\nORDER BY pay DESC\nLIMIT 2;","sol":"SELECT name, dept, pay\nFROM (\n  SELECT name, dept, pay,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY pay DESC) AS rn\n  FROM emp\n)\nWHERE rn <= 2\nORDER BY dept, pay DESC;","ordered":true,"ex":"🐛 원인: ORDER BY + LIMIT 2는 전체를 한 줄로 세워 상위 2행만 남긴다. 부서별로 나눠 각각 2명을 뽑는 '그룹별 상위 N' 요구를 표현하지 못한다.\n🔧 해결: 부서로 분할한 ROW_NUMBER()로 부서별 순번을 매기고 rn &lt;= 2로 거른다. 그러면 부서마다 상위 2명이 선택된다.\n🛡 재발 방지: '그룹별 상위 N'은 전역 LIMIT이 아니라 PARTITION BY가 있는 윈도우 함수로 처리한다는 패턴을 기본으로 익힌다."},{"t":"sql","k":"디버깅","cat":"debug","q":"부서 총 급여가 150을 초과하는 부서만 그 합계와 함께 출력해야 한다(정답: eng=160, sales=230). 아래 쿼리는 개별 급여에 필터를 걸어 eng를 통째로 빼먹고 합계도 틀린다. 부서 합계 기준으로 고쳐라.","schema":"CREATE TABLE emp (name TEXT, dept TEXT, pay INTEGER);\nINSERT INTO emp VALUES\n  ('A','eng',100),\n  ('B','eng',60),\n  ('C','sales',200),\n  ('D','sales',30);","src":"SELECT dept, SUM(pay) AS total\nFROM emp\nWHERE pay > 150\nGROUP BY dept\nORDER BY dept;","sol":"SELECT dept, SUM(pay) AS total\nFROM emp\nGROUP BY dept\nHAVING SUM(pay) > 150\nORDER BY dept;","ordered":true,"ex":"🐛 원인: WHERE는 그룹핑 이전에 개별 행을 거른다. 'pay &gt; 150'으로 C만 남긴 뒤 집계하므로 eng는 아예 사라지고 sales 합계도 200으로 잘못 계산된다. 집계 결과에 대한 조건을 WHERE로 표현할 수 없다.\n🔧 해결: 집계값에 대한 조건은 GROUP BY 이후 동작하는 HAVING SUM(pay) &gt; 150으로 건다. 그러면 부서 합계가 먼저 계산되고 그 합계 기준으로 필터되어 eng=160, sales=230이 나온다.\n🛡 재발 방지: '집계 결과에 대한 조건'은 HAVING, '개별 행에 대한 조건'은 WHERE로 구분한다. 조건 문장에 SUM/COUNT 같은 집계가 들어가면 HAVING을 떠올린다."},{"t":"sql","k":"디버깅","cat":"debug","q":"전체 주문 금액의 합계(총매출)를 구해야 한다(정답: 250). 아래 쿼리는 같은 금액(100)을 한 번만 더해 150을 낸다. 모든 주문 금액이 더해지도록 고쳐라.","schema":"CREATE TABLE ord (id INTEGER, amt INTEGER);\nINSERT INTO ord VALUES (1,100),(2,100),(3,50);","src":"SELECT SUM(DISTINCT amt) AS total\nFROM ord;","sol":"SELECT SUM(amt) AS total\nFROM ord;","ordered":false,"ex":"🐛 원인: SUM(DISTINCT amt)는 서로 다른 값만 남기고 중복 금액을 하나로 합쳐 버린다. 100이 두 건이지만 한 번만 더해져 100+50=150이 된다. 실제 매출은 금액 중복 여부와 무관하게 모두 더해야 한다.\n🔧 해결: 모든 행의 금액을 더하려면 DISTINCT를 제거한 SUM(amt)를 쓴다. 그러면 100+100+50=250이 나온다.\n🛡 재발 방지: 집계 함수 안의 DISTINCT는 '서로 다른 값만 대상으로' 한다는 뜻이므로, 총합/총량 계산에서는 정말 중복 제거가 필요한지 신중히 판단한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"고객별 주문 건수를 구하되, 주문이 없는 고객은 0으로 나와야 한다(정답: Kim=2, Lee=1, Park=0). 아래 쿼리는 주문이 없는 Park을 1로 잘못 센다. 0이 나오도록 고쳐라.","schema":"CREATE TABLE customer (id INTEGER, name TEXT);\nINSERT INTO customer VALUES (1,'Kim'),(2,'Lee'),(3,'Park');\n\nCREATE TABLE ord (id INTEGER, customer_id INTEGER);\nINSERT INTO ord VALUES (10,1),(11,1),(12,2);","src":"SELECT c.name, COUNT(*) AS cnt\nFROM customer c\nLEFT JOIN ord o ON o.customer_id = c.id\nGROUP BY c.id\nORDER BY c.id;","sol":"SELECT c.name, COUNT(o.id) AS cnt\nFROM customer c\nLEFT JOIN ord o ON o.customer_id = c.id\nGROUP BY c.id\nORDER BY c.id;","ordered":true,"ex":"🐛 원인: LEFT JOIN에서 매칭 주문이 없는 고객(Park)도 오른쪽이 NULL로 채워진 행이 1개 생긴다. COUNT(*)는 이 NULL 행까지 1로 세므로 주문 0건인 Park이 1로 집계된다.\n🔧 해결: 오른쪽 테이블의 NULL이 아닌 컬럼을 세는 COUNT(o.id)로 바꾼다. COUNT은 NULL을 세지 않으므로 Park은 0이 된다.\n🛡 재발 방지: LEFT JOIN 후 건수를 셀 때는 COUNT(*) 대신 오른쪽 테이블의 키 컬럼을 COUNT(col)로 세어, 매칭 없는 NULL 행이 카운트되지 않게 한다."}],"th":{"sum":"SQL 버그는 대개 **에러 없이 조용히 틀린 결과**를 낸다. 행이 사라지거나, 중복으로 부풀거나, NULL이 조용히 빠진다.","body":[{"h":"행이 사라지거나 부풀어나는 이유","t":"`INNER JOIN`은 짝이 없는 행을 버린다 — 주문 없는 회원까지 세야 한다면 `LEFT JOIN`이어야 한다. 반대로 1:N 조인 뒤 `SUM`을 하면 같은 값이 N번 더해져 부풀어난다(팬아웃). `LEFT JOIN` 후 오른쪽 테이블 컬럼을 `WHERE`에 쓰면 NULL이 걸러져 사실상 `INNER JOIN`이 되어버린다 — 그 조건은 `ON`에 둬야 한다."},{"h":"NULL과 집계의 함정","t":"`COUNT(col)`은 NULL을 세지 않지만 `COUNT(*)`는 모든 행을 센다. NULL은 `= NULL`로 비교되지 않고 `IS NULL`을 써야 한다. 집계 결과를 거르는 조건은 `WHERE`가 아니라 `HAVING`에 와야 하고, `WHERE`는 집계 전 행을 거른다. 정수끼리 나누면 소수점이 잘린다."},{"h":"검증 습관","t":"의심되면 집계 전 원본 행을 먼저 조회해 몇 행이 나오는지 확인하고, 실행 계획(`EXPLAIN`)으로 인덱스를 타는지 본다. '몇 행이 나와야 정상인가'를 먼저 정하고 쿼리를 쓰면 조용한 오차를 잡을 수 있다."}],"code":{"c":"-- 버그: LEFT JOIN 해놓고 오른쪽 컬럼을 WHERE에 두면 INNER JOIN이 된다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.status = 'paid'      -- 주문 없는 회원이 통째로 사라짐\nGROUP BY u.name;\n\n-- 수정: 조건을 ON으로 옮긴다\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id AND o.status = 'paid'\nGROUP BY u.name;","cap":"LEFT JOIN의 조건 위치 하나로 결과 집합이 달라진다."},"key":["INNER JOIN은 짝 없는 행을 버린다 — 필요하면 LEFT JOIN","LEFT JOIN 뒤 오른쪽 컬럼 조건은 WHERE가 아니라 ON에","1:N 조인 후 SUM은 팬아웃으로 부풀어난다","COUNT(col)은 NULL 제외, 집계 후 필터는 HAVING"]}}]},{"t":"직접 구현 — 실무 쿼리","l":[{"t":"실무 쿼리 I","q":[{"t":"sql","k":"직접 구현","q":"orders와 customers를 조인하여 각 주문의 주문ID(order_id), 고객명(name), 주문금액(amount)을 조회하세요. 고객 정보가 존재하는 주문만 포함하고, 주문금액 내림차순으로 정렬하세요.","schema":"CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, name TEXT, city TEXT);\nCREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER, order_date TEXT);\nINSERT INTO customers VALUES (1,'김민준','서울'),(2,'이서연','부산'),(3,'박도윤','대구');\nINSERT INTO orders VALUES (101,1,52000,'2024-03-01'),(102,2,18000,'2024-03-02'),(103,1,73000,'2024-03-05'),(104,3,26000,'2024-03-07'),(105,2,41000,'2024-03-10');","src":"-- 힌트: orders o INNER JOIN customers c ON o.customer_id = c.customer_id\n-- amount 기준 내림차순 정렬\nSELECT ","sol":"SELECT o.order_id, c.name, o.amount\nFROM orders o\nJOIN customers c ON o.customer_id = c.customer_id\nORDER BY o.amount DESC;","ordered":true,"ex":"INNER JOIN은 양쪽 테이블에 매칭되는 행만 결합합니다. ON 절로 조인 키를 지정합니다."},{"t":"sql","k":"직접 구현","q":"모든 고객의 고객명(name)과 주문 건수(order_count)를 조회하세요. 주문이 하나도 없는 고객은 0으로 표시하고, customer_id 오름차순으로 정렬하세요.","schema":"CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);\nINSERT INTO customers VALUES (1,'김민준'),(2,'이서연'),(3,'박도윤'),(4,'최지우');\nINSERT INTO orders VALUES (101,1,52000),(102,2,18000),(103,1,73000),(104,2,41000),(105,1,12000);","src":"-- 힌트: 주문 없는 고객도 나와야 하므로 LEFT JOIN\n-- COUNT(o.order_id)는 매칭 없는 행에서 0이 됩니다\nSELECT ","sol":"SELECT c.name, COUNT(o.order_id) AS order_count\nFROM customers c\nLEFT JOIN orders o ON c.customer_id = o.customer_id\nGROUP BY c.customer_id, c.name\nORDER BY c.customer_id;","ordered":true,"ex":"LEFT JOIN은 왼쪽 테이블의 모든 행을 유지하며, COUNT는 NULL을 세지 않아 매칭 없는 고객이 0이 됩니다."},{"t":"sql","k":"직접 구현","q":"products 테이블에서 카테고리(category)별 총 매출액(SUM(price*stock), total)과 상품 개수(cnt)를 조회하세요. 총 매출액 내림차순으로 정렬하세요.","schema":"CREATE TABLE products (product_id INTEGER PRIMARY KEY, name TEXT, category TEXT, price INTEGER, stock INTEGER);\nINSERT INTO products VALUES (1,'노트북','전자',1200000,5),(2,'마우스','전자',25000,40),(3,'셔츠','의류',35000,20),(4,'청바지','의류',59000,15),(5,'키보드','전자',89000,12),(6,'양말','의류',5000,100);","src":"-- 힌트: GROUP BY category, 집계 함수 SUM/COUNT 사용\nSELECT ","sol":"SELECT category, SUM(price * stock) AS total, COUNT(*) AS cnt\nFROM products\nGROUP BY category\nORDER BY total DESC;","ordered":true,"ex":"GROUP BY로 그룹을 나눈 뒤 SUM, COUNT 같은 집계 함수로 그룹별 요약값을 계산합니다."},{"t":"sql","k":"직접 구현","q":"orders에서 고객별 총 주문금액(total)을 구하되, 총 주문금액이 50000 이상인 고객만 customer_id와 함께 조회하세요. total 내림차순으로 정렬하세요.","schema":"CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (101,1,52000),(102,2,18000),(103,1,73000),(104,3,26000),(105,2,41000),(106,3,15000),(107,1,9000);","src":"-- 힌트: GROUP BY 후 그룹 조건은 WHERE가 아니라 HAVING으로 거릅니다\nSELECT ","sol":"SELECT customer_id, SUM(amount) AS total\nFROM orders\nGROUP BY customer_id\nHAVING SUM(amount) >= 50000\nORDER BY total DESC;","ordered":true,"ex":"HAVING은 GROUP BY로 만든 집계 결과에 조건을 겁니다. 개별 행 조건인 WHERE와 구분됩니다."},{"t":"sql","k":"직접 구현","q":"products에서 가격(price)이 전체 상품 평균 가격보다 높은 상품의 상품명(name)과 가격(price)을 조회하세요. 가격 내림차순으로 정렬하세요.","schema":"CREATE TABLE products (product_id INTEGER PRIMARY KEY, name TEXT, price INTEGER);\nINSERT INTO products VALUES (1,'노트북',1200000),(2,'마우스',25000),(3,'셔츠',35000),(4,'모니터',320000),(5,'키보드',89000);","src":"-- 힌트: 스칼라 서브쿼리로 (SELECT AVG(price) FROM products) 계산 후 비교\nSELECT ","sol":"SELECT name, price\nFROM products\nWHERE price > (SELECT AVG(price) FROM products)\nORDER BY price DESC;","ordered":true,"ex":"스칼라 서브쿼리는 단일 값을 반환하며 WHERE 절 비교에 그대로 사용할 수 있습니다."}],"th":{"sum":"쿼리는 적는 순서(SELECT부터)와 **실행되는 논리 순서가 다르다**: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.","body":[{"h":"논리적 실행 순서로 생각한다","t":"먼저 어떤 테이블을 어떻게 붙일지(FROM/JOIN), 다음 어떤 행을 남길지(WHERE), 무엇으로 묶을지(GROUP BY), 묶은 결과를 어떻게 거를지(HAVING), 무엇을 보여줄지(SELECT), 마지막으로 정렬(ORDER BY). 이 순서로 쓰면 'WHERE에 집계함수를 쓸 수 없다' 같은 문제가 자연히 풀린다. `SELECT`의 별칭을 `WHERE`에서 못 쓰는 이유도 같다."},{"h":"집계와 윈도우 함수의 차이","t":"`GROUP BY` 집계는 여러 행을 한 행으로 접지만, 윈도우 함수(`SUM() OVER`, `ROW_NUMBER() OVER`)는 **행을 유지한 채** 그룹 계산을 덧붙인다. '각 부서에서 급여 상위 3명'처럼 원본 행이 필요한 순위 문제는 `ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...)`를 CTE로 감싼 뒤 걸러낸다."},{"h":"요구사항을 그대로 옮긴다","t":"정렬을 요구하면 반드시 `ORDER BY`를 쓴다(정렬을 안 쓰면 순서는 보장되지 않는다). 컬럼 이름·개수·순서도 요구사항 그대로 맞춘다. NULL이 섞이는 집계에는 `COALESCE`를 고려한다."}],"code":{"c":"-- 각 부서에서 급여 상위 2명\nWITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees\n)\nSELECT name, dept, salary\nFROM ranked\nWHERE rn <= 2\nORDER BY dept, salary DESC;","cap":"윈도우 함수는 행을 유지하므로 '그룹별 상위 N'에 적합하다."},"key":["논리 순서: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","WHERE는 집계 전 행 필터, HAVING은 집계 후 필터","윈도우 함수는 행을 접지 않고 그룹 계산을 덧붙인다","정렬이 요구되면 ORDER BY 없이는 순서가 보장되지 않는다"]}},{"t":"실무 쿼리 II","q":[{"t":"sql","k":"직접 구현","q":"products에서 각 카테고리(category) 안에서 가격(price)이 가장 높은 상품의 상품명(name), 카테고리(category), 가격(price)을 조회하세요. 카테고리 오름차순으로 정렬하세요.","schema":"CREATE TABLE products (product_id INTEGER PRIMARY KEY, name TEXT, category TEXT, price INTEGER);\nINSERT INTO products VALUES (1,'노트북','전자',1200000),(2,'마우스','전자',25000),(3,'셔츠','의류',35000),(4,'청바지','의류',59000),(5,'키보드','전자',89000);","src":"-- 힌트: 상관 서브쿼리 -- 바깥 행의 category와 같은 그룹의 MAX(price)와 비교\nSELECT ","sol":"SELECT name, category, price\nFROM products p\nWHERE price = (SELECT MAX(price) FROM products p2 WHERE p2.category = p.category)\nORDER BY category;","ordered":true,"ex":"상관 서브쿼리는 바깥 쿼리의 각 행(p.category)을 참조하며 행마다 다시 평가됩니다."},{"t":"sql","k":"직접 구현","q":"employees에서 각 부서(dept) 내에서 급여(salary)가 높은 순으로 순위를 매겨, 부서별 급여 1위 직원의 이름(name), 부서(dept), 급여(salary)만 조회하세요. dept 오름차순으로 정렬하세요.","schema":"CREATE TABLE employees (emp_id INTEGER PRIMARY KEY, name TEXT, dept TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'김철수','영업',4200000),(2,'이영희','영업',5100000),(3,'박민수','개발',6200000),(4,'정수진','개발',5800000),(5,'한지민','개발',6200000);","src":"-- 힌트: ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC)를 CTE/서브쿼리로 뽑고 rn=1 필터\nSELECT ","sol":"SELECT name, dept, salary\nFROM (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees\n) t\nWHERE rn = 1\nORDER BY dept;","ordered":true,"ex":"ROW_NUMBER()는 PARTITION별로 1부터 고유 순번을 부여합니다. 동점이어도 하나만 1이 됩니다."},{"t":"sql","k":"직접 구현","q":"sales에서 지역(region)별로 매출(amount)이 높은 순으로 RANK를 매겨, 각 행의 지역(region), 판매원(seller), 매출(amount), 순위(rnk)를 조회하세요. region 오름차순, 그 다음 매출 내림차순으로 정렬하세요.","schema":"CREATE TABLE sales (id INTEGER PRIMARY KEY, region TEXT, seller TEXT, amount INTEGER);\nINSERT INTO sales VALUES (1,'수도권','김하나',300),(2,'수도권','이두리',300),(3,'수도권','박세찬',150),(4,'영남','최지훈',420),(5,'영남','정미래',210);","src":"-- 힌트: RANK() OVER (PARTITION BY region ORDER BY amount DESC), 동점은 같은 순위\nSELECT ","sol":"SELECT region, seller, amount,\n       RANK() OVER (PARTITION BY region ORDER BY amount DESC) AS rnk\nFROM sales\nORDER BY region, amount DESC;","ordered":true,"ex":"RANK()는 동점에 같은 순위를 주고 그 수만큼 다음 순위를 건너뜁니다(1,1,3)."},{"t":"sql","k":"직접 구현","q":"daily_sales에서 날짜(sale_date) 순으로 매출(amount)의 누적 합계(running_total)를 계산하여 날짜(sale_date), 매출(amount), 누적합(running_total)을 조회하세요. 날짜 오름차순으로 정렬하세요.","schema":"CREATE TABLE daily_sales (sale_date TEXT PRIMARY KEY, amount INTEGER);\nINSERT INTO daily_sales VALUES ('2024-05-01',100),('2024-05-02',150),('2024-05-03',80),('2024-05-04',200),('2024-05-05',120);","src":"-- 힌트: SUM(amount) OVER (ORDER BY sale_date)로 누적합 계산\nSELECT ","sol":"SELECT sale_date, amount,\n       SUM(amount) OVER (ORDER BY sale_date) AS running_total\nFROM daily_sales\nORDER BY sale_date;","ordered":true,"ex":"SUM() OVER (ORDER BY ...)는 현재 행까지의 누적 합계를 계산하는 윈도우 함수입니다."},{"t":"sql","k":"직접 구현","q":"CTE를 사용하여 카테고리(category)별 총 매출(SUM(amount))을 먼저 구한 뒤, 그 중 총 매출이 500 이상인 카테고리(category)와 총매출(total)을 조회하세요. 총매출 내림차순으로 정렬하세요.","schema":"CREATE TABLE sales (id INTEGER PRIMARY KEY, category TEXT, amount INTEGER);\nINSERT INTO sales VALUES (1,'가전',300),(2,'가전',250),(3,'식품',120),(4,'식품',90),(5,'의류',400),(6,'의류',150);","src":"-- 힌트: WITH cat_total AS (SELECT category, SUM(amount) ...) 로 CTE 정의 후 필터\nSELECT ","sol":"WITH cat_total AS (\n  SELECT category, SUM(amount) AS total\n  FROM sales\n  GROUP BY category\n)\nSELECT category, total\nFROM cat_total\nWHERE total >= 500\nORDER BY total DESC;","ordered":true,"ex":"CTE(WITH)는 이름 붙인 임시 결과 집합으로, 복잡한 쿼리를 단계별로 나눠 가독성을 높입니다."}],"th":{"sum":"쿼리는 적는 순서(SELECT부터)와 **실행되는 논리 순서가 다르다**: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.","body":[{"h":"논리적 실행 순서로 생각한다","t":"먼저 어떤 테이블을 어떻게 붙일지(FROM/JOIN), 다음 어떤 행을 남길지(WHERE), 무엇으로 묶을지(GROUP BY), 묶은 결과를 어떻게 거를지(HAVING), 무엇을 보여줄지(SELECT), 마지막으로 정렬(ORDER BY). 이 순서로 쓰면 'WHERE에 집계함수를 쓸 수 없다' 같은 문제가 자연히 풀린다. `SELECT`의 별칭을 `WHERE`에서 못 쓰는 이유도 같다."},{"h":"집계와 윈도우 함수의 차이","t":"`GROUP BY` 집계는 여러 행을 한 행으로 접지만, 윈도우 함수(`SUM() OVER`, `ROW_NUMBER() OVER`)는 **행을 유지한 채** 그룹 계산을 덧붙인다. '각 부서에서 급여 상위 3명'처럼 원본 행이 필요한 순위 문제는 `ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...)`를 CTE로 감싼 뒤 걸러낸다."},{"h":"요구사항을 그대로 옮긴다","t":"정렬을 요구하면 반드시 `ORDER BY`를 쓴다(정렬을 안 쓰면 순서는 보장되지 않는다). 컬럼 이름·개수·순서도 요구사항 그대로 맞춘다. NULL이 섞이는 집계에는 `COALESCE`를 고려한다."}],"code":{"c":"-- 각 부서에서 급여 상위 2명\nWITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees\n)\nSELECT name, dept, salary\nFROM ranked\nWHERE rn <= 2\nORDER BY dept, salary DESC;","cap":"윈도우 함수는 행을 유지하므로 '그룹별 상위 N'에 적합하다."},"key":["논리 순서: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","WHERE는 집계 전 행 필터, HAVING은 집계 후 필터","윈도우 함수는 행을 접지 않고 그룹 계산을 덧붙인다","정렬이 요구되면 ORDER BY 없이는 순서가 보장되지 않는다"]}},{"t":"실무 쿼리 III","q":[{"t":"sql","k":"직접 구현","q":"products에서 매출액(price*stock)이 가장 큰 상위 3개 상품의 상품명(name)과 매출액(revenue)을 조회하세요. 매출액 내림차순으로 정렬하고 3개만 반환하세요.","schema":"CREATE TABLE products (product_id INTEGER PRIMARY KEY, name TEXT, price INTEGER, stock INTEGER);\nINSERT INTO products VALUES (1,'노트북',1200000,5),(2,'마우스',25000,40),(3,'모니터',320000,8),(4,'키보드',89000,12),(5,'셔츠',35000,20);","src":"-- 힌트: 계산식으로 정렬 후 LIMIT 3\nSELECT ","sol":"SELECT name, price * stock AS revenue\nFROM products\nORDER BY revenue DESC\nLIMIT 3;","ordered":true,"ex":"상위 N개는 ORDER BY로 정렬한 뒤 LIMIT으로 개수를 제한하여 얻습니다."},{"t":"sql","k":"직접 구현","q":"orders에서 각 고객(customer_id)별로 상태(status)가 '완료'인 주문 금액 합계(done_amount)와 '취소'인 주문 금액 합계(cancel_amount)를 조건부 집계로 한 행에 조회하세요. customer_id 오름차순으로 정렬하세요.","schema":"CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, status TEXT, amount INTEGER);\nINSERT INTO orders VALUES (1,1,'완료',50000),(2,1,'취소',20000),(3,1,'완료',30000),(4,2,'완료',15000),(5,2,'취소',40000),(6,3,'완료',60000);","src":"-- 힌트: SUM(CASE WHEN status='완료' THEN amount ELSE 0 END) 형태의 조건부 집계\nSELECT ","sol":"SELECT customer_id,\n       SUM(CASE WHEN status = '완료' THEN amount ELSE 0 END) AS done_amount,\n       SUM(CASE WHEN status = '취소' THEN amount ELSE 0 END) AS cancel_amount\nFROM orders\nGROUP BY customer_id\nORDER BY customer_id;","ordered":true,"ex":"SUM(CASE WHEN ...)로 조건을 만족하는 값만 합산하여 여러 지표를 한 행에 피벗할 수 있습니다."},{"t":"sql","k":"직접 구현","q":"orders에서 주문일(order_date)이 2024-06-01부터 2024-06-30 사이인 주문의 주문ID(order_id)와 금액(amount)을 조회하세요. 주문일 오름차순으로 정렬하세요.","schema":"CREATE TABLE orders (order_id INTEGER PRIMARY KEY, amount INTEGER, order_date TEXT);\nINSERT INTO orders VALUES (1,10000,'2024-05-28'),(2,20000,'2024-06-03'),(3,15000,'2024-06-15'),(4,30000,'2024-07-01'),(5,25000,'2024-06-30');","src":"-- 힌트: 날짜 문자열은 'YYYY-MM-DD' 형식이라 BETWEEN 비교가 가능합니다\nSELECT ","sol":"SELECT order_id, amount\nFROM orders\nWHERE order_date BETWEEN '2024-06-01' AND '2024-06-30'\nORDER BY order_date;","ordered":true,"ex":"'YYYY-MM-DD' 형식 문자열은 사전순 비교가 날짜순과 일치하여 BETWEEN으로 범위 필터가 됩니다."},{"t":"sql","k":"직접 구현","q":"employees 테이블에서 각 직원의 이름(emp_name)과 그 직원의 관리자 이름(manager_name)을 self-join으로 조회하세요. 관리자가 없는 직원도 포함하고(관리자 이름은 NULL), emp_id 오름차순으로 정렬하세요.","schema":"CREATE TABLE employees (emp_id INTEGER PRIMARY KEY, name TEXT, manager_id INTEGER);\nINSERT INTO employees VALUES (1,'김대표',NULL),(2,'이부장',1),(3,'박과장',2),(4,'최사원',3),(5,'정사원',2);","src":"-- 힌트: employees를 자기 자신과 LEFT JOIN, e.manager_id = m.emp_id\nSELECT ","sol":"SELECT e.name AS emp_name, m.name AS manager_name\nFROM employees e\nLEFT JOIN employees m ON e.manager_id = m.emp_id\nORDER BY e.emp_id;","ordered":true,"ex":"self-join은 같은 테이블에 별칭을 두 개 부여해 조인합니다. LEFT JOIN으로 관리자 없는 행도 보존합니다."},{"t":"sql","k":"직접 구현","q":"users 테이블에서 사용자 이름(name)과, 연락처(phone)가 NULL이면 '미등록'으로 대체한 값(contact)을 조회하세요. user_id 오름차순으로 정렬하세요.","schema":"CREATE TABLE users (user_id INTEGER PRIMARY KEY, name TEXT, phone TEXT);\nINSERT INTO users VALUES (1,'김민준','010-1111-2222'),(2,'이서연',NULL),(3,'박도윤','010-3333-4444'),(4,'최지우',NULL);","src":"-- 힌트: COALESCE(phone, '미등록')로 NULL을 대체\nSELECT ","sol":"SELECT name, COALESCE(phone, '미등록') AS contact\nFROM users\nORDER BY user_id;","ordered":true,"ex":"COALESCE는 인자들 중 처음으로 NULL이 아닌 값을 반환하여 결측치를 기본값으로 채웁니다."}],"th":{"sum":"쿼리는 적는 순서(SELECT부터)와 **실행되는 논리 순서가 다르다**: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.","body":[{"h":"논리적 실행 순서로 생각한다","t":"먼저 어떤 테이블을 어떻게 붙일지(FROM/JOIN), 다음 어떤 행을 남길지(WHERE), 무엇으로 묶을지(GROUP BY), 묶은 결과를 어떻게 거를지(HAVING), 무엇을 보여줄지(SELECT), 마지막으로 정렬(ORDER BY). 이 순서로 쓰면 'WHERE에 집계함수를 쓸 수 없다' 같은 문제가 자연히 풀린다. `SELECT`의 별칭을 `WHERE`에서 못 쓰는 이유도 같다."},{"h":"집계와 윈도우 함수의 차이","t":"`GROUP BY` 집계는 여러 행을 한 행으로 접지만, 윈도우 함수(`SUM() OVER`, `ROW_NUMBER() OVER`)는 **행을 유지한 채** 그룹 계산을 덧붙인다. '각 부서에서 급여 상위 3명'처럼 원본 행이 필요한 순위 문제는 `ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...)`를 CTE로 감싼 뒤 걸러낸다."},{"h":"요구사항을 그대로 옮긴다","t":"정렬을 요구하면 반드시 `ORDER BY`를 쓴다(정렬을 안 쓰면 순서는 보장되지 않는다). 컬럼 이름·개수·순서도 요구사항 그대로 맞춘다. NULL이 섞이는 집계에는 `COALESCE`를 고려한다."}],"code":{"c":"-- 각 부서에서 급여 상위 2명\nWITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees\n)\nSELECT name, dept, salary\nFROM ranked\nWHERE rn <= 2\nORDER BY dept, salary DESC;","cap":"윈도우 함수는 행을 유지하므로 '그룹별 상위 N'에 적합하다."},"key":["논리 순서: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","WHERE는 집계 전 행 필터, HAVING은 집계 후 필터","윈도우 함수는 행을 접지 않고 그룹 계산을 덧붙인다","정렬이 요구되면 ORDER BY 없이는 순서가 보장되지 않는다"]}},{"t":"실무 쿼리 IV","q":[{"t":"sql","k":"직접 구현","q":"orders와 products를 조인하여 상품별 총 판매수량(total_qty)을 구하고, 상품명(name)과 총 판매수량을 조회하세요. 한 번도 팔리지 않은 상품도 수량 0으로 포함하고, 총 판매수량 내림차순, 동점 시 상품명 오름차순으로 정렬하세요.","schema":"CREATE TABLE products (product_id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE orders (order_id INTEGER PRIMARY KEY, product_id INTEGER, qty INTEGER);\nINSERT INTO products VALUES (1,'노트북'),(2,'마우스'),(3,'키보드'),(4,'모니터');\nINSERT INTO orders VALUES (101,1,2),(102,2,5),(103,1,1),(104,2,3),(105,3,4);","src":"-- 힌트: products LEFT JOIN orders, COALESCE(SUM(qty),0)로 미판매 상품 처리\nSELECT ","sol":"SELECT p.name, COALESCE(SUM(o.qty), 0) AS total_qty\nFROM products p\nLEFT JOIN orders o ON p.product_id = o.product_id\nGROUP BY p.product_id, p.name\nORDER BY total_qty DESC, p.name ASC;","ordered":true,"ex":"LEFT JOIN과 COALESCE(SUM(...),0)를 결합하면 매칭 없는 그룹의 집계 NULL을 0으로 표시할 수 있습니다."}],"th":{"sum":"쿼리는 적는 순서(SELECT부터)와 **실행되는 논리 순서가 다르다**: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.","body":[{"h":"논리적 실행 순서로 생각한다","t":"먼저 어떤 테이블을 어떻게 붙일지(FROM/JOIN), 다음 어떤 행을 남길지(WHERE), 무엇으로 묶을지(GROUP BY), 묶은 결과를 어떻게 거를지(HAVING), 무엇을 보여줄지(SELECT), 마지막으로 정렬(ORDER BY). 이 순서로 쓰면 'WHERE에 집계함수를 쓸 수 없다' 같은 문제가 자연히 풀린다. `SELECT`의 별칭을 `WHERE`에서 못 쓰는 이유도 같다."},{"h":"집계와 윈도우 함수의 차이","t":"`GROUP BY` 집계는 여러 행을 한 행으로 접지만, 윈도우 함수(`SUM() OVER`, `ROW_NUMBER() OVER`)는 **행을 유지한 채** 그룹 계산을 덧붙인다. '각 부서에서 급여 상위 3명'처럼 원본 행이 필요한 순위 문제는 `ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...)`를 CTE로 감싼 뒤 걸러낸다."},{"h":"요구사항을 그대로 옮긴다","t":"정렬을 요구하면 반드시 `ORDER BY`를 쓴다(정렬을 안 쓰면 순서는 보장되지 않는다). 컬럼 이름·개수·순서도 요구사항 그대로 맞춘다. NULL이 섞이는 집계에는 `COALESCE`를 고려한다."}],"code":{"c":"-- 각 부서에서 급여 상위 2명\nWITH ranked AS (\n  SELECT name, dept, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees\n)\nSELECT name, dept, salary\nFROM ranked\nWHERE rn <= 2\nORDER BY dept, salary DESC;","cap":"윈도우 함수는 행을 유지하므로 '그룹별 상위 N'에 적합하다."},"key":["논리 순서: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","WHERE는 집계 전 행 필터, HAVING은 집계 후 필터","윈도우 함수는 행을 접지 않고 그룹 계산을 덧붙인다","정렬이 요구되면 ORDER BY 없이는 순서가 보장되지 않는다"]}}]},{"t":"실행 계획 읽기 실무","l":[{"t":"EXPLAIN 읽기","q":[{"t":"choice","k":"추정 오차","q":"추정 rows는 1,200인데 actual rows가 980,000으로 나왔다. 가장 먼저 의심할 것은?","ex":"대량 적재 직후처럼 통계가 낡으면 추정이 크게 어긋나고, 옵티마이저는 그 잘못된 추정 위에서 조인 방식을 고릅니다. ANALYZE로 통계를 갱신하는 것이 첫 조치입니다.","o":["EXPLAIN ANALYZE의 표시 버그","테이블 통계가 오래되었거나 조건 컬럼 간 상관관계 때문에 선택도 추정이 빗나간 것","디스크가 고장 난 것","결과 집합이 실제로 잘못 계산된 것"],"a":1},{"t":"input","k":"실측 옵션","q":"EXPLAIN에 붙여 쿼리를 실제로 실행하고 실측 시간·행수를 보게 하는 키워드는? (영문)","ex":"EXPLAIN ANALYZE 는 계획과 함께 actual time, actual rows, loops 를 보여 줍니다. 추정과 실측의 차이를 비교하는 것이 진단의 핵심입니다.","a":["ANALYZE","EXPLAIN ANALYZE"]}],"th":{"sum":"EXPLAIN은 옵티마이저가 세운 계획과 추정치를, EXPLAIN ANALYZE는 실제로 실행한 결과를 보여준다. 스캔 방식과 조인 방식, 그리고 추정 행수와 실제 행수의 차이를 읽는 것이 튜닝의 출발점이다.","body":[{"h":"EXPLAIN과 EXPLAIN ANALYZE","t":"EXPLAIN은 쿼리를 실행하지 않고 비용 추정과 계획만 보여 준다. EXPLAIN ANALYZE는 실제로 실행해 actual time과 actual rows까지 보여 주므로, UPDATE·DELETE에 쓸 때는 BEGIN으로 감싸고 ROLLBACK 해야 안전하다. cost 값은 밀리초가 아니라 옵티마이저 내부의 상대적 비용 단위이므로 계획끼리 비교할 때만 의미가 있다."},{"h":"스캔 방식: 풀 스캔이 항상 나쁜 것은 아니다","t":"Seq Scan(풀 테이블 스캔)은 테이블을 처음부터 끝까지 순차로 읽고, Index Scan은 인덱스에서 위치를 찾은 뒤 해당 행을 테이블에서 다시 읽는다. 조건이 전체의 큰 비율을 골라내면 인덱스로 한 행씩 랜덤 접근하는 편이 오히려 비싸서 옵티마이저가 일부러 순차 스캔을 선택한다. 필요한 컬럼이 모두 인덱스 안에 있으면 테이블을 방문하지 않는 Index Only Scan이 되어 가장 저렴하다."},{"h":"조인 방식과 잘못된 추정","t":"Nested Loop는 바깥 입력이 작고 안쪽에 조인 키 인덱스가 있을 때 빠르고, Hash Join은 한쪽으로 해시 테이블을 만들어 큰 테이블끼리 등가 조인할 때 강하며, Merge Join은 양쪽이 조인 키로 정렬되어 있을 때 유리하다. 계획은 들여쓰기가 깊은 안쪽 노드부터 실행되어 바깥으로 결과를 올린다. 성능이 무너지는 전형적인 패턴은 추정 rows가 실제보다 훨씬 작게 잡혀 Nested Loop가 선택되고 안쪽이 수십만 번 반복되는 경우이며, 이때는 ANALYZE로 통계를 갱신하는 것이 먼저다."}],"code":{"c":"EXPLAIN ANALYZE\nSELECT o.id, o.total\nFROM orders o\nJOIN users u ON u.id = o.user_id\nWHERE u.country = 'KR'\n  AND o.created_at >= DATE '2026-01-01';\n\n-- Hash Join  (cost=... rows=1200 ...) (actual time=... rows=98000 loops=1)\n--   -> Seq Scan on orders o   (filter: created_at >= '2026-01-01')\n--   -> Hash\n--        -> Index Scan using users_country_idx on users u","cap":"추정 rows=1200 과 actual rows=98000 의 큰 차이가 잘못된 계획을 의심할 첫 신호다."},"key":["EXPLAIN은 추정, EXPLAIN ANALYZE는 실제 실행 — cost는 ms가 아닌 상대 단위","추정 rows와 actual rows의 큰 괴리는 통계 노후·잘못된 조인 선택의 신호","선택도가 낮은(많이 고르는) 조건에서는 순차 스캔이 오히려 유리하다"]}},{"t":"스캔 방식","q":[{"t":"choice","k":"Index Only Scan","q":"Index Only Scan이 나오려면 어떤 조건이 필요한가?","ex":"인덱스가 쿼리에 필요한 컬럼을 모두 덮으면(커버링) 테이블 접근을 생략할 수 있어 랜덤 I/O가 사라집니다. PostgreSQL에서는 가시성 맵 상태도 영향을 줍니다.","o":["테이블 행 수가 1000건 미만이어야 한다","테이블에 인덱스가 하나만 있어야 한다","SELECT와 WHERE에 필요한 모든 컬럼이 그 인덱스 안에 포함되어 있어야 한다","조건이 반드시 기본키에 대한 등호 비교여야 한다"],"a":2},{"t":"choice","k":"함수 래핑","q":"아래 쿼리에서 created_at 인덱스가 있는데도 계획에 Seq Scan이 나오는 이유는?","ex":"인덱스는 created_at 원본 값으로 정렬되어 있어 DATE(created_at) 결과로는 탐색할 수 없습니다. created_at &gt;= DATE '2026-01-01' AND created_at &lt; DATE '2026-01-02' 처럼 범위 조건으로 바꾸면 인덱스를 탑니다.","code":"SELECT * FROM orders\nWHERE DATE(created_at) = DATE '2026-01-01';","o":["인덱스는 등호 비교를 지원하지 않기 때문","비교 대상이 문자열 리터럴이기 때문","DATE 함수가 항상 느리기 때문","컬럼을 함수로 감싸면 인덱스에 저장된 원본 값과 비교할 수 없어 인덱스를 쓸 수 없기 때문"],"a":3}],"th":{"sum":"EXPLAIN은 옵티마이저가 세운 계획과 추정치를, EXPLAIN ANALYZE는 실제로 실행한 결과를 보여준다. 스캔 방식과 조인 방식, 그리고 추정 행수와 실제 행수의 차이를 읽는 것이 튜닝의 출발점이다.","body":[{"h":"EXPLAIN과 EXPLAIN ANALYZE","t":"EXPLAIN은 쿼리를 실행하지 않고 비용 추정과 계획만 보여 준다. EXPLAIN ANALYZE는 실제로 실행해 actual time과 actual rows까지 보여 주므로, UPDATE·DELETE에 쓸 때는 BEGIN으로 감싸고 ROLLBACK 해야 안전하다. cost 값은 밀리초가 아니라 옵티마이저 내부의 상대적 비용 단위이므로 계획끼리 비교할 때만 의미가 있다."},{"h":"스캔 방식: 풀 스캔이 항상 나쁜 것은 아니다","t":"Seq Scan(풀 테이블 스캔)은 테이블을 처음부터 끝까지 순차로 읽고, Index Scan은 인덱스에서 위치를 찾은 뒤 해당 행을 테이블에서 다시 읽는다. 조건이 전체의 큰 비율을 골라내면 인덱스로 한 행씩 랜덤 접근하는 편이 오히려 비싸서 옵티마이저가 일부러 순차 스캔을 선택한다. 필요한 컬럼이 모두 인덱스 안에 있으면 테이블을 방문하지 않는 Index Only Scan이 되어 가장 저렴하다."},{"h":"조인 방식과 잘못된 추정","t":"Nested Loop는 바깥 입력이 작고 안쪽에 조인 키 인덱스가 있을 때 빠르고, Hash Join은 한쪽으로 해시 테이블을 만들어 큰 테이블끼리 등가 조인할 때 강하며, Merge Join은 양쪽이 조인 키로 정렬되어 있을 때 유리하다. 계획은 들여쓰기가 깊은 안쪽 노드부터 실행되어 바깥으로 결과를 올린다. 성능이 무너지는 전형적인 패턴은 추정 rows가 실제보다 훨씬 작게 잡혀 Nested Loop가 선택되고 안쪽이 수십만 번 반복되는 경우이며, 이때는 ANALYZE로 통계를 갱신하는 것이 먼저다."}],"code":{"c":"EXPLAIN ANALYZE\nSELECT o.id, o.total\nFROM orders o\nJOIN users u ON u.id = o.user_id\nWHERE u.country = 'KR'\n  AND o.created_at >= DATE '2026-01-01';\n\n-- Hash Join  (cost=... rows=1200 ...) (actual time=... rows=98000 loops=1)\n--   -> Seq Scan on orders o   (filter: created_at >= '2026-01-01')\n--   -> Hash\n--        -> Index Scan using users_country_idx on users u","cap":"추정 rows=1200 과 actual rows=98000 의 큰 차이가 잘못된 계획을 의심할 첫 신호다."},"key":["EXPLAIN은 추정, EXPLAIN ANALYZE는 실제 실행 — cost는 ms가 아닌 상대 단위","추정 rows와 actual rows의 큰 괴리는 통계 노후·잘못된 조인 선택의 신호","선택도가 낮은(많이 고르는) 조건에서는 순차 스캔이 오히려 유리하다"]}},{"t":"조인 방식과 진단","q":[{"t":"choice","k":"반복되는 안쪽 스캔","q":"계획에서 Nested Loop 안쪽 노드에 loops=250000 과 Seq Scan이 함께 보인다. 가장 유력한 원인과 조치는?","ex":"안쪽 스캔이 25만 번 반복되면 비용이 곱해집니다. 조인 키 인덱스를 만들어 Index Scan으로 바꾸거나, 통계를 갱신해 Hash Join이 선택되도록 유도해야 합니다.","o":["조인 키에 인덱스가 없어 매 반복마다 테이블 전체를 훑는 것이므로 조인 키 인덱스를 만든다","LIMIT을 추가하면 반복 횟수가 줄어든다","정상 동작이므로 조치할 필요가 없다","결과 정렬 순서를 바꾸면 해결된다"],"a":0},{"t":"input","k":"큰 테이블 등가 조인","q":"인덱스가 마땅치 않은 두 대형 테이블을 등가 조건으로 조인할 때 옵티마이저가 흔히 고르는 조인 방식은? (영문)","ex":"한쪽으로 해시 테이블을 만들고 다른 쪽을 흘려보내며 매칭하므로, 각 테이블을 한 번씩만 읽으면 됩니다.","a":["Hash Join","hash join","해시 조인"]}],"th":{"sum":"EXPLAIN은 옵티마이저가 세운 계획과 추정치를, EXPLAIN ANALYZE는 실제로 실행한 결과를 보여준다. 스캔 방식과 조인 방식, 그리고 추정 행수와 실제 행수의 차이를 읽는 것이 튜닝의 출발점이다.","body":[{"h":"EXPLAIN과 EXPLAIN ANALYZE","t":"EXPLAIN은 쿼리를 실행하지 않고 비용 추정과 계획만 보여 준다. EXPLAIN ANALYZE는 실제로 실행해 actual time과 actual rows까지 보여 주므로, UPDATE·DELETE에 쓸 때는 BEGIN으로 감싸고 ROLLBACK 해야 안전하다. cost 값은 밀리초가 아니라 옵티마이저 내부의 상대적 비용 단위이므로 계획끼리 비교할 때만 의미가 있다."},{"h":"스캔 방식: 풀 스캔이 항상 나쁜 것은 아니다","t":"Seq Scan(풀 테이블 스캔)은 테이블을 처음부터 끝까지 순차로 읽고, Index Scan은 인덱스에서 위치를 찾은 뒤 해당 행을 테이블에서 다시 읽는다. 조건이 전체의 큰 비율을 골라내면 인덱스로 한 행씩 랜덤 접근하는 편이 오히려 비싸서 옵티마이저가 일부러 순차 스캔을 선택한다. 필요한 컬럼이 모두 인덱스 안에 있으면 테이블을 방문하지 않는 Index Only Scan이 되어 가장 저렴하다."},{"h":"조인 방식과 잘못된 추정","t":"Nested Loop는 바깥 입력이 작고 안쪽에 조인 키 인덱스가 있을 때 빠르고, Hash Join은 한쪽으로 해시 테이블을 만들어 큰 테이블끼리 등가 조인할 때 강하며, Merge Join은 양쪽이 조인 키로 정렬되어 있을 때 유리하다. 계획은 들여쓰기가 깊은 안쪽 노드부터 실행되어 바깥으로 결과를 올린다. 성능이 무너지는 전형적인 패턴은 추정 rows가 실제보다 훨씬 작게 잡혀 Nested Loop가 선택되고 안쪽이 수십만 번 반복되는 경우이며, 이때는 ANALYZE로 통계를 갱신하는 것이 먼저다."}],"code":{"c":"EXPLAIN ANALYZE\nSELECT o.id, o.total\nFROM orders o\nJOIN users u ON u.id = o.user_id\nWHERE u.country = 'KR'\n  AND o.created_at >= DATE '2026-01-01';\n\n-- Hash Join  (cost=... rows=1200 ...) (actual time=... rows=98000 loops=1)\n--   -> Seq Scan on orders o   (filter: created_at >= '2026-01-01')\n--   -> Hash\n--        -> Index Scan using users_country_idx on users u","cap":"추정 rows=1200 과 actual rows=98000 의 큰 차이가 잘못된 계획을 의심할 첫 신호다."},"key":["EXPLAIN은 추정, EXPLAIN ANALYZE는 실제 실행 — cost는 ms가 아닌 상대 단위","추정 rows와 actual rows의 큰 괴리는 통계 노후·잘못된 조인 선택의 신호","선택도가 낮은(많이 고르는) 조건에서는 순차 스캔이 오히려 유리하다"]}}]},{"t":"쿼리 튜닝 심화: 인덱스와 페이지네이션","l":[{"t":"sargable 조건","q":[{"t":"choice","k":"LIKE 패턴","q":"name 컬럼의 B-tree 인덱스를 활용할 수 있는 LIKE 조건은?","ex":"B-tree는 앞에서부터 정렬되어 있어 접두사가 고정된 패턴만 범위 탐색이 됩니다. 앞에 와일드카드가 오면 시작 위치를 알 수 없어 전체를 훑어야 합니다.","o":["name LIKE '%김%'","name LIKE '김%'","LOWER(name) LIKE '%kim'","name LIKE '%수민'"],"a":1},{"t":"choice","k":"표현식 인덱스","q":"대소문자 무시 검색을 위해 WHERE LOWER(email) = ? 를 반드시 써야 한다면?","ex":"CREATE INDEX ... ON users (LOWER(email)) 처럼 만들면 쿼리의 표현식과 인덱스 정의가 일치해 탐색이 가능합니다. 대소문자 무시 컬럼 타입을 쓰는 방법도 있습니다.","o":["인덱스는 쓸 수 없으므로 애플리케이션에서 필터링한다","LOWER(email)에 대한 표현식 인덱스를 만들어 그 표현식으로 탐색되게 한다","테이블 전체를 소문자로 다시 저장하는 것 외에는 방법이 없다","email 컬럼에 일반 인덱스를 하나 더 만든다"],"a":1},{"t":"input","k":"용어","q":"컬럼을 가공하지 않아 인덱스 탐색이 가능한 검색 조건을 부르는 용어는? (영문 소문자)","ex":"Search ARGument ABLE의 줄임말입니다. 조건이 sargable하지 않으면 옵티마이저는 인덱스 범위 탐색 대신 전체 스캔 후 필터를 택합니다.","a":["sargable"]}],"th":{"sum":"조건은 인덱스를 탈 수 있는 형태(sargable)로 쓰고, 복합 인덱스는 왼쪽 접두사 규칙을 따르며, 깊은 OFFSET 페이지네이션은 키셋 페이징으로 바꾼다.","body":[{"h":"sargable: 컬럼을 가공하지 말 것","t":"WHERE DATE(created_at) = '2026-01-01' 처럼 컬럼을 함수로 감싸면 인덱스에 저장된 원본 값으로 탐색할 수 없어 전체를 읽게 된다. created_at >= '2026-01-01' AND created_at < '2026-01-02' 같은 범위 조건으로 바꾸면 인덱스 탐색이 가능하다. 같은 이유로 WHERE price * 1.1 > 100 은 price > 100 / 1.1 로, 앞에 와일드카드가 붙는 LIKE '%kim' 도 인덱스를 쓸 수 없다. 굳이 표현식으로 검색해야 한다면 그 표현식 자체에 인덱스(표현식 인덱스)를 만든다."},{"h":"복합 인덱스와 커버링","t":"(a, b, c) 인덱스는 a 조건, a와 b 조건, a와 b와 c 조건에는 쓰이지만 b만 주어진 조건에는 쓸 수 없다 — 왼쪽 접두사 규칙이다. 등호로 고정되는 컬럼을 앞에, 범위 조건 컬럼을 뒤에 두어야 범위 이후 컬럼까지 효율적으로 좁혀진다. SELECT 목록과 WHERE·ORDER BY에 필요한 컬럼이 모두 인덱스에 들어 있으면 테이블을 읽지 않는 커버링 인덱스가 되지만, 인덱스가 늘수록 INSERT·UPDATE 비용과 저장 공간은 함께 늘어난다."},{"h":"OFFSET의 함정과 키셋 페이징","t":"LIMIT 20 OFFSET 100000 은 앞의 10만 행을 건너뛰는 것이 아니라 실제로 읽어서 버린 뒤 20행을 돌려주므로, 페이지가 뒤로 갈수록 선형으로 느려진다. 게다가 그 사이에 행이 삽입·삭제되면 다음 페이지에서 같은 행이 다시 나오거나 아예 누락된다. 마지막으로 본 행의 정렬 키를 기억해 WHERE (created_at, id) < ('...', 84213) 형태로 이어 읽는 키셋 페이징을 쓰면 페이지 깊이와 무관하게 일정한 성능이 나온다. 이때 정렬 키에 동점이 있을 수 있으므로 id 같은 유일한 타이브레이커를 반드시 포함한다."}],"code":{"c":"-- 느림: 앞의 100,000행을 읽고 버린다\nSELECT id, title FROM posts\nORDER BY created_at DESC, id DESC\nLIMIT 20 OFFSET 100000;\n\n-- 키셋 페이징: 마지막으로 본 (created_at, id) 다음부터만 읽는다\nSELECT id, title FROM posts\nWHERE (created_at, id) < (TIMESTAMP '2026-03-01 10:00:00', 84213)\nORDER BY created_at DESC, id DESC\nLIMIT 20;\n-- 인덱스: (created_at DESC, id DESC)","cap":"OFFSET은 건너뛰는 것이 아니라 읽고 버리는 것이다."},"key":["컬럼을 함수·연산으로 감싸면 인덱스를 쓸 수 없다 (sargable 위반)","복합 인덱스 (a,b,c)는 b 단독 조건에 쓰이지 않는다 — 왼쪽 접두사 규칙","OFFSET N은 앞의 N행을 실제로 읽고 버린다 — 깊은 페이지는 키셋 페이징으로"]}},{"t":"복합 인덱스와 커버링","q":[{"t":"choice","k":"왼쪽 접두사","q":"인덱스 (user_id, created_at)가 있을 때, WHERE created_at &gt;= ? 조건만 있는 쿼리는?","ex":"복합 인덱스는 선두 컬럼 기준으로 먼저 정렬되고 그 안에서 다음 컬럼이 정렬됩니다. 선두가 고정되지 않으면 created_at 값들이 인덱스 전체에 흩어져 있어 범위로 좁힐 수 없습니다.","o":["선두 컬럼인 user_id 조건이 없으므로 이 인덱스로 범위 탐색을 할 수 없다","두 번째 컬럼도 정렬되어 있으므로 문제없이 인덱스를 탄다","인덱스가 자동으로 (created_at, user_id) 순서로 재배열된다","created_at이 날짜 타입이면 항상 인덱스를 탄다"],"a":0},{"t":"choice","k":"컬럼 순서","q":"WHERE status = 'PAID' AND created_at &gt;= ? 를 자주 쓴다면 복합 인덱스 컬럼 순서로 좋은 것은?","ex":"등호로 고정된 컬럼이 앞에 오면 그 값 안에서 created_at이 정렬되어 범위 탐색이 연속 구간이 됩니다. 범위 컬럼을 앞에 두면 그 뒤 컬럼은 흩어져 필터링만 됩니다.","o":["두 컬럼에 각각 단일 인덱스를 만드는 것이 항상 더 낫다","순서는 옵티마이저가 재배열하므로 아무 상관 없다","(created_at, status) — 선택도가 높은 날짜를 앞에","(status, created_at) — 등호 컬럼을 앞에, 범위 컬럼을 뒤에"],"a":3},{"t":"input","k":"접두사 규칙","q":"복합 인덱스가 선두 컬럼부터 연속으로 주어진 조건에만 사용되는 규칙의 이름은? (한국어 또는 영문)","ex":"(a, b, c) 인덱스는 a / a,b / a,b,c 조건에 쓰이고 b 단독이나 c 단독 조건에는 쓰이지 않습니다.","a":["왼쪽 접두사 규칙","leftmost prefix","최좌측 접두사 규칙","leftmost prefix rule"]}],"th":{"sum":"조건은 인덱스를 탈 수 있는 형태(sargable)로 쓰고, 복합 인덱스는 왼쪽 접두사 규칙을 따르며, 깊은 OFFSET 페이지네이션은 키셋 페이징으로 바꾼다.","body":[{"h":"sargable: 컬럼을 가공하지 말 것","t":"WHERE DATE(created_at) = '2026-01-01' 처럼 컬럼을 함수로 감싸면 인덱스에 저장된 원본 값으로 탐색할 수 없어 전체를 읽게 된다. created_at >= '2026-01-01' AND created_at < '2026-01-02' 같은 범위 조건으로 바꾸면 인덱스 탐색이 가능하다. 같은 이유로 WHERE price * 1.1 > 100 은 price > 100 / 1.1 로, 앞에 와일드카드가 붙는 LIKE '%kim' 도 인덱스를 쓸 수 없다. 굳이 표현식으로 검색해야 한다면 그 표현식 자체에 인덱스(표현식 인덱스)를 만든다."},{"h":"복합 인덱스와 커버링","t":"(a, b, c) 인덱스는 a 조건, a와 b 조건, a와 b와 c 조건에는 쓰이지만 b만 주어진 조건에는 쓸 수 없다 — 왼쪽 접두사 규칙이다. 등호로 고정되는 컬럼을 앞에, 범위 조건 컬럼을 뒤에 두어야 범위 이후 컬럼까지 효율적으로 좁혀진다. SELECT 목록과 WHERE·ORDER BY에 필요한 컬럼이 모두 인덱스에 들어 있으면 테이블을 읽지 않는 커버링 인덱스가 되지만, 인덱스가 늘수록 INSERT·UPDATE 비용과 저장 공간은 함께 늘어난다."},{"h":"OFFSET의 함정과 키셋 페이징","t":"LIMIT 20 OFFSET 100000 은 앞의 10만 행을 건너뛰는 것이 아니라 실제로 읽어서 버린 뒤 20행을 돌려주므로, 페이지가 뒤로 갈수록 선형으로 느려진다. 게다가 그 사이에 행이 삽입·삭제되면 다음 페이지에서 같은 행이 다시 나오거나 아예 누락된다. 마지막으로 본 행의 정렬 키를 기억해 WHERE (created_at, id) < ('...', 84213) 형태로 이어 읽는 키셋 페이징을 쓰면 페이지 깊이와 무관하게 일정한 성능이 나온다. 이때 정렬 키에 동점이 있을 수 있으므로 id 같은 유일한 타이브레이커를 반드시 포함한다."}],"code":{"c":"-- 느림: 앞의 100,000행을 읽고 버린다\nSELECT id, title FROM posts\nORDER BY created_at DESC, id DESC\nLIMIT 20 OFFSET 100000;\n\n-- 키셋 페이징: 마지막으로 본 (created_at, id) 다음부터만 읽는다\nSELECT id, title FROM posts\nWHERE (created_at, id) < (TIMESTAMP '2026-03-01 10:00:00', 84213)\nORDER BY created_at DESC, id DESC\nLIMIT 20;\n-- 인덱스: (created_at DESC, id DESC)","cap":"OFFSET은 건너뛰는 것이 아니라 읽고 버리는 것이다."},"key":["컬럼을 함수·연산으로 감싸면 인덱스를 쓸 수 없다 (sargable 위반)","복합 인덱스 (a,b,c)는 b 단독 조건에 쓰이지 않는다 — 왼쪽 접두사 규칙","OFFSET N은 앞의 N행을 실제로 읽고 버린다 — 깊은 페이지는 키셋 페이징으로"]}},{"t":"페이지네이션 실무","q":[{"t":"choice","k":"키셋 페이징","q":"키셋(seek) 페이징의 핵심 원리는?","ex":"WHERE (created_at, id) &lt; (마지막값) 형태로 시작 위치를 직접 지정하므로, 인덱스에서 곧바로 해당 지점으로 탐색해 20행만 읽습니다. 페이지 깊이와 무관하게 일정합니다.","o":["OFFSET을 랜덤 값으로 바꿔 부하를 분산한다","결과 전체를 임시 테이블에 복사해 두고 잘라 준다","마지막으로 본 행의 정렬 키를 조건으로 넘겨 그 지점부터 인덱스를 이어 읽는다","페이지 번호를 캐시에 저장해 두었다가 재사용한다"],"a":2},{"t":"input","k":"읽는 행 수","q":"LIMIT 20 OFFSET 100000 쿼리를 실행할 때 데이터베이스가 정렬 결과에서 훑어야 하는 행 수는 대략 몇 행인가? (숫자만)","ex":"버릴 100,000행 + 반환할 20행 = 100,020행을 실제로 지나가야 합니다. 이것이 깊은 페이지가 느려지는 직접적인 이유입니다.","a":["100020"]}],"th":{"sum":"조건은 인덱스를 탈 수 있는 형태(sargable)로 쓰고, 복합 인덱스는 왼쪽 접두사 규칙을 따르며, 깊은 OFFSET 페이지네이션은 키셋 페이징으로 바꾼다.","body":[{"h":"sargable: 컬럼을 가공하지 말 것","t":"WHERE DATE(created_at) = '2026-01-01' 처럼 컬럼을 함수로 감싸면 인덱스에 저장된 원본 값으로 탐색할 수 없어 전체를 읽게 된다. created_at >= '2026-01-01' AND created_at < '2026-01-02' 같은 범위 조건으로 바꾸면 인덱스 탐색이 가능하다. 같은 이유로 WHERE price * 1.1 > 100 은 price > 100 / 1.1 로, 앞에 와일드카드가 붙는 LIKE '%kim' 도 인덱스를 쓸 수 없다. 굳이 표현식으로 검색해야 한다면 그 표현식 자체에 인덱스(표현식 인덱스)를 만든다."},{"h":"복합 인덱스와 커버링","t":"(a, b, c) 인덱스는 a 조건, a와 b 조건, a와 b와 c 조건에는 쓰이지만 b만 주어진 조건에는 쓸 수 없다 — 왼쪽 접두사 규칙이다. 등호로 고정되는 컬럼을 앞에, 범위 조건 컬럼을 뒤에 두어야 범위 이후 컬럼까지 효율적으로 좁혀진다. SELECT 목록과 WHERE·ORDER BY에 필요한 컬럼이 모두 인덱스에 들어 있으면 테이블을 읽지 않는 커버링 인덱스가 되지만, 인덱스가 늘수록 INSERT·UPDATE 비용과 저장 공간은 함께 늘어난다."},{"h":"OFFSET의 함정과 키셋 페이징","t":"LIMIT 20 OFFSET 100000 은 앞의 10만 행을 건너뛰는 것이 아니라 실제로 읽어서 버린 뒤 20행을 돌려주므로, 페이지가 뒤로 갈수록 선형으로 느려진다. 게다가 그 사이에 행이 삽입·삭제되면 다음 페이지에서 같은 행이 다시 나오거나 아예 누락된다. 마지막으로 본 행의 정렬 키를 기억해 WHERE (created_at, id) < ('...', 84213) 형태로 이어 읽는 키셋 페이징을 쓰면 페이지 깊이와 무관하게 일정한 성능이 나온다. 이때 정렬 키에 동점이 있을 수 있으므로 id 같은 유일한 타이브레이커를 반드시 포함한다."}],"code":{"c":"-- 느림: 앞의 100,000행을 읽고 버린다\nSELECT id, title FROM posts\nORDER BY created_at DESC, id DESC\nLIMIT 20 OFFSET 100000;\n\n-- 키셋 페이징: 마지막으로 본 (created_at, id) 다음부터만 읽는다\nSELECT id, title FROM posts\nWHERE (created_at, id) < (TIMESTAMP '2026-03-01 10:00:00', 84213)\nORDER BY created_at DESC, id DESC\nLIMIT 20;\n-- 인덱스: (created_at DESC, id DESC)","cap":"OFFSET은 건너뛰는 것이 아니라 읽고 버리는 것이다."},"key":["컬럼을 함수·연산으로 감싸면 인덱스를 쓸 수 없다 (sargable 위반)","복합 인덱스 (a,b,c)는 b 단독 조건에 쓰이지 않는다 — 왼쪽 접두사 규칙","OFFSET N은 앞의 N행을 실제로 읽고 버린다 — 깊은 페이지는 키셋 페이징으로"]}}]},{"t":"데이터 모델링 실무: 이력과 소프트 삭제","l":[{"t":"정규화 판단","q":[{"t":"choice","k":"1NF 위반","q":"tags 컬럼에 'sql,index,tuning' 처럼 콤마로 여러 값을 넣는 설계의 문제는?","ex":"다중 값은 별도 테이블(post_tags)이나 배열·JSONB 같은 전용 타입 + 전용 인덱스로 다뤄야 합니다. LIKE '%sql%'는 부분 문자열 오탐도 만듭니다.","o":["트랜잭션을 사용할 수 없게 된다","문자열 컬럼에는 NOT NULL을 걸 수 없다","개별 값으로 검색·조인·제약을 걸 수 없어 문자열 매칭에 의존하게 되고 인덱스 효율도 떨어진다","저장 공간이 정규화보다 항상 더 크다"],"a":2},{"t":"input","k":"이상 현상","q":"같은 사실이 여러 행에 중복 저장되어 일부만 수정될 때 값이 어긋나는 현상을 무엇이라 하는가? (한국어)","ex":"정규화의 목적은 삽입·갱신·삭제 이상을 제거하는 것입니다. 갱신 이상은 그중 가장 흔하게 데이터 신뢰를 무너뜨리는 형태입니다.","a":["갱신 이상","갱신이상","update anomaly"]}],"th":{"sum":"정규화는 기본값이고 비정규화는 측정된 읽기 병목에 대한 예외다. 이력과 삭제는 값을 덮어쓰거나 지우는 것이 아니라 시점을 기록하는 방식으로 설계한다.","body":[{"h":"정규화가 기본, 비정규화는 근거를 갖고","t":"정규화는 같은 사실을 한 곳에만 저장해 갱신 이상을 막는다. 상품명을 주문 테이블에도 복사해 두면 이름을 바꿀 때 두 곳을 모두 맞춰야 하고, 하나라도 놓치면 데이터가 서로 다른 말을 하게 된다. 비정규화(집계 컬럼 캐시, 값 중복)는 읽기를 빠르게 하는 대신 동기화 책임을 만들므로, 실행 계획으로 병목을 확인하고 갱신 경로가 한 곳으로 모이는 경우에만 도입한다."},{"h":"이력과 시점 스냅샷","t":"현재 값만 UPDATE로 덮어쓰면 '그때 가격이 얼마였는가'를 답할 수 없다. 이력 테이블에 valid_from과 valid_to를 두고 종료 시점이 NULL인 행을 현재 값으로 두면 특정 시점의 상태를 재현할 수 있다. 반면 주문처럼 과거 값이 확정되어야 하는 데이터는 조인으로 현재 가격을 끌어오면 안 되고, 주문 시점 가격을 주문 행에 스냅샷으로 복사해 둬야 한다. 이 복사는 중복이 아니라 '주문 당시의 사실'이라는 다른 사실을 저장하는 것이다."},{"h":"소프트 삭제의 실제 비용","t":"deleted_at 컬럼은 복구와 감사에 유리하지만 모든 조회에 조건이 붙고, 한 곳이라도 빠지면 삭제된 데이터가 노출된다. UNIQUE(email) 제약은 삭제된 행과도 충돌하므로 WHERE deleted_at IS NULL 조건이 붙은 부분 인덱스로 바꿔야 재가입이 가능하다. 또 삭제 행이 계속 쌓여 인덱스와 스캔 비용이 늘기 때문에 아카이브 전략이 필요하고, 개인정보 삭제 요구처럼 진짜로 지워야 하는 데이터는 소프트 삭제로 대신할 수 없다."}],"code":{"c":"-- 이력: 종료 시점이 NULL 인 행이 현재 값\nCREATE TABLE price_history (\n  product_id BIGINT      NOT NULL,\n  price      NUMERIC(12,2) NOT NULL,\n  valid_from TIMESTAMPTZ NOT NULL,\n  valid_to   TIMESTAMPTZ            -- NULL = 현재 유효\n);\n\n-- 특정 시점의 가격\nSELECT price FROM price_history\nWHERE product_id = 7\n  AND valid_from <= TIMESTAMPTZ '2026-02-01'\n  AND (valid_to IS NULL OR valid_to > TIMESTAMPTZ '2026-02-01');\n\n-- 소프트 삭제와 공존하는 유일성: 살아 있는 행에만 적용\nCREATE UNIQUE INDEX users_email_alive ON users (email) WHERE deleted_at IS NULL;","cap":"이력은 시점을 저장하고, 소프트 삭제는 유일성 제약을 다시 설계하게 만든다."},"key":["비정규화는 측정된 병목에 대한 예외 — 대가는 동기화 책임","확정되어야 할 과거 값(주문 시점 가격)은 조인이 아니라 스냅샷으로 저장","소프트 삭제 시 UNIQUE 제약은 부분 인덱스(WHERE deleted_at IS NULL)로 바꾼다"]}},{"t":"이력과 스냅샷","q":[{"t":"choice","k":"현재 행 찾기","q":"valid_from / valid_to 구조에서 '현재 유효한 행'을 나타내는 일반적인 방법은?","ex":"종료 시점이 비어 있는 행이 현재 값입니다. 이렇게 두면 WHERE valid_to IS NULL 로 현재 값을, 시점 조건으로 과거 값을 같은 테이블에서 조회할 수 있습니다.","o":["가장 큰 id를 가진 행을 현재 행으로 간주한다","별도 테이블에 현재 행만 따로 복사한다","valid_from이 가장 작은 행을 현재 행으로 본다","valid_to를 NULL(또는 무한대 값)로 두어 아직 종료되지 않았음을 표시한다"],"a":3},{"t":"choice","k":"시점 조회","q":"시점 t 기준으로 유효한 이력 행을 고르는 조건으로 올바른 것은?","ex":"시작 시점은 포함하고 종료 시점은 제외하는 반열린 구간 [valid_from, valid_to)으로 두면 구간이 겹치지도 비지도 않습니다. 종료가 NULL이면 아직 유효합니다.","o":["valid_to &gt;= t AND valid_from IS NULL","valid_from &lt; t AND valid_to IS NULL","valid_from &lt;= t AND (valid_to IS NULL OR valid_to &gt; t)","valid_from &gt;= t AND valid_to &lt;= t"],"a":2}],"th":{"sum":"정규화는 기본값이고 비정규화는 측정된 읽기 병목에 대한 예외다. 이력과 삭제는 값을 덮어쓰거나 지우는 것이 아니라 시점을 기록하는 방식으로 설계한다.","body":[{"h":"정규화가 기본, 비정규화는 근거를 갖고","t":"정규화는 같은 사실을 한 곳에만 저장해 갱신 이상을 막는다. 상품명을 주문 테이블에도 복사해 두면 이름을 바꿀 때 두 곳을 모두 맞춰야 하고, 하나라도 놓치면 데이터가 서로 다른 말을 하게 된다. 비정규화(집계 컬럼 캐시, 값 중복)는 읽기를 빠르게 하는 대신 동기화 책임을 만들므로, 실행 계획으로 병목을 확인하고 갱신 경로가 한 곳으로 모이는 경우에만 도입한다."},{"h":"이력과 시점 스냅샷","t":"현재 값만 UPDATE로 덮어쓰면 '그때 가격이 얼마였는가'를 답할 수 없다. 이력 테이블에 valid_from과 valid_to를 두고 종료 시점이 NULL인 행을 현재 값으로 두면 특정 시점의 상태를 재현할 수 있다. 반면 주문처럼 과거 값이 확정되어야 하는 데이터는 조인으로 현재 가격을 끌어오면 안 되고, 주문 시점 가격을 주문 행에 스냅샷으로 복사해 둬야 한다. 이 복사는 중복이 아니라 '주문 당시의 사실'이라는 다른 사실을 저장하는 것이다."},{"h":"소프트 삭제의 실제 비용","t":"deleted_at 컬럼은 복구와 감사에 유리하지만 모든 조회에 조건이 붙고, 한 곳이라도 빠지면 삭제된 데이터가 노출된다. UNIQUE(email) 제약은 삭제된 행과도 충돌하므로 WHERE deleted_at IS NULL 조건이 붙은 부분 인덱스로 바꿔야 재가입이 가능하다. 또 삭제 행이 계속 쌓여 인덱스와 스캔 비용이 늘기 때문에 아카이브 전략이 필요하고, 개인정보 삭제 요구처럼 진짜로 지워야 하는 데이터는 소프트 삭제로 대신할 수 없다."}],"code":{"c":"-- 이력: 종료 시점이 NULL 인 행이 현재 값\nCREATE TABLE price_history (\n  product_id BIGINT      NOT NULL,\n  price      NUMERIC(12,2) NOT NULL,\n  valid_from TIMESTAMPTZ NOT NULL,\n  valid_to   TIMESTAMPTZ            -- NULL = 현재 유효\n);\n\n-- 특정 시점의 가격\nSELECT price FROM price_history\nWHERE product_id = 7\n  AND valid_from <= TIMESTAMPTZ '2026-02-01'\n  AND (valid_to IS NULL OR valid_to > TIMESTAMPTZ '2026-02-01');\n\n-- 소프트 삭제와 공존하는 유일성: 살아 있는 행에만 적용\nCREATE UNIQUE INDEX users_email_alive ON users (email) WHERE deleted_at IS NULL;","cap":"이력은 시점을 저장하고, 소프트 삭제는 유일성 제약을 다시 설계하게 만든다."},"key":["비정규화는 측정된 병목에 대한 예외 — 대가는 동기화 책임","확정되어야 할 과거 값(주문 시점 가격)은 조인이 아니라 스냅샷으로 저장","소프트 삭제 시 UNIQUE 제약은 부분 인덱스(WHERE deleted_at IS NULL)로 바꾼다"]}},{"t":"소프트 삭제와 제약","q":[{"t":"choice","k":"물리 삭제 필요","q":"개인정보 삭제 요청을 받았을 때 소프트 삭제만으로 부족한 이유는?","ex":"소프트 삭제는 운영 편의를 위한 장치일 뿐 삭제의 법적·실질적 요건을 만족하지 못합니다. 주문 이력처럼 보존해야 하는 데이터는 식별자만 익명화하는 방식으로 분리 설계합니다.","o":["백업이 자동으로 삭제되기 때문","deleted_at 컬럼이 표준이 아니기 때문","데이터가 그대로 남아 있어 '삭제'라고 볼 수 없으므로, 해당 개인정보는 물리 삭제하거나 복원 불가능하게 익명화해야 한다","소프트 삭제는 조회 성능이 나쁘기 때문"],"a":2},{"t":"input","k":"조건부 인덱스","q":"WHERE 절이 붙어 특정 조건을 만족하는 행에만 적용되는 인덱스를 무엇이라 하는가? (한국어 또는 영문)","ex":"PostgreSQL의 partial index가 대표적입니다. 인덱스 크기를 줄이고, 소프트 삭제 환경에서 활성 행에만 유일성을 거는 데 유용합니다.","a":["부분 인덱스","partial index","조건부 인덱스"]}],"th":{"sum":"정규화는 기본값이고 비정규화는 측정된 읽기 병목에 대한 예외다. 이력과 삭제는 값을 덮어쓰거나 지우는 것이 아니라 시점을 기록하는 방식으로 설계한다.","body":[{"h":"정규화가 기본, 비정규화는 근거를 갖고","t":"정규화는 같은 사실을 한 곳에만 저장해 갱신 이상을 막는다. 상품명을 주문 테이블에도 복사해 두면 이름을 바꿀 때 두 곳을 모두 맞춰야 하고, 하나라도 놓치면 데이터가 서로 다른 말을 하게 된다. 비정규화(집계 컬럼 캐시, 값 중복)는 읽기를 빠르게 하는 대신 동기화 책임을 만들므로, 실행 계획으로 병목을 확인하고 갱신 경로가 한 곳으로 모이는 경우에만 도입한다."},{"h":"이력과 시점 스냅샷","t":"현재 값만 UPDATE로 덮어쓰면 '그때 가격이 얼마였는가'를 답할 수 없다. 이력 테이블에 valid_from과 valid_to를 두고 종료 시점이 NULL인 행을 현재 값으로 두면 특정 시점의 상태를 재현할 수 있다. 반면 주문처럼 과거 값이 확정되어야 하는 데이터는 조인으로 현재 가격을 끌어오면 안 되고, 주문 시점 가격을 주문 행에 스냅샷으로 복사해 둬야 한다. 이 복사는 중복이 아니라 '주문 당시의 사실'이라는 다른 사실을 저장하는 것이다."},{"h":"소프트 삭제의 실제 비용","t":"deleted_at 컬럼은 복구와 감사에 유리하지만 모든 조회에 조건이 붙고, 한 곳이라도 빠지면 삭제된 데이터가 노출된다. UNIQUE(email) 제약은 삭제된 행과도 충돌하므로 WHERE deleted_at IS NULL 조건이 붙은 부분 인덱스로 바꿔야 재가입이 가능하다. 또 삭제 행이 계속 쌓여 인덱스와 스캔 비용이 늘기 때문에 아카이브 전략이 필요하고, 개인정보 삭제 요구처럼 진짜로 지워야 하는 데이터는 소프트 삭제로 대신할 수 없다."}],"code":{"c":"-- 이력: 종료 시점이 NULL 인 행이 현재 값\nCREATE TABLE price_history (\n  product_id BIGINT      NOT NULL,\n  price      NUMERIC(12,2) NOT NULL,\n  valid_from TIMESTAMPTZ NOT NULL,\n  valid_to   TIMESTAMPTZ            -- NULL = 현재 유효\n);\n\n-- 특정 시점의 가격\nSELECT price FROM price_history\nWHERE product_id = 7\n  AND valid_from <= TIMESTAMPTZ '2026-02-01'\n  AND (valid_to IS NULL OR valid_to > TIMESTAMPTZ '2026-02-01');\n\n-- 소프트 삭제와 공존하는 유일성: 살아 있는 행에만 적용\nCREATE UNIQUE INDEX users_email_alive ON users (email) WHERE deleted_at IS NULL;","cap":"이력은 시점을 저장하고, 소프트 삭제는 유일성 제약을 다시 설계하게 만든다."},"key":["비정규화는 측정된 병목에 대한 예외 — 대가는 동기화 책임","확정되어야 할 과거 값(주문 시점 가격)은 조인이 아니라 스냅샷으로 저장","소프트 삭제 시 UNIQUE 제약은 부분 인덱스(WHERE deleted_at IS NULL)로 바꾼다"]}}]},{"t":"동시성 제어 실무: 락과 격리 수준","l":[{"t":"락과 FOR UPDATE","q":[{"t":"choice","k":"락 유지 기간","q":"FOR UPDATE로 얻은 행 락은 언제 해제되는가?","ex":"그래서 트랜잭션 길이가 곧 락 유지 시간입니다. 트랜잭션을 짧게 유지하고, 사용자 입력 대기나 외부 호출을 그 안에 넣지 않아야 합니다.","o":["다음 UPDATE 문이 실행될 때","트랜잭션이 COMMIT 또는 ROLLBACK 될 때","SELECT 문이 끝나는 즉시","설정된 타임아웃이 지나면 자동으로"],"a":1},{"t":"input","k":"건너뛰기 옵션","q":"이미 잠긴 행을 기다리지 않고 건너뛰게 하는 SELECT FOR UPDATE 옵션은? (영문)","ex":"NOWAIT는 즉시 오류를 내고, SKIP LOCKED는 잠긴 행을 결과에서 제외합니다. 작업 큐 구현의 표준 도구입니다.","a":["SKIP LOCKED","skip locked"]}],"th":{"sum":"동시 수정 충돌은 비관적 락(SELECT ... FOR UPDATE)으로 줄을 세우거나, 낙관적 락(버전 컬럼)으로 감지해 재시도한다. 격리 수준은 막고 싶은 이상 현상에 맞춰 고른다.","body":[{"h":"SELECT FOR UPDATE와 락 경합","t":"SELECT ... FOR UPDATE는 읽은 행에 배타 락을 걸어 다른 트랜잭션이 그 행을 수정하거나 같은 락을 잡지 못하게 한다. 이 락은 COMMIT 또는 ROLLBACK까지 유지되므로 트랜잭션을 짧게 유지해야 하고, 락을 쥔 채 외부 API를 호출하는 것은 대기 폭증의 전형적인 원인이다. 기다리고 싶지 않으면 NOWAIT로 즉시 실패시키고, 작업 큐처럼 잠긴 행을 건너뛰고 다음 것을 집어야 하면 SKIP LOCKED를 쓴다."},{"h":"비관적 락과 낙관적 락","t":"충돌이 잦고 재시도 비용이 크면 비관적 락으로 순서를 강제하는 편이 낫다. 충돌이 드물면 version 컬럼을 두고 UPDATE ... WHERE id = ? AND version = ? 로 갱신한 뒤 영향 행수가 0이면 누군가 먼저 바꾼 것이므로 다시 읽고 재시도한다. 낙관적 락은 대기가 없어 처리량이 높은 대신 재시도 로직을 애플리케이션이 책임져야 한다. 한편 balance = balance - 100 처럼 값을 데이터베이스 안에서 계산하면 읽고-수정하고-쓰는 사이의 갱신 손실 자체를 피할 수 있다."},{"h":"격리 수준 고르기","t":"READ COMMITTED(PostgreSQL 기본)는 커밋된 데이터만 읽지만 같은 쿼리를 두 번 실행하면 결과가 달라질 수 있다. REPEATABLE READ(MySQL InnoDB 기본)는 트랜잭션 시작 시점의 스냅샷을 계속 보므로 같은 행을 다시 읽어도 값이 같고, PostgreSQL에서는 동시 갱신이 충돌하면 직렬화 오류로 실패시킨다. 잔액을 확인한 뒤 각자 인출하는 것처럼 두 트랜잭션이 서로의 전제를 깨뜨리는 쓰기 스큐는 스냅샷 격리로 막히지 않아 SERIALIZABLE이나 명시적 락이 필요하다. 데드락은 모든 트랜잭션이 같은 순서로 락을 잡게 해서 줄인다."}],"code":{"c":"-- 비관적: 줄을 세운다\nBEGIN;\nSELECT balance FROM accounts WHERE id = 7 FOR UPDATE;   -- 커밋까지 배타 락\nUPDATE accounts SET balance = balance - 100 WHERE id = 7;\nCOMMIT;\n\n-- 낙관적: 충돌을 감지한다\nUPDATE accounts\n   SET balance = 900, version = version + 1\n WHERE id = 7 AND version = 3;   -- 영향 행수 0 이면 충돌 → 재시도\n\n-- 작업 큐: 잠긴 행은 건너뛰고 다음 것을 집는다\nSELECT id FROM jobs WHERE status = 'READY'\nORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;","cap":"줄을 세울지(락) 부딪히면 다시 할지(버전)는 충돌 빈도로 정한다."},"key":["FOR UPDATE 락은 COMMIT/ROLLBACK까지 유지 — 트랜잭션 안에서 외부 호출 금지","충돌이 잦으면 비관적 락, 드물면 낙관적 락 + 재시도","쓰기 스큐는 스냅샷 격리로 막히지 않는다 — SERIALIZABLE이나 명시적 락 필요"]}},{"t":"낙관적 락과 갱신 손실","q":[{"t":"choice","k":"낙관적 락 동작","q":"버전 컬럼을 이용한 낙관적 락의 동작 방식은?","ex":"읽을 때 본 version이 그대로 남아 있어야만 갱신됩니다. 다른 트랜잭션이 먼저 커밋해 version이 올라갔다면 조건이 맞지 않아 0행이 갱신되고, 이것이 충돌 신호입니다.","o":["충돌이 나면 데이터베이스가 자동으로 병합해 준다","테이블 전체를 잠그고 버전을 비교한다","UPDATE ... WHERE id = ? AND version = ? 로 갱신하고, 영향 행수가 0이면 충돌로 보고 재시도한다","갱신 전에 항상 행 락을 먼저 획득한다"],"a":2},{"t":"choice","k":"갱신 손실","q":"두 트랜잭션이 같은 재고 값을 각각 읽어 계산한 뒤 저장했더니 한쪽 차감이 사라졌다. 이 현상은?","ex":"읽고-수정하고-쓰는 구간이 원자적이지 않아 생깁니다. FOR UPDATE로 읽거나, 버전 조건 갱신, 또는 데이터베이스 안에서 직접 연산하는 방식으로 막습니다.","o":["팬텀 리드 — 없던 행이 나타났다","더티 리드 — 커밋되지 않은 값을 읽었다","갱신 손실(lost update) — 나중 쓰기가 먼저 쓰기를 덮어썼다","데드락 — 서로를 기다리다 취소되었다"],"a":2}],"th":{"sum":"동시 수정 충돌은 비관적 락(SELECT ... FOR UPDATE)으로 줄을 세우거나, 낙관적 락(버전 컬럼)으로 감지해 재시도한다. 격리 수준은 막고 싶은 이상 현상에 맞춰 고른다.","body":[{"h":"SELECT FOR UPDATE와 락 경합","t":"SELECT ... FOR UPDATE는 읽은 행에 배타 락을 걸어 다른 트랜잭션이 그 행을 수정하거나 같은 락을 잡지 못하게 한다. 이 락은 COMMIT 또는 ROLLBACK까지 유지되므로 트랜잭션을 짧게 유지해야 하고, 락을 쥔 채 외부 API를 호출하는 것은 대기 폭증의 전형적인 원인이다. 기다리고 싶지 않으면 NOWAIT로 즉시 실패시키고, 작업 큐처럼 잠긴 행을 건너뛰고 다음 것을 집어야 하면 SKIP LOCKED를 쓴다."},{"h":"비관적 락과 낙관적 락","t":"충돌이 잦고 재시도 비용이 크면 비관적 락으로 순서를 강제하는 편이 낫다. 충돌이 드물면 version 컬럼을 두고 UPDATE ... WHERE id = ? AND version = ? 로 갱신한 뒤 영향 행수가 0이면 누군가 먼저 바꾼 것이므로 다시 읽고 재시도한다. 낙관적 락은 대기가 없어 처리량이 높은 대신 재시도 로직을 애플리케이션이 책임져야 한다. 한편 balance = balance - 100 처럼 값을 데이터베이스 안에서 계산하면 읽고-수정하고-쓰는 사이의 갱신 손실 자체를 피할 수 있다."},{"h":"격리 수준 고르기","t":"READ COMMITTED(PostgreSQL 기본)는 커밋된 데이터만 읽지만 같은 쿼리를 두 번 실행하면 결과가 달라질 수 있다. REPEATABLE READ(MySQL InnoDB 기본)는 트랜잭션 시작 시점의 스냅샷을 계속 보므로 같은 행을 다시 읽어도 값이 같고, PostgreSQL에서는 동시 갱신이 충돌하면 직렬화 오류로 실패시킨다. 잔액을 확인한 뒤 각자 인출하는 것처럼 두 트랜잭션이 서로의 전제를 깨뜨리는 쓰기 스큐는 스냅샷 격리로 막히지 않아 SERIALIZABLE이나 명시적 락이 필요하다. 데드락은 모든 트랜잭션이 같은 순서로 락을 잡게 해서 줄인다."}],"code":{"c":"-- 비관적: 줄을 세운다\nBEGIN;\nSELECT balance FROM accounts WHERE id = 7 FOR UPDATE;   -- 커밋까지 배타 락\nUPDATE accounts SET balance = balance - 100 WHERE id = 7;\nCOMMIT;\n\n-- 낙관적: 충돌을 감지한다\nUPDATE accounts\n   SET balance = 900, version = version + 1\n WHERE id = 7 AND version = 3;   -- 영향 행수 0 이면 충돌 → 재시도\n\n-- 작업 큐: 잠긴 행은 건너뛰고 다음 것을 집는다\nSELECT id FROM jobs WHERE status = 'READY'\nORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;","cap":"줄을 세울지(락) 부딪히면 다시 할지(버전)는 충돌 빈도로 정한다."},"key":["FOR UPDATE 락은 COMMIT/ROLLBACK까지 유지 — 트랜잭션 안에서 외부 호출 금지","충돌이 잦으면 비관적 락, 드물면 낙관적 락 + 재시도","쓰기 스큐는 스냅샷 격리로 막히지 않는다 — SERIALIZABLE이나 명시적 락 필요"]}},{"t":"격리 수준과 이상 현상","q":[{"t":"choice","k":"기본 격리 수준","q":"널리 쓰이는 기본 격리 수준으로 옳은 조합은?","ex":"기본값이 다르므로 이식할 때 동작 차이가 생깁니다. 예를 들어 같은 트랜잭션에서 두 번 조회했을 때의 결과가 두 엔진에서 다르게 나타날 수 있습니다.","o":["둘 다 SERIALIZABLE","PostgreSQL은 READ COMMITTED, MySQL InnoDB는 REPEATABLE READ","둘 다 READ UNCOMMITTED","PostgreSQL은 REPEATABLE READ, MySQL InnoDB는 READ UNCOMMITTED"],"a":1},{"t":"input","k":"이상 현상 이름","q":"다른 트랜잭션이 아직 커밋하지 않은 변경을 읽어 버리는 현상의 이름은? (한국어 또는 영문)","ex":"더티 리드는 READ UNCOMMITTED에서만 허용되며, READ COMMITTED 이상에서는 발생하지 않습니다.","a":["더티 리드","dirty read","dirty read(더티 리드)"]}],"th":{"sum":"동시 수정 충돌은 비관적 락(SELECT ... FOR UPDATE)으로 줄을 세우거나, 낙관적 락(버전 컬럼)으로 감지해 재시도한다. 격리 수준은 막고 싶은 이상 현상에 맞춰 고른다.","body":[{"h":"SELECT FOR UPDATE와 락 경합","t":"SELECT ... FOR UPDATE는 읽은 행에 배타 락을 걸어 다른 트랜잭션이 그 행을 수정하거나 같은 락을 잡지 못하게 한다. 이 락은 COMMIT 또는 ROLLBACK까지 유지되므로 트랜잭션을 짧게 유지해야 하고, 락을 쥔 채 외부 API를 호출하는 것은 대기 폭증의 전형적인 원인이다. 기다리고 싶지 않으면 NOWAIT로 즉시 실패시키고, 작업 큐처럼 잠긴 행을 건너뛰고 다음 것을 집어야 하면 SKIP LOCKED를 쓴다."},{"h":"비관적 락과 낙관적 락","t":"충돌이 잦고 재시도 비용이 크면 비관적 락으로 순서를 강제하는 편이 낫다. 충돌이 드물면 version 컬럼을 두고 UPDATE ... WHERE id = ? AND version = ? 로 갱신한 뒤 영향 행수가 0이면 누군가 먼저 바꾼 것이므로 다시 읽고 재시도한다. 낙관적 락은 대기가 없어 처리량이 높은 대신 재시도 로직을 애플리케이션이 책임져야 한다. 한편 balance = balance - 100 처럼 값을 데이터베이스 안에서 계산하면 읽고-수정하고-쓰는 사이의 갱신 손실 자체를 피할 수 있다."},{"h":"격리 수준 고르기","t":"READ COMMITTED(PostgreSQL 기본)는 커밋된 데이터만 읽지만 같은 쿼리를 두 번 실행하면 결과가 달라질 수 있다. REPEATABLE READ(MySQL InnoDB 기본)는 트랜잭션 시작 시점의 스냅샷을 계속 보므로 같은 행을 다시 읽어도 값이 같고, PostgreSQL에서는 동시 갱신이 충돌하면 직렬화 오류로 실패시킨다. 잔액을 확인한 뒤 각자 인출하는 것처럼 두 트랜잭션이 서로의 전제를 깨뜨리는 쓰기 스큐는 스냅샷 격리로 막히지 않아 SERIALIZABLE이나 명시적 락이 필요하다. 데드락은 모든 트랜잭션이 같은 순서로 락을 잡게 해서 줄인다."}],"code":{"c":"-- 비관적: 줄을 세운다\nBEGIN;\nSELECT balance FROM accounts WHERE id = 7 FOR UPDATE;   -- 커밋까지 배타 락\nUPDATE accounts SET balance = balance - 100 WHERE id = 7;\nCOMMIT;\n\n-- 낙관적: 충돌을 감지한다\nUPDATE accounts\n   SET balance = 900, version = version + 1\n WHERE id = 7 AND version = 3;   -- 영향 행수 0 이면 충돌 → 재시도\n\n-- 작업 큐: 잠긴 행은 건너뛰고 다음 것을 집는다\nSELECT id FROM jobs WHERE status = 'READY'\nORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;","cap":"줄을 세울지(락) 부딪히면 다시 할지(버전)는 충돌 빈도로 정한다."},"key":["FOR UPDATE 락은 COMMIT/ROLLBACK까지 유지 — 트랜잭션 안에서 외부 호출 금지","충돌이 잦으면 비관적 락, 드물면 낙관적 락 + 재시도","쓰기 스큐는 스냅샷 격리로 막히지 않는다 — SERIALIZABLE이나 명시적 락 필요"]}}]},{"t":"분석 쿼리 심화: 윈도우 프레임과 상위 N","l":[{"t":"윈도우 프레임","q":[{"t":"choice","k":"기본 프레임","q":"SUM(x) OVER (ORDER BY d) 처럼 프레임을 생략하면 적용되는 기본 프레임은?","ex":"ORDER BY가 있으면 기본 프레임은 RANGE 기반 누적입니다. ORDER BY 자체가 없을 때만 파티션 전체가 대상이 됩니다.","o":["ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW","프레임이 적용되지 않아 파티션 전체가 대상이 된다","RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW","ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING"],"a":2},{"t":"choice","k":"동률 누적합","q":"같은 날짜가 3건씩 있는 테이블에서 SUM(amount) OVER (ORDER BY d) 를 쓰면?","ex":"기본 RANGE 프레임이 동률 묶음을 함께 포함하기 때문입니다. 행 단위로 하나씩 증가하는 누적합을 원하면 ROWS UNBOUNDED PRECEDING을 명시하거나 정렬 키에 유일 컬럼을 추가해야 합니다.","o":["날짜별로 나눠지지 않고 전체 합계가 반복된다","첫 행만 값이 나오고 나머지는 NULL이 된다","각 행마다 한 건씩 더해진 서로 다른 누적값이 나온다","같은 날짜의 세 행 모두 그 날짜까지의 합계로 같은 값이 나온다"],"a":3},{"t":"choice","k":"PARTITION BY 생략","q":"OVER 절에 PARTITION BY를 쓰지 않으면 어떻게 동작하는가?","ex":"PARTITION BY는 계산 그룹을 나누는 선택 사항입니다. 생략하면 전체가 한 그룹이므로 전체 누적합이나 전체 순위를 구할 때 그대로 씁니다.","o":["각 행이 독립된 파티션이 된다","GROUP BY 컬럼이 자동으로 파티션 키가 된다","윈도우 함수가 무시되고 NULL이 반환된다","결과 집합 전체가 하나의 파티션으로 취급된다"],"a":3},{"t":"input","k":"프레임 절 작성","q":"'앞의 2개 행과 현재 행'만 포함하는 프레임 절을 SQL로 그대로 쓰시오.","ex":"물리적 행 개수를 지정하려면 반드시 ROWS를 써야 합니다. RANGE로 쓰면 동률 행이 함께 포함되어 개수가 달라집니다.","a":["ROWS BETWEEN 2 PRECEDING AND CURRENT ROW","rows between 2 preceding and current row"]}],"th":{"sum":"윈도우 프레임에서 ROWS는 물리적인 행 개수로, RANGE는 ORDER BY 값이 같은 동률(peer)까지 묶어 범위를 정한다. 그룹별 상위 N과 이동 평균은 프레임을 정확히 지정해야 의도한 결과가 나온다.","body":[{"h":"ROWS와 RANGE는 다르다","t":"ROWS BETWEEN 2 PRECEDING AND CURRENT ROW는 앞의 두 행과 현재 행, 정확히 최대 3개 행을 본다. RANGE는 ORDER BY 값이 같은 행들을 하나의 동률 묶음으로 취급하므로, 같은 날짜가 여러 건이면 그 날짜의 모든 행이 함께 들어온다. ORDER BY만 쓰고 프레임을 생략하면 기본값이 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW이며, 이 때문에 누적합이 동률 행들에서 모두 같은 값으로 나온다 — 한 건씩 증가하는 누적합을 원하면 ROWS를 명시해야 한다."},{"h":"그룹별 상위 N","t":"PARTITION BY로 그룹을 나누고 ROW_NUMBER() OVER (PARTITION BY g ORDER BY v DESC)로 순위를 매긴 뒤, 서브쿼리 바깥에서 rn <= 3으로 거른다. 윈도우 함수는 WHERE와 GROUP BY, HAVING이 끝난 뒤에 계산되므로 같은 SELECT의 WHERE 절에서는 참조할 수 없다. 동점을 모두 포함하려면 RANK(), 동점에 같은 순위를 주되 번호를 건너뛰지 않으려면 DENSE_RANK()를 쓴다."},{"h":"누적과 이동 평균","t":"누적합은 SUM(x) OVER (ORDER BY d ROWS UNBOUNDED PRECEDING), 7일 이동 평균은 AVG(x) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)로 쓴다. 다만 중간에 빠진 날짜가 있으면 '6행 전'과 '6일 전'이 달라지므로, 달력 테이블로 빈 날짜를 채우거나 RANGE BETWEEN INTERVAL '6 days' PRECEDING AND CURRENT ROW 같은 값 기반 프레임을 쓴다. 앞뒤 행과의 비교는 자기 조인 대신 LAG/LEAD가 훨씬 간결하고 빠르다."}],"code":{"c":"-- 그룹별 상위 3\nSELECT category, name, sales\nFROM (\n  SELECT category, name, sales,\n         ROW_NUMBER() OVER (PARTITION BY category ORDER BY sales DESC) AS rn\n  FROM products\n) t\nWHERE rn <= 3;\n\n-- 7일 이동 평균(물리적 7행)과 전일 대비 증감\nSELECT d,\n       AVG(amount) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7,\n       amount - LAG(amount) OVER (ORDER BY d) AS diff\nFROM daily_sales;","cap":"ROWS는 행 개수, RANGE는 값이 같은 동률 묶음 — 프레임을 생략하면 RANGE가 기본이다."},"key":["ROWS는 물리적 행 수, RANGE는 ORDER BY 값이 같은 peer를 함께 포함","ORDER BY만 있고 프레임 생략 시 기본은 RANGE UNBOUNDED PRECEDING ~ CURRENT ROW","윈도우 함수는 WHERE 이후에 계산 — 순위 필터는 서브쿼리 바깥에서"]}},{"t":"그룹별 상위 N","q":[{"t":"choice","k":"동점 포함","q":"각 부서에서 급여 상위 3위까지를 뽑되 3위가 동점이면 모두 포함하려면?","ex":"ROW_NUMBER는 동점 중 하나만 남기므로 요구사항과 다릅니다. DENSE_RANK로 걸러도 동점은 포함되지만 순위가 건너뛰지 않아 '상위 3개 값'을 뽑는 의미가 되어 결과 행 수가 더 많아질 수 있습니다.","o":["RANK()를 사용해 순위를 매기고 rnk &lt;= 3 으로 거른다","DENSE_RANK()를 사용하고 rnk &lt;= 3 으로 걸러야만 동점이 모두 포함된다","ROW_NUMBER()를 사용하고 rn &lt;= 3 으로 거른다","LIMIT 3 을 사용한다"],"a":0},{"t":"choice","k":"그룹별 최신 1건","q":"사용자별 가장 최근 주문 1건씩만 조회하는 방법으로 적절한 것은?","ex":"GROUP BY로는 최대 날짜만 알 뿐 그 행의 다른 컬럼을 안전하게 가져올 수 없고, LIMIT 1은 전체에서 한 건만 나옵니다. 사용자별 상위 1건은 파티션 순번이 정석입니다.","o":["ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY created_at DESC)로 번호를 매기고 rn = 1 을 고른다","ORDER BY created_at DESC LIMIT 1 을 사용한다","DISTINCT user_id 를 사용한다","GROUP BY user_id 만 쓰고 나머지 컬럼을 그대로 SELECT 한다"],"a":0}],"th":{"sum":"윈도우 프레임에서 ROWS는 물리적인 행 개수로, RANGE는 ORDER BY 값이 같은 동률(peer)까지 묶어 범위를 정한다. 그룹별 상위 N과 이동 평균은 프레임을 정확히 지정해야 의도한 결과가 나온다.","body":[{"h":"ROWS와 RANGE는 다르다","t":"ROWS BETWEEN 2 PRECEDING AND CURRENT ROW는 앞의 두 행과 현재 행, 정확히 최대 3개 행을 본다. RANGE는 ORDER BY 값이 같은 행들을 하나의 동률 묶음으로 취급하므로, 같은 날짜가 여러 건이면 그 날짜의 모든 행이 함께 들어온다. ORDER BY만 쓰고 프레임을 생략하면 기본값이 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW이며, 이 때문에 누적합이 동률 행들에서 모두 같은 값으로 나온다 — 한 건씩 증가하는 누적합을 원하면 ROWS를 명시해야 한다."},{"h":"그룹별 상위 N","t":"PARTITION BY로 그룹을 나누고 ROW_NUMBER() OVER (PARTITION BY g ORDER BY v DESC)로 순위를 매긴 뒤, 서브쿼리 바깥에서 rn <= 3으로 거른다. 윈도우 함수는 WHERE와 GROUP BY, HAVING이 끝난 뒤에 계산되므로 같은 SELECT의 WHERE 절에서는 참조할 수 없다. 동점을 모두 포함하려면 RANK(), 동점에 같은 순위를 주되 번호를 건너뛰지 않으려면 DENSE_RANK()를 쓴다."},{"h":"누적과 이동 평균","t":"누적합은 SUM(x) OVER (ORDER BY d ROWS UNBOUNDED PRECEDING), 7일 이동 평균은 AVG(x) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)로 쓴다. 다만 중간에 빠진 날짜가 있으면 '6행 전'과 '6일 전'이 달라지므로, 달력 테이블로 빈 날짜를 채우거나 RANGE BETWEEN INTERVAL '6 days' PRECEDING AND CURRENT ROW 같은 값 기반 프레임을 쓴다. 앞뒤 행과의 비교는 자기 조인 대신 LAG/LEAD가 훨씬 간결하고 빠르다."}],"code":{"c":"-- 그룹별 상위 3\nSELECT category, name, sales\nFROM (\n  SELECT category, name, sales,\n         ROW_NUMBER() OVER (PARTITION BY category ORDER BY sales DESC) AS rn\n  FROM products\n) t\nWHERE rn <= 3;\n\n-- 7일 이동 평균(물리적 7행)과 전일 대비 증감\nSELECT d,\n       AVG(amount) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7,\n       amount - LAG(amount) OVER (ORDER BY d) AS diff\nFROM daily_sales;","cap":"ROWS는 행 개수, RANGE는 값이 같은 동률 묶음 — 프레임을 생략하면 RANGE가 기본이다."},"key":["ROWS는 물리적 행 수, RANGE는 ORDER BY 값이 같은 peer를 함께 포함","ORDER BY만 있고 프레임 생략 시 기본은 RANGE UNBOUNDED PRECEDING ~ CURRENT ROW","윈도우 함수는 WHERE 이후에 계산 — 순위 필터는 서브쿼리 바깥에서"]}},{"t":"누적·이동 평균 실무","q":[{"t":"choice","k":"초기 구간","q":"ROWS BETWEEN 6 PRECEDING AND CURRENT ROW 프레임에서 데이터의 첫 3행은 어떻게 계산되는가?","ex":"프레임은 파티션 경계를 넘지 않고 존재하는 행만 대상으로 합니다. 초기 구간의 불안정한 값을 감추려면 COUNT(*) OVER (같은 프레임)가 7 미만인 행을 NULL로 처리하면 됩니다.","o":["오류가 발생한다","앞선 행이 부족하므로 NULL이 반환된다","부족한 만큼 0으로 채워져 평균이 낮아진다","존재하는 행들만으로 평균이 계산되어, 첫 행은 자기 자신만의 평균이 된다"],"a":3},{"t":"input","k":"이전 행 함수","q":"정렬된 창에서 바로 이전 행의 값을 가져오는 윈도우 함수 이름은? (영문)","ex":"다음 행 값은 LEAD입니다. 둘 다 두 번째 인자로 오프셋, 세 번째 인자로 기본값을 지정할 수 있습니다.","a":["LAG","lag"]}],"th":{"sum":"윈도우 프레임에서 ROWS는 물리적인 행 개수로, RANGE는 ORDER BY 값이 같은 동률(peer)까지 묶어 범위를 정한다. 그룹별 상위 N과 이동 평균은 프레임을 정확히 지정해야 의도한 결과가 나온다.","body":[{"h":"ROWS와 RANGE는 다르다","t":"ROWS BETWEEN 2 PRECEDING AND CURRENT ROW는 앞의 두 행과 현재 행, 정확히 최대 3개 행을 본다. RANGE는 ORDER BY 값이 같은 행들을 하나의 동률 묶음으로 취급하므로, 같은 날짜가 여러 건이면 그 날짜의 모든 행이 함께 들어온다. ORDER BY만 쓰고 프레임을 생략하면 기본값이 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW이며, 이 때문에 누적합이 동률 행들에서 모두 같은 값으로 나온다 — 한 건씩 증가하는 누적합을 원하면 ROWS를 명시해야 한다."},{"h":"그룹별 상위 N","t":"PARTITION BY로 그룹을 나누고 ROW_NUMBER() OVER (PARTITION BY g ORDER BY v DESC)로 순위를 매긴 뒤, 서브쿼리 바깥에서 rn <= 3으로 거른다. 윈도우 함수는 WHERE와 GROUP BY, HAVING이 끝난 뒤에 계산되므로 같은 SELECT의 WHERE 절에서는 참조할 수 없다. 동점을 모두 포함하려면 RANK(), 동점에 같은 순위를 주되 번호를 건너뛰지 않으려면 DENSE_RANK()를 쓴다."},{"h":"누적과 이동 평균","t":"누적합은 SUM(x) OVER (ORDER BY d ROWS UNBOUNDED PRECEDING), 7일 이동 평균은 AVG(x) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)로 쓴다. 다만 중간에 빠진 날짜가 있으면 '6행 전'과 '6일 전'이 달라지므로, 달력 테이블로 빈 날짜를 채우거나 RANGE BETWEEN INTERVAL '6 days' PRECEDING AND CURRENT ROW 같은 값 기반 프레임을 쓴다. 앞뒤 행과의 비교는 자기 조인 대신 LAG/LEAD가 훨씬 간결하고 빠르다."}],"code":{"c":"-- 그룹별 상위 3\nSELECT category, name, sales\nFROM (\n  SELECT category, name, sales,\n         ROW_NUMBER() OVER (PARTITION BY category ORDER BY sales DESC) AS rn\n  FROM products\n) t\nWHERE rn <= 3;\n\n-- 7일 이동 평균(물리적 7행)과 전일 대비 증감\nSELECT d,\n       AVG(amount) OVER (ORDER BY d ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS ma7,\n       amount - LAG(amount) OVER (ORDER BY d) AS diff\nFROM daily_sales;","cap":"ROWS는 행 개수, RANGE는 값이 같은 동률 묶음 — 프레임을 생략하면 RANGE가 기본이다."},"key":["ROWS는 물리적 행 수, RANGE는 ORDER BY 값이 같은 peer를 함께 포함","ORDER BY만 있고 프레임 생략 시 기본은 RANGE UNBOUNDED PRECEDING ~ CURRENT ROW","윈도우 함수는 WHERE 이후에 계산 — 순위 필터는 서브쿼리 바깥에서"]}}]},{"t":"실무 디버깅 II — 조용히 틀린 결과","l":[{"t":"디버깅 I","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"블랙리스트에 올라 있지 않은 고객의 이름을 id 오름차순으로 조회해야 한다. 기대 결과는 Ann, Cho, Eun 세 명인데 이 쿼리는 한 행도 반환하지 않는다.","schema":"CREATE TABLE customer (id INTEGER, name TEXT);\nINSERT INTO customer VALUES (1,'Ann'),(2,'Ben'),(3,'Cho'),(4,'Dae'),(5,'Eun');\nCREATE TABLE blacklist (customer_id INTEGER, reason TEXT);\nINSERT INTO blacklist VALUES (2,'chargeback'),(4,'fraud'),(NULL,'unknown');","src":"SELECT name\nFROM customer\nWHERE id NOT IN (SELECT customer_id FROM blacklist)\nORDER BY id;","sol":"SELECT c.name\nFROM customer c\nWHERE NOT EXISTS (\n  SELECT 1 FROM blacklist b WHERE b.customer_id = c.id\n)\nORDER BY c.id;","ordered":true,"ex":"🐛 원인: 서브쿼리 결과에 NULL이 섞여 있어 NOT IN 비교가 모든 행에서 TRUE가 아닌 UNKNOWN이 된다. 그래서 WHERE 절이 어떤 행도 통과시키지 못한다.\n🔧 해결: NOT IN 대신 NOT EXISTS를 쓰거나 서브쿼리에 WHERE customer_id IS NOT NULL을 추가한다.\n🛡 재발 방지: 서브쿼리 컬럼이 NULL 가능하면 NOT IN을 쓰지 말고 NOT EXISTS/안티 조인을 기본형으로 삼는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"모든 매장에 대해 2024년 5월 매출 합계를 매장 id 순으로 내야 하며 5월 매출이 없는 매장은 0으로 나와야 한다. 기대 결과는 Gangnam 100, Hongdae 250, Jamsil 0, Ilsan 0인데 이 쿼리는 두 행만 반환한다.","schema":"CREATE TABLE store (id INTEGER, name TEXT);\nINSERT INTO store VALUES (1,'Gangnam'),(2,'Hongdae'),(3,'Jamsil'),(4,'Ilsan');\nCREATE TABLE sale (id INTEGER, store_id INTEGER, sold_on TEXT, amount INTEGER);\nINSERT INTO sale VALUES\n (1,1,'2024-05-02',100),\n (2,1,'2024-04-11',300),\n (3,2,'2024-05-20',250),\n (4,3,'2024-03-01',400);","src":"SELECT s.name, COALESCE(SUM(sa.amount), 0) AS may_total\nFROM store s\nLEFT JOIN sale sa ON sa.store_id = s.id\nWHERE sa.sold_on >= '2024-05-01' AND sa.sold_on < '2024-06-01'\nGROUP BY s.id, s.name\nORDER BY s.id;","sol":"SELECT s.name, COALESCE(SUM(sa.amount), 0) AS may_total\nFROM store s\nLEFT JOIN sale sa\n  ON sa.store_id = s.id\n AND sa.sold_on >= '2024-05-01'\n AND sa.sold_on < '2024-06-01'\nGROUP BY s.id, s.name\nORDER BY s.id;","ordered":true,"ex":"🐛 원인: LEFT JOIN으로 붙인 우측 테이블 컬럼 조건을 WHERE에 두면 매칭되지 않은 행의 NULL이 조건에서 탈락한다. 결과적으로 LEFT JOIN이 INNER JOIN으로 퇴화한다.\n🔧 해결: 우측 테이블에 대한 필터 조건을 WHERE가 아니라 ON 절로 옮긴다.\n🛡 재발 방지: LEFT JOIN한 테이블의 컬럼 조건은 항상 ON에 두고, WHERE에는 좌측 테이블 조건이나 IS NULL 검사만 둔다."},{"t":"sql","k":"디버깅","cat":"debug","q":"상품별 총 판매 수량과 총 환불 수량을 상품 id 순으로 구해야 한다. 기대 결과는 Keyboard 판매 5 환불 3, Mouse 판매 5 환불 1, Monitor 판매 1 환불 0인데 이 쿼리는 Keyboard 값을 부풀린다.","schema":"CREATE TABLE product (id INTEGER, name TEXT);\nINSERT INTO product VALUES (1,'Keyboard'),(2,'Mouse'),(3,'Monitor');\nCREATE TABLE sale (id INTEGER, product_id INTEGER, qty INTEGER);\nINSERT INTO sale VALUES (1,1,2),(2,1,3),(3,2,5),(4,3,1);\nCREATE TABLE refund (id INTEGER, product_id INTEGER, qty INTEGER);\nINSERT INTO refund VALUES (1,1,1),(2,1,2),(3,2,1);","src":"SELECT p.name,\n       COALESCE(SUM(s.qty), 0) AS sold,\n       COALESCE(SUM(r.qty), 0) AS refunded\nFROM product p\nLEFT JOIN sale s   ON s.product_id = p.id\nLEFT JOIN refund r ON r.product_id = p.id\nGROUP BY p.id, p.name\nORDER BY p.id;","sol":"SELECT p.name,\n       COALESCE((SELECT SUM(s.qty) FROM sale s   WHERE s.product_id = p.id), 0) AS sold,\n       COALESCE((SELECT SUM(r.qty) FROM refund r WHERE r.product_id = p.id), 0) AS refunded\nFROM product p\nORDER BY p.id;","ordered":true,"ex":"🐛 원인: 1:N 테이블 두 개를 한 번에 조인하면 두 자식 행 집합의 카테시안 곱이 만들어진다. 판매 2행 × 환불 2행 = 4행이 되어 양쪽 SUM이 모두 배로 부풀려진다.\n🔧 해결: 각 자식 테이블을 미리 따로 집계한 뒤(스칼라 서브쿼리나 사전 집계 CTE) 부모에 붙인다.\n🛡 재발 방지: 한 쿼리에서 1:N 관계를 두 개 이상 조인해 집계할 때는 반드시 자식별로 먼저 집계하고 조인한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"지역별로 주문한 '고객 수'를 지역 이름 순으로 구해야 한다. 기대 결과는 East 2, West 2인데 이 쿼리는 East 3, West 4를 반환한다.","schema":"CREATE TABLE orders (id INTEGER, region TEXT, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES\n (1,'East',10,100),\n (2,'East',10,150),\n (3,'East',11,200),\n (4,'West',20,300),\n (5,'West',21,120),\n (6,'West',21,80),\n (7,'West',21,60);","src":"SELECT region, COUNT(customer_id) AS customer_cnt\nFROM orders\nGROUP BY region\nORDER BY region;","sol":"SELECT region, COUNT(DISTINCT customer_id) AS customer_cnt\nFROM orders\nGROUP BY region\nORDER BY region;","ordered":true,"ex":"🐛 원인: COUNT(customer_id)는 고객 수가 아니라 고객 id가 들어 있는 주문 행 수를 센다. 한 고객이 여러 번 주문하면 그만큼 중복 계산된다.\n🔧 해결: COUNT(DISTINCT customer_id)로 바꿔 고유 고객 수를 센다.\n🛡 재발 방지: '~한 사람/건 수'를 셀 때 대상이 행 단위인지 엔터티 단위인지 먼저 정하고 DISTINCT 여부를 결정한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"거래를 날짜·id 순으로 놓고 '행 단위' 누적 합계를 구해야 한다. 기대 누적값은 100, 150, 220, 240, 270, 310인데 이 쿼리는 같은 날짜 행들이 같은 누적값을 갖는다.","schema":"CREATE TABLE ledger (id INTEGER, txn_date TEXT, amount INTEGER);\nINSERT INTO ledger VALUES\n (1,'2024-01-01',100),\n (2,'2024-01-02',50),\n (3,'2024-01-02',70),\n (4,'2024-01-03',20),\n (5,'2024-01-03',30),\n (6,'2024-01-04',40);","src":"SELECT id, txn_date, amount,\n       SUM(amount) OVER (ORDER BY txn_date) AS running_total\nFROM ledger\nORDER BY id;","sol":"SELECT id, txn_date, amount,\n       SUM(amount) OVER (\n         ORDER BY txn_date, id\n         ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n       ) AS running_total\nFROM ledger\nORDER BY id;","ordered":true,"ex":"🐛 원인: 윈도우 프레임을 생략하면 기본값이 RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW라서 ORDER BY 값이 같은 동점 행이 한 덩어리로 묶여 같은 누적값을 받는다.\n🔧 해결: ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW 프레임을 명시하고 ORDER BY에 고유 키를 덧붙여 순서를 확정한다.\n🛡 재발 방지: 누적 합계 윈도우 함수에는 프레임을 항상 명시하고, ORDER BY 키가 유일하지 않으면 tie-breaker 컬럼을 추가한다."}],"th":{"sum":"SQL은 **에러 없이 틀린다**. NULL과 조인 배수가 가장 흔한 두 범인이다.","body":[{"h":"NULL은 조건을 무력화한다","t":"`NOT IN (서브쿼리)`에 NULL이 하나라도 섞이면 결과가 통째로 비어버린다. `<>` 비교도 NULL 행을 빼먹으므로 의도했다면 `IS NULL`을 명시해야 한다. 전부 NULL인 열의 `SUM`은 0이 아니라 NULL이라 `COALESCE`가 필요하고, `COUNT(col)`은 NULL을 세지 않는다."},{"h":"조인과 윈도우는 배수·동점을 만든다","t":"일대다 테이블 두 개를 한꺼번에 조인하고 `SUM`을 하면 값이 곱해져 부풀어난다 — 각각 집계한 뒤 합쳐야 한다. `RANK`는 동점에서 순위를 건너뛰고 `DENSE_RANK`는 건너뛰지 않으며, 그룹별로 정확히 N개가 필요하면 `ROW_NUMBER`를 쓴다. 윈도우 프레임을 생략하면 기본이 `RANGE`라 동점 행이 함께 묶인다."}],"code":{"c":"-- 함정: 서브쿼리에 NULL이 있으면 NOT IN은 아무 행도 반환하지 않는다\nSELECT * FROM users\nWHERE id NOT IN (SELECT user_id FROM orders);   -- user_id에 NULL이 있으면 0행\n\n-- 안전: NOT EXISTS 는 NULL의 영향을 받지 않는다\nSELECT * FROM users u\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.user_id = u.id\n);","cap":"NOT IN + NULL은 조용히 전체 결과를 지운다."},"key":["NOT IN에 NULL이 섞이면 결과가 비어버린다 — NOT EXISTS 사용","<>는 NULL 행을 놓친다, IS NULL 명시","일대다 두 번 조인 후 SUM은 부풀어난다","RANK·DENSE_RANK·ROW_NUMBER는 동점 처리가 다르다"]}},{"t":"디버깅 II","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"부서마다 연봉이 가장 높은 직원 '한 명씩만' 뽑아야 하며 동점이면 이름 사전순으로 앞선 사람을 택한다. 기대 결과는 Sales-Ann, Tech-Dae 두 행인데 이 쿼리는 세 행을 반환한다.","schema":"CREATE TABLE emp (id INTEGER, dept TEXT, name TEXT, salary INTEGER);\nINSERT INTO emp VALUES\n (1,'Sales','Ann',500),\n (2,'Sales','Ben',500),\n (3,'Sales','Cho',400),\n (4,'Tech','Dae',700),\n (5,'Tech','Eun',600),\n (6,'Tech','Foo',600);","src":"SELECT dept, name, salary\nFROM (\n  SELECT dept, name, salary,\n         RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS rk\n  FROM emp\n)\nWHERE rk = 1\nORDER BY dept, name;","sol":"SELECT dept, name, salary\nFROM (\n  SELECT dept, name, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC, name ASC) AS rn\n  FROM emp\n)\nWHERE rn = 1\nORDER BY dept, name;","ordered":true,"ex":"🐛 원인: RANK()는 동점에 같은 순위를 부여하므로 rk=1인 행이 부서마다 여러 개 나올 수 있다. Sales의 Ann과 Ben이 둘 다 1위가 된다.\n🔧 해결: 그룹당 정확히 한 행이 필요하면 ROW_NUMBER()를 쓰고 ORDER BY에 tie-breaker(name)를 넣는다.\n🛡 재발 방지: '그룹별 상위 1건'은 ROW_NUMBER, '동점 포함 상위 N'은 RANK/DENSE_RANK로 요구사항을 명시해 구분한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"자기 부서의 예산 상한(max_salary)을 초과하는 직원을 emp_id 순으로 찾아야 한다. 기대 결과는 Ben, Cho, Dae, Foo인데 이 쿼리는 Ben과 Dae만 반환한다.","schema":"CREATE TABLE employee (emp_id INTEGER, name TEXT, dept_id INTEGER, salary INTEGER);\nINSERT INTO employee VALUES\n (1,'Ann',10,500),\n (2,'Ben',10,700),\n (3,'Cho',20,400),\n (4,'Dae',20,900),\n (5,'Eun',30,300),\n (6,'Foo',30,550);\nCREATE TABLE dept_budget (dept_id INTEGER, max_salary INTEGER);\nINSERT INTO dept_budget VALUES (10,600),(20,350),(30,450);","src":"SELECT e.name, e.salary\nFROM employee e\nWHERE e.salary > (\n  SELECT max_salary\n  FROM dept_budget\n  WHERE dept_id = dept_id\n)\nORDER BY e.emp_id;","sol":"SELECT e.name, e.salary\nFROM employee e\nWHERE e.salary > (\n  SELECT b.max_salary\n  FROM dept_budget b\n  WHERE b.dept_id = e.dept_id\n)\nORDER BY e.emp_id;","ordered":true,"ex":"🐛 원인: 서브쿼리 안의 dept_id = dept_id는 양쪽 모두 안쪽 테이블 컬럼으로 해석되어 항상 참이 된다. 상관 조건이 사라져 첫 부서의 상한 600이 모든 직원에게 적용된다.\n🔧 해결: 상관 서브쿼리의 모든 컬럼에 별칭을 붙여 b.dept_id = e.dept_id로 명시한다.\n🛡 재발 방지: 상관 서브쿼리에서는 안팎 컬럼을 예외 없이 테이블 별칭으로 한정해 작성한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"2024년 3월에 발생한 이벤트 건수를 세야 한다. 기대 결과는 4건인데 이 쿼리는 2건만 센다.","schema":"CREATE TABLE event_log (id INTEGER, occurred_at TEXT, kind TEXT);\nINSERT INTO event_log VALUES\n (1,'2024-03-01 09:00:00','click'),\n (2,'2024-03-15 12:30:00','view'),\n (3,'2024-03-31 00:00:00','click'),\n (4,'2024-03-31 23:45:10','view'),\n (5,'2024-04-01 08:00:00','click');","src":"SELECT COUNT(*) AS march_events\nFROM event_log\nWHERE occurred_at BETWEEN '2024-03-01' AND '2024-03-31';","sol":"SELECT COUNT(*) AS march_events\nFROM event_log\nWHERE occurred_at >= '2024-03-01'\n  AND occurred_at <  '2024-04-01';","ordered":false,"ex":"🐛 원인: occurred_at에는 시각까지 들어 있어서 '2024-03-31 00:00:00'조차 상한 '2024-03-31'보다 크다. BETWEEN의 상한이 그날 자정 딱 한 순간이라 3월 마지막 날이 통째로 빠진다.\n🔧 해결: 상한을 다음 달 1일 미만으로 바꾸는 반열림 구간(&gt;= 시작, &lt; 다음 시작)으로 작성한다.\n🛡 재발 방지: 타임스탬프 구간 필터에는 BETWEEN 대신 항상 [시작, 다음 경계) 반열림 비교를 쓴다."},{"t":"sql","k":"디버깅","cat":"debug","q":"발행일이 2024-06-01 이후(포함)인 청구서를 id 순으로 뽑아야 한다. 기대 결과는 id 3과 4 두 건인데 이 쿼리는 5건 모두 반환한다.","schema":"CREATE TABLE invoice (id INTEGER, issued TEXT, amount INTEGER);\nINSERT INTO invoice VALUES\n (1,'05/02/2024',100),\n (2,'28/02/2024',200),\n (3,'11/06/2024',300),\n (4,'03/07/2024',400),\n (5,'19/12/2023',500);","src":"SELECT id, issued, amount\nFROM invoice\nWHERE issued >= '01/06/2024'\nORDER BY id;","sol":"SELECT id, issued, amount\nFROM invoice\nWHERE substr(issued,7,4) || '-' || substr(issued,4,2) || '-' || substr(issued,1,2) >= '2024-06-01'\nORDER BY id;","ordered":true,"ex":"🐛 원인: issued가 DD/MM/YYYY 형식의 문자열이라 비교가 날짜가 아니라 앞자리(일)부터의 사전순으로 이뤄진다. '05/02/2024'가 '01/06/2024'보다 크다고 판정된다.\n🔧 해결: 문자열을 YYYY-MM-DD 순서로 재조립(또는 date()로 변환)한 뒤 비교한다.\n🛡 재발 방지: 날짜는 반드시 ISO-8601(YYYY-MM-DD) 형식으로 저장하고, 아니라면 비교 전에 정규화한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"팀별 총점을 총점 내림차순으로 내되 기록이 없는 팀은 0으로 표시해야 한다. 기대 결과는 Alpha 15, Beta 7, Delta 3, Gamma 0인데 이 쿼리는 Gamma의 총점을 NULL로 낸다.","schema":"CREATE TABLE team (id INTEGER, name TEXT);\nINSERT INTO team VALUES (1,'Alpha'),(2,'Beta'),(3,'Gamma'),(4,'Delta');\nCREATE TABLE point (id INTEGER, team_id INTEGER, pts INTEGER);\nINSERT INTO point VALUES (1,1,10),(2,1,5),(3,2,7),(4,4,3);","src":"SELECT t.name, SUM(p.pts) AS total\nFROM team t\nLEFT JOIN point p ON p.team_id = t.id\nGROUP BY t.id, t.name\nORDER BY total DESC, t.id;","sol":"SELECT t.name, COALESCE(SUM(p.pts), 0) AS total\nFROM team t\nLEFT JOIN point p ON p.team_id = t.id\nGROUP BY t.id, t.name\nORDER BY total DESC, t.id;","ordered":true,"ex":"🐛 원인: LEFT JOIN에서 매칭되는 자식 행이 하나도 없으면 SUM은 0이 아니라 NULL을 돌려준다. 집계 함수는 빈 집합에 대해 NULL을 반환하기 때문이다.\n🔧 해결: COALESCE(SUM(p.pts), 0)으로 감싸 빈 그룹을 0으로 만든다.\n🛡 재발 방지: LEFT JOIN 위의 SUM/COUNT 결과를 리포트에 노출할 때는 기본값 처리(COALESCE)를 습관화한다."}],"th":{"sum":"SQL은 **에러 없이 틀린다**. NULL과 조인 배수가 가장 흔한 두 범인이다.","body":[{"h":"NULL은 조건을 무력화한다","t":"`NOT IN (서브쿼리)`에 NULL이 하나라도 섞이면 결과가 통째로 비어버린다. `<>` 비교도 NULL 행을 빼먹으므로 의도했다면 `IS NULL`을 명시해야 한다. 전부 NULL인 열의 `SUM`은 0이 아니라 NULL이라 `COALESCE`가 필요하고, `COUNT(col)`은 NULL을 세지 않는다."},{"h":"조인과 윈도우는 배수·동점을 만든다","t":"일대다 테이블 두 개를 한꺼번에 조인하고 `SUM`을 하면 값이 곱해져 부풀어난다 — 각각 집계한 뒤 합쳐야 한다. `RANK`는 동점에서 순위를 건너뛰고 `DENSE_RANK`는 건너뛰지 않으며, 그룹별로 정확히 N개가 필요하면 `ROW_NUMBER`를 쓴다. 윈도우 프레임을 생략하면 기본이 `RANGE`라 동점 행이 함께 묶인다."}],"code":{"c":"-- 함정: 서브쿼리에 NULL이 있으면 NOT IN은 아무 행도 반환하지 않는다\nSELECT * FROM users\nWHERE id NOT IN (SELECT user_id FROM orders);   -- user_id에 NULL이 있으면 0행\n\n-- 안전: NOT EXISTS 는 NULL의 영향을 받지 않는다\nSELECT * FROM users u\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.user_id = u.id\n);","cap":"NOT IN + NULL은 조용히 전체 결과를 지운다."},"key":["NOT IN에 NULL이 섞이면 결과가 비어버린다 — NOT EXISTS 사용","<>는 NULL 행을 놓친다, IS NULL 명시","일대다 두 번 조인 후 SUM은 부풀어난다","RANK·DENSE_RANK·ROW_NUMBER는 동점 처리가 다르다"]}},{"t":"디버깅 III","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"벤더별 총 청구액을 벤더 이름 순으로 구해야 한다. 기대 결과는 Acme 100, Bolt 250, Cyan 300, Dyne 400, Echo 150의 5행인데 이 쿼리는 3행만 반환한다.","schema":"CREATE TABLE vendor (id INTEGER, name TEXT, tax_code TEXT);\nINSERT INTO vendor VALUES\n (1,'Acme','TC1'),\n (2,'Bolt',NULL),\n (3,'Cyan','TC2'),\n (4,'Dyne',NULL),\n (5,'Echo','TC1');\nCREATE TABLE bill (id INTEGER, vendor_id INTEGER, amount INTEGER);\nINSERT INTO bill VALUES (1,1,100),(2,2,200),(3,3,300),(4,4,400),(5,5,150),(6,2,50);","src":"SELECT v.name, SUM(b.amount) AS total\nFROM vendor v\nJOIN bill b ON b.vendor_id = v.id\nGROUP BY v.tax_code\nORDER BY v.name;","sol":"SELECT v.name, SUM(b.amount) AS total\nFROM vendor v\nJOIN bill b ON b.vendor_id = v.id\nGROUP BY v.id, v.name\nORDER BY v.name;","ordered":true,"ex":"🐛 원인: tax_code는 벤더를 유일하게 식별하지 못하고 NULL도 섞여 있다. GROUP BY는 NULL끼리도 한 그룹으로 묶으므로 Bolt와 Dyne이, TC1을 공유하는 Acme와 Echo가 각각 하나의 행으로 합쳐진다.\n🔧 해결: 그룹 키를 엔터티의 기본키인 v.id(와 표시용 v.name)로 바꾼다.\n🛡 재발 방지: GROUP BY 키는 NULL이 없고 유일성이 보장된 컬럼(보통 기본키)으로 잡는다."},{"t":"sql","k":"디버깅","cat":"debug","q":"온라인과 매장 두 채널의 모든 주문 건을 합쳐 고객별 총 매출을 이름 순으로 구해야 한다. 기대 결과는 Ann 300, Ben 100, Cho 70인데 이 쿼리는 Ann 100, Ben 50, Cho 70을 반환한다.","schema":"CREATE TABLE online_order (id INTEGER, customer TEXT, amount INTEGER);\nINSERT INTO online_order VALUES (1,'Ann',100),(2,'Ben',50),(3,'Ann',100);\nCREATE TABLE store_order (id INTEGER, customer TEXT, amount INTEGER);\nINSERT INTO store_order VALUES (1,'Ann',100),(2,'Cho',70),(3,'Ben',50);","src":"SELECT customer, SUM(amount) AS total\nFROM (\n  SELECT customer, amount FROM online_order\n  UNION\n  SELECT customer, amount FROM store_order\n)\nGROUP BY customer\nORDER BY customer;","sol":"SELECT customer, SUM(amount) AS total\nFROM (\n  SELECT customer, amount FROM online_order\n  UNION ALL\n  SELECT customer, amount FROM store_order\n)\nGROUP BY customer\nORDER BY customer;","ordered":true,"ex":"🐛 원인: UNION은 집합 연산이라 (customer, amount)가 동일한 주문 행들을 중복으로 보고 하나만 남긴다. 금액이 같은 별개의 주문 건이 통째로 사라진다.\n🔧 해결: 중복 제거가 필요 없는 합치기이므로 UNION ALL을 쓴다.\n🛡 재발 방지: 트랜잭션 성격의 데이터를 합칠 때는 기본을 UNION ALL로 하고, 중복 제거가 정말 필요할 때만 UNION을 쓴다."},{"t":"sql","k":"디버깅","cat":"debug","q":"취소되지 않은 작업을 id 순으로 조회해야 하며 상태가 미기입(NULL)인 작업도 포함해야 한다. 기대 결과는 id 1, 3, 4, 5인데 이 쿼리는 1과 4만 반환한다.","schema":"CREATE TABLE task (id INTEGER, title TEXT, status TEXT);\nINSERT INTO task VALUES\n (1,'spec','done'),\n (2,'design','cancelled'),\n (3,'build',NULL),\n (4,'test','done'),\n (5,'deploy',NULL),\n (6,'review','cancelled');","src":"SELECT id, title, status\nFROM task\nWHERE status <> 'cancelled'\nORDER BY id;","sol":"SELECT id, title, status\nFROM task\nWHERE status IS NULL OR status <> 'cancelled'\nORDER BY id;","ordered":true,"ex":"🐛 원인: NULL &lt;&gt; 'cancelled'는 TRUE가 아니라 UNKNOWN이므로 상태가 비어 있는 행이 조용히 탈락한다. 부정 조건은 NULL 행을 포함하지 않는다.\n🔧 해결: status IS NULL OR status &lt;&gt; 'cancelled' (또는 COALESCE(status,'') &lt;&gt; 'cancelled')로 NULL을 명시적으로 살린다.\n🛡 재발 방지: NULL 가능한 컬럼에 부정 조건을 걸 때는 NULL을 어느 쪽에 넣을지 항상 명시한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"같은 클럽에 속한 선수들의 서로 다른 조합을 순서 무관하게 한 번씩만 나열해야 한다. 기대 결과는 (Ann,Ben) (Ann,Cho) (Ben,Cho) (Dae,Eun) 네 쌍인데 이 쿼리는 자기 자신과의 쌍과 뒤집힌 중복 쌍까지 13행을 반환한다.","schema":"CREATE TABLE player (id INTEGER, name TEXT, club TEXT);\nINSERT INTO player VALUES\n (1,'Ann','Red'),\n (2,'Ben','Red'),\n (3,'Cho','Red'),\n (4,'Dae','Blue'),\n (5,'Eun','Blue');","src":"SELECT a.name AS p1, b.name AS p2, a.club\nFROM player a\nJOIN player b ON b.club = a.club\nORDER BY a.id, b.id;","sol":"SELECT a.name AS p1, b.name AS p2, a.club\nFROM player a\nJOIN player b ON b.club = a.club AND a.id < b.id\nORDER BY a.id, b.id;","ordered":true,"ex":"🐛 원인: 셀프 조인 조건이 클럽만 비교하므로 같은 행끼리의 쌍(a=b)과 (x,y)/(y,x) 두 방향이 모두 살아남는다.\n🔧 해결: 조인 조건에 a.id &lt; b.id를 추가해 자기 쌍과 대칭 중복을 한 번에 제거한다.\n🛡 재발 방지: 조합(순서 무관 쌍)을 만드는 셀프 조인에는 항상 키 부등호 조건을 함께 건다."},{"t":"sql","k":"디버깅","cat":"debug","q":"학생별 평균 점수를 소수 둘째 자리까지 학생 이름 순으로 구해야 한다. 기대 결과는 Ann 84.33, Ben 72.33인데 이 쿼리는 84와 72를 낸다.","schema":"CREATE TABLE score (id INTEGER, student TEXT, subject TEXT, points INTEGER);\nINSERT INTO score VALUES\n (1,'Ann','math',80),\n (2,'Ann','eng',85),\n (3,'Ann','sci',88),\n (4,'Ben','math',70),\n (5,'Ben','eng',75),\n (6,'Ben','sci',72);","src":"SELECT student, ROUND(SUM(points) / COUNT(*), 2) AS avg_points\nFROM score\nGROUP BY student\nORDER BY student;","sol":"SELECT student, ROUND(SUM(points) * 1.0 / COUNT(*), 2) AS avg_points\nFROM score\nGROUP BY student\nORDER BY student;","ordered":true,"ex":"🐛 원인: 정수끼리 나누면 SQLite는 정수 나눗셈을 수행해 소수부를 버린다. 253/3이 84.33이 아니라 84가 되고 ROUND는 이미 잘린 값을 받는다.\n🔧 해결: 분자나 분모 중 하나를 1.0을 곱하거나 CAST(... AS REAL)로 실수로 만든 뒤 나눈다.\n🛡 재발 방지: 비율·평균 계산에서는 나눗셈 전에 한쪽 피연산자를 반드시 실수로 승격시킨다."}],"th":{"sum":"SQL은 **에러 없이 틀린다**. NULL과 조인 배수가 가장 흔한 두 범인이다.","body":[{"h":"NULL은 조건을 무력화한다","t":"`NOT IN (서브쿼리)`에 NULL이 하나라도 섞이면 결과가 통째로 비어버린다. `<>` 비교도 NULL 행을 빼먹으므로 의도했다면 `IS NULL`을 명시해야 한다. 전부 NULL인 열의 `SUM`은 0이 아니라 NULL이라 `COALESCE`가 필요하고, `COUNT(col)`은 NULL을 세지 않는다."},{"h":"조인과 윈도우는 배수·동점을 만든다","t":"일대다 테이블 두 개를 한꺼번에 조인하고 `SUM`을 하면 값이 곱해져 부풀어난다 — 각각 집계한 뒤 합쳐야 한다. `RANK`는 동점에서 순위를 건너뛰고 `DENSE_RANK`는 건너뛰지 않으며, 그룹별로 정확히 N개가 필요하면 `ROW_NUMBER`를 쓴다. 윈도우 프레임을 생략하면 기본이 `RANGE`라 동점 행이 함께 묶인다."}],"code":{"c":"-- 함정: 서브쿼리에 NULL이 있으면 NOT IN은 아무 행도 반환하지 않는다\nSELECT * FROM users\nWHERE id NOT IN (SELECT user_id FROM orders);   -- user_id에 NULL이 있으면 0행\n\n-- 안전: NOT EXISTS 는 NULL의 영향을 받지 않는다\nSELECT * FROM users u\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.user_id = u.id\n);","cap":"NOT IN + NULL은 조용히 전체 결과를 지운다."},"key":["NOT IN에 NULL이 섞이면 결과가 비어버린다 — NOT EXISTS 사용","<>는 NULL 행을 놓친다, IS NULL 명시","일대다 두 번 조인 후 SUM은 부풀어난다","RANK·DENSE_RANK·ROW_NUMBER는 동점 처리가 다르다"]}},{"t":"디버깅 IV","q":[{"t":"sql","k":"디버깅","cat":"debug","q":"각 상품의 매출이 '자기 카테고리 총매출'에서 차지하는 비율을 id 순으로 구해야 한다. 기대 비율은 0.3, 0.7, 0.5, 0.25, 0.25인데 이 쿼리는 전체 합 200 기준으로 계산한다.","schema":"CREATE TABLE item_sales (id INTEGER, category TEXT, item TEXT, revenue INTEGER);\nINSERT INTO item_sales VALUES\n (1,'A','a1',30),\n (2,'A','a2',70),\n (3,'B','b1',50),\n (4,'B','b2',25),\n (5,'B','b3',25);","src":"SELECT id, category, item,\n       ROUND(revenue * 1.0 / SUM(revenue) OVER (), 4) AS share\nFROM item_sales\nORDER BY id;","sol":"SELECT id, category, item,\n       ROUND(revenue * 1.0 / SUM(revenue) OVER (PARTITION BY category), 4) AS share\nFROM item_sales\nORDER BY id;","ordered":true,"ex":"🐛 원인: OVER ()는 파티션 없이 테이블 전체를 하나의 창으로 보므로 분모가 카테고리 합이 아니라 전체 합이 된다.\n🔧 해결: 윈도우에 PARTITION BY category를 넣어 카테고리별 합계를 분모로 쓴다.\n🛡 재발 방지: '그룹 내 비중' 계산에서는 어떤 단위가 분모인지 확인하고 PARTITION BY를 명시한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"부서별 만족도 평균을 구하되 미응답(NULL)은 0점으로 보고 전체 인원 수로 나눠야 한다. 기대 결과는 Ops 4.0, HR 4.5인데 이 쿼리는 Ops 8.0, HR 6.0을 낸다.","schema":"CREATE TABLE survey (id INTEGER, dept TEXT, score INTEGER);\nINSERT INTO survey VALUES\n (1,'Ops',10),\n (2,'Ops',NULL),\n (3,'Ops',6),\n (4,'Ops',NULL),\n (5,'HR',8),\n (6,'HR',4),\n (7,'HR',NULL),\n (8,'HR',6);","src":"SELECT dept, ROUND(AVG(score), 2) AS avg_score\nFROM survey\nGROUP BY dept\nORDER BY dept;","sol":"SELECT dept, ROUND(AVG(COALESCE(score, 0)), 2) AS avg_score\nFROM survey\nGROUP BY dept\nORDER BY dept;","ordered":true,"ex":"🐛 원인: AVG는 NULL 행을 분자에서도 분모에서도 제외하므로 응답자 수로만 나눈 평균이 된다. 요구사항인 '전체 인원 기준 평균'과 분모가 달라진다.\n🔧 해결: AVG(COALESCE(score,0))처럼 NULL을 0으로 채워 전체 행이 분모에 들어가게 한다.\n🛡 재발 방지: 평균을 정의할 때 분모가 '응답자 수'인지 '전체 인원 수'인지 먼저 합의하고 NULL 처리를 명시한다."},{"t":"sql","k":"디버깅","cat":"debug","q":"측정값이 10 이상인 판독값만 값 내림차순으로 조회해야 한다. 기대 결과는 120, 100, 25 세 건인데 이 쿼리는 다섯 건 모두를 이상한 순서로 반환한다.","schema":"CREATE TABLE reading (id INTEGER, sensor TEXT, value TEXT);\nINSERT INTO reading VALUES\n (1,'s1','9'),\n (2,'s2','100'),\n (3,'s3','25'),\n (4,'s4','7'),\n (5,'s5','120');","src":"SELECT id, sensor, value\nFROM reading\nWHERE value >= '10'\nORDER BY value DESC;","sol":"SELECT id, sensor, value\nFROM reading\nWHERE CAST(value AS INTEGER) >= 10\nORDER BY CAST(value AS INTEGER) DESC;","ordered":true,"ex":"🐛 원인: value가 TEXT 컬럼이라 비교와 정렬이 숫자가 아닌 사전순으로 처리된다. '9'가 '10'보다 크고 '25'가 '120'보다 크다고 판정된다.\n🔧 해결: 비교와 정렬 모두에서 CAST(value AS INTEGER)로 숫자 변환한 뒤 사용한다.\n🛡 재발 방지: 수치 데이터는 숫자 타입 컬럼에 저장하고, 불가피하게 TEXT라면 비교·정렬 시 항상 명시적으로 캐스팅한다."}],"th":{"sum":"SQL은 **에러 없이 틀린다**. NULL과 조인 배수가 가장 흔한 두 범인이다.","body":[{"h":"NULL은 조건을 무력화한다","t":"`NOT IN (서브쿼리)`에 NULL이 하나라도 섞이면 결과가 통째로 비어버린다. `<>` 비교도 NULL 행을 빼먹으므로 의도했다면 `IS NULL`을 명시해야 한다. 전부 NULL인 열의 `SUM`은 0이 아니라 NULL이라 `COALESCE`가 필요하고, `COUNT(col)`은 NULL을 세지 않는다."},{"h":"조인과 윈도우는 배수·동점을 만든다","t":"일대다 테이블 두 개를 한꺼번에 조인하고 `SUM`을 하면 값이 곱해져 부풀어난다 — 각각 집계한 뒤 합쳐야 한다. `RANK`는 동점에서 순위를 건너뛰고 `DENSE_RANK`는 건너뛰지 않으며, 그룹별로 정확히 N개가 필요하면 `ROW_NUMBER`를 쓴다. 윈도우 프레임을 생략하면 기본이 `RANGE`라 동점 행이 함께 묶인다."}],"code":{"c":"-- 함정: 서브쿼리에 NULL이 있으면 NOT IN은 아무 행도 반환하지 않는다\nSELECT * FROM users\nWHERE id NOT IN (SELECT user_id FROM orders);   -- user_id에 NULL이 있으면 0행\n\n-- 안전: NOT EXISTS 는 NULL의 영향을 받지 않는다\nSELECT * FROM users u\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.user_id = u.id\n);","cap":"NOT IN + NULL은 조용히 전체 결과를 지운다."},"key":["NOT IN에 NULL이 섞이면 결과가 비어버린다 — NOT EXISTS 사용","<>는 NULL 행을 놓친다, IS NULL 명시","일대다 두 번 조인 후 SUM은 부풀어난다","RANK·DENSE_RANK·ROW_NUMBER는 동점 처리가 다르다"]}}]},{"t":"코드 리뷰 — 쿼리·스키마 결함 찾기","l":[{"t":"코드 리뷰 I","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT *\nFROM orders\nWHERE DATE(created_at) = '2024-05-01'\n  AND customer_name LIKE '%kim%'\nORDER BY created_at DESC;","items":[{"txt":"WHERE 절에서 created_at을 DATE() 함수로 감싸 인덱스를 사용할 수 없게 만든다. created_at &gt;= '2024-05-01' AND created_at &lt; '2024-05-02' 같은 범위 조건으로 바꿔야 한다.","bad":true},{"txt":"LIKE '%kim%' 처럼 앞에 와일드카드가 붙으면 B-Tree 인덱스로 시작점을 잡을 수 없어 전체 스캔이 된다. 전문 검색 인덱스나 trigram 인덱스가 필요하다.","bad":true},{"txt":"SELECT * 로 모든 컬럼을 읽어 불필요한 I/O와 네트워크 전송이 발생하고, 커버링 인덱스도 활용할 수 없다.","bad":true},{"txt":"ORDER BY created_at DESC는 인덱스를 사용할 수 없으므로 제거해야 한다.","bad":false},{"txt":"날짜를 '2024-05-01' 같은 문자열 리터럴과 비교하면 타입이 달라 항상 0건이 반환된다.","bad":false}],"ex":"실제 결함 3가지. (1) 컬럼을 함수로 감싼 조건(sargable하지 않음) — 범위 조건으로 재작성하거나 표현식 인덱스를 만든다. (2) 선행 와일드카드 LIKE — pg_trgm GIN 인덱스나 전문 검색으로 대체한다. (3) SELECT * — 필요한 컬럼만 명시한다. 디스트랙터: created_at 인덱스는 DESC 정렬을 역방향 스캔으로 처리할 수 있어 ORDER BY 자체는 문제가 아니다. 날짜 리터럴 문자열은 DBMS가 date/timestamp로 암묵 변환하므로 정상 비교된다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- V21__add_user_country.sql  (users 테이블에 이미 5천만 행 존재)\nALTER TABLE users ADD COLUMN country VARCHAR(2) NOT NULL;\nALTER TABLE users ADD COLUMN phone VARCHAR(20);\nUPDATE users SET country = 'KR';\nCREATE INDEX idx_users_country ON users(country);","items":[{"txt":"기존 행이 있는 테이블에 DEFAULT 없이 NOT NULL 컬럼을 추가하면 기존 행을 채울 값이 없어 마이그레이션 자체가 실패한다. DEFAULT를 주거나 nullable로 추가 후 백필하고 NOT NULL을 거는 단계로 나눠야 한다.","bad":true},{"txt":"5천만 행을 WHERE 없이 한 문장으로 UPDATE해 테이블 전체에 장시간 락과 대량 WAL이 발생하고 복제 지연을 유발한다. 기본키 범위로 나눠 배치 처리해야 한다.","bad":true},{"txt":"CREATE INDEX를 CONCURRENTLY 없이 실행해 인덱스 생성이 끝날 때까지 해당 테이블의 쓰기가 차단된다.","bad":true},{"txt":"phone 컬럼을 NULL 허용으로 추가한 것 역시 기존 행 때문에 실패한다.","bad":false},{"txt":"VARCHAR에 길이를 지정한 것이 결함이며 TEXT를 써야 한다.","bad":false}],"ex":"실제 결함 3가지. (1) DEFAULT 없는 NOT NULL 추가: ADD COLUMN country VARCHAR(2)로 먼저 추가 → 배치 백필 → SET NOT NULL 순서로 나눈다(또는 DEFAULT 'KR' NOT NULL). (2) 대량 UPDATE 한 방: WHERE id BETWEEN ... 형태로 수만 행씩 커밋하며 진행한다. (3) 락을 잡는 인덱스 생성: PostgreSQL이라면 CREATE INDEX CONCURRENTLY를 트랜잭션 밖에서 실행한다. 디스트랙터: nullable 컬럼 추가는 기존 행에 NULL이 들어가면 되므로 정상 동작하며, 최신 버전에서는 메타데이터만 바꾸는 즉시 작업이다. VARCHAR 길이 지정은 스타일·도메인 선택 문제다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- 애플리케이션이 순서대로 실행하는 계좌 이체\nUPDATE accounts SET balance = balance - 1000 WHERE id = 1;\nUPDATE accounts SET balance = balance + 1000 WHERE id = 2;\nINSERT INTO transfers (from_id, to_id, amount) VALUES (1, 2, 1000);","items":[{"txt":"BEGIN/COMMIT으로 묶여 있지 않아 각 문이 개별 커밋된다. 중간에 실패하면 출금만 되고 입금이나 이력 기록이 누락되는 정합성 붕괴가 발생한다.","bad":true},{"txt":"출금 UPDATE에 잔액 확인 조건(WHERE balance &gt;= 1000)이 없어 잔액이 부족해도 그대로 차감되어 음수 잔액이 만들어진다.","bad":true},{"txt":"balance = balance - 1000처럼 컬럼을 자기 자신으로 갱신하면 읽기와 쓰기 사이에 경쟁 조건이 생긴다.","bad":false},{"txt":"WHERE id = 1처럼 기본키 등치 조건을 쓰면 인덱스를 타지 못해 전체 스캔이 된다.","bad":false},{"txt":"두 계좌를 서로 다른 문장으로 갱신했기 때문에 반드시 데드락이 발생한다.","bad":false}],"ex":"실제 결함 2가지. (1) 트랜잭션 경계 부재: BEGIN; ... COMMIT; 으로 세 문장을 원자적으로 묶고, 실패 시 ROLLBACK한다. (2) 잔액 검증 부재: UPDATE accounts SET balance = balance - 1000 WHERE id = 1 AND balance &gt;= 1000 로 조건을 걸고 영향 행 수가 0이면 이체를 중단한다. 디스트랙터: balance = balance - 1000은 DB가 행 잠금 하에 원자적으로 수행하므로 오히려 애플리케이션에서 읽고 계산해 쓰는 방식보다 안전하다. 기본키 등치 조건은 인덱스를 가장 잘 활용하는 형태다. 계좌 갱신 순서를 일관되게 유지하면 데드락은 회피할 수 있으며 '반드시' 발생하지는 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- 매일 새벽 실행되는 정리 배치 (event_logs 약 8억 행)\nBEGIN;\nDELETE FROM event_logs WHERE created_at &lt; NOW() - INTERVAL '90 days';\nUPDATE users SET last_cleaned_at = NOW();\nCOMMIT;","items":[{"txt":"수억 행을 한 문장으로 DELETE해 장시간 락과 거대한 WAL/언두를 만들고, 복제 지연과 디스크 폭증을 유발한다. 기본키 범위로 나눈 배치 삭제나 파티션 DROP으로 대체해야 한다.","bad":true},{"txt":"UPDATE users에 WHERE 절이 전혀 없어 전체 사용자 행이 갱신된다. 정리 배치와 무관한 사용자까지 모두 건드리는 명백한 범위 오류다.","bad":true},{"txt":"두 대량 DML을 하나의 트랜잭션으로 묶어 커밋까지 락과 스냅샷이 유지되므로 다른 세션의 대기와 테이블 비대화(bloat)가 심해진다.","bad":true},{"txt":"NOW()는 각 문장마다 다시 평가되어 두 문장이 서로 다른 시각을 보게 되므로 일관성이 깨진다.","bad":false},{"txt":"INTERVAL '90 days'는 표준 문법이 아니어서 구문 오류가 난다.","bad":false}],"ex":"실제 결함 3가지. (1) 대량 DELETE 한 방: DELETE ... WHERE id IN (SELECT id ... LIMIT 10000) 를 반복하며 중간중간 커밋하거나, 날짜 파티션을 DROP한다. (2) WHERE 없는 UPDATE: 정리 대상 사용자에 한정하는 조건을 반드시 넣는다(배치 메타 테이블에 1행으로 기록하는 편이 낫다). (3) 하나의 긴 트랜잭션: 작업을 분할하고 각 배치를 짧게 커밋한다. 디스트랙터: NOW()는 트랜잭션 시작 시각을 반환해 같은 트랜잭션 안에서는 동일하다. INTERVAL '90 days'는 PostgreSQL에서 유효한 문법이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"CREATE TABLE payments (\n  id SERIAL PRIMARY KEY,\n  order_id INTEGER,\n  amount VARCHAR(20),\n  currency VARCHAR(3),\n  paid_at VARCHAR(30),\n  idempotency_key VARCHAR(64)\n);","items":[{"txt":"order_id에 외래키 제약이 없어 존재하지 않는 주문을 참조하는 고아 결제 행이 만들어질 수 있고, 주문 삭제 시 정합성도 보장되지 않는다.","bad":true},{"txt":"금액을 VARCHAR로 저장해 산술 연산·비교·집계가 불가능하거나 문자열 정렬로 잘못 동작한다. NUMERIC(정확한 십진 타입)을 써야 한다.","bad":true},{"txt":"paid_at을 문자열로 저장해 시간대 정보가 사라지고 날짜 함수·범위 검색·인덱스 활용이 어렵다. TIMESTAMPTZ를 써야 한다.","bad":true},{"txt":"idempotency_key에 UNIQUE 제약이 없어 재시도 요청이 중복 결제로 이어지는 것을 DB 수준에서 막지 못한다.","bad":true},{"txt":"SERIAL 대신 UUID를 쓰지 않은 것이 결함이다.","bad":false},{"txt":"currency를 VARCHAR(3)으로 선언해 ISO 4217 통화 코드를 담을 수 없다.","bad":false}],"ex":"실제 결함 4가지. (1) FK 누락: order_id INTEGER NOT NULL REFERENCES orders(id). (2) 금액 문자열 저장: amount NUMERIC(18,2) NOT NULL(또는 최소 단위 정수 BIGINT). (3) 시각 문자열 저장: paid_at TIMESTAMPTZ NOT NULL. (4) 유니크 제약 누락: idempotency_key에 UNIQUE를 걸어 중복 결제를 DB가 거부하게 한다. 디스트랙터: SERIAL 기본키는 이 스키마에서 충분히 적합하며 UUID는 요구사항에 따른 선택이다. ISO 4217 통화 코드는 정확히 3자이므로 VARCHAR(3)이 알맞다."}],"th":{"sum":"SQL 리뷰는 **인덱스를 타는가 · 잠그는 범위 · 되돌릴 수 있는가**를 본다.","body":[{"h":"인덱스를 못 타는 순간","t":"컬럼을 함수로 감싸거나(`DATE(created_at) = ...`) 앞에 와일드카드를 붙이면(`LIKE '%foo'`) 인덱스를 못 쓰고 풀스캔이 된다. 범위 조건으로 바꿔 쓰면 인덱스를 탄다. `SELECT *`는 필요 없는 컬럼과 민감 정보까지 끌고 오고 커버링 인덱스도 무력화한다."},{"h":"운영을 멈추는 변경","t":"한 문장으로 수백만 행을 UPDATE/DELETE하면 락이 오래 잡히고 복제 지연이 발생한다 — 배치로 쪼갠다. 값이 있는 테이블에 기본값 없이 NOT NULL 컬럼을 추가하는 마이그레이션은 실패하거나 테이블을 오래 잠근다. 큰 OFFSET 페이지네이션은 앞의 행을 전부 읽고 버린다."}],"code":{"c":"-- 결함: 함수로 감싸 인덱스를 못 탐 + SELECT *\nSELECT * FROM orders\nWHERE DATE(created_at) = '2026-01-01';\n\n-- 수정: 범위 조건 + 필요한 컬럼만\nSELECT id, user_id, total\nFROM orders\nWHERE created_at >= '2026-01-01'\n  AND created_at <  '2026-01-02';","cap":"조건을 '컬럼 그대로' 두어야 인덱스를 탄다."},"key":["함수로 감싼 컬럼·선행 와일드카드는 인덱스를 못 탄다","SELECT * 대신 필요한 컬럼만","대량 UPDATE/DELETE는 배치로 쪼갠다","기본값 없는 NOT NULL 추가는 위험한 마이그레이션","큰 OFFSET은 앞 행을 전부 읽고 버린다"]}},{"t":"코드 리뷰 II","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- articles(id, title, body, author_id, created_at, deleted_at)\nSELECT *\nFROM articles\nWHERE deleted_at IS NULL\nORDER BY created_at DESC\nLIMIT 20 OFFSET 200000;","items":[{"txt":"OFFSET 200000은 DB가 버릴 20만 행을 모두 읽고 정렬한 뒤 버리게 만들어, 뒤쪽 페이지일수록 급격히 느려진다. 마지막 행 값을 커서로 쓰는 키셋 페이지네이션으로 바꿔야 한다.","bad":true},{"txt":"SELECT * 로 body 같은 큰 컬럼까지 매 페이지 전송해 불필요한 I/O와 네트워크 비용이 발생한다.","bad":true},{"txt":"정렬 키 created_at이 유일하지 않아 동일 시각 행들의 순서가 실행마다 달라질 수 있고, 페이지 경계에서 행이 중복되거나 누락된다. id 같은 타이브레이커를 추가해야 한다.","bad":true},{"txt":"소프트 삭제 필터(deleted_at IS NULL)가 빠져 있어 삭제된 글까지 조회된다.","bad":false},{"txt":"LIMIT 20은 너무 작아 왕복이 늘어나므로 결함이다.","bad":false}],"ex":"실제 결함 3가지. (1) 대량 OFFSET: WHERE (created_at, id) &lt; (:last_created_at, :last_id) ORDER BY created_at DESC, id DESC LIMIT 20 형태로 바꾸면 인덱스 시작점을 바로 잡을 수 있다. (2) SELECT *: 목록 화면에 필요한 컬럼만 조회한다. (3) 불안정 정렬: ORDER BY created_at DESC, id DESC 로 결정적 순서를 만든다. 디스트랙터: deleted_at IS NULL 필터는 이미 포함되어 있다. 페이지 크기 20은 목록 화면의 일반적인 값으로 결함이 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- users(id, email, deleted_at), orders(id, user_id, status, deleted_at)\nSELECT u.id, u.email, COUNT(o.id) AS order_count\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nGROUP BY u.id, u.email\nORDER BY order_count DESC;","items":[{"txt":"users의 소프트 삭제 필터(u.deleted_at IS NULL)가 빠져 탈퇴·삭제된 사용자까지 집계 결과에 포함된다.","bad":true},{"txt":"orders의 소프트 삭제 필터도 빠져 삭제된 주문이 주문 수에 계산된다. LEFT JOIN이므로 WHERE가 아니라 ON 절에 o.deleted_at IS NULL을 넣어야 주문이 없는 사용자가 사라지지 않는다.","bad":true},{"txt":"LIMIT이 없어 전체 사용자 수만큼의 행을 정렬해 반환하므로, 사용자가 많아지면 메모리와 전송량이 폭증한다.","bad":true},{"txt":"LEFT JOIN에서는 COUNT(o.id) 대신 COUNT(*)를 써야 정확한 주문 수가 나온다.","bad":false},{"txt":"GROUP BY에 u.email을 포함한 것은 불필요하며 오류를 유발한다.","bad":false}],"ex":"실제 결함 3가지. (1)(2) 소프트 삭제 필터 누락: WHERE u.deleted_at IS NULL 과 LEFT JOIN orders o ON o.user_id = u.id AND o.deleted_at IS NULL 로 각각 처리한다. 조인 대상 필터를 WHERE에 넣으면 LEFT JOIN이 사실상 INNER JOIN이 되어 주문 없는 사용자가 결과에서 빠지는 점이 핵심이다. (3) LIMIT 부재: 상위 N명만 필요하다면 LIMIT을 붙이고, 전체가 필요하면 페이지네이션이나 사전 집계 테이블을 쓴다. 디스트랙터: LEFT JOIN에서 COUNT(*)는 매칭이 없는 행도 1로 세므로 주문 없는 사용자가 1건으로 잘못 계산된다 — COUNT(o.id)가 올바른 선택이다. 표준 SQL에서는 SELECT에 나온 비집계 컬럼을 GROUP BY에 모두 포함해야 하므로 u.email 포함이 정상이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- orders.created_at 은 TIMESTAMP WITHOUT TIME ZONE 이며 UTC 기준으로 저장됨\n-- 요구사항: 한국 시간(KST) 기준 일자별 주문 건수, 2024-05-01 ~ 2024-05-31\nSELECT DATE(created_at) AS day, COUNT(*) AS cnt\nFROM orders\nWHERE created_at &gt;= '2024-05-01'\n  AND created_at &lt;= '2024-05-31'\nGROUP BY DATE(created_at)\nORDER BY day;","items":[{"txt":"UTC로 저장된 값을 시간대 변환 없이 그대로 날짜로 잘라 KST 기준 하루 경계가 9시간 어긋난다. (created_at AT TIME ZONE 'UTC' AT TIME ZONE 'Asia/Seoul') 로 변환한 뒤 집계해야 한다.","bad":true},{"txt":"created_at &lt;= '2024-05-31'은 5월 31일 00:00:00까지만 포함해 마지막 하루의 대부분이 누락된다. created_at &gt;= start AND created_at &lt; start + INTERVAL '1 month' 같은 반열린 구간을 써야 한다.","bad":true},{"txt":"WHERE 절에서 created_at을 함수로 감싸고 있어 인덱스를 사용할 수 없다.","bad":false},{"txt":"SELECT * 를 사용해 불필요한 컬럼까지 읽는다.","bad":false},{"txt":"COUNT(*) 대신 COUNT(id)를 쓰지 않아 NULL 행이 누락된다.","bad":false}],"ex":"실제 결함 2가지. (1) 시간대 미고려: KST 기준 집계라면 DATE(created_at AT TIME ZONE 'UTC' AT TIME ZONE 'Asia/Seoul') 처럼 명시적으로 변환하고, 근본적으로는 컬럼을 TIMESTAMPTZ로 두는 편이 낫다. (2) 경계 조건: BETWEEN이나 &lt;= 로 날짜 끝을 잡으면 그날의 00:00 이후 데이터가 통째로 빠진다 — 반열린 구간 [시작, 끝)을 쓴다. 디스트랙터: WHERE 절의 created_at은 함수로 감싸지 않아 인덱스를 정상적으로 사용할 수 있다(GROUP BY의 DATE()는 인덱스 사용 여부와 무관하다). 이 쿼리는 SELECT *를 쓰지 않는다. COUNT(*)는 행 수를 세는 것이 목적이므로 정확하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- V33__rename_and_index.sql  (무중단 배포 중, orders 약 2억 행)\nBEGIN;\nALTER TABLE orders RENAME COLUMN amount TO total_amount;\nALTER TABLE orders ALTER COLUMN status TYPE VARCHAR(50);\nCREATE INDEX idx_orders_status ON orders(status);\nCOMMIT;","items":[{"txt":"컬럼을 곧바로 RENAME하면 아직 amount를 참조하는 구버전 애플리케이션 인스턴스가 즉시 오류를 낸다. 새 컬럼 추가 → 이중 쓰기 → 백필 → 읽기 전환 → 옛 컬럼 제거의 확장·축소(expand/contract) 단계로 나눠야 한다.","bad":true},{"txt":"ALTER COLUMN ... TYPE은 2억 행 테이블 전체를 재작성하면서 ACCESS EXCLUSIVE 락을 잡아 배포 시간 내내 읽기·쓰기가 모두 차단된다.","bad":true},{"txt":"대형 테이블에 CONCURRENTLY 없이 인덱스를 만들어 생성 내내 쓰기가 막힌다. 게다가 CREATE INDEX CONCURRENTLY는 트랜잭션 블록 안에서 실행할 수 없어, 이 마이그레이션 구조 자체를 나눠야 한다.","bad":true},{"txt":"DDL을 BEGIN/COMMIT으로 감싼 것은 PostgreSQL에서 무의미하므로 제거해야 한다.","bad":false},{"txt":"인덱스 이름에 idx_ 접두사를 쓴 것이 명명 규칙 위반이다.","bad":false}],"ex":"실제 결함 3가지. (1) 즉시 RENAME: 무중단 배포에서는 구·신 버전이 동시에 떠 있으므로 확장·축소 패턴으로 여러 릴리스에 나눠 적용한다. (2) 대형 테이블 타입 변경: 새 컬럼 추가 후 배치 백필하고 전환하거나, 최소한 락 시간이 짧은 방식(제약 검증 분리 등)을 쓴다. (3) 락을 잡는 인덱스 생성: CREATE INDEX CONCURRENTLY를 트랜잭션 밖에서 별도 마이그레이션으로 실행한다. 디스트랙터: PostgreSQL은 DDL도 트랜잭션 처리되므로 BEGIN/COMMIT으로 감싸는 것은 실패 시 원자적 롤백을 보장하는 유효한 관행이다(다만 CONCURRENTLY는 예외). 인덱스 이름 접두사는 팀 컨벤션 문제다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"CREATE OR REPLACE FUNCTION search_users(p_name TEXT)\nRETURNS SETOF users AS $$\nBEGIN\n  RETURN QUERY EXECUTE\n    'SELECT * FROM users WHERE name LIKE ''%' || p_name || '%''';\nEND;\n$$ LANGUAGE plpgsql;","items":[{"txt":"동적 SQL을 문자열 연결로 만들어 p_name에 따옴표를 섞으면 임의 SQL을 실행할 수 있는 인젝션 취약점이 된다. format(...%L...)이나 EXECUTE ... USING 파라미터를 써야 한다.","bad":true},{"txt":"LIKE 패턴 앞에 와일드카드가 붙어 name 인덱스를 전혀 사용할 수 없고 항상 전체 스캔이 된다.","bad":true},{"txt":"SELECT * 와 RETURNS SETOF users로 테이블 전체 컬럼을 그대로 반환해 비밀번호 해시 같은 민감 컬럼까지 노출되고, 컬럼 추가/변경 시 함수 계약이 조용히 바뀐다.","bad":true},{"txt":"$$ 달러 인용 부호로 함수 본문을 감싼 것이 결함이며 작은따옴표로 바꿔야 한다.","bad":false},{"txt":"LANGUAGE plpgsql 대신 LANGUAGE sql을 써야만 RETURN QUERY가 동작한다.","bad":false}],"ex":"실제 결함 3가지. (1) 동적 SQL 인젝션: RETURN QUERY EXECUTE format('SELECT ... WHERE name LIKE %L', '%' || p_name || '%'); 또는 애초에 동적 SQL 없이 RETURN QUERY SELECT ... WHERE name LIKE '%' || p_name || '%'; 로 작성한다. (2) 선행 와일드카드: pg_trgm GIN 인덱스를 만들거나 전문 검색으로 대체한다. (3) 전체 컬럼 반환: RETURNS TABLE(id BIGINT, name TEXT) 처럼 필요한 컬럼만 명시한다. 디스트랙터: 달러 인용은 함수 본문 작성의 표준 방식으로, 오히려 따옴표 이스케이프 문제를 줄여준다. RETURN QUERY는 plpgsql의 구문이므로 LANGUAGE plpgsql이 올바르다."}],"th":{"sum":"SQL 리뷰는 **인덱스를 타는가 · 잠그는 범위 · 되돌릴 수 있는가**를 본다.","body":[{"h":"인덱스를 못 타는 순간","t":"컬럼을 함수로 감싸거나(`DATE(created_at) = ...`) 앞에 와일드카드를 붙이면(`LIKE '%foo'`) 인덱스를 못 쓰고 풀스캔이 된다. 범위 조건으로 바꿔 쓰면 인덱스를 탄다. `SELECT *`는 필요 없는 컬럼과 민감 정보까지 끌고 오고 커버링 인덱스도 무력화한다."},{"h":"운영을 멈추는 변경","t":"한 문장으로 수백만 행을 UPDATE/DELETE하면 락이 오래 잡히고 복제 지연이 발생한다 — 배치로 쪼갠다. 값이 있는 테이블에 기본값 없이 NOT NULL 컬럼을 추가하는 마이그레이션은 실패하거나 테이블을 오래 잠근다. 큰 OFFSET 페이지네이션은 앞의 행을 전부 읽고 버린다."}],"code":{"c":"-- 결함: 함수로 감싸 인덱스를 못 탐 + SELECT *\nSELECT * FROM orders\nWHERE DATE(created_at) = '2026-01-01';\n\n-- 수정: 범위 조건 + 필요한 컬럼만\nSELECT id, user_id, total\nFROM orders\nWHERE created_at >= '2026-01-01'\n  AND created_at <  '2026-01-02';","cap":"조건을 '컬럼 그대로' 두어야 인덱스를 탄다."},"key":["함수로 감싼 컬럼·선행 와일드카드는 인덱스를 못 탄다","SELECT * 대신 필요한 컬럼만","대량 UPDATE/DELETE는 배치로 쪼갠다","기본값 없는 NOT NULL 추가는 위험한 마이그레이션","큰 OFFSET은 앞 행을 전부 읽고 버린다"]}},{"t":"코드 리뷰 III","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"CREATE TABLE sessions (\n  id BIGSERIAL PRIMARY KEY,\n  user_id BIGINT NOT NULL,\n  token VARCHAR(128) NOT NULL,\n  expires_at TIMESTAMP NOT NULL,\n  created_at TIMESTAMP DEFAULT NOW()\n);\nCREATE INDEX idx_sessions_token ON sessions(token);\n\n-- 인증 시 실행되는 쿼리\nSELECT * FROM sessions WHERE token = $1 AND expires_at &gt; NOW();","items":[{"txt":"token에 UNIQUE 제약이 없어 동일 토큰 행이 중복 생성될 수 있고, 인증 쿼리가 여러 행을 반환하는 상황을 DB가 막아주지 못한다.","bad":true},{"txt":"user_id에 외래키 제약이 없어 존재하지 않는 사용자의 세션이 남을 수 있고, 사용자 삭제 시 세션이 함께 정리되지 않는다.","bad":true},{"txt":"expires_at과 created_at을 TIMESTAMP(시간대 없음)로 선언해 NOW()와 비교할 때 서버 시간대 설정에 따라 만료 판정이 달라진다. TIMESTAMPTZ를 써야 한다.","bad":true},{"txt":"인증 경로에서 SELECT * 로 모든 컬럼을 읽어 필요 없는 데이터까지 매 요청 전송한다.","bad":true},{"txt":"idx_sessions_token 인덱스가 있어도 token = $1 같은 파라미터 비교는 인덱스를 사용하지 못한다.","bad":false},{"txt":"BIGSERIAL PRIMARY KEY는 인덱스를 자동 생성하지 않으므로 별도 인덱스를 만들어야 한다.","bad":false}],"ex":"실제 결함 4가지. (1) UNIQUE 누락: token VARCHAR(128) NOT NULL UNIQUE로 선언하면 별도 인덱스도 필요 없다. (2) FK 누락: user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE. (3) 시간대 미고려: TIMESTAMPTZ로 선언해야 세션 만료가 서버 설정과 무관하게 일관된다. (4) SELECT *: 인증에 필요한 user_id, expires_at 정도만 조회한다. 디스트랙터: 바인딩 파라미터의 등치 비교는 인덱스를 가장 잘 활용하는 형태다. PRIMARY KEY 선언은 유니크 인덱스를 자동으로 생성한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"CREATE TABLE counters (\n  id SERIAL PRIMARY KEY,\n  name VARCHAR(50),\n  value INT DEFAULT 0\n);\n\n-- 애플리케이션이 실행하는 순서\nSELECT id FROM counters WHERE name = 'signup';\n-- 위 결과가 비어 있으면\nINSERT INTO counters (name, value) VALUES ('signup', 1);\n-- 위 결과가 있으면\nUPDATE counters SET value = value + 1 WHERE name = 'signup';","items":[{"txt":"존재 여부를 SELECT로 확인한 뒤 INSERT하는 체크 후 사용 패턴이라, 두 요청이 동시에 들어오면 둘 다 '없음'을 보고 중복 행을 만든다. INSERT ... ON CONFLICT DO UPDATE 같은 원자적 UPSERT를 써야 한다.","bad":true},{"txt":"name에 UNIQUE 제약이 없어 중복 카운터 행을 DB가 거부하지 못하고, ON CONFLICT를 쓸 근거(충돌 대상)도 없다.","bad":true},{"txt":"세 문장이 하나의 트랜잭션으로 묶여 있지 않아, 중간 실패 시 조회 결과와 실제 상태가 어긋난 채로 남는다.","bad":true},{"txt":"조회·갱신 조건으로 쓰이는 name에 인덱스가 없어 카운터가 늘어날수록 매 요청이 전체 스캔을 한다.","bad":true},{"txt":"UPDATE counters SET value = value + 1 단일 문장은 원자적이지 않아 동시 실행 시 증가분이 유실된다.","bad":false},{"txt":"value INT DEFAULT 0인데 INSERT에서 value를 명시적으로 1로 지정한 것이 결함이다.","bad":false}],"ex":"실제 결함 4가지. (1) TOCTOU: INSERT INTO counters (name, value) VALUES ('signup', 1) ON CONFLICT (name) DO UPDATE SET value = counters.value + 1; 한 문장으로 대체한다. (2)(4) name에 UNIQUE 제약을 걸면 중복도 막고 인덱스도 함께 생겨 조회 성능 문제도 해결된다. (3) 트랜잭션 경계: 원자적 UPSERT로 바꾸면 여러 문장을 묶을 필요 자체가 사라진다. 디스트랙터: 단일 UPDATE 문의 value = value + 1은 DB가 행 잠금 하에 원자적으로 처리하므로 증가분이 유실되지 않는다. DEFAULT가 있는 컬럼에 값을 명시적으로 넣는 것은 정상이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- user_profiles 약 6천만 행, nickname 컬럼에는 UNIQUE 제약이 걸려 있음\nUPDATE user_profiles\nSET nickname = LOWER(TRIM(nickname))\nWHERE nickname &lt;&gt; LOWER(TRIM(nickname));","items":[{"txt":"6천만 행 테이블을 한 문장으로 UPDATE해 수백만 행이 한 트랜잭션에서 갱신되면 락 유지 시간이 길어지고 WAL 폭증과 복제 지연이 발생한다. 기본키 범위로 나눠 배치 커밋해야 한다.","bad":true},{"txt":"WHERE 조건이 nickname을 LOWER/TRIM 함수로 감싸고 있어 인덱스를 사용할 수 없고 전체 스캔이 강제된다.","bad":true},{"txt":"nickname에 UNIQUE 제약이 있으므로 'Kim'과 'kim'처럼 정규화 후 값이 겹치는 행이 존재하면 제약 위반으로 UPDATE 전체가 롤백된다. 충돌 행을 먼저 찾아 처리하는 계획이 없다.","bad":true},{"txt":"nickname이 NULL인 행은 &lt;&gt; 비교가 참이 되지 않아 갱신되지 않으므로 데이터가 누락된다.","bad":false},{"txt":"SET 절에서 LOWER(TRIM(...))처럼 함수를 중첩 호출한 것은 구문 오류다.","bad":false}],"ex":"실제 결함 3가지. (1) 대량 UPDATE 한 방: WHERE id BETWEEN :from AND :to 로 수만 행씩 나눠 커밋한다. (2) 함수로 감싼 WHERE 조건: 배치 분할 시 기본키 범위로 스캔하도록 하거나 LOWER(TRIM(nickname)) 표현식 인덱스를 만든다. (3) 유니크 충돌: 사전에 SELECT LOWER(TRIM(nickname)) FROM user_profiles GROUP BY 1 HAVING COUNT(*) &gt; 1 로 충돌 후보를 뽑아 개별 처리 정책(접미사 부여 등)을 정한 뒤 진행한다. 디스트랙터: NULL 닉네임은 정규화할 내용이 없으므로 대상에서 빠지는 것이 오히려 올바른 동작이다. 함수 중첩 호출은 정상적인 SQL이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- orders(id, customer_id, status VARCHAR(20), zipcode VARCHAR(10), total NUMERIC, deleted_at TIMESTAMP)\nSELECT o.id, c.name, o.total\nFROM orders o, customers c\nWHERE o.customer_id = c.id\n  AND o.status IN ('paid', 'shipped')\n  AND o.zipcode = 12345\nORDER BY o.total DESC;","items":[{"txt":"zipcode는 VARCHAR인데 숫자 리터럴 12345와 비교해 암묵적 형변환이 일어난다. 컬럼 쪽이 변환되면 zipcode 인덱스를 사용할 수 없고, '01234' 같은 값의 처리도 예측하기 어려워진다. '12345'로 비교해야 한다.","bad":true},{"txt":"소프트 삭제 필터 o.deleted_at IS NULL이 빠져 삭제된 주문까지 결과에 포함된다.","bad":true},{"txt":"LIMIT 없이 ORDER BY o.total DESC를 수행해 조건에 맞는 전체 행을 정렬하므로, 결과가 많으면 정렬 비용과 전송량이 커진다.","bad":true},{"txt":"조인 조건이 없어 orders와 customers의 카티전 곱이 만들어진다.","bad":false},{"txt":"ANSI JOIN 대신 콤마 조인을 쓰면 결과 집합이 달라지므로 반드시 JOIN 구문으로 바꿔야 한다.","bad":false},{"txt":"IN 절 대신 OR 조건으로 풀어써야 인덱스를 사용할 수 있다.","bad":false}],"ex":"실제 결함 3가지. (1) 암묵적 형변환: o.zipcode = '12345' 로 타입을 맞춰 인덱스를 살린다. (2) 소프트 삭제 필터 누락: AND o.deleted_at IS NULL 을 추가한다. (3) 무제한 정렬: 필요한 만큼 LIMIT을 걸거나 페이지네이션을 적용한다. 디스트랙터: WHERE o.customer_id = c.id 가 조인 조건 역할을 하므로 카티전 곱은 발생하지 않는다. 콤마 조인은 가독성이 떨어질 뿐 이 쿼리에서 ANSI INNER JOIN과 동일한 결과를 낸다. IN은 옵티마이저가 인덱스 조회 여러 번으로 잘 처리하며 OR로 푸는 것이 더 낫지 않다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"CREATE TABLE order_items (\n  id SERIAL PRIMARY KEY,\n  order_id INT REFERENCES orders(id),\n  sku VARCHAR(40) NOT NULL,\n  price DOUBLE PRECISION NOT NULL,\n  qty INT NOT NULL\n);\n\nCREATE VIEW order_totals AS\nSELECT order_id, SUM(price * qty) AS total\nFROM order_items\nGROUP BY order_id;","items":[{"txt":"금액을 DOUBLE PRECISION(이진 부동소수)으로 저장해 SUM 집계 시 반올림 오차가 누적되고, 같은 합계가 환경에 따라 미세하게 달라진다. NUMERIC(정확한 십진 타입)을 써야 한다.","bad":true},{"txt":"qty와 price에 CHECK 제약이 없어 0이나 음수 수량·금액이 저장될 수 있고, 뷰의 합계가 조용히 왜곡된다.","bad":true},{"txt":"PostgreSQL은 외래키 컬럼에 인덱스를 자동 생성하지 않는데 order_id에 인덱스가 없어, 뷰의 GROUP BY와 주문별 조회가 매번 전체 스캔한다.","bad":true},{"txt":"order_id에 외래키 제약이 없어 존재하지 않는 주문을 참조할 수 있다.","bad":false},{"txt":"GROUP BY order_id를 쓰면서 SELECT에 order_id를 포함한 것은 오류다.","bad":false},{"txt":"뷰에는 인덱스를 만들 수 없으므로 뷰를 사용하는 것 자체가 결함이다.","bad":false}],"ex":"실제 결함 3가지. (1) 부동소수 금액: price NUMERIC(12,2) NOT NULL 로 바꾼다. DOUBLE PRECISION은 화폐에 부적합하다. (2) 제약 누락: CHECK (qty &gt; 0), CHECK (price &gt;= 0)을 추가해 잘못된 값이 애초에 들어오지 못하게 한다. (3) FK 인덱스 부재: CREATE INDEX ON order_items(order_id) 를 만들어야 집계와 부모 삭제 검사 성능이 확보된다. 디스트랙터: order_id INT REFERENCES orders(id)에 이미 외래키가 선언되어 있다. GROUP BY 컬럼을 SELECT에 넣는 것은 정상이다. 뷰 자체에 인덱스를 만들 수 없는 것은 맞지만 기반 테이블 인덱스가 그대로 사용되므로 뷰 사용이 결함은 아니다."}],"th":{"sum":"SQL 리뷰는 **인덱스를 타는가 · 잠그는 범위 · 되돌릴 수 있는가**를 본다.","body":[{"h":"인덱스를 못 타는 순간","t":"컬럼을 함수로 감싸거나(`DATE(created_at) = ...`) 앞에 와일드카드를 붙이면(`LIKE '%foo'`) 인덱스를 못 쓰고 풀스캔이 된다. 범위 조건으로 바꿔 쓰면 인덱스를 탄다. `SELECT *`는 필요 없는 컬럼과 민감 정보까지 끌고 오고 커버링 인덱스도 무력화한다."},{"h":"운영을 멈추는 변경","t":"한 문장으로 수백만 행을 UPDATE/DELETE하면 락이 오래 잡히고 복제 지연이 발생한다 — 배치로 쪼갠다. 값이 있는 테이블에 기본값 없이 NOT NULL 컬럼을 추가하는 마이그레이션은 실패하거나 테이블을 오래 잠근다. 큰 OFFSET 페이지네이션은 앞의 행을 전부 읽고 버린다."}],"code":{"c":"-- 결함: 함수로 감싸 인덱스를 못 탐 + SELECT *\nSELECT * FROM orders\nWHERE DATE(created_at) = '2026-01-01';\n\n-- 수정: 범위 조건 + 필요한 컬럼만\nSELECT id, user_id, total\nFROM orders\nWHERE created_at >= '2026-01-01'\n  AND created_at <  '2026-01-02';","cap":"조건을 '컬럼 그대로' 두어야 인덱스를 탄다."},"key":["함수로 감싼 컬럼·선행 와일드카드는 인덱스를 못 탄다","SELECT * 대신 필요한 컬럼만","대량 UPDATE/DELETE는 배치로 쪼갠다","기본값 없는 NOT NULL 추가는 위험한 마이그레이션","큰 OFFSET은 앞 행을 전부 읽고 버린다"]}},{"t":"코드 리뷰 IV","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"-- V12__add_audit.sql\nCREATE TABLE audit_log (\n  id SERIAL PRIMARY KEY,\n  actor_email VARCHAR(255),\n  action TEXT,\n  payload TEXT,\n  created_at TIMESTAMP DEFAULT NOW()\n);\n\nINSERT INTO audit_log (actor_email, action, payload)\nSELECT email, 'migrated', row_to_json(u)::text FROM users u;\n\nGRANT ALL ON audit_log TO PUBLIC;","items":[{"txt":"PUBLIC에 ALL 권한을 부여해 데이터베이스에 접속 가능한 모든 롤이 감사 로그를 읽고 수정·삭제할 수 있다. 감사 테이블은 최소 권한으로 특정 롤에만, 그것도 대체로 INSERT/SELECT만 허용해야 한다.","bad":true},{"txt":"row_to_json(u)로 users 행 전체를 직렬화해 넣기 때문에 비밀번호 해시·전화번호 같은 민감 컬럼이 감사 테이블에 평문 텍스트로 복사된다. 필요한 컬럼만 선택해야 한다.","bad":true},{"txt":"마이그레이션에서 users 전체를 한 문장으로 audit_log에 복사해, 사용자 수만큼의 대량 INSERT가 배포 트랜잭션 안에서 실행되며 락과 배포 시간이 길어진다.","bad":true},{"txt":"created_at을 TIMESTAMP(시간대 없음)로 선언해 여러 시간대의 서버가 기록하면 감사 시각의 기준이 모호해진다. TIMESTAMPTZ를 써야 한다.","bad":true},{"txt":"SERIAL PRIMARY KEY는 감사 테이블에 부적합하므로 결함이다.","bad":false},{"txt":"마이그레이션 파일에 DDL과 INSERT를 함께 넣는 것은 구문 오류다.","bad":false}],"ex":"실제 결함 4가지. (1) GRANT ALL TO PUBLIC: REVOKE 후 GRANT INSERT, SELECT ON audit_log TO app_role 처럼 최소 권한만 준다. (2) 민감정보 복사: row_to_json 대신 감사에 필요한 필드만 명시적으로 뽑고, 저장 타입도 JSONB가 적합하다. (3) 배포 중 대량 백필: 초기 데이터 이관은 별도 배치로 분리해 나눠 커밋한다. (4) 시간대 미고려: created_at TIMESTAMPTZ DEFAULT NOW()로 선언한다. 디스트랙터: SERIAL 기본키는 감사 테이블에서 충분히 일반적인 선택이다. 마이그레이션 스크립트에 DDL과 DML을 함께 담는 것은 문법적으로 문제없다(운영상 분리가 바람직할 뿐이다)."}],"th":{"sum":"SQL 리뷰는 **인덱스를 타는가 · 잠그는 범위 · 되돌릴 수 있는가**를 본다.","body":[{"h":"인덱스를 못 타는 순간","t":"컬럼을 함수로 감싸거나(`DATE(created_at) = ...`) 앞에 와일드카드를 붙이면(`LIKE '%foo'`) 인덱스를 못 쓰고 풀스캔이 된다. 범위 조건으로 바꿔 쓰면 인덱스를 탄다. `SELECT *`는 필요 없는 컬럼과 민감 정보까지 끌고 오고 커버링 인덱스도 무력화한다."},{"h":"운영을 멈추는 변경","t":"한 문장으로 수백만 행을 UPDATE/DELETE하면 락이 오래 잡히고 복제 지연이 발생한다 — 배치로 쪼갠다. 값이 있는 테이블에 기본값 없이 NOT NULL 컬럼을 추가하는 마이그레이션은 실패하거나 테이블을 오래 잠근다. 큰 OFFSET 페이지네이션은 앞의 행을 전부 읽고 버린다."}],"code":{"c":"-- 결함: 함수로 감싸 인덱스를 못 탐 + SELECT *\nSELECT * FROM orders\nWHERE DATE(created_at) = '2026-01-01';\n\n-- 수정: 범위 조건 + 필요한 컬럼만\nSELECT id, user_id, total\nFROM orders\nWHERE created_at >= '2026-01-01'\n  AND created_at <  '2026-01-02';","cap":"조건을 '컬럼 그대로' 두어야 인덱스를 탄다."},"key":["함수로 감싼 컬럼·선행 와일드카드는 인덱스를 못 탄다","SELECT * 대신 필요한 컬럼만","대량 UPDATE/DELETE는 배치로 쪼갠다","기본값 없는 NOT NULL 추가는 위험한 마이그레이션","큰 OFFSET은 앞 행을 전부 읽고 버린다"]}}]},{"t":"로그 분석 — PostgreSQL","l":[{"t":"PostgreSQL 로그 I","q":[{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"특정 시각부터 모든 쓰기 쿼리가 실패합니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"02:00:00 LOG  checkpoint starting: time","bad":false},{"txt":"02:10:00 LOG  autovacuum: 정상 동작 중","bad":false},{"txt":"03:12:00 WARN  database \"app\" must be vacuumed within 10,000,000 transactions","bad":true},{"txt":"04:40:00 ERROR database is not accepting commands to avoid wraparound data loss","bad":false},{"txt":"04:40:01 ERROR INSERT INTO orders 실패 (read-only 상태)","bad":false},{"txt":"04:41:00 ERROR api: 500 전 쓰기 경로","bad":false},{"txt":"05:00:00 WARN  ops: 읽기 쿼리는 정상 동작","bad":false},{"txt":"05:30:00 ERROR ops: 단독 모드 VACUUM 필요","bad":false}],"ex":"03:12:00 트랜잭션 ID 소진 경고가 원인입니다. autovacuum 이 오래 실행되는 트랜잭션이나 설정 문제로 오래된 튜플을 정리하지 못한 상태입니다. 쓰기 거부·전 경로 500·읽기만 정상은 전부 그 결과입니다. 경고 단계에서 잡아야 하며, 넘어가면 단독 모드 VACUUM 으로 서비스를 세워야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"주문 처리 API 가 자주 실패한다는 보고가 있습니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"10:00:00 LOG  connection authorized: user=app","bad":false},{"txt":"10:20:00 LOG  duration: 12.402 ms statement: SELECT ...","bad":false},{"txt":"10:35:00 WARN  app: 주문 처리 시 orders → items 순, 재고 처리 시 items → orders 순으로 잠금","bad":true},{"txt":"10:36:00 LOG  process 4412 still waiting for ShareLock after 1000.145 ms","bad":false},{"txt":"10:36:01 ERROR deadlock detected","bad":false},{"txt":"10:36:01 ERROR DETAIL: Process 4412 waits for ShareLock on transaction 88213","bad":false},{"txt":"10:40:00 ERROR api: 500 POST /api/orders (x64)","bad":false},{"txt":"11:00:00 ERROR ops: 교착 발생 빈도 시간당 40회","bad":false}],"ex":"10:35:00 코드 경로에 따라 테이블 잠금 순서가 다른 것이 원인입니다. 두 트랜잭션이 서로의 락을 기다리면 교착이 됩니다. still waiting·deadlock detected·500·빈발은 전부 그 결과입니다. 모든 경로에서 같은 순서로 잠그도록 규칙을 정해야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"배포 시 마이그레이션이 서비스를 멈춰 세웠습니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"01:00:00 LOG  migration 시작","bad":false},{"txt":"01:00:01 LOG  ALTER TABLE users ADD COLUMN nickname text","bad":false},{"txt":"01:00:02 WARN  migration: ALTER TABLE users ALTER COLUMN email TYPE varchar(500)","bad":true},{"txt":"01:00:03 LOG  process 8812 acquires AccessExclusiveLock on relation users","bad":false},{"txt":"01:02:00 LOG  1,204 queries waiting on relation users","bad":false},{"txt":"01:03:00 ERROR api: 요청 타임아웃 (x2,800)","bad":false},{"txt":"01:12:00 LOG  ALTER TABLE 완료 (11분 소요)","bad":false},{"txt":"01:15:00 ERROR ops: 다운타임 12분 기록","bad":false}],"ex":"01:00:02 컬럼 타입 변경이 원인입니다. 이 작업은 테이블 전체를 재작성하며 배타 락을 오래 잡습니다. 대기 쿼리 누적·요청 타임아웃·12분 다운타임은 전부 그 결과이고, 앞의 컬럼 추가는 즉시 끝나는 안전한 작업입니다. 새 컬럼 추가 → 이중 쓰기 → 백필 → 교체 순으로 나눠야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"리포트 쿼리 하나가 DB 전체를 느리게 만듭니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"09:00:00 LOG  duration: 8.1 ms SELECT ...","bad":false},{"txt":"09:20:00 LOG  autovacuum: 정상","bad":false},{"txt":"09:40:00 WARN  app: 리포트 트랜잭션을 열고 커밋하지 않은 채 유지 (idle in transaction 40분)","bad":true},{"txt":"10:20:00 WARN  autovacuum: 오래된 튜플 정리 불가 (최소 xmin 고정)","bad":false},{"txt":"11:00:00 WARN  table orders: dead tuples 4,200,000 (bloat 62%)","bad":false},{"txt":"11:30:00 ERROR api: 조회 p99 3800ms","bad":false},{"txt":"12:00:00 ERROR db: 디스크 사용량 급증","bad":false},{"txt":"12:30:00 ERROR ops: 인덱스 재구축 검토","bad":false}],"ex":"09:40:00 트랜잭션을 열어 둔 채 방치한 것이 원인입니다. 열린 트랜잭션이 정리 기준점을 붙잡아 VACUUM 이 아무것도 회수하지 못합니다. dead tuple 누적·블로트·조회 지연·디스크 급증은 전부 그 결과입니다. idle_in_transaction_session_timeout 을 설정하고 트랜잭션을 짧게 유지해야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"인덱스를 추가했는데 여전히 느립니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"13:00:00 LOG  CREATE INDEX idx_orders_created ON orders(created_at)","bad":false},{"txt":"13:05:00 LOG  인덱스 생성 완료","bad":false},{"txt":"13:20:00 WARN  app: WHERE date(created_at) = '2026-07-01' 형태로 조회 (컬럼에 함수 적용)","bad":true},{"txt":"13:25:00 LOG  Seq Scan on orders (cost=0.00..184203.00 rows=1)","bad":false},{"txt":"13:30:00 ERROR api: 조회 p99 4200ms","bad":false},{"txt":"13:40:00 ERROR db: CPU 88%","bad":false},{"txt":"14:00:00 WARN  ops: 인덱스는 존재하지만 사용되지 않음","bad":false},{"txt":"14:20:00 ERROR api: 타임아웃 증가","bad":false}],"ex":"13:20:00 인덱스 컬럼에 함수를 적용해 조회한 것이 원인입니다. 그러면 일반 B-tree 인덱스를 쓸 수 없습니다. Seq Scan·지연·CPU 상승·인덱스 미사용은 전부 그 결과입니다. 범위 조건(created_at >= ... AND < ...)으로 바꾸거나 표현식 인덱스를 만들어야 합니다."}],"th":{"sum":"데이터베이스 로그는 **락·잠금 순서 · 실행 계획 · 정리(VACUUM)** 세 갈래로 갈린다.","body":[{"h":"기다림의 정체를 찾는다","t":"교착은 잠금 순서가 경로마다 다를 때 생긴다. 배타 락을 오래 잡는 DDL(컬럼 타입 변경, 대량 DELETE)은 그 자체로 다운타임이다. 열어 둔 트랜잭션 하나가 VACUUM 을 막아 테이블을 부풀린다. 'idle in transaction' 은 항상 의심 대상이다."},{"h":"계획이 바뀌면 성능이 바뀐다","t":"쿼리와 인덱스가 그대로인데 갑자기 느려졌다면 통계를 본다. 컬럼에 함수·캐스팅을 적용하면 인덱스를 쓸 수 없고, 파티션 키에 캐스팅하면 프루닝이 깨진다. 외래 키 참조 컬럼에 인덱스가 없으면 부모 삭제가 자식 전체 스캔이 된다."},{"h":"쓰기 경로의 함정","t":"WAL 아카이브가 실패하면 디스크가 채워지고, synchronous_commit 을 끄면 커밋 후에도 유실될 수 있다. 트랜잭션 ID 소진 경고는 방치하면 DB 가 쓰기를 거부한다. 커밋하지 않고 커넥션을 반납하면 조용히 롤백된다."},{"h":"복제와 일관성","t":"대량 변경은 복제 지연을 만들고, 방금 쓴 데이터를 복제본에서 읽으면 없다. 복제본의 장시간 쿼리는 프라이머리의 VACUUM 과 충돌해 취소된다. 정렬에 유일 키가 없으면 페이지네이션에서 행이 중복·누락된다."}],"code":{"c":"-- 증상: 조회가 100배 느려졌다\nSeq Scan on orders (통계 기준 rows=1200, 실제 4,800,000)\n\n-- 원인은 그 앞\nWARN: orders 테이블에 대량 적재 후 ANALYZE 미실행\n\n-- 확인 순서\nEXPLAIN (ANALYZE, BUFFERS) SELECT ...;      -- 계획과 실제의 괴리\nSELECT * FROM pg_stat_activity WHERE state='idle in transaction';\nSELECT relname, n_dead_tup FROM pg_stat_user_tables ORDER BY 2 DESC;\nSELECT * FROM pg_locks WHERE NOT granted;","cap":"계획과 실제 행 수의 차이가 통계 문제를 가리킨다"},"key":["교착은 잠금 순서를 통일해 막는다. DDL 은 배타 락 시간을 먼저 확인한다","쿼리·인덱스가 그대로인데 느려졌으면 통계(ANALYZE)를 본다","컬럼에 함수·캐스팅을 씌우면 인덱스와 파티션 프루닝이 죽는다","idle in transaction 은 VACUUM 을 막아 블로트를 만든다","대량 변경은 배치로 쪼갠다 — 락·WAL·복제 지연이 함께 폭발한다","ORDER BY 에 유일 키가 없으면 페이지네이션이 흔들린다"]}},{"t":"PostgreSQL 로그 II","q":[{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"복제 지연이 계속 늘어납니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"15:00:00 LOG  streaming replication 정상 (lag 0.2s)","bad":false},{"txt":"15:10:00 LOG  standby: WAL 적용 중","bad":false},{"txt":"15:30:00 WARN  primary: 대량 UPDATE 실행 (1,200만 행)","bad":true},{"txt":"15:40:00 WARN  standby: replay lag 210s","bad":false},{"txt":"15:50:00 ERROR api(read-replica): 방금 저장한 데이터가 조회되지 않음","bad":false},{"txt":"16:00:00 ERROR api: 저장 후 목록 새로고침 시 누락","bad":false},{"txt":"16:20:00 ERROR support: 데이터 사라짐 문의","bad":false},{"txt":"16:40:00 WARN  standby: lag 480s","bad":false}],"ex":"15:30:00 한 번에 대량 UPDATE 를 실행한 것이 원인입니다. 생성된 WAL 을 스탠바이가 순차 적용하느라 지연이 누적됩니다. replay lag·읽기 복제본 데이터 누락·문의는 전부 그 결과입니다. 대량 변경은 배치로 쪼개고, 방금 쓴 데이터는 프라이머리에서 읽어야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"커넥션이 남아 있는데 새 연결이 거부됩니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"11:00:00 LOG  max_connections = 100","bad":false},{"txt":"11:10:00 LOG  현재 연결 42","bad":false},{"txt":"11:30:00 WARN  app: 커넥션 풀 없이 요청마다 새 연결 생성","bad":true},{"txt":"11:50:00 WARN  db: 연결 98 (대부분 idle)","bad":false},{"txt":"11:52:00 ERROR FATAL: sorry, too many clients already","bad":false},{"txt":"11:53:00 ERROR api: 500 전 경로 (x1,800)","bad":false},{"txt":"12:00:00 WARN  db: CPU 18% (한가함)","bad":false},{"txt":"12:20:00 ERROR ops: DB 재시작 검토","bad":false}],"ex":"11:30:00 커넥션 풀을 쓰지 않은 것이 원인입니다. 요청마다 연결을 새로 만들면 idle 연결이 상한을 채웁니다. idle 연결 누적·too many clients·전 경로 500 은 전부 그 결과이고, DB CPU 가 한가한 것이 단서입니다. 풀을 쓰거나 PgBouncer 를 두어야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"같은 쿼리가 갑자기 100배 느려졌습니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"08:00:00 LOG  duration: 14.2 ms SELECT ... WHERE user_id = $1","bad":false},{"txt":"08:20:00 LOG  Index Scan using idx_user 사용","bad":false},{"txt":"08:40:00 WARN  db: orders 테이블에 대량 적재 후 ANALYZE 미실행","bad":true},{"txt":"09:00:00 LOG  Seq Scan on orders (통계 기준 rows=1200, 실제 4,800,000)","bad":false},{"txt":"09:10:00 ERROR api: 조회 p99 2900ms","bad":false},{"txt":"09:20:00 ERROR db: 디스크 읽기 급증","bad":false},{"txt":"09:40:00 ERROR api: 타임아웃 증가","bad":false},{"txt":"10:00:00 WARN  ops: 쿼리·인덱스 변경 없음","bad":false}],"ex":"08:40:00 대량 적재 후 통계를 갱신하지 않은 것이 원인입니다. 플래너가 낡은 통계로 잘못된 실행 계획을 고릅니다. Seq Scan 전환·지연·디스크 읽기 급증은 전부 그 결과이고, 쿼리와 인덱스가 그대로인 것이 단서입니다. 적재 후 ANALYZE 를 실행하고 autovacuum 임계값을 조정해야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"트랜잭션이 간헐적으로 실패하며 재시도됩니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"17:00:00 LOG  SET default_transaction_isolation = 'repeatable read'","bad":false},{"txt":"17:10:00 LOG  트랜잭션 정상 커밋","bad":false},{"txt":"17:30:00 WARN  app: 동일 행을 여러 트랜잭션이 동시에 갱신 (재시도 로직 없음)","bad":true},{"txt":"17:35:00 ERROR ERROR: could not serialize access due to concurrent update","bad":false},{"txt":"17:35:01 ERROR api: 500 POST /api/wallet","bad":false},{"txt":"17:40:00 ERROR api: 실패율 2.1%","bad":false},{"txt":"18:00:00 ERROR support: 잔액 반영 실패 문의","bad":false},{"txt":"18:20:00 ERROR ops: 수동 재처리","bad":false}],"ex":"17:30:00 직렬화 실패가 정상적으로 발생하는 격리 수준인데 재시도 로직이 없는 것이 원인입니다. serialize 오류·500·실패율·수동 재처리는 전부 그 결과입니다. 이 격리 수준을 쓰면 애플리케이션이 직렬화 실패를 잡아 재시도해야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"디스크가 갑자기 가득 찼습니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"04:00:00 LOG  WAL 아카이빙 정상","bad":false},{"txt":"04:20:00 LOG  pg_wal 사용량 1.2GB","bad":false},{"txt":"04:40:00 WARN  archive_command failed: exit code 1 (스토리지 인증 만료)","bad":true},{"txt":"06:00:00 WARN  pg_wal 사용량 42GB","bad":false},{"txt":"07:00:00 ERROR PANIC: could not write to file \"pg_wal/...\": No space left on device","bad":false},{"txt":"07:00:05 ERROR database system is shut down","bad":false},{"txt":"07:01:00 ERROR api: 전면 장애","bad":false},{"txt":"07:30:00 ERROR ops: WAL 수동 정리 후 복구","bad":false}],"ex":"04:40:00 WAL 아카이브 명령이 실패한 것이 원인입니다. 아카이브가 성공하지 않으면 PostgreSQL 은 WAL 을 지우지 않고 계속 쌓습니다. 사용량 급증·PANIC·DB 종료·전면 장애는 전부 그 결과입니다. archive_command 실패 자체에 알람을 걸어야 합니다."}],"th":{"sum":"데이터베이스 로그는 **락·잠금 순서 · 실행 계획 · 정리(VACUUM)** 세 갈래로 갈린다.","body":[{"h":"기다림의 정체를 찾는다","t":"교착은 잠금 순서가 경로마다 다를 때 생긴다. 배타 락을 오래 잡는 DDL(컬럼 타입 변경, 대량 DELETE)은 그 자체로 다운타임이다. 열어 둔 트랜잭션 하나가 VACUUM 을 막아 테이블을 부풀린다. 'idle in transaction' 은 항상 의심 대상이다."},{"h":"계획이 바뀌면 성능이 바뀐다","t":"쿼리와 인덱스가 그대로인데 갑자기 느려졌다면 통계를 본다. 컬럼에 함수·캐스팅을 적용하면 인덱스를 쓸 수 없고, 파티션 키에 캐스팅하면 프루닝이 깨진다. 외래 키 참조 컬럼에 인덱스가 없으면 부모 삭제가 자식 전체 스캔이 된다."},{"h":"쓰기 경로의 함정","t":"WAL 아카이브가 실패하면 디스크가 채워지고, synchronous_commit 을 끄면 커밋 후에도 유실될 수 있다. 트랜잭션 ID 소진 경고는 방치하면 DB 가 쓰기를 거부한다. 커밋하지 않고 커넥션을 반납하면 조용히 롤백된다."},{"h":"복제와 일관성","t":"대량 변경은 복제 지연을 만들고, 방금 쓴 데이터를 복제본에서 읽으면 없다. 복제본의 장시간 쿼리는 프라이머리의 VACUUM 과 충돌해 취소된다. 정렬에 유일 키가 없으면 페이지네이션에서 행이 중복·누락된다."}],"code":{"c":"-- 증상: 조회가 100배 느려졌다\nSeq Scan on orders (통계 기준 rows=1200, 실제 4,800,000)\n\n-- 원인은 그 앞\nWARN: orders 테이블에 대량 적재 후 ANALYZE 미실행\n\n-- 확인 순서\nEXPLAIN (ANALYZE, BUFFERS) SELECT ...;      -- 계획과 실제의 괴리\nSELECT * FROM pg_stat_activity WHERE state='idle in transaction';\nSELECT relname, n_dead_tup FROM pg_stat_user_tables ORDER BY 2 DESC;\nSELECT * FROM pg_locks WHERE NOT granted;","cap":"계획과 실제 행 수의 차이가 통계 문제를 가리킨다"},"key":["교착은 잠금 순서를 통일해 막는다. DDL 은 배타 락 시간을 먼저 확인한다","쿼리·인덱스가 그대로인데 느려졌으면 통계(ANALYZE)를 본다","컬럼에 함수·캐스팅을 씌우면 인덱스와 파티션 프루닝이 죽는다","idle in transaction 은 VACUUM 을 막아 블로트를 만든다","대량 변경은 배치로 쪼갠다 — 락·WAL·복제 지연이 함께 폭발한다","ORDER BY 에 유일 키가 없으면 페이지네이션이 흔들린다"]}},{"t":"PostgreSQL 로그 III","q":[{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"삭제한 데이터가 여전히 조회됩니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"12:00:00 LOG  DELETE FROM sessions WHERE expired_at &lt; now()","bad":false},{"txt":"12:00:01 LOG  DELETE 42,000","bad":false},{"txt":"12:00:02 WARN  app: 트랜잭션 커밋 없이 커넥션 반납 (autocommit off)","bad":true},{"txt":"12:00:10 LOG  트랜잭션 롤백 (커넥션 종료)","bad":false},{"txt":"12:10:00 ERROR cleanup: 만료 세션 여전히 42,000건","bad":false},{"txt":"12:30:00 ERROR api: 만료 토큰으로 접근 성공","bad":false},{"txt":"13:00:00 ERROR security: 세션 만료 미적용 확인","bad":false},{"txt":"13:30:00 ERROR ops: 정리 배치 재작성","bad":false}],"ex":"12:00:02 커밋하지 않고 커넥션을 반납한 것이 원인입니다. 자동 커밋이 꺼진 상태에서는 커넥션이 닫히며 롤백됩니다. 롤백·세션 잔존·만료 토큰 접근은 전부 그 결과입니다. 명시적으로 커밋하고, 배치는 영향 행 수를 검증해야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"JSON 컬럼 조회가 매우 느립니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"14:20:00 LOG  events 테이블 1,200만 행","bad":false},{"txt":"14:30:00 LOG  payload jsonb 컬럼 사용","bad":false},{"txt":"14:40:00 WARN  app: WHERE payload-&gt;&gt;'user_id' = $1 조회, GIN 인덱스 없음","bad":true},{"txt":"14:50:00 LOG  Seq Scan on events (rows=12000000)","bad":false},{"txt":"15:00:00 ERROR api: 조회 p99 9200ms","bad":false},{"txt":"15:10:00 ERROR db: 디스크 읽기 포화","bad":false},{"txt":"15:30:00 ERROR api: 타임아웃","bad":false},{"txt":"16:00:00 ERROR db: 다른 쿼리도 지연","bad":false}],"ex":"14:40:00 JSON 내부 키로 조회하는데 인덱스가 없는 것이 원인입니다. 매번 1,200만 행을 전부 훑습니다. Seq Scan·지연·디스크 포화·다른 쿼리 지연은 전부 그 결과입니다. 표현식 인덱스나 GIN 인덱스를 만들거나, 자주 쓰는 키를 별도 컬럼으로 승격해야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"배치 삭제가 서비스를 멈춥니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"02:30:00 LOG  일별 정리 배치 시작","bad":false},{"txt":"02:30:01 LOG  대상 행 3,400만","bad":false},{"txt":"02:30:02 WARN  batch: 단일 DELETE 로 3,400만 행 삭제 시도","bad":true},{"txt":"02:35:00 LOG  lock wait: 다른 트랜잭션 620건 대기","bad":false},{"txt":"02:40:00 ERROR api: 요청 타임아웃 (x5,400)","bad":false},{"txt":"02:50:00 WARN  db: WAL 생성량 급증, 복제 지연 300s","bad":false},{"txt":"03:10:00 LOG  DELETE 완료 (40분)","bad":false},{"txt":"03:20:00 ERROR ops: 야간 다운타임 40분","bad":false}],"ex":"02:30:02 한 번에 대량 삭제를 시도한 것이 원인입니다. 긴 트랜잭션이 락과 WAL 을 폭발시킵니다. 락 대기·요청 타임아웃·복제 지연·40분 다운타임은 전부 그 결과입니다. LIMIT 을 걸어 배치로 쪼개거나 파티션을 DROP 하는 방식으로 바꿔야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"같은 조건인데 결과 개수가 매번 다릅니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"10:40:00 LOG  SELECT * FROM posts ORDER BY created_at LIMIT 20 OFFSET 0","bad":false},{"txt":"10:40:01 LOG  20행 반환","bad":false},{"txt":"10:45:00 WARN  app: created_at 에 동일 값 다수, ORDER BY 에 유일 키 없음","bad":true},{"txt":"10:50:00 LOG  OFFSET 20 조회 시 일부 행 중복","bad":false},{"txt":"10:51:00 ERROR api: 목록 2페이지에 1페이지 항목 재등장","bad":false},{"txt":"10:52:00 ERROR api: 일부 게시글 어느 페이지에도 안 나옴","bad":false},{"txt":"11:10:00 ERROR support: 글이 사라졌다는 문의","bad":false},{"txt":"11:40:00 ERROR ops: 페이지네이션 재설계 필요","bad":false}],"ex":"10:45:00 정렬 기준에 유일 키가 없는 것이 원인입니다. 동일 값 사이의 순서는 보장되지 않으므로 페이지마다 순서가 흔들립니다. 행 중복·누락·문의는 전부 그 결과입니다. ORDER BY created_at, id 처럼 유일 키를 덧붙이고 커서 기반 페이지네이션으로 바꿔야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"쿼리는 빠른데 API 응답이 느립니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"16:20:00 LOG  duration: 3.2 ms SELECT id FROM orders WHERE user_id=$1","bad":false},{"txt":"16:25:00 LOG  초당 쿼리 4,200건","bad":false},{"txt":"16:30:00 WARN  app: 목록 20건에 대해 상세를 개별 쿼리로 조회 (루프 안 쿼리)","bad":true},{"txt":"16:40:00 LOG  요청당 쿼리 수 평균 63","bad":false},{"txt":"16:50:00 ERROR api: p99 2100ms (쿼리 합 200ms, 왕복 지연 누적)","bad":false},{"txt":"17:00:00 ERROR db: 커넥션 사용률 상승","bad":false},{"txt":"17:20:00 ERROR api: 타임아웃 산발","bad":false},{"txt":"17:40:00 WARN  ops: 개별 쿼리는 모두 3ms 이하","bad":false}],"ex":"16:30:00 루프 안에서 쿼리를 던진 것이 원인입니다. 각 쿼리는 빠르지만 네트워크 왕복이 수십 번 누적됩니다. 요청당 쿼리 63회·p99 상승·커넥션 사용률·타임아웃은 전부 그 결과이고, 개별 쿼리가 다 빠른 것이 특징입니다. IN 절이나 조인으로 한 번에 가져와야 합니다."}],"th":{"sum":"데이터베이스 로그는 **락·잠금 순서 · 실행 계획 · 정리(VACUUM)** 세 갈래로 갈린다.","body":[{"h":"기다림의 정체를 찾는다","t":"교착은 잠금 순서가 경로마다 다를 때 생긴다. 배타 락을 오래 잡는 DDL(컬럼 타입 변경, 대량 DELETE)은 그 자체로 다운타임이다. 열어 둔 트랜잭션 하나가 VACUUM 을 막아 테이블을 부풀린다. 'idle in transaction' 은 항상 의심 대상이다."},{"h":"계획이 바뀌면 성능이 바뀐다","t":"쿼리와 인덱스가 그대로인데 갑자기 느려졌다면 통계를 본다. 컬럼에 함수·캐스팅을 적용하면 인덱스를 쓸 수 없고, 파티션 키에 캐스팅하면 프루닝이 깨진다. 외래 키 참조 컬럼에 인덱스가 없으면 부모 삭제가 자식 전체 스캔이 된다."},{"h":"쓰기 경로의 함정","t":"WAL 아카이브가 실패하면 디스크가 채워지고, synchronous_commit 을 끄면 커밋 후에도 유실될 수 있다. 트랜잭션 ID 소진 경고는 방치하면 DB 가 쓰기를 거부한다. 커밋하지 않고 커넥션을 반납하면 조용히 롤백된다."},{"h":"복제와 일관성","t":"대량 변경은 복제 지연을 만들고, 방금 쓴 데이터를 복제본에서 읽으면 없다. 복제본의 장시간 쿼리는 프라이머리의 VACUUM 과 충돌해 취소된다. 정렬에 유일 키가 없으면 페이지네이션에서 행이 중복·누락된다."}],"code":{"c":"-- 증상: 조회가 100배 느려졌다\nSeq Scan on orders (통계 기준 rows=1200, 실제 4,800,000)\n\n-- 원인은 그 앞\nWARN: orders 테이블에 대량 적재 후 ANALYZE 미실행\n\n-- 확인 순서\nEXPLAIN (ANALYZE, BUFFERS) SELECT ...;      -- 계획과 실제의 괴리\nSELECT * FROM pg_stat_activity WHERE state='idle in transaction';\nSELECT relname, n_dead_tup FROM pg_stat_user_tables ORDER BY 2 DESC;\nSELECT * FROM pg_locks WHERE NOT granted;","cap":"계획과 실제 행 수의 차이가 통계 문제를 가리킨다"},"key":["교착은 잠금 순서를 통일해 막는다. DDL 은 배타 락 시간을 먼저 확인한다","쿼리·인덱스가 그대로인데 느려졌으면 통계(ANALYZE)를 본다","컬럼에 함수·캐스팅을 씌우면 인덱스와 파티션 프루닝이 죽는다","idle in transaction 은 VACUUM 을 막아 블로트를 만든다","대량 변경은 배치로 쪼갠다 — 락·WAL·복제 지연이 함께 폭발한다","ORDER BY 에 유일 키가 없으면 페이지네이션이 흔들린다"]}},{"t":"PostgreSQL 로그 IV","q":[{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"특정 시각에 쿼리가 일제히 느려집니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"05:00:00 LOG  duration: 6.4 ms 평균","bad":false},{"txt":"05:20:00 LOG  shared_buffers 4GB","bad":false},{"txt":"05:40:00 WARN  cron: 전체 테이블 통계 재수집 + 인덱스 재구축 동시 실행","bad":true},{"txt":"05:50:00 WARN  db: 버퍼 적중률 99% → 61%","bad":false},{"txt":"06:00:00 ERROR api: p99 3400ms","bad":false},{"txt":"06:10:00 ERROR db: 디스크 읽기 8배","bad":false},{"txt":"06:40:00 LOG  유지보수 작업 완료","bad":false},{"txt":"06:50:00 LOG  버퍼 적중률 98% 회복","bad":false}],"ex":"05:40:00 무거운 유지보수 작업을 동시에 실행한 것이 원인입니다. 캐시가 밀려나 디스크 읽기가 폭증합니다. 적중률 하락·p99 상승·디스크 읽기 8배는 전부 그 결과이고, 작업이 끝나자 회복되는 것이 결정적 단서입니다. 작업을 분산하고 트래픽이 가장 적은 시간대로 옮겨야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"외래 키가 있는데 삭제가 매우 느립니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"13:40:00 LOG  DELETE FROM users WHERE id = $1","bad":false},{"txt":"13:40:05 LOG  5초 소요","bad":false},{"txt":"13:45:00 WARN  db: orders.user_id 외래 키에 인덱스 없음","bad":true},{"txt":"13:50:00 LOG  Seq Scan on orders (참조 검사)","bad":false},{"txt":"14:00:00 ERROR api: 사용자 삭제 타임아웃","bad":false},{"txt":"14:10:00 ERROR db: 삭제 중 락 유지 시간 증가","bad":false},{"txt":"14:30:00 ERROR api: 다른 주문 조회도 대기","bad":false},{"txt":"15:00:00 ERROR ops: 삭제 기능 임시 차단","bad":false}],"ex":"13:45:00 참조하는 쪽 컬럼에 인덱스가 없는 것이 원인입니다. 부모 행을 지울 때마다 자식 테이블 전체를 훑어 참조를 확인합니다. Seq Scan·삭제 타임아웃·락 유지·대기는 전부 그 결과입니다. 외래 키 컬럼에 인덱스를 만들어야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"커밋은 성공했는데 데이터가 없습니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"09:20:00 LOG  트랜잭션 시작","bad":false},{"txt":"09:20:01 LOG  INSERT INTO audit_log 실행","bad":false},{"txt":"09:20:02 WARN  db: synchronous_commit = off 설정됨","bad":true},{"txt":"09:20:02 LOG  COMMIT 응답 (WAL 디스크 flush 전)","bad":false},{"txt":"09:21:00 ERROR os: 서버 전원 이상으로 강제 재시작","bad":false},{"txt":"09:25:00 ERROR db: 마지막 0.4초 트랜잭션 유실","bad":false},{"txt":"09:30:00 ERROR audit: 감사 로그 누락 확인","bad":false},{"txt":"10:00:00 ERROR compliance: 감사 요건 위반 가능","bad":false}],"ex":"09:20:02 커밋 시 WAL 을 디스크에 강제로 내리지 않도록 설정한 것이 원인입니다. 성능은 오르지만 크래시 시 최근 트랜잭션이 사라집니다. 커밋 후 유실·감사 로그 누락·요건 위반은 전부 그 결과입니다. 감사·금전 데이터에는 이 설정을 쓰지 않아야 합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"파티션 테이블 조회가 전혀 빨라지지 않습니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"11:20:00 LOG  events 를 월별 파티션으로 구성","bad":false},{"txt":"11:30:00 LOG  파티션 24개","bad":false},{"txt":"11:40:00 WARN  app: WHERE created_at::text LIKE '2026-07%' 조회 (파티션 키에 캐스팅)","bad":true},{"txt":"11:50:00 LOG  Append: 24개 파티션 전부 스캔","bad":false},{"txt":"12:00:00 ERROR api: p99 7100ms","bad":false},{"txt":"12:10:00 ERROR db: 디스크 읽기 급증","bad":false},{"txt":"12:30:00 ERROR api: 타임아웃","bad":false},{"txt":"13:00:00 WARN  ops: 파티션 구성은 정상 확인","bad":false}],"ex":"11:40:00 파티션 키에 캐스팅을 적용한 것이 원인입니다. 플래너가 어느 파티션인지 판단할 수 없어 전부 스캔합니다. 24개 전체 스캔·지연·디스크 급증은 전부 그 결과입니다. 날짜 범위 조건으로 바꿔야 파티션 프루닝이 동작합니다."},{"t":"log","k":"로그 분석","cat":"logs","d":4,"q":"읽기 전용 복제본에서 쿼리가 자주 취소됩니다. 가장 먼저 고쳐야 하는 원인 한 줄을 고르세요.","file":"postgresql.log","items":[{"txt":"15:40:00 LOG  standby: 읽기 쿼리 정상 처리","bad":false},{"txt":"15:50:00 LOG  replay 지연 0.3s","bad":false},{"txt":"16:00:00 WARN  standby: hot_standby_feedback = off, 장시간 분석 쿼리 실행","bad":true},{"txt":"16:10:00 LOG  primary: VACUUM 이 해당 튜플 회수","bad":false},{"txt":"16:12:00 ERROR ERROR: canceling statement due to conflict with recovery","bad":false},{"txt":"16:12:01 ERROR analytics: 리포트 생성 실패 (x18)","bad":false},{"txt":"16:30:00 ERROR analytics: 일별 리포트 미생성","bad":false},{"txt":"17:00:00 ERROR ops: 분석 작업 프라이머리로 이동 검토","bad":false}],"ex":"16:00:00 복제본이 자신이 읽는 튜플을 프라이머리에 알리지 않는 설정이 원인입니다. 프라이머리가 그 튜플을 회수하면 복제본의 쿼리가 취소됩니다. conflict with recovery·리포트 실패·미생성은 전부 그 결과입니다. hot_standby_feedback 을 켜거나 max_standby_streaming_delay 를 늘려야 합니다."}],"th":{"sum":"데이터베이스 로그는 **락·잠금 순서 · 실행 계획 · 정리(VACUUM)** 세 갈래로 갈린다.","body":[{"h":"기다림의 정체를 찾는다","t":"교착은 잠금 순서가 경로마다 다를 때 생긴다. 배타 락을 오래 잡는 DDL(컬럼 타입 변경, 대량 DELETE)은 그 자체로 다운타임이다. 열어 둔 트랜잭션 하나가 VACUUM 을 막아 테이블을 부풀린다. 'idle in transaction' 은 항상 의심 대상이다."},{"h":"계획이 바뀌면 성능이 바뀐다","t":"쿼리와 인덱스가 그대로인데 갑자기 느려졌다면 통계를 본다. 컬럼에 함수·캐스팅을 적용하면 인덱스를 쓸 수 없고, 파티션 키에 캐스팅하면 프루닝이 깨진다. 외래 키 참조 컬럼에 인덱스가 없으면 부모 삭제가 자식 전체 스캔이 된다."},{"h":"쓰기 경로의 함정","t":"WAL 아카이브가 실패하면 디스크가 채워지고, synchronous_commit 을 끄면 커밋 후에도 유실될 수 있다. 트랜잭션 ID 소진 경고는 방치하면 DB 가 쓰기를 거부한다. 커밋하지 않고 커넥션을 반납하면 조용히 롤백된다."},{"h":"복제와 일관성","t":"대량 변경은 복제 지연을 만들고, 방금 쓴 데이터를 복제본에서 읽으면 없다. 복제본의 장시간 쿼리는 프라이머리의 VACUUM 과 충돌해 취소된다. 정렬에 유일 키가 없으면 페이지네이션에서 행이 중복·누락된다."}],"code":{"c":"-- 증상: 조회가 100배 느려졌다\nSeq Scan on orders (통계 기준 rows=1200, 실제 4,800,000)\n\n-- 원인은 그 앞\nWARN: orders 테이블에 대량 적재 후 ANALYZE 미실행\n\n-- 확인 순서\nEXPLAIN (ANALYZE, BUFFERS) SELECT ...;      -- 계획과 실제의 괴리\nSELECT * FROM pg_stat_activity WHERE state='idle in transaction';\nSELECT relname, n_dead_tup FROM pg_stat_user_tables ORDER BY 2 DESC;\nSELECT * FROM pg_locks WHERE NOT granted;","cap":"계획과 실제 행 수의 차이가 통계 문제를 가리킨다"},"key":["교착은 잠금 순서를 통일해 막는다. DDL 은 배타 락 시간을 먼저 확인한다","쿼리·인덱스가 그대로인데 느려졌으면 통계(ANALYZE)를 본다","컬럼에 함수·캐스팅을 씌우면 인덱스와 파티션 프루닝이 죽는다","idle in transaction 은 VACUUM 을 막아 블로트를 만든다","대량 변경은 배치로 쪼갠다 — 락·WAL·복제 지연이 함께 폭발한다","ORDER BY 에 유일 키가 없으면 페이지네이션이 흔들린다"]}}]},{"t":"코드 리뷰 · 쿼리 결함 찾기","l":[{"t":"코드 리뷰 I","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT *\nFROM orders\nWHERE DATE(created_at) = '2026-07-26';","items":[{"txt":"인덱스가 걸린 컬럼을 함수로 감싸 인덱스를 쓰지 못하고 전체 스캔이 된다","bad":true},{"txt":"created_at &gt;= '2026-07-26' AND created_at &lt; '2026-07-27' 로 범위 조건으로 바꾸면 인덱스를 탄다","bad":false},{"txt":"SELECT * 는 필요 없는 컬럼까지 읽어 I/O 와 네트워크를 낭비한다","bad":true},{"txt":"표현식 인덱스를 만들면 함수를 쓰면서도 인덱스를 활용할 수 있다","bad":false},{"txt":"날짜 리터럴을 문자열로 쓰면 세션의 날짜 형식 설정에 따라 해석이 달라질 수 있다","bad":false},{"txt":"WHERE 절에 조건이 하나뿐이라 옵티마이저가 계획을 세우기는 쉽다","bad":false}],"ex":"결함은 인덱스 컬럼을 함수로 감싼 것(SARGable 하지 않음)과 SELECT * 입니다. DATE(created_at) 은 모든 행에 대해 계산해야 하므로 인덱스의 정렬 성질을 쓸 수 없어 전체 스캔이 됩니다. 같은 결과를 범위 조건으로 표현하면 인덱스 레인지 스캔이 됩니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT name\nFROM users\nWHERE id NOT IN (SELECT user_id FROM banned);","items":[{"txt":"서브쿼리 결과에 NULL 이 하나라도 있으면 NOT IN 전체가 어떤 행도 반환하지 않는다","bad":true},{"txt":"NOT EXISTS 나 LEFT JOIN ... IS NULL 로 바꾸면 NULL 에 영향받지 않는다","bad":false},{"txt":"banned.user_id 에 NOT NULL 제약이 있다면 이 쿼리도 의도대로 동작한다","bad":false},{"txt":"NULL 과의 비교는 참도 거짓도 아닌 UNKNOWN 이라 WHERE 가 행을 걸러낸다","bad":false},{"txt":"서브쿼리가 크면 매번 평가되어 느릴 수 있으므로 조인 방식이 유리할 수 있다","bad":false},{"txt":"name 컬럼만 선택해 필요한 데이터만 읽는 것은 올바른 습관이다","bad":false}],"ex":"결함은 NOT IN 과 NULL 의 상호작용입니다. id NOT IN (1, NULL) 은 'id != 1 AND id != NULL' 이고 두 번째가 UNKNOWN 이므로 전체가 참이 될 수 없어 결과가 항상 빈 집합이 됩니다. 오류도 경고도 없이 조용히 0건이 나오는 것이 위험한 점입니다. NOT EXISTS 를 씁니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT o.*, u.name\nFROM orders o, users u\nWHERE o.total &gt; 1000;","items":[{"txt":"조인 조건이 없어 두 테이블의 카티션 곱이 만들어져 행 수가 곱으로 폭증한다","bad":true},{"txt":"명시적 JOIN ... ON 문법을 쓰면 조인 조건 누락을 눈에 띄게 만든다","bad":false},{"txt":"o.* 로 모든 컬럼을 가져와 필요 없는 데이터까지 실어 나른다","bad":true},{"txt":"쉼표 조인은 SQL-89 문법으로 표준에서 여전히 유효하지만 가독성이 떨어진다","bad":false},{"txt":"total 컬럼에 인덱스가 없다면 조건 평가에 전체 스캔이 필요하다","bad":false},{"txt":"별칭 o, u 를 쓰면 컬럼 출처가 명확해져 읽기 좋다","bad":false}],"ex":"결함은 조인 조건 누락으로 인한 카티션 곱과 o.* 입니다. 주문 1만 건 × 사용자 1만 명이면 1억 행이 만들어져 데이터베이스와 애플리케이션 양쪽이 마비됩니다. 쉼표 조인은 조건을 WHERE 에 섞어 두므로 이런 누락이 눈에 띄지 않는 것이 근본 원인입니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT * FROM logs\nORDER BY created_at DESC\nLIMIT 20 OFFSET 200000;","items":[{"txt":"OFFSET 은 건너뛸 행을 실제로 읽고 버리므로 뒤 페이지로 갈수록 선형으로 느려진다","bad":true},{"txt":"마지막으로 본 행의 키를 기준으로 하는 커서 기반 페이지네이션이 일정한 성능을 준다","bad":false},{"txt":"페이지를 넘기는 동안 새 행이 들어오면 항목이 중복되거나 건너뛰어진다","bad":true},{"txt":"created_at 에 인덱스가 있으면 정렬 비용은 줄지만 OFFSET 비용은 그대로다","bad":false},{"txt":"LIMIT 20 은 한 페이지 크기로 적절하다","bad":false},{"txt":"ORDER BY 가 없으면 순서가 보장되지 않으므로 정렬을 명시한 것은 올바르다","bad":false}],"ex":"결함은 큰 OFFSET 과 페이지네이션 중 데이터 이동입니다. OFFSET 200000 은 20만 행을 읽어 버린 뒤 20행을 돌려주므로 뒤로 갈수록 느려지고, 그 사이 새 로그가 들어오면 경계에서 중복·누락이 생깁니다. WHERE created_at < :lastSeen 형태의 커서 방식이 두 문제를 함께 해결합니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"UPDATE inventory SET qty = qty - 1 WHERE sku = 'A-100';\nINSERT INTO shipments (order_id, sku) VALUES (9001, 'A-100');","items":[{"txt":"재고 차감과 출고 기록이 하나의 트랜잭션으로 묶이지 않아, 중간에 실패하면 재고만 줄고 출고가 없는 상태로 남는다","bad":true},{"txt":"BEGIN ... COMMIT 으로 감싸 원자성을 보장해야 한다","bad":false},{"txt":"남은 수량이 충분한지 확인하는 조건이 없어 재고가 음수가 될 수 있다","bad":true},{"txt":"qty = qty - 1 처럼 읽은 값을 애플리케이션에서 계산해 다시 쓰지 않고 데이터베이스에서 처리한 것은 경쟁을 줄이는 올바른 방식이다","bad":false},{"txt":"동시에 여러 주문이 같은 SKU 를 차감하면 행 잠금 대기가 길어질 수 있다","bad":false},{"txt":"수량 1 과 SKU 를 하드코딩하면 재사용할 수 없으므로 파라미터로 받아야 한다","bad":false}],"ex":"결함은 트랜잭션 부재와 수량 검사 부재입니다. 재고를 줄인 직후 프로세스가 죽거나 INSERT 가 실패하면 팔린 기록 없이 재고만 사라지고, 수량 조건이 없어 재고가 음수가 됩니다. 계산을 DB 에서 수행한 것 자체는 경쟁을 줄이는 올바른 방식이라 오탐입니다."}],"th":{"sum":"결과는 맞는데 느리거나, 조용히 0건을 돌려주거나, 데이터를 잃는 쿼리를 골라내는 훈련입니다.","body":[{"h":"인덱스를 못 쓰게 만드는 것들","t":"컬럼을 함수로 감싸기, 선행 와일드카드 <code>LIKE '%x%'</code>, 타입이 다른 리터럴로 인한 암묵적 형변환 — 셋 다 <b>인덱스의 정렬 성질</b>을 무력화해 전체 스캔이 됩니다."},{"h":"NULL 은 값이 아니다","t":"<code>NOT IN</code> 서브쿼리에 NULL 이 섞이면 결과가 항상 빈 집합이 됩니다. 오류도 경고도 없이 0건이 나오는 것이 가장 위험합니다."},{"h":"조인의 조건이 어디 있는가","t":"조인 조건이 없으면 카티션 곱, LEFT JOIN 의 조건을 WHERE 에 두면 INNER JOIN 이 됩니다. <b>ON 과 WHERE 의 차이</b>가 결과 집합을 바꿉니다."},{"h":"원자성과 권한","t":"두 UPDATE 를 트랜잭션으로 묶지 않으면 돈이 사라지고, 확인 후 삽입은 동시에 실행되면 중복을 만듭니다. 그리고 계정 권한의 크기가 곧 사고의 크기입니다."}],"code":{"t":"조용히 0건","c":"SELECT name FROM users\nWHERE id NOT IN (SELECT user_id FROM banned);\n-- banned.user_id 에 NULL 이 하나라도 있으면 결과는 항상 0건"},"key":["컬럼에 함수·형변환을 씌우면 인덱스를 못 쓴다","NOT IN + NULL 은 조용히 0건","ON 과 WHERE 는 LEFT JOIN 에서 결과가 다르다","트랜잭션·유니크 제약·최소 권한"]}},{"t":"코드 리뷰 II","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT user_id, COUNT(*)\nFROM events\nWHERE type = 'click'\nGROUP BY user_id\nHAVING COUNT(*) &gt; 0;","items":[{"txt":"HAVING COUNT(*) &gt; 0 은 GROUP BY 결과에 항상 참이라 아무것도 걸러내지 않는 불필요한 조건이다","bad":true},{"txt":"WHERE 로 걸러낼 수 있는 조건을 HAVING 에 두면 집계 후에 평가되어 비효율적이다","bad":false},{"txt":"type 과 user_id 를 포함한 복합 인덱스가 있으면 인덱스만으로 집계할 수 있다","bad":false},{"txt":"COUNT(*) 결과 컬럼에 별칭이 없어 애플리케이션이 위치로 접근해야 한다","bad":false},{"txt":"COUNT(*) 는 NULL 을 포함해 행 수를 세므로 이 용도에 맞다","bad":false},{"txt":"GROUP BY 에 없는 컬럼을 SELECT 하지 않아 표준에 맞는 쿼리다","bad":false}],"ex":"결함은 의미 없는 HAVING 절입니다. GROUP BY 는 원소가 하나 이상인 그룹만 만들므로 COUNT(*) > 0 은 언제나 참이며, 읽는 사람에게 '무언가 걸러진다' 는 잘못된 인상만 줍니다. 필터가 집계와 무관하면 WHERE 로 옮겨 집계 이전에 줄이는 것이 원칙입니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT * FROM products\nWHERE name LIKE '%노트북%';","items":[{"txt":"앞에 와일드카드가 오는 LIKE 는 B-tree 인덱스를 쓸 수 없어 전체 스캔이 된다","bad":true},{"txt":"전문 검색 인덱스나 트라이그램 인덱스를 쓰면 부분 일치도 색인할 수 있다","bad":false},{"txt":"SELECT * 는 필요 없는 컬럼까지 읽는다","bad":true},{"txt":"뒤에만 와일드카드가 오는 'x%' 형태는 인덱스 레인지 스캔이 가능하다","bad":false},{"txt":"검색어를 파라미터로 받는다면 % 를 붙이는 위치를 애플리케이션이 정해야 한다","bad":false},{"txt":"LIKE 는 대소문자 구분 여부가 데이터베이스와 콜레이션에 따라 달라진다","bad":false}],"ex":"결함은 선행 와일드카드와 SELECT * 입니다. B-tree 인덱스는 앞에서부터 정렬돼 있어 시작 문자열을 알아야 범위를 좁힐 수 있는데, '%...' 는 그 성질을 쓸 수 없어 모든 행을 확인합니다. 부분 일치 검색이 정말 필요하면 전문 검색이나 트라이그램 인덱스를 도입합니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"CREATE TABLE sessions (\n  id VARCHAR(64) PRIMARY KEY,\n  user_id INT,\n  data TEXT,\n  created_at TIMESTAMP\n);","items":[{"txt":"user_id 에 외래 키와 인덱스가 없어 사용자별 조회가 전체 스캔이 되고 고아 행을 막지 못한다","bad":true},{"txt":"만료 시각 컬럼과 정리 작업이 없어 세션 행이 무한히 쌓인다","bad":true},{"txt":"created_at 에 NOT NULL 과 기본값이 없어 값이 빠진 행이 생길 수 있다","bad":true},{"txt":"세션 식별자를 기본 키로 둔 것은 조회 패턴에 맞는 선택이다","bad":false},{"txt":"TEXT 컬럼은 큰 값을 별도 저장 영역에 두므로 행 크기를 작게 유지한다","bad":false},{"txt":"VARCHAR(64) 는 대부분의 세션 토큰 길이를 담기에 충분하다","bad":false}],"ex":"결함은 인덱스·외래 키 부재, 만료 정책 부재, NOT NULL 기본값 부재입니다. 세션 테이블은 쓰기가 많고 오래된 행이 계속 쌓이므로 만료와 정리를 설계에 넣지 않으면 몇 달 뒤 디스크와 쿼리 성능을 함께 잠식합니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT u.id, u.name,\n  (SELECT COUNT(*) FROM orders o WHERE o.user_id = u.id) AS cnt\nFROM users u\nWHERE u.active = true;","items":[{"txt":"상관 서브쿼리가 사용자마다 실행되어 사용자 수만큼 집계가 반복된다","bad":true},{"txt":"LEFT JOIN 과 GROUP BY 로 한 번에 집계하면 한 번의 스캔으로 끝난다","bad":false},{"txt":"o.user_id 에 인덱스가 있으면 각 서브쿼리는 빠르지만 호출 횟수 자체는 줄지 않는다","bad":false},{"txt":"필요한 컬럼만 선택한 것은 올바른 습관이다","bad":false},{"txt":"주문이 없는 사용자도 0 으로 나오므로 결과 자체는 의도에 맞는다","bad":false},{"txt":"active = true 는 불리언 타입이 없는 데이터베이스에서는 다르게 써야 한다","bad":false}],"ex":"결함은 상관 서브쿼리로 인한 반복 집계입니다. 결과는 맞지만 사용자가 10만 명이면 집계가 10만 번 실행됩니다. 옵티마이저가 조인으로 바꿔 주기도 하지만 항상은 아니므로, 처음부터 LEFT JOIN + GROUP BY 로 쓰는 편이 안전합니다. 다른 항목들은 오탐이거나 개선 제안입니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"DELETE FROM audit_log\nWHERE created_at &lt; NOW() - INTERVAL '1 year';","items":[{"txt":"한 번의 문장으로 수백만 행을 지우면 긴 트랜잭션과 대량 잠금으로 다른 작업이 막힌다","bad":true},{"txt":"배치 크기를 정해 나눠 지우고 사이에 커밋하면 잠금 시간이 짧아진다","bad":false},{"txt":"created_at 에 인덱스가 없으면 삭제 대상을 찾는 데만 전체 스캔이 필요하다","bad":false},{"txt":"파티션 테이블이라면 오래된 파티션을 통째로 드롭하는 편이 훨씬 빠르다","bad":false},{"txt":"감사 로그를 지우기 전에 보관 정책과 규제 요건을 확인해야 한다","bad":false},{"txt":"WHERE 절이 있으므로 전체 삭제가 되는 실수는 방지된다","bad":false}],"ex":"결함은 대량 삭제를 한 트랜잭션에 몰아넣은 것입니다. 실행 중 잠금이 유지되고 되돌리기 로그가 부풀어 복제 지연과 저장소 압박까지 일으킵니다. 배치로 나누거나, 애초에 시간 기준 파티션을 두어 파티션 드롭으로 처리합니다."}],"th":{"sum":"결과는 맞는데 느리거나, 조용히 0건을 돌려주거나, 데이터를 잃는 쿼리를 골라내는 훈련입니다.","body":[{"h":"인덱스를 못 쓰게 만드는 것들","t":"컬럼을 함수로 감싸기, 선행 와일드카드 <code>LIKE '%x%'</code>, 타입이 다른 리터럴로 인한 암묵적 형변환 — 셋 다 <b>인덱스의 정렬 성질</b>을 무력화해 전체 스캔이 됩니다."},{"h":"NULL 은 값이 아니다","t":"<code>NOT IN</code> 서브쿼리에 NULL 이 섞이면 결과가 항상 빈 집합이 됩니다. 오류도 경고도 없이 0건이 나오는 것이 가장 위험합니다."},{"h":"조인의 조건이 어디 있는가","t":"조인 조건이 없으면 카티션 곱, LEFT JOIN 의 조건을 WHERE 에 두면 INNER JOIN 이 됩니다. <b>ON 과 WHERE 의 차이</b>가 결과 집합을 바꿉니다."},{"h":"원자성과 권한","t":"두 UPDATE 를 트랜잭션으로 묶지 않으면 돈이 사라지고, 확인 후 삽입은 동시에 실행되면 중복을 만듭니다. 그리고 계정 권한의 크기가 곧 사고의 크기입니다."}],"code":{"t":"조용히 0건","c":"SELECT name FROM users\nWHERE id NOT IN (SELECT user_id FROM banned);\n-- banned.user_id 에 NULL 이 하나라도 있으면 결과는 항상 0건"},"key":["컬럼에 함수·형변환을 씌우면 인덱스를 못 쓴다","NOT IN + NULL 은 조용히 0건","ON 과 WHERE 는 LEFT JOIN 에서 결과가 다르다","트랜잭션·유니크 제약·최소 권한"]}},{"t":"코드 리뷰 III","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT * FROM orders\nWHERE order_no = 12345;\n-- order_no 는 VARCHAR(20) 이고 인덱스가 있다","items":[{"txt":"문자열 컬럼을 숫자와 비교해 암묵적 형변환이 일어나고, 그 결과 인덱스를 쓰지 못할 수 있다","bad":true},{"txt":"'12345' 처럼 컬럼 타입에 맞는 리터럴을 쓰면 인덱스를 정상적으로 탄다","bad":false},{"txt":"단건 조회인데도 모든 컬럼을 가져와, 스키마가 바뀌면 결과 구조가 함께 바뀐다","bad":true},{"txt":"데이터베이스에 따라 변환 방향이 달라 결과 자체가 달라지는 경우도 있다","bad":false},{"txt":"주문 번호를 숫자로 저장하는 편이 나았을 수 있지만 지금 스키마는 문자열이다","bad":false},{"txt":"등호 비교는 범위 비교보다 인덱스 활용에 유리하다","bad":false}],"ex":"결함은 암묵적 형변환과 SELECT * 입니다. 문자열 컬럼과 숫자를 비교하면 대부분의 데이터베이스가 컬럼 쪽을 숫자로 변환하는데, 이는 컬럼에 함수를 씌운 것과 같아 인덱스를 쓸 수 없게 만듭니다. 리터럴 하나만 따옴표로 감싸면 실행 계획이 완전히 달라집니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"INSERT INTO stats (day, hits)\nVALUES (CURRENT_DATE, 1);\n-- 이미 오늘 행이 있으면 UPDATE 하려고 먼저 SELECT 로 확인한다","items":[{"txt":"확인과 삽입 사이에 다른 세션이 같은 행을 넣을 수 있는 경쟁 조건(check-then-act)이다","bad":true},{"txt":"INSERT ... ON CONFLICT DO UPDATE 같은 upsert 로 원자적으로 처리해야 한다","bad":false},{"txt":"day 컬럼에 유니크 제약이 없으면 upsert 도 충돌을 감지할 수 없다","bad":true},{"txt":"CURRENT_DATE 는 세션 시간대에 따라 날짜 경계가 달라질 수 있다","bad":false},{"txt":"hits 를 1 로 고정 삽입하는 것은 첫 기록에는 맞는 값이다","bad":false},{"txt":"통계 테이블은 쓰기가 잦으므로 인덱스를 최소화하는 편이 좋다","bad":false}],"ex":"결함은 확인 후 삽입 사이의 경쟁과 유니크 제약 부재입니다. 두 요청이 동시에 '없다' 고 확인하면 둘 다 삽입해 같은 날짜 행이 둘 생기고, 이후 집계가 조용히 틀어집니다. 유니크 제약을 걸고 upsert 로 한 문장에 처리하면 데이터베이스가 원자성을 보장합니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"GRANT ALL PRIVILEGES ON DATABASE shop TO app_user;\n-- 애플리케이션은 조회와 주문 삽입만 한다","items":[{"txt":"애플리케이션이 필요로 하는 것보다 훨씬 넓은 권한을 주어, 침해 시 피해 범위가 데이터베이스 전체가 된다","bad":true},{"txt":"필요한 테이블에 대한 SELECT·INSERT 만 부여하는 최소 권한 원칙을 적용해야 한다","bad":false},{"txt":"DROP·TRUNCATE 권한이 있으면 애플리케이션 버그 하나가 데이터를 통째로 지울 수 있다","bad":true},{"txt":"마이그레이션용 계정을 분리하면 런타임 계정의 권한을 낮게 유지할 수 있다","bad":false},{"txt":"권한을 데이터베이스 단위로 주면 새 테이블에도 자동으로 적용되어 관리가 편하다","bad":false},{"txt":"역할(role)을 만들어 권한을 묶으면 계정이 늘어나도 관리가 쉬워진다","bad":false}],"ex":"결함은 과도한 권한 부여입니다. SQL 인젝션이나 자격 증명 유출이 일어났을 때 피해 크기는 그 계정이 할 수 있는 일의 크기와 같습니다. 조회와 삽입만 하는 애플리케이션에 DROP 권한을 주면, 사고 하나가 복구 불가능한 손실이 됩니다. 최소 권한이 원칙입니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"SELECT c.name, SUM(o.total) AS revenue\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.status = 'paid'\nGROUP BY c.name;","items":[{"txt":"LEFT JOIN 의 오른쪽 테이블 조건을 WHERE 에 두어 NULL 행이 걸러지고, 결과적으로 INNER JOIN 이 된다","bad":true},{"txt":"조건을 ON 절로 옮기면 주문이 없는 고객도 결과에 남는다","bad":false},{"txt":"c.name 으로 그룹핑하면 동명이인의 매출이 합쳐지므로 c.id 로 묶어야 한다","bad":true},{"txt":"SUM 은 NULL 을 무시하므로 주문이 없는 고객의 매출은 NULL 이 된다","bad":false},{"txt":"COALESCE 로 감싸면 NULL 대신 0 을 보여줄 수 있다","bad":false},{"txt":"별칭 revenue 를 붙여 결과 컬럼 이름을 명확히 한 것은 좋다","bad":false}],"ex":"결함은 LEFT JOIN 을 무력화한 WHERE 조건과 이름 기준 그룹핑입니다. 주문이 없는 고객은 o.status 가 NULL 이라 WHERE 에서 탈락하므로, LEFT JOIN 을 쓴 의도가 사라집니다. 그리고 동명이인이 한 행으로 합쳐져 매출이 잘못 집계됩니다. 조건은 ON 으로, 그룹핑은 기본 키로 합니다."}],"th":{"sum":"결과는 맞는데 느리거나, 조용히 0건을 돌려주거나, 데이터를 잃는 쿼리를 골라내는 훈련입니다.","body":[{"h":"인덱스를 못 쓰게 만드는 것들","t":"컬럼을 함수로 감싸기, 선행 와일드카드 <code>LIKE '%x%'</code>, 타입이 다른 리터럴로 인한 암묵적 형변환 — 셋 다 <b>인덱스의 정렬 성질</b>을 무력화해 전체 스캔이 됩니다."},{"h":"NULL 은 값이 아니다","t":"<code>NOT IN</code> 서브쿼리에 NULL 이 섞이면 결과가 항상 빈 집합이 됩니다. 오류도 경고도 없이 0건이 나오는 것이 가장 위험합니다."},{"h":"조인의 조건이 어디 있는가","t":"조인 조건이 없으면 카티션 곱, LEFT JOIN 의 조건을 WHERE 에 두면 INNER JOIN 이 됩니다. <b>ON 과 WHERE 의 차이</b>가 결과 집합을 바꿉니다."},{"h":"원자성과 권한","t":"두 UPDATE 를 트랜잭션으로 묶지 않으면 돈이 사라지고, 확인 후 삽입은 동시에 실행되면 중복을 만듭니다. 그리고 계정 권한의 크기가 곧 사고의 크기입니다."}],"code":{"t":"조용히 0건","c":"SELECT name FROM users\nWHERE id NOT IN (SELECT user_id FROM banned);\n-- banned.user_id 에 NULL 이 하나라도 있으면 결과는 항상 0건"},"key":["컬럼에 함수·형변환을 씌우면 인덱스를 못 쓴다","NOT IN + NULL 은 조용히 0건","ON 과 WHERE 는 LEFT JOIN 에서 결과가 다르다","트랜잭션·유니크 제약·최소 권한"]}}]},{"t":"결과 예측 · 쿼리가 무엇을 돌려주는가","l":[{"t":"결과 예측 I","q":[{"t":"input","k":"결과 예측","q":"결과 행 수는? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT u.name, o.total FROM users u JOIN orders o ON o.user_id = u.id;","a":["3"],"ex":"INNER JOIN 은 양쪽에 짝이 있는 행만 남깁니다. user_id 9 인 주문은 users 에 없고, 도·라는 주문이 없어 빠집니다. 1번 사용자가 주문 2건이라 3행입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 행 수는? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT u.name, o.total FROM users u LEFT JOIN orders o ON o.user_id = u.id;","a":["5"],"ex":"LEFT JOIN 은 왼쪽 행을 모두 남기고 짝이 없으면 오른쪽을 NULL 로 채웁니다. 1번은 주문 2건이라 2행으로 늘고, 2·3·4번이 각 1행씩 더해져 5행입니다. user_id 9 인 주문은 왼쪽에 짝이 없어 여전히 빠집니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT count(*) FROM users u LEFT JOIN orders o ON o.user_id = u.id WHERE o.total &gt; 150;","a":["1"],"ex":"LEFT JOIN 의 오른쪽 컬럼 조건을 WHERE 에 두면 NULL 행이 걸러져 사실상 INNER JOIN 이 됩니다. total 이 150 을 넘는 행은 200 하나뿐입니다. NULL > 150 은 UNKNOWN 이라 이것도 탈락합니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT count(*) FROM users, orders;","a":["16"],"ex":"조인 조건이 없는 쉼표 조인은 카티션 곱입니다. 사용자 4명 × 주문 4건 = 16행이 만들어집니다. 실무에서 조인 조건을 빠뜨렸을 때 정확히 이 폭증이 일어납니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과를 셀 순서대로 쉼표로 이어 적으세요 (예: 1,2,3)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT count(*), count(city), count(DISTINCT city) FROM users;","a":["4,3,2"],"ex":"세 함수가 세는 대상이 모두 다릅니다. count(*) 는 행 4개, count(city) 는 NULL 을 뺀 3개, count(DISTINCT city) 는 서로 다른 값인 서울·부산 2개입니다. NULL 은 DISTINCT 집계에서도 값으로 세지 않습니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}},{"t":"결과 예측 II","q":[{"t":"input","k":"결과 예측","q":"결과를 셀 순서대로 쉼표로 이어 적으세요","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT round(avg(total), 2), sum(total), count(total) FROM orders;","a":["116.67,350,3"],"ex":"집계 함수는 NULL 을 무시합니다. 그래서 avg 의 분모가 4 가 아니라 3 이 되어 350/3 이 됩니다. '평균이 이상하다' 는 신고의 흔한 원인입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT count(*) FROM users WHERE city != '서울';","a":["1"],"ex":"NULL 과의 비교는 참도 거짓도 아닌 UNKNOWN 이라 WHERE 가 걸러냅니다. 그래서 '서울이 아닌' 조건에 도시가 NULL 인 행이 포함되지 않습니다. 포함하려면 OR city IS NULL 을 명시해야 합니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE t (n INTEGER, s TEXT);\nINSERT INTO t VALUES (1,'a'),(2,'b'),(3,NULL),(4,'a'),(NULL,'c');\n\nSELECT count(*) FROM t WHERE s NOT IN (SELECT s FROM t WHERE n = 3);","a":["0"],"ex":"서브쿼리가 NULL 을 돌려주므로 NOT IN 전체가 UNKNOWN 이 되어 어떤 행도 통과하지 못합니다. 오류도 경고도 없이 조용히 0건이 나오는 것이 이 함정의 위험한 점입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"n 값을 위에서부터 쉼표로 적으세요 (NULL 은 null)","code":"CREATE TABLE t (n INTEGER, s TEXT);\nINSERT INTO t VALUES (1,'a'),(2,'b'),(3,NULL),(4,'a'),(NULL,'c');\n\nSELECT n FROM t ORDER BY n;","a":["null,1,2,3,4"],"ex":"SQLite 의 기본 정렬에서 NULL 은 가장 작은 값으로 취급되어 앞에 옵니다. 데이터베이스마다 기본 위치가 달라 NULLS FIRST/LAST 를 명시하는 편이 안전합니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"행은 세미콜론, 셀은 쉼표로 이어 적으세요 (예: a,1;b,2)","code":"CREATE TABLE t (n INTEGER, s TEXT);\nINSERT INTO t VALUES (1,'a'),(2,'b'),(3,NULL),(4,'a'),(NULL,'c');\n\nSELECT coalesce(s, 'none'), ifnull(n, -1) FROM t WHERE s IS NULL OR n IS NULL;","a":["none,3;c,-1"],"ex":"coalesce 와 ifnull 은 NULL 을 대체값으로 바꿉니다. IS NULL 로 걸러야 NULL 행을 잡을 수 있고 = NULL 로는 잡히지 않습니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}},{"t":"결과 예측 III","q":[{"t":"input","k":"결과 예측","q":"행은 세미콜론, 셀은 쉼표로 (NULL 은 null)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT region, count(*), sum(amount) FROM sales GROUP BY region ORDER BY region;","a":["a,3,700;b,2,400;c,1,null"],"ex":"그룹마다 집계가 따로 계산됩니다. C 지역은 값이 NULL 하나뿐이라 count(*) 는 1 이지만 sum 은 더할 값이 없어 NULL 입니다. sum 이 0 이 아니라 NULL 이라는 점이 자주 틀립니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT count(*) FROM (SELECT region FROM sales GROUP BY region HAVING sum(amount) &gt; 500);","a":["1"],"ex":"HAVING 은 집계 결과에 대한 필터라 그룹이 만들어진 뒤 평가됩니다. 합계가 500 을 넘는 지역은 A(700) 뿐이고, C 는 합계가 NULL 이라 비교가 UNKNOWN 이 되어 탈락합니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과를 셀 순서대로 쉼표로 이어 적으세요","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT count(DISTINCT amount), count(DISTINCT region) FROM sales;","a":["3,3"],"ex":"DISTINCT 집계도 NULL 을 세지 않습니다. 금액은 100·300·200 세 종류이고 지역은 A·B·C 세 종류입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 행 수는? (숫자만)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT region, amount FROM sales GROUP BY region ORDER BY region;","a":["3"],"ex":"SQLite 는 GROUP BY 에 없는 컬럼을 SELECT 해도 오류를 내지 않고 그룹 중 한 행의 값을 임의로 고릅니다. 행 수는 그룹 수와 같지만, 이 관용은 표준이 아니며 다른 데이터베이스에서는 오류입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"값을 위에서부터 쉼표로 적으세요","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT row_number() OVER (ORDER BY amount DESC) FROM sales;","a":["1,2,3,4,5,6"],"ex":"row_number 는 동점이어도 서로 다른 연번을 붙입니다. 전체 행 수만큼 1부터 이어지므로 중복이 없습니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}},{"t":"결과 예측 IV","q":[{"t":"input","k":"결과 예측","q":"두 번째 열 값을 위에서부터 쉼표로 적으세요","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT amount, rank() OVER (ORDER BY amount DESC) FROM sales ORDER BY amount DESC;","a":["1,1,3,3,5,6"],"ex":"rank 는 동점에 같은 순위를 주고 그 수만큼 다음 순위를 건너뜁니다. 300 이 둘이면 다음은 3위입니다. NULL 은 DESC 정렬에서 가장 뒤로 갑니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"두 번째 열 값을 위에서부터 쉼표로 적으세요","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT amount, dense_rank() OVER (ORDER BY amount DESC) FROM sales ORDER BY amount DESC;","a":["1,1,2,2,3,4"],"ex":"dense_rank 는 동점에 같은 순위를 주지만 다음 순위를 건너뛰지 않습니다. rank 와의 차이가 정확히 이 지점입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"두 번째 열 값을 위에서부터 쉼표로 적으세요 (NULL 은 null)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT region, sum(amount) OVER (PARTITION BY region ORDER BY id) FROM sales ORDER BY id;","a":["100,400,200,400,null,700"],"ex":"PARTITION BY 로 그룹을 나누고 ORDER BY 를 주면 기본 프레임이 '시작부터 현재 행까지' 라 누적합이 됩니다. GROUP BY 와 달리 행이 줄지 않는 것이 윈도우 함수의 성질입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"두 번째 열 값을 위에서부터 쉼표로 적으세요 (NULL 은 null)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT amount, lag(amount) OVER (ORDER BY id) FROM sales ORDER BY id;","a":["null,100,300,200,200,null"],"ex":"lag 는 이전 행의 값을 가져오며 첫 행은 이전이 없어 NULL 입니다. 원본 값이 NULL 인 행은 그 NULL 이 그대로 다음 행에 전달됩니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"값을 위에서부터 쉼표로 적으세요 (NULL 은 null)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT lead(amount, 2, -1) OVER (ORDER BY id) FROM sales ORDER BY id;","a":["200,200,null,300,-1,-1"],"ex":"lead 의 세 번째 인자는 가져올 행이 없을 때 쓰는 기본값입니다. 마지막 두 행은 두 칸 뒤가 없어 -1 이 되지만, 값 자체가 NULL 인 행은 기본값이 아니라 NULL 그대로입니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}},{"t":"결과 예측 V","q":[{"t":"input","k":"결과 예측","q":"결과 행 수는? (숫자만)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT region FROM sales UNION SELECT region FROM sales;","a":["3"],"ex":"UNION 은 중복을 제거합니다. 같은 집합을 두 번 합쳐도 결과는 서로 다른 지역 수와 같습니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 행 수는? (숫자만)","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT region FROM sales UNION ALL SELECT region FROM sales;","a":["12"],"ex":"UNION ALL 은 중복을 그대로 둡니다. 중복 제거가 필요 없으면 정렬 비용이 없어 UNION 보다 빠릅니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"값을 위에서부터 쉼표로 적으세요","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT amount FROM sales ORDER BY amount DESC LIMIT 2 OFFSET 1;","a":["300,200"],"ex":"OFFSET 은 정렬된 결과에서 앞의 행을 건너뜁니다. 큰 OFFSET 은 건너뛸 행을 실제로 읽어 버리므로 뒤 페이지일수록 느려집니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"값을 위에서부터 쉼표로 적으세요 (NULL 은 null)","code":"CREATE TABLE t (n INTEGER, s TEXT);\nINSERT INTO t VALUES (1,'a'),(2,'b'),(3,NULL),(4,'a'),(NULL,'c');\n\nSELECT DISTINCT s FROM t ORDER BY s;","a":["null,a,b,c"],"ex":"DISTINCT 는 NULL 도 하나의 값으로 취급해 한 번만 남깁니다. 집계 함수가 NULL 을 무시하는 것과 규칙이 다릅니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과를 셀 순서대로 쉼표로 이어 적으세요","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT 7/2, 7%2, 7*1.0/2;","a":["3,1,3.5"],"ex":"정수끼리의 나눗셈은 소수점을 버립니다. 한쪽에 1.0 을 곱해 실수로 만들면 소수 결과를 얻습니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}},{"t":"결과 예측 VI","q":[{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT count(*) FROM users WHERE id IN (SELECT user_id FROM orders);","a":["2"],"ex":"IN 서브쿼리는 짝이 있는 사용자만 남깁니다. 주문의 user_id 는 1·1·2·9 이고 그중 users 에 있는 것은 1·2 입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (숫자만)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT count(*) FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id AND o.total IS NOT NULL);","a":["1"],"ex":"EXISTS 는 한 건이라도 있으면 참이라 조건을 만족하는 첫 행에서 멈출 수 있습니다. total 이 NULL 이 아닌 주문을 가진 사용자는 1번뿐입니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"값을 위에서부터 쉼표로 적으세요","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT CASE WHEN amount IS NULL THEN 'none' WHEN amount &gt;= 300 THEN 'high' ELSE 'low' END FROM sales ORDER BY id;","a":["low,high,low,low,none,high"],"ex":"CASE 는 위에서부터 첫 참을 만나면 멈춥니다. NULL 검사를 앞에 두지 않으면 NULL 이 비교에서 UNKNOWN 이 되어 ELSE 로 떨어집니다.","cat":"predict"},{"t":"input","k":"결과 예측","q":"행은 세미콜론, 셀은 쉼표로","code":"CREATE TABLE sales (id INTEGER, region TEXT, amount INTEGER, ymd TEXT);\nINSERT INTO sales VALUES\n (1,'A',100,'2026-01-01'),(2,'A',300,'2026-01-02'),(3,'B',200,'2026-01-01'),\n (4,'B',200,'2026-01-03'),(5,'C',NULL,'2026-01-02'),(6,'A',300,'2026-01-04');\n\nSELECT substr(ymd,1,7), count(*) FROM sales GROUP BY substr(ymd,1,7);","a":["2026-01,6"],"ex":"SQLite 의 substr 은 1부터 시작합니다. 컬럼을 함수로 감싸 그룹핑하면 그 컬럼의 인덱스를 쓸 수 없다는 점도 함께 기억하세요.","cat":"predict"},{"t":"input","k":"결과 예측","q":"결과 값은? (문자열 그대로)","code":"CREATE TABLE users (id INTEGER, name TEXT, city TEXT);\nINSERT INTO users VALUES (1,'가','서울'),(2,'나','부산'),(3,'다',NULL),(4,'라','서울');\nCREATE TABLE orders (id INTEGER, user_id INTEGER, total INTEGER);\nINSERT INTO orders VALUES (10,1,100),(11,1,200),(12,2,NULL),(13,9,50);\n\nSELECT group_concat(name, '-') FROM users WHERE city = '서울';","a":["가-라"],"ex":"group_concat 은 그룹의 값을 이어 붙입니다. 구분자를 두 번째 인자로 줄 수 있고, NULL 값은 건너뜁니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}},{"t":"결과 예측 VII","q":[{"t":"input","k":"결과 예측","q":"결과를 셀 순서대로 쉼표로 이어 적으세요","code":"CREATE TABLE t (n INTEGER, s TEXT);\nINSERT INTO t VALUES (1,'a'),(2,'b'),(3,NULL),(4,'a'),(NULL,'c');\n\nSELECT typeof(n), typeof(s) FROM t WHERE n IS NULL;","a":["null,text"],"ex":"SQLite 는 값마다 타입을 가지며 NULL 도 하나의 타입입니다. 컬럼 선언 타입과 실제 저장된 값의 타입이 다를 수 있는 동적 타입 시스템입니다.","cat":"predict"}],"th":{"sum":"쿼리를 읽고 결과를 먼저 적어 보는 훈련입니다. 행이 몇 개 나오는지, NULL 이 어떻게 취급되는지가 핵심입니다.","body":[{"h":"행 수부터 센다","t":"INNER JOIN 은 짝이 있는 행만, LEFT JOIN 은 왼쪽을 모두 남깁니다. 한쪽이 여러 건이면 <b>행이 늘어납니다</b>. 조인 조건이 없으면 카티션 곱입니다. 결과를 보기 전에 '몇 행이 나올까' 를 먼저 답할 수 있어야 합니다."},{"h":"NULL 은 값이 아니라 '모름' 이다","t":"<code>count(*)</code> 는 행을 세지만 <code>count(컬럼)</code> 과 <code>avg</code>·<code>sum</code> 은 NULL 을 무시합니다. <code>!= '서울'</code> 은 NULL 행을 빼고, <code>NOT IN</code> 에 NULL 이 섞이면 결과가 조용히 0건이 됩니다."},{"h":"GROUP BY 는 줄이고 윈도우는 줄이지 않는다","t":"집계는 그룹당 한 행으로 접지만 윈도우 함수는 행을 그대로 두고 옆에 값을 붙입니다. <code>rank</code> 는 동점 뒤를 건너뛰고 <code>dense_rank</code> 는 건너뛰지 않습니다."},{"h":"평가 순서를 기억한다","t":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. <code>WHERE</code> 는 집계 전에, <code>HAVING</code> 은 집계 후에 평가되고, LEFT JOIN 의 오른쪽 조건을 WHERE 에 두면 INNER JOIN 이 됩니다."}],"code":{"t":"NULL 하나가 결과를 0건으로 만든다","c":"SELECT count(*) FROM t\nWHERE s NOT IN (SELECT s FROM t WHERE n = 3);\n-- 서브쿼리가 NULL 을 돌려주면 결과는 항상 0"},"key":["조인은 행 수부터 예측한다","집계는 NULL 을 무시하고 count(*) 는 세지 않는다","rank 는 건너뛰고 dense_rank 는 안 건너뛴다","WHERE 는 집계 전, HAVING 은 집계 후"]}}]},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"자료구조 시각화","lv":2,"q":"인덱스 탐색과 풀스캔의 <b>읽은 행 수</b>를 비교하세요. 정렬된 인덱스에서는 이분 탐색으로 찾고, 풀스캔은 처음부터 훑습니다. <b>행을 읽을 때마다</b> <code>snap(라벨, {읽음:n, 위치:i})</code> 을 부르세요. 반환값은 <code>{index, scan}</code> 읽은 행 수입니다.","src":"const ROWS = [10, 20, 30, 40, 50, 60, 70, 80];\n\nfunction lookup(target) {\n  let indexReads = 0, scanReads = 0;\n  // 여기에 구현하세요 — 이분 탐색과 순차 스캔을 각각 세고 snap 을 부르세요\n  return { index: indexReads, scan: scanReads };\n}\n\nRESULT = lookup(70);","tests":[{"d":"인덱스는 3번 이하로 찾는다","js":"RESULT.index<=3"},{"d":"풀스캔은 7번 읽는다","js":"RESULT.scan===7"},{"d":"인덱스가 풀스캔보다 적게 읽는다","js":"RESULT.index<RESULT.scan"},{"d":"두 방식의 장면이 모두 남았다","js":"FRAMES.filter(f=>/인덱스/.test(f.label)).length>0 && FRAMES.filter(f=>/풀스캔/.test(f.label)).length>0"},{"d":"풀스캔은 위치가 0 부터 한 칸씩 나아간다","js":"(function(){var p=FRAMES.filter(f=>/풀스캔/.test(f.label)).map(f=>f.value['위치']);for(var i=0;i<p.length;i++) if(p[i]!==i) return false; return true;})()"}],"ex":"인덱스가 빠른 이유는 마법이 아니라 <b>읽는 행이 적어서</b>입니다. 8행에서는 7 대 3 이지만 100만 행이면 100만 대 20 이 됩니다. 그래서 실행 계획에서 봐야 할 것은 시간이 아니라 <code>rows</code> 입니다. 반대로 테이블이 아주 작거나 전체의 절반 이상을 읽어야 하면 <b>풀스캔이 더 빠릅니다</b> — 인덱스를 타면 행마다 테이블을 다시 찾아가는 비용이 붙기 때문입니다."},{"t":"sim","k":"알고리즘 시각화","lv":3,"q":"중첩 루프 조인과 해시 조인의 <b>비교 횟수</b>를 비교하세요. <b>비교하거나 해시를 조회할 때마다</b> <code>snap(라벨, {비교:n})</code> 을 부르세요. 반환값은 <code>{nested, hash, rows}</code> 입니다.","src":"const A = [{ id: 1 }, { id: 2 }, { id: 3 }];\nconst B = [{ aid: 2 }, { aid: 3 }, { aid: 3 }, { aid: 9 }];\n\nfunction join() {\n  let nested = 0, hash = 0, rows = 0;\n  // 여기에 구현하세요 — 두 방식으로 각각 조인하고 비교 횟수를 셉니다\n  return { nested: nested, hash: hash, rows: rows };\n}\n\nRESULT = join();","tests":[{"d":"조인 결과 행 수가 3 이다","js":"RESULT.rows===3"},{"d":"중첩 루프는 3×4 = 12번 비교한다","js":"RESULT.nested===12"},{"d":"해시 조인은 3+4 = 7번만 훑는다","js":"RESULT.hash===7"},{"d":"해시 조인이 더 적게 일한다","js":"RESULT.hash<RESULT.nested"},{"d":"두 방식의 장면이 모두 남았다","js":"FRAMES.filter(f=>/중첩/.test(f.label)).length===12 && FRAMES.filter(f=>/해시/.test(f.label)).length===7"}],"ex":"중첩 루프 조인은 O(N×M), 해시 조인은 O(N+M) 입니다. 그래서 옵티마이저는 큰 테이블끼리 붙일 때 해시 조인을 고릅니다. 다만 해시 조인은 <b>한쪽을 메모리에 다 올려야</b> 하므로 작업 메모리가 부족하면 디스크로 흘러 오히려 느려지고, 한쪽이 아주 작거나 인덱스가 있으면 중첩 루프가 이깁니다. '어느 조인이 좋다' 가 아니라 <b>데이터 크기가 정한다</b> 는 것이 요점입니다."},{"t":"sim","k":"상태 시각화","lv":3,"q":"두 트랜잭션이 같은 행을 건드릴 때의 <b>격리 수준</b>을 보이세요. READ COMMITTED 는 커밋된 값만 보이고, READ UNCOMMITTED 는 커밋 전 값까지 보입니다. <b>연산마다</b> <code>snap(라벨, {커밋값:c, T1이쓴값:w, T2가읽은값:r})</code> 를 부르세요. 반환값은 T2 가 읽은 값 배열입니다.","src":"function isolate(level) {\n  let committed = 100, written = null;\n  const seen = [];\n  // 여기에 구현하세요 — T1 이 150 으로 쓰고, T2 가 읽고, T1 이 롤백합니다\n  return seen;\n}\n\nRESULT = { rc: isolate('read committed'), ru: isolate('read uncommitted') };","tests":[{"d":"READ COMMITTED 는 커밋된 값만 본다","js":"JSON.stringify(RESULT.rc)==='[100,100,100]'"},{"d":"READ UNCOMMITTED 는 롤백될 값을 읽는다 (더티 리드)","js":"JSON.stringify(RESULT.ru)==='[100,150,100]'"},{"d":"두 수준의 장면이 모두 남았다","js":"FRAMES.filter(f=>/read committed/.test(f.label)).length===5 && FRAMES.filter(f=>/read uncommitted/.test(f.label)).length===5"},{"d":"커밋값은 끝까지 100 이다","js":"FRAMES.every(f=>f.value['커밋값']===100)"},{"d":"롤백 뒤에는 쓴 값이 사라진다","js":"FRAMES.filter(f=>/롤백/.test(f.label)).every(f=>f.value['T1이쓴값']===null)"}],"ex":"더티 리드는 '<b>없던 일이 될 값</b>' 을 읽는 것입니다. T1 이 150 을 쓰고 롤백했는데 T2 가 그사이 150 을 읽어 그걸로 계산하면, 근거가 사라진 결과가 남습니다. READ COMMITTED 는 이것만 막고, 같은 행을 두 번 읽을 때 값이 달라지는 <b>반복 불가능한 읽기</b>는 여전히 허용합니다 — 그것까지 막으려면 REPEATABLE READ 가 필요합니다. 격리 수준은 안전과 동시성을 맞바꾸는 다이얼입니다."},{"t":"sim","k":"자료구조 시각화","lv":4,"q":"MVCC 버전 체인을 만드세요. 각 트랜잭션은 <b>자기 시작 시점보다 이전에 커밋된</b> 가장 최신 버전을 봅니다. <b>쓰기·읽기마다</b> <code>snap(라벨, {버전:[...], 읽은값:v})</code> 을 부르세요. 반환값은 각 읽기의 결과 배열입니다.","src":"function mvcc(ops) {\n  const versions = [{ value: 'v0', at: 0 }];\n  const reads = [];\n  // 여기에 구현하세요 — ['write', 값, 커밋시각] 과 ['read', 시작시각]\n  return reads;\n}\n\nRESULT = mvcc([['read', 5], ['write', 'v1', 10], ['read', 5], ['read', 20]]);","tests":[{"d":"오래된 스냅숏은 옛 버전을 계속 본다","js":"JSON.stringify(RESULT)==='[\"v0\",\"v0\",\"v1\"]'"},{"d":"장면이 4개 기록됐다","js":"FRAMES.length===4"},{"d":"버전은 지워지지 않고 쌓인다","js":"(function(){for(var i=1;i<FRAMES.length;i++) if(FRAMES[i].value['버전'].length<FRAMES[i-1].value['버전'].length) return false; return true;})()"},{"d":"쓰기가 진행 중인 읽기를 막지 않는다","js":"(function(){var i=FRAMES.findIndex(f=>/쓰기/.test(f.label));return FRAMES[i+1].value['읽은값']==='v0';})()"},{"d":"나중에 시작한 읽기는 새 버전을 본다","js":"FRAMES[FRAMES.length-1].value['읽은값']==='v1'"}],"ex":"MVCC 의 핵심은 '<b>덮어쓰지 않고 새 버전을 쌓는다</b>' 입니다. 그래서 읽기가 쓰기를 막지 않고, 쓰기도 읽기를 막지 않습니다 — 락 없이 일관된 스냅숏을 봅니다. 대가는 <b>옛 버전이 쌓인다</b>는 것이고, 그래서 PostgreSQL 은 VACUUM 으로 청소합니다. 오래 열어 둔 트랜잭션 하나가 청소를 막아 테이블이 부푸는 사고가 여기서 나옵니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"상태 시각화","lv":3,"q":"행 잠금과 대기를 만드세요. 이미 잠긴 행을 요청하면 <b>대기</b>하고, 커밋하면 대기 중인 첫 트랜잭션이 잠급니다. <b>연산마다</b> <code>snap(라벨, {잠금:{...held}, 대기:[...wait]})</code> 을 부르세요. 반환값은 최종 대기 인원입니다.","src":"function locks(ops) {\n  const held = {};\n  const wait = [];\n  // 여기에 구현하세요 — ['lock', 트랜잭션, 행], ['commit', 트랜잭션]\n  return wait.length;\n}\n\nRESULT = locks([['lock','T1','r1'],['lock','T2','r1'],['lock','T3','r1'],['commit','T1'],['commit','T2']]);","tests":[{"d":"마지막에 T3 하나만 잠금을 쥐고 대기가 없다","js":"RESULT===0"},{"d":"장면이 5개 기록됐다","js":"FRAMES.length===5"},{"d":"한 행은 동시에 한 트랜잭션만 잠근다","js":"FRAMES.every(f=>Object.keys(f.value['잠금']).length<=1)"},{"d":"대기 줄이 최대 2까지 길어진다","js":"Math.max.apply(null,FRAMES.map(f=>f.value['대기'].length))===2"},{"d":"커밋하면 기다리던 트랜잭션이 곧바로 잠근다","js":"(function(){var i=FRAMES.findIndex(f=>/커밋 T1/.test(f.label));return FRAMES[i].value['잠금'].r1==='T2';})()"}],"ex":"쓰기 잠금은 한 행에 하나뿐이므로 뒤따라온 트랜잭션은 <b>줄을 섭니다</b>. 이 줄이 길어지면 커넥션 풀이 대기 트랜잭션으로 가득 차 서비스 전체가 멈춥니다 — 실무 장애의 흔한 모양입니다. 그래서 트랜잭션은 <b>짧게</b> 유지하고, 안에서 외부 API 를 호출하지 않습니다. 서로 다른 행을 반대 순서로 잠그면 교착이 되고, DB 는 대기 그래프에서 사이클을 찾아 한쪽을 죽입니다."},{"t":"sim","k":"알고리즘 시각화","lv":2,"q":"GROUP BY 를 해시 집계로 구현하세요. <b>행을 처리할 때마다</b> <code>snap(\"행 \"+i, {...집계})</code> 로 지금까지의 집계 상태를 기록하세요. 반환값은 그룹별 합계 객체입니다.","src":"const SALES = [\n  { city: '서울', amt: 100 }, { city: '부산', amt: 50 },\n  { city: '서울', amt: 30 },  { city: '대구', amt: 70 }, { city: '부산', amt: 20 }\n];\n\nfunction groupBy() {\n  const agg = {};\n  // 여기에 구현하세요 — 행마다 집계를 갱신하고 snap 을 부르세요\n  return agg;\n}\n\nRESULT = groupBy();","tests":[{"d":"그룹별 합계가 맞다","js":"RESULT['서울']===130 && RESULT['부산']===70 && RESULT['대구']===70"},{"d":"행마다 장면이 남았다","js":"FRAMES.length===5"},{"d":"그룹 수는 줄어들지 않는다","js":"(function(){for(var i=1;i<FRAMES.length;i++) if(Object.keys(FRAMES[i].value).length<Object.keys(FRAMES[i-1].value).length) return false; return true;})()"},{"d":"각 그룹의 합계도 줄어들지 않는다","js":"(function(){for(var i=1;i<FRAMES.length;i++) for(var k in FRAMES[i-1].value) if(FRAMES[i].value[k]<FRAMES[i-1].value[k]) return false; return true;})()"},{"d":"한 번만 훑는다 (행 수만큼만 장면이 있다)","js":"FRAMES.length===5"}],"ex":"해시 집계는 테이블을 <b>한 번만</b> 훑으면서 그룹별 누적값을 해시 표에 유지합니다 — 정렬이 필요 없어 O(n) 입니다. 그래서 실행 계획에 <code>HashAggregate</code> 가 보이면 정렬 없이 처리 중이라는 뜻이고, <code>GroupAggregate</code> 가 보이면 먼저 정렬하고 있다는 뜻입니다. 그룹 수가 너무 많아 해시 표가 메모리를 넘으면 디스크로 흘러 느려지므로, 옵티마이저는 <b>추정 그룹 수</b>를 보고 둘 중 하나를 고릅니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"쿼리 시뮬레이션","lv":3,"q":"<b>인덱스를 못 타는 조건</b>을 판정하세요. 조건마다 인덱스 사용 여부를 <code>snap</code> 으로 기록하고 <b>풀스캔이 되는 조건 수</b>를 돌려주세요.","src":"const CONDS = [\n  \"created_at >= '2026-01-01'\",\n  \"DATE(created_at) = '2026-01-01'\",\n  \"name LIKE 'kim%'\",\n  \"name LIKE '%kim'\",\n  \"status = 'paid'\",\n  \"UPPER(email) = 'A@X.COM'\"\n];\n\nfunction plan() {\n  let scans = 0;\n  // 여기에 구현하세요 — 컬럼이 함수로 감싸이거나 앞에 와일드카드가 있으면 못 탑니다\n  return scans;\n}\n\nRESULT = plan();","tests":[{"d":"풀스캔이 되는 조건은 3개다","js":"RESULT===3"},{"d":"조건마다 장면이 기록된다","js":"FRAMES.length===6"},{"d":"범위 조건은 인덱스를 탄다","js":"FRAMES[0].opt.indexed===true"},{"d":"함수로 감싼 컬럼은 인덱스를 못 탄다","js":"FRAMES[1].opt.indexed===false"},{"d":"뒤쪽 와일드카드는 인덱스를 탄다","js":"FRAMES[2].opt.indexed===true"}],"ex":"인덱스는 <b>컬럼의 값 순서</b>로 만들어져 있습니다. 컬럼을 함수로 감싸면 <b>다른 값</b>이 되므로 정렬된 순서를 쓸 수 없고, 앞에 와일드카드가 붙으면 <b>어디서 시작할지</b>를 알 수 없습니다. 그래서 <code>DATE(created_at) = '...'</code> 는 <code>created_at &gt;= '...' AND &lt; '...'</code> 로 바꿔 씁니다. 함수를 꼭 써야 한다면 <b>표현식 인덱스</b>를 따로 만들면 됩니다."},{"t":"sim","k":"쿼리 시뮬레이션","lv":3,"q":"<b>복합 인덱스의 컬럼 순서</b>를 판정하세요. 인덱스가 <code>(status, created_at)</code> 일 때 각 조건 조합이 인덱스를 <b>얼마나 활용하는지</b>(0=못 탐, 1=앞 컬럼만, 2=둘 다) 기록하고 총점을 돌려주세요.","src":"const QUERIES = [\n  ['status'],\n  ['created_at'],\n  ['status', 'created_at'],\n  ['created_at', 'status']\n];\nconst INDEX = ['status', 'created_at'];\n\nfunction usage() {\n  let total = 0;\n  // 여기에 구현하세요 — 인덱스는 앞 컬럼부터 순서대로만 쓸 수 있습니다\n  return total;\n}\n\nRESULT = usage();","tests":[{"d":"총 활용 점수는 5다","js":"RESULT===5"},{"d":"질의마다 장면이 기록된다","js":"FRAMES.length===4"},{"d":"앞 컬럼만 있으면 1이다","js":"FRAMES[0].value[0]===1"},{"d":"뒤 컬럼만 있으면 0이다","js":"FRAMES[1].value[0]===0"},{"d":"조건에 적는 순서는 상관없다","js":"FRAMES[2].value[0]===FRAMES[3].value[0]"}],"ex":"복합 인덱스는 <b>전화번호부</b>와 같습니다 — 성으로는 찾을 수 있지만 이름만으로는 찾을 수 없습니다. 그래서 <code>(status, created_at)</code> 인덱스는 <code>created_at</code> 단독 조건에 쓸모가 없습니다. 반대로 <b>조건을 적는 순서는 상관없습니다</b> — 옵티마이저가 알아서 맞춥니다. 설계 요령은 <b>등호 조건 컬럼을 앞에, 범위 조건을 뒤에</b> 두는 것입니다."},{"t":"sim","k":"조인 시뮬레이션","lv":3,"q":"<b>중첩 루프 조인과 해시 조인</b>의 비교 횟수를 세어 보세요. 왼쪽 1,000행·오른쪽 10,000행일 때 각각의 <b>연산 수</b>를 <code>[중첩루프, 해시]</code> 로 돌려주세요.","src":"const L = 1000, R = 10000;\n\nfunction joins() {\n  // 중첩 루프: 왼쪽마다 오른쪽 전체를 훑는다\n  // 해시: 오른쪽으로 해시 테이블을 만들고 왼쪽을 한 번 훑는다\n  return [0, 0];\n}\n\nRESULT = joins();","tests":[{"d":"중첩 루프는 1,000만 번 비교한다","js":"RESULT[0]===10000000"},{"d":"해시 조인은 11,000 번이면 된다","js":"RESULT[1]===11000"},{"d":"해시가 1,000배 가까이 적다","js":"RESULT[0]/RESULT[1]>500"},{"d":"두 방식의 장면이 기록된다","js":"FRAMES.length===2"},{"d":"기록된 값이 반환값과 같다","js":"FRAMES[0].value[0]===RESULT[0]&&FRAMES[1].value[0]===RESULT[1]"}],"ex":"조인 방식의 선택이 <b>세 자릿수 차이</b>를 만듭니다. 중첩 루프는 한쪽이 아주 작거나 <b>인덱스가 있을 때</b>(그러면 전체를 훑지 않습니다) 유리하고, 해시 조인은 큰 테이블끼리 등호 조인에 강합니다. 실행 계획에서 <code>Nested Loop</code> 가 큰 테이블 둘 사이에 나타나면 <b>통계가 틀렸거나 인덱스가 없다는 신호</b>입니다 — 옵티마이저는 행 수 추정에 기반해 고르기 때문입니다."},{"t":"sim","k":"트랜잭션 시뮬레이션","lv":4,"q":"<b>팬텀 리드</b>를 모델링하세요. T1 이 같은 범위를 두 번 세는 사이 T2 가 그 범위에 행을 추가합니다. READ COMMITTED 와 SERIALIZABLE 각각의 <b>두 번째 개수</b>를 <code>[rc, ser]</code> 로 돌려주세요.","src":"function phantom() {\n  let rows = [1, 2, 3];   // 조건에 맞는 행\n  return [0, 0];\n}\n\nRESULT = phantom();","tests":[{"d":"READ COMMITTED 의 두 번째 개수는 4다","js":"RESULT[0]===4"},{"d":"직렬화 수준에서는 개수가 변하지 않는다","js":"(function(){const s=FRAMES.filter(f=>f.opt.level==='SER');return s[0].value[0]===s[1].value[0];})()"},{"d":"RC 에서는 두 번의 개수가 다르다","js":"(function(){const r=FRAMES.filter(f=>f.opt.level==='RC');return r[0].value[0]!==r[1].value[0];})()"},{"d":"네 번의 조회가 기록된다","js":"FRAMES.length===4"},{"d":"개수가 음수가 되지 않는다","js":"FRAMES.every(f=>f.value[0]>=0)"}],"ex":"팬텀은 <b>행의 값이 아니라 개수</b>가 달라지는 현상입니다 — 잠금은 이미 존재하는 행에만 걸리므로, <b>새로 들어오는 행</b>은 막지 못합니다. 그래서 '예약이 정원을 넘지 않는지 세고 삽입' 같은 로직은 격리 수준만으로 안전해지지 않습니다. 해법은 <b>범위 잠금</b>(SERIALIZABLE·predicate lock)이나, 애초에 <b>DB 제약</b>으로 조건을 표현하는 것입니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 IV","q":[{"t":"sim","k":"쿼리 시뮬레이션","lv":2,"q":"<b>NULL 의 삼치 논리</b>를 판정하세요. 각 비교의 결과를 true·false·unknown 으로 기록하고, <b>WHERE 절을 통과하는 조건 수</b>를 돌려주세요(unknown 은 통과하지 못합니다).","src":"const TESTS = [\n  'NULL = NULL',\n  'NULL <> NULL',\n  'NULL IS NULL',\n  '1 = NULL',\n  'NULL IN (1,2)',\n  'NOT (NULL = 1)'\n];\n\nfunction threeValued() {\n  let passed = 0;\n  // 여기에 구현하세요 — NULL 이 낀 비교는 IS NULL 을 빼면 전부 unknown 입니다\n  return passed;\n}\n\nRESULT = threeValued();","tests":[{"d":"통과하는 조건은 1개뿐이다","js":"RESULT===1"},{"d":"조건마다 장면이 기록된다","js":"FRAMES.length===6"},{"d":"NULL = NULL 은 unknown 이다","js":"FRAMES[0].opt.result==='unknown'"},{"d":"IS NULL 만 true 다","js":"FRAMES[2].opt.result==='true'"},{"d":"NOT 을 붙여도 unknown 은 그대로다","js":"FRAMES[5].opt.result==='unknown'"}],"ex":"SQL 은 <b>참·거짓·모름</b> 세 값을 씁니다. <code>NULL</code> 은 '값이 없음' 이 아니라 <b>'모름'</b> 이므로, 모르는 값끼리 같은지도 알 수 없습니다(<code>NULL = NULL</code> 은 참이 아닙니다). WHERE 는 <b>참인 행만</b> 통과시키므로 unknown 은 걸러집니다. 여기서 <code>NOT IN (서브쿼리)</code> 안에 NULL 이 하나라도 있으면 <b>결과가 통째로 비는</b> 악명 높은 함정이 나옵니다 — <code>NOT EXISTS</code> 를 쓰는 이유입니다."},{"t":"sim","k":"쿼리 시뮬레이션","lv":3,"q":"<b>GROUP BY 와 집계</b>의 처리 순서를 모델링하세요. WHERE 는 그룹 전, HAVING 은 그룹 후에 적용됩니다. 각 단계의 행 수를 <code>snap</code> 으로 기록하고 <b>최종 그룹 수</b>를 돌려주세요.","src":"const ROWS = [\n  {cat:'a', amt:100}, {cat:'a', amt:50}, {cat:'b', amt:300},\n  {cat:'b', amt:20},  {cat:'c', amt:10}, {cat:'c', amt:5}\n];\n\nfunction agg() {\n  // WHERE amt >= 20 → GROUP BY cat → HAVING SUM(amt) >= 100\n  return 0;\n}\n\nRESULT = agg();","tests":[{"d":"최종 그룹은 2개다","js":"RESULT===2"},{"d":"네 단계가 기록된다","js":"FRAMES.length===4"},{"d":"WHERE 가 행을 먼저 줄인다","js":"FRAMES[1].value[0]<FRAMES[0].value[0]"},{"d":"GROUP BY 단계에서 행이 그룹으로 접힌다","js":"FRAMES[2].value[0]<FRAMES[1].value[0]"},{"d":"HAVING 은 그룹 수를 줄인다","js":"FRAMES[3].value[0]<=FRAMES[2].value[0]"}],"ex":"순서를 알면 <b>WHERE 와 HAVING 의 차이</b>가 분명해집니다 — WHERE 는 <b>행</b>을 거르고 HAVING 은 <b>그룹</b>을 거릅니다. 그래서 집계 함수는 HAVING 에만 쓸 수 있고, 반대로 <b>행 단위 조건을 HAVING 에 쓰면</b> 불필요하게 많은 행을 그룹으로 만든 뒤 버리게 되어 느립니다. 가능한 한 <b>일찍 거르는 것</b>이 언제나 유리합니다."},{"t":"sim","k":"트랜잭션 시뮬레이션","lv":3,"q":"<b>롤백과 부분 커밋</b>을 모델링하세요. 트랜잭션 안에서 여러 작업을 하다 중간에 실패합니다. 저장점(savepoint)이 있을 때와 없을 때 <b>남는 작업 수</b>를 <code>[없음, 있음]</code> 으로 돌려주세요.","src":"const OPS = ['insert A', 'insert B', 'FAIL', 'insert C'];\n\nfunction tx() {\n  return [0, 0];\n}\n\nRESULT = tx();","tests":[{"d":"저장점이 없으면 전부 롤백된다","js":"RESULT[0]===0"},{"d":"저장점이 있으면 실패 이후 작업이 이어진다","js":"RESULT[1]===3"},{"d":"두 방식의 장면이 모두 기록된다","js":"FRAMES.some(f=>f.opt.mode==='no-savepoint') && FRAMES.some(f=>f.opt.mode==='savepoint')"},{"d":"롤백 장면이 두 번 있다","js":"FRAMES.filter(f=>/롤백/.test(f.label)).length===2"},{"d":"완료 수가 음수가 되지 않는다","js":"FRAMES.every(f=>f.value[0]>=0)"}],"ex":"트랜잭션의 기본은 <b>전부 아니면 전무</b>입니다 — 중간 실패는 처음 상태로 되돌립니다. <b>저장점</b>은 그 안에 작은 되돌림 지점을 만들어, 실패한 부분만 취소하고 나머지를 이어갈 수 있게 합니다(대량 처리에서 유용). 다만 저장점을 남발하면 <b>원자성이라는 보장이 흐려집니다</b> — '어디까지 반영됐는지' 를 호출자가 알 수 있어야 의미가 있습니다."},{"t":"sim","k":"쿼리 시뮬레이션","lv":2,"q":"<b>SELECT * 의 비용</b>을 계산하세요. 테이블에 컬럼 20개(총 2KB/행)가 있고 필요한 것은 3개(120B/행)입니다. 10만 행을 읽을 때 <b>전송 바이트</b>를 <code>[전체, 필요분]</code> 으로 돌려주세요.","src":"const ROWS = 100000, FULL_B = 2048, NEEDED_B = 120;\n\nfunction cost() {\n  return [0, 0];\n}\n\nRESULT = cost();","tests":[{"d":"전체 조회는 204,800,000 바이트다","js":"RESULT[0]===204800000"},{"d":"필요분만 읽으면 12,000,000 바이트다","js":"RESULT[1]===12000000"},{"d":"17배 가까이 차이 난다","js":"RESULT[0]/RESULT[1]>15"},{"d":"두 방식의 장면이 기록된다","js":"FRAMES.length===2"},{"d":"MB 환산이 기록돼 있다","js":"FRAMES.every(f=>typeof f.opt.mb==='number')"}],"ex":"<code>SELECT *</code> 의 비용은 전송량만이 아닙니다 — <b>커버링 인덱스</b>를 무력화하는 것이 더 큽니다. 필요한 컬럼이 인덱스 안에 다 있으면 테이블을 읽지 않아도 되는데, <code>*</code> 는 반드시 테이블까지 가게 만듭니다. 게다가 나중에 컬럼이 추가되면 <b>질의를 고치지 않아도 응답이 커지고</b>, 민감 컬럼이 의도치 않게 흘러나갑니다. 명시적으로 적는 편이 언제나 낫습니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}]},{"t":"디버깅 실전 — 고장난 쿼리 고치기 (실행 채점)","l":[{"t":"고장난 쿼리 고치기 I — NULL 과 조인","xp":70,"th":{"sum":"SQL 버그의 절반은 **NULL** 과 **조인이 남기는 행**에서 나온다. 오류가 아니라 '행이 조용히 사라지거나 늘어나는' 형태라 더 오래 산다.","body":[{"h":"NULL 은 값이 아니라 '모름' 이다","t":"`= NULL` 은 참도 거짓도 아닌 UNKNOWN 이라 아무 행도 통과하지 못한다 — `IS NULL` 을 써야 한다. 부정 조건은 더 위험하다. `NOT IN` 의 서브쿼리에 NULL 이 **하나만** 섞여도 결과가 통째로 비고, `COUNT(col)`·`AVG(col)` 은 NULL 행을 조용히 빼고 센다. NULL 을 허용하는 컬럼에 조건을 걸 때는 NULL 을 어떻게 볼지 쿼리에 적어야 한다."},{"h":"조인은 행을 없애거나 곱한다","t":"`LEFT JOIN` 으로 살려 둔 NULL 행을 `WHERE` 가 다시 걸러내면 결국 INNER JOIN 이 된다 — 오른쪽 테이블 조건은 `ON` 으로 옮긴다. 반대로 1:N 테이블을 **둘 이상** 조인하면 행이 곱해져(팬아웃) 합계와 개수가 부풀려진다. 집계 대상이 둘이면 각각 집계한 뒤 합쳐야 한다."}],"code":{"c":"SELECT d.dept, SUM(s.amount)\nFROM depts d LEFT JOIN spend s ON s.dept_id = d.id\nWHERE s.yr = 2024        -- ← 여기서 LEFT JOIN 이 무효가 된다\nGROUP BY d.dept;","cap":"오른쪽 테이블 조건이 WHERE 에 있으면 LEFT JOIN 이 아니다"},"key":["`= NULL` 이 아니라 `IS NULL` — 부정 조건은 NULL 을 삼킨다","`NOT IN` 서브쿼리에 NULL 이 있으면 결과가 통째로 빈다 → `NOT EXISTS`","LEFT JOIN 뒤 WHERE 에 오른쪽 컬럼이 나오면 거의 항상 버그","1:N 을 둘 이상 조인하면 팬아웃 — 각각 집계한 뒤 합친다"]},"q":[{"t":"sql","k":"LEFT JOIN 을 WHERE 가 INNER JOIN 으로 되돌린다","cat":"debug","q":"모든 부서를 나열하되 각 부서의 2024년 지출 합계를 함께 보여줘야 합니다. 지출이 한 건도 없는 부서도 0 으로 나와야 하는데 아예 사라집니다. dept, spent 두 컬럼을 dept 오름차순으로 출력하세요.","schema":"CREATE TABLE depts (id INTEGER, dept TEXT);\nINSERT INTO depts VALUES (1,'개발'),(2,'디자인'),(3,'법무');\nCREATE TABLE spend (dept_id INTEGER, yr INTEGER, amount INTEGER);\nINSERT INTO spend VALUES (1,2024,100),(1,2024,200),(2,2023,500),(2,2024,50);","src":"SELECT d.dept, COALESCE(SUM(s.amount),0) AS spent\nFROM depts d\nLEFT JOIN spend s ON s.dept_id = d.id\nWHERE s.yr = 2024\nGROUP BY d.dept\nORDER BY d.dept;","sol":"SELECT d.dept, COALESCE(SUM(s.amount),0) AS spent\nFROM depts d\nLEFT JOIN spend s ON s.dept_id = d.id AND s.yr = 2024\nGROUP BY d.dept\nORDER BY d.dept;","ordered":true,"ex":"🐛 원인: LEFT JOIN 이 오른쪽에 짝이 없는 행을 NULL 로 채워 살려 놓아도, WHERE s.yr = 2024 가 그 NULL 행을 다시 걸러냅니다. 결과적으로 INNER JOIN 과 같아져 법무(지출 없음)와 디자인(2024 건은 있으나 2023 건만 매칭됐다면)까지 사라집니다.\n🔧 해결: 오른쪽 테이블에 대한 조건은 ON 절로 옮깁니다. 그러면 조인 단계에서 걸러지고 짝 없는 왼쪽 행은 NULL 로 남습니다.\n🛡 재발 방지: LEFT JOIN 을 쓴 뒤 WHERE 에 오른쪽 테이블 컬럼이 등장하면 거의 항상 버그입니다. 'NULL 을 남기고 싶은가' 를 기준으로 ON 과 WHERE 를 나누세요."},{"t":"sql","k":"NOT IN 과 NULL","cat":"debug","q":"한 번도 주문하지 않은 고객의 이름을 name 오름차순으로 출력해야 하는데, 결과가 아예 비어 있습니다.","schema":"CREATE TABLE customers (id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'김'),(2,'박'),(3,'이');\nCREATE TABLE orders (id INTEGER, customer_id INTEGER);\nINSERT INTO orders VALUES (10,1),(11,NULL),(12,3);","src":"SELECT name FROM customers\nWHERE id NOT IN (SELECT customer_id FROM orders)\nORDER BY name;","sol":"SELECT name FROM customers\nWHERE id NOT IN (SELECT customer_id FROM orders WHERE customer_id IS NOT NULL)\nORDER BY name;","ordered":true,"ex":"🐛 원인: 서브쿼리 결과에 NULL 이 하나라도 있으면 NOT IN 은 어떤 값에 대해서도 참이 될 수 없습니다. 'x &lt;&gt; NULL' 이 참도 거짓도 아닌 UNKNOWN 이기 때문입니다. 그래서 결과가 통째로 비어 버립니다.\n🔧 해결: 서브쿼리에서 NULL 을 걸러냅니다. NOT EXISTS 로 바꾸면 NULL 에 영향받지 않아 더 안전합니다.\n🛡 재발 방지: NOT IN 의 서브쿼리 컬럼이 NULL 을 허용하는지 항상 확인하세요. 습관적으로 NOT EXISTS 를 쓰면 이 함정을 통째로 피할 수 있습니다."},{"t":"sql","k":"조인 팬아웃이 합계를 부풀린다","cat":"debug","q":"주문별 결제 총액과 상품 개수를 함께 보고 싶습니다. 결제가 여러 건인 주문에서 상품 개수가 실제보다 크게 나옵니다. order_id, paid, items 를 order_id 오름차순으로 출력하세요.","schema":"CREATE TABLE items (order_id INTEGER, sku TEXT);\nINSERT INTO items VALUES (1,'A'),(1,'B'),(2,'C');\nCREATE TABLE pays (order_id INTEGER, amount INTEGER);\nINSERT INTO pays VALUES (1,300),(1,700),(2,500);","src":"SELECT i.order_id, SUM(p.amount) AS paid, COUNT(i.sku) AS items\nFROM items i\nJOIN pays p ON p.order_id = i.order_id\nGROUP BY i.order_id\nORDER BY i.order_id;","sol":"SELECT i.order_id,\n  (SELECT SUM(p.amount) FROM pays p WHERE p.order_id = i.order_id) AS paid,\n  COUNT(i.sku) AS items\nFROM items i\nGROUP BY i.order_id\nORDER BY i.order_id;","ordered":true,"ex":"🐛 원인: 두 개의 1:N 테이블을 함께 조인하면 행이 곱해집니다. 주문 1은 상품 2건 × 결제 2건 = 4행이 되어 상품 개수가 2가 아니라 4로, 결제 합계도 두 배로 집계됩니다.\n🔧 해결: 한쪽만 조인하고 나머지는 스칼라 서브쿼리(또는 각각 집계한 뒤 조인)로 가져옵니다.\n🛡 재발 방지: 한 쿼리에서 1:N 테이블을 둘 이상 조인하면서 집계하면 거의 항상 팬아웃입니다. 집계 대상이 두 개 이상이면 먼저 각각 집계한 뒤 조인하세요."},{"t":"sql","k":"COUNT(컬럼) 은 NULL 을 세지 않는다","cat":"debug","q":"부서별 직원 수를 세는데, 이메일이 없는 직원이 빠집니다. dept, n 을 dept 오름차순으로 출력하세요.","schema":"CREATE TABLE emp (dept TEXT, name TEXT, email TEXT);\nINSERT INTO emp VALUES ('개발','김','k@x'),('개발','박',NULL),('영업','이',NULL),('영업','최','c@x');","src":"SELECT dept, COUNT(email) AS n FROM emp GROUP BY dept ORDER BY dept;","sol":"SELECT dept, COUNT(*) AS n FROM emp GROUP BY dept ORDER BY dept;","ordered":true,"ex":"🐛 원인: COUNT(email) 은 email 이 NULL 이 아닌 행만 셉니다. '직원 수' 를 물었는데 '이메일 있는 직원 수' 를 센 것입니다.\n🔧 해결: 행 수를 세려면 COUNT(*) 를 씁니다.\n🛡 재발 방지: COUNT(*) 는 행 수, COUNT(col) 은 NULL 이 아닌 값의 수, COUNT(DISTINCT col) 은 서로 다른 값의 수입니다. 세 개를 구분해서 쓰세요."},{"t":"sql","k":"WHERE 로는 집계를 거를 수 없다","cat":"debug","q":"주문이 2건 이상인 고객만 골라 customer, n 을 customer 오름차순으로 출력해야 하는데 쿼리가 실행되지 않습니다.","schema":"CREATE TABLE orders (id INTEGER, customer TEXT);\nINSERT INTO orders VALUES (1,'김'),(2,'김'),(3,'박'),(4,'이'),(5,'이'),(6,'이');","src":"SELECT customer, COUNT(*) AS n\nFROM orders\nWHERE COUNT(*) >= 2\nGROUP BY customer\nORDER BY customer;","sol":"SELECT customer, COUNT(*) AS n\nFROM orders\nGROUP BY customer\nHAVING COUNT(*) >= 2\nORDER BY customer;","ordered":true,"ex":"🐛 원인: WHERE 는 그룹으로 묶기 '전' 에 개별 행을 거릅니다. 그 시점에는 COUNT(*) 라는 값이 존재하지 않습니다.\n🔧 해결: 집계 결과로 거를 때는 GROUP BY 뒤의 HAVING 을 씁니다.\n🛡 재발 방지: WHERE 는 행 필터, HAVING 은 그룹 필터입니다. 성능상 행 단위로 거를 수 있는 조건은 WHERE 에 두어 집계 대상을 먼저 줄이세요."},{"t":"sql","k":"= NULL 은 아무것도 찾지 못한다","cat":"debug","q":"배송지가 입력되지 않은 주문을 찾아야 하는데 결과가 비어 있습니다. id 를 오름차순으로 출력하세요.","schema":"CREATE TABLE orders (id INTEGER, address TEXT);\nINSERT INTO orders VALUES (1,'서울'),(2,NULL),(3,''),(4,NULL);","src":"SELECT id FROM orders WHERE address = NULL ORDER BY id;","sol":"SELECT id FROM orders WHERE address IS NULL ORDER BY id;","ordered":true,"ex":"🐛 원인: NULL 은 '값이 없음' 이라 어떤 값과도 같지 않고, NULL 과도 같지 않습니다. address = NULL 은 항상 UNKNOWN 이라 WHERE 를 통과하는 행이 없습니다.\n🔧 해결: IS NULL / IS NOT NULL 을 씁니다.\n🛡 재발 방지: 빈 문자열 ''과 NULL 은 다릅니다. 이 데이터에는 둘 다 있으니, '미입력' 의 정의를 먼저 정하고 필요하면 address IS NULL OR address = '' 로 명시하세요."},{"t":"sql","k":"UNION 이 중복을 지운다","cat":"debug","q":"올해와 작년의 구매 이력을 모두 이어 붙여 전체 건수를 봐야 합니다. 같은 금액이 반복된 건이 사라져 건수가 모자랍니다. amount 를 오름차순으로 출력하세요.","schema":"CREATE TABLE y2024 (amount INTEGER);\nINSERT INTO y2024 VALUES (100),(100),(200);\nCREATE TABLE y2023 (amount INTEGER);\nINSERT INTO y2023 VALUES (100),(300);","src":"SELECT amount FROM y2024\nUNION\nSELECT amount FROM y2023\nORDER BY amount;","sol":"SELECT amount FROM y2024\nUNION ALL\nSELECT amount FROM y2023\nORDER BY amount;","ordered":true,"ex":"🐛 원인: UNION 은 두 결과를 합친 뒤 중복 행을 제거합니다. 100원짜리 구매가 세 건 있어도 한 건으로 줄어듭니다.\n🔧 해결: 중복을 유지하려면 UNION ALL 을 씁니다. 중복 제거를 위한 정렬·해싱도 사라져 더 빠릅니다.\n🛡 재발 방지: 기본값이 UNION(중복 제거)이라는 점이 함정입니다. 이력·로그처럼 '건수' 가 의미 있는 데이터에는 항상 UNION ALL 을 쓰세요."},{"t":"sql","k":"정수 나눗셈이 소수를 버린다","cat":"debug","q":"부서별 평균 급여를 소수점 이하까지 보고 싶은데 전부 정수로 잘려 나옵니다. dept, avg_pay 를 dept 오름차순으로 출력하세요.","schema":"CREATE TABLE pay (dept TEXT, amount INTEGER);\nINSERT INTO pay VALUES ('개발',100),('개발',101),('영업',200),('영업',201),('영업',203);","src":"SELECT dept, SUM(amount)/COUNT(*) AS avg_pay\nFROM pay GROUP BY dept ORDER BY dept;","sol":"SELECT dept, SUM(amount)*1.0/COUNT(*) AS avg_pay\nFROM pay GROUP BY dept ORDER BY dept;","ordered":true,"ex":"🐛 원인: 정수끼리 나누면 SQLite 는 정수 나눗셈을 해 소수를 버립니다. 100.5 가 100 이 됩니다.\n🔧 해결: 한쪽에 1.0 을 곱해 실수 연산으로 만듭니다. CAST(SUM(amount) AS REAL) 이나 그냥 AVG(amount) 도 같은 결과입니다.\n🛡 재발 방지: 비율·평균·전환율처럼 소수가 나와야 하는 계산은 나누기 전에 타입을 확인하세요. 방언마다 정수 나눗셈 규칙이 달라 이식할 때도 자주 깨집니다."}]},{"t":"고장난 쿼리 고치기 II — 집계와 그룹","xp":70,"th":{"sum":"`WHERE` 와 `HAVING`, `COUNT(*)` 와 `COUNT(DISTINCT)`, `UNION` 과 `UNION ALL` — 이름이 비슷한 짝들이 전혀 다른 값을 낸다.","body":[{"h":"거르는 시점이 결과를 바꾼다","t":"`WHERE` 는 그룹으로 묶기 **전**에 개별 행을 거르고, `HAVING` 은 묶은 **뒤**에 그룹을 거른다. '평균이 200 이상인 카테고리' 를 `WHERE price >= 200` 으로 쓰면 200 미만 행이 먼저 사라져 평균 자체가 달라진다. 요구사항의 주어가 행인지 그룹인지 먼저 정한다."},{"h":"세는 대상을 정확히 말한다","t":"`COUNT(*)` 는 행 수, `COUNT(col)` 은 NULL 아닌 값의 수, `COUNT(DISTINCT col)` 은 서로 다른 값의 수다. '구매 고객 수' 를 `COUNT(customer)` 로 세면 같은 사람이 여러 번 세어진다. `UNION` 도 기본이 중복 제거라, 건수가 의미 있는 이력·로그에는 `UNION ALL` 을 써야 한다."}],"code":{"c":"-- 평균이 200 이상인 카테고리\nWHERE price >= 200   -- ✗ 200 미만 행을 먼저 지워 평균이 바뀐다\nHAVING AVG(price) >= 200  -- ✓ 평균을 낸 뒤 그룹을 고른다","cap":"행 필터와 그룹 필터는 다른 값을 낸다"},"key":["`WHERE` 는 행 필터, `HAVING` 은 그룹 필터","`COUNT(*)` / `COUNT(col)` / `COUNT(DISTINCT col)` 은 전부 다른 수","`UNION` 은 중복을 지운다 — 건수가 중요하면 `UNION ALL`","정수끼리 나누면 소수가 잘린다 — `*1.0` 이나 `CAST`"]},"q":[{"t":"sql","k":"AND 가 OR 보다 먼저 묶인다","cat":"debug","q":"결제가 완료된 주문 중 금액이 100 미만이거나 10000 초과인 '이상 거래' 를 찾아야 합니다. 취소된 주문까지 섞여 나옵니다. id 를 오름차순으로 출력하세요.","schema":"CREATE TABLE orders (id INTEGER, status TEXT, amount INTEGER);\nINSERT INTO orders VALUES (1,'완료',50),(2,'취소',20000),(3,'완료',20000),(4,'완료',500),(5,'취소',10);","src":"SELECT id FROM orders\nWHERE status = '완료' AND amount < 100 OR amount > 10000\nORDER BY id;","sol":"SELECT id FROM orders\nWHERE status = '완료' AND (amount < 100 OR amount > 10000)\nORDER BY id;","ordered":true,"ex":"🐛 원인: AND 가 OR 보다 우선순위가 높아 조건이 (status='완료' AND amount&lt;100) OR (amount&gt;10000) 로 묶입니다. 뒤쪽 OR 가지에는 상태 조건이 걸리지 않아 취소된 고액 주문까지 통과합니다.\n🔧 해결: 묶고 싶은 범위에 괄호를 칩니다.\n🛡 재발 방지: AND 와 OR 를 한 WHERE 절에 섞을 때는 우선순위를 외우지 말고 괄호를 치세요. 리뷰에서도 괄호 없는 AND/OR 혼용은 그 자체로 지적 대상입니다."},{"t":"sql","k":"CASE 에 ELSE 가 없어 NULL 이 된다","cat":"debug","q":"점수를 등급으로 바꿉니다. 60점 미만이 NULL 로 나옵니다. '하' 로 표시되어야 합니다. name, grade 를 name 오름차순으로 출력하세요.","schema":"CREATE TABLE score (name TEXT, pt INTEGER);\nINSERT INTO score VALUES ('김',95),('박',75),('이',40),('최',20);","src":"SELECT name,\n  CASE WHEN pt >= 90 THEN '상'\n       WHEN pt >= 60 THEN '중'\n  END AS grade\nFROM score ORDER BY name;","sol":"SELECT name,\n  CASE WHEN pt >= 90 THEN '상'\n       WHEN pt >= 60 THEN '중'\n       ELSE '하'\n  END AS grade\nFROM score ORDER BY name;","ordered":true,"ex":"🐛 원인: CASE 의 모든 WHEN 이 거짓이고 ELSE 가 없으면 결과는 NULL 입니다. 오류가 아니라 조용히 빈 값이 되어 화면에는 빈칸으로 보입니다.\n🔧 해결: ELSE 를 명시해 나머지 경우를 정의합니다.\n🛡 재발 방지: CASE 에는 항상 ELSE 를 쓰세요. '있을 수 없는 경우' 라도 ELSE '미분류' 를 두면 데이터 이상을 바로 알아챌 수 있습니다."},{"t":"sql","k":"AVG 는 NULL 을 빼고 계산한다","cat":"debug","q":"설문 응답 점수의 평균을 냅니다. 무응답(NULL)을 0점으로 쳐야 하는데 아예 빠져서 평균이 높게 나옵니다. avg_pt 한 컬럼을 출력하세요.","schema":"CREATE TABLE survey (id INTEGER, pt INTEGER);\nINSERT INTO survey VALUES (1,10),(2,NULL),(3,20),(4,NULL);","src":"SELECT AVG(pt) AS avg_pt FROM survey;","sol":"SELECT AVG(COALESCE(pt,0)) AS avg_pt FROM survey;","ordered":true,"ex":"🐛 원인: AVG 는 NULL 인 행을 분모에서도 빼 버립니다. (10+20)/2 = 15 가 되지만, 무응답을 0점으로 치면 (10+0+20+0)/4 = 7.5 여야 합니다.\n🔧 해결: COALESCE 로 NULL 을 0 으로 바꾼 뒤 평균을 냅니다.\n🛡 재발 방지: 집계 함수는 전부 NULL 을 건너뜁니다. '무응답을 0으로 볼 것인가, 모집단에서 뺄 것인가' 는 도메인 결정이므로 쿼리에 명시적으로 드러내야 합니다."},{"t":"sql","k":"BETWEEN 이 마지막 날의 시각을 자른다","cat":"debug","q":"3월 한 달간의 주문을 모두 뽑아야 하는데 3월 31일 오후 건이 빠집니다. id 를 오름차순으로 출력하세요.","schema":"CREATE TABLE orders (id INTEGER, created_at TEXT);\nINSERT INTO orders VALUES (1,'2024-03-01 09:00:00'),(2,'2024-03-15 12:00:00'),(3,'2024-03-31 18:30:00'),(4,'2024-04-01 08:00:00');","src":"SELECT id FROM orders\nWHERE created_at BETWEEN '2024-03-01' AND '2024-03-31'\nORDER BY id;","sol":"SELECT id FROM orders\nWHERE created_at >= '2024-03-01' AND created_at < '2024-04-01'\nORDER BY id;","ordered":true,"ex":"🐛 원인: '2024-03-31' 은 문자열 비교에서 '2024-03-31 18:30:00' 보다 작습니다(짧은 쪽이 먼저 끝나므로). BETWEEN 의 상한이 그날 00:00 을 뜻하게 되어 31일 낮 시간대가 통째로 빠집니다.\n🔧 해결: 상한을 다음 달 1일 '미만' 으로 잡는 반열린 구간을 씁니다.\n🛡 재발 방지: 시각이 붙은 컬럼에 BETWEEN 을 쓰지 마세요. 기간 조건은 언제나 `&gt;= 시작 AND &lt; 다음_시작` 이 안전하고, 타임존·윤초·정밀도 변화에도 깨지지 않습니다."},{"t":"sql","k":"COUNT 와 COUNT DISTINCT","cat":"debug","q":"상품별로 '구매한 고객 수' 를 세야 하는데, 같은 고객이 여러 번 사면 중복으로 세어집니다. sku, buyers 를 sku 오름차순으로 출력하세요.","schema":"CREATE TABLE buys (sku TEXT, customer TEXT);\nINSERT INTO buys VALUES ('A','김'),('A','김'),('A','박'),('B','이'),('B','이');","src":"SELECT sku, COUNT(customer) AS buyers FROM buys GROUP BY sku ORDER BY sku;","sol":"SELECT sku, COUNT(DISTINCT customer) AS buyers FROM buys GROUP BY sku ORDER BY sku;","ordered":true,"ex":"🐛 원인: COUNT(customer) 는 행 수를 셉니다. 같은 고객이 두 번 사면 두 번 세어져 '고객 수' 가 아니라 '구매 건수' 가 됩니다.\n🔧 해결: COUNT(DISTINCT customer) 로 서로 다른 값의 개수를 셉니다.\n🛡 재발 방지: 지표 이름에 '수' 가 붙으면 무엇의 수인지 먼저 확정하세요. 건수·사용자 수·세션 수는 전부 다른 쿼리이고, 셋을 섞으면 대시보드 전체가 틀어집니다."},{"t":"sql","k":"문자열 이어붙이기는 || 다","cat":"debug","q":"성과 이름을 붙여 전체 이름을 만듭니다. 결과가 전부 0 으로 나옵니다. full 한 컬럼을 오름차순으로 출력하세요.","schema":"CREATE TABLE person (last TEXT, first TEXT);\nINSERT INTO person VALUES ('김','철수'),('박','영희');","src":"SELECT last + first AS full FROM person ORDER BY full;","sol":"SELECT last || first AS full FROM person ORDER BY full;","ordered":true,"ex":"🐛 원인: SQLite 에서 + 는 산술 덧셈입니다. 숫자가 아닌 문자열은 0 으로 변환되어 0 + 0 = 0 이 됩니다. 오류가 아니라 그럴듯한 값이 나오는 게 더 위험합니다.\n🔧 해결: 표준 SQL 의 문자열 연결 연산자 || 를 씁니다.\n🛡 재발 방지: + 로 문자열을 잇는 건 SQL Server 방언입니다. MySQL 은 CONCAT, 표준·SQLite·PostgreSQL 은 || 입니다. 방언을 넘나들 때 가장 먼저 깨지는 지점입니다."},{"t":"sql","k":"LIMIT 앞에 ORDER BY 가 없다","cat":"debug","q":"가장 비싼 상품 2건을 뽑아야 하는데 아무거나 두 개가 나옵니다. name, price 를 price 내림차순으로 출력하세요.","schema":"CREATE TABLE products (name TEXT, price INTEGER);\nINSERT INTO products VALUES ('USB',100),('노트북',900),('키보드',300),('모니터',700);","src":"SELECT name, price FROM products LIMIT 2;","sol":"SELECT name, price FROM products ORDER BY price DESC LIMIT 2;","ordered":true,"ex":"🐛 원인: ORDER BY 가 없으면 행 순서는 정의되지 않습니다. 지금 우연히 맞아 보여도 인덱스·통계·플랜이 바뀌면 결과가 달라집니다.\n🔧 해결: LIMIT 은 반드시 ORDER BY 와 함께 씁니다.\n🛡 재발 방지: 'TOP N' 은 정렬 기준이 있어야 정의되는 개념입니다. 동점이 있을 수 있다면 타이브레이커 컬럼(예: ORDER BY price DESC, name)까지 넣어야 결과가 재현됩니다."},{"t":"sql","k":"<> 가 NULL 행을 조용히 버린다","cat":"debug","q":"상태가 '취소' 가 아닌 주문을 모두 세야 합니다. 상태가 아직 입력되지 않은(NULL) 주문이 빠집니다. id 를 오름차순으로 출력하세요.","schema":"CREATE TABLE orders (id INTEGER, status TEXT);\nINSERT INTO orders VALUES (1,'완료'),(2,'취소'),(3,NULL),(4,'배송중');","src":"SELECT id FROM orders WHERE status <> '취소' ORDER BY id;","sol":"SELECT id FROM orders WHERE status IS NULL OR status <> '취소' ORDER BY id;","ordered":true,"ex":"🐛 원인: NULL &lt;&gt; '취소' 는 참이 아니라 UNKNOWN 입니다. WHERE 는 UNKNOWN 인 행을 버리므로, '취소가 아닌' 조건인데도 상태 미입력 행이 함께 사라집니다.\n🔧 해결: NULL 을 어떻게 볼지 명시합니다. COALESCE(status,'') &lt;&gt; '취소' 도 같은 결과를 냅니다.\n🛡 재발 방지: 부정 조건(&lt;&gt;, NOT IN, NOT LIKE)은 전부 NULL 을 삼킵니다. NULL 을 허용하는 컬럼에 부정 조건을 쓸 때는 반드시 NULL 처리를 함께 적으세요."}]},{"t":"고장난 쿼리 고치기 III — 조건·정렬·타입","xp":70,"th":{"sum":"괄호 하나, 와일드카드 하나, 컬럼 타입 하나가 결과를 바꾼다. 문법 오류가 안 나서 리뷰에서도 잘 안 잡히는 것들이다.","body":[{"h":"연산자 우선순위와 범위 조건","t":"`AND` 는 `OR` 보다 먼저 묶인다. `status='완료' AND amount<100 OR amount>10000` 은 뒤쪽 가지에 상태 조건이 걸리지 않는다 — 섞어 쓸 때는 괄호를 친다. 시각이 붙은 컬럼에 `BETWEEN '3/01' AND '3/31'` 을 쓰면 31일 낮 시간대가 통째로 빠진다. 기간은 언제나 `>= 시작 AND < 다음_시작` 이다."},{"h":"정렬과 타입은 함께 본다","t":"`LIMIT` 을 `ORDER BY` 없이 쓰면 'TOP N' 이 정의되지 않는다 — 지금 맞아 보여도 플랜이 바뀌면 달라진다. 숫자를 TEXT 로 저장하면 정렬이 사전순이라 `10` 이 `9` 보다 앞에 온다. `DISTINCT` 는 특정 컬럼이 아니라 **선택된 행 전체**에 걸린다는 것도 같은 종류의 오해다."}],"code":{"c":"WHERE created_at BETWEEN '2024-03-01' AND '2024-03-31'\n-- '2024-03-31 18:30:00' > '2024-03-31'  → 31일 낮이 빠진다\nWHERE created_at >= '2024-03-01' AND created_at < '2024-04-01'  -- ✓","cap":"시각이 붙은 컬럼에 BETWEEN 을 쓰지 않는다"},"key":["`AND`/`OR` 를 섞을 때는 괄호를 친다","기간 조건은 `>= 시작 AND < 다음_시작`","`LIMIT` 은 반드시 `ORDER BY` 와 함께","`DISTINCT` 는 선택된 행 전체에 걸린다"]},"q":[{"t":"sql","k":"DISTINCT 가 의도한 컬럼에 걸리지 않는다","cat":"debug","q":"주문한 적 있는 고객 목록을 중복 없이 뽑아야 하는데, 같은 고객이 여러 번 나옵니다. customer 를 오름차순으로 출력하세요.","schema":"CREATE TABLE orders (id INTEGER, customer TEXT);\nINSERT INTO orders VALUES (1,'김'),(2,'김'),(3,'박');","src":"SELECT DISTINCT customer, id FROM orders ORDER BY customer;","sol":"SELECT DISTINCT customer FROM orders ORDER BY customer;","ordered":true,"ex":"🐛 원인: DISTINCT 는 특정 컬럼이 아니라 '선택된 행 전체' 에 걸립니다. id 를 함께 고르면 (김,1) 과 (김,2) 는 서로 다른 행이라 둘 다 남습니다.\n🔧 해결: 중복 판단에 쓰지 않을 컬럼은 SELECT 목록에서 빼야 합니다.\n🛡 재발 방지: DISTINCT 로 원하는 결과가 안 나오면 대개 SELECT 목록에 군더더기 컬럼이 있습니다. 정말 그 컬럼도 필요하다면 GROUP BY 와 집계로 어느 값을 고를지 정하세요."},{"t":"sql","k":"LIKE 의 와일드카드 위치","cat":"debug","q":"제목에 '오류' 가 들어간 로그를 찾아야 하는데, '오류' 로 시작하는 것만 나옵니다. id 를 오름차순으로 출력하세요.","schema":"CREATE TABLE logs (id INTEGER, title TEXT);\nINSERT INTO logs VALUES (1,'오류 발생'),(2,'결제 오류 로그'),(3,'정상 처리'),(4,'DB 오류');","src":"SELECT id FROM logs WHERE title LIKE '오류%' ORDER BY id;","sol":"SELECT id FROM logs WHERE title LIKE '%오류%' ORDER BY id;","ordered":true,"ex":"🐛 원인: '오류%' 는 '오류로 시작하는' 패턴입니다. 문자열 어디든 포함되는지 보려면 앞에도 와일드카드가 필요합니다.\n🔧 해결: 앞뒤에 % 를 붙여 '%오류%' 로 만듭니다.\n🛡 재발 방지: 앞에 % 가 붙으면 인덱스를 못 씁니다. 대량 테이블에서 부분 문자열 검색이 잦다면 LIKE 대신 전문 검색(FTS)이나 별도 색인 컬럼을 검토하세요."},{"t":"sql","k":"HAVING 에 쓴 별칭과 집계 순서","cat":"debug","q":"평균 단가가 200 이상인 카테고리만 남겨야 하는데, 개별 주문 단가로 걸러져 결과가 다릅니다. cat, avg_price 를 cat 오름차순으로 출력하세요.","schema":"CREATE TABLE items (cat TEXT, price INTEGER);\nINSERT INTO items VALUES ('A',100),('A',500),('B',150),('B',180),('C',900);","src":"SELECT cat, AVG(price) AS avg_price\nFROM items\nWHERE price >= 200\nGROUP BY cat\nORDER BY cat;","sol":"SELECT cat, AVG(price) AS avg_price\nFROM items\nGROUP BY cat\nHAVING AVG(price) >= 200\nORDER BY cat;","ordered":true,"ex":"🐛 원인: WHERE price &gt;= 200 은 200 미만인 개별 행을 먼저 버립니다. A 카테고리는 100 이 빠진 채 평균이 500 으로 계산되고, B 는 모든 행이 사라져 그룹 자체가 없어집니다. 실제 평균(A=300, B=165)과 전혀 다릅니다.\n🔧 해결: 평균을 낸 '뒤' 에 거르는 HAVING 을 씁니다.\n🛡 재발 방지: '평균이 ~인 그룹' 과 '값이 ~인 행' 은 완전히 다른 조건입니다. 요구사항의 주어가 그룹인지 행인지 먼저 확인하세요."},{"t":"sql","k":"자기 조인이 쌍을 두 번 만든다","cat":"debug","q":"같은 팀에 속한 사람들의 조합을 한 번씩만 나열해야 하는데, (김,박)과 (박,김)이 둘 다 나옵니다. a, b 를 a, b 오름차순으로 출력하세요.","schema":"CREATE TABLE members (name TEXT, team TEXT);\nINSERT INTO members VALUES ('김','A'),('박','A'),('이','A'),('최','B');","src":"SELECT m1.name AS a, m2.name AS b\nFROM members m1 JOIN members m2\n  ON m1.team = m2.team AND m1.name <> m2.name\nORDER BY a, b;","sol":"SELECT m1.name AS a, m2.name AS b\nFROM members m1 JOIN members m2\n  ON m1.team = m2.team AND m1.name < m2.name\nORDER BY a, b;","ordered":true,"ex":"🐛 원인: &lt;&gt; 는 서로 다르기만 하면 참이라 (김,박)과 (박,김)이 모두 나옵니다. 자기 자신만 제외했을 뿐 순서가 뒤집힌 쌍은 막지 못합니다.\n🔧 해결: &lt; 로 비교하면 한쪽 방향만 남아 각 쌍이 정확히 한 번씩 나옵니다.\n🛡 재발 방지: 조합(순서 없음)과 순열(순서 있음)을 구분하세요. 조합이면 자기 조인에 부등호 하나로 방향을 고정하는 것이 표준 관용구입니다."},{"t":"sql","k":"IN 서브쿼리가 엉뚱한 컬럼을 본다","cat":"debug","q":"VIP 고객이 낸 주문만 뽑아야 하는데 모든 주문이 나옵니다. id 를 오름차순으로 출력하세요.","schema":"CREATE TABLE vips (customer_id INTEGER);\nINSERT INTO vips VALUES (1),(3);\nCREATE TABLE orders (id INTEGER, customer_id INTEGER);\nINSERT INTO orders VALUES (1,1),(2,2),(3,3),(4,4);","src":"SELECT id FROM orders o\nWHERE o.customer_id IN (SELECT o.customer_id FROM vips)\nORDER BY id;","sol":"SELECT id FROM orders o\nWHERE o.customer_id IN (SELECT v.customer_id FROM vips v)\nORDER BY id;","ordered":true,"ex":"🐛 원인: 서브쿼리 안에서 o.customer_id 를 고르면 바깥 쿼리의 컬럼을 그대로 참조합니다. 조건이 'x IN (x, x, ...)' 이 되어 언제나 참이고, VIP 테이블은 행 수만 제공할 뿐 값은 쓰이지 않습니다.\n🔧 해결: 서브쿼리에서 참조할 테이블에 별칭을 붙이고 그 별칭으로 컬럼을 지정합니다.\n🛡 재발 방지: 상관 서브쿼리는 바깥 컬럼을 조용히 끌어다 씁니다. 서브쿼리 안 모든 컬럼에 테이블 별칭을 붙이는 습관이 이 실수를 원천 차단합니다."},{"t":"sql","k":"GROUP BY 기준이 빠졌다","cat":"debug","q":"연도별·부서별 지출 합계를 봐야 하는데 부서가 뭉쳐져 나옵니다. yr, dept, total 을 yr, dept 오름차순으로 출력하세요.","schema":"CREATE TABLE spend (yr INTEGER, dept TEXT, amount INTEGER);\nINSERT INTO spend VALUES (2024,'개발',100),(2024,'영업',200),(2023,'개발',50),(2023,'영업',70);","src":"SELECT yr, dept, SUM(amount) AS total\nFROM spend GROUP BY yr ORDER BY yr, dept;","sol":"SELECT yr, dept, SUM(amount) AS total\nFROM spend GROUP BY yr, dept ORDER BY yr, dept;","ordered":true,"ex":"🐛 원인: GROUP BY 에 dept 가 빠져 연도 단위로만 묶였습니다. SQLite 는 오류 없이 그룹 안 임의의 dept 값을 보여 주므로 '부서별' 로 보이지만 실제로는 연도 합계입니다.\n🔧 해결: SELECT 에 있는 비집계 컬럼은 모두 GROUP BY 에 넣습니다.\n🛡 재발 방지: 다른 DB(PostgreSQL 등)는 같은 쿼리를 오류로 막습니다. SQLite 가 허용한다고 맞는 게 아니라, 오히려 조용히 틀린 값을 내는 쪽이 위험합니다."},{"t":"sql","k":"COALESCE 자리가 잘못돼 0 이 사라진다","cat":"debug","q":"상품별 재고를 보여 주되 재고 기록이 없으면 0 으로 표시해야 합니다. 기록이 없는 상품이 아예 안 나옵니다. sku, qty 를 sku 오름차순으로 출력하세요.","schema":"CREATE TABLE products (sku TEXT);\nINSERT INTO products VALUES ('A'),('B'),('C');\nCREATE TABLE stock (sku TEXT, qty INTEGER);\nINSERT INTO stock VALUES ('A',5),('C',0);","src":"SELECT p.sku, COALESCE(s.qty,0) AS qty\nFROM products p\nJOIN stock s ON s.sku = p.sku\nORDER BY p.sku;","sol":"SELECT p.sku, COALESCE(s.qty,0) AS qty\nFROM products p\nLEFT JOIN stock s ON s.sku = p.sku\nORDER BY p.sku;","ordered":true,"ex":"🐛 원인: COALESCE 는 값이 NULL 일 때만 도와줍니다. INNER JOIN 은 짝이 없는 행을 아예 없애므로 NULL 이 될 기회조차 없습니다. B 는 결과에 등장하지 않습니다.\n🔧 해결: 왼쪽을 모두 남기는 LEFT JOIN 으로 바꿔야 COALESCE 가 일할 수 있습니다.\n🛡 재발 방지: '없으면 0' 요구사항은 COALESCE 하나로 끝나지 않습니다. 먼저 조인이 그 행을 남기는지 확인하고, 그다음에 NULL 을 채우세요."},{"t":"sql","k":"ORDER BY 가 문자열 정렬을 한다","cat":"debug","q":"버전 코드를 숫자 크기 순으로 정렬해야 하는데 10 이 9 보다 앞에 옵니다. code 를 숫자 오름차순으로 출력하세요.","schema":"CREATE TABLE rel (code TEXT);\nINSERT INTO rel VALUES ('2'),('10'),('9'),('100');","src":"SELECT code FROM rel ORDER BY code;","sol":"SELECT code FROM rel ORDER BY CAST(code AS INTEGER);","ordered":true,"ex":"🐛 원인: code 가 TEXT 라 사전순으로 정렬됩니다. '10' 은 '9' 보다 앞이고 '100' 은 '2' 보다 앞입니다.\n🔧 해결: CAST 로 숫자로 바꿔 정렬합니다.\n🛡 재발 방지: 근본 해결은 컬럼 타입을 INTEGER 로 잡는 것입니다. 매 조회마다 CAST 하면 인덱스를 못 쓰고, 숫자가 아닌 값이 섞이면 조용히 0 으로 정렬됩니다."}]}]},{"t":"시뮬레이션 실전 — 쿼리 비용과 잠금","l":[{"t":"인덱스·N+1·락","xp":85,"th":{"sum":"SQL 튜닝은 감이 아니라 **읽는 행 수와 왕복 횟수**의 문제다. 숫자로 세어 보면 어디를 고쳐야 하는지가 그냥 보인다.","body":[{"h":"읽지 않아도 되는 행을 만든다","t":"인덱스가 주는 것은 '빠름' 이 아니라 **읽지 않아도 되는 행**이다. 100만 행에서 50행을 찾을 때 전체 스캔은 100만 행을, 인덱스는 탐색 깊이 20 + 50행만 읽는다. 다만 인덱스는 '어디 있는지' 만 알려 주므로 인덱스에 없는 컬럼을 읽으려면 행마다 테이블로 되돌아간다 — 커버링 인덱스가 그 왕복을 없앤다. 선택도가 낮으면(조건에 맞는 행이 많으면) 전체 스캔이 더 빠를 수도 있다."},{"h":"잠금은 순서의 문제다","t":"데드락은 두 트랜잭션이 **서로가 쥔 것을 기다릴 때** 생긴다 — 대기 그래프에 순환이 있으면 데드락이다. 예방책은 단순하다: 항상 같은 순서로 잠근다. 낙관적 잠금은 반대로 일단 진행한 뒤 `WHERE version = ?` 로 검사하는데, **0행 갱신을 확인하지 않는 코드**가 가장 흔한 버그다."}],"code":{"c":"주문 200건에 사용자 이름 붙이기\n  항목마다 조회 → 쿼리 201개\n  id 모아 IN 한 번  → 쿼리 2개","cap":"N+1 은 개발 데이터에서 보이지 않는다"},"key":["인덱스 효과는 선택도가 결정한다 — 옵티마이저가 무시하는 건 대개 판단이다","인덱스에 없는 컬럼을 읽으면 행마다 테이블 왕복 → 커버링 인덱스","N+1 은 요청당 쿼리 수를 세면 바로 보인다","데드락은 락 순서를 통일하면 생기지 않는다","낙관적 잠금은 0행 갱신을 반드시 검사한다"]},"q":[{"t":"sim","k":"인덱스가 바꾸는 비용","lv":2,"cat":"design","q":"100만 행 테이블에서 조건에 맞는 <b>50행</b>을 찾습니다. (1) 인덱스가 없으면 <b>전체 스캔</b>(읽은 행 = 100만), (2) 인덱스가 있으면 <b>탐색 깊이 + 매칭 행</b>(= ceil(log2(100만)) + 50) 입니다. 두 계획을 <code>snap</code> 하고 <code>[전체스캔, 인덱스]</code> 읽은 행 수를 돌려주세요.","src":"const ROWS = 1000000, MATCH = 50;\n\nfunction run() {\n  // TODO: 두 방식의 읽은 행 수를 계산해 각각 snap 하세요\n  return [0, 0];\n}\n\nRESULT = run();","tests":[{"d":"전체 스캔은 100만 행을 읽는다","js":"RESULT[0]===1000000"},{"d":"인덱스는 70행만 읽는다","js":"RESULT[1]===70"},{"d":"두 계획을 순서대로 기록한다","js":"FRAMES.length===2 && FRAMES.map(f=>f.opt.plan).join(',')==='full,index'"},{"d":"인덱스가 만 배 이상 적게 읽는다","js":"RESULT[0]/RESULT[1]>10000"},{"d":"인덱스 비용은 탐색 깊이와 매칭 행의 합이다","js":"RESULT[1]===Math.ceil(Math.log2(1000000))+50"}],"ex":"🎯 인덱스가 주는 것은 '빠름' 이 아니라 <b>읽지 않아도 되는 행</b>입니다. 100만 행 중 50행을 찾는데 100만 행을 훑는 것과 70행만 읽는 것의 차이입니다.\n💡 그래서 인덱스 효과는 <b>선택도</b>에 달려 있습니다. 조건에 맞는 행이 전체의 30% 라면 인덱스로 30만 번 랜덤 접근하는 것보다 전체 스캔이 <b>더 빠릅니다</b> — 옵티마이저가 인덱스를 무시하는 것은 대개 버그가 아니라 판단입니다.\n⚠️ 인덱스는 공짜가 아닙니다. INSERT·UPDATE 마다 함께 갱신되고 디스크를 더 씁니다. '일단 다 걸어 두기' 는 쓰기 성능을 갉아먹습니다.\n🔧 실제로는 EXPLAIN 으로 계획을 확인하세요. 추측이 아니라 <b>옵티마이저가 무엇을 고르는지</b> 봐야 합니다."},{"t":"sim","k":"N+1 이 만드는 쿼리 수","lv":2,"cat":"design","q":"주문 <b>200건</b>에 사용자 이름을 붙입니다. (1) 항목마다 조회하면 쿼리가 몇 개인지, (2) id 를 모아 <code>IN</code> 한 번으로 가져오면 몇 개인지 계산하세요(사용자는 중복 포함 <b>50명</b>). 두 방식을 <code>snap</code> 하고 <code>[N+1, 배치]</code> 를 돌려주세요.","src":"const ORDERS = 200, USERS = 50;\n\nfunction run() {\n  // TODO: 두 방식의 쿼리 수를 계산해 snap 하세요\n  return [0, 0];\n}\n\nRESULT = run();","tests":[{"d":"N+1 은 쿼리 201개","js":"RESULT[0]===201"},{"d":"배치는 쿼리 2개","js":"RESULT[1]===2"},{"d":"두 방식을 모두 기록한다","js":"FRAMES.length===2"},{"d":"배치가 백 배 이상 적다","js":"RESULT[0]/RESULT[1]>100"},{"d":"중복 제거된 사용자 수를 알고 있다","js":"FRAMES[1].opt.distinct===50"}],"ex":"🎯 N+1 의 무서움은 <b>개발 데이터에서 안 보인다</b>는 것입니다. 10건이면 쿼리 11개라 눈치채기 어렵고, 운영 200건이 되면 201개가 됩니다. 페이지 하나에 쿼리 수천 개가 나가는 일이 이렇게 생깁니다.\n🔧 고치는 방법은 <b>id 를 먼저 모아 한 번에</b> 가져오는 것입니다. 중복 id 는 Set 으로 걸러 조회량을 더 줄입니다.\n⚠️ ORM 의 지연 로딩이 이 문제를 <b>코드에서 보이지 않게</b> 만듭니다. <code>orders.map(o =&gt; o.user.name)</code> 한 줄이 쿼리 200개입니다 — eager loading·JOIN FETCH·DataLoader 로 명시해야 합니다.\n💡 발견하는 방법은 하나입니다. <b>요청당 쿼리 수를 세는</b> 것 — 개발 환경에서 임계를 넘으면 경고를 띄우는 팀이 많습니다."},{"t":"sim","k":"커버링 인덱스","lv":3,"cat":"design","q":"인덱스로 <b>1000행</b>을 찾은 뒤 각 행의 다른 컬럼을 읽어야 합니다. (1) 일반 인덱스는 <b>행마다 테이블을 한 번 더</b> 찾아갑니다. (2) 커버링 인덱스는 필요한 컬럼이 인덱스 안에 있어 <b>테이블 접근이 0</b> 입니다. 각각 <code>snap</code> 하고 <code>[일반, 커버링]</code> 의 테이블 접근 횟수를 돌려주세요.","src":"const MATCH = 1000;\n\nfunction run() {\n  // TODO: 두 경우의 테이블 접근 횟수를 snap 하고 돌려주세요\n  return [0, 0];\n}\n\nRESULT = run();","tests":[{"d":"일반 인덱스는 1000번 테이블을 찾아간다","js":"RESULT[0]===1000"},{"d":"커버링 인덱스는 테이블 접근이 없다","js":"RESULT[1]===0"},{"d":"두 계획을 모두 기록한다","js":"FRAMES.length===2"},{"d":"커버링 여부를 표시한다","js":"FRAMES[0].opt.covering===false && FRAMES[1].opt.covering===true"},{"d":"기록한 값이 테이블 접근 수와 일치한다","js":"FRAMES.every(f=>f.value[0]===f.opt.tableHits)"}],"ex":"🎯 인덱스를 탔는데도 느린 가장 흔한 이유가 이것입니다. 인덱스는 '어디 있는지' 만 알려 주므로, <b>인덱스에 없는 컬럼</b>을 읽으려면 행마다 테이블로 되돌아가야 합니다(random I/O).\n🔧 <b>커버링 인덱스</b>는 조회에 필요한 컬럼을 인덱스에 함께 넣어 그 왕복을 없앱니다. PostgreSQL 의 <code>INCLUDE</code>, MySQL 은 복합 인덱스 뒤에 컬럼을 덧붙이는 식입니다.\n💡 EXPLAIN 에서 <code>Index Only Scan</code>(PostgreSQL)이나 <code>Using index</code>(MySQL)가 보이면 커버링이 된 것입니다 — <code>Using index condition</code> 과는 다릅니다.\n⚠️ 대가는 인덱스 크기입니다. 컬럼을 많이 넣을수록 인덱스가 커져 캐시 효율이 떨어지고 쓰기가 느려집니다. <b>자주 쓰는 조회 한둘</b>에만 적용하세요."},{"t":"sim","k":"데드락 탐지","lv":3,"cat":"design","q":"두 트랜잭션이 <b>반대 순서</b>로 락을 잡습니다. 대기 그래프를 만들어 <b>순환이 생기는 순간</b>을 찾으세요. 각 락 요청을 <code>snap</code> 하고 <b>데드락이 감지된 단계 번호</b>(0부터)를 돌려주세요. 없으면 -1 입니다.","src":"/* [트랜잭션, 원하는 자원] */\nconst REQ = [['T1','A'], ['T2','B'], ['T1','B'], ['T2','A']];\n\nfunction run() {\n  const owner = {};   // 자원 -> 소유 트랜잭션\n  const waits = {};   // 트랜잭션 -> 기다리는 대상 트랜잭션\n  // TODO: 대기 그래프에 순환이 생기면 그 단계 번호를 돌려주세요\n  return -1;\n}\n\nRESULT = run();","tests":[{"d":"마지막 요청에서 데드락이 감지된다","js":"RESULT===3"},{"d":"앞의 두 요청은 락을 얻는다","js":"FRAMES.slice(0,2).every(f=>f.opt.got===true)"},{"d":"세 번째 요청은 T2 를 기다린다","js":"FRAMES[2].opt.got===false && FRAMES[2].opt.waitsFor==='T2'"},{"d":"세 번째까지는 데드락이 아니다","js":"FRAMES.slice(0,3).every(f=>!f.opt.deadlock)"},{"d":"네 번째에서 순환이 생긴다","js":"FRAMES[3].opt.deadlock===true"}],"ex":"🎯 데드락은 <b>두 트랜잭션이 서로가 쥔 것을 기다릴 때</b> 생깁니다. 대기 그래프에 순환이 있으면 데드락이고, DB 는 이걸 감지해 한쪽을 희생시킵니다(victim).\n🔧 애플리케이션 쪽 예방책은 단순합니다 — <b>항상 같은 순서로</b> 락을 잡으면 순환이 만들어지지 않습니다. 계좌 이체에서 id 가 작은 쪽부터 잠그는 관용구가 그것입니다.\n💡 데드락은 재시도로 해결 가능한 오류입니다. 희생된 트랜잭션은 <b>처음부터 다시</b> 실행하면 대개 성공하므로, 트랜잭션 경계 밖에서 재시도할 수 있게 코드를 짜야 합니다.\n⚠️ 데드락이 잦다면 트랜잭션이 <b>너무 길거나 너무 많이 잠그고</b> 있다는 신호입니다. 외부 API 호출을 트랜잭션 안에 두는 것이 대표적인 원인입니다."},{"t":"sim","k":"낙관적 잠금 재시도","lv":2,"cat":"design","q":"세 요청이 같은 행을 고칩니다. 셋 다 <b>같은 버전을 읽은</b> 상태에서 차례로 <code>WHERE version = ?</code> 갱신을 시도하는데, 버전이 다르면 <b>0행이 갱신되어</b> 다시 읽고 재시도합니다. 각 시도를 <code>snap</code> 하고 <b>총 시도 횟수</b>를 돌려주세요.","src":"const REQS = ['A', 'B', 'C'];\n\nfunction run() {\n  let version = 1, tries = 0;\n  const read = {};\n  REQS.forEach((r) => { read[r] = version; });   // 셋 다 같은 버전을 읽었다\n  // TODO: 차례로 갱신을 시도하고, 실패하면 다시 읽어 재시도하세요\n  return tries;\n}\n\nRESULT = run();","tests":[{"d":"총 6번 시도한다","js":"RESULT===6"},{"d":"첫 시도는 성공한다","js":"FRAMES[0].opt.ok===true"},{"d":"두 번째와 세 번째는 버전 충돌로 실패한다","js":"FRAMES[1].opt.ok===false && FRAMES[2].opt.ok===false"},{"d":"최종적으로 세 번 모두 성공한다","js":"FRAMES.filter(f=>f.opt.ok).length===3"},{"d":"버전이 1에서 시작해 3까지 오른다","js":"FRAMES[0].opt.version===1 && FRAMES[FRAMES.length-1].opt.version===3"}],"ex":"🎯 낙관적 잠금은 '<b>충돌은 드물다</b>' 고 보고 일단 진행한 뒤 검사합니다. 읽을 때 버전을 같이 읽고 쓸 때 <code>WHERE version = ?</code> 를 붙이면, 그 사이 누가 고쳤을 때 <b>0행이 갱신되어</b> 알 수 있습니다.\n💡 '0행 갱신' 을 <b>확인하지 않는 코드</b>가 이 방식의 가장 흔한 버그입니다. UPDATE 가 성공했다고 넘어가면 변경이 조용히 사라집니다 — 반환된 행 수를 반드시 검사하세요.\n⚠️ 충돌이 잦으면 재시도가 쌓여 오히려 느려집니다. 3개 요청에 6번 시도가 든 것처럼요 — 나중에 온 요청일수록 더 자주 밀립니다. 경합이 심하면 비관적 잠금(<code>SELECT ... FOR UPDATE</code>)이나 원자적 연산(<code>SET n = n - 1 WHERE n &gt;= 1</code>)이 낫습니다.\n🔧 재시도에는 상한이 필요합니다. 무한 재시도는 라이브락이 됩니다."}]}]},{"t":"설계 실전 — 스키마가 감당하는 규모","l":[{"t":"쌓이고, 늘어나고, 어긋난다","xp":85,"th":{"sum":"작은 스키마는 대부분 맞는다. 설계가 갈리는 지점은 **데이터가 쌓이고, 종류가 늘고, 값이 어긋나기 시작할 때**다.","body":[{"h":"쌓이는 데이터는 지우는 방법부터 정한다","t":"수천만 행을 `DELETE` 로 지우면 트랜잭션이 길어지고 락과 WAL 이 폭발한다 — 삭제가 서비스를 멈춘다. 시각으로 파티셔닝해 두면 **파티션 통째로 DROP** 할 수 있어 거의 즉시 끝나고, 조회도 파티션 프루닝으로 빨라진다. 조회 인덱스도 순서가 중요하다 — 복합 인덱스는 **왼쪽부터**만 쓸 수 있으므로 '등호 조건 먼저, 정렬 나중' 이다."},{"h":"늘어나는 것은 컬럼이 아니라 행이어야 한다","t":"언어별 컬럼(`name_ko`, `name_en`)이나 제공자별 컬럼(`google_id`)은 종류가 늘 때마다 마이그레이션을 부른다. 행으로 두면 데이터만 넣으면 된다. 태그를 문자열로 뭉쳐 두면 `LIKE '%tag%'` 가 되어 인덱스를 못 쓰고, 다형 관계를 `target_type`+`target_id` 로 두면 **DB 가 무결성을 지켜 줄 수 없다**."}],"code":{"c":"-- 복합 인덱스는 왼쪽부터만 쓰인다\nINDEX (member_id, created_at)\n  member_id = ?              ✓ 쓰인다\n  created_at > ? (단독)      ✗ 안 쓰인다","cap":"등호 조건 먼저, 정렬·범위 나중"},"key":["쌓이는 테이블은 파티셔닝 + 파티션 DROP 으로 지운다","복합 인덱스는 leftmost prefix — 순서가 곧 성능이다","종류가 늘어나는 것은 컬럼이 아니라 행으로","다형 관계는 공통 상위 테이블로 진짜 외래키를 만든다","비정규화는 원본·갱신 방법·보정 계획을 함께 적는다"]},"q":[{"t":"arch","kind":"erd","k":"시계열 데이터와 파티셔닝","lv":3,"cat":"design","q":"센서 측정값이 하루 수천만 건씩 쌓입니다. <b>최근 7일 조회가 대부분</b>이고 오래된 데이터는 <b>90일 뒤 삭제</b>합니다. 삭제가 서비스를 멈추지 않도록 설계하세요.","src":"{\n  \"entities\": [\n    { \"name\": \"reading\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"sensor_id\", \"type\": \"bigint\" },\n      { \"name\": \"value\", \"type\": \"double\" },\n      { \"name\": \"at\", \"type\": \"timestamptz\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"측정값 테이블이 시각으로 파티셔닝된다","js":"D.entities.some(e=>/at|time/i.test(String(e.partitionBy||'')))"},{"d":"파티션 단위가 정해져 있다","js":"D.entities.some(e=>!!String(e.partitionUnit||'').trim())"},{"d":"보관 정책이 파티션 단위 삭제다","js":"D.entities.some(e=>/DROP|파티션/i.test(String(e.retention||'')))"},{"d":"조회 기준 컬럼에 인덱스가 있다","js":"D.entities.find(e=>e.partitionBy).fields.some(f=>/at|time/i.test(f.name)&&f.index===true)"},{"d":"센서 외래키에 인덱스가 있다","js":"D.entities.find(e=>e.partitionBy).fields.filter(f=>f.fk).every(f=>f.index===true)"}],"ex":"🎯 <code>DELETE FROM reading WHERE at &lt; ...</code> 로 수천만 행을 지우면 트랜잭션이 길어지고 락과 WAL 이 폭발합니다. 삭제가 <b>서비스를 멈추는</b> 전형적인 방식입니다.\n🔧 시각으로 파티셔닝하면 오래된 데이터를 <b>파티션 통째로 DROP</b> 할 수 있습니다 — 메타데이터만 바뀌므로 거의 즉시 끝납니다.\n💡 파티션 프루닝 덕분에 조회도 빨라집니다. '최근 7일' 조건이면 옵티마이저가 7개 파티션만 봅니다.\n⚠️ 파티션 키는 <b>거의 모든 조회 조건에 들어가야</b> 합니다. 센서 id 로만 조회하는 쿼리는 전 파티션을 훑게 되므로, 접근 패턴을 먼저 확인하고 키를 정하세요."},{"t":"arch","kind":"erd","k":"다형 관계의 함정","lv":3,"cat":"design","q":"댓글이 <b>게시글·사진·영상</b> 어디에나 달릴 수 있습니다. <code>target_type</code>+<code>target_id</code> 한 쌍으로 가리키는 방식은 <b>외래키를 걸 수 없습니다</b>. 참조 무결성을 지키도록 설계하세요.","src":"{\n  \"entities\": [\n    { \"name\": \"comment\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"target_type\", \"type\": \"varchar(20)\" },\n      { \"name\": \"target_id\", \"type\": \"bigint\" },\n      { \"name\": \"body\", \"type\": \"text\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"댓글이 진짜 외래키를 갖는다","js":"D.entities.find(e=>e.name==='comment').fields.some(f=>!!f.fk)"},{"d":"target_type 문자열로 분기하지 않는다","js":"!D.entities.find(e=>e.name==='comment').fields.some(f=>/target_type|_type$/i.test(f.name))"},{"d":"공통 상위 테이블이 있다","js":"D.entities.length>=3"},{"d":"구체 타입들이 그 상위를 참조한다","js":"D.entities.filter(e=>e.name!=='comment').filter(e=>e.fields.some(f=>!!f.fk)).length>=2"},{"d":"댓글의 외래키에 인덱스가 있다","js":"D.entities.find(e=>e.name==='comment').fields.filter(f=>f.fk).every(f=>f.index===true)"}],"ex":"🎯 <code>target_type</code>+<code>target_id</code> 방식은 편해 보이지만 <b>DB 가 무결성을 지켜 줄 수 없습니다</b>. 게시글이 지워져도 댓글은 그대로 남아 어디에도 속하지 않는 고아가 됩니다.\n🔧 공통 상위 테이블(commentable)을 두고 구체 타입들이 그 id 를 공유하면, 댓글은 <b>진짜 외래키 하나</b>만 가지면 됩니다. 이 방식을 클래스 테이블 상속이라고 부릅니다.\n💡 조인도 단순해집니다 — <code>WHERE target_type = 'post'</code> 같은 분기가 사라지고, 인덱스도 컬럼 하나에만 걸면 됩니다.\n⚠️ 대가는 테이블 하나와 조인 한 번입니다. 대상 타입이 둘뿐이고 앞으로도 안 늘어난다면 <b>각각 별도 댓글 테이블</b>(post_comment, photo_comment)이 더 단순할 수도 있습니다."},{"t":"arch","kind":"erd","k":"감사 로그","lv":2,"cat":"design","q":"누가 언제 무엇을 바꿨는지 남겨야 합니다. 대상 레코드가 <b>지워져도 기록은 남아야</b> 하고, <b>변경 전후 값</b>을 알 수 있어야 하며, 감사 로그 자체는 <b>수정할 수 없어야</b> 합니다.","src":"{\n  \"entities\": [\n    { \"name\": \"audit_log\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"message\", \"type\": \"text\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"행위자·대상·동작·시각이 모두 있다","js":"['actor','entity','action','at'].every(k=>D.entities[0].fields.some(f=>new RegExp(k,'i').test(f.name)))"},{"d":"변경 전후 값을 담는 자리가 있다","js":"D.entities[0].fields.some(f=>/before|old|prev/i.test(f.name)) && D.entities[0].fields.some(f=>/after|new/i.test(f.name))"},{"d":"대상 레코드로 외래키를 걸지 않았다","js":"!D.entities[0].fields.some(f=>/entity_id|target_id/i.test(f.name)&&!!f.fk)"},{"d":"추가 전용임을 명시했다","js":"D.entities[0].appendOnly===true || /append|불변|immutable|수정할 수 없/i.test(String(D.entities[0].note||''))"},{"d":"조회 기준 컬럼에 인덱스가 있다","js":"D.entities[0].fields.filter(f=>/entity_id|actor|^at$/i.test(f.name)).every(f=>f.index===true)"}],"ex":"🎯 감사 로그에 <b>외래키를 걸면 안 됩니다</b>. 사용자를 지울 때 감사 기록까지 함께 지워지거나(CASCADE) 삭제 자체가 막힙니다 — 둘 다 감사의 목적에 어긋납니다. id 만 값으로 남기세요.\n💡 '무엇을 바꿨는지' 는 <b>전후 값 전체</b>를 남기는 편이 안전합니다. 스키마가 바뀌어도 과거 기록을 그대로 읽을 수 있도록 JSON 으로 담는 것이 흔한 선택입니다.\n⚠️ 감사 로그가 <b>수정 가능하면 감사가 아닙니다</b>. 애플리케이션 계정에 UPDATE·DELETE 권한을 주지 않고, 필요하면 별도 저장소나 append-only 스토리지로 분리합니다.\n🔧 개인정보가 전후 값에 그대로 들어갈 수 있습니다 — 마스킹 대상 필드를 미리 정해 두세요."},{"t":"arch","kind":"erd","k":"복합 인덱스의 컬럼 순서","lv":3,"cat":"design","q":"주문 테이블에서 <b>'특정 회원의 최근 주문 20건'</b> 조회가 가장 잦습니다. <b>복합 인덱스의 컬럼 순서</b>를 정하고, 왜 그 순서인지가 설계에 드러나게 하세요.","src":"{\n  \"entities\": [\n    { \"name\": \"orders\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"member_id\", \"type\": \"bigint\" },\n      { \"name\": \"status\", \"type\": \"varchar(20)\" },\n      { \"name\": \"created_at\", \"type\": \"timestamptz\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"복합 인덱스를 선언했다","js":"(D.entities[0].indexes||[]).some(i=>Array.isArray(i.columns)&&i.columns.length>=2)"},{"d":"등호 조건 컬럼이 앞에 온다","js":"(D.entities[0].indexes||[]).some(i=>i.columns[0]==='member_id')"},{"d":"정렬 컬럼이 뒤에 온다","js":"(D.entities[0].indexes||[]).some(i=>/created|at$/i.test(String(i.columns[1])))"},{"d":"정렬 방향을 지정했다","js":"(D.entities[0].indexes||[]).some(i=>Array.isArray(i.order)&&i.order.length===i.columns.length)"},{"d":"순서를 정한 이유를 적어 두었다","js":"(D.entities[0].indexes||[]).some(i=>/등호|정렬|범위|선행|prefix/i.test(String(i.note||'')))"}],"ex":"🎯 복합 인덱스는 <b>왼쪽부터 순서대로</b>만 쓸 수 있습니다(leftmost prefix). <code>(member_id, created_at)</code> 인덱스는 member_id 단독 조회에도 쓰이지만, created_at 단독 조회에는 <b>전혀 쓰이지 않습니다</b>.\n🔧 그래서 순서 규칙은 '<b>등호 조건 먼저, 범위·정렬 나중</b>' 입니다. member_id = ? 로 좁힌 뒤 created_at 순서대로 20건만 읽으면 정렬 작업 자체가 사라집니다.\n💡 순서를 반대로 <code>(created_at, member_id)</code> 로 잡으면 특정 회원을 찾으려고 시간 범위 전체를 훑게 됩니다.\n⚠️ 인덱스를 종류별로 다 만들지 마세요. <code>(a, b)</code> 가 있으면 <code>(a)</code> 는 대개 불필요합니다 — 중복 인덱스는 쓰기 비용만 늘립니다."},{"t":"arch","kind":"erd","k":"태그와 검색","lv":2,"cat":"design","q":"글에 태그를 여러 개 붙이고 <b>'이 태그가 붙은 글 목록'</b>을 빠르게 조회해야 합니다. 태그 이름은 <b>중복될 수 없고</b>, 같은 글에 같은 태그를 두 번 붙일 수 없습니다.","src":"{\n  \"entities\": [\n    { \"name\": \"post\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"tags\", \"type\": \"varchar(500)\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"태그를 문자열 컬럼에 몰아넣지 않았다","js":"!D.entities.some(e=>e.fields.some(f=>/^tags$/i.test(f.name)))"},{"d":"태그 테이블과 연결 테이블이 있다","js":"D.entities.length===3"},{"d":"태그 이름에 유니크가 걸려 있다","js":"(D.entities.find(e=>/^tag$/i.test(e.name)).unique||[]).some(u=>u.length===1&&/name/i.test(u[0]))"},{"d":"(글, 태그) 조합이 유일하다","js":"D.entities.some(e=>(e.unique||[]).some(u=>u.length===2&&u.some(c=>/post/.test(c))&&u.some(c=>/tag/.test(c))))"},{"d":"양쪽 외래키에 인덱스가 있다","js":"D.entities.find(e=>e.fields.filter(f=>f.fk).length===2).fields.filter(f=>f.fk).every(f=>f.index===true)"}],"ex":"🎯 태그를 <code>'a,b,c'</code> 처럼 한 컬럼에 몰아넣으면 '이 태그가 붙은 글' 조회가 <b>LIKE '%tag%'</b> 가 됩니다 — 인덱스를 못 쓰고, 'java' 를 찾는데 'javascript' 가 딸려 옵니다.\n🔧 연결 테이블로 나누면 <code>tag_id = ?</code> 등호 조회가 되어 인덱스가 그대로 듣습니다.\n💡 연결 테이블에는 별도 id 대신 <b>복합 기본키 (post_id, tag_id)</b> 를 쓰는 것이 자연스럽습니다 — 중복 방지와 기본키가 한 번에 해결됩니다.\n⚠️ 인덱스 방향이 둘 다 필요합니다. <code>(post_id, tag_id)</code> 만 있으면 '태그로 글 찾기' 가 느리므로 반대 방향 인덱스도 두세요."},{"t":"arch","kind":"erd","k":"중복 계정 병합","lv":3,"cat":"design","q":"같은 사람이 이메일과 소셜 로그인으로 <b>계정을 두 개</b> 만들었습니다. 로그인 수단을 계정에서 분리해 한 사람이 <b>여러 로그인 수단</b>을 가질 수 있게 설계하세요. 같은 수단이 두 계정에 붙으면 안 됩니다.","src":"{\n  \"entities\": [\n    { \"name\": \"users\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"email\", \"type\": \"varchar(255)\" },\n      { \"name\": \"google_id\", \"type\": \"varchar(64)\" }\n    ], \"unique\": [[\"email\"]] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"로그인 수단이 별도 테이블로 분리됐다","js":"D.entities.length===2"},{"d":"users 에 제공자별 컬럼이 남아 있지 않다","js":"!D.entities.find(e=>/user/i.test(e.name)).fields.some(f=>/google|kakao|naver|apple/i.test(f.name))"},{"d":"수단 테이블이 사용자를 참조한다","js":"D.entities.some(e=>e.fields.some(f=>/user/i.test(String(f.fk||''))))"},{"d":"(provider, subject) 조합이 유일하다","js":"D.entities.some(e=>(e.unique||[]).some(u=>u.length===2&&u.some(c=>/provider/i.test(c))&&u.some(c=>/subject|uid/i.test(c))))"},{"d":"사용자 외래키에 인덱스가 있다","js":"D.entities.filter(e=>e.fields.some(f=>f.fk)).every(e=>e.fields.filter(f=>f.fk).every(f=>f.index===true))"}],"ex":"🎯 로그인 수단을 users 컬럼으로 두면 <b>제공자가 늘 때마다 컬럼이 늘어납니다</b>. 그리고 한 사람이 두 수단을 쓰는 순간 계정이 쪼개집니다.\n🔧 identity 테이블로 분리하면 사용자 1명이 여러 수단을 가질 수 있고, 계정 병합은 <b>identity 의 user_id 를 옮기는</b> 것으로 끝납니다.\n💡 유니크는 <code>(provider, subject)</code> 조합에 걸어야 합니다 — 구글의 subject 와 카카오의 subject 가 우연히 같을 수 있기 때문입니다.\n⚠️ 이메일을 신원 확인 수단으로 쓸 때는 <b>검증 여부</b>를 꼭 함께 두세요. 검증되지 않은 이메일로 자동 병합하면 계정 탈취 경로가 됩니다."},{"t":"arch","kind":"erd","k":"통화와 다국어","lv":2,"cat":"design","q":"상품을 <b>여러 통화</b>로 팔고 <b>여러 언어</b>로 이름을 보여 줍니다. 통화마다 소수 자릿수가 다르고, 언어가 늘어날 때 스키마를 바꾸지 않아야 합니다.","src":"{\n  \"entities\": [\n    { \"name\": \"product\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"name_ko\", \"type\": \"varchar(200)\" },\n      { \"name\": \"name_en\", \"type\": \"varchar(200)\" },\n      { \"name\": \"price\", \"type\": \"double\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"언어별 컬럼(name_ko/name_en)이 사라졌다","js":"!D.entities.some(e=>e.fields.some(f=>/_ko$|_en$|_ja$/i.test(f.name)))"},{"d":"이름과 가격이 별도 테이블로 분리됐다","js":"D.entities.length>=3"},{"d":"(상품, 언어) 조합이 유일하다","js":"D.entities.some(e=>(e.unique||[]).some(u=>u.length===2&&u.some(c=>/locale|lang/i.test(c))))"},{"d":"(상품, 통화) 조합이 유일하다","js":"D.entities.some(e=>(e.unique||[]).some(u=>u.length===2&&u.some(c=>/currency/i.test(c))))"},{"d":"금액에 부동소수를 쓰지 않았다","js":"D.entities.every(e=>e.fields.filter(f=>/amount|price/i.test(f.name)).every(f=>!/float|double|real/i.test(String(f.type))))"}],"ex":"🎯 언어마다 컬럼을 만들면 <b>언어를 추가할 때마다 스키마 마이그레이션</b>이 필요합니다. 행으로 두면 데이터만 넣으면 됩니다.\n💡 통화도 마찬가지입니다. '환율로 환산' 은 안 됩니다 — 나라마다 실제 판매가를 따로 정하고(9,900원 vs $9.99), 환율은 그 관계를 설명하지 못합니다.\n🔧 금액은 <b>최소 단위 정수</b>로 저장하세요. 통화마다 소수 자릿수가 다르므로(원 0자리, 달러 2자리, 디나르 3자리) 정수 + 통화 코드가 가장 안전합니다.\n⚠️ 조회할 때 해당 언어가 없으면 어떻게 할지도 정해야 합니다 — 기본 언어로 폴백할지, 빈 값을 보여 줄지."},{"t":"arch","kind":"erd","k":"읽기를 위한 비정규화","lv":3,"cat":"design","q":"글 목록에 <b>좋아요 수</b>와 <b>댓글 수</b>를 함께 보여 줍니다. 매번 COUNT 하면 느리므로 집계값을 저장하되, <b>원본과 어긋났을 때의 대책</b>까지 설계에 담으세요.","src":"{\n  \"entities\": [\n    { \"name\": \"post\", \"fields\": [{ \"name\": \"id\", \"type\": \"bigint\", \"pk\": true }] },\n    { \"name\": \"post_like\", \"fields\": [\n      { \"name\": \"post_id\", \"type\": \"bigint\", \"fk\": \"post.id\" },\n      { \"name\": \"user_id\", \"type\": \"bigint\" }\n    ] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"집계 컬럼이 두 개 이상 있다","js":"D.entities.find(e=>e.name==='post').fields.filter(f=>/count$/i.test(f.name)).length>=2"},{"d":"비정규화임을 표시했다","js":"D.entities.find(e=>e.name==='post').fields.filter(f=>/count$/i.test(f.name)).every(f=>f.denormalized===true)"},{"d":"원본이 무엇인지 적어 두었다","js":"D.entities.find(e=>e.name==='post').fields.filter(f=>/count$/i.test(f.name)).every(f=>!!String(f.source||'').trim())"},{"d":"갱신 방법을 명시했다","js":"D.entities.find(e=>e.name==='post').fields.filter(f=>/count$/i.test(f.name)).every(f=>/트랜잭션|transaction|트리거|trigger/i.test(String(f.maintainedBy||'')))"},{"d":"같은 사람이 두 번 좋아요를 누를 수 없다","js":"(D.entities.find(e=>/like/i.test(e.name)).unique||[]).some(u=>u.length===2)"},{"d":"어긋났을 때의 보정 계획이 있다","js":"/보정|대조|reconcile|재계산/i.test(JSON.stringify(D))"}],"ex":"🎯 비정규화는 <b>정규화 위반이 아니라 트레이드오프</b>입니다. 읽기가 압도적으로 많으면 집계값을 저장하는 편이 맞고, 중요한 건 그 사실을 <b>스키마에 명시</b>하는 것입니다.\n🔧 갱신은 원본 변경과 <b>같은 트랜잭션</b>에서 해야 합니다. 애플리케이션 두 곳에서 따로 하면 반드시 어긋납니다.\n⚠️ 그래도 어긋납니다 — 버그·수동 수정·마이그레이션 때문에요. 그래서 <b>주기적으로 원본과 대조해 보정하는</b> 배치가 함께 있어야 합니다. '어긋나지 않게 한다' 가 아니라 '어긋나면 고친다' 가 현실적인 목표입니다.\n💡 인기 글에서는 같은 행을 모두가 갱신해 락 경합이 생깁니다. 아주 큰 규모에서는 카운터를 여러 행으로 쪼개는(sharded counter) 기법을 씁니다."}]}]}]);
